#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADS1115 I2C address
#define ADS1115_ADDR 0x48

// ADS1115 register addresses
#define ADS1115_REG_CONFIG 0x01
#define ADS1115_REG_CONVERT 0x00

// Configuration register values
#define CONFIG_OS_SINGLE 0x8000  // Start a single conversion
#define CONFIG_MUX_SINGLE_0 0x4000 // AIN0 single-ended
#define CONFIG_PGA_4_096V 0x0000 // +/-4.096V range
#define CONFIG_DR_128SPS 0x0080  // 128 SPS data rate
#define CONFIG_MODE_SINGLE 0x0100  // Single-shot mode

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Signal handler for Ctrl+C
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", sig);
}

// Function to write a 16-bit value to the ADS1115
int write_ads1115(int handle, uint16_t value) {
    char buf[3];
    buf[0] = ADS1115_REG_CONVERT;
    buf[1] = (value >> 8) & 0xFF; // MSB
    buf[2] = value & 0xFF;       // LSB

    int result = i2cWriteDevice(handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to ADS1115: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read a 16-bit value from the ADS1115
int read_ads1115(int handle, uint16_t *value) {
    char buf[1];
    buf[0] = ADS1115_REG_CONVERT;

    int result = i2cWriteDevice(handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from ADS1115: %d\n", result);
        return -1;
    }

    *value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to convert the raw ADC reading to amperes
float convert_to_amperes(uint16_t raw_value) {
    // Assuming a 4.096V range and a gain of +/-4.096V
    float voltage = (float)raw_value * 4.096 / 32768.0;
    float current = voltage / 0.004; // 0.004V/A
    return current;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t raw_value;
        if (read_ads1115(i2c_handle, &raw_value) == 0) {
            float current = convert_to_amperes(raw_value);
            printf("Current: %.4f A\n", current);
        } else {
            fprintf(stderr, "Failed to read current\n");
        }

        gpioDelay(500); // Wait 500 milliseconds
    }

    // Close I2C bus and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

