            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Create sensor data
        SensorData data;
        data.timestamp = time(NULL);
        data.flame_detected = flame_detected;
        data.temperature = temperature;

        // Log data
        if (log_data(data) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

