#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Configuration
#define FLAME_SENSOR_GPIO 4
#define BUZZER_GPIO 27
#define ADS1115_I2C_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERSION_REG 0x00
#define TEMPERATURE_THRESHOLD 60.0
#define DEBOUNCE_DELAY_MS 50
#define BUZZER_DURATION_S 2
#define LOG_FILE_NAME "fire_log.txt"

// Global variables
static volatile int running = 1;
static int i2c_handle;
static FILE *log_file;

// Function prototypes
int initialize_gpio();
int initialize_i2c();
int configure_ads1115();
int read_temperature();
int read_flame_sensor();
void activate_buzzer();
void deactivate_buzzer();
void log_event(const char *message);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int flame_detected;
    float temperature;
} SensorData;

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off initially

    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-1");

    i2c_handle = open(i2c_device, O_RDWR);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        return -1;
    }

    if (ioctl(i2c_handle, I2C_SLAVE, ADS1115_I2C_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave: %s\n", strerror(errno));
        close(i2c_handle);
        return -1;
    }

    return 0;
}

// Function to configure ADS1115
int configure_ads1115() {
    // Configure ADS1115 for single-ended AIN0, 4.096V range, single-shot mode, 128 SPS
    uint16_t config = 0x4003; // 0b0100000000000011
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    if (write(i2c_handle, buf, 3) != 3) {
        fprintf(stderr, "Failed to write to ADS1115 configuration register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read temperature from ADS1115
int read_temperature() {
    char buf[2];
    buf[0] = ADS1115_CONVERSION_REG;

    if (write(i2c_handle, buf, 1) != 1) {
        fprintf(stderr, "Failed to write to ADS1115 conversion register for temperature: %s\n", strerror(errno));
        return -1;
    }

    char read_buf[2];
    if (read(i2c_handle, read_buf, 2) != 2) {
        fprintf(stderr, "Failed to read from ADS1115 conversion register for temperature: %s\n", strerror(errno));
        return -1;
    }

    int16_t raw_value = (read_buf[0] << 8) | read_buf[1];
    float voltage = (raw_value * 4.096) / 32768.0;
    float temperature = (voltage - 0.5) * 100.0;

    return (int)temperature;
}

// Function to read flame sensor
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Function to activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1);
}

// Function to deactivate buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0);
}

// Function to log event to file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    deactivate_buzzer();
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT); // Set back to input
    gpioSetMode(BUZZER_GPIO, PI_INPUT);
    gpioTerminate();
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    printf("Fire detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        SensorData sensor_data;
        int flame_detected = read_flame_sensor();
        int temperature = read_temperature();

        if (flame_detected < 0 || temperature < 0) {
            log_event("Error reading sensor data. Skipping this iteration.");
            gpioDelay(100); // Small delay to avoid spamming errors
            continue;
        }

        sensor_data.flame_detected = flame_detected;
        sensor_data.temperature = (float)temperature;

        // Flame detection
        if (flame_detected == 0) {
            log_event("Flame detected!");
        }

        // Temperature threshold
        if (sensor_data.temperature > TEMPERATURE_THRESHOLD) {
            log_event("Temperature exceeds threshold!");
        }

        // Debounce and fire condition
        if (flame_detected == 0 && sensor_data.temperature > TEMPERATURE_THRESHOLD) {
            activate_buzzer();
            gpioDelay(BUZZER_DURATION_S * 1000); // Delay for buzzer duration
            deactivate_buzzer();
            log_event("Fire event detected!");
        }

        gpioDelay(DEBOUNCE_DELAY_MS); // Debounce delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

