#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define FAN_GPIO 18
#define CURRENT_THRESHOLD 50.0 // Amperes
#define LOG_FILE "current_log.txt"
#define SENSOR_ID "MLX91219_01"

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init(const char *device, int mode, int bits_per_word, int speed);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_mcp3008(int fd, int channel);
float convert_adc_to_current(int adc_value);
int log_current(const char *timestamp, float current, const char *sensor_id);
int control_fan(int gpio_pin, int state);
void signal_handler(int signal);
int open_gpio_chip(const char *chip_name);
int close_gpio_chip(int chip_fd);
int set_gpio_direction(int chip_fd, int pin, const char *direction);
int write_gpio_value(int chip_fd, int pin, int value);

// SPI Initialization
int spi_init(const char *device, int mode, int bits_per_word, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_buf[1];
    mode_buf[0] = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_buf) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_per_word_buf[1];
    bits_per_word_buf[0] = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word_buf) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed_buf[1];
    speed_buf[0] = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_buf) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Convert ADC value to current (Amperes)
float convert_adc_to_current(int adc_value) {
    // Assuming 3.3V reference, 10-bit ADC, and 1000 Ohm load resistor
    // Current = (ADC value / 1023.0) * 3.3 / 1000.0 = (ADC value / 1023.0) * 3.3 / 1000.0
    // Current = (ADC value / 1023.0) * 3.3 / 1000.0
    // Current = (adc_value / 1023.0) * 3.3
    float current = (adc_value / 1023.0) * 3.3;
    return current;
}

// Log current reading to file
int log_current(const char *timestamp, float current, const char *sensor_id) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%s,%.2f\n", timestamp, sensor_id, current);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Control fan
int control_fan(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Open GPIO chip
int open_gpio_chip(const char *chip_name) {
    int chip_fd = gpioInitialise();
    if (chip_fd < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", chip_fd);
        return -1;
    }

    return chip_fd;
}

// Close GPIO chip
int close_gpio_chip(int chip_fd) {
    gpioTerminate();
    return 0;
}

// Set GPIO direction
int set_gpio_direction(int chip_fd, int pin, const char *direction) {
    gpioSetMode(pin, PI_INPUT); // Set as input initially
    return 0;
}

// Write GPIO value
int write_gpio_value(int chip_fd, int pin, int value) {
    gpioWrite(pin, value);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    // Open GPIO chip
    int chip_fd = open_gpio_chip("gpiochip0");
    if (chip_fd < 0) {
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    // Set GPIO direction for fan control
    set_gpio_direction(chip_fd, FAN_GPIO, "out");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, 0); // Channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to current
        float current = convert_adc_to_current(adc_value);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20]; // YYYY-MM-DDTHH:MM:SSZ\0
        time(&rawtime);
        timeinfo = gmtime(&rawtime); // Use gmtime for UTC time
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log current reading
        if (log_current(timestamp, current, SENSOR_ID) < 0) {
            fprintf(stderr, "Error logging current reading.\n");
        }

        // Control fan
        if (current > CURRENT_THRESHOLD) {
            control_fan(FAN_GPIO, 1); // Turn fan ON
        } else {
            control_fan(FAN_GPIO, 0); // Turn fan OFF
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_fan(FAN_GPIO, 0); // Turn fan OFF
    close(spi_fd);
    fclose(log_file);
    close_gpio_chip(chip_fd);

    return 0;
}

