        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed_buf[1];
    speed_buf[0] = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_buf) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI Transfer
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Convert ADC value to current (Amperes)
float convert_adc_to_current(int adc_value) {
    // Assuming 3.3V reference, 10-bit ADC, and 1000 Ohm load resistor
    // Current = (ADC value / 1023.0) * 3.3 / 1000.0 = (ADC value / 1023.0) * 3.3 / 1000.0
    // Current = (ADC value / 1023.0) * 3.3 / 1000.0
    // Current = (adc_value / 1023.0) * 3.3
    float current = (adc_value / 1023.0) * 3.3;
    return current;
}

