    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%s,%.2f\n", timestamp, sensor_id, current);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Control fan
int control_fan(int gpio_pin, int state) {
    gpioWrite(gpio_pin, state);
    return 0;
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Open GPIO chip
int open_gpio_chip(const char *chip_name) {
    int chip_fd = gpioInitialise();
    if (chip_fd < 0) {
        fprintf(stderr, "pigpio initialisation failed: %d\n", chip_fd);
        return -1;
    }

    return chip_fd;
}

// Close GPIO chip
int close_gpio_chip(int chip_fd) {
    gpioTerminate();
    return 0;
}

// Set GPIO direction
int set_gpio_direction(int chip_fd, int pin, const char *direction) {
    gpioSetMode(pin, PI_INPUT); // Set as input initially
    return 0;
}

// Write GPIO value
int write_gpio_value(int chip_fd, int pin, int value) {
    gpioWrite(pin, value);
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (spi_fd < 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(spi_fd);
        return 1;
    }

    // Open GPIO chip
    int chip_fd = open_gpio_chip("gpiochip0");
    if (chip_fd < 0) {
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    // Set GPIO direction for fan control
    set_gpio_direction(chip_fd, FAN_GPIO, "out");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(spi_fd, 0); // Channel 0
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value.\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to current
        float current = convert_adc_to_current(adc_value);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[20]; // YYYY-MM-DDTHH:MM:SSZ\0
        time(&rawtime);
        timeinfo = gmtime(&rawtime); // Use gmtime for UTC time
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

        // Log current reading
        if (log_current(timestamp, current, SENSOR_ID) < 0) {
            fprintf(stderr, "Error logging current reading.\n");
        }

        // Control fan
        if (current > CURRENT_THRESHOLD) {
            control_fan(FAN_GPIO, 1); // Turn fan ON
        } else {
            control_fan(FAN_GPIO, 0); // Turn fan OFF
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_fan(FAN_GPIO, 0); // Turn fan OFF
    close(spi_fd);
    fclose(log_file);
    close_gpio_chip(chip_fd);

    return 0;
}

