#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define MICS4514_ADDR 0x4A
#define CO_REG 0x00
#define NO2_REG 0x02
#define CO_THRESHOLD 25.0
#define ALERT_LOG_FILE "alert_log.txt"
#define CO_LOG_FILE "co_log.txt"

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float co_ppm;
    float no2_ppm;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *co_value, int16_t *no2_value);
float convert_co_to_ppm(int16_t co_value);
int log_co_data(float co_ppm);
int log_alert(float co_ppm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, MICS4514_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from MICS-4514
int read_sensor_data(int16_t *co_value, int16_t *no2_value) {
    char buf[4];
    int result = i2cReadI2CBlockData(i2c_handle, CO_REG, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    *co_value = (int16_t)((buf[0] << 8) | buf[1]);
    *no2_value = (int16_t)((buf[2] << 8) | buf[3]);

    return 0;
}

// Convert CO value to ppm (example conversion, adjust as needed)
float convert_co_to_ppm(int16_t co_value) {
    // This is a placeholder.  A real implementation would
    // involve calibration data and a more accurate conversion formula.
    // For example, using a lookup table or a polynomial function.
    // This example assumes a linear relationship.
    return (float)co_value * 0.1; // Example conversion factor
}

// Log CO data to file
int log_co_data(float co_ppm) {
    FILE *fp = fopen(CO_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", CO_LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, CO: %.2f ppm\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm);

    fclose(fp);
    return 0;
}

// Log alert to file
int log_alert(float co_ppm) {
    FILE *fp = fopen(ALERT_LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening alert log file: %s\n", ALERT_LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, ALERT: CO concentration exceeds threshold (%.2f ppm > %.2f ppm)\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, co_ppm, CO_THRESHOLD);

    fclose(fp);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    int16_t co_value, no2_value;
    float co_ppm;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&co_value, &no2_value) == 0) {
            // Convert CO to ppm
            co_ppm = convert_co_to_ppm(co_value);

            // Log CO data
            if (log_co_data(co_ppm) != 0) {
                fprintf(stderr, "Error logging CO data\n");
            }

            // Check for alert
            if (co_ppm > CO_THRESHOLD) {
                if (log_alert(co_ppm) != 0) {
                    fprintf(stderr, "Error logging alert\n");
                }
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait 5 seconds
        gpioSleep(PI_TIME_RELATIVE, 5, 0);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

