    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    int16_t co_value, no2_value;
    float co_ppm;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&co_value, &no2_value) == 0) {
            // Convert CO to ppm
            co_ppm = convert_co_to_ppm(co_value);

            // Log CO data
