        for (int i = 0; i < NUM_SAMPLES; i++) {
            average_level1 += samples1[i];
            average_level2 += samples2[i];
        }
        average_level1 /= NUM_SAMPLES;
        average_level2 /= NUM_SAMPLES;

        // Log data
        log_data(average_level1);
