        printf("Average Level 1: %.2f dB\n", average_level1);
        printf("Average Level 2: %.2f dB\n", average_level2);

        gpioDelay(100000); // Delay for 100 ms (10 Hz sampling rate)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

