#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define LED_GPIO 27
#define RMS_THRESHOLD 0.5 // RMS threshold in dB
#define SAMPLE_WINDOW_MS 100
#define SAMPLE_RATE_HZ 1000 // 1 kHz
#define NUM_CHANNELS 2
#define NUM_SAMPLES (SAMPLE_WINDOW_MS * SAMPLE_RATE_HZ) / 1000

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold microphone data
typedef struct {
    int16_t data[NUM_SAMPLES];
} MicrophoneData;

// Function prototypes
int spi_init();
int read_mcp3008(int channel);
double calculate_rms(const int16_t *data, int num_samples);
void log_data(double mic1_rms, double mic2_rms);
void control_led(double mic1_rms, double mic2_rms);
void signal_handler(int signal);
void cleanup();

// Function to initialize SPI
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate RMS level
double calculate_rms(const int16_t *data, int num_samples) {
    double sum_of_squares = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum_of_squares += (double)data[i] * data[i];
    }
    double mean_square = sum_of_squares / num_samples;
    return sqrt(mean_square);
}

// Function to log data to file
void log_data(double mic1_rms, double mic2_rms) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f,%.4f\n", timestamp, mic1_rms, mic2_rms);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control LED
void control_led(double mic1_rms, double mic2_rms) {
    if (mic1_rms > RMS_THRESHOLD || mic2_rms > RMS_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
        gpioDelay(500);          // Wait for 500ms
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        MicrophoneData mic1_data, mic2_data;

        // Read data from microphones
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int adc_value = read_mcp3008(0); // Read from channel 0
            if (adc_value < 0) {
                fprintf(stderr, "Error reading from MCP3008 (Mic1)\n");
                break;
            }
            mic1_data.data[i] = (int16_t)adc_value; // Store as int16_t

            adc_value = read_mcp3008(1); // Read from channel 1
            if (adc_value < 0) {
                fprintf(stderr, "Error reading from MCP3008 (Mic2)\n");
                break;
            }
            mic2_data.data[i] = (int16_t)adc_value; // Store as int16_t
        }

        // Calculate RMS levels
        double mic1_rms = calculate_rms(mic1_data.data, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_data.data, NUM_SAMPLES);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Control LED
        control_led(mic1_rms, mic2_rms);

        gpioDelay(1); // Delay for 1ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

