    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("audio_events.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        MicrophoneData mic1_data, mic2_data;

        // Read data from microphones
        for (int i = 0; i < NUM_SAMPLES; i++) {
            int adc_value = read_mcp3008(0); // Read from channel 0
            if (adc_value < 0) {
                fprintf(stderr, "Error reading from MCP3008 (Mic1)\n");
                break;
            }
            mic1_data.data[i] = (int16_t)adc_value; // Store as int16_t

            adc_value = read_mcp3008(1); // Read from channel 1
            if (adc_value < 0) {
                fprintf(stderr, "Error reading from MCP3008 (Mic2)\n");
                break;
            }
            mic2_data.data[i] = (int16_t)adc_value; // Store as int16_t
        }

        // Calculate RMS levels
        double mic1_rms = calculate_rms(mic1_data.data, NUM_SAMPLES);
        double mic2_rms = calculate_rms(mic2_data.data, NUM_SAMPLES);

        // Log data
        log_data(mic1_rms, mic2_rms);

        // Control LED
        control_led(mic1_rms, mic2_rms);

        gpioDelay(1); // Delay for 1ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

