#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define BUFFER_SIZE 100
#define THRESHOLD 50.0
#define SAMPLE_RATE_HZ 10
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ)

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_ads1115(int16_t *raw_value);
float convert_to_current(int16_t raw_value);
void add_to_buffer(CircularBuffer *buffer, float value);
float calculate_average(CircularBuffer *buffer);
void control_led(bool on);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize I2C communication
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the ADS1115 ADC
int configure_ads1115() {
    // Configure for single-ended A0, 4.096V range, 128 SPS, single-shot mode
    uint16_t config = 0x4003; // 0b0100000000000011
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read raw ADC value from the ADS1115
int read_ads1115(int16_t *raw_value) {
    char buf[1];
    buf[0] = CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to conversion register: %d\n", result);
        return -1;
    }

    gpioDelay(9); // Wait for conversion (at least 8ms for 128 SPS)

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from conversion register: %d\n", result);
        return -1;
    }

    *raw_value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Convert raw ADC value to current (assuming 4.096V range)
float convert_to_current(int16_t raw_value) {
    // Assuming 4.096V range, 16-bit ADC
    float voltage = (float)raw_value * 4.096 / 32768.0;
    float current = voltage / 0.004; // 0.004V/A
    return current;
}

// Add a new value to the circular buffer
void add_to_buffer(CircularBuffer *buffer, float value) {
    buffer->buffer[buffer->head] = value;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

// Control the LED
void control_led(bool on) {
    gpioWrite(LED_GPIO, on ? 1 : 0);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    control_led(false); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Configure LED GPIO
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    CircularBuffer current_buffer;
    init_buffer(&current_buffer);

    // Main loop
    while (!terminate) {
        int16_t raw_value;
        if (read_ads1115(&raw_value) == 0) {
            float current = convert_to_current(raw_value);
            add_to_buffer(&current_buffer, current);
            float average_current = calculate_average(&current_buffer);

            if (average_current > THRESHOLD) {
                control_led(true); // Turn on LED
            } else {
                control_led(false); // Turn off LED
            }

            printf("Current: %.2f A, Average: %.2f A\n", current, average_current);
        } else {
            fprintf(stderr, "Failed to read ADC value\n");
        }

        gpioDelay(SAMPLE_PERIOD_US); // Delay for sampling rate
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

