#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL 0
#define MOTOR_GPIO 17
#define CURRENT_THRESHOLD 10.0
#define LOG_FILE "current_log.csv"
#define RETRY_COUNT 3

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    int spi_fd;
    FILE *log_file;
    int motor_gpio;
    float current_threshold;
    char log_file_name[64];
} Config;

// Function prototypes
int spi_init(const char *device, int mode, int bits_per_word, int speed);
int spi_transfer(int fd, uint8_t tx_buf[], uint8_t rx_buf[], int len);
int read_mcp3008(int fd, int channel);
float adc_to_current(int adc_value);
int log_current(FILE *fp, float current);
int check_overcurrent(float current, float threshold);
int motor_control(int gpio, int state);
void signal_handler(int signal);
int cleanup(Config *config);

// SPI initialization function
int spi_init(const char *device, int mode, int bits_per_word, int speed) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode_buf[1];
    mode_buf[0] = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_buf) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits_per_word_buf[1];
    bits_per_word_buf[0] = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word_buf) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Set max speed
    uint32_t speed_buf[1];
    speed_buf[0] = speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_buf) < 0) {
        perror("Error setting max speed");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t tx_buf[], uint8_t rx_buf[], int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int ret = ioctl(fd, SPI_IOC_MESSAGE(1), &transfer);
    if (ret < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// MCP3008 read function
int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    for (int i = 0; i < RETRY_COUNT; ++i) {
        if (spi_transfer(fd, tx_buf, rx_buf, 3) == 0) {
            // Extract ADC value
            int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
            return adc_value;
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d/%d), retrying...\n", i + 1, RETRY_COUNT);
            gpioDelay(10000); // 10ms delay
        }
    }

    fprintf(stderr, "SPI transfer failed after %d attempts\n", RETRY_COUNT);
    return -1;
}

// ADC to current conversion function
float adc_to_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // This is a simplified example and may need calibration
    // based on the sensor's datasheet and your specific setup.
    // The MLX91211 outputs a voltage proportional to the current.
    // You'll need to determine the voltage range and the current range
    // for your specific setup.
    // Example: 0-1023 ADC -> 0-3.3V -> 0-10A
    float voltage = (float)adc_value / 1023.0 * 3.3;
    float current = voltage / 0.01; // Example: 0.01V per A
    return current;
}

// Log current function
int log_current(FILE *fp, float current) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", timestamp, current) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Check overcurrent function
int check_overcurrent(float current, float threshold) {
    return (current > threshold) ? 1 : 0;
}

// Motor control function
int motor_control(int gpio, int state) {
    gpioWrite(gpio, state);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
int cleanup(Config *config) {
    if (config->spi_fd != -1) {
        close(config->spi_fd);
    }
    if (config->log_file != NULL) {
        fclose(config->log_file);
    }
    gpioWrite(config->motor_gpio, 1); // Ensure motor is off
    gpioTerminate();
    return 0;
}

int main() {
    Config config = {
        .spi_fd = -1,
        .log_file = NULL,
        .motor_gpio = MOTOR_GPIO,
        .current_threshold = CURRENT_THRESHOLD,
        .log_file_name = LOG_FILE
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(config.motor_gpio, PI_OUTPUT);
    gpioWrite(config.motor_gpio, 1); // Initialize motor to ON state

    // Initialize SPI
    config.spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (config.spi_fd < 0) {
        cleanup(&config);
        return 1;
    }

    // Open log file
    config.log_file = fopen(config.log_file_name, "a");
    if (config.log_file == NULL) {
        perror("Error opening log file");
        cleanup(&config);
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(config.log_file, 0, SEEK_END);
    long file_size = ftell(config.log_file);
    if (file_size == 0) {
        fprintf(config.log_file, "Timestamp,Current (A)\n");
    }
    rewind(config.log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Log current
        if (log_current(config.log_file, current) != 0) {
            fprintf(stderr, "Failed to log current\n");
        }

        // Check for overcurrent
        int overcurrent = check_overcurrent(current, config.current_threshold);
        if (overcurrent) {
            fprintf(stderr, "Overcurrent detected! Current: %.2f A\n", current);

            // Disable motor
            motor_control(config.motor_gpio, 0);

            // Log overcurrent event
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(config.log_file, "%s,OVERCURRENT\n", timestamp);
            fflush(config.log_file);

            // Wait for 1 second
            gpioDelay(1000000); // 1 second

            // Re-enable motor
            motor_control(config.motor_gpio, 1);
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup(&config);
    return 0;
}

