    return -1;
}

// ADC to current conversion function
float adc_to_current(int adc_value) {
    // Assuming a linear relationship between ADC value and current
    // This is a simplified example and may need calibration
    // based on the sensor's datasheet and your specific setup.
    // The MLX91211 outputs a voltage proportional to the current.
    // You'll need to determine the voltage range and the current range
    // for your specific setup.
    // Example: 0-1023 ADC -> 0-3.3V -> 0-10A
    float voltage = (float)adc_value / 1023.0 * 3.3;
    float current = voltage / 0.01; // Example: 0.01V per A
    return current;
}

// Log current function
int log_current(FILE *fp, float current) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (fprintf(fp, "%s,%.2f\n", timestamp, current) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Check overcurrent function
int check_overcurrent(float current, float threshold) {
    return (current > threshold) ? 1 : 0;
}

// Motor control function
int motor_control(int gpio, int state) {
    gpioWrite(gpio, state);
    return 0;
}

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
int cleanup(Config *config) {
    if (config->spi_fd != -1) {
        close(config->spi_fd);
    }
    if (config->log_file != NULL) {
        fclose(config->log_file);
    }
    gpioWrite(config->motor_gpio, 1); // Ensure motor is off
    gpioTerminate();
    return 0;
}

int main() {
    Config config = {
        .spi_fd = -1,
        .log_file = NULL,
        .motor_gpio = MOTOR_GPIO,
        .current_threshold = CURRENT_THRESHOLD,
        .log_file_name = LOG_FILE
    };

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(config.motor_gpio, PI_OUTPUT);
    gpioWrite(config.motor_gpio, 1); // Initialize motor to ON state

    // Initialize SPI
    config.spi_fd = spi_init(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_SPEED);
    if (config.spi_fd < 0) {
        cleanup(&config);
        return 1;
    }

    // Open log file
    config.log_file = fopen(config.log_file_name, "a");
    if (config.log_file == NULL) {
        perror("Error opening log file");
        cleanup(&config);
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(config.log_file, 0, SEEK_END);
    long file_size = ftell(config.log_file);
    if (file_size == 0) {
        fprintf(config.log_file, "Timestamp,Current (A)\n");
    }
    rewind(config.log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(config.spi_fd, MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Log current
        if (log_current(config.log_file, current) != 0) {
            fprintf(stderr, "Failed to log current\n");
        }

        // Check for overcurrent
        int overcurrent = check_overcurrent(current, config.current_threshold);
        if (overcurrent) {
            fprintf(stderr, "Overcurrent detected! Current: %.2f A\n", current);

            // Disable motor
            motor_control(config.motor_gpio, 0);

            // Log overcurrent event
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(config.log_file, "%s,OVERCURRENT\n", timestamp);
            fflush(config.log_file);

            // Wait for 1 second
            gpioDelay(1000000); // 1 second

            // Re-enable motor
            motor_control(config.motor_gpio, 1);
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup and exit
    cleanup(&config);
    return 0;
}

