#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define ADS1115_CONFIG_REG 0x01
#define ADS1115_CONVERT_REG 0x00
#define GPIO_LED 17
#define PRESSURE_THRESHOLD 105.0
#define NTC_TEMP_OFFSET 25.0
#define NTC_TEMP_SCALE 0.01
#define NTC_TEMP_NOMINAL 100.0
#define NTC_TEMP_RREF 430.0
#define NTC_TEMP_BETA 3950.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_ads1115();
int read_pressure(int16_t *pressure);
int read_temperature(int16_t *temperature);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
void control_led(float pressure);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function to initialize pigpio
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "I2C open failed: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to configure ADS1115
int configure_ads1115() {
    // Configure for single-ended AIN0, 4.096V range, single-shot mode, 128 SPS
    uint16_t config = 0x4003; // 0b0100000000000011
    char buf[3];
    buf[0] = ADS1115_CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "ADS1115 configuration failed: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read pressure from ADS1115
int read_pressure(int16_t *pressure) {
    char buf[2];
    buf[0] = ADS1115_CONVERT_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "ADS1115 conversion start failed: %d\n", result);
        return -1;
    }

    gpioDelay(9000); // Wait for conversion (9ms)

    buf[0] = ADS1115_CONVERT_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "ADS1115 conversion read failed: %d\n", result);
        return -1;
    }

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "ADS1115 conversion data read failed: %d\n", result);
        return -1;
    }

    *pressure = (data[0] << 8) | data[1];
    return 0;
}

// Function to read temperature from ADS1115
int read_temperature(int16_t *temperature) {
    char buf[2];
    buf[0] = ADS1115_CONVERT_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "ADS1115 conversion start failed: %d\n", result);
        return -1;
    }

    gpioDelay(9000); // Wait for conversion (9ms)

    buf[0] = ADS1115_CONVERT_REG;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "ADS1115 conversion read failed: %d\n", result);
        return -1;
    }

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "ADS1115 conversion data read failed: %d\n", result);
        return -1;
    }

    *temperature = (data[0] << 8) | data[1];
    return 0;
}

// Function to convert raw pressure to kPa
float convert_pressure(int16_t raw_pressure) {
    // ADS1115 returns a 16-bit value, left-aligned.
    // The pressure is in the range of 0-4095, so we need to shift right by 4 bits.
    raw_pressure = raw_pressure >> 4;

    // The pressure formula from the MLX90834 datasheet is:
    // Pressure (kPa) = (Raw Pressure - 16383) * 4096 / 32767 * 0.0625
    // The 0.0625 is the conversion factor for the MLX90834.
    return (float)(raw_pressure - 16383) * 4096.0 / 32767.0 * 0.0625;
}

// Function to convert raw temperature to °C
float convert_temperature(int16_t raw_temperature) {
    // ADS1115 returns a 16-bit value, left-aligned.
    // The temperature is in the range of 0-4095, so we need to shift right by 4 bits.
    raw_temperature = raw_temperature >> 4;

    // The temperature formula from the MLX90834 datasheet is:
    // Temperature (°C) = (Raw Temperature - 16383) * 4096 / 32767 * 0.0625 + 25.0
    // The 0.0625 is the conversion factor for the MLX90834.
    return (float)(raw_temperature - 16383) * 4096.0 / 32767.0 * 0.0625 + 25.0;
}

// Function to control the LED
void control_led(float pressure) {
    if (pressure > PRESSURE_THRESHOLD) {
        gpioWrite(GPIO_LED, 1); // Turn LED on
    } else {
        gpioWrite(GPIO_LED, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(GPIO_LED, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_LED, PI_OUTPUT);

    int16_t raw_pressure, raw_temperature;
    float pressure, temperature;
    time_t current_time;
    struct tm *time_info;
    char timestamp[20];

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_pressure(&raw_pressure) == 0 && read_temperature(&raw_temperature) == 0) {
            // Convert raw data to physical units
            pressure = convert_pressure(raw_pressure);
            temperature = convert_temperature(raw_temperature);

            // Get current timestamp
            time(&current_time);
            time_info = localtime(&current_time);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", time_info);

            // Print sensor data
            printf("%s - Pressure: %.2f kPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);

            // Control LED
            control_led(pressure);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

