#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_BUS 0
#define SPI_DEVICE 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0
#define MCP3008_CHANNEL 0
#define OVERCURRENT_THRESHOLD 10.0 // Amps
#define GPIO_SHUTDOWN 27
#define LOG_FILE "current_log.txt"
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_init();
int read_mcp3008(int channel);
float adc_to_current(int adc_value);
int log_current(float current);
void overcurrent_event();
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_bus;
    int spi_device;
    int spi_speed;
    int spi_mode;
    int mcp3008_channel;
    float overcurrent_threshold;
    int gpio_shutdown;
    char *log_file;
    int sample_interval_ms;
} Config;

// SPI initialization function
int spi_init() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = 8,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to convert ADC value to current (example linear conversion)
float adc_to_current(int adc_value) {
    // Assuming 3.3V reference and 10-bit ADC
    float voltage = (float)adc_value / 1023.0 * 3.3;
    float current = voltage * 10.0; // Example: 10V/A
    return current;
}

// Function to log current to file
int log_current(float current) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, Current: %.2f A\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to handle overcurrent event
void overcurrent_event() {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, OVERCURRENT EVENT: Current exceeds threshold (%.2f A > %.2f A)\n", timestamp, OVERCURRENT_THRESHOLD, OVERCURRENT_THRESHOLD);
    fflush(log_file);

    gpioWrite(GPIO_SHUTDOWN, 1); // Set GPIO HIGH to shut down the motor
    fprintf(stderr, "OVERCURRENT EVENT! Shutting down motor.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(GPIO_SHUTDOWN, 0); // Set GPIO LOW to reset motor
    gpioTerminate();

    fprintf(stderr, "Cleanup complete. Exiting.\n");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO27 as output
    gpioSetMode(GPIO_SHUTDOWN, PI_OUTPUT);
    gpioWrite(GPIO_SHUTDOWN, 0); // Ensure motor is off initially

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Motor control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error reading ADC value. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
            continue;
        }

        // Convert ADC value to current
        float current = adc_to_current(adc_value);

        // Log current
        if (log_current(current) != 0) {
            fprintf(stderr, "Error logging current. Retrying in %d ms.\n", SAMPLE_INTERVAL_MS);
        }

        // Check for overcurrent condition
        if (current > OVERCURRENT_THRESHOLD) {
            overcurrent_event();
        }

        // Delay for 100ms
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

