#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define ALARM_GPIO 4
#define VOLTAGE_THRESHOLD 2.5
#define LOG_FILE "co_log.txt"
#define RETRY_COUNT 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float voltage_from_adc(int adc_value);
int log_data(float voltage);
void control_alarm(float voltage);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_baud;
    int alarm_gpio;
    float voltage_threshold;
    char *log_file;
    int retry_count;
} Config;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float voltage_from_adc(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
}

// Function to log data to file
int log_data(float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to control the alarm
void control_alarm(float voltage) {
    if (voltage > VOLTAGE_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Turn alarm ON
    } else {
        gpioWrite(ALARM_GPIO, 0); // Turn alarm OFF
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Turn off alarm
    gpioWrite(ALARM_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value;
        float voltage;
        int retry = 0;

        // Read ADC value with retry mechanism
        while (retry < RETRY_COUNT) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Retry %d failed, retrying...\n", retry + 1);
                retry++;
                gpioDelay(1000); // Wait 1 second before retrying
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", RETRY_COUNT);
            // Log the error to the log file
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (log_file != NULL) {
                fprintf(log_file, "%s,Error: Failed to read ADC value after %d retries\n", timestamp, RETRY_COUNT);
                fflush(log_file);
            }
            gpioDelay(1000); // Wait 1 second before retrying
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        voltage = voltage_from_adc(adc_value);

        // Log data
        if (log_data(voltage) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Control alarm
        control_alarm(voltage);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

