    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to convert ADC value to voltage
float voltage_from_adc(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
}

// Function to log data to file
int log_data(float voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,Voltage: %.2f V\n", timestamp, voltage);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to control the alarm
void control_alarm(float voltage) {
    if (voltage > VOLTAGE_THRESHOLD) {
        gpioWrite(ALARM_GPIO, 1); // Turn alarm ON
