    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return -1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is initially off

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    printf("Cleaning up...\n");

    // Close SPI channel
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Turn off alarm
    gpioWrite(ALARM_GPIO, 0);

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("CO sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value;
        float voltage;
        int retry = 0;

        // Read ADC value with retry mechanism
        while (retry < RETRY_COUNT) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Retry %d failed, retrying...\n", retry + 1);
                retry++;
                gpioDelay(1000); // Wait 1 second before retrying
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", RETRY_COUNT);
            // Log the error to the log file
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            if (log_file != NULL) {
                fprintf(log_file, "%s,Error: Failed to read ADC value after %d retries\n", timestamp, RETRY_COUNT);
                fflush(log_file);
            }
            gpioDelay(1000); // Wait 1 second before retrying
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        voltage = voltage_from_adc(adc_value);

        // Log data
        if (log_data(voltage) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Control alarm
        control_alarm(voltage);

        // Wait for 1 second
        gpioDelay(1000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

