    // 4. Set MODE (bits 7-6) to Single-shot (01)
    // 5. Set DR (bits 5-3) to 128 SPS (011)
    // 6. Set COMP_MODE (bits 2-0) to Traditional comparator (000)
    // 7. Set COMP_POL (bit 1) to Active low (0)
    // 8. Set COMP_LAT (bit 0) to Non-latching (0)
    // 9. Set COMP_QUE (bits 5-3) to Disable comparator (000)

    uint16_t config_value = 0x4083; // Start single conversion, AIN0, +/- 4.096V, 128 SPS, single-shot

    int result = i2cWriteWordData(i2c_handle, CONFIG_REG, config_value);
    if (result < 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read raw pressure value from ADS1115
int read_pressure(int i2c_handle, int *raw_pressure) {
    int result = i2cReadWordData(i2c_handle, CONVERSION_REG);
    if (result < 0) {
        fprintf(stderr, "Failed to read from conversion register: %d\n", result);
        return -1;
    }

    *raw_pressure = result;
    return 0;
}

// Convert raw pressure value to kPa
float convert_to_kpa(int raw_pressure) {
    // ADS1115 returns a 16-bit signed integer, left-aligned.
    // The pressure range is 0-4.096V, so the raw value needs to be scaled to 0-65535.
    // The conversion formula is:
    // pressure_kPa = (raw_pressure / 65535.0) * pressure_range
    float pressure_kPa = (float)raw_pressure / 65535.0 * PRESSURE_RANGE_KPA;
    return pressure_kPa;
}

// Validate pressure value
int validate_pressure(float pressure) {
    if (pressure >= 0.0 && pressure <= PRESSURE_RANGE_KPA) {
        return 1; // Valid
    } else {
        return 0; // Invalid
    }
}

// Log pressure value with timestamp
int log_pressure(float pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return -1;
    }

    fprintf(fp, "%s,%.2f\n", timestamp, pressure);
    fclose(fp);

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115(i2c_handle) != 0) {
        cleanup();
        return 1;
    }

    printf("Pressure monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int raw_pressure;
        float pressure;

        // Read pressure
        if (read_pressure(i2c_handle, &raw_pressure) == 0) {
            // Convert to kPa
            pressure = convert_to_kpa(raw_pressure);

            // Validate pressure
            if (validate_pressure(pressure)) {
                // Log pressure
                if (log_pressure(pressure) != 0) {
                    fprintf(stderr, "Failed to log pressure\n");
                }
            } else {
                fprintf(stderr, "Invalid pressure value: %.2f kPa\n", pressure);
            }
        } else {
            fprintf(stderr, "Failed to read pressure\n");
        }

        // Delay for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

