#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define CS_PIN 8         // GPIO8 (CE0)
#define HUMIDITY_THRESHOLD 80.0
#define LOG_FILE "humidity_log.txt"
#define EMAIL_RECIPIENT "recipient@example.com"
#define EMAIL_SUBJECT "Humidity Alert"
#define EMAIL_BODY "Humidity level exceeded threshold!\nHumidity: %.2f%%\nTimestamp: %s"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3208(int channel);
float calculate_humidity(int adc_value);
float calculate_temperature(int adc_value);
int log_data(float humidity, float temperature);
int send_email_alert(float humidity);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    float humidity;
    float temperature;
} sensor_data_t;

// Function to initialize the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the MCP3208 ADC
int read_mcp3208(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3208 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message (MCP3208 datasheet)
    tx_buffer[0] = 0x01;                           // Start bit
    tx_buffer[1] = (0x08 | channel) << 4;           // Single-ended mode, channel select
    tx_buffer[2] = 0x00;                           // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate humidity from ADC value
float calculate_humidity(int adc_value) {
    // HIH-4602-A datasheet formula
    float humidity = ((float)adc_value / 1023.0) * 100.0;
    return humidity;
}

// Function to calculate temperature from ADC value (simplified linear approximation)
float calculate_temperature(int adc_value) {
    // HIH-4602-A datasheet formula (simplified)
    float temperature = ((float)adc_value / 1023.0) * 165.0 - 40.0;
    return temperature;
}

// Function to log data to a file
int log_data(float humidity, float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, humidity, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to send an email alert
int send_email_alert(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    char body[256];

    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    snprintf(body, sizeof(body), EMAIL_BODY, humidity, timestamp);

    char command[512];
    snprintf(command, sizeof(command), "echo \"%s\" | ssmtp %s", body, EMAIL_RECIPIENT);

    int status = system(command);
    if (status == -1) {
        fprintf(stderr, "Error executing ssmtp command\n");
        return -1;
    } else if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        fprintf(stderr, "ssmtp command failed with status %d\n", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the chip initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Humidity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc_value_humidity = read_mcp3208(0);
        int adc_value_temperature = read_mcp3208(1);

        if (adc_value_humidity == -1 || adc_value_temperature == -1) {
            fprintf(stderr, "Error reading ADC values, retrying...\n");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Calculate humidity and temperature
        float humidity = calculate_humidity(adc_value_humidity);
        float temperature = calculate_temperature(adc_value_temperature);

        // Log data
        log_data(humidity, temperature);

        // Check humidity threshold and send email alert
        if (humidity > HUMIDITY_THRESHOLD) {
            printf("Humidity threshold exceeded! Humidity: %.2f%%\n", humidity);
            send_email_alert(humidity);
        }

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

