#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Si1172 I2C address
#define SI1172_ADDR 0x49

// Si1172 register addresses (Example - adjust based on datasheet)
#define REG_PART_ID 0x00
#define REG_HW_REV 0x01
#define REG_SEQ_ID 0x02
#define REG_INT_CFG 0x03
#define REG_INT_EN 0x04
#define REG_RSP0_CFG 0x07
#define REG_RSP1_CFG 0x08
#define REG_RSP2_CFG 0x09
#define REG_RSP3_CFG 0x0A
#define REG_IRQ_STATUS 0x0B
#define REG_IRQ_ENABLE 0x0C
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_ALS_IR_DATA0 0x24
#define REG_ALS_IR_DATA1 0x25
#define REG_PS1_DATA0 0x26
#define REG_PS1_DATA1 0x27
#define REG_COMMAND 0x30

// Commands
#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06
#define CMD_PS_FORCE 0x07

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int hr;
    int spo2;
    int error_flag;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the Si1172 sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure sensor (Example - adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, REG_INT_CFG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write INT_CFG.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_INT_EN, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write INT_EN.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_RSP0_CFG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write RSP0_CFG.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_RSP1_CFG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write RSP1_CFG.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_RSP2_CFG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write RSP2_CFG.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_RSP3_CFG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write RSP3_CFG.\n");
        return -1;
    }

    // Start ALS and PS measurements
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_ALS_FORCE) < 0) {
        fprintf(stderr, "Error: Failed to start ALS measurement.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_PS_FORCE) < 0) {
        fprintf(stderr, "Error: Failed to start PS measurement.\n");
        return -1;
    }

    return 0;
}

// Reads raw sensor data from the Si1172
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    int als_vis_low, als_vis_high, als_ir_low, als_ir_high, ps1_low, ps1_high;

    // Read ALS data
    als_vis_low = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
    als_vis_high = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA1);
    als_ir_low = i2cReadByteData(i2c_handle, REG_ALS_IR_DATA0);
    als_ir_high = i2cReadByteData(i2c_handle, REG_ALS_IR_DATA1);

    // Read PS1 data
    ps1_low = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
    ps1_high = i2cReadByteData(i2c_handle, REG_PS1_DATA1);

    if (als_vis_low < 0 || als_vis_high < 0 || als_ir_low < 0 || als_ir_high < 0 || ps1_low < 0 || ps1_high < 0) {
        data.error_flag = 1; // I2C read error
        data.hr = -1;
        data.spo2 = -1;
        fprintf(stderr, "Error: Failed to read sensor data.\n");
        return data;
    }

    // Combine high and low bytes (assuming little-endian)
    int als_vis = (als_vis_high << 8) | als_vis_low;
    int als_ir = (als_ir_high << 8) | als_ir_low;
    int ps1 = (ps1_high << 8) | ps1_low;

    // Dummy HR and SpO2 calculations (replace with actual algorithm)
    data.hr = (als_vis + als_ir) / 2; // Example: Average ALS values
    data.spo2 = (ps1 + 100) / 2;    // Example: Add a constant and divide by 2
    data.error_flag = 0; // OK

    return data;
}

// Logs sensor data to a CSV file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.hr, data.spo2, data.error_flag);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, SI1172_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed (%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("biometric_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,HR (bpm),SpO2 (%),Error Flag\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(1000); // Sample every 1 second
    }

    // Close I2C connection and log file
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

