#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define ADC_CHANNEL 0
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 5.0
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_adc(int channel);
float convert_to_flow_rate(int adc_value);
int validate_flow_rate(float flow_rate);
int log_flow_rate(float flow_rate);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int adc_channel;
    float flow_rate_min;
    float flow_rate_max;
    char *log_file;
    int sample_interval_us;
} Config;

// Initialize configuration
Config config = {
    SPI_CHANNEL,
    SPI_SPEED,
    ADC_CHANNEL,
    FLOW_RATE_MIN,
    FLOW_RATE_MAX,
    LOG_FILE,
    SAMPLE_INTERVAL_US
};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_adc(config.adc_channel);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to flow rate
        float flow_rate = convert_to_flow_rate(adc_value);

        // Validate flow rate
        if (validate_flow_rate(flow_rate) != 0) {
            fprintf(stderr, "Invalid flow rate: %.2f L/min\n", flow_rate);
            continue; // Skip to the next iteration
        }

        // Log flow rate
        if (log_flow_rate(flow_rate) != 0) {
            fprintf(stderr, "Failed to log flow rate\n");
        }

        // Wait for the next sample
        gpioDelay(config.sample_interval_us);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(config.spi_channel, config.spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read ADC value from MCP3008
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message
    uint8_t tx_buffer[3];
    uint8_t rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Convert ADC value to flow rate (L/min)
float convert_to_flow_rate(int adc_value) {
    // Assuming 0 ADC corresponds to 0 L/min and 1023 ADC corresponds to 5 L/min
    // This is a linear approximation.  A more accurate conversion would require
    // calibration data from the sensor.
    return (float)adc_value * (FLOW_RATE_MAX - FLOW_RATE_MIN) / 1023.0 + FLOW_RATE_MIN;
}

// Validate flow rate
int validate_flow_rate(float flow_rate) {
    if (flow_rate < FLOW_RATE_MIN || flow_rate > FLOW_RATE_MAX) {
        return -1;
    }
    return 0;
}

// Log flow rate to file
int log_flow_rate(float flow_rate) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

