// ICP-10125 I2C address
#define ICP10125_ADDR 0x69

// ICP-10125 register addresses
#define ICP10125_REG_PRODUCT_ID 0x00
#define ICP10125_REG_RESET 0x01
#define ICP10125_REG_MEASURE 0x02
#define ICP10125_REG_PRESSURE_MSB 0x03
#define ICP10125_REG_PRESSURE_LSB 0x04
#define ICP10125_REG_TEMPERATURE_MSB 0x05
#define ICP10125_REG_TEMPERATURE_LSB 0x06
#define ICP10125_REG_CRC 0x07

// Calibration coefficients (example values, replace with actual values from datasheet)
#define PRESSURE_OFFSET 0.0
#define PRESSURE_SCALE 1.0
#define TEMPERATURE_OFFSET 0.0
#define TEMPERATURE_SCALE 1.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold calibration coefficients
typedef struct {
    float pressure_offset;
    float pressure_scale;
    float temperature_offset;
    float temperature_scale;
} calibration_coeffs_t;

calibration_coeffs_t coeffs = {PRESSURE_OFFSET, PRESSURE_SCALE, TEMPERATURE_OFFSET, TEMPERATURE_SCALE};

// Function prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(int16_t *pressure, int16_t *temperature);
float convert_pressure(int16_t raw_pressure);
float convert_temperature(int16_t raw_temperature);
int log_data(float pressure, float temperature);
void display_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, ICP10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the ICP-10125 sensor
int init_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, ICP10125_REG_RESET, 0x80) < 0) {
        fprintf(stderr, "Failed to reset sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Verify product ID (example)
    int product_id = i2cReadByteData(i2c_handle, ICP10125_REG_PRODUCT_ID);
    if (product_id < 0) {
        fprintf(stderr, "Failed to read product ID\n");
        return -1;
    }
    if (product_id != 0x41) {
        fprintf(stderr, "Incorrect product ID: 0x%02X\n", product_id);
        return -1;
    }

    return 0;
}

// Read raw pressure and temperature data from the sensor
int read_sensor_data(int16_t *pressure, int16_t *temperature) {
    char buf[6];

    // Trigger measurement
    if (i2cWriteByteData(i2c_handle, ICP10125_REG_MEASURE, 0x01) < 0) {
        fprintf(stderr, "Failed to trigger measurement\n");
        return -1;
    }

    gpioDelay(10); // Wait for measurement to complete

    // Read 6 bytes of data
    if (i2cReadI2CBlockData(i2c_handle, ICP10125_REG_PRESSURE_MSB, buf, 6) != 6) {
        fprintf(stderr, "Failed to read sensor data\n");
        return -1;
    }

    // Combine MSB and LSB for pressure and temperature
    *pressure = (int16_t)((buf[0] << 8) | buf[1]);
    *temperature = (int16_t)((buf[3] << 8) | buf[4]);

    return 0;
}

// Convert raw pressure data to Pascals
float convert_pressure(int16_t raw_pressure) {
    return coeffs.pressure_offset + (float)raw_pressure * coeffs.pressure_scale;
}

// Convert raw temperature data to degrees Celsius
float convert_temperature(int16_t raw_temperature) {
    return coeffs.temperature_offset + (float)raw_temperature * coeffs.temperature_scale;
}

// Log data to a CSV file
int log_data(float pressure, float temperature) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Display data on the console
void display_data(float pressure, float temperature) {
    printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("environmental_data.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    rewind(log_file);

    int16_t raw_pressure, raw_temperature;
    float pressure, temperature;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&raw_pressure, &raw_temperature) == 0) {
            // Convert raw data to physical units
            pressure = convert_pressure(raw_pressure);
            temperature = convert_temperature(raw_temperature);

            // Log data
            log_data(pressure, temperature);

            // Display data
            display_data(pressure, temperature);
        } else {
            fprintf(stderr, "Failed to read sensor data, retrying in 5 seconds...\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000); // pigpioDelay takes milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

