#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Define MCP3008 channel numbers
#define MIC1_CHANNEL 0
#define MIC2_CHANNEL 1

// Define noise cancellation threshold
#define NOISE_THRESHOLD 500

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold program configuration
typedef struct {
    int gain1;
    int gain2;
} ProgramConfig;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
int apply_noise_cancellation(int mic1_sample, int mic2_sample, int gain1, int gain2);
void print_csv(int mic1_sample, int mic2_sample, int noise_cancellation);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Reads the analog value from the MCP3008
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    // Construct SPI message
    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Applies the noise cancellation algorithm
int apply_noise_cancellation(int mic1_sample, int mic2_sample, int gain1, int gain2) {
    int noise_cancellation = mic1_sample - (gain1 * mic2_sample);
    if (noise_cancellation < -NOISE_THRESHOLD) {
        noise_cancellation = -NOISE_THRESHOLD;
    } else if (noise_cancellation > NOISE_THRESHOLD) {
        noise_cancellation = NOISE_THRESHOLD;
    }
    return noise_cancellation;
}

// Prints the audio samples to the terminal in CSV format
void print_csv(int mic1_sample, int mic2_sample, int noise_cancellation) {
    printf("%d,%d,%d\n", mic1_sample, mic2_sample, noise_cancellation);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <gain1> <gain2>\n", argv[0]);
        return 1;
    }

    int gain1 = atoi(argv[1]);
    int gain2 = atoi(argv[2]);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read audio samples from microphones
        int mic1_sample = read_mcp3008(MIC1_CHANNEL);
        int mic2_sample = read_mcp3008(MIC2_CHANNEL);

        if (mic1_sample < 0 || mic2_sample < 0) {
            fprintf(stderr, "Error reading audio samples, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Apply noise cancellation
        int noise_cancellation = apply_noise_cancellation(mic1_sample, mic2_sample, gain1, gain2);

        // Print audio samples to the terminal
        print_csv(mic1_sample, mic2_sample, noise_cancellation);

        // Delay for a short period
        gpioDelay(10); // 10 ms
    }

    // Close SPI connection and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

