#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <math.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define BUZZER_GPIO 18
#define AMBIENT_TEMP_FILE "ambient_temp.txt"
#define LOG_FILE "flame_log.txt"
#define RETRY_COUNT 3
#define SAMPLE_INTERVAL_MS 500

// Global variables
static volatile int keep_running = 1;
static int spi_fd = -1;
static FILE *log_file = NULL;

// Function prototypes
int spi_transfer(uint8_t mode, uint8_t channel);
float read_ambient_temperature();
float compensate_voltage(int raw_adc, float ambient_temp);
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected);
void signal_handler(int sig);

// SPI transfer function
int spi_transfer(uint8_t mode, uint8_t channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct spi_ioc_transfer tr = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | (channel & 0x07)) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Dummy byte

    int retries = 0;
    while (retries < RETRY_COUNT) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &tr) >= 1) {
            // Success
            return (rx_buf[1] & 0x03) << 8 | rx_buf[2]; // Extract 10-bit ADC value
        } else {
            // Error
            fprintf(stderr, "SPI transfer failed (attempt %d): %s\n", retries + 1, strerror(errno));
            fprintf(log_file, "SPI transfer failed (attempt %d): %s\n", retries + 1, strerror(errno));
            fflush(log_file);
            retries++;
            usleep(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "SPI transfer failed after %d retries.\n", RETRY_COUNT);
    fprintf(log_file, "SPI transfer failed after %d retries.\n", RETRY_COUNT);
    fflush(log_file);
    return -1; // Indicate failure
}

// Function to read ambient temperature from file
float read_ambient_temperature() {
    FILE *fp = fopen(AMBIENT_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening ambient temperature file: %s. Using default temperature of 25.0\n", strerror(errno));
        fprintf(log_file, "Error opening ambient temperature file: %s. Using default temperature of 25.0\n", strerror(errno));
        fflush(log_file);
        return 25.0;
    }

    float temp;
    if (fscanf(fp, "%f", &temp) != 1) {
        fprintf(stderr, "Error reading ambient temperature from file. Using default temperature of 25.0\n");
        fprintf(log_file, "Error reading ambient temperature from file. Using default temperature of 25.0\n");
        fflush(log_file);
        fclose(fp);
        return 25.0;
    }

    fclose(fp);
    return temp;
}

// Function to compensate voltage
float compensate_voltage(int raw_adc, float ambient_temp) {
    // Linear approximation (replace with actual calibration data)
    float voltage = (float)raw_adc * 3.3 / 1023.0; // Assuming 3.3V reference
    float temperature_offset = 25.0; // Example offset
    float compensated_voltage = voltage + (temperature_offset - ambient_temp) * 0.01; // Example compensation
    return compensated_voltage;
}

// Function to log data to file
void log_data(int raw_adc, float voltage, float compensated_voltage, float temperature, int flame_detected) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d,%d,%.3f,%.3f,%.3f,%d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            raw_adc, voltage, compensated_voltage, temperature, flame_detected);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    keep_running = 0;
}

int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Configure max speed hz
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting max speed hz: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Set buzzer GPIO as output
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting buzzer GPIO mode: %s\n", strerror(errno));
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read ambient temperature
        float ambient_temp = read_ambient_temperature();

        // Read ADC value
        int raw_adc = spi_transfer(SPI_MODE, 0);
        if (raw_adc < 0) {
            fprintf(stderr, "Error reading ADC value. Skipping iteration.\n");
            fprintf(log_file, "Error reading ADC value. Skipping iteration.\n");
            fflush(log_file);
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before next iteration
            continue;
        }

        // Compensate voltage
        float voltage = compensate_voltage(raw_adc, ambient_temp);

        // Check for flame detection (example: voltage below a threshold)
        int flame_detected = (voltage < 0.5); // Assuming 0.5V is below the threshold

        // Log data
        log_data(raw_adc, voltage, voltage, ambient_temp, flame_detected);

        // Control buzzer
        gpioWrite(BUZZER_GPIO, flame_detected);

        // Wait for next sample
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    fclose(log_file);
    close(spi_fd);

    fprintf(stderr, "Program finished.\n");
    return 0;
}

