int main() {
    // Initialize signal handling
    signal(SIGINT, signal_handler);

    // Open SPI device
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error opening SPI device: %s\n", strerror(errno));
        return 1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Configure max speed hz
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        fprintf(stderr, "Error setting max speed hz: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        close(spi_fd);
        return 1;
    }

    // Set buzzer GPIO as output
    if (gpioSetMode(BUZZER_GPIO, PI_OUTPUT) != 0) {
        fprintf(stderr, "Error setting buzzer GPIO mode: %s\n", strerror(errno));
        fclose(log_file);
        close(spi_fd);
        return 1;
    }

    // Main loop
    while (keep_running) {
        // Read ambient temperature
        float ambient_temp = read_ambient_temperature();

        // Read ADC value
        int raw_adc = spi_transfer(SPI_MODE, 0);
        if (raw_adc < 0) {
            fprintf(stderr, "Error reading ADC value. Skipping iteration.\n");
            fprintf(log_file, "Error reading ADC value. Skipping iteration.\n");
            fflush(log_file);
            usleep(SAMPLE_INTERVAL_MS * 1000); // Wait before next iteration
            continue;
        }

        // Compensate voltage
        float voltage = compensate_voltage(raw_adc, ambient_temp);

        // Check for flame detection (example: voltage below a threshold)
        int flame_detected = (voltage < 0.5); // Assuming 0.5V is below the threshold

        // Log data
        log_data(raw_adc, voltage, voltage, ambient_temp, flame_detected);

        // Control buzzer
        gpioWrite(BUZZER_GPIO, flame_detected);

        // Wait for next sample
        usleep(SAMPLE_INTERVAL_MS * 1000);
    }

    // Cleanup
    gpioWrite(BUZZER_GPIO, 0); // Turn off buzzer
    fclose(log_file);
    close(spi_fd);

    fprintf(stderr, "Program finished.\n");
    return 0;
}

