#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define LED_GPIO 17
#define WATER_LEVEL_THRESHOLD_HIGH 75.0
#define WATER_LEVEL_THRESHOLD_LOW 70.0
#define SAMPLE_INTERVAL_SEC 5
#define SAMPLE_INTERVAL_MS 100

// Global variables
int spi_handle;
FILE *json_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_water_level(int adc_value);
void control_led(float water_level);
void log_data(float water_level);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate water level percentage
float calculate_water_level(int adc_value) {
    // Assuming ADC value ranges from 0 to 1023
    // Water level is inversely proportional to ADC value
    // 0%: 1023
    // 100%: 0
    float water_level = 100.0 - ((float)adc_value / 1023.0) * 100.0;
    return water_level;
}

// Function to control the LED based on water level
void control_led(float water_level) {
    if (water_level > WATER_LEVEL_THRESHOLD_HIGH) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else if (water_level < WATER_LEVEL_THRESHOLD_LOW) {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Function to log data to JSON file
void log_data(float water_level) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%S", tstruct);

    // Get milliseconds
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    char json_string[256];
    snprintf(json_string, sizeof(json_string), "{\"timestamp\": \"%s.%03ld\", \"water_level\": %.2f}\n", buf, milliseconds, water_level);

    // Append to JSON file
    if (json_file != NULL) {
        fprintf(json_file, "%s", json_string);
        fflush(json_file); // Ensure data is written immediately
    } else {
        fprintf(stderr, "Error: JSON file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

