    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open JSON file for appending
    json_file = fopen("water_levels.json", "a");
    if (json_file == NULL) {
        fprintf(stderr, "Error: Failed to open water_levels.json for writing\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Write opening bracket to JSON file
    fprintf(json_file, "[\n");

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value, skipping this iteration.\n");
            gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Sleep for 100ms
            continue;
        }

        // Calculate water level
        float water_level = calculate_water_level(adc_value);

        // Control LED
        control_led(water_level);

        // Log data
        log_data(water_level);

        // Sleep for the specified interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // Sleep for 5000ms (5 seconds)
    }

    // Cleanup
    // Close SPI channel
    spiClose(spi_handle);

    // Turn off LED
    gpioWrite(LED_GPIO, 0);

    // Close JSON file
    if (json_file != NULL) {
        fprintf(json_file, "]\n");
        fclose(json_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

