    fprintf(stderr, "Cleaning up...\n");

    // Close SPI device
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int sleep_interval = SLEEP_INTERVAL;

    // Parse command-line arguments
    if (argc > 1) {
        sleep_interval = atoi(argv[1]);
        if (sleep_interval <= 0) {
            fprintf(stderr, "Error: Invalid sleep interval. Using default value (%d seconds).\n", sleep_interval);
            sleep_interval = SLEEP_INTERVAL;
        }
    }

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    fprintf(stderr, "Soil moisture monitoring started. Sleeping for %d seconds...\n", sleep_interval);

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value. Skipping this iteration.\n");
            sleep(sleep_interval);
            continue;
        }

        // Calculate moisture percentage
        float moisture_percentage = calculate_moisture_percentage(adc_value);

        // Log data
        log_data(adc_value, moisture_percentage);

        // Sleep for the specified interval
        sleep(sleep_interval);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

