#define ADC_CHANNEL 0
#define LOG_INTERVAL_SEC 5

// Global variables
int spi_fd = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold configuration data
typedef struct {
    const char *spi_device;
    int spi_mode;
    int spi_bits_per_word;
    int spi_speed;
    int adc_channel;
    int log_interval_sec;
} Config;

// Function prototypes
int spi_init(const char *spi_device, int spi_mode, int spi_bits_per_word, int spi_speed);
int spi_transfer(int spi_fd, uint8_t tx_buf[], uint8_t rx_buf[], int len);
int read_adc(int spi_fd, int channel);
float calculate_moisture_percentage(int adc_value);
void log_data(int adc_value, float moisture_percentage);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", sig);
}

// Initialize SPI interface
int spi_init(const char *spi_device, int spi_mode, int spi_bits_per_word, int spi_speed) {
    int fd = open(spi_device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = spi_mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = spi_bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = spi_speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting SPI speed");
        close(fd);
        return -1;
    }

    return fd;
}

