#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define MCP3008_CHANNEL 0 // MLX90823 connected to channel 0
#define VREF 3.3          // Reference voltage for MCP3008
#define MIN_PRESSURE 0.0   // Minimum pressure in kPa
#define MAX_PRESSURE 100.0  // Maximum pressure in kPa
#define MIN_VOLTAGE 0.0     // Minimum voltage in V
#define MAX_VOLTAGE 3.3     // Maximum voltage in V
#define SENSOR_ID "MLX90823"

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    char sensor_id[20];
    float pressure;
    float voltage;
} sensor_data_t;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_pressure(float voltage);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "SPI transfer error: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Convert ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Convert voltage to pressure (kPa) using linear approximation
float voltage_to_pressure(float voltage) {
    // Assuming a linear relationship between voltage and pressure
    // This is a simplified example and may need calibration
    // based on the sensor's datasheet and calibration curve.
    // For example, a more complex relationship might be needed.
    // This example assumes a linear relationship between 0V and 3.3V and 0kPa and 100kPa.
    return (voltage / VREF) * (MAX_PRESSURE - MIN_PRESSURE) + MIN_PRESSURE;
}

// Log data to console with timestamp
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - Sensor ID: %s, Pressure: %.2f kPa, Voltage: %.2f V\n",
           timestamp, data.sensor_id, data.pressure, data.voltage);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to voltage
        float voltage = adc_to_voltage(adc_value);

        // Convert voltage to pressure
        float pressure = voltage_to_pressure(voltage);

        // Validate sensor readings
        if (voltage < MIN_VOLTAGE || voltage > MAX_VOLTAGE) {
            fprintf(stderr, "Warning: Voltage out of range: %.2f V\n", voltage);
        }

        if (pressure < MIN_PRESSURE || pressure > MAX_PRESSURE) {
            fprintf(stderr, "Warning: Pressure out of range: %.2f kPa\n", pressure);
        }

        // Create sensor data structure
        sensor_data_t data;
        strncpy(data.sensor_id, SENSOR_ID, sizeof(data.sensor_id) - 1);
        data.sensor_id[sizeof(data.sensor_id) - 1] = '\0'; // Ensure null termination
        data.pressure = pressure;
        data.voltage = voltage;

        // Log data
        log_data(data);

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

