// Define the I2C bus and address
#define I2C_BUS 1
#define MAX30102_ADDR 0x57

// Define register addresses
#define MAX30102_REG_INTR_STATUS_1 0x00
#define MAX30102_REG_INTR_ENABLE_1 0x01
#define MAX30102_REG_FIFO_WR_PTR 0x02
#define MAX30102_REG_OVERFLOW_CTR 0x03
#define MAX30102_REG_FIFO_RD_PTR 0x04
#define MAX30102_REG_FIFO_DATA 0x07
#define MAX30102_REG_FIFO_CONFIG 0x08
#define MAX30102_REG_MODE_CONFIG 0x09
#define MAX30102_REG_SPO2_CONFIG 0x0A
#define MAX30102_REG_LED1_PA 0x0C
#define MAX30102_REG_LED2_PA 0x0D
#define MAX30102_REG_PILOT_PA 0x0E
#define MAX30102_REG_TEMP_INTR 0x1F
#define MAX30102_REG_TEMP_FRAC 0x20
#define MAX30102_REG_TEMP_VALUE 0x21
#define MAX30102_REG_PROX_INT_THRESH 0x30
#define MAX30102_REG_REV_ID 0xFE
#define MAX30102_REG_PART_ID 0xFF

// Define modes
#define MAX30102_MODE_SPO2_HR 0x03

// Define LED pulse amplitudes
#define MAX30102_LED_CURRENT_0_1MA 0x00
#define MAX30102_LED_CURRENT_4_0MA 0x01
#define MAX30102_LED_CURRENT_7_0MA 0x02
#define MAX30102_LED_CURRENT_10MA 0x03

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_max30102();
int read_max30102_data(int *spo2, int *hr);
void log_health_data(int spo2, int hr);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize the MAX30102 sensor
int init_max30102() {
    // Check Part ID
    int part_id = i2cReadByteData(i2c_handle, MAX30102_REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error reading Part ID: %d\n", part_id);
        return -1;
    }
    if (part_id != 0x10) {
        fprintf(stderr, "Error: Invalid Part ID: 0x%02X\n", part_id);
        return -1;
    }

    // Configure mode
    if (i2cWriteByteData(i2c_handle, MAX30102_REG_MODE_CONFIG, MAX30102_MODE_SPO2_HR) < 0) {
        fprintf(stderr, "Error writing to MODE_CONFIG\n");
        return -1;
    }

    // Configure SpO2
    if (i2cWriteByteData(i2c_handle, MAX30102_REG_SPO2_CONFIG, 0x27) < 0) { // Sample rate = 100 Hz, LED pulse width = 400us
        fprintf(stderr, "Error writing to SPO2_CONFIG\n");
        return -1;
    }

    // Configure LED current
    if (i2cWriteByteData(i2c_handle, MAX30102_REG_LED1_PA, MAX30102_LED_CURRENT_10MA) < 0) {
        fprintf(stderr, "Error writing to LED1_PA\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MAX30102_REG_LED2_PA, MAX30102_LED_CURRENT_10MA) < 0) {
        fprintf(stderr, "Error writing to LED2_PA\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MAX30102_REG_PILOT_PA, MAX30102_LED_CURRENT_10MA) < 0) {
        fprintf(stderr, "Error writing to PILOT_PA\n");
        return -1;
    }

    return 0;
}

// Read SpO2 and heart-rate data from the MAX30102
int read_max30102_data(int *spo2, int *hr) {
    // Read FIFO data (2 bytes per sample)
    char buffer[6];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, MAX30102_REG_FIFO_DATA, buffer, 6);

    if (bytes_read != 6) {
        fprintf(stderr, "Error reading FIFO data: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int raw_hr = (buffer[0] << 8) | buffer[1];
    int raw_spo2 = (buffer[2] << 8) | buffer[3];

    // Validate data (example ranges, adjust as needed)
    if (raw_hr < 40 || raw_hr > 200 || raw_spo2 < 70 || raw_spo2 > 100) {
        fprintf(stderr, "Warning: Invalid HR or SpO2 data: HR=%d, SpO2=%d\n", raw_hr, raw_spo2);
        return -1; // Indicate invalid data
    }

    *hr = raw_hr;
    *spo2 = raw_spo2;

    return 0;
}

// Log health data to a file
void log_health_data(int spo2, int hr) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, SpO2: %d%%, HR: %d BPM\n", timestamp, spo2, hr);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, MAX30102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize MAX30102 sensor
    if (init_max30102() < 0) {
        fprintf(stderr, "MAX30102 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("health_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int spo2, hr;

    // Main loop
    while (!terminate) {
        if (read_max30102_data(&spo2, &hr) == 0) {
            log_health_data(spo2, hr);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

