#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_RELAY 17
#define GPIO_REED 27
#define DISTANCE_THRESHOLD 500 // mm
#define RELAY_DURATION 3000 // ms
#define NUM_CALIBRATION_SAMPLES 10
#define SAMPLE_DELAY_MS 50
#define CALIBRATION_DELAY_MS 500

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int i2c_read_word(int fd, uint8_t reg);
int i2c_write_word(int fd, uint8_t reg, uint16_t value);
int read_distance(int fd);
int read_reed_sensor(int gpio);
void control_relay(int gpio, int state);
void log_event(const char *event);
void signal_handler(int signal);
int initialize();
void cleanup();

// Function to read a 16-bit word from the ADS1115
int i2c_read_word(int fd, uint8_t reg) {
    uint8_t buf[2];
    buf[0] = reg;

    if (write(fd, buf, 1) != 1) {
        perror("Failed to write register address");
        return -1;
    }

    if (read(fd, buf, 2) != 2) {
        perror("Failed to read data");
        return -1;
    }

    return (buf[0] << 8) | buf[1];
}

// Function to write a 16-bit word to the ADS1115
int i2c_write_word(int fd, uint8_t reg, uint16_t value) {
    uint8_t buf[3];
    buf[0] = reg;
    buf[1] = (value >> 8) & 0xFF;
    buf[2] = value & 0xFF;

    if (write(fd, buf, 3) != 3) {
        perror("Failed to write data");
        return -1;
    }

    return 0;
}

// Function to read the distance from the GP2Y0A21YK0F Sharp IR sensor
int read_distance(int fd) {
    // Configure the ADS1115 for single-ended A0, 4.096V range, 128 SPS, and start a conversion
    uint16_t config = 0x4093; // Single-ended A0, 4.096V range, 128 SPS, Start single conversion
    if (i2c_write_word(fd, CONFIG_REG, config) != 0) {
        log_event("Error writing to ADS1115 configuration register");
        return -1;
    }

    // Wait for the conversion to complete (at least 8ms for 128 SPS)
    gpioDelay(10); // 10ms delay

    // Read the conversion result
    int16_t raw_value = i2c_read_word(fd, CONVERSION_REG);
    if (raw_value < 0) {
        log_event("Error reading from ADS1115 conversion register");
        return -1;
    }

    // Convert the raw value to millimeters (assuming a linear relationship)
    // This is a placeholder; the actual conversion depends on the sensor's datasheet
    // and the ADS1115's gain setting.
    // Example: raw_value * 0.0625 = distance in mm
    int distance = (int)(raw_value * 0.0625); // Example conversion

    return distance;
}

// Function to read the state of the reed sensor
int read_reed_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to control the relay (active-high)
void control_relay(int gpio, int state) {
    gpioWrite(gpio, state);
}

// Function to log events to a file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure the log is written immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Failed to open I2C bus");
        gpioTerminate();
        return -1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, ADS1115_ADDR) < 0) {
        perror("Failed to set I2C slave address");
        close(i2c_fd);
        gpioTerminate();
        return -1;
    }

    // Open log file
    log_file = fopen("/var/log/door_events.log", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        close(i2c_fd);
        gpioTerminate();
        return -1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is initially off

    // Set GPIO27 as input with pull-up resistor
    gpioSetMode(GPIO_REED, PI_INPUT);
    gpioSetPullUpDown(GPIO_REED, PI_PUD_UP);

    return 0;
}

// Cleanup function
void cleanup() {
    // Deactivate relay
    control_relay(GPIO_RELAY, 0);

    // Close I2C bus
    close(i2c_fd);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        fprintf(stderr, "Initialization failed, exiting\n");
        return 1;
    }

    // Calibration phase
    printf("Starting calibration phase...\n");
    int baseline_sum = 0;
    for (int i = 0; i < NUM_CALIBRATION_SAMPLES; i++) {
        int distance = read_distance(i2c_fd);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance during calibration, skipping sample %d\n", i + 1);
            continue; // Skip to the next sample
        }
        baseline_sum += distance;
        gpioDelay(SAMPLE_DELAY_MS * 1000); // Delay in microseconds
    }
    int baseline = baseline_sum / NUM_CALIBRATION_SAMPLES;
    printf("Calibration complete. Baseline: %d mm\n", baseline);

    // Main loop
    while (program_running) {
        // Read distance
        int distance = read_distance(i2c_fd);
        if (distance < 0) {
            fprintf(stderr, "Error reading distance, retrying...\n");
            gpioDelay(100 * 1000); // Wait before retrying
            continue;
        }

        // Check if distance is below threshold
        if (distance < DISTANCE_THRESHOLD) {
            printf("Distance below threshold (%d mm). Activating relay.\n", distance);
