#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for chip select lines
#define CS0_PIN 8
#define CS1_PIN 7
#define CS2_PIN 25

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define SPI mode
#define SPI_MODE 0

// Define CSV file name
#define CSV_FILE "soil_moisture_log.csv"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_mcp3008(int channel);
int log_data(int sensor1, int sensor2, int sensor3);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int sensor1;
    int sensor2;
    int sensor3;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(CS0_PIN, PI_OUTPUT);
    gpioSetMode(CS1_PIN, PI_OUTPUT);
    gpioSetMode(CS2_PIN, PI_OUTPUT);

    gpioWrite(CS0_PIN, 1); // Deselect chip 0 initially
    gpioWrite(CS1_PIN, 1); // Deselect chip 1 initially
    gpioWrite(CS2_PIN, 1); // Deselect chip 2 initially

    return 0;
}

// Function to initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }

    // Request manual chip select control
    gpioCfgClock(5, 1, 0); // 5us sample rate, 1us clock width
    gpioSetMode(CS0_PIN, PI_OUTPUT);
    gpioSetMode(CS1_PIN, PI_OUTPUT);
    gpioSetMode(CS2_PIN, PI_OUTPUT);

    gpioWrite(CS0_PIN, 1); // Deselect chip 0 initially
    gpioWrite(CS1_PIN, 1); // Deselect chip 1 initially
    gpioWrite(CS2_PIN, 1); // Deselect chip 2 initially

    return 0;
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    gpioWrite(CS0_PIN, 0); // Select chip 0
    gpioWrite(CS1_PIN, 0); // Select chip 1
    gpioWrite(CS2_PIN, 0); // Select chip 2

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);

    gpioWrite(CS0_PIN, 1); // Deselect chip 0
    gpioWrite(CS1_PIN, 1); // Deselect chip 1
    gpioWrite(CS2_PIN, 1); // Deselect chip 2

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to log data to CSV file
int log_data(int sensor1, int sensor2, int sensor3) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    // Check if the file is new and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,sensor3\n");
    }

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for appending
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", CSV_FILE);
        cleanup();
        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read sensor data
        int sensor1 = read_mcp3008(0);
        int sensor2 = read_mcp3008(1);
        int sensor3 = read_mcp3008(2);

        // Log data
        if (sensor1 != -1 && sensor2 != -1 && sensor3 != -1) {
            log_data(sensor1, sensor2, sensor3);
        } else {
            fprintf(stderr, "Failed to read sensor data. Skipping logging.\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    printf("Soil moisture monitoring stopped.\n");
    return 0;
}

