#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    int threshold;
    int pump_duration;
    int sleep_interval;
    int spi_channel;
    int spi_speed;
    int spi_mode;
    int pump_gpio;
    char log_file[64];
} Config;

// Global variables
int spi_handle;
Config config;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_to_voltage(int adc_value);
int is_moisture_low(float voltage, int threshold);
void activate_pump(int gpio, int duration_seconds);
void deactivate_pump(int gpio);
void log_message(const char *message);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[], Config *config);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        log_message("Error: Invalid MCP3008 channel.");
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int retries = 3;
    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) == 0) {
            // Extract ADC value (10 bits)
            int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
            return adc_value;
        } else {
            log_message("Error: SPI communication failed. Retrying...");
            gpioDelay(10000); // 10ms delay
            retries--;
        }
    }

    log_message("Error: SPI communication failed after multiple retries.");
    return -1;
}

// Function to convert ADC value to voltage
float convert_to_voltage(int adc_value) {
    return (adc_value / 1023.0) * 3.3;
}

// Function to check if moisture level is low
int is_moisture_low(float voltage, int threshold) {
    return (voltage * 100.0) < threshold;
}

// Function to activate the water pump
void activate_pump(int gpio, int duration_seconds) {
    gpioWrite(gpio, 1); // Set GPIO HIGH
    log_message("Pump activated.");
    gpioDelay(duration_seconds * 1000000); // Delay for specified duration (microseconds)
    gpioWrite(gpio, 0); // Set GPIO LOW
    log_message("Pump deactivated.");
}

// Function to deactivate the water pump
void deactivate_pump(int gpio) {
    gpioWrite(gpio, 0); // Set GPIO LOW
    log_message("Pump deactivated.");
}

// Function to log messages with timestamps
void log_message(const char *message) {
    FILE *fp = fopen(config.log_file, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_message("Signal received, shutting down...");
    terminate = 1;
}

// Function to parse command-line arguments
int parse_arguments(int argc, char *argv[], Config *config) {
    config->threshold = 30;
    config->pump_duration = 10;
    config->sleep_interval = 60;
    config->spi_channel = 0;
    config->spi_speed = 1000000; // 1 MHz
    config->spi_mode = 0;
    config->pump_gpio = 18;
    strcpy(config->log_file, "irrigation.log");

    int opt;
    while ((opt = getopt(argc, argv, "t:d:s:c:s:g:l:")) != -1) {
        switch (opt) {
            case 't':
                config->threshold = atoi(optarg);
                break;
            case 'd':
                config->pump_duration = atoi(optarg);
                break;
            case 's':
                config->sleep_interval = atoi(optarg);
                break;
            case 'c':
                config->spi_channel = atoi(optarg);
                break;
            case 's':
                config->spi_speed = atoi(optarg);
                break;
            case 'g':
                config->pump_gpio = atoi(optarg);
                break;
            case 'l':
                strcpy(config->log_file, optarg);
                break;
            default:
