    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Sound event detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value >= 0) {
            if (detect_peak(adc_value, THRESHOLD)) {
                if (log_event(adc_value) != 0) {
