void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Cleaning up and exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, PCF8591_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (1) {
        // Dummy read to discard the previous conversion
        char buf[1];
        buf[0] = 0x40; // Control byte: AIN0, single-ended mode
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }
        gpioDelay(10); // Small delay after writing

        // Read the ADC value
        buf[0] = 0x40; // Control byte: AIN0, single-ended mode
        if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
            fprintf(stderr, "Failed to write to I2C device\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        if (i2cReadDevice(i2c_handle, buf, 1) != 1) {
            fprintf(stderr, "Failed to read from I2C device\n");
            i2cClose(i2c_handle);
            gpioTerminate();
            return 1;
        }

        // Print the ADC value
        printf("ADC Value: %d\n", buf[0]);

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // The following lines will never be reached because of the infinite loop.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

