// Configuration
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define GPIO_SHUTDOWN 27
#define THRESHOLD_GAUSS 500.0
#define BUFFER_SIZE 10
#define SAMPLE_RATE_HZ 1
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE_HZ) // microseconds
#define MQTT_BROKER_ADDRESS "localhost" // Replace with your MQTT broker address
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_sensor_node"
#define MQTT_TOPIC "sensor_data"

// Global variables
int i2c_handle;
bool running = true;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_i2c();
int read_ads1115(int16_t *raw_value);
float convert_to_gauss(int16_t raw_value);
void add_to_buffer(CircularBuffer *buffer, float value);
float calculate_average(CircularBuffer *buffer);
void control_motor(float average_gauss);
void log_message(int priority, const char *message);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        log_message(LOG_ERR, "Failed to open I2C device");
        return -1;
    }

    // Configure ADS1115 for single-ended AIN0, 4.096V range, 128 SPS, single-shot mode
    uint16_t config = 0x4083; // Single-shot mode, AIN0, +/- 4.096V, 128 SPS
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config >> 8) & 0xFF;
    buf[2] = config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        log_message(LOG_ERR, "Failed to write to I2C device");
        i2cClose(i2c_handle);
        return -1;
    }

