        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int moisture_level = read_mcp3008(0);

        if (moisture_level >= 0) {
            printf("Moisture level: %d\n", moisture_level);

            if (moisture_level < MOISTURE_THRESHOLD) {
