// Define GPIO pins
#define MOTOR_PIN 18
#define SPI_CE 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
void set_motor_speed(int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid ADC channel %d\n", channel);
        return -1;
    }

    // Construct SPI message
    uint8_t tx_buffer[3];
    uint8_t rx_buffer[3];

    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);

    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed with code %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to set motor speed using PWM
void set_motor_speed(int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 1023) {
        fprintf(stderr, "Error: Invalid duty cycle %d\n", duty_cycle);
        return;
    }

    gpioPWM(MOTOR_PIN, duty_cycle);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Configure GPIO18 as PWM output
    gpioSetMode(MOTOR_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(MOTOR_PIN, 1000); // 1 kHz
    gpioSetPWMrange(MOTOR_PIN, 1023);    // 0-1023 range

    // Open SPI channel
    spi_handle = spiOpen(SPI_CE, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed with code %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Motor control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Set motor speed
        set_motor_speed(adc_value);

        // Print ADC value and PWM duty cycle
        printf("ADC Value: %d, PWM Duty Cycle: %d\n", adc_value, adc_value);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Stop PWM output
    gpioPWM(MOTOR_PIN, 0);

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

