#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define ADS1115_ADDR 0x48
#define CONFIG_REG 0x01
#define CONVERSION_REG 0x00
#define LED_GPIO 17
#define DEFAULT_THRESHOLD 100.0
#define BLINK_DURATION_MS 50
#define BLINK_COUNT 1

// Global variables
int i2c_handle;
double threshold = DEFAULT_THRESHOLD;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_ads1115();
int read_ads1115(int16_t *raw_value);
double convert_to_gauss(int16_t raw_value);
void print_field_strength(double gauss);
void signal_handler(int signal);
void blink_led(int gpio, int duration_ms, int count);

// Structure for configuration (optional, but good practice)
typedef struct {
    int i2c_bus;
    int ads1115_address;
    int config_register;
    int conversion_register;
    int led_gpio;
    double threshold;
} Config;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize I2C
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, ADS1115_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to configure the ADS1115
int configure_ads1115() {
    // Configure for single-ended AIN0, +/- 4.096V, single-shot mode, 128 SPS
    uint16_t config_value = 0x4003; // Single-shot mode, AIN0, +/- 4.096V, 128 SPS

    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config_value >> 8) & 0xFF;
    buf[2] = config_value & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read data from the ADS1115
int read_ads1115(int16_t *raw_value) {
    char buf[1];
    buf[0] = CONVERSION_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to conversion register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from conversion register: %d\n", result);
        return -1;
    }

    *raw_value = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Function to convert raw ADC value to Gauss
double convert_to_gauss(int16_t raw_value) {
    // Assuming +/- 4.096V range, 16-bit ADC
    double voltage = (double)raw_value * 4.096 / 32768.0;
    return voltage / 0.00000000000000006103515625; // 4.096V / 2^15
}

// Function to print the field strength
void print_field_strength(double gauss) {
    printf("Field Strength: %.2f Gauss\n", gauss);
}

// Function to blink the LED
void blink_led(int gpio, int duration_ms, int count) {
    for (int i = 0; i < count; i++) {
        gpioWrite(gpio, 1); // Turn LED on
        gpioDelay(duration_ms * 1000); // Delay for on time
        gpioWrite(gpio, 0); // Turn LED off
        gpioDelay(duration_ms * 1000); // Delay for off time
    }
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        threshold = atof(argv[1]);
        printf("Using threshold: %.2f Gauss\n", threshold);
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure ADS1115
    if (configure_ads1115() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t raw_value;
    double gauss;

    // Main loop
    while (!terminate) {
        // Read ADC value
        if (read_ads1115(&raw_value) == 0) {
            // Convert to Gauss
            gauss = convert_to_gauss(raw_value);

            // Print field strength
            print_field_strength(gauss);

            // Check threshold and blink LED
            if (gauss > threshold) {
                blink_led(LED_GPIO, BLINK_DURATION_MS, BLINK_COUNT);
            }
        } else {
            fprintf(stderr, "Failed to read ADC value. Retrying...\n");
        }

        // Delay for 100ms
        gpioDelay(100 * 1000); // 100ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

