#define MQTT_TOPIC_MOISTURE "soil_moisture"
#define MQTT_TOPIC_PUMP_CONTROL "pump_control"
#define PUMP_ON_COMMAND "pump_on"
#define PUMP_OFF_COMMAND "pump_off"
#define PUMP_ON_DELAY 5 // seconds
#define PUMP_OFF_DELAY 10 // seconds

// Global variables
int spi_handle;
struct mosquitto *mosq = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
void control_pump(int pump_state);
void publish_moisture_data(float moisture_percentage);
void subscribe_pump_control(struct mosquitto *mosq);
void on_connect(struct mosquitto *mosq, void *userdata, int result);
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc);
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        syslog(LOG_ERR, "Invalid MCP3008 channel: %d", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        syslog(LOG_ERR, "SPI transfer failed: %d", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    // Assuming ADC value ranges from 0 to 1023
    // Adjust the calibration values based on your sensor's characteristics
    float moisture_percentage = 100.0 - ((float)adc_value / 1023.0) * 100.0;

    // Clamp the moisture percentage to the range 0-100
    if (moisture_percentage < 0.0) {
        moisture_percentage = 0.0;
    } else if (moisture_percentage > 100.0) {
        moisture_percentage = 100.0;
    }

    return moisture_percentage;
}

// Function to control the pump
void control_pump(int pump_state) {
    gpioWrite(PUMP_GPIO, pump_state);
    syslog(LOG_INFO, "Pump set to %s", pump_state ? "ON" : "OFF");
}

// Function to publish moisture data to MQTT
void publish_moisture_data(float moisture_percentage) {
    char payload[50];
    snprintf(payload, sizeof(payload), "{\"moisture\": %.2f}", moisture_percentage);

    int rc = mosquitto_publish(mosq, NULL, MQTT_TOPIC_MOISTURE, strlen(payload), payload, 0, false);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to publish moisture data: %s", mosquitto_strerror(rc));
    }
