        subscribe_pump_control(mosq);
    } else {
        syslog(LOG_ERR, "MQTT connection failed: %s", mosquitto_strerror(result));
    }
}

// Callback function for MQTT disconnection
void on_disconnect(struct mosquitto *mosq, void *userdata, int rc) {
    syslog(LOG_INFO, "MQTT disconnected with code %d", rc);
}

// Callback function for MQTT message
void on_message(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > 0) {
        syslog(LOG_INFO, "Received message on topic %s: %s", message->topic, (char *)message->payload);

        if (strcmp(message->topic, MQTT_TOPIC_PUMP_CONTROL) == 0) {
