#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MOTOR1_GPIO 17
#define MOTOR2_GPIO 27
#define NOISE_THRESHOLD 500
#define LOG_FILE "vibration_log.txt"
#define SAMPLE_INTERVAL_MS 10

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int calculate_noise_level(int *samples, int num_samples);
void control_motor(int gpio, int duty_cycle);
void log_vibration_event(int motor_number);
void signal_handler(int signal);
int initialize();
void cleanup();

// Structure for configuration (optional, but good practice)
typedef struct {
    int spi_channel;
    int spi_speed;
    int motor1_gpio;
    int motor2_gpio;
    int noise_threshold;
    char *log_file;
    int sample_interval_ms;
} Config;

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 3) != 0) {
        fprintf(stderr, "Error: SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Function to calculate noise level from samples
int calculate_noise_level(int *samples, int num_samples) {
    int sum = 0;
    for (int i = 0; i < num_samples; i++) {
        sum += samples[i];
    }
    return sum / num_samples;
}

// Function to control a motor using PWM
void control_motor(int gpio, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Error: Invalid duty cycle: %d\n", duty_cycle);
        return;
    }

    gpioPWM(gpio, duty_cycle);
}

// Function to log vibration event
void log_vibration_event(int motor_number) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Vibration detected on Motor %d\n", timestamp, motor_number);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialization function
int initialize() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Open SPI device
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed\n");
        gpioTerminate();
        return -1;
    }

    // Set GPIO modes for motors
    gpioSetMode(MOTOR1_GPIO, PI_OUTPUT);
    gpioSetMode(MOTOR2_GPIO, PI_OUTPUT);

    // Set PWM range for motors (adjust as needed)
    gpioSetPWMrange(MOTOR1_GPIO, 255);
    gpioSetPWMrange(MOTOR2_GPIO, 255);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    // Stop motors
    control_motor(MOTOR1_GPIO, 0);
    control_motor(MOTOR2_GPIO, 0);

    // Close SPI device
    spiClose(spi_handle);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize
    if (initialize() != 0) {
        return 1;
    }

    printf("Vibration monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int samples[10]; // 10 samples for averaging
        int noise_level;
        int motor1_duty_cycle = 0;
        int motor2_duty_cycle = 0;

        // Read samples from MCP3008
        for (int i = 0; i < 10; i++) {
            int adc_value = read_mcp3008(0); // Read from channel 0
            if (adc_value < 0) {
                fprintf(stderr, "Error: Failed to read ADC value, skipping iteration.\n");
                samples[i] = 0; // Assign a default value to avoid further issues
            } else {
                samples[i] = adc_value;
            }
            gpioDelay(1); // Small delay between samples
        }

        // Calculate noise level
        noise_level = calculate_noise_level(samples, 10);

        // Control motors based on noise level
        if (noise_level > NOISE_THRESHOLD) {
            // Vibration detected, increase duty cycle
            motor1_duty_cycle = 128; // 50%
            motor2_duty_cycle = 128; // 50%
            control_motor(MOTOR1_GPIO, motor1_duty_cycle);
            control_motor(MOTOR2_GPIO, motor2_duty_cycle);
            log_vibration_event(1); // Log motor 1
            log_vibration_event(2); // Log motor 2
        } else {
            // No vibration detected, turn off motors
            control_motor(MOTOR1_GPIO, 0);
            control_motor(MOTOR2_GPIO, 0);
        }

        gpioDelay(SAMPLE_INTERVAL_MS); // Delay for 10ms
    }

    // Cleanup and exit
    cleanup();
    printf("Vibration monitoring stopped.\n");
    return 0;
}

