#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define FAN_GPIO 18
#define CO2_THRESHOLD 700
#define LOG_FILE "air_quality.log"
#define RETRY_COUNT 3

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_mcp3008(int channel);
float adc_to_co2(int adc_value);
void control_fan(float co2_ppm);
void log_data(float co2_ppm, int fan_state);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (channel %d): %d\n", channel, result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to CO2 concentration (ppm)
float adc_to_co2(int adc_value) {
    // Linear approximation: CO2 = a * ADC_value + b
    // Assuming a = 0.5 and b = 0
    float co2_ppm = adc_value * 0.5; // Example linear conversion
    return co2_ppm;
}

// Function to control the ventilation fan
void control_fan(float co2_ppm) {
    if (co2_ppm > CO2_THRESHOLD) {
        gpioWrite(FAN_GPIO, 1); // Turn fan ON
    } else {
        gpioWrite(FAN_GPIO, 0); // Turn fan OFF
    }
}

// Function to log data to file
void log_data(float co2_ppm, int fan_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, co2_ppm, fan_state);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Air quality monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int adc_value;
        float co2_ppm;
        int fan_state;

        // Read ADC value with retry mechanism
        int retry = 0;
        while (retry < RETRY_COUNT) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Error: Retrying ADC read (attempt %d/%d)\n", retry + 1, RETRY_COUNT);
                retry++;
                gpioDelay(100); // Wait before retrying
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value after multiple retries\n");
            co2_ppm = -1.0; // Indicate error
        } else {
            // Convert ADC value to CO2 concentration
            co2_ppm = adc_to_co2(adc_value);
        }

        // Control fan
        control_fan(co2_ppm);
        fan_state = gpioRead(FAN_GPIO);

        // Log data
        log_data(co2_ppm, fan_state);

        printf("CO2: %.2f ppm, Fan: %s\n", co2_ppm, fan_state ? "ON" : "OFF");

        // Wait 5 seconds
        gpioDelay(5000); // pigpioDelay takes milliseconds
    }

