#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define VALVE_GPIO 17
#define PWM_FREQUENCY 100
#define PWM_RANGE 100
#define LOG_FILE "irrigation.log"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_average(int *samples, int num_samples);
int set_valve_position(int position);
int log_data(int raw_values[3], float average, int position);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed (%d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to calculate the average of an array of integers
float calculate_average(int *samples, int num_samples) {
    if (num_samples <= 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += samples[i];
    }
    return sum / num_samples;
}

// Function to set the valve position using PWM
int set_valve_position(int position) {
    if (position < 0 || position > PWM_RANGE) {
        fprintf(stderr, "Error: Invalid valve position %d (must be between 0 and %d)\n", position, PWM_RANGE);
        return -1;
    }

    gpioPWM(VALVE_GPIO, position);
    return 0;
}

// Function to log data to a file
int log_data(int raw_values[3], float average, int position) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Raw: %d, %d, %d, Average: %.2f, Position: %d\n",
            timestamp, raw_values[0], raw_values[1], raw_values[2], average, position);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set valve GPIO as output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(VALVE_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(VALVE_GPIO, PWM_RANGE);

    // Open SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 1MHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Irrigation system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int raw_values[3];
        int failed_reads = 0;

        // Read three samples
        for (int i = 0; i < 3; i++) {
            int value = read_mcp3008(0); // Read from channel 0
            if (value < 0) {
                fprintf(stderr, "Error: Failed to read sample %d\n", i + 1);
                failed_reads++;
                gpioDelay(100000); // Wait 100ms before retrying
                continue;
            }
            raw_values[i] = value;
            gpioDelay(10000); // Small delay between readings
        }

        // Calculate average
        float average = calculate_average(raw_values, 3);

        // Set valve position
        int position = (int)(average / 1023.0 * PWM_RANGE); // Map ADC value to PWM range
        if (set_valve_position(position) != 0) {
            fprintf(stderr, "Error: Failed to set valve position\n");
        }

        // Log data
        log_data(raw_values, average, position);

        // Wait for the next sample interval
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_valve_position(0); // Set valve to 0 before exiting
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

