        return 1;
    }

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int adc_value = -1;
        int retry = 0;

        while (retry < RETRY_COUNT) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) {
                break; // Success
            } else {
                fprintf(stderr, "Retry %d failed, delaying for %d ms\n", retry + 1, RETRY_DELAY_MS);
                gpioDelay(RETRY_DELAY_MS * 1000); // pigpioDelay takes microseconds
                retry++;
            }
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries\n", RETRY_COUNT);
            // Log error to file
            FILE *fp = fopen(LOG_FILE, "a");
            if (fp != NULL) {
                time_t t = time(NULL);
                struct tm tm = *localtime(&t);
                char timestamp[64];
                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
                fprintf(fp, "%s, ERROR: Failed to read ADC value after %d retries\n", timestamp, RETRY_COUNT);
                fclose(fp);
            }
            continue; // Skip to the next iteration
        }

        float moisture_percentage = convert_to_moisture_percentage(adc_value);
        if (moisture_percentage >= 0) {
            if (log_data(moisture_percentage) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
            printf("Moisture: %.2f%%\n", moisture_percentage);
        } else {
            fprintf(stderr, "Failed to convert ADC value to moisture percentage\n");
        }

        gpioDelay(5000000); // 5 seconds
    }

    cleanup();
    return 0;
}

