#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    int trig_pin;
    int echo_pin;
    int ldr_channel;
    int pwm_pin;
    int spi_bus;
    int spi_device;
    int spi_speed;
    float distance_min;
    float distance_max;
    float volume_min;
    float volume_max;
    char config_file[64];
} Config;

// Global variables
Config config;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_config(const char *filename, Config *config);
int initialize_gpio(Config *config);
int initialize_spi(Config *config);
int read_ldr(Config *config);
float map_distance_to_frequency(float distance);
float map_volume_to_duty_cycle(float volume);
int generate_pwm(Config *config, float frequency, float duty_cycle);
int capture_echo(Config *config);
float calculate_distance(Config *config);
void signal_handler(int signal);
void cleanup(Config *config);

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Skip comments and empty lines
        if (line[0] == '#' || line[0] == '\0') continue;

        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "trig_pin") == 0) {
                config->trig_pin = atoi(value);
            } else if (strcmp(key, "echo_pin") == 0) {
                config->echo_pin = atoi(value);
            } else if (strcmp(key, "ldr_channel") == 0) {
                config->ldr_channel = atoi(value);
            } else if (strcmp(key, "pwm_pin") == 0) {
                config->pwm_pin = atoi(value);
            } else if (strcmp(key, "spi_bus") == 0) {
                config->spi_bus = atoi(value);
            } else if (strcmp(key, "spi_device") == 0) {
                config->spi_device = atoi(value);
            } else if (strcmp(key, "spi_speed") == 0) {
                config->spi_speed = atoi(value);
            } else if (strcmp(key, "distance_min") == 0) {
                config->distance_min = atof(value);
            } else if (strcmp(key, "distance_max") == 0) {
                config->distance_max = atof(value);
            } else if (strcmp(key, "volume_min") == 0) {
                config->volume_min = atof(value);
            } else if (strcmp(key, "volume_max") == 0) {
                config->volume_max = atof(value);
            } else if (strcmp(key, "config_file") == 0) {
                strncpy(config->config_file, value, sizeof(config->config_file) - 1);
                config->config_file[sizeof(config->config_file) - 1] = '\0';
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize GPIO pins
int initialize_gpio(Config *config) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config->trig_pin, PI_OUTPUT);
    gpioSetMode(config->echo_pin, PI_INPUT);
    gpioSetMode(config->pwm_pin, PI_OUTPUT);

    gpioWrite(config->trig_pin, 0);
    gpioPWM(config->pwm_pin, 0); // Ensure PWM is off initially

    return 0;
}

// Function to initialize SPI communication
int initialize_spi(Config *config) {
    int fd = open("/dev/spidev0.0", O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    uint8_t mode = 0; // SPI_MODE_0
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Set SPI bits per word
    uint8_t bits = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting SPI bits per word");
        close(fd);
        return -1;
    }

    // Set SPI max speed hz
    uint32_t speed = config->spi_speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI max speed hz");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read LDR value from MCP3008
int read_ldr(Config *config) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | config->ldr_channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = config->spi_speed,
        .bits_per_word = 8,
    };

    if (ioctl(config->spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to map distance to frequency
float map_distance_to_frequency(float distance) {
    // Ensure distance is within the defined range
    if (distance < config.distance_min) {
        distance = config.distance_min;
    } else if (distance > config.distance_max) {
        distance = config.distance_max;
    }

    // Map distance to frequency (Hz)
    float frequency = 2000.0 + (distance - config.distance_min) * (2000.0 - 200.0) / (config.distance_max - config.distance_min);

    return frequency;
}

// Function to map volume to duty cycle (0-100%)
float map_volume_to_duty_cycle(float volume) {
    // Ensure volume is within the defined range
    if (volume < config.volume_min) {
        volume = config.volume_min;
    } else if (volume > config.volume_max) {
        volume = config.volume_max;
    }

    // Map volume to duty cycle (0-100%)
    float duty_cycle = (volume - config.volume_min) * (100.0 - 0.0) / (config.volume_max - config.volume_min) + 0.0;

    return duty_cycle;
}

// Function to generate PWM signal
int generate_pwm(Config *config, float frequency, float duty_cycle) {
    // Calculate PWM period (in microseconds)
    int period_us = 1000000 / frequency; // Period in microseconds

    // Calculate duty cycle (in microseconds)
    int duty_cycle_us = (int)(period_us * duty_cycle / 100.0);

    // Set PWM period
    gpioSetPWMfrequency(config->pwm_pin, frequency);
    gpioSetPWMrange(config->pwm_pin, period_us);

    // Set PWM duty cycle
    gpioPWM(config->pwm_pin, duty_cycle_us);

    return 0;
}

// Function to capture echo pulse width
int capture_echo(Config *config) {
    long long start_time = 0, end_time = 0;

    // Wait for echo to go high (with timeout)
    int timeout = 100000; // 100ms timeout
    while (gpioRead(config->echo_pin) == 0 && timeout > 0) {
        timeout--;
        usleep(1); // Small delay to avoid busy-waiting
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for echo high\n");
        return -1;
    }

    start_time = gpioTick();

    // Wait for echo to go low (with timeout)
    timeout = 100000; // 100ms timeout
    while (gpioRead(config->echo_pin) == 1 && timeout > 0) {
        timeout--;
        usleep(1); // Small delay to avoid busy-waiting
    }

    if (timeout == 0) {
        fprintf(stderr, "Timeout waiting for echo low\n");
        return -1;
    }

    end_time = gpioTick();

    return (int)(end_time - start_time);
}

// Function to calculate distance in centimeters
float calculate_distance(Config *config) {
    int pulse_width = capture_echo(config);
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }

    // Speed of sound in air (cm/us)
    float speed_of_sound = 34300.0; // cm/s

    // Calculate distance in centimeters
    float distance = (pulse_width * speed_of_sound) / 2000000.0; // Divide by 2 for one-way distance

    return distance;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(Config *config) {
    gpioPWM(config->pwm_pin, 0); // Stop PWM
    gpioTerminate(); // Terminate pigpio
    close(config->spi_fd); // Close SPI device
}

int main() {
    // Read configuration from file
    if (read_config("theremin_config.txt", &config) != 0) {
        fprintf(stderr, "Failed to read configuration. Using default values.\n");
    }

    // Initialize GPIO
    if (initialize_gpio(&config) != 0) {
        return 1;
    }

    // Initialize SPI
    config.spi_fd = initialize_spi(&config);
    if (config.spi_fd < 0) {
        cleanup(&config);
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read LDR value
        int ldr_value = read_ldr(&config);
        if (ldr_value < 0) {
            fprintf(stderr, "Error reading LDR value. Using last valid value.\n");
            // Use last valid volume or distance if LDR read fails
            float last_valid_volume = 50.0; // Default volume
            float last_valid_distance = 100.0; // Default distance
            if (config.volume_min != config.volume_max) {
                last_valid_volume = config.volume_min + (config.volume_max - config.volume_min) * 0.5; // Average the two extremes
            }
            if (config.distance_min != config.distance_max) {
                last_valid_distance = config.distance_min + (config.distance_max - config.distance_min) * 0.5; // Average the two extremes
            }
            ldr_value = (int)(last_valid_volume * 1023.0 / 100.0); // Map to ADC range
        }

        // Calculate distance
        float distance = calculate_distance(&config);
        if (distance < 0) {
            fprintf(stderr, "Error calculating distance. Using last valid value.\n");
            distance = last_valid_distance; // Use last valid distance
        }

        // Map distance to frequency and volume
        float frequency = map_distance_to_frequency(distance);
        float volume = map_volume_to_duty_cycle((float)ldr_value / 1023.0 * 100.0);

        // Generate PWM signal
        generate_pwm(&config, frequency, volume);

        // Print distance and volume (for debugging)
        printf("Distance: %.2f cm, Frequency: %.2f Hz, Volume: %.2f%%\n", distance, frequency, volume);

        // Delay
        usleep(10000); // 10ms
    }

    // Cleanup and exit
    cleanup(&config);
    return 0;
}

