            continue; // Skip to the next iteration
        }

        // Classify alcohol level
        char *alcohol_level = classify_alcohol_level(voltage);

        // Get current timestamp
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30]; // YYYY-MM-DDTHH:MM:SSZ\0

        time(&rawtime);
        timeinfo = gmtime(&rawtime); // Use gmtime for UTC

