            log_data(moisture_value, pump_state);
        } else {
            fprintf(stderr, "Error: Failed to read moisture value\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_pump(0); // Turn off pump
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

