#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MOTOR1_ENABLE 18
#define MOTOR1_DIRECTION 23
#define MOTOR2_ENABLE 24
#define MOTOR2_DIRECTION 25
#define SPI_CE 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SPI_MODE 0

// Define PWM parameters
#define PWM_FREQUENCY 1000 // 1 kHz
#define PWM_RANGE 1000

// Define motor speed mapping parameters
#define MIN_POT_VALUE 0
#define MAX_POT_VALUE 1023
#define MIN_SPEED 0
#define MAX_SPEED 100

// Define acceleration and deceleration parameters
#define ACCELERATION_TIME 2 // seconds
#define DECELERATION_TIME 2 // seconds
#define ACCELERATION_DELAY 0.01 // seconds
#define DECELERATION_DELAY 0.01 // seconds

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
int map_pot_value_to_speed(int pot_value);
void set_motor_speed(int motor_enable, int motor_direction, int speed);
void accelerate_motor(int motor_enable, int motor_direction, int speed);
void hold_constant_speed(int motor_enable, int motor_direction, int speed);
void decelerate_motor(int motor_enable, int motor_direction, int speed);
void reverse_motor(int motor1_enable, int motor1_direction, int motor2_enable, int motor2_direction);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(SPI_CE, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(SPI_CE, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "Error: SPI transfer failed (result = %d)\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to map potentiometer value to motor speed
int map_pot_value_to_speed(int pot_value) {
    if (pot_value < MIN_POT_VALUE) {
        pot_value = MIN_POT_VALUE;
    } else if (pot_value > MAX_POT_VALUE) {
        pot_value = MAX_POT_VALUE;
    }

    int speed = MIN_SPEED + (int)(((float)(pot_value - MIN_POT_VALUE) / (MAX_POT_VALUE - MIN_POT_VALUE)) * (MAX_SPEED - MIN_SPEED));
    return speed;
}

// Function to set motor speed using PWM
void set_motor_speed(int motor_enable, int motor_direction, int speed) {
    if (speed < 0) speed = 0;
    if (speed > 100) speed = 100;

    gpioPWM(motor_enable, speed);
    gpioWrite(motor_direction, (speed > 50) ? 1 : 0); // Set direction based on speed
}

// Function to accelerate motor
void accelerate_motor(int motor_enable, int motor_direction, int speed) {
    for (int i = 0; i <= speed; i += 1) {
        set_motor_speed(motor_enable, motor_direction, i);
        gpioDelay(ACCELERATION_DELAY * 1000); // Delay in milliseconds
    }
}

// Function to hold constant speed
void hold_constant_speed(int motor_enable, int motor_direction, int speed) {
    set_motor_speed(motor_enable, motor_direction, speed);
    gpioDelay(ACCELERATION_TIME * 1000); // Delay in milliseconds
}

// Function to decelerate motor
void decelerate_motor(int motor_enable, int motor_direction, int speed) {
    for (int i = speed; i >= 0; i -= 1) {
        set_motor_speed(motor_enable, motor_direction, i);
        gpioDelay(DECELERATION_DELAY * 1000); // Delay in milliseconds
    }
}

// Function to reverse motor
void reverse_motor(int motor1_enable, int motor1_direction, int motor2_enable, int motor2_direction) {
    set_motor_speed(motor1_enable, motor1_direction, 0);
    set_motor_speed(motor2_enable, motor2_direction, 0);
    gpioDelay(5000); // 5 seconds

    set_motor_speed(motor1_enable, motor1_direction, 50);
    set_motor_speed(motor2_enable, motor2_direction, 50);
    gpioDelay(1000); // 1 second

    set_motor_speed(motor1_enable, motor1_direction, 0);
    set_motor_speed(motor2_enable, motor2_direction, 0);
    gpioDelay(5000); // 5 seconds
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR1_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR1_DIRECTION, PI_OUTPUT);
    gpioSetMode(MOTOR2_ENABLE, PI_OUTPUT);
    gpioSetMode(MOTOR2_DIRECTION, PI_OUTPUT);
    gpioSetMode(SPI_CE, PI_OUTPUT);

    // Initialize SPI
    spi_handle = spiOpen(SPI_CE, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Set PWM frequency and range
    gpioSetPWMfrequency(MOTOR1_ENABLE, PWM_FREQUENCY);
    gpioSetPWMfrequency(MOTOR2_ENABLE, PWM_FREQUENCY);
    gpioSetPWMrange(MOTOR1_ENABLE, PWM_RANGE);
    gpioSetPWMrange(MOTOR2_ENABLE, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read potentiometer values
        int pot1_value = read_mcp3008(0);
        int pot2_value = read_mcp3008(1);

        if (pot1_value < 0 || pot2_value < 0) {
            fprintf(stderr, "Error: Failed to read potentiometer values\n");
            // Attempt to recover by setting speed to 0
            set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, 0);
            set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, 0);
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Map potentiometer values to motor speeds
        int speed1 = map_pot_value_to_speed(pot1_value);
        int speed2 = map_pot_value_to_speed(pot2_value);

        // Accelerate motors
        accelerate_motor(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1);
        accelerate_motor(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2);

        // Hold constant speed
        hold_constant_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1);
        hold_constant_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2);

        // Decelerate motors
        decelerate_motor(MOTOR1_ENABLE, MOTOR1_DIRECTION, speed1);
        decelerate_motor(MOTOR2_ENABLE, MOTOR2_DIRECTION, speed2);

        // Reverse motors
        reverse_motor(MOTOR1_ENABLE, MOTOR1_DIRECTION, MOTOR2_ENABLE, MOTOR2_DIRECTION);

        // Delay before next iteration
        gpioDelay(1000); // 1 second
    }

    // Clean up resources
    set_motor_speed(MOTOR1_ENABLE, MOTOR1_DIRECTION, 0);
    set_motor_speed(MOTOR2_ENABLE, MOTOR2_DIRECTION, 0);
    spiClose(spi_handle);
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully.\n");
    return 0;
}

