    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Calibrate noise level
    int baseline = calibrate_noise_level();
    if (baseline < 0) {
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    printf("Noise level baseline: %d\n", baseline);

    // Main loop
    while (!terminate) {
        // Read sound level
        int new_level = read_mcp3008(0);
        if (new_level < 0) {
            fprintf(stderr, "Error reading sound level\n");
            continue; // Skip to the next iteration
        }

        // Compare sound level to baseline
        int sound_detected = compare_sound_level(new_level, baseline);

        // Debounce and control LED
        if (sound_detected) {
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce time in microseconds
            if (compare_sound_level(read_mcp3008(0), baseline)) {
                control_led(1); // Turn LED on
            }
        } else {
            control_led(0); // Turn LED off
        }

        gpioDelay(1000); // Delay for 1ms
    }

    // Cleanup
    control_led(0); // Turn off LED
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

