static int spi_fd = -1;
static FILE *log_file = NULL;

// Structure to hold GPIO configuration
typedef struct {
    int pin;
    int direction;
} gpio_config_t;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_write(int pin, int value);
int spi_open(const char *device, int mode, int bits_per_word, int max_speed);
int spi_close(int fd);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int log_data(FILE *fp, struct timeval tv, int raw_adc_value);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, exiting gracefully.\n", sig);
        keep_running = 0;
    }
}

// GPIO export function
int gpio_export(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/export: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/export: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO unexport function
int gpio_unexport(int pin) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening /sys/class/gpio/unexport: %s\n", strerror(errno));
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        fprintf(stderr, "Error writing to /sys/class/gpio/unexport: %s\n", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// GPIO write function
int gpio_write(int pin, int value) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", path, strerror(errno));
        return -1;
    }
    if (value != 0 && value != 1) {
        fprintf(stderr, "Invalid GPIO value: %d\n", value);
        close(fd);
        return -1;
    }
    char val_str[2];
    snprintf(val_str, sizeof(val_str), "%d", value);
    if (write(fd, val_str, 1) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// SPI open function
int spi_open(const char *device, int mode, int bits_per_word, int max_speed) {
    int fd;

    fd = open(device, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening SPI device %s: %s\n", device, strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode_val = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_val) == -1) {
        fprintf(stderr, "Error setting SPI mode: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits_per_word_val = bits_per_word;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_per_word_val) == -1) {
        fprintf(stderr, "Error setting bits per word: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    // Configure max speed
    uint32_t max_speed_val = max_speed;
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &max_speed_val) == -1) {
        fprintf(stderr, "Error setting max speed: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// SPI close function
int spi_close(int fd) {
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing SPI device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = SPI_MAX_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        fprintf(stderr, "Error during SPI transfer: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Log data function
int log_data(FILE *fp, struct timeval tv, int raw_adc_value) {
    char timestamp_str[32];
    struct tm *tm_info;

    tm_info = localtime(&tv.tv_sec);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
    snprintf(timestamp_str + strlen(timestamp_str), sizeof(timestamp_str) - strlen(timestamp_str), ".%06ld", tv.tv_usec);

    if (fprintf(fp, "%s|%d\n", timestamp_str, raw_adc_value) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export GPIO pin
    if (gpio_export(GPIO_CS) < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_CS);
        return 1;
    }

    // Set GPIO direction to output
    if (gpio_set_direction(GPIO_CS, "out") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to output\n", GPIO_CS);
        gpio_unexport(GPIO_CS);
        return 1;
    }

    // Open SPI device
    spi_fd = spi_open(SPI_DEVICE, SPI_MODE, SPI_BITS_PER_WORD, SPI_MAX_SPEED);
    if (spi_fd < 0) {
        fprintf(stderr, "Failed to open SPI device\n");
        gpio_unexport(GPIO_CS);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file %s: %s\n", LOG_FILE, strerror(errno));
        spi_close(spi_fd);
        gpio_unexport(GPIO_CS);
        return 1;
    }

    // Main loop
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];
    struct timeval tv;
    int raw_adc_value;

    while (keep_running) {
        // Generate SPI command (MCP3008 single-ended read)
        tx_buf[0] = 0x01; // Start bit
        tx_buf[1] = 0x80; // Single-ended channel 0 (0b10000000)
        tx_buf[2] = 0x00; // Don't care

        // Transfer SPI data
        if (spi_transfer(spi_fd, tx_buf, rx_buf, 3) < 0) {
            fprintf(stderr, "SPI transfer failed, exiting\n");
            break;
        }

        // Extract raw ADC value (10 bits)
        raw_adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

        // Get timestamp
        if (gettimeofday(&tv, NULL) < 0) {
            fprintf(stderr, "Error getting timestamp: %s\n", strerror(errno));
            break;
        }

        // Log data
        if (log_data(log_file, tv, raw_adc_value) < 0) {
            fprintf(stderr, "Failed to log data, exiting\n");
            break;
        }

        // Sleep for 1 ms
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 1000000; // 1 ms
        nanosleep(&sleep_time, NULL);
    }

    // Cleanup
    printf("Cleaning up...\n");
    if (spi_close(spi_fd) < 0) {
        fprintf(stderr, "Failed to close SPI device\n");
    }
    if (gpio_write(GPIO_CS, 1) < 0) {
        fprintf(stderr, "Failed to set GPIO %d to high\n", GPIO_CS);
    }
    if (gpio_unexport(GPIO_CS) < 0) {
        fprintf(stderr, "Failed to unexport GPIO %d\n", GPIO_CS);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Exiting.\n");
    return 0;
}

