#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define LOG_FILE "gas_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define VREF 3.3 // Reference voltage for MCP3008

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float voltage;
    float ppm;
} SensorData;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float adc_to_voltage(int adc_value);
float voltage_to_ppm(float voltage);
int log_data(float voltage, float ppm);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Reads the ADC value from the specified channel
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Converts the ADC value to voltage
float adc_to_voltage(int adc_value) {
    return ((float)adc_value / 1023.0) * VREF;
}

// Converts the voltage to PPM (Placeholder formula)
float voltage_to_ppm(float voltage) {
    // This is a placeholder.  A real implementation would
    // involve calibration data and a more complex relationship.
    // For example, a linear relationship might be used.
    // This example returns a constant value.
    return 100.0; // Example PPM value
}

// Logs the data to the file
int log_data(float voltage, float ppm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f V, %.2f PPM\n", timestamp, voltage, ppm);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Gas leak detector started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int adc_value;
        float voltage, ppm;

        // Retry ADC read with exponential backoff
        int retry = 0;
        while (retry < RETRY_COUNT) {
            adc_value = read_mcp3008(0);
            if (adc_value >= 0) {
                break; // Success
            }
            fprintf(stderr, "Retry %d failed, delaying for %d ms...\n", retry + 1, RETRY_DELAY_MS);
            gpioDelay(RETRY_DELAY_MS * 1000); // pigpioDelay takes microseconds
            retry++;
        }

        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value after %d retries.\n", RETRY_COUNT);
            // Log the error to the file
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            fprintf(log_file, "%s, SPI read error\n", timestamp);
            fflush(log_file);
        } else {
            // Convert ADC value to voltage
            voltage = adc_to_voltage(adc_value);

            // Convert voltage to PPM
            ppm = voltage_to_ppm(voltage);

            // Log the data
