#include <signal.h>
#include <math.h>

// ADXL335 Register Addresses
#define ADXL335_REG_DEVID_AD 0x00
#define ADXL335_REG_THRESH_TAP 0x1D
#define ADXL335_REG_OFSX 0x1E
#define ADXL335_REG_OFSY 0x1F
#define ADXL335_REG_OFSZ 0x20
#define ADXL335_REG_DUR 0x21
#define ADXL335_REG_LATENT 0x22
#define ADXL335_REG_WINDOW 0x23
#define ADXL335_REG_THRESH_ACT 0x24
#define ADXL335_REG_TIME_ACT 0x25
#define ADXL335_REG_THRESH_INACT 0x26
#define ADXL335_REG_TIME_INACT 0x27
#define ADXL335_REG_ACT_INACT_CTL 0x28
#define ADXL335_REG_THRESH_FF 0x29
#define ADXL335_REG_TIME_FF 0x2A
#define ADXL335_REG_TAP_AXES 0x2B
#define ADXL335_REG_ACT_TAP_STATUS 0x2C
#define ADXL335_REG_BW_RATE 0x2C
#define ADXL335_REG_POWER_CTL 0x2D
#define ADXL335_REG_INT_ENABLE 0x2E
#define ADXL335_REG_INT_MAP 0x2F
#define ADXL335_REG_INT_SOURCE 0x30
#define ADXL335_REG_DATA_FORMAT 0x31
#define ADXL335_REG_DATAX0 0x32
#define ADXL335_REG_DATAX1 0x33
#define ADXL335_REG_DATAY0 0x34
#define ADXL335_REG_DATAY1 0x35
#define ADXL335_REG_DATAZ0 0x36
#define ADXL335_REG_DATAZ1 0x37

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8

// Kalman Filter Parameters
#define Q 0.01
#define R 0.01

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Structure to hold Kalman filter state
typedef struct {
    float x;
    float y;
    float z;
    float P;
} kalman_state_t;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg);
int spi_write_register(int handle, uint8_t reg, uint8_t value);
int adxl335_init(int handle);
accelerometer_data_t read_accelerometer_data(int handle);
kalman_state_t kalman_filter(kalman_state_t state, accelerometer_data_t data);
void print_filtered_data(kalman_state_t state);
void signal_handler(int signal);

// SPI Read Function
int spi_read_register(int handle, uint8_t reg) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = reg | 0x80; // Read bit + register address
    tx_buf[2] = 0x00; // Dummy byte

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI Read Error: %d\n", result);
        return -1;
    }

    return ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
}

// SPI Write Function
int spi_write_register(int handle, uint8_t reg, uint8_t value) {
    char tx_buf[3];
    char rx_buf[3];

    tx_buf[0] = 0x00; // Start bit
    tx_buf[1] = reg & 0x7F; // Write bit + register address
    tx_buf[2] = value;

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(handle, tx_buf, rx_buf, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI Write Error: %d\n", result);
        return -1;
    }

    return 0;
}

// ADXL335 Initialization Function
int adxl335_init(int handle) {
    // Verify device ID
    int devid = spi_read_register(handle, ADXL335_REG_DEVID_AD);
    if (devid != 0xAD) {
        fprintf(stderr, "Error: Invalid device ID: 0x%X\n", devid);
        return -1;
    }

    // Set data format: Full resolution, +/- 2g range
    if (spi_write_register(handle, ADXL335_REG_DATA_FORMAT, 0x0B) != 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Set bandwidth rate: 100 Hz
    if (spi_write_register(handle, ADXL335_REG_BW_RATE, 0x0A) != 0) {
        fprintf(stderr, "Error writing to BW_RATE register\n");
        return -1;
    }

    // Enable measurement mode
    if (spi_write_register(handle, ADXL335_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Read Accelerometer Data Function
accelerometer_data_t read_accelerometer_data(int handle) {
    accelerometer_data_t data;
    int16_t raw_x, raw_y, raw_z;

    raw_x = (int16_t)((spi_read_register(handle, ADXL335_REG_DATAX1) << 8) | spi_read_register(handle, ADXL335_REG_DATAX0));
    raw_y = (int16_t)((spi_read_register(handle, ADXL335_REG_DATAY1) << 8) | spi_read_register(handle, ADXL335_REG_DATAY0));
    raw_z = (int16_t)((spi_read_register(handle, ADXL335_REG_DATAZ1) << 8) | spi_read_register(handle, ADXL335_REG_DATAZ0));

    // Convert raw data to g-force units (assuming +/- 2g range)
    data.x = (float)raw_x / 256.0;
    data.y = (float)raw_y / 256.0;
    data.z = (float)raw_z / 256.0;

    return data;
}

// Kalman Filter Function
kalman_state_t kalman_filter(kalman_state_t state, accelerometer_data_t data) {
    // Prediction step
    state.x = state.x; // No prediction for X
    state.y = state.y; // No prediction for Y
    state.z = state.z + data.z; // Accumulate Z data

    // Update step
    state.P = state.P + Q; // Update covariance matrix

    return state;
}

// Print Filtered Data Function
void print_filtered_data(kalman_state_t state) {
    printf("X: %.3f g, Y: %.3f g, Z: %.3f g\n", state.x, state.y, state.z);
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008 initially

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL335
    if (adxl335_init(spi_handle) != 0) {
        fprintf(stderr, "ADXL335 initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Kalman filter state
    kalman_state_t kalman_state = {0.0, 0.0, 0.0, 1.0}; // Initial state: zero, zero, zero, and 1.0 covariance

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        accelerometer_data_t raw_data = read_accelerometer_data(spi_handle);

        // Apply Kalman filter
        kalman_state = kalman_filter(kalman_state, raw_data);

        // Print filtered data
        print_filtered_data(kalman_state);

        // Delay for 100ms (10Hz sampling rate)
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

