#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <signal.h>
#include <time.h>
#include <string.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 4
#define SENSOR2_GPIO 17
#define SENSOR3_GPIO 27

// Define the ADC range (0.0 to 3.3V)
#define ADC_RANGE 3.3

// Define the magnetic field range (100 mT to 1000 mT)
#define MAGNETIC_FIELD_RANGE 1000.0

// Define the log file name
#define LOG_FILE "magnetic_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int sensor_value = gpioRead(gpio_pin);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to convert the sensor state to a magnetic field strength
float convert_to_magnetic_field(int sensor_value) {
    // Assuming HIGH is 3.3V and LOW is 0.0V
    float voltage = (float)sensor_value * ADC_RANGE;
    float magnetic_field = (voltage - 0.5) * MAGNETIC_FIELD_RANGE; // Scale to 0-1000 mT
    return magnetic_field;
}

// Function to log the magnetic field strengths to a file
void log_magnetic_field(float sensor1_mT, float sensor2_mT, float sensor3_mT) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "sensor1_mT,sensor2_mT,sensor3_mT\n");
    }

    fprintf(fp, "%.2f,%.2f,%.2f\n", sensor1_mT, sensor2_mT, sensor3_mT);
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

