#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>

// Define SPI device and mode
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0

// Define CSV file name
#define CSV_FILE "sensor_data.csv"

// Global variable for SPI file descriptor
int spi_fd = -1;

// Function prototypes
int spi_init(const char *device, int mode);
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len);
int read_mcp3008(int fd, int channel);
int log_data(const char *filename, int channel0, int channel1, int channel2);
void signal_handler(int signal);

// Structure to hold SPI configuration
typedef struct {
    const char *device;
    int mode;
} spi_config_t;

// SPI initialization function
int spi_init(const char *device, int mode) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode_buf[1];
    mode_buf[0] = mode;
    if (ioctl(fd, SPI_IOC_WR_MODE, &mode_buf) < 0) {
        perror("Error setting SPI mode");
        close(fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits_buf[1];
    bits_buf[0] = 8;
    if (ioctl(fd, SPI_IOC_WR_BITS_PER_WORD, &bits_buf) < 0) {
        perror("Error setting bits per word");
        close(fd);
        return -1;
    }

    // Configure max speed hz
    uint32_t speed_buf[1];
    speed_buf[0] = 1000000; // 1 MHz
    if (ioctl(fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed_buf) < 0) {
        perror("Error setting max speed hz");
        close(fd);
        return -1;
    }

    return fd;
}

// SPI transfer function
int spi_transfer(int fd, uint8_t *tx_buf, uint8_t *rx_buf, int len) {
    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = len,
        .speed_hz = 1000000, // 1 MHz
        .bits_per_word = 8,
    };

    if (ioctl(fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error during SPI transfer");
        return -1;
    }

    return 0;
}

// Function to read from MCP3008 channel
int read_mcp3008(int fd, int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (spi_transfer(fd, tx_buf, rx_buf, 3) < 0) {
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to log data to CSV file
int log_data(const char *filename, int channel0, int channel1, int channel2) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        perror("Error opening CSV file");
        return -1;
    }

    // Get current timestamp
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write data to CSV file
    fprintf(fp, "%s,%d,%d,%d\n", timestamp, channel0, channel1, channel2);

    if (fclose(fp) != 0) {
        perror("Error closing CSV file");
        return -1;
    }

    return 0;
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    if (spi_fd != -1) {
        close(spi_fd);
    }

    exit(0);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize SPI
    spi_fd = spi_init(SPI_DEVICE, SPI_MODE);
    if (spi_fd < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    printf("SPI initialized successfully.\n");

    // Main loop
    while (1) {
        // Read analog values from MCP3008 channels
        int channel0_value = read_mcp3008(spi_fd, 0);
        int channel1_value = read_mcp3008(spi_fd, 1);
        int channel2_value = read_mcp3008(spi_fd, 2);

        if (channel0_value < 0 || channel1_value < 0 || channel2_value < 0) {
            fprintf(stderr, "Error reading from MCP3008. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Log data to CSV file
        if (log_data(CSV_FILE, channel0_value, channel1_value, channel2_value) < 0) {
            fprintf(stderr, "Error logging data. Retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

