        // Read analog values from MCP3008 channels
        int channel0_value = read_mcp3008(spi_fd, 0);
        int channel1_value = read_mcp3008(spi_fd, 1);
        int channel2_value = read_mcp3008(spi_fd, 2);

        if (channel0_value < 0 || channel1_value < 0 || channel2_value < 0) {
            fprintf(stderr, "Error reading from MCP3008. Retrying...\n");
            sleep(1); // Wait before retrying
            continue;
        }

        // Log data to CSV file
        if (log_data(CSV_FILE, channel0_value, channel1_value, channel2_value) < 0) {
            fprintf(stderr, "Error logging data. Retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    return 0;
}

