#include <netinet/in.h>
#include <arpa/inet.h>
#include <mosquitto.h>
#include <jansson.h>
#include <pigpio.h>

// Configuration
#define MQTT_BROKER_ADDRESS "mqtt.eclipseprojects.io"
#define MQTT_BROKER_PORT 1883
#define MQTT_CLIENT_ID "rpi_led_control"
#define MQTT_TOPIC "home/led_control"
#define GPIO_PIN 17
#define MAX_RECONNECT_DELAY 60 // seconds
#define MAX_JSON_LENGTH 256

// Global variables
static struct mosquitto *mosq = NULL;
static int running = 1;
static int reconnect_delay = 1;

// Function prototypes
void signal_handler(int signum);
int mqtt_connect();
int mqtt_subscribe();
int parse_json(const char *json_string, int *led_state);
int set_gpio_state(int led_state);
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message);
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result);
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc);

// Signal handler
void signal_handler(int signum) {
    if (signum == SIGINT || signum == SIGTERM) {
        printf("Received signal %d, shutting down...\n", signum);
        running = 0;
    }
}

// MQTT connect callback
void mqtt_connect_callback(struct mosquitto *mosq, void *userdata, int result) {
    if (!result) {
        printf("MQTT connected to %s:%d\n", MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT);
        mqtt_subscribe();
    } else {
        fprintf(stderr, "MQTT connection error: %s\n", mosquitto_connack_string(result));
        reconnect_delay *= 2; // Exponential backoff
        if (reconnect_delay > MAX_RECONNECT_DELAY) {
            reconnect_delay = MAX_RECONNECT_DELAY;
        }
        printf("Attempting to reconnect in %d seconds...\n", reconnect_delay);
        sleep(reconnect_delay);
        mosquitto_reconnect(mosq);
    }
}

// MQTT disconnect callback
void mqtt_disconnect_callback(struct mosquitto *mosq, void *userdata, int rc) {
    printf("MQTT disconnected with code %d\n", rc);
    reconnect_delay = 1; // Reset delay on disconnect
}

// MQTT message callback
void mqtt_message_callback(struct mosquitto *mosq, void *userdata, const struct mosquitto_message *message) {
    if (message->payloadlen > MAX_JSON_LENGTH) {
        fprintf(stderr, "Error: JSON payload too long (%d bytes)\n", message->payloadlen);
        return;
    }

    char json_string[MAX_JSON_LENGTH + 1];
    strncpy(json_string, (char *)message->payload, message->payloadlen);
    json_string[message->payloadlen] = '\0';

    int led_state;
    if (parse_json(json_string, &led_state) == 0) {
        if (set_gpio_state(led_state) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO state\n");
        }
    } else {
        fprintf(stderr, "Error: Failed to parse JSON\n");
    }
}

// MQTT connect
int mqtt_connect() {
    mosquitto_lib_init();
    mosq = mosquitto_new(MQTT_CLIENT_ID, true, NULL);
    if (!mosq) {
        fprintf(stderr, "Error: Out of memory.\n");
        return -1;
    }

    mosquitto_connect_callback_set(mosq, mqtt_connect_callback);
    mosquitto_disconnect_callback_set(mosq, mqtt_disconnect_callback);
    mosquitto_message_callback_set(mosq, mqtt_message_callback);

    int rc = mosquitto_connect(mosq, MQTT_BROKER_ADDRESS, MQTT_BROKER_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not connect to MQTT broker: %s\n", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    return 0;
}

// MQTT subscribe
int mqtt_subscribe() {
    int rc = mosquitto_subscribe(mosq, NULL, MQTT_TOPIC, 0);
    if (rc != MOSQ_ERR_SUCCESS) {
        fprintf(stderr, "Error: Could not subscribe to topic: %s\n", mosquitto_strerror(rc));
        return -1;
    }
    return 0;
}

// Parse JSON
int parse_json(const char *json_string, int *led_state) {
    json_error_t error;
    json_t *root = json_loads(json_string, 0, &error);

    if (!root) {
        fprintf(stderr, "Error: Could not parse JSON: %s\n", error.text);
        return -1;
    }

    json_t *led_state_json = json_object_get(root, "led_state");
    if (!led_state_json) {
        fprintf(stderr, "Error: Missing 'led_state' key\n");
        json_decref(root);
        return -1;
    }

    if (!json_is_boolean(led_state_json)) {
        fprintf(stderr, "Error: 'led_state' is not a boolean\n");
        json_decref(root);
        return -1;
    }

    *led_state = json_boolean_value(led_state_json);
    json_decref(root);
    return 0;
}

// Set GPIO state
int set_gpio_state(int led_state) {
    gpioWrite(GPIO_PIN, led_state);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Turn off LED initially

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize MQTT
    if (mqtt_connect() != 0) {
        fprintf(stderr, "Error: MQTT connection failed\n");
        gpioTerminate();
        return 1;
    }

    // Start MQTT loop
    mosquitto_loop_start(mosq);

    // Main loop
    while (running) {
        sleep(1); // Reduce CPU usage
    }

    // Stop MQTT loop
    mosquitto_loop_stop(mosq, false);

    // Disconnect from MQTT
    mosquitto_disconnect(mosq);

    // Destroy MQTT client
    mosquitto_destroy(mosq);

    // Cleanup pigpio
    gpioWrite(GPIO_PIN, 0); // Turn off LED
    gpioTerminate();

    printf("Exiting cleanly.\n");
    return 0;
}

