#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the sound sensor value
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to control the alarm LED
void control_alarm_led(int state) {
    gpioWrite(ALARM_LED_PIN, state);
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(ALARM_LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sound_level = read_sound_sensor();

        if (sound_level == PI_BAD_GPIO) {
            fprintf(stderr, "Error reading sound sensor value\n");
        } else {
            printf("Sound Level: %d\n", sound_level);

            if (sound_level == 0) { // Sound detected (LOW signal)
                control_alarm_led(1); // Turn on LED
                gpioDelay(1000);       // Wait for 1 second
                control_alarm_led(0); // Turn off LED
            }
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup GPIO before exiting
    cleanup_gpio();

    return 0;
}

