#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>

#define GPIO_CHIP 0
#define GPIO_LINE 17
#define GPIO_PATH "/sys/class/gpio"
#define LOG_FILE "/var/log/vibration_shutdown.log"
#define DEBOUNCE_DELAY_MS 50

volatile sig_atomic_t program_running = 1;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to export the GPIO line
int gpio_export(int gpio) {
    char buffer[64];
    int fd;

    fd = open(GPIO_PATH "/export", O_WRONLY);
    if (fd < 0) {
        perror("gpio/export");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("gpio/export");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to unexport the GPIO line
int gpio_unexport(int gpio) {
    char buffer[64];
    int fd;

    fd = open(GPIO_PATH "/unexport", O_WRONLY);
    if (fd < 0) {
        perror("gpio/unexport");
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        perror("gpio/unexport");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set the GPIO direction (in or out)
int gpio_set_direction(int gpio, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/direction", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        perror("gpio/direction");
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        perror("gpio/direction");
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to open the GPIO value file for reading
int gpio_open_value(int gpio) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), GPIO_PATH "/gpio%d/value", gpio);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        perror("gpio/value");
        return -1;
    }
    return fd;
}

// Function to read the GPIO value
int gpio_read_value(int fd) {
    char value_str[3];

    if (read(fd, value_str, 3) < 0) {
        perror("gpio/value");
        return -1;
    }
    return atoi(value_str);
}

// Function to close the GPIO value file
int gpio_close_value(int fd) {
    if (close(fd) < 0) {
        perror("gpio/value");
        return -1;
    }
    return 0;
}

// Function to log a message to the log file
int log_message(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("fopen");
        return -1;
    }

    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Function to print a message to stdout
void print_message(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    printf("[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
}

// Function to shutdown the system
int shutdown_system() {
    if (system("sudo shutdown -h now") != 0) {
        perror("system");
        return -1;
    }
    return 0;
}

int main() {
    int gpio_fd;
    int value;
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = DEBOUNCE_DELAY_MS * 1000000; // Convert milliseconds to nanoseconds

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Export the GPIO line
    if (gpio_export(GPIO_LINE) < 0) {
        fprintf(stderr, "Failed to export GPIO %d\n", GPIO_LINE);
        return 1;
    }

    // Set the GPIO direction to input
    if (gpio_set_direction(GPIO_LINE, "in") < 0) {
        fprintf(stderr, "Failed to set GPIO %d direction to input\n", GPIO_LINE);
        gpio_unexport(GPIO_LINE);
        return 1;
    }

    // Open the GPIO value file for reading
    gpio_fd = gpio_open_value(GPIO_LINE);
    if (gpio_fd < 0) {
        fprintf(stderr, "Failed to open GPIO %d value file\n", GPIO_LINE);
        gpio_unexport(GPIO_LINE);
        return 1;
    }

    printf("Vibration monitor started. Monitoring GPIO %d...\n", GPIO_LINE);

    // Main loop
    while (program_running) {
        value = gpio_read_value(gpio_fd);
        if (value < 0) {
            fprintf(stderr, "Failed to read GPIO %d value\n", GPIO_LINE);
            break;
        }

        if (value == 0) { // Assuming active-low sensor
            // Debounce delay
            nanosleep(&delay, NULL);

            // Re-read the value after the debounce delay
            value = gpio_read_value(gpio_fd);
            if (value < 0) {
                fprintf(stderr, "Failed to read GPIO %d value after debounce\n", GPIO_LINE);
                break;
            }

            if (value == 0) { // Still low after debounce
                // Log the event
                if (log_message("Vibration detected!") < 0) {
                    fprintf(stderr, "Failed to log message\n");
                }

                // Print the event to stdout
                print_message("Vibration detected!");

                // Shutdown the system
                if (shutdown_system() < 0) {
                    fprintf(stderr, "Failed to shutdown system\n");
                }

                // Unexport the GPIO line before exiting
                gpio_unexport(GPIO_LINE);

                // Exit the program
                break;
            }
        }

        // Small delay to avoid busy-waiting
        nanosleep(&delay, NULL);
    }

    // Close the GPIO value file
    gpio_close_value(gpio_fd);

    printf("Vibration monitor stopped.\n");

    return 0;
}

