    // Check the chip ID
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_ID);
    if (chip_id != 0x58) {
        fprintf(stderr, "Error: BMP280 not found. Chip ID: 0x%x\n", chip_id);
        return -1;
    }

    // Read calibration data
