    return p;
}

// Calculate altitude using the barometric formula
double calculate_altitude(double pressure) {
    return 44330.0 * (1.0 - pow(pressure / 101325.0, 0.1903));
}

// Log altitude to a file with a timestamp
int log_altitude(double altitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, altitude);
    fflush(log_file); // Ensure data is written to disk immediately

