// Read calibration data from the BMP280
int read_calibration_data() {
    char data[26];

    if (i2cReadI2CBlockData(i2c_handle, BMP280_REG_CALIB_00, data, 26) != 26) {
        fprintf(stderr, "Error: Failed to read calibration data (part 1).\n");
        return -1;
    }

    calib.dig_T1 = (uint16_t)data[0] | ((uint16_t)data[1] << 8);
    calib.dig_T2 = (int16_t)data[2] | ((int16_t)data[3] << 8);
    calib.dig_T3 = (int16_t)data[4] | ((int16_t)data[5] << 8);
    calib.dig_P1 = (uint16_t)data[6] | ((uint16_t)data[7] << 8);
    calib.dig_P2 = (int16_t)data[8] | ((int16_t)data[9] << 8);
    calib.dig_P3 = (int16_t)data[10] | ((int16_t)data[11] << 8);
    calib.dig_P4 = (int16_t)data[12] | ((int16_t)data[13] << 8);
    calib.dig_P5 = (int16_t)data[14] | ((int16_t)data[15] << 8);
    calib.dig_P6 = (int16_t)data[16] | ((int16_t)data[17] << 8);
    calib.dig_P7 = (int16_t)data[18] | ((int16_t)data[19] << 8);
    calib.dig_P8 = (int16_t)data[20] | ((int16_t)data[21] << 8);
    calib.dig_P9 = (int16_t)data[22] | ((int16_t)data[23] << 8);

    return 0;
}

int main() {
    int32_t raw_temperature, raw_pressure;
    double temperature, pressure, altitude;
    int status;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize BMP280 sensor
    if (init_bmp280() != 0) {
        fprintf(stderr, "Error: BMP280 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("altitude_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw data
        status = read_raw_data(&raw_temperature, &raw_pressure);
        if (status != 0) {
            fprintf(stderr, "Error: Failed to read raw data. Retrying in 5 seconds...\n");
            sleep(5);
            continue;
        }

        // Compensate temperature and pressure
        temperature = compensate_temperature(raw_temperature);
        pressure = compensate_pressure(raw_pressure, temperature);

        // Calculate altitude
        altitude = calculate_altitude(pressure);

        // Log altitude
        log_altitude(altitude);

        // Print altitude to console
        printf("Altitude: %.2f meters\n", altitude);

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

