#include <time.h>
#include <signal.h>
#include <string.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8
#define BUFFER_SIZE 120
#define LOG_FILE "temp_log.dat"

// Global variables
int spi_handle;
float temperature_buffer[BUFFER_SIZE];
int buffer_index = 0;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_spi();
int read_mcp3008(int channel);
float convert_to_temperature(int adc_value);
void store_temperature(float temperature);
void print_temperature(float temperature);
void log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for configuration (optional)
typedef struct {
    int spi_channel;
    int spi_speed;
    int cs_pin;
    int buffer_size;
    char *log_file;
} Config;

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    gpioWrite(CS_PIN, 0); // Select the MCP3008
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008

    if (result != 3) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];
    return adc_value;
}

// Convert ADC value to temperature (LM35: 10mV/°C)
float convert_to_temperature(int adc_value) {
    return (adc_value * 3.3) / 1024.0 * 100.0;
}

// Store temperature in circular buffer
void store_temperature(float temperature) {
    temperature_buffer[buffer_index] = temperature;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Print temperature to console
void print_temperature(float temperature) {
    printf("Temperature: %.2f °C\n", temperature);
}

// Log temperature to file
void log_temperature(float temperature) {
    FILE *fp = fopen(LOG_FILE, "wb+");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return;
    }

    // Write temperatures to file
    size_t elements_written = fwrite(temperature_buffer, sizeof(float), BUFFER_SIZE, fp);
    if (elements_written != BUFFER_SIZE) {
        fprintf(stderr, "Error writing to log file: wrote %zu elements, expected %d\n", elements_written, BUFFER_SIZE);
    }

    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the MCP3008 initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(0);
        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value, skipping this iteration.\n");
            gpioDelay(5000); // Wait 5 seconds before retrying
            continue;
        }

        // Convert ADC value to temperature
        float temperature = convert_to_temperature(adc_value);

        // Store temperature in buffer
        store_temperature(temperature);

        // Print temperature to console
        print_temperature(temperature);

        // Log temperature to file
        log_temperature(temperature);

        // Wait 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

