// Define the GPIO pin connected to the flame sensor
#define FLAME_SENSOR_PIN 17

// Define the log file name
#define LOG_FILE "flame_events.log"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_PIN, PI_PUD_DOWN);

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_PIN);
}

// Function to log the flame event to a CSV file
int log_flame_event(int pin, int state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, pin, state);
    fclose(fp);

    return 0;
}

// Function to print an alarm message to stdout
void print_alarm_message() {
    printf("ALARM: Flame detected!\n");
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO pin
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 1) {
            log_flame_event(FLAME_SENSOR_PIN, sensor_value);
            print_alarm_message();
        }

        gpioDelay(1000); // Wait for 1 second
    }

    // Clean up GPIO resources before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

