#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define MCP3008_CHANNEL 0
#define MCP4725_I2C_ADDR 0x60
#define DAC_VOLTAGE_MAX 3.3
#define LOG_FILE "temperature_log.txt"
#define SAMPLE_INTERVAL_SEC 0.5

// Global variables
int spi_handle;
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float convert_adc_to_temperature(int adc_value);
int set_dac_voltage(float temperature);
int log_data(int adc_value, float temperature, float dac_voltage);
void signal_handler(int signal);

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    char tx_buffer[3];
    char rx_buffer[3];

    // Construct SPI message
    tx_buffer[0] = 0x01; // Start bit
    tx_buffer[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buffer[2] = 0x00; // Don't care

    // Transfer SPI data
    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buffer[1] & 0x03) << 8) + rx_buffer[2];

    return adc_value;
}

// Function to convert ADC value to temperature (Celsius)
float convert_adc_to_temperature(int adc_value) {
    float voltage = (float)adc_value / 1023.0 * DAC_VOLTAGE_MAX;
    float temperature = (voltage - 0.5) * 100.0;
    return temperature;
}

// Function to set DAC voltage
int set_dac_voltage(float temperature) {
    // Map temperature to DAC voltage (0-3.3V)
    float voltage = temperature / 100.0 * DAC_VOLTAGE_MAX;

    // Convert voltage to DAC value (0-4095)
    int dac_value = (int)(voltage / DAC_VOLTAGE_MAX * 4095.0);

    // Construct DAC command (MCP4725 datasheet)
    char tx_buffer[3];
    tx_buffer[0] = 0x40; // Write DAC command
    tx_buffer[1] = (dac_value >> 4) & 0xFF; // MSB
    tx_buffer[2] = dac_value & 0x0F; // LSB

    // Transfer DAC data
    int result = i2cWriteDevice(i2c_handle, tx_buffer, 3);
    if (result != 0) {
        fprintf(stderr, "Error: I2C write failed: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to log data to file
int log_data(int adc_value, float temperature, float dac_voltage) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, ADC: %d, Temperature: %.2f °C, DAC: %.2f V\n", timestamp, adc_value, temperature, dac_voltage);
    fflush(log_file); // Ensure data is written to file immediately

    printf("%s, ADC: %d, Temperature: %.2f °C, DAC: %.2f V\n", timestamp, adc_value, temperature, dac_voltage);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI interface
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // CE0, 500kHz, Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open I2C interface
    i2c_handle = i2cOpen(1, MCP4725_I2C_ADDR, 0); // Bus 1, address 0x60, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC value
        int adc_value = read_mcp3008(MCP3008_CHANNEL);
        if (adc_value < 0) {
            fprintf(stderr, "Error: Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to temperature
        float temperature = convert_adc_to_temperature(adc_value);

        // Set DAC voltage
        if (set_dac_voltage(temperature) != 0) {
            fprintf(stderr, "Error: Failed to set DAC voltage\n");
        }

        // Log data
        log_data(adc_value, temperature, (float)adc_value / 4095.0 * DAC_VOLTAGE_MAX);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

