#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define MCP3008_CHANNEL_0 0
#define MCP3008_CHANNEL_1 1
#define MCP3008_CHANNEL_2 2
#define SLEEP_DURATION 60 // seconds
#define LOG_FILE "soil_data.txt"

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_mcp3008(int channel);
float calculate_moisture_percentage(int adc_value);
int log_data(float moisture_percentage_0, float moisture_percentage_1, float moisture_percentage_2);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Error: Invalid MCP3008 channel: %d\n", channel);
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message
    spi_tx_buf[0] = 0x01; // Start bit
    spi_tx_buf[1] = ((channel & 0x07) << 4) | 0x80; // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00; // Don't care

    // Transfer data
    int result = spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3);
    if (result != 0) {
        fprintf(stderr, "Error: SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract ADC value
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];

    return adc_value;
}

// Function to calculate moisture percentage
float calculate_moisture_percentage(int adc_value) {
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: Invalid ADC value: %d\n", adc_value);
        return -1.0; // Indicate invalid value
    }

    // Linear mapping: 0 ADC = 100% moisture, 1023 ADC = 0% moisture
    float moisture_percentage = 100.0 - ((float)adc_value / 1023.0) * 100.0;

    return moisture_percentage;
}

// Function to log data to file
int log_data(float moisture_percentage_0, float moisture_percentage_1, float moisture_percentage_2) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, moisture_percentage_0, moisture_percentage_1, moisture_percentage_2);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed: %d\n", spi_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Soil moisture monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read ADC values
        int adc_value_0 = read_mcp3008(MCP3008_CHANNEL_0);
        int adc_value_1 = read_mcp3008(MCP3008_CHANNEL_1);
        int adc_value_2 = read_mcp3008(MCP3008_CHANNEL_2);

        // Calculate moisture percentages
        float moisture_percentage_0 = calculate_moisture_percentage(adc_value_0);
        float moisture_percentage_1 = calculate_moisture_percentage(adc_value_1);
        float moisture_percentage_2 = calculate_moisture_percentage(adc_value_2);

        // Log data
        if (log_data(moisture_percentage_0, moisture_percentage_1, moisture_percentage_2) != 0) {
            fprintf(stderr, "Error: Failed to log data\n");
        }

        // Print data to console
        printf("Sensor 0: %.2f%%, Sensor 1: %.2f%%, Sensor 2: %.2f%%\n", moisture_percentage_0, moisture_percentage_1, moisture_percentage_2);

        // Sleep for specified duration
        gpioSleep(PI_TIME_RELATIVE, SLEEP_DURATION, 0); // seconds, microseconds
    }

    // Cleanup
    printf("Cleaning up...\n");
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

