#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RELAY1_PIN 17
#define RELAY2_PIN 22
#define RELAY3_PIN 23
#define RELAY4_PIN 24

// Function prototypes
void activate_relay(int pin);
void deactivate_relay(int pin);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
        program_running = 0;
        cleanup_gpio();
        exit(0);
    }
}

// Function to activate a relay
void activate_relay(int pin) {
    if (gpioWrite(pin, 0) != 0) { // Active-high relays, LOW to activate
        fprintf(stderr, "Error: Failed to activate relay on pin %d\n", pin);
    } else {
        printf("Relay on pin %d activated\n", pin);
    }
}

// Function to deactivate a relay
void deactivate_relay(int pin) {
    if (gpioWrite(pin, 1) != 0) { // Active-high relays, HIGH to deactivate
        fprintf(stderr, "Error: Failed to deactivate relay on pin %d\n", pin);
    } else {
        printf("Relay on pin %d deactivated\n", pin);
    }
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    // Deactivate all relays
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Set all pins to input mode (safer)
    gpioSetMode(RELAY1_PIN, PI_INPUT);
    gpioSetMode(RELAY2_PIN, PI_INPUT);
    gpioSetMode(RELAY3_PIN, PI_INPUT);
    gpioSetMode(RELAY4_PIN, PI_INPUT);

    // Terminate pigpio library
    gpioTerminate();
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize relays to inactive state (LOW)
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Set up signal handling for Ctrl+C and termination signals
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Activate relay 1 for 1 second
        activate_relay(RELAY1_PIN);
