#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define RAIN_THRESHOLD 5
#define MOTOR_FORWARD_PIN 17
#define MOTOR_REVERSE_PIN 18
#define MOTOR_ENABLE_PIN 27
#define LOG_FILE "rain_log.txt"
#define MOTOR_FORWARD_DURATION 3 // seconds
#define MOTOR_REVERSE_DURATION 3 // seconds

// Global variables
volatile sig_atomic_t program_running = 1;
int spi_fd;
FILE *log_file;

// Function prototypes
int read_mcp3008(int channel);
int log_data(int rain_level);
void close_window();
void open_window();
void signal_handler(int signal);

// Function to read data from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel selection
    tx_buf[2] = 0x00; // Don't care

    if (wiringPiSPIDataRW(SPI_CHANNEL, tx_buf, 3) == -1) {
        fprintf(stderr, "Error: SPI data transfer failed: %s\n", strerror(errno));
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to log data to file
int log_data(int rain_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s, %d\n", timestamp, rain_level);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to close the window
void close_window() {
    printf("Closing window...\n");
    digitalWrite(MOTOR_FORWARD_PIN, LOW);
    digitalWrite(MOTOR_REVERSE_PIN, HIGH);
    pwmWrite(MOTOR_ENABLE_PIN, 150); // PWM duty cycle (0-255)
    delay(MOTOR_FORWARD_DURATION * 1000); // Delay in milliseconds
    digitalWrite(MOTOR_FORWARD_PIN, LOW);
    digitalWrite(MOTOR_REVERSE_PIN, LOW);
    pwmWrite(MOTOR_ENABLE_PIN, 0); // Stop the motor
    printf("Window closed.\n");
}

// Function to open the window
void open_window() {
    printf("Opening window...\n");
    digitalWrite(MOTOR_FORWARD_PIN, HIGH);
    digitalWrite(MOTOR_REVERSE_PIN, LOW);
    pwmWrite(MOTOR_ENABLE_PIN, 150); // PWM duty cycle (0-255)
    delay(MOTOR_REVERSE_DURATION * 1000); // Delay in milliseconds
    digitalWrite(MOTOR_FORWARD_PIN, LOW);
    digitalWrite(MOTOR_REVERSE_PIN, LOW);
    pwmWrite(MOTOR_ENABLE_PIN, 0); // Stop the motor
    printf("Window opened.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

int main() {
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize SPI
    spi_fd = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_fd == -1) {
        fprintf(stderr, "Error: SPI initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Configure GPIO pins for motor control
    pinMode(MOTOR_FORWARD_PIN, OUTPUT);
    pinMode(MOTOR_REVERSE_PIN, OUTPUT);
    pinMode(MOTOR_ENABLE_PIN, PWM_OUTPUT);
    pwmSetMode(PWM_MODE_MS); // Mark:Space mode
    pwmSetRange(255);       // Set PWM range to 255
    pwmSetClock(192);       // Set PWM clock (adjust as needed)

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Rain sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read rain level from MCP3008
        int rain_level = read_mcp3008(0);
        if (rain_level == -1) {
            fprintf(stderr, "Error: Failed to read rain level.\n");
            continue; // Skip to the next iteration
        }

        // Log data
        if (log_data(rain_level) == -1) {
            fprintf(stderr, "Error: Failed to log data.\n");
        }

        // Check rain threshold and control window
        if (rain_level > RAIN_THRESHOLD) {
            close_window();
        } else {
            open_window();
        }

        // Wait for 1 second
        delay(1000);
    }

    // Cleanup
    printf("Cleaning up...\n");
    close_window(); // Ensure window is closed on exit
    fclose(log_file);
    close(spi_fd);

    printf("Exiting.\n");
    return 0;
}

