// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define VREF 3.3          // Reference voltage for MCP3008
#define ADC_CHANNEL 0      // MCP3008 channel connected to the sensor
#define GPIO_PIN 17        // GPIO pin connected to the sensor's power enable
#define LOG_FILE "current_log.txt"
#define SLEEP_DURATION 1 // Sleep duration in seconds

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float voltage;
    float current;
} sensor_data_t;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_adc(int channel);
float convert_to_current(int adc_value);
int log_data(float current);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library and sets the GPIO pin as output
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure power is off initially
    return 0;
}

// Initializes the SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_SPEED, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Reads the ADC value from the specified channel
int read_adc(int channel) {
    if (channel < 0 || channel > 7) {
        fprintf(stderr, "Invalid ADC channel\n");
        return -1;
    }

    unsigned char spi_tx_buf[3];
    unsigned char spi_rx_buf[3];

    // Construct SPI message (MCP3008 datasheet)
    spi_tx_buf[0] = 0x01;                           // Start bit
    spi_tx_buf[1] = (0x08 | channel) << 4;           // Single-ended mode, channel select
    spi_tx_buf[2] = 0x00;                           // Don't care

    if (spiXfer(spi_handle, spi_tx_buf, spi_rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Extract ADC value from response
    int adc_value = ((spi_rx_buf[1] & 0x03) << 8) + spi_rx_buf[2];
    return adc_value;
}

// Converts the ADC reading to current in amperes
float convert_to_current(int adc_value) {
    float voltage = (float)adc_value * VREF / 1024.0;
    float current = voltage / 0.1; // Assuming 100mV/A
    return current;
}

// Logs the current data to a CSV file
int log_data(float current) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.4f\n", timestamp, current);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(GPIO_PIN, 0); // Turn off power
    spiClose(spi_handle);
    fclose(log_file);
    gpioTerminate();
}

