        if (adc_value < 0) {
            fprintf(stderr, "Failed to read ADC value\n");
            continue; // Skip to the next iteration
        }

        // Convert ADC value to current
        float current = convert_to_current(adc_value);

        // Log data
        if (log_data(current) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Sleep for 1 second
        gpioDelay(SLEEP_DURATION * 1000000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
