#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 4
#define SENSOR_2_GPIO 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 2

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to debounce the sensor readings
int debounce_sensor(int gpio_pin) {
    int count_0 = 0;
    int count_1 = 0;
    for (int i = 0; i < 5; i++) {
        int value = read_sensor(gpio_pin);
        if (value == 0) {
            count_0++;
        } else if (value == 1) {
            count_1++;
        } else {
            fprintf(stderr, "Error reading sensor value in debounce.\n");
            return -1; // Indicate an error
        }
        gpioDelay(DEBOUNCE_DELAY * 1000); // Delay in microseconds
    }
    return (count_0 > count_1) ? 0 : 1;
}

// Function to log the sensor state
void log_sensor_state(int sensor_number, int state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Sensor %d: %s\n", timestamp, sensor_number, state ? "Object Present" : "No Object");
}

// Function to check if both sensors detect object
int check_both_sensors(int sensor1_state, int sensor2_state) {
    return (sensor1_state == 0 && sensor2_state == 0) ? 1 : 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor 1
        int sensor1_state = debounce_sensor(SENSOR_1_GPIO);
        if (sensor1_state < 0) {
            fprintf(stderr, "Error reading sensor 1, exiting.\n");
            break;
        }

        // Read sensor 2
        int sensor2_state = debounce_sensor(SENSOR_2_GPIO);
        if (sensor2_state < 0) {
            fprintf(stderr, "Error reading sensor 2, exiting.\n");
            break;
        }

        // Log the sensor states
        log_sensor_state(1, sensor1_state);
        log_sensor_state(2, sensor2_state);

        // Check if both sensors detect object
        int both_sensors_detect_object = check_both_sensors(sensor1_state, sensor2_state);

        // Log the alert if both sensors detect object
        if (both_sensors_detect_object) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            printf("[%s] ALERT: Both sensors detect object\n", timestamp);
        }

        gpioDelay(1000000); // Delay for 1 second (1000000 microseconds)
    }

    // Release GPIO resources before exiting
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

