#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/videodev2.h>
#include <errno.h>
#include <sys/stat.h>
#include <sys/types.h>

// Configuration
#define GPIO_PIN 17
#define DEBOUNCE_DELAY_MS 200
#define CAPTURE_DIR "/home/pi/security_cam/"
#define LOG_FILE "/var/log/security_cam.log"
#define MAX_FILENAME_LENGTH 256

// Global variables
static volatile int running = 1;
static int gpio_fd = -1;
static int camera_fd = -1;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
int gpio_set_direction(int pin, const char *direction);
int gpio_read(int pin);
int capture_image(const char *filename);
int log_event(const char *message);
void signal_handler(int sig);
int initialize_gpio();
int initialize_camera();
void cleanup();

// Helper function to construct the filename
int construct_filename(char *filename, size_t filename_size, const char *timestamp) {
    if (filename == NULL || filename_size == 0 || timestamp == NULL) {
        return -1;
    }

    snprintf(filename, filename_size, "%s%s.jpg", CAPTURE_DIR, timestamp);
    return 0;
}

// GPIO export function
int gpio_export(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open /sys/class/gpio/export: %s", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        syslog(LOG_ERR, "Failed to write to /sys/class/gpio/export: %s", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO unexport function
int gpio_unexport(int pin) {
    char buffer[64];
    int len;
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open /sys/class/gpio/unexport: %s", strerror(errno));
        return -1;
    }

    len = snprintf(buffer, sizeof(buffer), "%d", pin);
    if (write(fd, buffer, len) != len) {
        syslog(LOG_ERR, "Failed to write to /sys/class/gpio/unexport: %s", strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO set direction function
int gpio_set_direction(int pin, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", pin);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", path, strerror(errno));
        return -1;
    }

    if (write(fd, direction, strlen(direction)) != strlen(direction)) {
        syslog(LOG_ERR, "Failed to write to %s: %s", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// GPIO read function
int gpio_read(int pin) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", pin);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", path, strerror(errno));
        return -1;
    }

    if (read(fd, value_str, 3) < 0) {
        syslog(LOG_ERR, "Failed to read from %s: %s", path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return atoi(value_str);
}

// Capture image function using libcamera-still
int capture_image(const char *filename) {
    char command[256];
    int status;

    snprintf(command, sizeof(command), "libcamera-still -o %s --width 640 --height 480 --encoding jpeg --timeout 1000", filename);
    syslog(LOG_INFO, "Executing command: %s", command);

    status = system(command);
    if (status == -1) {
        syslog(LOG_ERR, "Failed to execute command: %s", strerror(errno));
        return -1;
    }

    if (WIFEXITED(status) && WEXITSTATUS(status) != 0) {
        syslog(LOG_ERR, "libcamera-still exited with status %d", WEXITSTATUS(status));
        return -1;
    }

    return 0;
}

// Log event function
int log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[32];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize GPIO
int initialize_gpio() {
    if (gpio_export(GPIO_PIN) < 0) {
        return -1;
    }

    if (gpio_set_direction(GPIO_PIN, "in") < 0) {
        gpio_unexport(GPIO_PIN);
        return -1;
    }

    gpio_fd = open("/sys/class/gpio/gpio17/value", O_RDONLY);
    if (gpio_fd < 0) {
        syslog(LOG_ERR, "Failed to open GPIO value file: %s", strerror(errno));
        gpio_unexport(GPIO_PIN);
        return -1;
    }

    return 0;
}

// Initialize camera
int initialize_camera() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;
    struct v4l2_buffer buf;

    camera_fd = open("/dev/video0", O_RDWR | O_NONBLOCK, 0);
    if (camera_fd < 0) {
        syslog(LOG_ERR, "Failed to open camera device: %s", strerror(errno));
        return -1;
    }

    if (ioctl(camera_fd, VIDIOC_QUERYCAP, &cap) < 0) {
        syslog(LOG_ERR, "Failed to query camera capabilities: %s", strerror(errno));
        close(camera_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        syslog(LOG_ERR, "Camera does not support video capture");
        close(camera_fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        syslog(LOG_ERR, "Camera does not support streaming I/O");
        close(camera_fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = 640;
    fmt.fmt.pix.height = 480;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(camera_fd, VIDIOC_S_FMT, &fmt) < 0) {
        syslog(LOG_ERR, "Failed to set camera format: %s", strerror(errno));
        close(camera_fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(camera_fd, VIDIOC_REQBUFS, &req) < 0) {
        syslog(LOG_ERR, "Failed to request buffers: %s", strerror(errno));
        close(camera_fd);
        return -1;
    }

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(camera_fd, VIDIOC_QUERYBUF, &buf) < 0) {
        syslog(LOG_ERR, "Failed to query buffer: %s", strerror(errno));
        close(camera_fd);
        return -1;
    }

    if (ioctl(camera_fd, VIDIOC_QBUF, &buf) < 0) {
        syslog(LOG_ERR, "Failed to queue buffer: %s", strerror(errno));
        close(camera_fd);
        return -1;
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(camera_fd, VIDIOC_STREAMON, &type) < 0) {
        syslog(LOG_ERR, "Failed to start streaming: %s", strerror(errno));
        close(camera_fd);
        return -1;
    }

    return 0;
}

// Cleanup function
void cleanup() {
    if (gpio_fd != -1) {
        close(gpio_fd);
        gpio_unexport(GPIO_PIN);
    }
    if (camera_fd != -1) {
        enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        ioctl(camera_fd, VIDIOC_STREAMOFF, &type);
        close(camera_fd);
    }
    closelog();
}

int main() {
    int current_state = 0;
    int last_state = 0;
    struct timespec delay = {0, DEBOUNCE_DELAY_MS * 1000000L}; // 200ms
    char filename[MAX_FILENAME_LENGTH];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    // Initialize syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        cleanup();
        return 1;
    }

    // Initialize camera
    if (initialize_camera() < 0) {
        syslog(LOG_ERR, "Camera initialization failed");
        cleanup();
        return 1;
    }

    log_event("System started");

    while (running) {
        int new_state = gpio_read(GPIO_PIN);
        if (new_state < 0) {
            syslog(LOG_ERR, "Failed to read GPIO value");
            break;
        }

        if (new_state != last_state) {
            nanosleep(&delay, NULL);
            int re_read_state = gpio_read(GPIO_PIN);
            if (re_read_state < 0) {
                syslog(LOG_ERR, "Failed to re-read GPIO value");
                break;
            }

            if (re_read_state == new_state) {
                if (new_state == 1) {
                    // Motion detected
                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

                    if (construct_filename(filename, sizeof(filename), timestamp) == 0) {
                        if (capture_image(filename) == 0) {
                            log_event("Motion detected and image captured");
                        } else {
                            syslog(LOG_ERR, "Failed to capture image");
                        }
                    } else {
                        syslog(LOG_ERR, "Failed to construct filename");
                    }
                }
                last_state = new_state;
            }
        }

        usleep(10000); // Check every 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

