    int last_state = 0;
    struct timespec delay = {0, DEBOUNCE_DELAY_MS * 1000000L}; // 200ms
    char filename[MAX_FILENAME_LENGTH];
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[32];

    // Initialize syslog
    openlog("security_cam", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        cleanup();
        return 1;
    }

    // Initialize camera
    if (initialize_camera() < 0) {
        syslog(LOG_ERR, "Camera initialization failed");
        cleanup();
        return 1;
    }

    log_event("System started");

    while (running) {
        int new_state = gpio_read(GPIO_PIN);
        if (new_state < 0) {
            syslog(LOG_ERR, "Failed to read GPIO value");
            break;
        }

        if (new_state != last_state) {
            nanosleep(&delay, NULL);
            int re_read_state = gpio_read(GPIO_PIN);
            if (re_read_state < 0) {
                syslog(LOG_ERR, "Failed to re-read GPIO value");
                break;
            }

            if (re_read_state == new_state) {
                if (new_state == 1) {
                    // Motion detected
                    time(&rawtime);
                    timeinfo = localtime(&rawtime);
                    strftime(timestamp, sizeof(timestamp), "%Y%m%d_%H%M%S", timeinfo);

                    if (construct_filename(filename, sizeof(filename), timestamp) == 0) {
