// Default camera device
#define DEFAULT_DEVICE "/dev/video0"

// Image width and height
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480

// Global variables
static int fd = -1; // File descriptor for the camera device
static void *buffer = NULL; // Buffer to store the image data
static size_t buffer_size = 0; // Size of the buffer
static volatile sig_atomic_t stop_flag = 0; // Flag to signal program termination

// Structure to hold camera configuration
typedef struct {
    char device[256];
    int width;
    int height;
} camera_config_t;

// Function prototypes
int open_camera(const char *device);
int configure_camera(int fd, int width, int height);
int map_buffer(int fd, void **buffer, size_t *buffer_size);
int dequeue_buffer(int fd, void **buffer);
int enqueue_buffer(int fd, void *buffer);
int save_image(const char *filename, void *buffer, size_t buffer_size);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    if (sig == SIGINT || sig == SIGTERM) {
        printf("Caught signal %d, stopping...\n", sig);
        stop_flag = 1;
    }
}

// Open the camera device
int open_camera(const char *device) {
    int fd = open(device, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening camera device");
        return -1;
    }
    return fd;
}

// Configure the camera for grayscale capture
int configure_camera(int fd, int width, int height) {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    // Check device capabilities
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying camera capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming I/O\n");
        return -1;
    }

    // Set image format
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = width;
    fmt.fmt.pix.height = height;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_GREY;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting image format");
        return -1;
    }

    // Request buffers
    memset(&req, 0, sizeof(req));
    req.count = 1; // Single buffer
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < 1) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        return -1;
    }

    buffer_size = req.count * fmt.fmt.pix.bytesperline * fmt.fmt.pix.height;
    buffer = malloc(buffer_size);
    if (!buffer) {
        perror("Error allocating buffer");
        return -1;
    }

    return 0;
}

// Map the buffer to memory
int map_buffer(int fd, void **buffer, size_t *buffer_size) {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = 0;

    if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
        perror("Error querying buffer");
        return -1;
    }

    *buffer = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);
    if (*buffer == MAP_FAILED) {
        perror("Error mapping buffer");
        return -1;
    }

    *buffer_size = buf.length;
    return 0;
}

// Dequeue a buffer from the queue
int dequeue_buffer(int fd, void **buffer) {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buf) < 0) {
        if (errno == EAGAIN) {
            // No data available, return EAGAIN
            return EAGAIN;
        } else {
            perror("Error dequeuing buffer");
            return -1;
        }
    }

    *buffer = buffer + buf.index;
    return 0;
}

// Enqueue a buffer back to the queue
int enqueue_buffer(int fd, void *buffer) {
    struct v4l2_buffer buf;

    memset(&buf, 0, sizeof(buf));
    buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf.memory = V4L2_MEMORY_MMAP;
    buf.index = buffer - buffer; // Index of the buffer in the array

    if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
        perror("Error queuing buffer");
        return -1;
    }

    return 0;
}

// Save the image as a PGM file
int save_image(const char *filename, void *buffer, size_t buffer_size) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) {
        perror("Error opening file for writing");
        return -1;
    }

    // Write PGM header
    fprintf(fp, "P5\n%d %d\n255\n", IMAGE_WIDTH, IMAGE_HEIGHT);

    // Write image data
    size_t bytes_written = fwrite(buffer, 1, buffer_size, fp);
    if (bytes_written != buffer_size) {
        fprintf(stderr, "Error writing to file\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (fd != -1) {
        // Stop streaming
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        for (int i = 0; i < 1; i++) {
            buf.index = i;
            ioctl(fd, VIDIOC_QBUF, &buf);
        }
        ioctl(fd, VIDIOC_STREAMOFF, V4L2_BUF_TYPE_VIDEO_CAPTURE);

        // Unmap buffer
        if (buffer) {
            munmap(buffer, buffer_size);
        }

        // Close device
        close(fd);
    }

    printf("Cleanup complete. Exiting.\n");
}

int main(int argc, char *argv[]) {
    camera_config_t config;
    config.width = IMAGE_WIDTH;
    config.height = IMAGE_HEIGHT;
    strncpy(config.device, DEFAULT_DEVICE, sizeof(config.device) - 1);
    config.device[sizeof(config.device) - 1] = '\0'; // Ensure null termination

    // Parse command-line arguments
    if (argc > 1) {
        strncpy(config.device, argv[1], sizeof(config.device) - 1);
        config.device[sizeof(config.device) - 1] = '\0';
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the camera device
    fd = open_camera(config.device);
    if (fd < 0) {
        return 1;
    }

    // Configure the camera
    if (configure_camera(fd, config.width, config.height) < 0) {
        cleanup();
        return 1;
    }

    // Map the buffer
    if (map_buffer(fd, &buffer, &buffer_size) < 0) {
        cleanup();
        return 1;
    }

    printf("Camera initialized successfully. Capturing images...\n");

    // Main loop
    struct timeval start_time, current_time;
    gettimeofday(&start_time, NULL);
    int frame_number = 1;

    while (!stop_flag) {
        void *dequeued_buffer;
        if (dequeue_buffer(fd, &dequeued_buffer) == 0) {
            // Save the image
            char filename[64];
            snprintf(filename, sizeof(filename), "image_%04d.pgm", frame_number);
            if (save_image(filename, dequeued_buffer, buffer_size) < 0) {
                fprintf(stderr, "Error saving image\n");
            }
            frame_number++;

            // Enqueue the buffer
            if (enqueue_buffer(fd, dequeued_buffer) < 0) {
                fprintf(stderr, "Error enqueueing buffer\n");
            }
        } else {
            // Handle EAGAIN (no data available)
            struct timeval timeout;
            timeout.tv_sec = 2; // 2 seconds
            timeout.tv_usec = 0;

            fd_set fds;
            FD_ZERO(&fds);
            FD_SET(fd, &fds);

            int select_result = select(fd + 1, &fds, NULL, NULL, &timeout);

            if (select_result == -1) {
                perror("Error in select");
                break;
            } else if (select_result == 0) {
                // Timeout occurred, no data available
                fprintf(stderr, "Timeout waiting for data\n");
                break;
            }
        }
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

