#include <sys/mman.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Configuration
#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define YUYV_FORMAT V4L2_PIX_FMT_YUYV
#define NUM_BUFFERS 4
#define UDP_IP "127.0.0.1"
#define UDP_PORT 5000
#define MAX_PACKET_SIZE 65000
#define MAX_FRAME_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 2) // YUYV

// Global variables
static int fd = -1;
static struct v4l2_buffer buf;
static struct v4l2_buffer *buffers = NULL;
static int frame_index = 0;
static int fragment_index = 0;
static int total_fragments = 0;
static int packet_size = 0;
static int udp_socket = -1;
static struct sockaddr_in server_addr;
static volatile sig_atomic_t running = 1;

// Function prototypes
int open_device(const char *device_name);
int init_device(int fd);
int request_buffers(int fd, int num_buffers);
int map_buffers(int fd, struct v4l2_buffer *buffers, int num_buffers);
int unmap_buffers(int fd, struct v4l2_buffer *buffers, int num_buffers);
int close_device(int fd);
int capture_frame(int fd, struct v4l2_buffer *buf);
int fragment_frame(unsigned char *frame, int frame_size, unsigned char *packet, int packet_size);
int send_udp_packet(int socket, struct sockaddr_in server_addr, unsigned char *packet, int packet_size);
void signal_handler(int sig);

// Function to open the device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Function to initialize the device
int init_device(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Error: Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Error: Device does not support streaming I/O\n");
        return -1;
    }

    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = YUYV_FORMAT;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        return -1;
    }

    return 0;
}

// Function to request buffers
int request_buffers(int fd, int num_buffers) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = num_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Error: Insufficient buffer memory\n");
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        perror("Error allocating buffer memory");
        return -1;
    }

    for (int i = 0; i < req.count; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }
    }

    return 0;
}

// Function to map buffers
int map_buffers(int fd, struct v4l2_buffer *buffers, int num_buffers) {
    for (int i = 0; i < num_buffers; ++i) {
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QBUF, &buf) < 0) {
            perror("Error queuing buffer");
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        return -1;
    }

    return 0;
}

// Function to unmap buffers
int unmap_buffers(int fd, struct v4l2_buffer *buffers, int num_buffers) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    for (int i = 0; i < num_buffers; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }

    free(buffers);
    return 0;
}

// Function to close the device
int close_device(int fd) {
    if (fd != -1) {
        close(fd);
    }
    return 0;
}

// Function to capture a frame
int capture_frame(int fd, struct v4l2_buffer *buf) {
    memset(buf, 0, sizeof(*buf));
    buf->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buf->memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, buf) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return 0;
}

// Function to fragment a frame into UDP packets
int fragment_frame(unsigned char *frame, int frame_size, unsigned char *packet, int packet_size) {
    // YUYV format: Y0 U0 Y1 V1 Y2 U2 Y3 V3 ...
    // Each pixel is 2 bytes (Y0, U0, Y1, V1)
    // Each frame is IMAGE_WIDTH * IMAGE_HEIGHT * 2 bytes
    // Each packet is MAX_PACKET_SIZE bytes
    // Total number of packets = (frame_size / MAX_PACKET_SIZE) + 1
    // Total number of fragments = (frame_size / MAX_FRAME_SIZE) + 1

    total_fragments = (frame_size / MAX_FRAME_SIZE) + 1;
    packet_size = MAX_PACKET_SIZE;

    // Calculate the number of fragments in the last packet
    int last_packet_fragments = (frame_size % MAX_FRAME_SIZE) / MAX_PACKET_SIZE;
    if (last_packet_fragments > 0) {
        total_fragments++;
    }

    // Copy the frame data into the packet buffer
    memcpy(packet, frame, frame_size);

    return 0;
}

// Function to send a UDP packet
int send_udp_packet(int socket, struct sockaddr_in server_addr, unsigned char *packet, int packet_size) {
    ssize_t bytes_sent = sendto(socket, packet, packet_size, 0, (struct sockaddr *)&server_addr, sizeof(server_addr));
    if (bytes_sent < 0) {
        perror("Error sending UDP packet");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", sig);
}

int main(int argc, char *argv[]) {
    if (argc != 3) {
        fprintf(stderr, "Usage: %s <libv4l2_api_call> <libv4l2_api_call>\n", argv[0]);
        return 1;
    }

    // Initialize libv4l2
    if (system(argv[1]) != 0) {
        fprintf(stderr, "Error initializing libv4l2: %s\n", argv[1]);
        return 1;
    }

    // Initialize libv4l2
    if (system(argv[2]) != 0) {
        fprintf(stderr, "Error initializing libv4l2: %s\n", argv[2]);
        return 1;
    }

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return 1;
    }

    // Initialize the device
    if (init_device(fd) < 0) {
        close_device(fd);
        return 1;
    }

    // Request buffers
    if (request_buffers(fd, NUM_BUFFERS) < 0) {
        close_device(fd);
        return 1;
    }

    // Map buffers
    if (map_buffers(fd, buffers, NUM_BUFFERS) < 0) {
        unmap_buffers(fd, buffers, NUM_BUFFERS);
        close_device(fd);
        return 1;
    }

    // Set up UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
