#define IMAGE_SIZE (IMAGE_WIDTH * IMAGE_HEIGHT * 3 / 2) // MJPEG
#define NUM_BUFFERS 4

// Global variables
static int fd = -1;
static struct v4l2_buffer *buffers = NULL;
static unsigned int n_buffers = 0;
static volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int open_device(const char *device_name);
int query_capabilities(int fd);
int set_pixel_format(int fd);
int request_buffers(int fd, unsigned int count);
int map_buffers(int fd, struct v4l2_buffer *buffers, unsigned int count);
int start_streaming(int fd);
int dequeue_buffer(int fd, struct v4l2_buffer *buffer);
int verify_buffer(const struct v4l2_buffer *buffer);
int write_image(const unsigned char *data, size_t size);
int stop_streaming(int fd);
int unmap_buffers(int fd, struct v4l2_buffer *buffers, unsigned int count);
int close_device(int fd);
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nSignal received, stopping streaming...\n");
    stop_flag = 1;
}

// Opens the specified video device
int open_device(const char *device_name) {
    int fd = open(device_name, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }
    return fd;
}

// Queries the device capabilities
int query_capabilities(int fd) {
    struct v4l2_capability cap;
    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming\n");
        return -1;
    }

    printf("Device capabilities: %s\n", cap.card);
    return 0;
}

// Sets the pixel format to V4L2_PIX_FMT_MJPEG
int set_pixel_format(int fd) {
    struct v4l2_format fmt;
    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_MJPEG;
    fmt.fmt.pix.field = V4L2_FIELD_NONE;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting pixel format");
        return -1;
    }

    printf("Pixel format set to MJPEG\n");
    return 0;
}

// Requests the specified number of buffers
int request_buffers(int fd, unsigned int count) {
    struct v4l2_requestbuffers req;
    memset(&req, 0, sizeof(req));
    req.count = count;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

    printf("Requested %d buffers\n", req.count);
    return 0;
}

// Maps the buffers to memory
int map_buffers(int fd, struct v4l2_buffer *buffers, unsigned int count) {
    for (unsigned int i = 0; i < count; ++i) {
        struct v4l2_buffer buf;
        memset(&buf, 0, sizeof(buf));
        buf.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buf.memory = V4L2_MEMORY_MMAP;
        buf.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buf) < 0) {
            perror("Error querying buffer");
            return -1;
        }

        buffers[i].length = buf.length;
        buffers[i].start = mmap(NULL, buf.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buf.m.offset);

        if (buffers[i].start == MAP_FAILED) {
            perror("Error mapping buffer");
            return -1;
        }

        printf("Mapped buffer %d at %p\n", i, buffers[i].start);
    }
    return 0;
}

// Starts streaming
int start_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting streaming");
        return -1;
    }

    printf("Streaming started\n");
    return 0;
}

// Dequeues a buffer
int dequeue_buffer(int fd, struct v4l2_buffer *buffer) {
    memset(buffer, 0, sizeof(*buffer));
    buffer->type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buffer->memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, buffer) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    printf("Dequeued buffer %d\n", buffer->index);
    return 0;
}

// Verifies the buffer's bytesused field
int verify_buffer(const struct v4l2_buffer *buffer) {
    if (buffer->bytesused == 0) {
        fprintf(stderr, "Buffer is empty\n");
        return -1;
    }
    return 0;
}

// Writes the raw MJPEG bytes directly to a file
int write_image(const unsigned char *data, size_t size) {
    FILE *fp = fopen("image.jpg", "wb");
    if (fp == NULL) {
        perror("Error opening image file");
        return -1;
    }

    size_t bytes_written = fwrite(data, 1, size, fp);
    if (bytes_written != size) {
        fprintf(stderr, "Error writing to image file\n");
        fclose(fp);
        return -1;
    }

    printf("Image written to image.jpg\n");
    fclose(fp);
    return 0;
}

// Stops streaming
int stop_streaming(int fd) {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping streaming");
        return -1;
    }

    printf("Streaming stopped\n");
    return 0;
}

// Unmaps the buffers
int unmap_buffers(int fd, struct v4l2_buffer *buffers, unsigned int count) {
    for (unsigned int i = 0; i < count; ++i) {
        if (munmap(buffers[i].start, buffers[i].length) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
        printf("Unmapped buffer %d\n", i);
    }
    return 0;
}

// Closes the device file descriptor
int close_device(int fd) {
    if (fd != -1) {
        if (close(fd) < 0) {
            perror("Error closing device");
            return -1;
        }
        printf("Device closed\n");
    }
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the device
    fd = open_device(DEVICE_NAME);
    if (fd < 0) {
        return EXIT_FAILURE;
    }

    // Query device capabilities
    if (query_capabilities(fd) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Set pixel format
    if (set_pixel_format(fd) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Request buffers
    if (request_buffers(fd, NUM_BUFFERS) < 0) {
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Map buffers
    buffers = calloc(NUM_BUFFERS, sizeof(*buffers));
    if (!buffers) {
        perror("Error allocating buffer array");
        close_device(fd);
        return EXIT_FAILURE;
    }

    if (map_buffers(fd, buffers, NUM_BUFFERS) < 0) {
        free(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Start streaming
    if (start_streaming(fd) < 0) {
        unmap_buffers(fd, buffers, NUM_BUFFERS);
        free(buffers);
        close_device(fd);
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        struct v4l2_buffer buffer;
        if (dequeue_buffer(fd, &buffer) < 0) {
            break; // Exit loop on error
        }

        if (verify_buffer(&buffer) < 0) {
            break; // Exit loop on error
        }

        if (write_image((const unsigned char *)buffers[buffer.index].start, buffer.bytesused) < 0) {
            break; // Exit loop on error
        }

        if (ioctl(fd, VIDIOC_QBUF, &buffer) < 0) {
            perror("Error queuing buffer");
            break; // Exit loop on error
        }
    }

    // Stop streaming
    if (stop_streaming(fd) < 0) {
        fprintf(stderr, "Error stopping streaming during cleanup\n");
    }

    // Unmap buffers
    if (unmap_buffers(fd, buffers, NUM_BUFFERS) < 0) {
        fprintf(stderr, "Error unmapping buffers during cleanup\n");
    }

    // Free buffer array
    free(buffers);

    // Close device
    if (close_device(fd) < 0) {
        fprintf(stderr, "Error closing device during cleanup\n");
    }

    return EXIT_SUCCESS;
}

