#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5

// Define GPIO pins for buttons
#define TILT_UP_BUTTON_PIN 6
#define TILT_DOWN_BUTTON_PIN 7
#define PAN_LEFT_BUTTON_PIN 8
#define PAN_RIGHT_BUTTON_PIN 9

// Define PWM frequency and range
#define PWM_FREQUENCY 50
#define PWM_RANGE 1000

// Define pan and tilt limits
#define PAN_MIN 25
#define PAN_MAX 125
#define TILT_MIN 25
#define TILT_MAX 125

// Global variables for pan and tilt positions
int pan_position = 75;
int tilt_position = 75;

// Function prototypes
int initialize_gpio();
int set_servo_position(int gpio_pin, int duty_cycle);
int adjust_servo_position(int gpio_pin, int direction);
int read_button(int gpio_pin);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    // Stop PWM on both servos
    set_servo_position(PAN_SERVO_PIN, 0);
    set_servo_position(TILT_SERVO_PIN, 0);

    // Release GPIO pins
    gpioTerminate();

    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(TILT_UP_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(TILT_DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(PAN_LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(PAN_LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(PAN_RIGHT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(PAN_RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency and range
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    return 0;
}

// Set servo position
int set_servo_position(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 1000) {
        fprintf(stderr, "Invalid duty cycle: %d\n", duty_cycle);
        return 1;
    }

    // Convert duty cycle to pulse width (500us to 2500us)
    int pulse_width = (int)((float)duty_cycle / 1000.0 * PWM_RANGE);

    // Set PWM pulse width
    gpioPWM(gpio_pin, pulse_width);

    return 0;
}

// Adjust servo position
int adjust_servo_position(int gpio_pin, int direction) {
    int new_position = pan_position + (direction * 5);

    // Clamp position to the range
    if (new_position < PAN_MIN) {
        new_position = PAN_MIN;
    } else if (new_position > PAN_MAX) {
        new_position = PAN_MAX;
    }

    pan_position = new_position;

    // Set servo position
    if (set_servo_position(gpio_pin, pan_position) != 0) {
        fprintf(stderr, "Failed to set servo position\n");
        return 1;
    }

    return 0;
}

// Read button state
int read_button(int gpio_pin) {
    return gpioRead(gpio_pin);
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Camera pan-tilt mount control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read button states
        int tilt_up_pressed = read_button(TILT_UP_BUTTON_PIN);
        int tilt_down_pressed = read_button(TILT_DOWN_BUTTON_PIN);
        int pan_left_pressed = read_button(PAN_LEFT_BUTTON_PIN);
        int pan_right_pressed = read_button(PAN_RIGHT_BUTTON_PIN);

        // Adjust servo positions based on button presses
        if (tilt_up_pressed) {
            if (adjust_servo_position(TILT_SERVO_PIN, 1) != 0) {
                fprintf(stderr, "Failed to adjust tilt up\n");
            }
        }
        if (tilt_down_pressed) {
            if (adjust_servo_position(TILT_SERVO_PIN, -1) != 0) {
                fprintf(stderr, "Failed to adjust tilt down\n");
            }
        }
        if (pan_left_pressed) {
            if (adjust_servo_position(PAN_SERVO_PIN, -1) != 0) {
                fprintf(stderr, "Failed to adjust pan left\n");
            }
        }
        if (pan_right_pressed) {
            if (adjust_servo_position(PAN_SERVO_PIN, 1) != 0) {
                fprintf(stderr, "Failed to adjust pan right\n");
            }
        }

        // Delay for 50ms
        gpioDelay(50000); // 50ms = 50000 microseconds
    }

    return 0;
}

