#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <jpeglib.h>

#define DEVICE_NAME "/dev/video0"
#define IMAGE_WIDTH 640
#define IMAGE_HEIGHT 480
#define BUFFER_COUNT 4
#define TIMEOUT_MS 2000

// Structure to hold buffer information
typedef struct {
    void   *start;
    size_t  length;
} buffer_t;

// Global variables
int fd = -1;
buffer_t *buffers = NULL;
int n_buffers = 0;
volatile sig_atomic_t stop_flag = 0;

// Function prototypes
int init_camera();
int request_buffers(buffer_t **buffers, int n_buffers);
int map_buffers(buffer_t *buffers, int n_buffers);
int start_streaming(buffer_t *buffers, int n_buffers);
int capture_frame(buffer_t *buffer);
int process_frame(unsigned char *yuyv_buffer, unsigned char *rgb_buffer, int width, int height);
int encode_jpeg(unsigned char *rgb_buffer, int width, int height, unsigned char **jpeg_buffer, unsigned long *jpeg_size);
int save_jpeg(unsigned char *jpeg_buffer, unsigned long jpeg_size, const char *filename);
void stop_streaming(buffer_t *buffers, int n_buffers);
void unmap_buffers(buffer_t *buffers, int n_buffers);
void free_buffers(buffer_t *buffers, int n_buffers);
void close_camera();
void signal_handler(int sig);

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", sig);
    stop_flag = 1;
}

// Initialize the camera
int init_camera() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        fprintf(stderr, "Error opening device %s: %s\n", DEVICE_NAME, strerror(errno));
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        fprintf(stderr, "Error querying capabilities: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device %s is not a video capture device\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device %s does not support streaming i/o\n", DEVICE_NAME);
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = IMAGE_WIDTH;
    fmt.fmt.pix.height = IMAGE_HEIGHT;
    fmt.fmt.pix.pixelformat = V4L2_PIX_FMT_YUYV;
    fmt.fmt.pix.field = V4L2_FIELD_INTERLACED;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        fprintf(stderr, "Error setting format: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        close(fd);
        return -1;
    }

    buffers = calloc(req.count, sizeof(*buffers));
    if (!buffers) {
        fprintf(stderr, "Out of memory\n");
        close(fd);
        return -1;
    }

    n_buffers = req.count;

    return 0;
}

// Request buffers from the camera
int request_buffers(buffer_t **buffers, int n_buffers) {
    struct v4l2_requestbuffers req;

    memset(&req, 0, sizeof(req));
    req.count = n_buffers;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        fprintf(stderr, "Error requesting buffers: %s\n", strerror(errno));
        return -1;
    }

    if (req.count < 2) {
        fprintf(stderr, "Insufficient buffer memory\n");
        return -1;
    }

