    if (start_streaming(buffers, n_buffers) < 0) {
        fprintf(stderr, "Streaming start failed\n");
        close_camera();
        return 1;
    }

    // Capture frame with timeout
    struct timeval start_time, current_time;
    gettimeofday(&start_time, NULL);

    while (!stop_flag) {
        fd_set fds;
        struct timeval tv;

        FD_ZERO(&fds);
        FD_SET(fd, &fds);

        tv.tv_sec = 0;
        tv.tv_usec = TIMEOUT_MS * 1000; // Convert milliseconds to microseconds

        int r = select(fd + 1, &fds, NULL, NULL, &tv);

        if (r == -1) {
            fprintf(stderr, "Error in select: %s\n", strerror(errno));
            break;
        } else if (r == 0) {
            fprintf(stderr, "Timeout waiting for frame\n");
            break;
        } else {
            if (capture_frame(buffers) < 0) {
                fprintf(stderr, "Frame capture failed\n");
                break;
            }

            // Process frame
            unsigned char *yuyv_buffer = buffers[0].start;
            unsigned char *rgb_buffer = malloc(IMAGE_WIDTH * IMAGE_HEIGHT * 3);
            if (!rgb_buffer) {
                fprintf(stderr, "Out of memory\n");
                break;
            }

            if (process_frame(yuyv_buffer, rgb_buffer, IMAGE_WIDTH, IMAGE_HEIGHT) < 0) {
                fprintf(stderr, "Frame processing failed\n");
                free(rgb_buffer);
                break;
            }

            // Encode to JPEG
            unsigned char *jpeg_buffer = NULL;
            unsigned long jpeg_size = 0;
            if (encode_jpeg(rgb_buffer, IMAGE_WIDTH, IMAGE_HEIGHT, &jpeg_buffer, &jpeg_size) < 0) {
                fprintf(stderr, "JPEG encoding failed\n");
                free(rgb_buffer);
                break;
            }

            // Save JPEG image
            time_t rawtime;
            struct tm *timeinfo;
            char filename[80];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(filename, sizeof(filename), "capture_%Y%m%d_%H%M%S.jpg", timeinfo);

            if (save_jpeg(jpeg_buffer, jpeg_size, filename) < 0) {
                fprintf(stderr, "JPEG saving failed\n");
            }

            free(rgb_buffer);
            free(jpeg_buffer);
        }
    }

    // Stop streaming and close camera
    stop_streaming(buffers, n_buffers);
    close_camera();

    return 0;
}

