#include <linux/videodev2.h>
#include <errno.h>

#define DEVICE_NODE "/dev/video0"

// Function to check if a file exists
int file_exists(const char *filename) {
    return access(filename, F_OK) == 0;
}

// Function to open a device node
int open_device(const char *device_node) {
    int fd = open(device_node, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device node");
        return -1;
    }
    return fd;
}

// Function to query device capabilities
int query_device_capabilities(int fd, struct v4l2_capability *cap) {
    if (ioctl(fd, VIDIOC_QUERYCAP, cap) < 0) {
        perror("Error querying device capabilities");
        return -1;
    }
    return 0;
}

// Function to enumerate frame sizes
int enum_frame_sizes(int fd, struct v4l2_frmsizeenum *fsize) {
    while (ioctl(fd, VIDIOC_ENUM_FRAMESIZES, fsize) == 0) {
        printf("  %dx%d\n", fsize->discrete.width, fsize->discrete.height);
        fsize++;
    }
    if (errno != EINVAL) {
        perror("Error enumerating frame sizes");
        return -1;
    }
    return 0;
}

// Function to enumerate frame intervals
int enum_frame_intervals(int fd, struct v4l2_frmivalenum *finterval) {
    while (ioctl(fd, VIDIOC_ENUM_FRAMEINTERVALS, finterval) == 0) {
        printf("    %d/%d\n", finterval->discrete.numerator, finterval->discrete.denominator);
        finterval++;
    }
    if (errno != EINVAL) {
        perror("Error enumerating frame intervals");
        return -1;
    }
    return 0;
}

// Function to query the V4L2_CID_FOCUS_AUTO control
int query_focus_control(int fd) {
    struct v4l2_control ctrl;
    ctrl.id = V4L2_CID_FOCUS_AUTO;
    if (ioctl(fd, VIDIOC_QUERYCTRL, &ctrl) < 0) {
        perror("Error querying focus control");
        return -1;
    }
    if (ctrl.flags & V4L2_CTRL_FLAG_DISABLED) {
        printf("  Focus control is disabled.\n");
    } else {
        printf("  Focus control is supported.\n");
    }
    return 0;
}

int main() {
    int fd;
    struct v4l2_capability cap;
    struct v4l2_frmsizeenum fsize;
    struct v4l2_frmivalenum finterval;

    // Check if the device node exists
    if (!file_exists(DEVICE_NODE)) {
        fprintf(stderr, "Error: Device node %s does not exist.\n", DEVICE_NODE);
        return 1;
    }

    // Open the device node
    fd = open_device(DEVICE_NODE);
    if (fd < 0) {
        return 1;
    }

    // Query device capabilities
    if (query_device_capabilities(fd, &cap) < 0) {
        close(fd);
        return 1;
    }

    printf("Device name: %s\n", cap.card);
    printf("Driver: %s\n", cap.driver);
    printf("Version: %d.%d.%d\n", (cap.version >> 16) & 0xFF, (cap.version >> 8) & 0xFF, cap.version & 0xFF);
    printf("Capabilities: 0x%08X\n", cap.capabilities);

    // Enumerate frame sizes
    printf("Supported frame sizes:\n");
    fsize = cap.frmsizeenum;
    if (enum_frame_sizes(fd, &fsize) < 0) {
        close(fd);
        return 1;
    }

    // Enumerate frame intervals
    printf("Supported frame intervals:\n");
    finterval = cap.frmivalenum;
    if (enum_frame_intervals(fd, &finterval) < 0) {
        close(fd);
        return 1;
    }

    // Query the V4L2_CID_FOCUS_AUTO control
    if (query_focus_control(fd) < 0) {
        close(fd);
        return 1;
    }

    // Close the device node
    close(fd);

    return 0;
}

