#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos and buttons
#define PAN_SERVO_PIN 4
#define TILT_SERVO_PIN 5
#define UP_BUTTON_PIN 6
#define DOWN_BUTTON_PIN 7
#define LEFT_BUTTON_PIN 8
#define RIGHT_BUTTON_PIN 9

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 1000
#define MAX_PULSE_WIDTH 2000

// Define center pulse width (microseconds)
#define CENTER_PULSE_WIDTH 1500

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set servo pins as output
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
    gpioSetMode(TILT_SERVO_PIN, PI_OUTPUT);

    // Set button pins as input with pull-up resistors
    gpioSetMode(UP_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(UP_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(DOWN_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(DOWN_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(LEFT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_BUTTON_PIN, PI_PUD_UP);
    gpioSetMode(RIGHT_BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency for servos
    gpioSetPWMfrequency(PAN_SERVO_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    return 0;
}

// Function to set the pulse width of a servo
void set_servo_pulse_width(int pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH) {
        pulse_width = MIN_PULSE_WIDTH;
    } else if (pulse_width > MAX_PULSE_WIDTH) {
        pulse_width = MAX_PULSE_WIDTH;
    }
    gpioPWM(pin, pulse_width);
}

// Function to move the pan servo
void move_pan(int direction) {
    static int current_pulse_width = CENTER_PULSE_WIDTH;
    static int increment = 10; // Adjust increment as needed

    if (direction == 1) { // Move right
        current_pulse_width += increment;
        if (current_pulse_width > MAX_PULSE_WIDTH) {
            current_pulse_width = MAX_PULSE_WIDTH;
            increment = -increment; // Reverse direction
        }
    } else if (direction == -1) { // Move left
        current_pulse_width -= increment;
        if (current_pulse_width < MIN_PULSE_WIDTH) {
            current_pulse_width = MIN_PULSE_WIDTH;
            increment = -increment; // Reverse direction
        }
    }
    set_servo_pulse_width(PAN_SERVO_PIN, current_pulse_width);
}

// Function to move the tilt servo
void move_tilt(int direction) {
    static int current_pulse_width = CENTER_PULSE_WIDTH;
    static int increment = 10; // Adjust increment as needed

    if (direction == 1) { // Move up
        current_pulse_width += increment;
        if (current_pulse_width > MAX_PULSE_WIDTH) {
            current_pulse_width = MAX_PULSE_WIDTH;
            increment = -increment; // Reverse direction
        }
    } else if (direction == -1) { // Move down
        current_pulse_width -= increment;
        if (current_pulse_width < MIN_PULSE_WIDTH) {
            current_pulse_width = MIN_PULSE_WIDTH;
            increment = -increment; // Reverse direction
        }
    }
    set_servo_pulse_width(TILT_SERVO_PIN, current_pulse_width);
}

// Function to handle button presses
void handle_button_press(int pin) {
    if (pin == UP_BUTTON_PIN) {
        move_tilt(1);
    } else if (pin == DOWN_BUTTON_PIN) {
        move_tilt(-1);
    } else if (pin == LEFT_BUTTON_PIN) {
        move_pan(-1);
    } else if (pin == RIGHT_BUTTON_PIN) {
        move_pan(1);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Camera pan-tilt mount control program started.\n");
    printf("Press Ctrl+C to exit.\n");
    printf("UP/DOWN: Move tilt\n");
    printf("LEFT/RIGHT: Move pan\n");

    // Main loop
    while (program_running) {
        // Check for button presses
        if (gpioRead(UP_BUTTON_PIN) == 0) {
            handle_button_press(UP_BUTTON_PIN);
            gpioDelay(50); // Debounce delay
        }
        if (gpioRead(DOWN_BUTTON_PIN) == 0) {
            handle_button_press(DOWN_BUTTON_PIN);
            gpioDelay(50); // Debounce delay
        }
        if (gpioRead(LEFT_BUTTON_PIN) == 0) {
            handle_button_press(LEFT_BUTTON_PIN);
            gpioDelay(50); // Debounce delay
        }
        if (gpioRead(RIGHT_BUTTON_PIN) == 0) {
            handle_button_press(RIGHT_BUTTON_PIN);
            gpioDelay(50); // Debounce delay
        }

        gpioDelay(50); // Delay to avoid excessive CPU usage
    }

    // Stop PWM on servos
    gpioPWM(PAN_SERVO_PIN, 0);
    gpioPWM(TILT_SERVO_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

