#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration
#define PIR_GPIO 17
#define DEBOUNCE_TIME 2 // seconds
#define IMAGE_DIR "motion_captures"
#define HTTP_ENDPOINT "http://<IP>:<PORT>/upload" // Replace with your server endpoint
#define LOG_FILE "motion_log.txt"

// Global variables
static volatile int running = 1;
static int http_socket = -1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
int capture_jpeg_snapshot(const char *filename);
int create_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin, json_t **payload);
int post_http_request(const char *payload);
void log_message(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Signal received, shutting down...");
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Read PIR sensor value with debouncing
int read_pir_sensor() {
    int value = gpioRead(PIR_GPIO);
    gpioDelay(DEBOUNCE_TIME * 1000000); // Debounce time in microseconds
    return value;
}

// Capture JPEG snapshot using raspistill
int capture_jpeg_snapshot(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s -q 85", filename);
    int status = system(command);
    if (status != 0) {
        fprintf(stderr, "Error capturing JPEG snapshot: %d\n", status);
        return -1;
    }
    return 0;
}

// Create JSON payload
int create_json_payload(const char *filename, const char *timestamp, int motion_status, int gpio_pin, json_t **payload) {
    json_error_t error;
    *payload = json_object();
    if (!*payload) {
        fprintf(stderr, "Error creating JSON object\n");
        return -1;
    }

    json_object_set_new(*payload, "filename", json_string(filename));
    json_object_set_new(*payload, "timestamp", json_string(timestamp));
    json_object_set_new(*payload, "motion_status", json_integer(motion_status));
    json_object_set_new(*payload, "gpio_pin", json_integer(gpio_pin));

    return 0;
}

// Post HTTP request using libcurl
int post_http_request(const char *payload) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(80); // Default HTTP port

