#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define GPIO_PIN 17
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define DEBOUNCE_DELAY_MS 50
#define IMAGE_DIR "/home/pi/images/"
#define LOG_FILE "/home/pi/motion_capture.log"
#define SERVER_IP "192.168.1.100"
#define SERVER_PORT 5000
#define MAX_RETRIES 3

// Global variables
static volatile int running = 1;
static int spi_fd = -1;
static int udp_socket = -1;

// Function prototypes
int read_mcp3008(int channel);
int capture_image(const char *filename);
int log_message(const char *message);
int send_image_udp(const char *filename);
void signal_handler(int signal);
int initialize_gpio();
int initialize_spi();
int initialize_udp();
void cleanup();

// Function to read from MCP3008 ADC
int read_mcp3008(int channel) {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    if (write(spi_fd, tx_buf, 3) != 3) {
        log_message("Error writing to SPI device");
        return -1;
    }

    if (read(spi_fd, rx_buf, 3) != 3) {
        log_message("Error reading from SPI device");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to capture image using raspistill
int capture_image(const char *filename) {
    char command[256];
    snprintf(command, sizeof(command), "raspistill -o %s --width 640 --height 480 --q 85 --timeout 2000 --nopreview", filename);

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int status = system(command);
        if (status == 0) {
            return 0; // Success
        } else {
            char error_message[256];
            snprintf(error_message, sizeof(error_message), "Error capturing image: %s (status %d, retry %d/%d)", strerror(errno), status, retries + 1, MAX_RETRIES);
            log_message(error_message);
            retries++;
            sleep(1); // Wait before retrying
        }
    }

    log_message("Failed to capture image after multiple retries.");
    return -1; // Failure
}

// Function to log messages to file
int log_message(const char *message) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// Function to send image via UDP
int send_image_udp(const char *filename) {
    struct sockaddr_in server_addr;
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(SERVER_PORT);
    if (inet_pton(AF_INET, SERVER_IP, &server_addr.sin_addr) <= 0) {
        log_message("Invalid server IP address");
        return -1;
    }

    int retries = 0;
    while (retries < MAX_RETRIES) {
        int sockfd = socket(AF_INET, SOCK_DGRAM, 0);
        if (sockfd < 0) {
            log_message("Error creating socket");
            retries++;
            sleep(1);
            continue;
        }

        // Send image data
        FILE *fp = fopen(filename, "rb");
        if (fp == NULL) {
            log_message("Error opening image file for sending");
            close(sockfd);
            retries++;
            sleep(1);
            continue;
        }

        fseek(fp, 0, SEEK_END);
        long file_size = ftell(fp);
        fseek(fp, 0, SEEK_SET);

        char buffer[4096];
        ssize_t bytes_sent = 0;
        while (bytes_sent < file_size && retries < MAX_RETRIES) {
            ssize_t bytes_to_send = (file_size - bytes_sent > 4096) ? 4096 : (file_size - bytes_sent);
            if (fread(buffer, 1, bytes_to_send, fp) != bytes_to_send) {
                log_message("Error reading from image file");
                fclose(fp);
                close(sockfd);
                retries++;
                sleep(1);
                break;
            }

            if (sendto(sockfd, buffer, bytes_to_send, 0, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
                log_message("Error sending data");
                fclose(fp);
                close(sockfd);
                retries++;
                sleep(1);
                break;
            }

            bytes_sent += bytes_to_send;
        }

        fclose(fp);
        close(sockfd);

        if (retries < MAX_RETRIES) {
            return 0; // Success
        } else {
            log_message("Failed to send image after multiple retries.");
            return -1; // Failure
        }
    }

    return -1; // Failure after all retries
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_message("Signal received, shutting down...");
}

// Initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message("pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor
    return 0;
}

// Initialize SPI
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        log_message("Error opening SPI device");
        return -1;
    }

    // Set SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        log_message("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        log_message("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Set max speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        log_message("Error setting max speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Initialize UDP socket
int initialize_udp() {
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        log_message("Error creating socket");
        return -1;
    }

    // Set time-to-live (optional)
    int ttl = 1;
    if (setsockopt(udp_socket, IPPROTO_IP, IP_MULTICAST_TTL, (void *)&ttl, sizeof(ttl)) < 0) {
        log_message("Error setting TTL");
        close(udp_socket);
        return -1;
    }

    return 0;
}

// Cleanup resources
void cleanup() {
    log_message("Cleaning up resources...");

    if (spi_fd != -1) {
        close(spi_fd);
    }

    if (udp_socket != -1) {
        close(udp_socket);
    }

    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize resources
    if (initialize_gpio() != 0) {
        return 1;
    }

    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    if (initialize_udp() != 0) {
        cleanup();
        return 1;
    }

    log_message("Motion detection system started");

    // Main loop
    while (running) {
        // Read sensor value
        int sensor_value = read_mcp3008(0); // Channel 0
        if (sensor_value < 0) {
            log_message("Error reading sensor value");
            continue; // Skip to the next iteration
        }

        // Check for motion (LOW signal)
        if (sensor_value == 0) {
            log_message("Motion detected!");

            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // pigpioDelay takes microseconds

            // Re-read sensor value after debounce
            int debounced_value = read_mcp3008(0);
            if (debounced_value < 0) {
                log_message("Error reading debounced sensor value");
                continue; // Skip to the next iteration
            }

            // Verify motion still detected after debounce
            if (debounced_value == 0) {
                // Generate timestamped filename
                time_t t = time(NULL);
                struct tm tm = *localtime(&t);
                char filename[256];
                snprintf(filename, sizeof(filename), "%s%d%02d%02d_%02d%02d%02d_mmm.jpg", IMAGE_DIR, tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec);

                // Capture image
                if (capture_image(filename) == 0) {
                    log_message("Image captured successfully");

                    // Send image via UDP
                    if (send_image_udp(filename) == 0) {
                        log_message("Image sent via UDP successfully");
                    } else {
                        log_message("Failed to send image via UDP");
                    }
                } else {
                    log_message("Failed to capture image");
                }
            }
        }

        gpioDelay(10000); // Check every 10ms
    }

    // Cleanup and exit
    cleanup();
    log_message("Motion detection system stopped");
    return 0;
}

