#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <sys/mman.h>
#include <linux/videodev2.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

#define DEVICE_NAME "/dev/video0"
#define WIDTH 640
#define HEIGHT 480
#define PIXEL_FORMAT V4L2_PIX_FMT_YUYV
#define FIELD V4L2_FIELD_NONE
#define BUFFER_COUNT 4
#define TIMEOUT_MS 2000

static int fd = -1;
static struct v4l2_buffer buffer;
static unsigned char *buffer_start = NULL;
static FILE *output_file = NULL;
static volatile sig_atomic_t stop_flag = 0;

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, stopping...\n");
    stop_flag = 1;
}

// Function to initialize the V4L2 device
int init_device() {
    struct v4l2_capability cap;
    struct v4l2_format fmt;
    struct v4l2_requestbuffers req;

    fd = open(DEVICE_NAME, O_RDWR | O_NONBLOCK, 0);
    if (fd < 0) {
        perror("Error opening device");
        return -1;
    }

    if (ioctl(fd, VIDIOC_QUERYCAP, &cap) < 0) {
        perror("Error querying capabilities");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_VIDEO_CAPTURE)) {
        fprintf(stderr, "Device does not support video capture\n");
        close(fd);
        return -1;
    }

    if (!(cap.capabilities & V4L2_CAP_STREAMING)) {
        fprintf(stderr, "Device does not support streaming I/O\n");
        close(fd);
        return -1;
    }

    memset(&fmt, 0, sizeof(fmt));
    fmt.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    fmt.fmt.pix.width = WIDTH;
    fmt.fmt.pix.height = HEIGHT;
    fmt.fmt.pix.pixelformat = PIXEL_FORMAT;
    fmt.fmt.pix.field = FIELD;

    if (ioctl(fd, VIDIOC_S_FMT, &fmt) < 0) {
        perror("Error setting format");
        close(fd);
        return -1;
    }

    memset(&req, 0, sizeof(req));
    req.count = BUFFER_COUNT;
    req.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    req.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_REQBUFS, &req) < 0) {
        perror("Error requesting buffers");
        close(fd);
        return -1;
    }

    for (int i = 0; i < req.count; ++i) {
        memset(&buffer, 0, sizeof(buffer));
        buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
        buffer.memory = V4L2_MEMORY_MMAP;
        buffer.index = i;

        if (ioctl(fd, VIDIOC_QUERYBUF, &buffer) < 0) {
            perror("Error querying buffer");
            close(fd);
            return -1;
        }

        buffer_start = mmap(NULL, buffer.length, PROT_READ | PROT_WRITE, MAP_SHARED, fd, buffer.m.offset);
        if (buffer_start == MAP_FAILED) {
            perror("Error mapping buffer");
            close(fd);
            return -1;
        }

        if (ioctl(fd, VIDIOC_QBUF, &buffer) < 0) {
            perror("Error queuing buffer");
            close(fd);
            return -1;
        }
    }

    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMON, &type) < 0) {
        perror("Error starting stream");
        close(fd);
        return -1;
    }

    return 0;
}

// Function to capture a frame
int capture_frame() {
    fd_set fds;
    struct timeval tv;
    int r;

    FD_ZERO(&fds);
    FD_SET(fd, &fds);

    tv.tv_sec = TIMEOUT_MS / 1000;
    tv.tv_usec = (TIMEOUT_MS % 1000) * 1000;

    r = select(fd + 1, &fds, NULL, NULL, &tv);

    if (r == -1) {
        perror("select() error");
        return -1;
    } else if (r == 0) {
        fprintf(stderr, "Timeout occurred\n");
        return -1;
    }

    memset(&buffer, 0, sizeof(buffer));
    buffer.type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    buffer.memory = V4L2_MEMORY_MMAP;

    if (ioctl(fd, VIDIOC_DQBUF, &buffer) < 0) {
        perror("Error dequeuing buffer");
        return -1;
    }

    return 0;
}

// Function to process the YUYV frame
int process_frame(unsigned char *frame_start, int width, int height) {
    unsigned char *cropped_frame = malloc(width * height * 2);
    if (cropped_frame == NULL) {
        perror("Error allocating memory for cropped frame");
        return -1;
    }

    // Crop the frame to 200x150
    for (int i = 0; i < height; ++i) {
        for (int j = 0; j < width; ++j) {
            // YUYV format: Y0 U Y1 V
            int index = i * width + j;
            int cropped_index = (i / 2) * 200 + (j / 2) * 2; // Assuming 200x150 is a multiple of 2

            cropped_frame[cropped_index] = frame_start[index * 2]; // Y0
            cropped_frame[cropped_index + 1] = frame_start[index * 2 + 1]; // U
            cropped_frame[cropped_index + 2] = frame_start[index * 2 + 2]; // Y1
            cropped_frame[cropped_index + 3] = frame_start[index * 2 + 3]; // V
        }
    }

    // Write the cropped frame to the output file
    if (fwrite(cropped_frame, 1, width * height * 2, output_file) != width * height * 2) {
        perror("Error writing to file");
        free(cropped_frame);
        return -1;
    }

    free(cropped_frame);
    return 0;
}

// Function to stop the V4L2 device
int stop_device() {
    enum v4l2_buf_type type = V4L2_BUF_TYPE_VIDEO_CAPTURE;
    if (ioctl(fd, VIDIOC_STREAMOFF, &type) < 0) {
        perror("Error stopping stream");
        return -1;
    }

    for (int i = 0; i < BUFFER_COUNT; ++i) {
        if (munmap(buffer_start, buffer.length) < 0) {
            perror("Error unmapping buffer");
            return -1;
        }
    }

    if (close(fd) < 0) {
        perror("Error closing device");
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the device
    if (init_device() < 0) {
        fprintf(stderr, "Device initialization failed\n");
        return EXIT_FAILURE;
    }

    // Open the output file
    output_file = fopen("cropped.yuv", "wb");
    if (output_file == NULL) {
        perror("Error opening output file");
        stop_device();
        return EXIT_FAILURE;
    }

    // Main loop
    while (!stop_flag) {
        // Capture a frame
        if (capture_frame() < 0) {
            fprintf(stderr, "Frame capture failed\n");
            break;
        }

        // Process the frame
        if (process_frame(buffer_start, WIDTH, HEIGHT) < 0) {
            fprintf(stderr, "Frame processing failed\n");
            break;
        }

        // Requeue the buffer
        if (ioctl(fd, VIDIOC_QBUF, &buffer) < 0) {
            perror("Error requeuing buffer");
            break;
        }
    }

    // Stop the device
    if (stop_device() < 0) {
        fprintf(stderr, "Device stop failed\n");
    }

    // Close the output file
    if (output_file != NULL) {
        fclose(output_file);
    }

    return EXIT_SUCCESS;
}

