#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define PAN_SERVO_PIN 17
#define TILT_SERVO_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 50

// Define PWM range
#define PWM_RANGE 2000

// Define angle limits for servos
#define MIN_ANGLE 0
#define MAX_ANGLE 180

// Define neutral position for servos
#define NEUTRAL_ANGLE 90

// Define delay between commands
#define DELAY_MS 100

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the angle of a servo motor
int set_servo_angle(int gpio_pin, int angle) {
    if (angle < MIN_ANGLE || angle > MAX_ANGLE) {
        fprintf(stderr, "Error: Angle out of range (%d). Angle must be between %d and %d.\n", angle, MIN_ANGLE, MAX_ANGLE);
        return -1;
    }

    // Calculate pulse width (500us - 2500us for 0-180 degrees)
    int pulse_width = 500 + (int)((float)(angle / 180.0) * (PWM_RANGE - 1000));

    // Set PWM duty cycle for the specified GPIO pin
    gpioPWM(gpio_pin, pulse_width);

    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(PAN_SERVO_PIN, PI_OUTPUT);
