    gpioSetPWMfrequency(TILT_SERVO_PIN, PWM_FREQUENCY);

    // Set PWM range for both servos
    gpioSetPWMrange(PAN_SERVO_PIN, PWM_RANGE);
    gpioSetPWMrange(TILT_SERVO_PIN, PWM_RANGE);

    // Set initial servo positions to neutral
    if (set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
        gpioTerminate();
        return 1;
    }
    if (set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
        gpioTerminate();
        return 1;
    }

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop
    char input;
    while (program_running) {
        // Read input from stdin
        input = getchar();

        // Process input
        switch (input) {
            case 'a': // Left arrow key
                if (set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE - 5) != 0) {
                    fprintf(stderr, "Error setting pan servo angle.\n");
                }
                if (set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE) != 0) {
