                if (set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE + 5) != 0) {
                    fprintf(stderr, "Error setting tilt servo angle.\n");
                }
                break;
            case 'q': // 'q' key
                printf("Exiting program.\n");
                // Set both servos to neutral position
                set_servo_angle(PAN_SERVO_PIN, NEUTRAL_ANGLE);
                set_servo_angle(TILT_SERVO_PIN, NEUTRAL_ANGLE);

