// Function to read CPU temperature from file
float read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;

    fp = fopen(CPU_TEMP_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CPU temperature file: %s\n", CPU_TEMP_FILE);
        return -1.0;
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        fprintf(stderr, "Error reading CPU temperature from file: %s\n", CPU_TEMP_FILE);
        fclose(fp);
        return -1.0;
    }

    fclose(fp);
    return (float)temp_milli_celsius / 1000.0;
}

// Function to calculate CPU usage percentage
float calculate_cpu_usage(const char *stat_file) {
    FILE *fp;
    unsigned long prev_user, prev_nice, prev_system, prev_idle, prev_iowait, prev_irq, prev_softirq, prev_steal, prev_guest, prev_guest_nice;
    unsigned long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;
    unsigned long prev_total, total;
    float usage;

    fp = fopen(stat_file, "r");
    if (fp == NULL) {
        fprintf(stderr, "Error opening stat file: %s\n", stat_file);
        return -1.0;
    }

    if (fscanf(fp, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &prev_user, &prev_nice, &prev_system, &prev_idle, &prev_iowait, &prev_irq, &prev_softirq, &prev_steal, &prev_guest, &prev_guest_nice) != 10) {
        fprintf(stderr, "Error reading CPU stats from file: %s\n", stat_file);
        fclose(fp);
        return -1.0;
    }

    if (fscanf(fp, "cpu  %lu %lu %lu %lu %lu %lu %lu %lu %lu %lu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal, &guest, &guest_nice) != 10) {
        fprintf(stderr, "Error reading CPU stats from file: %s\n", stat_file);
        fclose(fp);
        return -1.0;
    }

    fclose(fp);

    prev_total = prev_user + prev_nice + prev_system + prev_idle + prev_iowait + prev_irq + prev_softirq + prev_steal + prev_guest + prev_guest_nice;
    total = user + nice + system + idle + iowait + irq + softirq + steal + guest + guest_nice;

    usage = 100.0 - ((float)(idle + iowait) / total) * 100.0;
    return usage;
}

// Function to render text on the OLED display
void render_text(int x, int y, const char *text) {
    int i, j;
    unsigned char c;

    for (i = 0; text[i] != '\0'; i++) {
        c = text[i] - ' ';
        if (c < 0 || c > 95) continue; // Check if character is valid

        for (j = 0; j < FONT_HEIGHT; j++) {
            oled_send_command(0xB0 + y + j); // Set page address
            oled_send_command(0x00 + (x & 0x0F)); // Set lower column address
            oled_send_command(0x10 + ((x >> 4) & 0x0F)); // Set higher column address

            for (int k = 0; k < FONT_WIDTH; k++) {
                oled_send_data(font[c][j] >> (7 - k) & 0x01);
            }
        }
    }
}

// Function to initialize the OLED display
void oled_init() {
    i2c_write_byte(i2c_handle, 0x00, 0xAE); // Display off
    i2c_write_byte(i2c_handle, 0x00, 0xD5); // Set display clock divide ratio/oscillator frequency
    i2c_write_byte(i2c_handle, 0x00, 0x80); // --ratio
    i2c_write_byte(i2c_handle, 0x00, 0xA8); // Set multiplex ratio
    i2c_write_byte(i2c_handle, 0x00, 0x3F); // --ratio
    i2c_write_byte(i2c_handle, 0x00, 0xD3); // Set display offset
    i2c_write_byte(i2c_handle, 0x00, 0x00); // --offset
    i2c_write_byte(i2c_handle, 0x00, 0x40); // Set start line address
    i2c_write_byte(i2c_handle, 0x00, 0x8D); // Charge pump setting
    i2c_write_byte(i2c_handle, 0x00, 0x14); // --enable
    i2c_write_byte(i2c_handle, 0x00, 0x20); // Set memory addressing mode
    i2c_write_byte(i2c_handle, 0x00, 0x00); // --horizontal addressing mode
    i2c_write_byte(i2c_handle, 0x00, 0xA1); // Set segment re-map
    i2c_write_byte(i2c_handle, 0x00, 0xC8); // Set COM output scan direction
    i2c_write_byte(i2c_handle, 0x00, 0xDA); // Set COM pins hardware configuration
    i2c_write_byte(i2c_handle, 0x00, 0x12); // --alternative
    i2c_write_byte(i2c_handle, 0x00, 0x81); // Set contrast control
    i2c_write_byte(i2c_handle, 0x00, 0xCF); // --contrast
    i2c_write_byte(i2c_handle, 0x00, 0xD9); // Set pre-charge period
    i2c_write_byte(i2c_handle, 0x00, 0xF1); // --period
    i2c_write_byte(i2c_handle, 0x00, 0xDB); // Set VCOMH deselect level
    i2c_write_byte(i2c_handle, 0x00, 0x40); // --level
    i2c_write_byte(i2c_handle, 0x00, 0xA4); // Entire display ON/OFF
    i2c_write_byte(i2c_handle, 0x00, 0xA6); // Set normal/inverse display
    i2c_write_byte(i2c_handle, 0x00, 0xAF); // Display on
}

// Function to clear the OLED display
void oled_clear() {
    for (int i = 0; i < (OLED_WIDTH / 8) * OLED_HEIGHT; i++) {
        oled_send_command(0xB0 + (i / (OLED_WIDTH / 8))); // Set page address
        oled_send_command(0x00 + (i % (OLED_WIDTH / 8))); // Set lower column address
        oled_send_command(0x10 + ((i % (OLED_WIDTH / 8)) >> 4)); // Set higher column address
        oled_send_data(0x00); // Clear the pixel
    }
}

// Function to send a command to the OLED display
void oled_send_command(unsigned char command) {
    char buf[2];
    buf[0] = 0x00; // Control byte: command
    buf[1] = command;
    i2c_write_device(i2c_handle, buf, 2);
}

// Function to send data to the OLED display
void oled_send_data(unsigned char data) {
    char buf[2];
    buf[0] = 0x40; // Control byte: data
    buf[1] = data;
    i2c_write_device(i2c_handle, buf, 2);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    float cpu_temp, cpu_usage;
    char temp_str[20], usage_str[20];
    time_t current_time;
    struct tm *time_info;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, 0x3C, 0); // Bus 1, address 0x3C, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize OLED display
    oled_init();

    // Set up signal handler for Ctrl+C
