// LCD functions (simplified, using wiringPiI2C functions directly)
void lcd_init() {
    lcd_fd = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (lcd_fd == -1) {
        fprintf(stderr, "Error initializing LCD: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialization sequence (simplified)
    delay(50); // Wait for LCD to power up
    wiringPiI2CWriteReg8(lcd_fd, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS, 0);
    delay(5);
    wiringPiI2CWriteReg8(lcd_fd, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS, 0);
    delay(1);
    wiringPiI2CWriteReg8(lcd_fd, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS, 0);
    delay(1);
    wiringPiI2CWriteReg8(lcd_fd, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS);
    delay(1);

    wiringPiI2CWriteReg8(lcd_fd, LCD_DISPLAYCONTROL | LCD_DISPLAYON | LCD_CURSOROFF | LCD_BLINKOFF, 0);
    wiringPiI2CWriteReg8(lcd_fd, LCD_ENTRYMODESET | LCD_ENTRYLEFT | LCD_ENTRYSHIFTDECREMENT, 0);
    wiringPiI2CWriteReg8(lcd_fd, LCD_CLEARDISPLAY, 0);
}

void lcd_clear() {
    wiringPiI2CWriteReg8(lcd_fd, LCD_CLEARDISPLAY, 0);
    delay(2); // Clear display command takes 2ms
}

void lcd_set_cursor(int row, int col) {
    int addr = LCD_SETDDRAMADDR | (row * 0x40 + col);
    wiringPiI2CWriteReg8(lcd_fd, addr, 0);
}

void lcd_print(const char *str) {
    for (int i = 0; str[i] != '\0'; i++) {
        wiringPiI2CWriteReg8(lcd_fd, LCD_SETDDRAMADDR | i, str[i]);
    }
}

// Setup GPIO pins
void setup_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    pinMode(FLOW_SENSOR_PIN, INPUT);
    pullUpDnControl(FLOW_SENSOR_PIN, PUD_UP); // Enable pull-up resistor
}

// Setup LCD
void setup_lcd() {
    lcd_init();
    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print("Flow Rate:");
    lcd_set_cursor(1, 0);
    lcd_print("Total Vol:");
}

// Pulse counter function
void pulse_counter() {
    unsigned long current_time = millis();
    if (digitalRead(FLOW_SENSOR_PIN) == LOW) {
        if (last_pulse_time == 0) {
            last_pulse_time = current_time;
        } else {
            pulse_count++;
            total_volume += 1000; // Assuming 1ml flow rate (adjust as needed)
            last_pulse_time = current_time;
        }
    }
}

// Calculate flow rate
float calculate_flow_rate() {
    unsigned long current_time = millis();
    unsigned long time_diff = current_time - last_pulse_time;
    if (time_diff == 0) {
        return 0.0; // Avoid division by zero
    }
    return (float)pulse_count / (time_diff / 1000.0); // ml/min
}

// Display flow rate on LCD
void display_flow_rate(float flow_rate) {
    char flow_rate_str[16];
    snprintf(flow_rate_str, sizeof(flow_rate_str), "Flow Rate: %.2f ml/min", flow_rate);
    lcd_set_cursor(0, 10);
    lcd_print(flow_rate_str);
}

// Display total volume on LCD
void display_total_volume(unsigned long total_volume) {
    char total_volume_str[16];
    snprintf(total_volume_str, sizeof(total_volume_str), "Total Vol: %lu ml", total_volume);
    lcd_set_cursor(1, 10);
    lcd_print(total_volume_str);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    setup_gpio();

    // Setup LCD
    setup_lcd();

    printf("Water flow sensor and LCD program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
