    if (lcd_fd == -1) {
        fprintf(stderr, "Error initializing LCD: %s\n", strerror(errno));
        exit(EXIT_FAILURE);
    }

    // Initialization sequence (simplified)
    delay(50); // Wait for LCD to power up
    wiringPiI2CWriteReg8(lcd_fd, LCD_FUNCTIONSET | LCD_4BITMODE | LCD_2LINE | LCD_5x8DOTS, 0);
    delay(5);
