    unsigned long current_time = millis();
    if (digitalRead(FLOW_SENSOR_PIN) == LOW) {
        if (last_pulse_time == 0) {
            last_pulse_time = current_time;
        } else {
            pulse_count++;
            total_volume += 1000; // Assuming 1ml flow rate (adjust as needed)
            last_pulse_time = current_time;
        }
    }
}

// Calculate flow rate
float calculate_flow_rate() {
    unsigned long current_time = millis();
    unsigned long time_diff = current_time - last_pulse_time;
