#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>
#include <wiringPi.h>
#include <wiringPiSPI.h>

// Configuration
#define ANEMOMETER_GPIO 17
#define LCD_I2C_ADDR 0x27
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define SAMPLE_WINDOW_MS 500
#define LCD_WIDTH 16
#define LCD_HEIGHT 2

// Global variables
volatile int pulse_count = 0;
volatile unsigned long last_interrupt_time = 0;
int spi_handle;
int i2c_handle;

// Function prototypes
void anemometer_interrupt_handler(int gpio, int level, unsigned int tick);
float calculate_wind_speed(int pulse_count, int sample_window_ms);
int read_wind_direction(int spi_handle);
void lcd_init(int i2c_handle);
void lcd_clear(int i2c_handle);
void lcd_set_cursor(int i2c_handle, int row, int col);
void lcd_print(int i2c_handle, const char *text);
void signal_handler(int signal);

// Anemometer interrupt handler
void anemometer_interrupt_handler(int gpio, int level, unsigned int tick) {
    if (level == PI_HIGH) {
        unsigned long current_time = gpioTick();
        if (current_time - last_interrupt_time > 1000) { // Debounce
            pulse_count++;
            last_interrupt_time = current_time;
        }
    }
}

// Calculate wind speed
float calculate_wind_speed(int pulse_count, int sample_window_ms) {
    float pulses_per_second = (float)pulse_count / (float)sample_window_ms * 1000.0;
    float wind_speed = pulses_per_second * 0.244; // m/s
    return wind_speed;
}

// Read wind direction from MCP3008 ADC
int read_wind_direction(int spi_handle) {
    unsigned char buffer[3];
    int adc_value;

    buffer[0] = 0x01; // Start bit
    buffer[1] = 0x80; // Single-ended mode, channel 0
    buffer[2] = 0x00;

    if (wiringPiSPIDataRW(SPI_CHANNEL, buffer, 3) == -1) {
        fprintf(stderr, "Error: SPI data read/write failed.\n");
        return -1; // Indicate error
    }

    adc_value = ((buffer[1] & 0x03) << 8) + buffer[2];

    // Basic sanity check
    if (adc_value < 0 || adc_value > 1023) {
        fprintf(stderr, "Error: ADC value out of range: %d\n", adc_value);
        return -1; // Indicate error
    }

    // Map ADC value to wind direction (0-360 degrees)
    float angle = (float)adc_value / 1023.0 * 360.0;

    return (int)angle;
}

// LCD initialization function
void lcd_init(int i2c_handle) {
    // Initialization sequence (simplified)
    delay(50); // Wait for LCD to power up
    lcd_send_command(i2c_handle, 0x33); // Initialize
    delay(5);
    lcd_send_command(i2c_handle, 0x32); // Initialize
    delay(1);
    lcd_send_command(i2c_handle, 0x28); // 4-bit mode, 2 lines, 5x8 font
    delay(1);
    lcd_send_command(i2c_handle, 0x0C); // Display on, cursor off, blink off
    delay(1);
    lcd_send_command(i2c_handle, 0x06); // Increment cursor, no shift
    delay(1);
    lcd_clear(i2c_handle);
}

// LCD clear function
void lcd_clear(int i2c_handle) {
    lcd_send_command(i2c_handle, 0x01); // Clear display
    delay(2);
}

// LCD set cursor function
void lcd_set_cursor(int i2c_handle, int row, int col) {
    int address = 0x00 + (row * 0x40 + col);
    lcd_send_command(i2c_handle, 0x80 | address);
}

// LCD print function
void lcd_print(int i2c_handle, const char *text) {
    for (int i = 0; text[i] != '\0'; i++) {
        lcd_send_data(i2c_handle, text[i]);
    }
}

// LCD send command function
void lcd_send_command(int i2c_handle, unsigned char command) {
    unsigned char data_u, data_l;
    data_u = command & 0xF0;
    data_l = (command << 4) & 0xF0;

    wiringPiI2CWriteReg8(i2c_handle, 0x00, data_u);
    wiringPiI2CWriteReg8(i2c_handle, 0x00, data_l);
}

// LCD send data function
void lcd_send_data(int i2c_handle, unsigned char data) {
    unsigned char data_u, data_l;
    data_u = (data & 0xF0) | 0x01; // Enable bit
    data_l = ((data << 4) & 0xF0) | 0x01; // Enable bit

    wiringPiI2CWriteReg8(i2c_handle, 0x00, data_u);
    wiringPiI2CWriteReg8(i2c_handle, 0x00, data_l);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    lcd_clear(i2c_handle);
    lcd_print(i2c_handle, "Exiting...");
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error: wiringPi initialisation failed.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize SPI
    spi_handle = wiringPiSPISetup(SPI_CHANNEL, SPI_SPEED);
    if (spi_handle == -1) {
        fprintf(stderr, "Error: SPI initialisation failed.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    i2c_handle = wiringPiI2CSetup(LCD_I2C_ADDR);
    if (i2c_handle == -1) {
        fprintf(stderr, "Error: I2C initialisation failed.\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LCD
    lcd_init(i2c_handle);

    // Set up anemometer interrupt
    gpioSetMode(ANEMOMETER_GPIO, PI_INPUT);
    gpioSetPullUpDown(ANEMOMETER_GPIO, PI_PUD_UP); // Enable pull-up resistor
    gpioSetAlertFunc(ANEMOMETER_GPIO, anemometer_interrupt_handler);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Wind sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read wind direction
        int wind_direction = read_wind_direction(spi_handle);
        if (wind_direction == -1) {
            fprintf(stderr, "Error: Failed to read wind direction.\n");
            lcd_clear(i2c_handle);
            lcd_print(i2c_handle, "Error: Wind Dir");
            delay(1000);
            continue;
        }

        // Calculate wind speed
        float wind_speed = calculate_wind_speed(pulse_count, SAMPLE_WINDOW_MS);

        // Format data for LCD
        char wind_speed_str[16];
        char wind_direction_str[16];
        snprintf(wind_speed_str, sizeof(wind_speed_str), "Speed: %.2f m/s", wind_speed);
        snprintf(wind_direction_str, sizeof(wind_direction_str), "Dir: %d deg", wind_direction);

        // Clear LCD
        lcd_clear(i2c_handle);

        // Print data on LCD
        lcd_set_cursor(i2c_handle, 0, 0);
        lcd_print(i2c_handle, wind_speed_str);
        lcd_set_cursor(i2c_handle, 1, 0);
        lcd_print(i2c_handle, wind_direction_str);

        // Reset pulse count
        pulse_count = 0;

        // Wait for 500ms
        delay(SAMPLE_WINDOW_MS);
    }

    return 0;
}

