#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define GPIO_PIN 17
#define LCD_ADDR 0x27
#define LCD_WIDTH 16
#define LCD_HEIGHT 2
#define PULSES_PER_LITER 450.0
#define ZERO_PULSES_THRESHOLD 1000 // Number of pulses to consider as zero
#define ZERO_PULSES_TIMEOUT 5      // Timeout in seconds for zero pulses

// Global variables
volatile int pulse_count = 0;
volatile int zero_pulse_count = 0;
volatile int zero_pulse_start_time = 0;
volatile int lcd_initialized = 0;
int i2c_handle;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick);
float calculate_flow_rate(int pulse_count);
void display_flow_rate(float flow_rate);
void lcd_init();
void lcd_send_command(unsigned char command);
void lcd_send_data(unsigned char data);
void lcd_clear();
void lcd_set_cursor(int row, int col);
void lcd_print(const char *str);
void signal_handler(int signal);

// Pulse callback function
void pulse_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        pulse_count++;
        zero_pulse_count = 0; // Reset zero pulse counter on rising edge
    } else if (level == 0) { // Falling edge
        zero_pulse_count++;
        if (zero_pulse_count > ZERO_PULSES_THRESHOLD) {
            zero_pulse_start_time = tick; // Record start time of zero pulses
        }
    }
}

// Function to calculate flow rate in liters per minute
float calculate_flow_rate(int pulse_count) {
    return (float)pulse_count / PULSES_PER_LITER * 60.0;
}

// Function to display flow rate on LCD
void display_flow_rate(float flow_rate) {
    char buffer[20];
    snprintf(buffer, sizeof(buffer), "Flow Rate: %.2f L/min", flow_rate);

    lcd_clear();
    lcd_set_cursor(0, 0);
    lcd_print(buffer);

    snprintf(buffer, sizeof(buffer), "X.XX L/min");
    lcd_set_cursor(1, 0);
    lcd_print(buffer);
}

// LCD initialization function
void lcd_init() {
    if (!lcd_initialized) {
        // Initialize LCD
        gpioDelay(5000); // Wait for LCD to power up
        lcd_send_command(0x33); // Initialize
        gpioDelay(5000); // Wait for LCD to power up
        lcd_send_command(0x32); // Initialize
        gpioDelay(5000); // Wait for LCD to power up
