#include <pigpio.h>

// Define GPIO pins for row and column control
#define ROW_PINS {17, 18, 27, 22, 23, 24, 25, 4}
#define COL_PINS {5, 6, 12, 13, 19, 16, 26, 20}

// Define the number of rows and columns
#define NUM_ROWS 8
#define NUM_COLS 8

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
void setup_gpio();
void cleanup_gpio();
void set_row(int row_index, int state);
void set_column(int col_index, int state);
void wave_left();
void wave_right();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a row
void set_row(int row_index, int state) {
    if (row_index < 0 || row_index >= NUM_ROWS) {
        fprintf(stderr, "Error: Invalid row index: %d\n", row_index);
        return;
    }
    gpioWrite(ROW_PINS[row_index], state);
}

// Function to set the state of a column
void set_column(int col_index, int state) {
    if (col_index < 0 || col_index >= NUM_COLS) {
        fprintf(stderr, "Error: Invalid column index: %d\n", col_index);
        return;
    }
    gpioWrite(COL_PINS[col_index], state);
}

// Function to perform a wave-like animation moving from left to right
void wave_left() {
    for (int i = 0; i < NUM_COLS; i++) {
        for (int j = 0; j < NUM_ROWS; j++) {
            set_row(j, 0); // Turn off all rows
            set_column(i, 1); // Turn on the current column
            gpioDelay(800); // Delay for 800 microseconds
        }
    }
}

// Function to perform a wave-like animation moving from right to left
void wave_right() {
    for (int i = NUM_COLS - 1; i >= 0; i--) {
        for (int j = 0; j < NUM_ROWS; j++) {
            set_row(j, 0); // Turn off all rows
            set_column(i, 1); // Turn on the current column
            gpioDelay(800); // Delay for 800 microseconds
        }
    }
}

// Function to set up GPIO pins
void setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        exit(1);
    }

    // Set row pins as outputs
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioSetMode(ROW_PINS[i], PI_OUTPUT);
        gpioWrite(ROW_PINS[i], 1); // Initialize row pins to HIGH
    }

    // Set column pins as outputs
    for (int i = 0; i < NUM_COLS; i++) {
        gpioSetMode(COL_PINS[i], PI_OUTPUT);
        gpioWrite(COL_PINS[i], 0); // Initialize column pins to LOW
    }
}

// Function to clean up GPIO pins
void cleanup_gpio() {
    // Turn off all rows and columns
    for (int i = 0; i < NUM_ROWS; i++) {
        gpioWrite(ROW_PINS[i], 0);
    }
    for (int i = 0; i < NUM_COLS; i++) {
        gpioWrite(COL_PINS[i], 0);
    }

    gpioTerminate();
}

int main() {
    // Register signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Set up GPIO pins
    setup_gpio();

    fprintf(stderr, "LED matrix animation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        wave_left();
        wave_right();
    }

    // Clean up GPIO pins before exiting
    cleanup_gpio();

    return 0;
}

