// Define GPIO pins for row anodes (BCM)
#define ROW_1 2
#define ROW_2 3
#define ROW_3 4
#define ROW_4 17
#define ROW_5 27
#define ROW_6 22
#define ROW_7 10
#define ROW_8 9

// Define GPIO pins for column cathodes (BCM)
#define COL_1 14
#define COL_2 15
#define COL_3 18
#define COL_4 23
#define COL_5 24
#define COL_6 25
#define COL_7 8
#define COL_8 7

// Function prototypes
void cleanup(int signal);
void set_row(int row, int state);
void set_column(int column, int state);
void wave_animation();

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void cleanup(int signal) {
    program_running = 0;
    printf("\nCleaning up and exiting...\n");

    // Set all row and column pins to LOW (OFF)
    set_row(ROW_1, 0);
    set_row(ROW_2, 0);
    set_row(ROW_3, 0);
    set_row(ROW_4, 0);
    set_row(ROW_5, 0);
    set_row(ROW_6, 0);
    set_row(ROW_7, 0);
    set_row(ROW_8, 0);

    set_column(COL_1, 0);
    set_column(COL_2, 0);
    set_column(COL_3, 0);
    set_column(COL_4, 0);
    set_column(COL_5, 0);
    set_column(COL_6, 0);
    set_column(COL_7, 0);
    set_column(COL_8, 0);

    // Terminate pigpio library
    gpioTerminate();

    exit(0);
}

// Function to set the state of a row anode
void set_row(int row, int state) {
    if (gpioWrite(row, state) != 0) {
        fprintf(stderr, "Error writing to row %d\n", row);
        cleanup(0); // Exit gracefully
    }
}

// Function to set the state of a column cathode
void set_column(int column, int state) {
    if (gpioWrite(column, state) != 0) {
        fprintf(stderr, "Error writing to column %d\n", column);
        cleanup(0); // Exit gracefully
    }
}

// Function to perform the wave animation
void wave_animation() {
    int i, j;

    // Scan columns from left to right
    for (i = 0; i < 8 && program_running; i++) {
        // Clear the matrix (turn off all LEDs)
        set_column(COL_1, 0);
        set_column(COL_2, 0);
        set_column(COL_3, 0);
        set_column(COL_4, 0);
        set_column(COL_5, 0);
        set_column(COL_6, 0);
        set_column(COL_7, 0);
        set_column(COL_8, 0);

        // Set the current column cathode LOW
        set_column(i, 1);

        // Light up LEDs sequentially for each row
        for (j = 0; j < 8 && program_running; j++) {
            // Set the current row anode HIGH
            set_row(ROW_1 + j, 1);

            // Delay for 150ms
            gpioDelay(150000); // 150ms = 150000 microseconds

            // Set the current row anode LOW
            set_row(ROW_1 + j, 0);
        }

        // Delay between columns
        gpioDelay(50000); // 50ms = 50000 microseconds
    }
}

