    gpioSetMode(ROW_1, PI_OUTPUT);
    gpioSetMode(ROW_2, PI_OUTPUT);
    gpioSetMode(ROW_3, PI_OUTPUT);
    gpioSetMode(ROW_4, PI_OUTPUT);
    gpioSetMode(ROW_5, PI_OUTPUT);
    gpioSetMode(ROW_6, PI_OUTPUT);
    gpioSetMode(ROW_7, PI_OUTPUT);
    gpioSetMode(ROW_8, PI_OUTPUT);

    gpioSetMode(COL_1, PI_OUTPUT);
    gpioSetMode(COL_2, PI_OUTPUT);
    gpioSetMode(COL_3, PI_OUTPUT);
    gpioSetMode(COL_4, PI_OUTPUT);
    gpioSetMode(COL_5, PI_OUTPUT);
    gpioSetMode(COL_6, PI_OUTPUT);
    gpioSetMode(COL_7, PI_OUTPUT);
    gpioSetMode(COL_8, PI_OUTPUT);

    // Set all row and column pins to LOW (OFF) initially
    set_row(ROW_1, 0);
    set_row(ROW_2, 0);
    set_row(ROW_3, 0);
    set_row(ROW_4, 0);
    set_row(ROW_5, 0);
    set_row(ROW_6, 0);
    set_row(ROW_7, 0);
    set_row(ROW_8, 0);

    set_column(COL_1, 0);
    set_column(COL_2, 0);
    set_column(COL_3, 0);
    set_column(COL_4, 0);
    set_column(COL_5, 0);
    set_column(COL_6, 0);
    set_column(COL_7, 0);
    set_column(COL_8, 0);

    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    // Perform the wave animation
    wave_animation();

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

