#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define MLX75031_ADDR 0x4C

// Define the register address for distance data
#define DISTANCE_REG 0x00

// Define the log file name
#define LOG_FILE "depth_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float distance;
    time_t timestamp;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_distance(float *distance);
int log_data(float distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the pigpio library and opens the I2C bus
int initialize_sensor() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, MLX75031_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Reads the distance data from the MLX75031 sensor
int read_distance(float *distance) {
    char buf[2];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, DISTANCE_REG, buf, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "I2C read failed: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes into a 16-bit integer
    int16_t raw_distance = (buf[0] << 8) | buf[1];

    // Convert the raw distance to millimeters (adjust scaling as needed)
    *distance = (float)raw_distance * 0.1; // Example scaling

    return 0;
}

// Logs the distance data to the CSV file
int log_data(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            fprintf(stderr, "Failed to open log file\n");
            return -1;
        }

        // Check if the file is new and write the header
        fseek(log_file, 0, SEEK_END);
        long file_size = ftell(log_file);
        if (file_size == 0) {
            fprintf(log_file, "Timestamp,Distance (mm)\n");
        }
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        return 1;
    }

    float distance;

    // Main loop
    while (!terminate) {
        // Read the distance
        if (read_distance(&distance) == 0) {
            // Log the data
            if (log_data(distance) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read distance\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close the I2C handle and log file
    i2cClose(i2c_handle);
    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();

    return 0;
}

