#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 4
#define LED_PIN 17

// Define log file name
#define LOG_FILE "proximity.log"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
int detect_object(int sensor_value);
int log_event(const char *timestamp);
int blink_led(int duration_ms);
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int sensor_pin;
    int led_pin;
    const char *log_file_name;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to detect an object
int detect_object(int sensor_value) {
    return (sensor_value == 0); // Object detected if sensor output is LOW
}

// Function to log an event to the file
int log_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s Object detected\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to blink the LED
int blink_led(int duration_ms) {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
    gpioWrite(LED_PIN, 0); // Turn LED off
    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(LED_PIN, 0); // Ensure LED is off
    gpioTerminate(); // Terminate pigpio
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup_gpio();
        return 1;
    }

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value\n");
            break;
        }

        if (detect_object(sensor_value)) {
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20]; // ISO 8601 format: YYYY-MM-DDTHH:MM:SSZ

            time(&rawtime);
            timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

            if (log_event(timestamp) == 0) {
                printf("Object detected at %s\n", timestamp);
                blink_led(100); // Blink LED for 100ms
            } else {
                fprintf(stderr, "Error logging event\n");
            }
        }

        gpioDelay(100 * 1000); // Delay for 100ms (microseconds)
    }

    // Cleanup
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }

    printf("Proximity sensor monitoring stopped.\n");

    return 0;
}

