    printf("\nCaught signal %d, cleaning up...\n", signal);
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Initialize the Si1145 sensor
int si1145_init() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, 0x17, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1145\n");
        return -1;
