#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0      // cm
#define TIMEOUT_US 30000       // 30ms timeout in microseconds
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void trigger_sensor();
long measure_pulse_width();
float calculate_distance(long pulse_width);
void log_distance(float distance);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long measure_pulse_width() {
    long start_tick = 0, end_tick = 0;

    // Wait for the echo pin to go high (with timeout)
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout >= TIMEOUT_US) {
        log_error("Timeout waiting for echo high");
        return -1; // Timeout error
    }

    start_tick = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout >= TIMEOUT_US) {
        log_error("Timeout waiting for echo low");
        return -1; // Timeout error
    }

    end_tick = gpioTick();

    return end_tick - start_tick;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log the distance to a file
void log_distance(float distance) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
        fprintf(log_file, "%s, Distance: %.2f cm\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(log_file, "%s, Error: Distance out of range (%.2f cm)\n", timestamp, distance);
        fflush(log_file);
    }
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
