// APDS9960 I2C address
#define APDS9960_I2C_ADDR 0x39

// APDS9960 register addresses
#define APDS9960_ENABLE 0x80
#define APDS9960_ATIME 0x81
#define APDS9960_WTIME 0x83
#define APDS9960_AILTL 0x84
#define APDS9960_AILTH 0x85
#define APDS9960_AIHTL 0x86
#define APDS9960_AIHTH 0x87
#define APDS9960_PERS 0x8C
#define APDS9960_CONFIG1 0x8D
#define APDS9960_PPULSE 0x8E
#define APDS9960_CONTROL 0x8F
#define APDS9960_CONFIG2 0x90
#define APDS9960_ID 0x92
#define APDS9960_STATUS 0x93
#define APDS9960_CDATAL 0x94
#define APDS9960_CDATAH 0x95
#define APDS9960_RDATAL 0x96
#define APDS9960_RDATAH 0x97
#define APDS9960_GDATAL 0x98
#define APDS9960_GDATAH 0x99
#define APDS9960_BDATAL 0x9A
#define APDS9960_BDATAH 0x9B
#define APDS9960_PDATA 0x9C
#define APDS9960_POFFSET_UR 0x9D
#define APDS9960_POFFSET_DL 0x9E
#define APDS9960_CONFIG3 0x9F

// Proximity threshold
#define PROXIMITY_THRESHOLD 200

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int apds9960_init();
int apds9960_read_proximity();
int apds9960_read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue);
void log_data(uint16_t proximity, uint16_t red, uint16_t green, uint16_t blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the APDS9960 sensor
int apds9960_init() {
    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, APDS9960_ID);
    if (sensor_id != 0xAB) {
        fprintf(stderr, "Error: Invalid sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Enable proximity and RGB sensors
    if (i2cWriteByteData(i2c_handle, APDS9960_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error: Failed to enable proximity and RGB sensors\n");
        return -1;
    }

    // Set proximity threshold
    if (i2cWriteByteData(i2c_handle, APDS9960_ATIME, 0xD5) < 0) {
        fprintf(stderr, "Error: Failed to set proximity time\n");
        return -1;
    }

    // Set proximity gain
    if (i2cWriteByteData(i2c_handle, APDS9960_PPULSE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set proximity pulse width\n");
        return -1;
    }

    // Set proximity interrupt
    if (i2cWriteByteData(i2c_handle, APDS9960_CONTROL, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to set proximity interrupt\n");
        return -1;
    }

    return 0;
}

// Function to read the proximity value from the APDS9960
int apds9960_read_proximity() {
    int proximity = i2cReadByteData(i2c_handle, APDS9960_PDATA);
    if (proximity < 0) {
        fprintf(stderr, "Error: Failed to read proximity data\n");
        return -1;
    }
    return proximity;
}

// Function to read the RGB color values from the APDS9960
int apds9960_read_rgb(uint16_t *red, uint16_t *green, uint16_t *blue) {
    int red_l = i2cReadByteData(i2c_handle, APDS9960_RDATAL);
    int red_h = i2cReadByteData(i2c_handle, APDS9960_RDATAH);
    int green_l = i2cReadByteData(i2c_handle, APDS9960_GDATAL);
    int green_h = i2cReadByteData(i2c_handle, APDS9960_GDATAH);
    int blue_l = i2cReadByteData(i2c_handle, APDS9960_BDATAL);
    int blue_h = i2cReadByteData(i2c_handle, APDS9960_BDATAH);

    if (red_l < 0 || red_h < 0 || green_l < 0 || green_h < 0 || blue_l < 0 || blue_h < 0) {
        fprintf(stderr, "Error: Failed to read RGB data\n");
        return -1;
    }

    *red = (red_h << 8) | red_l;
    *green = (green_h << 8) | green_l;
    *blue = (blue_h << 8) | blue_l;

    return 0;
}

// Function to log the data to a CSV file
void log_data(uint16_t proximity, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, proximity, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, APDS9960_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize APDS9960 sensor
    if (apds9960_init() < 0) {
        fprintf(stderr, "Error: APDS9960 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen("color_proximity_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to CSV file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Proximity,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("APDS9960 proximity and color monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        int proximity = apds9960_read_proximity();
        if (proximity >= 0) {
            uint16_t red, green, blue;
            if (apds9960_read_rgb(&red, &green, &blue) == 0) {
                if (proximity > PROXIMITY_THRESHOLD) {
                    log_data(proximity, red, green, blue);
                    printf("Proximity: %u, Red: %u, Green: %u, Blue: %u\n", proximity, red, green, blue);
                }
            }
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

