#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define CH101_ADDR 0x50

// Define the register addresses for CH101
#define CH101_REG_WHO_AM_I 0x0F
#define CH101_REG_DISTANCE 0x00
#define CH101_REG_CONFIG 0x01

// Define the distance threshold for valid readings
#define DISTANCE_THRESHOLD 500

// Define the sampling interval in milliseconds
#define SAMPLING_INTERVAL 200

// Define the log file name
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold the configuration
typedef struct {
    uint8_t config_value;
} ch101_config_t;

// Function prototypes
int init_i2c();
int init_ch101();
int read_distance(int *distance);
int validate_distance(int distance);
int log_distance(int distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, CH101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the CH101 sensor
int init_ch101() {
    // Verify WHO_AM_I register
    int who_am_i;
    if (i2cReadByteData(i2c_handle, CH101_REG_WHO_AM_I) < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register\n");
        return -1;
    }
    who_am_i = i2cReadByteData(i2c_handle, CH101_REG_WHO_AM_I);
    if (who_am_i != 0x41) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x41\n", who_am_i);
        return -1;
    }

    // Configure the sensor (example configuration)
    ch101_config_t config = {0x00}; // Example configuration value
    if (i2cWriteByteData(i2c_handle, CH101_REG_CONFIG, config.config_value) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        return -1;
    }

    return 0;
}

// Read the distance from the CH101 sensor
int read_distance(int *distance) {
    int raw_distance;

    raw_distance = i2cReadWordData(i2c_handle, CH101_REG_DISTANCE);
    if (raw_distance < 0) {
        fprintf(stderr, "Failed to read distance register\n");
        return -1;
    }

    *distance = raw_distance; // Store the raw distance

    return 0;
}

// Validate the distance reading
int validate_distance(int distance) {
    if (distance < 0 || distance > 4000) {
        fprintf(stderr, "Invalid distance reading: %d\n", distance);
        return -1;
    }
    return 0;
}

// Log the distance to a file
int log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // Buffer to hold the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
        printf("%s, %d\n", timestamp, distance); // Also print to stdout
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    int distance;

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize CH101 sensor
    if (init_ch101() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Starting distance measurement...\n");

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Validate distance
            if (validate_distance(distance) == 0) {
                // Log distance
                if (log_distance(distance) != 0) {
                    fprintf(stderr, "Failed to log distance\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read distance, skipping sample\n");
        }

        // Wait for the next sample
        gpioDelay(SAMPLING_INTERVAL * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

