        return -1;
    }
    who_am_i = i2cReadByteData(i2c_handle, CH101_REG_WHO_AM_I);
    if (who_am_i != 0x41) {
        fprintf(stderr, "WHO_AM_I returned 0x%02X, expected 0x41\n", who_am_i);
        return -1;
    }

    // Configure the sensor (example configuration)
    ch101_config_t config = {0x00}; // Example configuration value
    if (i2cWriteByteData(i2c_handle, CH101_REG_CONFIG, config.config_value) < 0) {
        fprintf(stderr, "Failed to write to CONFIG register\n");
        return -1;
    }

    return 0;
}

// Read the distance from the CH101 sensor
int read_distance(int *distance) {
    int raw_distance;

    raw_distance = i2cReadWordData(i2c_handle, CH101_REG_DISTANCE);
    if (raw_distance < 0) {
        fprintf(stderr, "Failed to read distance register\n");
        return -1;
    }

    *distance = raw_distance; // Store the raw distance

    return 0;
}

// Validate the distance reading
int validate_distance(int distance) {
    if (distance < 0 || distance > 4000) {
        fprintf(stderr, "Invalid distance reading: %d\n", distance);
        return -1;
    }
    return 0;
}

// Log the distance to a file
int log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20]; // Buffer to hold the timestamp

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, %d\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
        printf("%s, %d\n", timestamp, distance); // Also print to stdout
    } else {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
