    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize CH101 sensor
    if (init_ch101() != 0) {
        cleanup();
        return 1;
    }

