    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Starting distance measurement...\n");

    // Main loop
    while (!terminate) {
        // Read distance
        if (read_distance(&distance) == 0) {
            // Validate distance
            if (validate_distance(distance) == 0) {
                // Log distance
                if (log_distance(distance) != 0) {
                    fprintf(stderr, "Failed to log distance\n");
                }
            }
        } else {
