// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

// Define the log file name
#define LOG_FILE "obstacle_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int gpio_pin) {
    int sensor_value = gpioRead(gpio_pin);
    if (sensor_value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d: %d\n", gpio_pin, sensor_value);
        return -1; // Indicate an error
    }
    return sensor_value;
}

// Function to log the sensor data to a file
void log_data(int sensor1_value, int sensor2_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s,%d,%d\n", timestamp, sensor1_value, sensor2_value);
    fclose(fp);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    fprintf(stderr, "Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        // Log the data if readings were successful
        if (sensor1_value != -1 && sensor2_value != -1) {
            log_data(sensor1_value, sensor2_value);
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 milliseconds = 100000 microseconds
    }

    // Release GPIO resources before exiting
    gpioTerminate();

    fprintf(stderr, "Obstacle detection program terminated.\n");
    return 0;
}

