// Si1182 I2C address
#define SI1182_ADDR 0x60

// Si1182 register addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x24
#define REG_COMMAND 0x30
#define REG_HW_KEY 0x07

// Commands
#define CMD_RESET 0x01
#define CMD_ALS_FORCE 0x06
#define CMD_PS_FORCE 0x07

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int proximity;
    int ambient_light;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, cleaning up...\n", signal);
}

// Initializes the Si1182 sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration - adjust as needed)
    if (i2cWriteByteData(i2c_handle, 0x18, 0x0F) < 0) { // PS1_ADCMUX
        fprintf(stderr, "Error: Failed to write PS1_ADCMUX.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x19, 0x0F) < 0) { // ALS_ADCMUX
        fprintf(stderr, "Error: Failed to write ALS_ADCMUX.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x02, 0x01) < 0) { // PS1_LED11_SELECT
        fprintf(stderr, "Error: Failed to write PS1_LED11_SELECT.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x03, 0x01) < 0) { // ALS_LED11_SELECT
        fprintf(stderr, "Error: Failed to write ALS_LED11_SELECT.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x04, 0x01) < 0) { // PS1_LED21_SELECT
        fprintf(stderr, "Error: Failed to write PS1_LED21_SELECT.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x05, 0x01) < 0) { // ALS_LED21_SELECT
        fprintf(stderr, "Error: Failed to write ALS_LED21_SELECT.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x06, 0x01) < 0) { // PS1_LED31_SELECT
        fprintf(stderr, "Error: Failed to write PS1_LED31_SELECT.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x07, 0x01) < 0) { // ALS_LED31_SELECT
        fprintf(stderr, "Error: Failed to write ALS_LED31_SELECT.\n");
