#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define B5L_LD50_ADDR 0x50

// Define the command to request a measurement
#define REQUEST_MEASUREMENT_CMD 0x01

// Define the number of samples to take
#define NUM_SAMPLES 10

// Define the delay between samples in milliseconds
#define SAMPLE_DELAY_MS 100

// Define the log file name
#define LOG_FILE "intrusion_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int request_measurement();
int read_sensor_data(sensor_data_t *data);
float calculate_average_distance(sensor_data_t *data, int num_samples);
int log_intrusion_event(float average_distance);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, B5L_LD50_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to request a measurement from the sensor
int request_measurement() {
    char cmd[1] = {REQUEST_MEASUREMENT_CMD};
    int result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[15];
    int result = i2cReadDevice(i2c_handle, buffer, 15);
    if (result != 15) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Verify the header byte
    if (buffer[0] != 0x50) {
        fprintf(stderr, "Invalid header byte: 0x%02X\n", buffer[0]);
        return -1;
    }

    // Extract the distance from the buffer
    data->distance = (buffer[11] << 8) | buffer[12];

    return 0;
}

// Function to calculate the average distance
float calculate_average_distance(sensor_data_t *data, int num_samples) {
    float sum = 0.0;
    for (int i = 0; i < num_samples; i++) {
        sum += data[i].distance;
    }
    return sum / num_samples;
}

// Function to log an intrusion event
int log_intrusion_event(float average_distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Average Distance: %.2f mm\n", timestamp, average_distance);
    fflush(log_file); // Ensure data is written to the file immediately

    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data[NUM_SAMPLES];

    // Main loop
    while (!terminate) {
        // Request a measurement
        if (request_measurement() != 0) {
            fprintf(stderr, "Failed to request measurement, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for the measurement to complete (adjust as needed)
        gpioDelay(10); // 10 ms delay

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Calculate the average distance
        float average_distance = calculate_average_distance(sensor_data, NUM_SAMPLES);

        // Log the intrusion event
        if (average_distance < 1000.0) {
            log_intrusion_event(average_distance);
        }

        // Delay before the next sample
        gpioDelay(SAMPLE_DELAY_MS);
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

