#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <signal.h>
#include <errno.h>
#include <time.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define MLX75030_ADDR 0x4C

// Define the register address for distance measurement
#define DISTANCE_REG 0x00

// Global variable for the I2C file descriptor
int i2c_fd = -1;

// Signal handler function
void signal_handler(int sig) {
    printf("\nCaught signal %d, cleaning up...\n", sig);
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    exit(0);
}

// Function to initialize the I2C bus
int init_i2c(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        return -1;
    }

    // Specify the address of the slave device
    if (ioctl(fd, I2C_SLAVE, MLX75030_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        close(fd);
        return -1;
    }

    return fd;
}

// Function to read distance from the sensor
int read_distance(int fd) {
    uint8_t buffer[2];
    ssize_t bytes_read = read(fd, buffer, 2);

    if (bytes_read != 2) {
        fprintf(stderr, "Error reading distance data: %s\n", strerror(errno));
        return -1;
    }

    // Combine the two bytes into a 16-bit value
    int distance = (buffer[0] << 8) | buffer[1];

    return distance;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C bus
    i2c_fd = init_i2c(I2C_BUS);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    printf("I2C initialized successfully.\n");

    // Main loop
    while (1) {
        // Read the distance from the sensor
        int distance = read_distance(i2c_fd);

        if (distance >= 0) {
            // Print the distance to stdout
            printf("Distance: %d mm\n", distance);
        } else {
            // Log the error to stderr
            fprintf(stderr, "Error reading distance. Retrying in 500ms.\n");
        }

        // Wait for 500 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 500 * 1000 * 1000; // 500 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    return 0;
}

