// Define the OPT3101 I2C address
#define OPT3101_ADDR 0x60

// Define register addresses
#define OPT3101_REG_STATUS 0x00
#define OPT3101_REG_DISTANCE_MSB 0x01
#define OPT3101_REG_DISTANCE_LSB 0x02
#define OPT3101_REG_ALS_MSB 0x03
#define OPT3101_REG_ALS_LSB 0x04
#define OPT3101_REG_CONFIG 0x05

// Define configuration values
#define OPT3101_CONFIG_CONT_MODE 0x00 // Continuous mode
#define OPT3101_CONFIG_GAIN_1X 0x00  // Gain 1x
#define OPT3101_CONFIG_IT_500MS 0x00 // Integration time 500ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    uint16_t ambient_light;
    uint8_t error_flags;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, OPT3101_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the OPT3101 sensor
int configure_sensor() {
    char config_data[2];
    config_data[0] = OPT3101_REG_CONFIG;
    config_data[1] = OPT3101_CONFIG_CONT_MODE | OPT3101_CONFIG_GAIN_1X | OPT3101_CONFIG_IT_500MS;

    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read sensor data from OPT3101
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];
    int result;

    // Read 6 bytes from the sensor (distance MSB, distance LSB, ALS MSB, ALS LSB, status, error flags)
    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        data.distance = 0; // Set to 0 to indicate error
        data.ambient_light = 0;
        data.error_flags = 0xFF; // Set all error flags to 1
        return data;
    }

    // Extract distance data
    data.distance = (buffer[0] << 8) | buffer[1];

    // Extract ambient light data
    data.ambient_light = (buffer[3] << 8) | buffer[4];

    // Extract error flags
    data.error_flags = buffer[5];

    return data;
}

// Log sensor data to the console
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Distance: %u mm, Ambient Light: %u lux, Error Flags: 0x%02X\n",
           timestamp, data.distance, data.ambient_light, data.error_flags);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Configure the sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data();

        // Log the data
        log_data(sensor_data);

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500ms = 500000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

