#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // Speed of sound in cm/s
#define TIMEOUT_US 200000      // Timeout for echo pulse in microseconds
#define MAX_DISTANCE 400.0     // Maximum measurable distance in cm

// Global variable for graceful shutdown
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 microseconds trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse duration
long measureEcho() {
    long startTime = 0, endTime = 0;

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pin did not go high within timeout.\n");
        return -1; // Indicate timeout error
    }

    startTime = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pin did not go low within timeout.\n");
        return -1; // Indicate timeout error
    }

    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseDuration) {
    if (pulseDuration <= 0) {
        fprintf(stderr, "Error: Invalid pulse duration: %ld\n", pulseDuration);
        return -1.0; // Indicate invalid distance
    }

    // Calculate distance in centimeters
    float distance = (pulseDuration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance

    // Ensure distance is within the valid range
    if (distance > MAX_DISTANCE) {
        fprintf(stderr, "Error: Distance out of range: %.2f cm\n", distance);
        return -1.0; // Indicate invalid distance
    }

    return distance;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        triggerSensor();
        long pulseDuration = measureEcho();

        if (pulseDuration > 0) {
            float distance = calculateDistance(pulseDuration);

            if (distance > 0) {
                // Get current timestamp
                time_t rawtime;
                struct tm *timeinfo;
                char timestamp[80];

                time(&rawtime);
                timeinfo = localtime(&rawtime);

                strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

                // Log the distance with timestamp
                printf("%s Distance: %.2f cm\n", timestamp, distance);
            }
        } else {
            fprintf(stderr, "Error: Invalid distance measurement.\n");
        }

        gpioDelay(1000000); // Wait for 1 second (1000000 microseconds)
    }

    // Clean up and terminate pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    return 0;
}

