#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <termios.h>
#include <errno.h>
#include <pigpio.h>

// Configuration
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define LED_GPIO 17
#define DISTANCE_THRESHOLD 1.0 // meters
#define LOG_FILE "intrusion_log.csv"
#define BUFFER_SIZE 2048

// Global variables
int uart_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure for configuration
typedef struct {
    char uart_device[20];
    int baud_rate;
    int led_gpio;
    float distance_threshold;
    char log_file[50];
} Config;

// Function prototypes
int init_uart(const char *device, int baud_rate);
int read_uart_data(int fd, unsigned char *buffer, int max_len);
int parse_range_profile(const unsigned char *buffer, int len, float *distance);
int check_distance_threshold(float distance, float threshold);
int log_intrusion(float distance);
int activate_led(int gpio, int duration_ms);
void signal_handler(int signal);
int init_gpio(int gpio);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize UART
int init_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);    // ignore modem controls, enable reading
    tty.c_cflag &= ~CSIZE;             // mask the character size bits
    tty.c_cflag |= CS8;              // 8-bit characters
    tty.c_cflag &= ~PARENB;            // no parity bit
    tty.c_cflag &= ~CSTOPB;            // only need 1 stop bit
    tty.c_cflag &= ~CRTSCTS;           // disable hardware flow control

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                // no remapping, no delays
    tty.c_cc[VMIN]  = 0;            // read doesn't block
    tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Read data from UART
int read_uart_data(int fd, unsigned char *buffer, int max_len) {
    int bytes_read = 0;
    while (bytes_read < max_len && !terminate) {
        int c = read(fd, buffer + bytes_read, 1);
        if (c == -1) {
            if (errno == EAGAIN || errno == EWOULDBLOCK) {
                // No data available, sleep briefly to avoid busy-waiting
                usleep(1000); // 1 ms
                continue;
            } else {
                perror("Error reading from UART");
                return -1;
            }
        } else if (c == 0) {
            // End of file (or error)
            break;
        }
        bytes_read++;
    }
    return bytes_read;
}

// Parse range profile data
int parse_range_profile(const unsigned char *buffer, int len, float *distance) {
    if (len < 128) {
        fprintf(stderr, "Error: Insufficient data length (%d bytes)\n", len);
        return -1;
    }

    // Check for magic word (example: 0x01020304)
    if (buffer[0] != 0x01 || buffer[1] != 0x02 || buffer[2] != 0x03 || buffer[3] != 0x04) {
        fprintf(stderr, "Error: Invalid magic word\n");
        return -1;
    }

    // Extract distance data (assuming little-endian)
    int16_t *range_data = (int16_t *)(buffer + 4); // Skip the magic word
    *distance = 0.0; // Initialize distance

    for (int i = 0; i < 64; i++) {
        *distance += (float)range_data[i];
    }

    *distance /= 64.0; // Average the distance bins

    return 0;
}

// Check if distance is within threshold
int check_distance_threshold(float distance, float threshold) {
    return (distance <= threshold);
}

// Log intrusion event
int log_intrusion(float distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately

    printf("Intrusion detected! Timestamp: %s, Distance: %.2f meters\n", timestamp, distance);
    return 0;
}

// Activate LED
int activate_led(int gpio, int duration_ms) {
    gpioWrite(gpio, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
    gpioWrite(gpio, 0); // Turn LED off
    return 0;
}

// Initialize GPIO
int init_gpio(int gpio) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0); // Ensure LED is off initially
    return 0;
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");
    if (uart_fd != -1) {
        close(uart_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize configuration
    Config config = {
        .uart_device = UART_DEVICE,
        .baud_rate = BAUD_RATE,
        .led_gpio = LED_GPIO,
        .distance_threshold = DISTANCE_THRESHOLD,
        .log_file = LOG_FILE
    };

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(config.uart_device, config.baud_rate);
    if (uart_fd == -1) {
        return 1;
    }

    // Initialize GPIO
    if (init_gpio(config.led_gpio) == -1) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    unsigned char buffer[BUFFER_SIZE];
    float distance;

    printf("Intrusion detection system started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        int bytes_read = read_uart_data(uart_fd, buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            if (parse_range_profile(buffer, bytes_read, &distance) == 0) {
                if (check_distance_threshold(distance, config.distance_threshold)) {
                    log_intrusion(distance);
                    activate_led(config.led_gpio, 2000); // Activate LED for 2 seconds
                }
            }
        } else if (bytes_read < 0) {
            fprintf(stderr, "Error reading from UART, retrying...\n");
            close(uart_fd);
            usleep(100000); // Wait 100ms before retrying
            uart_fd = init_uart(config.uart_device, config.baud_rate);
            if (uart_fd == -1) {
                fprintf(stderr, "Failed to re-initialize UART, exiting.\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }
        usleep(10000); // Small delay to avoid busy-waiting
    }

    // Cleanup and exit
    cleanup();
    printf("Intrusion detection system stopped.\n");
    return 0;
}

