#include <signal.h>
#include <unistd.h>
#include <string.h>

// Define constants
#define I2C_BUS 1
#define CH201_ADDR 0x50
#define LED_GPIO 18
#define LED_ON_TIME_US 500000 // 500ms
#define LED_OFF_TIME_US 500000 // 500ms
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 3
#define RETRY_DELAY_US 10000 // 10ms

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float distance;
    int frequency;
} SensorData;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_ch201_distance(float *distance);
int calculate_led_frequency(float distance);
void set_led_frequency(int frequency);
void log_data(float distance, int frequency);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, CH201_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read distance from CH201 sensor
int read_ch201_distance(float *distance) {
    char cmd[1] = {0x00}; // Command to trigger a measurement
    char buffer[2];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, cmd, 1) != 0) {
            fprintf(stderr, "I2C write failed (attempt %d): %d\n", retries + 1, i2c_handle);
            gpioDelay(RETRY_DELAY_US);
            retries++;
            continue;
        }

        gpioDelay(1000); // Wait for measurement (adjust as needed)

        if (i2cReadDevice(i2c_handle, buffer, 2) != 2) {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, i2c_handle);
            gpioDelay(RETRY_DELAY_US);
            retries++;
            continue;
        }

        // Convert raw data to distance (adjust based on CH201 datasheet)
        int raw_distance = (buffer[0] << 8) | buffer[1];
        *distance = (float)raw_distance / 10.0; // Example conversion

        return 0; // Success
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

