int calculate_led_frequency(float distance) {
    // Map distance (0-100cm) to frequency (0-100Hz)
    // This is a linear mapping, adjust as needed
    int frequency = (int)(100.0 - (distance / 100.0) * 100.0);

    // Clamp frequency to valid range
    if (frequency < 0) {
        frequency = 0;
    } else if (frequency > 100) {
        frequency = 100;
    }

    return frequency;
}

// Set LED frequency using pigpio
void set_led_frequency(int frequency) {
    // Calculate on and off times based on frequency (100Hz = 10ms period)
    int on_time_us = (int)(1000000.0 / frequency);
    int off_time_us = (int)(1000000.0 / frequency);

    gpioPWM(LED_GPIO, 128); // 50% duty cycle
    gpioDelay(on_time_us);
    gpioPWM(LED_GPIO, 0); // Turn off LED
    gpioDelay(off_time_us);
}

// Log data to stdout
void log_data(float distance, int frequency) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s, Distance: %.2f cm, Frequency: %d Hz\n", timestamp, distance, frequency);
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    float distance;
    int frequency;

    // Main loop
    while (!terminate) {
        // Read distance from sensor
        if (read_ch201_distance(&distance) == 0) {
            // Calculate LED frequency
            frequency = calculate_led_frequency(distance);

            // Set LED frequency
            set_led_frequency(frequency);

            // Log data
            log_data(distance, frequency);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay for 100ms
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

