#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 27

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define log file name
#define LOG_FILE "proximity_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_sensor(int gpio_pin);
void log_event(int sensor_id, const char *event_type);
void debounce(int gpio_pin);
void signal_handler(int signal);

// Function to read the sensor value with debouncing
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    debounce(gpio_pin);
    return value;
}

// Function to log the event to the file
void log_event(int sensor_id, const char *event_type) {
    time_t now = time(NULL);
    struct tm *tstruct = gmtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d, %s\n", buf, sensor_id, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to implement software debounce
void debounce(int gpio_pin) {
    gpioDelay(DEBOUNCE_TIME * 1000); // Delay in microseconds
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Proximity sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor 1
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        if (sensor1_value == 1) {
            log_event(1, "DETECTED");
        } else if (sensor1_value == 0) {
            log_event(1, "CLEARED");
        }

        // Read sensor 2
        int sensor2_value = read_sensor(SENSOR_2_GPIO);
        if (sensor2_value == 1) {
            log_event(2, "DETECTED");
        } else if (sensor2_value == 0) {
            log_event(2, "CLEARED");
        }

        gpioDelay(10000); // Delay for 10ms (10000 microseconds)
    }

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Proximity sensor monitoring stopped.\n");

    return 0;
}

