#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define CH101_ADDR 0x50

// Define the register addresses
#define MEAS_STATUS_REG 0x00
#define DISTANCE_REG 0x01

// Define the measurement command
#define MEASURE_CMD 0x01

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    time_t timestamp;
    float distance_mm;
} sensor_data_t;

// Function prototypes
int i2c_open(const char *bus);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_close(int fd);
int read_distance(int fd, float *distance_mm);
int log_data(FILE *fp, time_t timestamp, float distance_mm);
void signal_handler(int sig);

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

// Function to open the I2C device
int i2c_open(const char *bus) {
    int fd = open(bus, O_RDWR);
    if (fd < 0) {
        fprintf(stderr, "Error opening I2C device: %s\n", strerror(errno));
        return -1;
    }
    return fd;
}

// Function to write a byte to an I2C register
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;
    if (write(fd, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read bytes from an I2C register
int i2c_read_bytes(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        fprintf(stderr, "Error writing register address for read: %s\n", strerror(errno));
        return -1;
    }
    if (read(fd, buf, len) != len) {
        fprintf(stderr, "Error reading from I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to close the I2C device
int i2c_close(int fd) {
    if (close(fd) < 0) {
        fprintf(stderr, "Error closing I2C device: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read the distance from the sensor
int read_distance(int fd, float *distance_mm) {
    uint8_t status_buf[1];
    uint8_t data_buf[2];
    int retries = 3;

    // Send measurement command
    if (i2c_write_byte(fd, MEAS_STATUS_REG, MEASURE_CMD) < 0) {
        fprintf(stderr, "Error sending measurement command\n");
        return -1;
    }

    // Wait for measurement to complete (50ms timeout)
    struct timespec delay;
    delay.tv_sec = 0;
    delay.tv_nsec = 50000000; // 50ms
    while (retries > 0) {
        if (i2c_read_bytes(fd, MEAS_STATUS_REG, status_buf, 1) == 0) {
            if (status_buf[0] & 0x01) { // Check MEAS_STATUS bit
                break; // Measurement complete
            }
        }
        nanosleep(&delay, NULL);
        retries--;
    }

    if (retries == 0) {
        fprintf(stderr, "Timeout waiting for measurement to complete\n");
        return -1;
    }

    // Read distance data
    if (i2c_read_bytes(fd, DISTANCE_REG, data_buf, 2) == 0) {
        // Combine the two bytes into a 16-bit value
        int16_t raw_distance = (data_buf[0] << 8) | data_buf[1];

        // Convert raw distance to millimeters (adjust scaling factor as needed)
        *distance_mm = (float)raw_distance * 0.1; // Example scaling factor

        return 0; // Success
    } else {
        fprintf(stderr, "Error reading distance data\n");
        return -1; // Failure
    }
}

// Function to log the data to a CSV file
int log_data(FILE *fp, time_t timestamp, float distance_mm) {
    struct tm *tm_info = localtime(&timestamp);
    char timestamp_str[30];

    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%dT%H:%M:%SZ", tm_info);

    if (fprintf(fp, "%s,%.2f\n", timestamp_str, distance_mm) < 0) {
        fprintf(stderr, "Error writing to log file: %s\n", strerror(errno));
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the I2C device
    i2c_fd = i2c_open(I2C_BUS);
    if (i2c_fd < 0) {
        return 1;
    }

    // Set the I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, CH101_ADDR) < 0) {
        fprintf(stderr, "Error setting I2C slave address: %s\n", strerror(errno));
        i2c_close(i2c_fd);
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("distance_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2c_close(i2c_fd);
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,distance_mm\n");
    }
    rewind(log_file);

    // Main loop
    float distance_mm;
    time_t current_time;

    while (!terminate) {
        // Read the distance
        if (read_distance(i2c_fd, &distance_mm) == 0) {
            // Get the current timestamp
            current_time = time(NULL);

            // Log the data
            if (log_data(log_file, current_time, distance_mm) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            // Print the data to the console
            printf("Timestamp: %ld, Distance: %.2f mm\n", current_time, distance_mm);
        } else {
            fprintf(stderr, "Error reading distance\n");
        }

        // Wait for 500ms
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 500000000; // 500ms
        nanosleep(&delay, NULL);
    }

    // Clean up
    i2c_close(i2c_fd);
    fclose(log_file);

    return 0;
}

