#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// VL53L5CX I2C address
#define VL53L5CX_ADDR 0x29

// VL53L5CX register addresses (Example - refer to datasheet for complete list)
#define VL53L5CX_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L5CX_REG_RANGING_MODE 0x0010
#define VL53L5CX_REG_START_STOP_CONTROL 0x0000
#define VL53L5CX_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD1 0x0052
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD2 0x0054
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD3 0x0056
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD4 0x0058
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD5 0x005A
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD6 0x005C
#define VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD7 0x005E

// I2C handle
int i2c_handle;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting...\n");
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Function to write a byte to a VL53L5CX register
int write_register(int handle, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;
    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to read a byte from a VL53L5CX register
int read_register(int handle, uint8_t reg, uint8_t *value) {
    int result = i2cWriteDevice(handle, &reg, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing register address for read: %d\n", result);
        return -1;
    }
    result = i2cReadDevice(handle, value, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from register 0x%02X: %d\n", reg, result);
        return -1;
    }
    return 0;
}

// Function to initialize the VL53L5CX sensor
int init_sensor(int handle) {
    // Check sensor ID
    uint8_t model_id;
    if (read_register(handle, VL53L5CX_REG_IDENTIFICATION_MODEL_ID, &model_id) != 0) {
        fprintf(stderr, "Error reading sensor ID\n");
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", model_id);
        return -1;
    }

    // Configure for continuous ranging mode (example - adjust as needed)
    if (write_register(handle, VL53L5CX_REG_RANGING_MODE, 0x01) != 0) {
        fprintf(stderr, "Error configuring ranging mode\n");
        return -1;
    }

    // Start continuous ranging
    if (write_register(handle, VL53L5CX_REG_START_STOP_CONTROL, 0x01) != 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Function to read distance data from the VL53L5CX sensor
int read_distance_data(int handle, uint16_t *distances) {
    // Read distance data for each zone (64 zones)
    for (int i = 0; i < 64; i++) {
        uint8_t reg_low, reg_high;
        if (read_register(handle, VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 2 * i, &reg_low) != 0) {
            fprintf(stderr, "Error reading distance data (low byte) for zone %d\n", i);
            return -1;
        }
        if (read_register(handle, VL53L5CX_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 + 2 * i + 1, &reg_high) != 0) {
            fprintf(stderr, "Error reading distance data (high byte) for zone %d\n", i);
            return -1;
        }
        distances[i] = (reg_high << 8) | reg_low;
    }
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(1, VL53L5CX_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor(i2c_handle) != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    uint16_t distances[64];
    while (1) {
        // Read distance data
        if (read_distance_data(i2c_handle, distances) == 0) {
            // Log the distances to the console
            for (int i = 0; i < 64; i++) {
                printf("Zone %d: %d mm\n", i, distances[i]);
            }
        } else {
            fprintf(stderr, "Error reading distance data\n");
        }

        // Wait 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    gpioTerminate();
    return 0;
}

