int read_distance(uint16_t *distance) {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1;
    }

    *distance = (buf[0] << 8) | buf[1];
    return 0;
