        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup resources before exiting
    cleanup();

    printf("Program terminated.\n");
    return 0;
}

