// Read distance from VL53L4CX sensor
int read_distance(int *distance) {
    char cmd[1] = {0x00}; // Example command to trigger a measurement
    char data[2]; // Example buffer to store the distance data

    int status = i2cWriteDevice(i2c_handle, cmd, 1);
    if (status != 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", status);
        return -1;
    }

    gpioDelay(10); // Wait for measurement to complete (adjust as needed)

    status = i2cReadDevice(i2c_handle, data, 2);
    if (status != 2) {
        fprintf(stderr, "Error reading distance data: %d\n", status);
        return -1;
    }

    *distance = (data[0] << 8) | data[1]; // Combine the two bytes into a 16-bit distance value

    return 0;
}

// Log data to console with timestamp
void log_data(int distance) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&ts.tv_sec));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ld", ts.tv_nsec / 1000);

    printf("Timestamp: %s, Distance: %d mm\n", timestamp, distance);
}

