        status = i2cWriteDevice(i2c_handle, &status_reg, 1);
        if (status != 0) {
            fprintf(stderr, "Error writing to interrupt status register: %d\n", status);
            break; // Exit loop on I2C error
        }

        gpioDelay(500); // 500ms delay

        status = i2cReadDevice(i2c_handle, status_data, 1);
        if (status != 1) {
            fprintf(stderr, "Error reading interrupt status: %d\n", status);
            break; // Exit loop on I2C error
        }

        // Check if the interrupt status bit is set
        if (status_data[0] & 0x01) {
            // Clear the interrupt by writing to the interrupt clear register
            char clear_reg = VL53L4CX_REG_SYSTEM_INTERRUPT_CLEAR;
            char clear_data[1] = {0x01}; // Example value to clear the interrupt

            status = i2cWriteDevice(i2c_handle, &clear_reg, 1);
            if (status != 0) {
                fprintf(stderr, "Error writing to interrupt clear register: %d\n", status);
                break; // Exit loop on I2C error
            }

            gpioDelay(1); // Small delay after clearing the interrupt
        }
    }

    // Close I2C connection and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
