// Read distance from VL53L1X sensor
int read_distance() {
    uint8_t data[2];
    int retries = 0;
    int distance = -1; // Default to -1 to indicate error

    while (retries < MAX_RETRIES) {
        if (i2c_read_i2c_block_data(i2c_handle, VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0, (char *)data, 2) == 2) {
            distance = (data[0] << 8) | data[1];
            return distance;
        } else {
            fprintf(stderr, "Error reading distance, retrying (%d/%d)\n", retries + 1, MAX_RETRIES);
            retries++;
            usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
        }
    }

    fprintf(stderr, "Failed to read distance after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure
}

// Log distance to message queue
void log_distance(int distance) {
    message_t message;
    message.mtype = 1; // Message type for distance
    message.distance = distance;

    if (msgsnd(message_queue_id, &message, sizeof(message.distance), 0) == -1) {
        perror("Error sending message to queue");
    }
}

// Activate buzzer
void activate_buzzer() {
    gpioWrite(BUZZER_GPIO, 1); // Turn buzzer on
    usleep(500000);           // Wait for 500ms
    gpioWrite(BUZZER_GPIO, 0); // Turn buzzer off
}

// Deactivate buzzer
void deactivate_buzzer() {
    gpioWrite(BUZZER_GPIO, 0); // Ensure buzzer is off
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        close(i2c_handle);
    }
    if (message_queue_id >= 0) {
        msgctl(message_queue_id, IPC_RMID, NULL);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer GPIO as output
    gpioSetMode(BUZZER_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        cleanup();
        return 1;
    }

    // Create message queue
    message_queue_id = msgget(MESSAGE_QUEUE_KEY, IPC_CREAT | 0666);
    if (message_queue_id < 0) {
        perror("Error creating message queue");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int distance = read_distance();

        if (distance != -1) {
            log_distance(distance);

            if (distance < DISTANCE_THRESHOLD) {
                activate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read distance, skipping buzzer activation\n");
        }

        usleep(500000); // 500ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

