#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 27
#define BUZZER_PIN 22

// Define constants
#define SPEED_OF_SOUND 34300 // cm/s
#define TIMEOUT_US 50000      // 50ms timeout
#define DISTANCE_MIN 2.0      // cm
#define DISTANCE_MAX 400.0    // cm
#define DISTANCE_THRESHOLD 30.0 // cm

// Global variables
volatile unsigned int start_tick = 0;
volatile unsigned int end_tick = 0;
volatile int echo_received = 0;
volatile int running = 1;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, unsigned int tick);
float calculate_distance(unsigned int start_tick, unsigned int end_tick);
void control_buzzer(float distance);
void signal_handler(int signal);

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1;
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0;
    }
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to calculate the distance in centimeters
float calculate_distance(unsigned int start_tick, unsigned int end_tick) {
    if (end_tick < start_tick) {
        // Handle tick wraparound
        return -1.0; // Indicate error
    }

    unsigned int diff = end_tick - start_tick;
    float time_taken = (float)diff / 1000000.0; // Convert us to s
    float distance = (time_taken * SPEED_OF_SOUND) / 2.0;

    return distance;
}

// Function to control the buzzer
void control_buzzer(float distance) {
    if (distance >= 0 && distance <= DISTANCE_MAX) {
        if (distance < DISTANCE_THRESHOLD) {
            gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
        } else {
            gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
        }
    } else {
        fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioTerminate(); // Terminate pigpio
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Register interrupt handler for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set alert function for echo pin\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Parking sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_sensor();

        // Wait for echo to be received or timeout
        int timeout = 0;
        while (!echo_received && timeout < TIMEOUT_US) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            timeout++;
        }

        if (!echo_received) {
            fprintf(stderr, "Timeout waiting for echo\n");
        } else {
            float distance = calculate_distance(start_tick, end_tick);
            if (distance < 0) {
                fprintf(stderr, "Error calculating distance\n");
            } else {
                printf("Distance: %.2f cm\n", distance);
                control_buzzer(distance);
            }
        }

        gpioDelay(100); // 100 ms delay
    }

    return 0;
}

