#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define SERVO_GPIO 18
#define DISTANCE_THRESHOLD 200 // mm
#define SERVO_OPEN_PULSEWIDTH 1500 // us
#define SERVO_CLOSE_PULSEWIDTH 1000 // us
#define SERVO_RANGE 2000 // us
#define SERVO_MIN_PULSEWIDTH 500 // us
#define SERVO_MAX_PULSEWIDTH 2500 // us
#define UDP_PORT 5000
#define LOG_FILE "gate_log.txt"
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
int udp_socket;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void open_gate();
void close_gate();
void log_event(const char *message);
void handle_udp_command(const char *command);
void signal_handler(int signal);
void cleanup();

// VL53L1X register addresses (example, adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050
#define VL53L1X_REG_SYSTEM_START 0x0000
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    int retries = 0;
    int status;

    // Reset the sensor
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, 0x88, 0x00); // Soft reset
        if (status == 0) {
            gpioDelay(100); // Wait for reset to complete
            return 0; // Success
        } else {
            log_event("Error: Failed to reset VL53L1X (attempt 1).");
            retries++;
            gpioDelay(100); // Wait before retrying
        }
    }
    log_event("Error: Failed to reset VL53L1X after multiple retries.");
    return -1; // Failure
}

// Function to read the distance from the VL53L1X sensor
int read_distance() {
    int retries = 0;
    int distance = -1; // Default to -1 to indicate error

    while (retries < MAX_RETRIES) {
        distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
        if (distance >= 0) {
            return distance; // Success
        } else {
            log_event("Error: Failed to read distance (attempt 1).");
            retries++;
            gpioDelay(100); // Wait before retrying
        }
    }
    log_event("Error: Failed to read distance after multiple retries.");
    return -1; // Failure
}

// Function to open the gate
void open_gate() {
    gpioServo(SERVO_GPIO, SERVO_OPEN_PULSEWIDTH);
    log_event("Gate opened.");
}

// Function to close the gate
void close_gate() {
    gpioServo(SERVO_GPIO, SERVO_CLOSE_PULSEWIDTH);
    log_event("Gate closed.");
}

// Function to log events to a file
void log_event(const char *message) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to handle UDP commands
void handle_udp_command(const char *command) {
    if (strcmp(command, "open") == 0) {
        open_gate();
    } else if (strcmp(command, "close") == 0) {
        close_gate();
    } else if (strcmp(command, "status") == 0) {
        int distance = read_distance();
        if (distance >= 0) {
            char status_message[100];
            snprintf(status_message, sizeof(status_message), "Distance: %d mm", distance);
            log_event(status_message);
            send(udp_socket, status_message, strlen(status_message), 0);
        } else {
            log_event("Error: Failed to read distance for status.");
            send(udp_socket, "Error: Failed to read distance for status.", strlen("Error: Failed to read distance for status."), 0);
        }
    } else {
        log_event("Error: Invalid command.");
        send(udp_socket, "Error: Invalid command.", strlen("Error: Invalid command."), 0);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event("Signal received, shutting down...");
}

// Cleanup function to release resources
void cleanup() {
    log_event("Cleaning up...");
    close_gate(); // Ensure gate is closed on exit
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (udp_socket >= 0) {
        close(udp_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    log_event("Cleanup complete.");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        log_event("Error: Failed to open I2C connection.");
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() != 0) {
        log_event("Error: VL53L1X initialization failed.");
        cleanup();
        return 1;
    }

    // Set servo GPIO as output
    gpioSetMode(SERVO_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO_GPIO, 50); // 50 Hz

    // Set PWM range
    gpioSetPWMrange(SERVO_GPIO, SERVO_RANGE);

    // Create UDP socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        log_event("Error: Failed to create UDP socket.");
        fprintf(stderr, "Error creating socket: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Set UDP port
    struct sockaddr_in server_addr;
    server_addr.sin_family = AF_INET;
    server_addr.sin_port = htons(UDP_PORT);
