#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    int retries = 0;
    int status;

    // Reset the sensor
    while (retries < MAX_RETRIES) {
        status = i2cWriteByteData(i2c_handle, 0x88, 0x00); // Soft reset
        if (status == 0) {
            gpioDelay(100); // Wait for reset to complete
            return 0; // Success
        } else {
            log_event("Error: Failed to reset VL53L1X (attempt 1).");
            retries++;
            gpioDelay(100); // Wait before retrying
        }
    }
    log_event("Error: Failed to reset VL53L1X after multiple retries.");
    return -1; // Failure
}

// Function to read the distance from the VL53L1X sensor
int read_distance() {
    int retries = 0;
    int distance = -1; // Default to -1 to indicate error

    while (retries < MAX_RETRIES) {
        distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RANGING_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
