#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 30000       // 30ms timeout
#define LOG_FILE "distance_log.txt"

// Global variables
static volatile uint32_t rising_tick = 0;
static volatile uint32_t falling_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, uint32_t tick);
double calculate_distance(uint32_t pulse_duration);
void log_distance(double distance);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (gpio == ECHO_PIN) {
        if (level == 1) {
            rising_tick = tick;
            echo_received = 1;
        } else if (level == 0 && echo_received) {
            falling_tick = tick;
            echo_received = 0;
        }
    }
}

// Function to calculate distance in centimeters
double calculate_distance(uint32_t pulse_duration) {
    if (pulse_duration == 0) {
        return -1.0; // Indicate timeout
    }
    return (pulse_duration * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log distance to file
void log_distance(double distance) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);

    if (distance >= 0) {
        fprintf(log_file, "%s,%.2f\n", buf, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "%s,WARNING: Timeout or no object detected\n", buf);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetPullUpDown(ECHO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();
        gpioDelay(200); // 200 ms delay

        // Check for timeout
        if (rising_tick == 0 && falling_tick == 0) {
            log_distance(-1.0); // Log timeout
            gpioDelay(100); // Small delay before next trigger
            continue;
        }

        // Calculate pulse duration
        uint32_t pulse_duration = falling_tick - rising_tick;

        // Check for valid pulse duration
        if (pulse_duration > TIMEOUT_US) {
            log_distance(-1.0); // Log timeout
            gpioDelay(100); // Small delay before next trigger
            continue;
        }

        // Calculate distance
        double distance = calculate_distance(pulse_duration);

        // Log distance
        log_distance(distance);

        // Reset rising and falling tick
        rising_tick = 0;
        falling_tick = 0;

        gpioDelay(100); // Small delay before next trigger
    }

    // Cleanup
    printf("Cleaning up...\n");
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

