#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// GPIO pins for gate control
#define GATE_OPEN_PIN 18
#define GATE_CLOSE_PIN 19

// I2C handle
int i2c_handle;

// File pointer for logging
FILE *log_file;

// Function prototypes
int vl53l1x_init(int i2c_handle);
int vl53l1x_start_ranging(int i2c_handle);
int vl53l1x_read_distance(int i2c_handle, uint16_t *distance);
void control_gate(int open_pin, int close_pin, int distance);
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X register addresses (example, adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID  0x00c0
#define VL53L1X_REG_RANGING_MEASUREMENT_DATA_READY 0x0014
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to initialize the VL53L1X sensor
int vl53l1x_init(int i2c_handle) {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, 0x0080, 0x00) < 0) {
        log_event("Error: Failed to reset VL53L1X");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure timing budget (example: 100ms)
    if (i2cWriteByteData(i2c_handle, 0x0088, 0x00) < 0) {
        log_event("Error: Failed to write timing budget");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x0089, 0x00) < 0) {
        log_event("Error: Failed to write timing budget");
        return -1;
    }

    // Start ranging
    if (vl53l1x_start_ranging(i2c_handle) < 0) {
        log_event("Error: Failed to start ranging");
        return -1;
    }

    return 0;
}

// Function to start ranging on the VL53L1X sensor
int vl53l1x_start_ranging(int i2c_handle) {
    if (i2cWriteByteData(i2c_handle, 0x0000, 0x01) < 0) {
        log_event("Error: Failed to start ranging");
        return -1;
    }
    return 0;
}

// Function to read the distance from the VL53L1X sensor
int vl53l1x_read_distance(int i2c_handle, uint16_t *distance) {
    int range_status;
    int distance_mm;

    // Read range status
    range_status = i2cReadByteData(i2c_handle, VL53L1X_REG_RESULT_RANGE_STATUS);
    if (range_status < 0) {
        log_event("Error: Failed to read range status");
        return -1;
    }

    // Read distance
    distance_mm = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance_mm < 0) {
        log_event("Error: Failed to read distance");
        return -1;
    }

    *distance = (uint16_t)distance_mm;
    return 0;
}

// Function to control the gate based on distance
void control_gate(int open_pin, int close_pin, int distance) {
    if (distance < 200) {
        gpioWrite(open_pin, 0); // Close gate
        gpioWrite(close_pin, 1); // Open gate
        log_event("Gate opened");
    } else {
        gpioWrite(open_pin, 1); // Open gate
        gpioWrite(close_pin, 0); // Close gate
        log_event("Gate closed");
    }
}

// Function to log events to a file
void log_event(const char *event) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C handle
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Reset GPIO pins
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    gpioSetMode(GATE_OPEN_PIN, PI_INPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_INPUT);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("gate_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;

    // Main loop
    while (1) {
        // Read distance
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            // Control gate
            control_gate(GATE_OPEN_PIN, GATE_CLOSE_PIN, distance);
        } else {
            log_event("Error: Failed to read distance, retrying...");
        }

        // Wait 500ms
        gpioDelay(500);
    }

    return 0;
}

