    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s: %s\n", timestamp, event);
    fflush(log_file); // Ensure immediate write to file
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Close I2C handle
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Reset GPIO pins
    gpioWrite(GATE_OPEN_PIN, 0);
    gpioWrite(GATE_CLOSE_PIN, 0);
    gpioSetMode(GATE_OPEN_PIN, PI_INPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_INPUT);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (vl53l1x_init(i2c_handle) < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(GATE_OPEN_PIN, PI_OUTPUT);
    gpioSetMode(GATE_CLOSE_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("gate_events.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t distance;

    // Main loop
    while (1) {
        // Read distance
        if (vl53l1x_read_distance(i2c_handle, &distance) == 0) {
            // Control gate
            control_gate(GATE_OPEN_PIN, GATE_CLOSE_PIN, distance);
        } else {
            log_event("Error: Failed to read distance, retrying...");
        }

        // Wait 500ms
        gpioDelay(500);
    }

    return 0;
}

