    if (i2cWriteByteData(i2c_handle, 0x0080, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to write soft reset command.\n");
        return -1;
    }
    gpioDelay(1); // Delay for reset to complete

    // Configure GPIO1 for interrupt
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_SYSTEM_MODE_GPIO1, 0x01) < 0) {
