#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS "/dev/i2c-1"
#define MPR121_ADDR 0x5A
#define LED_GPIO 17
#define LED_GPIO_2 18
#define LED_GPIO_3 27
#define LED_GPIO_4 22
#define LED_PATTERN_SIZE 4
#define POLL_INTERVAL_MS 50
#define LOG_FILE "proximity_log.txt"

// Global variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Function prototypes
int mpr121_init();
int mpr121_read_touch_status(uint16_t *touch_status);
void log_proximity_event(uint16_t touch_status);
void set_led_pattern(uint8_t pattern);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = false;
}

// MPR121 initialization function
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_fd, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121. Error code: %d\n", errno);
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure electrode sensitivity (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_fd, 0x41 + (i * 2), 0x0A) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d. Error code: %d\n", i, errno);
            return -1;
        }
        if (i2cWriteByteData(i2c_fd, 0x42 + (i * 2), 0x05) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d. Error code: %d\n", i, errno);
            return -1;
        }
    }

    // Configure MPR121 to enable all electrodes
    if (i2cWriteByteData(i2c_fd, 0x5E, 0x0C) < 0) { // Enable all electrodes
        fprintf(stderr, "Error: Failed to enable all electrodes. Error code: %d\n", errno);
        return -1;
    }

    // Configure MPR121 to enter run mode
    if (i2cWriteByteData(i2c_fd, 0x5B, 0x01) < 0) { // Enter run mode
        fprintf(stderr, "Error: Failed to enter run mode. Error code: %d\n", errno);
        return -1;
    }

    return 0;
}

// MPR121 read touch status function
int mpr121_read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_fd, 0x00, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status. Error code: %d\n", errno);
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Log proximity event function
void log_proximity_event(uint16_t touch_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s - Touch status: 0x%04X\n", timestamp, touch_status);
    fflush(log_file); // Ensure data is written to file immediately
}

// Set LED pattern function
void set_led_pattern(uint8_t pattern) {
    gpioWrite(LED_GPIO, (pattern >> 0) & 1);
    gpioWrite(LED_GPIO_2, (pattern >> 1) & 1);
    gpioWrite(LED_GPIO_3, (pattern >> 2) & 1);
    gpioWrite(LED_GPIO_4, (pattern >> 3) & 1);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. Error code: %d\n", errno);
        gpioTerminate();
        return 1;
    }

    // Specify slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to acquire bus access and/or talk to slave. Error code: %d\n", errno);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file. Error code: %d\n", errno);
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(LED_GPIO, PI_OUTPUT);
    gpioSetMode(LED_GPIO_2, PI_OUTPUT);
    gpioSetMode(LED_GPIO_3, PI_OUTPUT);
    gpioSetMode(LED_GPIO_4, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;
    uint8_t led_pattern = 0;

    printf("Proximity-based art installation started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        if (mpr121_read_touch_status(&touch_status) == 0) {
            for (int i = 0; i < 12; i++) {
                if (touch_status & (1 << i)) {
                    led_pattern |= (1 << i);
                }
            }
            set_led_pattern(led_pattern);
            log_proximity_event(touch_status);
        } else {
            fprintf(stderr, "Error: Failed to read touch status, retrying...\n");
        }

        gpioDelay(POLL_INTERVAL_MS);
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_led_pattern(0); // Turn off LEDs
    fclose(log_file);
    close(i2c_fd);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

