#define TIMEOUT_US 500000      // 500ms timeout
#define MIN_DISTANCE 5.0       // cm
#define MAX_DISTANCE 400.0      // cm

// Global variables
static volatile unsigned int start_tick = 0;
static volatile unsigned int end_tick = 0;
static volatile int echo_received = 0;
static FILE *log_file = NULL;
static volatile int running = 1;

// Function prototypes
void trigger_pulse();
void echo_callback(int gpio, int level, unsigned int tick);
double calculate_distance(unsigned int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_pulse() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, unsigned int tick) {
    if (level == 1) {
        start_tick = tick;
        echo_received = 1;
    } else if (level == 0 && echo_received) {
        end_tick = tick;
        echo_received = 0;
    }
}

// Function to calculate distance in centimeters
double calculate_distance(unsigned int pulse_width) {
    if (pulse_width == 0) {
        return -1.0; // Indicate invalid pulse width
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log distance to file
void log_distance(double distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Disable ISR
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_pulse();

        // Wait for echo to be received with timeout
        int timeout_count = 0;
        while (!echo_received && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            timeout_count++;
        }

        if (!echo_received) {
            fprintf(stderr, "Timeout waiting for echo.\n");
            continue; // Skip to the next iteration
        }

        // Calculate pulse width
        unsigned int pulse_width = end_tick - start_tick;

        // Calculate distance
        double distance = calculate_distance(pulse_width);

        if (distance >= MIN_DISTANCE && distance <= MAX_DISTANCE) {
            // Log distance
            log_distance(distance);
            printf("Distance: %.2f cm\n", distance);
        } else {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
        }

        // Reset echo received flag
        echo_received = 0;

        gpioDelay(100000); // 100ms delay
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioSetISRFuncEx(ECHO_PIN, EITHER_EDGE, 0, NULL, NULL);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

