#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define XSHUT_GPIO 27
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_distance(int *distance);
void log_data(int distance, int status);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Function to initialize the VL53L1X sensor
int initialize_sensor() {
    // Set XSHUT pin as output
    gpioSetMode(XSHUT_GPIO, PI_OUTPUT);
    gpioWrite(XSHUT_GPIO, 1); // Deactivate sensor initially

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        gpioTerminate();
        return -1;
    }

    // Verify sensor ID (example, adjust as needed)
    char id[2];
    if (i2cReadDevice(i2c_handle, id, 2) != 2) {
        syslog(LOG_ERR, "Failed to read sensor ID");
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    if (id[0] != 0xEE || id[1] != 0xAA) {
        syslog(LOG_ERR, "Incorrect sensor ID: 0x%02X 0x%02X", id[0], id[1]);
        i2cClose(i2c_handle);
        gpioTerminate();
        return -1;
    }

    syslog(LOG_INFO, "Sensor initialized successfully");
    return 0;
}

// Function to read distance from the VL53L1X sensor
int read_distance(int *distance) {
    char cmd[1] = {0x00}; // Example command to trigger a single measurement
    char data[2];
    int status;

    // Send command to trigger measurement
    if (i2cWriteDevice(i2c_handle, cmd, 1) != 1) {
        syslog(LOG_ERR, "Failed to write to I2C device");
        return -1;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10); // 10ms delay

    // Read distance data
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        syslog(LOG_ERR, "Failed to read distance data");
        return -1;
    }

    // Combine the two bytes into a single distance value
    *distance = (data[0] << 8) | data[1];

    return 0;
}

// Function to log data to the systemd journal
void log_data(int distance, int status) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (status == 0) {
        syslog(LOG_INFO, "%s - Distance: %d mm, Status: OK", timestamp, distance);
    } else {
        syslog(LOG_ERR, "%s - Distance: %d mm, Status: ERROR", timestamp, distance);
    }
}

int main() {
    // Open syslog
    openlog("vl53l1x_sensor", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        syslog(LOG_ERR, "Sensor initialization failed, exiting");
        closelog();
        return 1;
    }

    int distance;
    int status;

    // Main loop
    while (!terminate) {
        // Read distance from the sensor
        status = read_distance(&distance);

        if (status == 0) {
            // Log the data
            log_data(distance, status);
        } else {
            syslog(LOG_ERR, "Failed to read distance, retrying...");
        }

        // Wait for 100ms
        gpioDelay(100); // 100ms delay
    }

    // Close I2C device and terminate pigpio library
    i2cClose(i2c_handle);
    gpioTerminate();

    // Close syslog
    closelog();

    return 0;
}

