#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>
#include <math.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 2400.0    // cm
#define SERVO_MIN_PULSEWIDTH 500  // us
#define SERVO_MAX_PULSEWIDTH 2500 // us
#define SERVO_MIN_ANGLE 0       // degrees
#define SERVO_MAX_ANGLE 180     // degrees
#define MOVING_AVG_SIZE 5
#define LOG_FILE "distance_log.csv"

// Global variables
volatile unsigned int pulse_width = 0;
volatile int new_pulse = 0;
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Moving average filter
float distance_buffer[MOVING_AVG_SIZE];
int buffer_index = 0;

// Function prototypes
void trigger_sensor();
void echo_callback(int gpio, int level, uint32_t tick);
float calculate_distance(unsigned int pulse_width);
float moving_average(float new_distance);
int set_servo_angle(int angle);
int log_data(float distance, int angle);
void signal_handler(int signal);
int initialize_gpio();
int cleanup_gpio();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(SERVO_PIN, 50); // Set PWM frequency to 50 Hz
    gpioSetPWMrange(SERVO_PIN, 2000000); // Set PWM range to 2000000 (2ms)

    return 0;
}

// Function to cleanup GPIO pins
int cleanup_gpio() {
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();
    return 0;
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Callback function for echo pin
void echo_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_width = tick;
        new_pulse = 1;
    }
}

// Function to calculate distance in centimeters
float calculate_distance(unsigned int pulse_width) {
    if (pulse_width == 0) {
        return -1.0; // Indicate invalid reading
    }
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to calculate moving average
float moving_average(float new_distance) {
    distance_buffer[buffer_index] = new_distance;
    buffer_index = (buffer_index + 1) % MOVING_AVG_SIZE;

    float sum = 0.0;
    for (int i = 0; i < MOVING_AVG_SIZE; i++) {
        sum += distance_buffer[i];
    }
    return sum / MOVING_AVG_SIZE;
}

// Function to set servo angle
int set_servo_angle(int angle) {
    if (angle < SERVO_MIN_ANGLE || angle > SERVO_MAX_ANGLE) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return -1;
    }

    int pulsewidth = (int)((float)(angle - SERVO_MIN_ANGLE) / (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) * (SERVO_MAX_PULSEWIDTH - SERVO_MIN_PULSEWIDTH) + SERVO_MIN_PULSEWIDTH);
    gpioServo(SERVO_PIN, pulsewidth);
    return 0;
}

// Function to log data to CSV file
int log_data(float distance, int angle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, distance, angle);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

