    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup_gpio();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (cm),Servo Angle (degrees)\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Register alert function for echo pin
    if (gpioSetAlertFuncEx(ECHO_PIN, echo_callback, NULL) != 0) {
        fprintf(stderr, "Error setting alert function\n");
        fclose(log_file);
        cleanup_gpio();
        return 1;
    }

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    while (program_running) {
        trigger_sensor();

        // Wait for echo to be ready with timeout
        int timeout_count = 0;
        while (!new_pulse && timeout_count < 1000) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            timeout_count++;
        }

        if (!new_pulse) {
            fprintf(stderr, "Timeout waiting for echo\n");
            log_data(-1.0, -1); // Log invalid reading
            set_servo_angle(90); // Set servo to 90 degrees
            gpioDelay(100); // Small delay
            continue;
        }

        new_pulse = 0; // Reset flag

        unsigned int pulse_width = gpioTick(); // Get pulse width

        float distance = calculate_distance(pulse_width);
        if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
            fprintf(stderr, "Invalid distance reading: %.2f cm\n", distance);
            log_data(-1.0, -1); // Log invalid reading
            set_servo_angle(90); // Set servo to 90 degrees
            gpioDelay(100); // Small delay
            continue;
        }

        float filtered_distance = moving_average(distance);

        int angle = (int)((filtered_distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE) * (SERVO_MAX_ANGLE - SERVO_MIN_ANGLE) + SERVO_MIN_ANGLE);

        if (set_servo_angle(angle) != 0) {
            fprintf(stderr, "Error setting servo angle\n");
        }

        log_data(filtered_distance, angle);

        gpioDelay(100); // Delay between readings
    }

    // Cleanup
    set_servo_angle(90); // Stop the servo
    fclose(log_file);
    cleanup_gpio();

    printf("Program finished.\n");
    return 0;
}

