// VL53L1X I2C address
#define VL53L1X_ADDR 0x29

// GPIO pin for the warning LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 10

// Distance threshold for warning
#define WARNING_THRESHOLD 200

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    int buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_vl53l1x();
int read_distance(int *distance);
void add_to_buffer(CircularBuffer *cb, int value);
int get_average_distance(CircularBuffer *cb);
void control_led(int average_distance);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, int value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Get the average distance from the circular buffer
int get_average_distance(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0; // Return 0 if the buffer is empty
    }

    int sum = 0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

