#define LOG_FILE "proximity.log"
#define MAX_RETRIES 3

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c(int i2c_bus, int i2c_address);
int init_gpio(int gpio_pin);
int init_sensor(int i2c_fd);
int read_proximity(int i2c_fd);
int compare_threshold(int proximity_value, int threshold);
int log_data(FILE *log_file, int proximity_value, const char *status);
void interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int gpio_pin;
    int proximity_threshold;
} sensor_config_t;

// Function to initialize I2C
int init_i2c(int i2c_bus, int i2c_address) {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", i2c_bus);
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, i2c_address) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        i2c_fd = -1;
        return -1;
    }

    return 0;
}

// Function to initialize GPIO
int init_gpio(int gpio_pin) {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(gpio_pin, PI_INPUT);
    gpioSetPullUpDown(gpio_pin, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

