#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define PWM_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define MIN_DISTANCE 2.0      // cm
#define MAX_DISTANCE 200.0     // cm
#define MIN_FREQUENCY 200.0   // Hz
#define MAX_FREQUENCY 2000.0  // Hz
#define PWM_RANGE 1000000      // 1 MHz PWM range
#define TIMEOUT_US 200000      // 200 ms timeout

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long getPulseWidth();
float calculateDistance(long pulseWidth);
float calculateFrequency(float distance);
void setPWMFrequency(float frequency);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long getPulseWidth() {
    long startTime = 0, endTime = 0;
    long pulseWidth = 0;

    // Wait for the echo pin to go high (with timeout)
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal timeout (high)\n");
        return -1; // Indicate timeout error
    }

    startTime = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }

    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo signal timeout (low)\n");
        return -1; // Indicate timeout error
    }

    endTime = gpioTick();

    pulseWidth = endTime - startTime;

    return pulseWidth;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    if (pulseWidth <= 0) {
        return -1.0; // Indicate error
    }
    return (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to calculate the frequency in Hz
float calculateFrequency(float distance) {
    if (distance < MIN_DISTANCE || distance > MAX_DISTANCE) {
        return 0.0; // Out of range
    }

    // Logarithmic scale
    float frequency = MIN_FREQUENCY * pow(MAX_FREQUENCY / MIN_FREQUENCY, 1.0 - (distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE));
    return frequency;
}

// Function to set the PWM frequency
void setPWMFrequency(float frequency) {
    if (frequency <= 0.0) {
        gpioPWM(PWM_PIN, 0); // Stop PWM if frequency is 0
        return;
    }

    int period = 1000000 / frequency; // Calculate period in microseconds
    gpioSetPWMfrequency(PWM_PIN, frequency);
    gpioSetPWMrange(PWM_PIN, period);
    gpioPWM(PWM_PIN, period / 2); // 50% duty cycle
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(PWM_PIN, PI_OUTPUT);

    // Set PWM range
    gpioSetPWMrange(PWM_PIN, PWM_RANGE);

    // Set PWM frequency to 0 initially
    gpioPWM(PWM_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signalHandler);
    signal(SIGTERM, signalHandler);

    printf("Ultrasonic Theremin started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        long pulseWidth = getPulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulseWidth);

        // Calculate the frequency
        float frequency = calculateFrequency(distance);

        // Set the PWM frequency
        setPWMFrequency(frequency);

        // Print the distance and frequency (for debugging)
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        // Delay to avoid excessive CPU usage
        gpioDelay(10); // 10 ms delay
    }

    // Stop PWM and terminate pigpio
    gpioPWM(PWM_PIN, 0);
    gpioTerminate();

    printf("Ultrasonic Theremin stopped.\n");

    return 0;
}

