// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define BUZZER_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 100000      // 100ms timeout in microseconds
#define MIN_DISTANCE 5.0       // Minimum distance in cm
#define MAX_DISTANCE 50.0      // Maximum distance in cm
#define MIN_FREQUENCY 200.0    // Minimum frequency in Hz
#define MAX_FREQUENCY 2000.0   // Maximum frequency in Hz

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
void triggerSensor();
long getEchoPulseWidth();
float calculateDistance(long pulseWidth);
float mapDistanceToFrequency(float distance);
void generateTone(float frequency);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, stopping program...\n", signal);
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the echo pulse width with microsecond precision
long getEchoPulseWidth() {
    long startTime = 0, endTime = 0;

    // Wait for the echo pin to go high (with timeout)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (low start)\n");
        return -1; // Indicate timeout error
    }
    startTime = gpioTick();

    // Wait for the echo pin to go low (with timeout)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pulse timeout (high end)\n");
        return -1; // Indicate timeout error
    }
    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) return -1.0; // Indicate error
    return (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map the distance to a frequency in Hz
float mapDistanceToFrequency(float distance) {
    if (distance < MIN_DISTANCE) return MIN_FREQUENCY;
    if (distance > MAX_DISTANCE) return MAX_FREQUENCY;
    return MIN_FREQUENCY + (distance - MIN_DISTANCE) * (MAX_FREQUENCY - MIN_FREQUENCY) / (MAX_DISTANCE - MIN_DISTANCE);
}

// Function to generate a tone on the buzzer using PWM
void generateTone(float frequency) {
    if (frequency <= 0) return; // Avoid division by zero

    // Calculate the period in microseconds
    float period = 1000000.0 / frequency; // Period in microseconds

    // Calculate the duty cycle (50%)
    int dutyCycle = (int)(period / 2.0); // 50% duty cycle

    // Set the PWM frequency and duty cycle
    gpioSetPWMfrequency(BUZZER_PIN, (int)frequency);
    gpioPWM(BUZZER_PIN, dutyCycle);
}

