    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(BUZZER_PIN, 255);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Theremin-like instrument started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Trigger the sensor
        triggerSensor();

        // Measure the echo pulse width
        long pulseWidth = getEchoPulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulseWidth);

        // Map the distance to a frequency
        float frequency = mapDistanceToFrequency(distance);

        // Generate a tone on the buzzer
        generateTone(frequency);

        // Print the measured distance and the resulting frequency
        printf("Distance: %.2f cm, Frequency: %.2f Hz\n", distance, frequency);

        // Wait 10 ms
        gpioDelay(10000); // 10 ms
    }

    // Stop the PWM signal
    gpioPWM(BUZZER_PIN, 0);

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");

    return 0;
}

