#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define constants
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define CS_PIN 8         // GPIO8 (CE0)
#define LOG_FILE "distance_log.csv"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t distance;
    uint16_t status;
} sensor_data_t;

// Function prototypes
int initialize_spi();
int read_sensor_data(sensor_data_t *data);
float convert_to_mm(uint16_t raw_distance);
int log_data(float distance_mm);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI communication
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI channel: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from ICU-20201
int read_sensor_data(sensor_data_t *data) {
    char tx_buffer[2]; // Transmit buffer (dummy data for reading)
    char rx_buffer[4]; // Receive buffer (2 bytes distance, 2 bytes status)

    // Dummy write to trigger the sensor to start reading
    tx_buffer[0] = 0x00; // Dummy byte
    tx_buffer[1] = 0x00; // Dummy byte

    int result = spiXfer(spi_handle, tx_buffer, rx_buffer, 4);
    if (result != 4) {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        return -1;
    }

    // Extract distance and status from the received data
    data->distance = (rx_buffer[0] << 8) | rx_buffer[1];
    data->status = (rx_buffer[2] << 8) | rx_buffer[3];

    return 0;
}

// Convert raw distance data to millimeters
float convert_to_mm(uint16_t raw_distance) {
    // Assuming a linear relationship between raw distance and millimeters
    // This is a placeholder; replace with the actual calibration data
    // from the ICU-20201 datasheet.
    // Example: 200 mm = 0, 5000 mm = 65535
    float distance_mm = (float)raw_distance * 200.0 / 65535.0;
    return distance_mm;
}

// Log data to CSV file
int log_data(float distance_mm) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f\n", timestamp, distance_mm);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    fprintf(stderr, "Cleaning up resources...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set CS pin as output
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the sensor initially

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (mm)\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(&sensor_data) == 0) {
                float distance_mm = convert_to_mm(sensor_data.distance);
                log_data(distance_mm);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Retry %d failed, delaying...\n", retries + 1);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

