    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Distance (mm)\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;
    int retries;

    // Main loop
    while (!terminate) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_sensor_data(&sensor_data) == 0) {
                float distance_mm = convert_to_mm(sensor_data.distance);
                log_data(distance_mm);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Retry %d failed, delaying...\n", retries + 1);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }

        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", MAX_RETRIES);
        }

        gpioDelay(100000); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

