#include <pigpio.h>

// Si1120 I2C address
#define SI1120_ADDR 0x60

// Si1120 register addresses
#define REG_PART_ID 0x00
#define REG_ALS_VIS_DATA0 0x22
#define REG_PS1_DATA0 0x24
#define REG_RESET 0x07

// Reset command value
#define RESET_CMD 0x01

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t proximity;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the Si1120 sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_RESET, RESET_CMD) != 0) {
        fprintf(stderr, "Error: Failed to reset Si1120\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Verify the part ID
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Failed to read part ID\n");
        return -1;
    }

    if (part_id != 0x50) {
        fprintf(stderr, "Error: Incorrect part ID: 0x%02X (expected 0x50)\n", part_id);
        return -1;
    }

    // Add initialization sequence here if needed based on the datasheet
    // For example, writing configuration registers

    return 0;
}

// Reads ambient light and proximity data from the Si1120 sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    uint8_t als_low, als_high, prox_low, prox_high;

    als_low = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0);
    als_high = i2cReadByteData(i2c_handle, REG_ALS_VIS_DATA0 + 1);
    prox_low = i2cReadByteData(i2c_handle, REG_PS1_DATA0);
    prox_high = i2cReadByteData(i2c_handle, REG_PS1_DATA0 + 1);

    if (als_low < 0 || als_high < 0 || prox_low < 0 || prox_high < 0) {
        fprintf(stderr, "Error: Failed to read sensor data\n");
        data.als = 0; // Set to 0 to indicate error
        data.proximity = 0;
        return data;
    }

    data.als = (als_high << 8) | als_low;
    data.proximity = (prox_high << 8) | prox_low;

    return data;
}

// Logs the sensor data to a file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, data.als, data.proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, SI1120_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Error: Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen("si1120_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();

        if (data.als != 0 || data.proximity != 0) {
            log_data(data);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data, skipping logging.\n");
        }

        gpioDelay(500); // Wait 500ms
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

