#include <linux/i2c-dev.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define SI1182_ADDR 0x60

// Define register addresses
#define REG_PART_ID 0x00
#define REG_ALS_RATE 0x08
#define REG_PS_RATE 0x0A
#define REG_ALS_DATA 0x22
#define REG_PS_DATA 0x24

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Structure to hold sensor configuration
typedef struct {
    uint8_t als_rate;
    uint8_t ps_rate;
} sensor_config_t;

// Function prototypes
int init_i2c();
int read_register(uint8_t reg, uint8_t *value);
int write_register(uint8_t reg, uint8_t value);
int verify_sensor();
int read_sensor_data(uint16_t *ambient_light, uint16_t *proximity);
int log_data(uint16_t ambient_light, uint16_t proximity);
void print_data(uint16_t ambient_light, uint16_t proximity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1182_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read a single byte from a register
int read_register(uint8_t reg, uint8_t *value) {
    if (write(i2c_fd, &reg, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(i2c_fd, value, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }

    return 0;
}

// Write a single byte to a register
int write_register(uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }

    return 0;
}

// Verify the sensor by reading the Part ID register
int verify_sensor() {
    uint8_t part_id;
    if (read_register(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error reading Part ID register\n");
        return -1;
    }

    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    printf("Sensor verified: Part ID = 0x%02X\n", part_id);
    return 0;
}

// Read ambient light and proximity data from the sensor
int read_sensor_data(uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t als_data[2];
    uint8_t ps_data[2];

    if (read_register(REG_ALS_DATA, als_data) != 0) {
        fprintf(stderr, "Error reading ALS data\n");
        return -1;
    }

    if (read_register(REG_PS_DATA, ps_data) != 0) {
        fprintf(stderr, "Error reading PS data\n");
        return -1;
    }

    *ambient_light = (als_data[1] << 8) | als_data[0];
    *proximity = (ps_data[1] << 8) | ps_data[0];

    return 0;
}

// Log data to a CSV file
int log_data(uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, ambient_light, proximity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Print data to stdout
void print_data(uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s,%u,%u\n", timestamp, ambient_light, proximity);
}

