        return -1;
    }

    return 0;
}

// Write a single byte to a register
int write_register(uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }

    return 0;
}

// Verify the sensor by reading the Part ID register
int verify_sensor() {
    uint8_t part_id;
    if (read_register(REG_PART_ID, &part_id) != 0) {
        fprintf(stderr, "Error reading Part ID register\n");
        return -1;
    }

    if (part_id != 0x82) {
        fprintf(stderr, "Incorrect Part ID: 0x%02X\n", part_id);
        return -1;
    }

    printf("Sensor verified: Part ID = 0x%02X\n", part_id);
    return 0;
}

// Read ambient light and proximity data from the sensor
int read_sensor_data(uint16_t *ambient_light, uint16_t *proximity) {
    uint8_t als_data[2];
    uint8_t ps_data[2];

    if (read_register(REG_ALS_DATA, als_data) != 0) {
        fprintf(stderr, "Error reading ALS data\n");
        return -1;
    }

    if (read_register(REG_PS_DATA, ps_data) != 0) {
        fprintf(stderr, "Error reading PS data\n");
        return -1;
    }

    *ambient_light = (als_data[1] << 8) | als_data[0];
    *proximity = (ps_data[1] << 8) | ps_data[0];

    return 0;
}

// Log data to a CSV file
int log_data(uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u\n", timestamp, ambient_light, proximity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Print data to stdout
void print_data(uint16_t ambient_light, uint16_t proximity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s,%u,%u\n", timestamp, ambient_light, proximity);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("biometric_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(i2c_fd);
        return 1;
    }

    // Verify the sensor
    if (verify_sensor() != 0) {
        fprintf(stderr, "Sensor verification failed. Exiting.\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Configure the sensor (example: set ALS and PS rates)
    sensor_config_t config = {
        .als_rate = 0x0A, // 100 Hz
        .ps_rate = 0x0A  // 100 Hz
    };

    if (write_register(REG_ALS_RATE, config.als_rate) != 0) {
        fprintf(stderr, "Error writing ALS rate\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    if (write_register(REG_PS_RATE, config.ps_rate) != 0) {
        fprintf(stderr, "Error writing PS rate\n");
        fclose(log_file);
        close(i2c_fd);
        return 1;
    }

    // Main loop
    uint16_t ambient_light, proximity;
    while (program_running) {
        if (read_sensor_data(&ambient_light, &proximity) == 0) {
            log_data(ambient_light, proximity);
            print_data(ambient_light, proximity);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        usleep(100000); // 100 ms
    }

    // Close resources before exiting
    fclose(log_file);
    close(i2c_fd);

    return 0;
}

