#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VL53L1X_ADDR 0x29
#define GPIO_SERVO 18
#define DISTANCE_THRESHOLD_FAR 250 // mm
#define DISTANCE_THRESHOLD_CLOSE 200 // mm
#define SERVO_OPEN_PULSE_WIDTH 1000 // us
#define SERVO_CLOSE_PULSE_WIDTH 2000 // us
#define LOG_FILE "gate_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_vl53l1x();
int read_distance();
void set_servo_pulse_width(int pulse_width);
void log_event(const char *event);
void signal_handler(int signal);

// VL53L1X register addresses (Example - adjust based on datasheet)
#define VL53L1X_REG_IDENTIFICATION_MODEL_ID 0x00c0
#define VL53L1X_REG_TIMING_BUDGET_MSB 0x0081
#define VL53L1X_REG_RANGING_START 0x0004
#define VL53L1X_REG_RESULT_RANGE_STATUS 0x0014
#define VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0 0x0050

// Function to handle signals (e.g., Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the VL53L1X sensor
int init_vl53l1x() {
    // Check sensor ID
    int model_id = i2cReadByteData(i2c_handle, VL53L1X_REG_IDENTIFICATION_MODEL_ID);
    if (model_id < 0) {
        fprintf(stderr, "Error reading model ID: %d\n", model_id);
        return -1;
    }
    if (model_id != 0xEACC) {
        fprintf(stderr, "Incorrect model ID: 0x%02X (expected 0xEACC)\n", model_id);
        return -1;
    }

    // Set timing budget (adjust as needed)
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_TIMING_BUDGET_MSB, 0x01) < 0) {
        fprintf(stderr, "Error writing timing budget\n");
        return -1;
    }

    // Start ranging
    if (i2cWriteByteData(i2c_handle, VL53L1X_REG_RANGING_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL53L1X sensor
int read_distance() {
    int distance = i2cReadWordData(i2c_handle, VL53L1X_REG_RESULT_FINAL_CROSSTALK_CORRECTED_RANGE_MM_SD0);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance: %d\n", distance);
        return -1;
    }
    return distance;
}

// Function to set the servo pulse width
void set_servo_pulse_width(int pulse_width) {
    gpioServo(GPIO_SERVO, pulse_width);
}

// Function to log events to a file
void log_event(const char *event) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, event);
    fflush(log_file); // Ensure the log is written immediately
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, VL53L1X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize VL53L1X sensor
    if (init_vl53l1x() < 0) {
        fprintf(stderr, "VL53L1X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO18 as output for servo control
    gpioSetMode(GPIO_SERVO, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        int distance = read_distance();
        if (distance >= 0) {
            if (distance > DISTANCE_THRESHOLD_FAR) {
                set_servo_pulse_width(SERVO_OPEN_PULSE_WIDTH);
                log_event("Gate opened");
            } else if (distance < DISTANCE_THRESHOLD_CLOSE) {
                set_servo_pulse_width(SERVO_CLOSE_PULSE_WIDTH);
                log_event("Gate closed");
            } else {
                // No change in gate state
            }
        } else {
            // Error reading distance, log the error
            log_event("Error reading distance");
        }

        gpioDelay(100); // Delay for 100ms
    }

    // Cleanup
    set_servo_pulse_width(0); // Stop the servo
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

