#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIGGER_PIN 23
#define ECHO_PIN 24
#define SERVO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout
#define MIN_DISTANCE 2.0       // cm
#define MAX_DISTANCE 400.0      // cm
#define MIN_ANGLE 0.0          // degrees
#define MAX_ANGLE 180.0        // degrees

// Global variables
static volatile int terminate = 0;

// Function prototypes
void triggerSensor();
long getPulseWidth();
float calculateDistance(long pulseWidth);
int mapDistanceToAngle(float distance);
int setServoAngle(int angle);
void signalHandler(int signal);

// Signal handler for graceful shutdown
void signalHandler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to trigger the ultrasonic sensor
void triggerSensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long getPulseWidth() {
    long startTime = 0, endTime = 0;

    // Wait for the echo pin to go high (rising edge)
    int count = 0;
    while (gpioRead(ECHO_PIN) == 0 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pin did not go high (rising edge) within timeout.\n");
        return -1; // Indicate timeout error
    }
    startTime = gpioTick();

    // Wait for the echo pin to go low (falling edge)
    count = 0;
    while (gpioRead(ECHO_PIN) == 1 && count < TIMEOUT_US) {
        count++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (count >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pin did not go low (falling edge) within timeout.\n");
        return -1; // Indicate timeout error
    }
    endTime = gpioTick();

    return endTime - startTime;
}

// Function to calculate the distance in centimeters
float calculateDistance(long pulseWidth) {
    if (pulseWidth < 0) {
        return -1.0; // Indicate timeout error
    }
    return (pulseWidth * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to map the distance to a servo angle
int mapDistanceToAngle(float distance) {
    if (distance < MIN_DISTANCE) {
        return 0;
    } else if (distance > MAX_DISTANCE) {
        return 180;
    } else {
        return (int)(((distance - MIN_DISTANCE) / (MAX_DISTANCE - MIN_DISTANCE)) * 180.0);
    }
}

// Function to set the servo angle
int setServoAngle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Error: Invalid servo angle. Angle must be between 0 and 180 degrees.\n");
        return -1; // Indicate invalid angle
    }

    // Calculate pulse width based on angle (SG90 servo)
    int pulseWidth = 500 + (int)(((float)angle / 180.0) * 2000.0);

    // Set the servo pulse width
    gpioServo(SERVO_PIN, pulseWidth);

    return 0; // Indicate success
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);
    gpioSetMode(SERVO_PIN, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signalHandler);

    printf("Ultrasonic distance measurement started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Trigger the sensor
        triggerSensor();

        // Measure the pulse width
        long pulseWidth = getPulseWidth();

        // Calculate the distance
        float distance = calculateDistance(pulseWidth);

        // Map the distance to an angle
        int angle = mapDistanceToAngle(distance);

        // Set the servo angle
        if (setServoAngle(angle) != 0) {
            fprintf(stderr, "Error: Failed to set servo angle.\n");
        }

        // Print the distance and angle
        printf("Distance: %.2f cm, Angle: %d degrees\n", distance, angle);

        // Wait for 100ms
        gpioDelay(100);
    }

    // Stop the servo
    setServoAngle(0);

    // Terminate pigpio library
    gpioTerminate();

    printf("Ultrasonic distance measurement stopped.\n");

    return 0; // Exit successfully
}

