#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define SI7005_ADDR 0x40
#define CONFIG_REG 0xF3
#define TEMP_MEASURE_CMD 0xE3
#define HUMID_MEASURE_CMD 0xE5
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int configure_sensor();
int read_sensor_data(float *temperature, float *humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SI7005_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configures the Si7005 sensor
int configure_sensor() {
    char buf[2];
    buf[0] = CONFIG_REG;
    buf[1] = 0x00; // Normal mode

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }

    gpioDelay(10000); // 10 ms delay

    return 0;
}

// Reads temperature and humidity data from the Si7005 sensor
int read_sensor_data(float *temperature, float *humidity) {
    char buf[1];
    char data[2];
    int result;

    // Measure temperature
    buf[0] = TEMP_MEASURE_CMD;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write temperature command: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return -1;
    }

    uint16_t raw_temperature = (data[0] << 8) | data[1];
    *temperature = (175.72 * raw_temperature / 65536.0) - 46.85;

    // Measure humidity
    buf[0] = HUMID_MEASURE_CMD;
    result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write humidity command: %d\n", result);
        return -1;
    }
    gpioDelay(10000); // 10 ms delay

    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read humidity data: %d\n", result);
        return -1;
    }

    uint16_t raw_humidity = (data[0] << 8) | data[1];
    *humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

// Logs the temperature and humidity data to the console
void log_data(float temperature, float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, temperature, humidity);
}

// Cleans up resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Configure sensor
    if (configure_sensor() != 0) {
        cleanup();
        return 1;
    }

    float temperature, humidity;

    // Main loop
    while (!terminate) {
        if (read_sensor_data(&temperature, &humidity) == 0) {
            log_data(temperature, humidity);
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        sleep(2);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

