uint8_t crc8(const uint8_t *data, int len);
sensor_data_t process_sensor_data(const uint8_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, SHT40_ADDR, 0); // Bus 1, address 0x44, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send measurement command to SHT40
int send_measurement_command() {
    char cmd[1] = {MEASURE_CMD};
    int result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Wait for measurement (at least 10ms)
    return 0;
}

// Read sensor data from SHT40
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Process sensor data (CRC validation)
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // CRC validation for temperature
    uint8_t temp_data[2] = {data[0], data[1]};
    uint8_t temp_crc = data[2];
    if (crc8(temp_data, 2) != temp_crc) {
        fprintf(stderr, "Temperature CRC check failed!\n");
        sensor_data.temperature = -999.0; // Indicate error
    } else {
        int16_t raw_temperature = (data[0] << 8) | data[1];
        sensor_data.temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);
    }

    // CRC validation for humidity
    uint8_t humidity_data[2] = {data[3], data[4]};
    uint8_t humidity_crc = data[5];
    if (crc8(humidity_data, 2) != humidity_crc) {
        fprintf(stderr, "Humidity CRC check failed!\n");
        sensor_data.humidity = -999.0; // Indicate error
    } else {
        int16_t raw_humidity = (data[3] << 8) | data[4];
        sensor_data.humidity = 100.0 * (float)raw_humidity / 65535.0;
    }

    return sensor_data;
}

// Log sensor data to console
void log_data(sensor_data_t data) {
    if (data.temperature != -999.0 && data.humidity != -999.0) {
        printf("Temperature: %.2f °C, Humidity: %.2f %%\n", data.temperature, data.humidity);
    } else {
        fprintf(stderr, "Error: Invalid sensor data. Skipping logging.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and terminate pigpio
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("SHT40 sensor reader started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint8_t sensor_data[6];

        // Send measurement command
        if (send_measurement_command() == 0) {
            // Read sensor data
            if (read_sensor_data(sensor_data) == 0) {
                // Process sensor data
                sensor_data_t processed_data = process_sensor_data(sensor_data);

                // Log data
                log_data(processed_data);
            }
        } else {
            fprintf(stderr, "Failed to send measurement command. Attempting to re-initialize I2C.\n");
            i2cClose(i2c_handle);
            if (init_i2c() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C. Exiting.\n");
                break; // Exit loop if re-initialization fails
            }
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    printf("SHT40 sensor reader terminated.\n");
    return 0;
}

