    float temperature;
    int status;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
sensor_data_t read_sts30_temperature();
int log_temperature(float temperature);
int log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Reads temperature from the STS30 sensor
sensor_data_t read_sts30_temperature() {
    sensor_data_t data = {0.0, 0};
    char buf[6];
    int result;

    // Send measurement command
    result = i2cWriteWordData(i2c_handle, (MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF);
    if (result != 0) {
        log_error("Failed to write measurement command");
        data.status = -1;
        return data;
    }

    // Wait for measurement (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        log_error("Failed to read temperature data");
        data.status = -1;
        return data;
    }

    // Convert raw data to temperature (Celsius)
    int temp_raw = (buf[0] << 8) | buf[1];
    data.temperature = -45.0 + (175.0 * (float)temp_raw / 65535.0);
    data.status = 0; // Success

    return data;
}

