        fprintf(stderr, "Error opening error log file: %s\n", ERROR_LOG_FILE);
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        log_error("I2C initialization failed");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t sensor_data = read_sts30_temperature();

        if (sensor_data.status == 0) {
            log_temperature(sensor_data.temperature);
        } else {
            log_error("Failed to read temperature, skipping logging.");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

