// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sht40(uint16_t *temperature, uint16_t *humidity);
uint8_t crc8(const uint8_t *data, int len);
