int read_sht40(uint16_t *temperature, uint16_t *humidity) {
    char cmd[1] = {MEASURE_HIGH_REPEATABILITY};
    char buf[6];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for measurement (datasheet specifies 10ms)

    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    *temperature = (buf[0] << 8) | buf[1];
    *humidity = (buf[3] << 8) | buf[4];

    return 0;
}

// CRC-8 checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
