        data.temperature = -999.0; // Indicate error
        data.humidity = -999.0;
        return data;
    }

    // Convert to Celsius and relative humidity
    data.temperature = -45.0 + (175.0 * (float)temp_msb / 65535.0);
    data.humidity = 100.0 * (float)hum_msb / 65535.0;

    return data;
}

