volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor();
int read_sensor_data(uint16_t *temperature, uint16_t *humidity);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
void log_data(float temperature, float humidity);
void print_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the Si7015 sensor
int initialize_sensor() {
    // No specific initialization needed for Si7015 in No Hold Master mode
    return 0; // Success
}

// Reads temperature and humidity data from the Si7015 sensor
int read_sensor_data(uint16_t *temperature, uint16_t *humidity) {
    char buf[2];
    int result;

    // Send temperature measurement command
    result = i2cWriteByteData(i2c_handle, 0, TEMP_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing temperature command: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (at least 20ms)
    gpioDelay(20000); // 20ms

    // Read temperature data
    result = i2cReadI2CBlockData(i2c_handle, 0, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature data: %s\n", strerror(errno));
        return -1;
    }
    *temperature = (buf[0] << 8) | buf[1];

    // Send humidity measurement command
    result = i2cWriteByteData(i2c_handle, 0, HUMID_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Error writing humidity command: %s\n", strerror(errno));
        return -1;
    }

    // Wait for measurement to complete (at least 20ms)
    gpioDelay(20000); // 20ms

    // Read humidity data
    result = i2cReadI2CBlockData(i2c_handle, 0, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading humidity data: %s\n", strerror(errno));
        return -1;
    }
    *humidity = (buf[0] << 8) | buf[1];

    return 0;
}

