    i2c_handle = i2cOpen(I2C_BUS, SI7015_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data with retry mechanism
        int retry = 0;
        while (retry < RETRY_COUNT) {
            result = read_sensor_data(&raw_temperature, &raw_humidity);
            if (result == 0) {
                break; // Success, exit retry loop
            } else {
                fprintf(stderr, "Retry %d failed: %s\n", retry + 1, strerror(errno));
                retry++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries.\n", RETRY_COUNT);
            // Log the error to the file as well
            time_t t = time(NULL);
            struct tm tm = *localtime(&t);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);
            fprintf(log_file, "%s, ERROR: Failed to read sensor data after %d retries.\n", timestamp, RETRY_COUNT);
            fflush(log_file);
        } else {
            // Convert raw data to Celsius and relative humidity
            temperature = convert_temperature(raw_temperature);
            humidity = convert_humidity(raw_humidity);

            // Log data
            log_data(temperature, humidity);

            // Print data
            print_data(temperature, humidity);
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Close I2C bus and log file
    i2cClose(i2c_handle);
    fclose(log_file);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

