#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define STS30_ADDR 0x4A
#define MEASUREMENT_COMMAND 0x2C06
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define LOG_FILE "enclosure_temp_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define SAMPLE_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int send_measurement_command();
int read_sensor_data(uint8_t *data);
uint8_t calculate_crc8(const uint8_t *data, int len);
int validate_crc8(const uint8_t *data, int len, uint8_t crc);
int convert_data(const uint8_t *data, sensor_data_t *sensor_data);
int log_data(const sensor_data_t *sensor_data);
int log_error(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initializes the I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, STS30_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Sends the measurement command to the STS30 sensor
int send_measurement_command() {
    char buf[2];
    buf[0] = (MEASUREMENT_COMMAND >> 8) & 0xFF;
    buf[1] = MEASUREMENT_COMMAND & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 0) {
        log_error("Failed to write measurement command");
        return -1;
    }
    return 0;
}

// Reads the sensor data from the STS30 sensor
int read_sensor_data(uint8_t *data) {
    int result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        log_error("Failed to read sensor data");
        return -1;
    }
    return 0;
}

// Calculates the CRC-8 checksum
uint8_t calculate_crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validates the CRC-8 checksum
int validate_crc8(const uint8_t *data, int len, uint8_t crc) {
    uint8_t calculated_crc = calculate_crc8(data, len);
    if (calculated_crc != crc) {
        char error_message[100];
        snprintf(error_message, sizeof(error_message), "CRC validation failed: calculated 0x%02X, received 0x%02X", calculated_crc, crc);
        log_error(error_message);
        return -1;
    }
    return 0;
}

// Converts the raw sensor data to temperature and humidity
int convert_data(const uint8_t *data, sensor_data_t *sensor_data) {
    int16_t temperature_raw = (data[0] << 8) | data[1];
    int16_t humidity_raw = (data[3] << 8) | data[4];

    sensor_data->temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
    sensor_data->humidity = 100.0 * (float)humidity_raw / 65535.0;

    return 0;
}

// Logs the temperature data to a file
int log_data(const sensor_data_t *sensor_data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, sensor_data->temperature, sensor_data->humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Logs errors to a file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(error_log, "%s, Error: %s\n", timestamp, message);
    fflush(error_log);
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    error_log = fopen(ERROR_LOG_FILE, "a");
    if (error_log == NULL) {
        fprintf(stderr, "Failed to open error log file\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fclose(log_file);
        fclose(error_log);
        gpioTerminate();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint8_t sensor_data[6];
        sensor_data_t sensor_data_struct;

        // Send measurement command
        if (send_measurement_command() != 0) {
            continue; // Skip to the next iteration
        }

        // Wait for conversion (at least 15 ms)
        gpioDelay(20000); // 20 ms

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            continue; // Skip to the next iteration
        }

        // Validate CRC
        if (validate_crc8(sensor_data, 2, sensor_data[2]) != 0) {
            continue; // Skip to the next iteration
        }
        if (validate_crc8(sensor_data + 3, 2, sensor_data[5]) != 0) {
            continue; // Skip to the next iteration
        }

        // Convert data
        if (convert_data(sensor_data, &sensor_data_struct) != 0) {
            continue; // Skip to the next iteration
        }

        // Log data
        if (log_data(&sensor_data_struct) != 0) {
            continue; // Skip to the next iteration
        }

        printf("Temperature: %.2f °C, Humidity: %.2f %%\n", sensor_data_struct.temperature, sensor_data_struct.humidity);

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Convert seconds to microseconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    fclose(error_log);
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");
    return 0;
}

