int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Temperature: %.2f °C, Humidity: %.2f %%\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    printf("Smart Greenhouse Environment Monitor started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        uint8_t sensor_data[6];
        sensor_data_t converted_data;

        // Send measurement command
        if (send_measurement_command() != 0) {
            fprintf(stderr, "Failed to send measurement command. Retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Read sensor data
        if (read_sensor_data(sensor_data) != 0) {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
            gpioDelay(1000); // Wait before retrying
            continue;
        }

        // Convert data
        converted_data = convert_data(sensor_data);

        // Log data
        if (converted_data.temperature != -999.0 && converted_data.humidity != -999.0) {
            log_data(converted_data);
        } else {
            fprintf(stderr, "Failed to convert sensor data. Skipping logging.\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    printf("Smart Greenhouse Environment Monitor stopped.\n");
    return 0;
