    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read temperature from Si7021
int read_temperature(float *temperature) {
    char cmd[1] = {0xE3}; // Command to read temperature
    char buf[2];
    int result;

    for (int i = 0; i < RETRY_COUNT; ++i) {
        result = i2cWriteDevice(i2c_handle, cmd, 1);
        if (result == 0) {
            gpioDelay(20); // Wait for measurement (datasheet specifies 15ms for high repeatability)
            result = i2cReadDevice(i2c_handle, buf, 2);
            if (result == 2) {
                uint16_t raw_temp = (buf[0] << 8) | buf[1];
                *temperature = (175.72 * raw_temp / 65536.0) - 46.85;
                return 0; // Success
            } else {
                fprintf(stderr, "Error reading temperature (attempt %d): %d\n", i + 1, result);
            }
        } else {
            fprintf(stderr, "Error writing temperature command (attempt %d): %d\n", i + 1, result);
