#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define LOG_FILE "air_quality.log"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define SLEEP_INTERVAL_SEC 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the SCD40 sensor
int init_scd40() {
    // Send start periodic measurement command (0x21B1)
    char cmd[2] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to send start periodic measurement command (result = %d)\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to start
    return 0;
}

// Function to read data from the SCD40 sensor
int read_scd40_data(uint16_t *co2, float *temperature, float *humidity) {
    char cmd[2] = {0xE4, 0xB8}; // Read measurement command (0xE4B8)
    char buffer[9];
    int result;

    // Send read measurement command
    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to send read measurement command (result = %d)\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for the sensor to prepare data

    // Read 9 bytes of data
    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        fprintf(stderr, "Error: Failed to read data (result = %d)\n", result);
        return -1;
    }

    // CRC Check for CO2
    uint8_t co2_data[2] = {buffer[0], buffer[1]};
    uint8_t co2_crc = buffer[2];
    if (crc8(co2_data, 2) != co2_crc) {
        fprintf(stderr, "Error: CO2 CRC check failed\n");
        return -1;
    }

    // CRC Check for Temperature
    uint8_t temp_data[2] = {buffer[3], buffer[4]};
    uint8_t temp_crc = buffer[5];
    if (crc8(temp_data, 2) != temp_crc) {
        fprintf(stderr, "Error: Temperature CRC check failed\n");
        return -1;
    }

    // CRC Check for Humidity
    uint8_t humidity_data[2] = {buffer[6], buffer[7]};
    uint8_t humidity_crc = buffer[8];
    if (crc8(humidity_data, 2) != humidity_crc) {
        fprintf(stderr, "Error: Humidity CRC check failed\n");
        return -1;
    }

    // Extract CO2, Temperature, and Humidity values
    *co2 = (buffer[0] << 8) | buffer[1];
    *temperature = -45 + 175 * ((float)((buffer[3] << 8) | buffer[4])) / 65535.0;
    *humidity = 100 * ((float)((buffer[6] << 8) | buffer[7])) / 65535.0;

    return 0;
}

// Function to log data to a file
int log_data(uint16_t co2, float temperature, float humidity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,%u,%.2f,%.2f\n", timestamp, co2, temperature, humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C device (result = %d)\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize SCD40 sensor
    if (init_scd40() != 0) {
        fprintf(stderr, "Error: SCD40 initialisation failed\n");
        fclose(log_file);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(stderr, "SCD40 sensor initialized successfully\n");

    // Main loop
    while (!terminate) {
        uint16_t co2;
        float temperature, humidity;

        // Wait for data ready flag
        char cmd[2] = {0xE4, 0xB8};
        char buffer[2];
        int result;
        int data_ready = 0;

        while (!data_ready) {
            result = i2cWriteDevice(i2c_handle, cmd, 2);
            if (result != 0) {
                fprintf(stderr, "Error: Failed to send data ready command (result = %d)\n", result);
                break;
            }
            gpioDelay(10); // Wait for the sensor to prepare data

            result = i2cReadDevice(i2c_handle, buffer, 2);
            if (result != 2) {
                fprintf(stderr, "Error: Failed to read data ready flag (result = %d)\n", result);
                break;
            }

            if (buffer[0] == 0x00 && buffer[1] == 0x01) {
                data_ready = 1;
            } else {
                gpioDelay(100); // Wait before retrying
            }
        }

        if (!data_ready) {
            fprintf(stderr, "Error: Data not ready after waiting\n");
            continue; // Skip to the next iteration
        }

        // Read sensor data
        if (read_scd40_data(&co2, &temperature, &humidity) == 0) {
            // Log data
            log_data(co2, temperature, humidity);

            printf("CO2: %u ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", co2, temperature, humidity);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        gpioDelay(SLEEP_INTERVAL_SEC * 1000); // Sleep for 5 seconds
    }

    // Stop periodic measurement
    char stop_cmd[2] = {0x3F, 0x86};
    int result = i2cWriteDevice(i2c_handle, stop_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to send stop periodic measurement command (result = %d)\n", result);
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully\n");
    return 0;
}

