            if (result != 2) {
                fprintf(stderr, "Error: Failed to read data ready flag (result = %d)\n", result);
                break;
            }

            if (buffer[0] == 0x00 && buffer[1] == 0x01) {
                data_ready = 1;
            } else {
                gpioDelay(100); // Wait before retrying
            }
        }

        if (!data_ready) {
            fprintf(stderr, "Error: Data not ready after waiting\n");
            continue; // Skip to the next iteration
        }

        // Read sensor data
        if (read_scd40_data(&co2, &temperature, &humidity) == 0) {
            // Log data
            log_data(co2, temperature, humidity);

            printf("CO2: %u ppm, Temperature: %.2f °C, Humidity: %.2f %%\n", co2, temperature, humidity);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

