    }

    // Stop periodic measurement
    char stop_cmd[2] = {0x3F, 0x86};
    int result = i2cWriteDevice(i2c_handle, stop_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error: Failed to send stop periodic measurement command (result = %d)\n", result);
    }

    // Close I2C connection
    i2cClose(i2c_handle);

    // Close log file
    fclose(log_file);

    // Terminate pigpio
    gpioTerminate();

    fprintf(stderr, "Program terminated successfully\n");
    return 0;
}

