#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define LED_GPIO 17
#define CO2_THRESHOLD 1000
#define BUFFER_SIZE 20
#define RETRY_COUNT 3

// Data structure for sensor readings
typedef struct {
    time_t timestamp;
    uint16_t co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Circular buffer structure
typedef struct {
    sensor_data_t buffer[BUFFER_SIZE];
    int head;
    int count;
} circular_buffer_t;

// Global variables
int i2c_handle;
circular_buffer_t data_buffer;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_scd40();
int read_scd40(uint16_t *co2, float *temperature, float *humidity);
uint8_t crc8(const uint8_t *data, int len);
void add_to_buffer(circular_buffer_t *buffer, uint16_t co2, float temperature, float humidity);
void print_buffer(const circular_buffer_t *buffer);
void control_led(uint16_t co2);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize SCD40 sensor
int init_scd40() {
    // Start periodic measurement command (0x21B1)
    uint8_t cmd[2] = {0x21, 0xB1};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to SCD40: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for measurement to start
    return 0;
}

// Read data from SCD40 sensor
int read_scd40(uint16_t *co2, float *temperature, float *humidity) {
    uint8_t cmd[2] = {0xE4, 0xB8}; // Read measurement command
    uint8_t data[9];
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to SCD40 for read: %d\n", result);
        return -1;
    }

    gpioDelay(10); // Wait for measurement to complete

    result = i2cReadDevice(i2c_handle, data, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading from SCD40: %d\n", result);
        return -1;
    }

    // CRC Check
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5] || crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert data
    *co2 = (data[0] << 8) | data[1];
    *temperature = -45 + 175 * (float)((data[3] << 8) | data[4]) / 65535.0;
    *humidity = 100 * (float)((data[6] << 8) | data[7]) / 65535.0;

    return 0;
}

// Add data to circular buffer
void add_to_buffer(circular_buffer_t *buffer, uint16_t co2, float temperature, float humidity) {
    time(&buffer->buffer[buffer->head].timestamp);
    buffer->buffer[buffer->head].co2 = co2;
    buffer->buffer[buffer->head].temperature = temperature;
    buffer->buffer[buffer->head].humidity = humidity;

    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Print contents of circular buffer
void print_buffer(const circular_buffer_t *buffer) {
    printf("\n--- Sensor Data ---\n");
    for (int i = 0; i < buffer->count; i++) {
        int index = (buffer->head - buffer->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&buffer->buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] CO2: %d ppm, Temperature: %.2f °C, Humidity: %.2f %%\n",
               timestamp_str, buffer->buffer[index].co2, buffer->buffer[index].temperature, buffer->buffer[index].humidity);
    }
    printf("--- End of Data ---\n\n");
}

// Control CO2 warning LED
void control_led(uint16_t co2) {
    if (co2 > CO2_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD40 sensor
    if (init_scd40() != 0) {
        fprintf(stderr, "SCD40 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize circular buffer
    data_buffer.head = 0;
    data_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t co2;
    float temperature, humidity;
    int retry;

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_scd40(&co2, &temperature, &humidity) == 0) {
                add_to_buffer(&data_buffer, co2, temperature, humidity);
                print_buffer(&data_buffer);
                control_led(co2);
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Read failed, retrying (%d/%d)...\n", retry + 1, RETRY_COUNT);
                retry++;
                gpioDelay(100); // Wait before retrying
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

