#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define PWM_PIN 4
#define CS_PIN 23

// Define constants
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000000   // microseconds
#define LOG_FILE "temperature_log.txt"
#define ERROR_LOG_FILE "error_log.txt"
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define VALID_TEMP_MIN -40.0
#define VALID_TEMP_MAX 150.0

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static FILE *error_log_file = NULL;

// Structure to hold pulse width data
typedef struct {
    uint32_t high_time;
    uint32_t low_time;
} pulse_width_t;

// Function prototypes
int initialize_gpio();
pulse_width_t read_pwm_pulse_width();
double calculate_temperature(pulse_width_t pulse_width);
void log_temperature(double temperature);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(PWM_PIN, PI_INPUT);
    gpioSetMode(CS_PIN, PI_OUTPUT);
    gpioWrite(CS_PIN, 1); // Deselect the sensor initially

    return 0;
}

// Read PWM pulse width
pulse_width_t read_pwm_pulse_width() {
    pulse_width_t pulse_width;
    uint32_t start_time, end_time;
    int i;

    // Wait for the PWM pin to go high (rising edge)
    int timeout = 0;
    while (gpioRead(PWM_PIN) == 0 && timeout < 100000) { // Timeout after 100ms
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }
    if (timeout >= 100000) {
        log_error("Timeout waiting for rising edge");
        pulse_width.high_time = 0;
        pulse_width.low_time = 0;
        return pulse_width;
    }
    start_time = gpioTick();

    // Wait for the PWM pin to go low (falling edge)
    timeout = 0;
    while (gpioRead(PWM_PIN) == 1 && timeout < 100000) { // Timeout after 100ms
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }
    if (timeout >= 100000) {
        log_error("Timeout waiting for falling edge");
        pulse_width.high_time = 0;
        pulse_width.low_time = 0;
        return pulse_width;
    }
    end_time = gpioTick();

    pulse_width.high_time = end_time - start_time;
    pulse_width.low_time = 0; // Dummy low time for now

    return pulse_width;
}

// Calculate temperature from pulse width
double calculate_temperature(pulse_width_t pulse_width) {
    if (pulse_width.low_time == 0) {
        log_error("Invalid low time, cannot calculate temperature");
        return -273.15; // Return absolute zero on error
    }

    // TMP05 datasheet formula
    double temperature = (pulse_width.high_time / 1000000.0) * 100.0; // Convert to seconds and multiply by 100

    return temperature;
}

// Log temperature to file
void log_temperature(double temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        log_error("Log file is not open");
    }
}

// Log error to file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s,%s\n", timestamp, message);
        fflush(error_log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error log file is not open\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }

    gpioTerminate();
}

int main() {
    int retries = 0;
    pulse_width_t pulse_width;
    double temperature;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error opening error log file: %s\n", ERROR_LOG_FILE);
        fclose(log_file);
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            pulse_width = read_pwm_pulse_width();

            if (pulse_width.high_time != 0 && pulse_width.low_time != 0) {
                temperature = calculate_temperature(pulse_width);

                if (temperature > VALID_TEMP_MIN && temperature < VALID_TEMP_MAX) {
                    log_temperature(temperature);
                    break; // Exit retry loop on success
                } else {
                    char error_message[100];
                    snprintf(error_message, sizeof(error_message), "Invalid temperature reading: %.2f", temperature);
                    log_error(error_message);
                }
            } else {
                log_error("Failed to read pulse width, retrying...");
            }

            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }

        if (retries == MAX_RETRIES) {
            log_error("Failed to read temperature after multiple retries");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

