    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        log_error("Log file is not open");
    }
}

// Log error to file
void log_error(const char *message) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (error_log_file != NULL) {
        fprintf(error_log_file, "%s,%s\n", timestamp, message);
        fflush(error_log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error log file is not open\n");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }
    if (error_log_file != NULL) {
        fclose(error_log_file);
    }

    gpioTerminate();
}

int main() {
