    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        fprintf(stderr, "Error opening error log file: %s\n", ERROR_LOG_FILE);
        fclose(log_file);
        cleanup();
        return 1;
    }

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        retries = 0;
        while (retries < MAX_RETRIES) {
            pulse_width = read_pwm_pulse_width();

            if (pulse_width.high_time != 0 && pulse_width.low_time != 0) {
                temperature = calculate_temperature(pulse_width);

                if (temperature > VALID_TEMP_MIN && temperature < VALID_TEMP_MAX) {
                    log_temperature(temperature);
                    break; // Exit retry loop on success
                } else {
