                    snprintf(error_message, sizeof(error_message), "Invalid temperature reading: %.2f", temperature);
                    log_error(error_message);
                }
            } else {
                log_error("Failed to read pulse width, retrying...");
            }

            retries++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }

        if (retries == MAX_RETRIES) {
            log_error("Failed to read temperature after multiple retries");
        }

        gpioDelay(5000000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

