#define MEASUREMENT_COMMAND 0x2C06 // High repeatability, clock stretching disabled
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100
#define SLEEP_DURATION_S 5
#define SINUSOIDAL_OFFSET_TEMP 2.0
#define SINUSOIDAL_OFFSET_HUM 5.0
#define LOG_FILE "environmental_data.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint16_t *temperature, uint16_t *humidity);
int validate_crc(uint16_t data, uint8_t crc);
sensor_data_t convert_data(uint16_t raw_temperature, uint16_t raw_humidity);
void apply_sinusoidal_offset(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation (SHT35 datasheet)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_temperature, raw_humidity;
        sensor_data_t sensor_data;

        // Read sensor data with retries
        int retries = 0;
        while (retries < RETRY_COUNT) {
            if (read_sensor_data(&raw_temperature, &raw_humidity) == 0) {
                break; // Success
            } else {
                fprintf(stderr, "I2C read failed, retrying (%d/%d)\n", retries + 1, RETRY_COUNT);
                retries++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retries == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
            sensor_data.temperature = NAN;
            sensor_data.humidity = NAN;
        } else {
            // Validate CRC
            if (!validate_crc(raw_temperature, (raw_temperature >> 8) & 0xFF)) {
                fprintf(stderr, "Temperature CRC check failed\n");
                sensor_data.temperature = NAN;
            } else if (!validate_crc(raw_humidity, (raw_humidity >> 8) & 0xFF)) {
                fprintf(stderr, "Humidity CRC check failed\n");
                sensor_data.humidity = NAN;
            } else {
                // Convert data
                sensor_data = convert_data(raw_temperature, raw_humidity);

                // Apply sinusoidal offset
                apply_sinusoidal_offset(&sensor_data);

                // Log data
                log_data(sensor_data);
            }
        }

        // Sleep for 5 seconds
        gpioDelay(SLEEP_DURATION_S * 1000000); // Delay in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT35_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *temperature, uint16_t *humidity) {
    char buf[6];
    int result = i2cWriteByteData(i2c_handle, 0, MEASUREMENT_COMMAND >> 8); // MSB
    if (result != 0) {
        fprintf(stderr, "Failed to write MSB to I2C device: %d\n", result);
        return 1;
    }
    result = i2cWriteByteData(i2c_handle, 0, MEASUREMENT_COMMAND & 0xFF); // LSB
    if (result != 0) {
        fprintf(stderr, "Failed to write LSB to I2C device: %d\n", result);
        return 1;
    }

    gpioDelay(20000); // Wait for measurement (at least 15ms)

    result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read data from I2C device: %d\n", result);
        return 1;
    }

    *temperature = (buf[0] << 8) | buf[1];
    *humidity = (buf[3] << 8) | buf[4];

    return 0;
}

// Validate CRC
int validate_crc(uint16_t data, uint8_t crc) {
    uint8_t data_bytes[2];
    data_bytes[0] = (data >> 8) & 0xFF;
    data_bytes[1] = data & 0xFF;

    uint8_t calculated_crc = crc8(data_bytes, 2);
    return calculated_crc == crc;
}

// Convert raw data to temperature and humidity
sensor_data_t convert_data(uint16_t raw_temperature, uint16_t raw_humidity) {
    sensor_data_t data;
    data.temperature = -45.0 + (175.0 * (float)raw_temperature / 65535.0);
    data.humidity = 100.0 * (float)raw_humidity / 65535.0;
    return data;
}

// Apply sinusoidal offset
void apply_sinusoidal_offset(sensor_data_t *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    float time_of_day = (float)(t->tm_hour * 3600 + t->tm_min * 60 + t->tm_sec) / 86400.0;
    float temperature_offset = SINUSOIDAL_OFFSET_TEMP * sin(2 * M_PI * time_of_day);
    float humidity_offset = SINUSOIDAL_OFFSET_HUM * sin(2 * M_PI * time_of_day);

    data->temperature += temperature_offset;
    data->humidity += humidity_offset;

    // Clamp humidity to 0-100%
    if (data->humidity < 0.0) {
        data->humidity = 0.0;
    } else if (data->humidity > 100.0) {
        data->humidity = 100.0;
    }
}

// Log data to file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (isnan(data.temperature) || isnan(data.humidity)) {
        fprintf(log_file, "%s,NaN,NaN\n", timestamp);
    } else {
        fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    }
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

