#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SDP810_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define CSV_FILE "airflow.csv"
#define SLEEP_DURATION_US 1000000 // 1 second

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(uint16_t command);
int read_data(uint8_t *data, int count);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t convert_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read data from the sensor
int read_data(uint8_t *data, int count) {
    int result = i2cReadDevice(i2c_handle, (char *)data, count);
    if (result != count) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Convert raw data to pressure and temperature
sensor_data_t convert_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor = (data[6] << 8) | data[7];

    // CRC validation
    uint8_t pressure_data[2] = {data[0], data[1]};
    uint8_t temperature_data[2] = {data[3], data[4]};
    uint8_t scale_factor_data[2] = {data[6], data[7]};

    uint8_t pressure_crc = crc8(pressure_data, 2);
    uint8_t temperature_crc = crc8(temperature_data, 2);
    uint8_t scale_factor_crc = crc8(scale_factor_data, 2);

    if (pressure_crc != data[2] || temperature_crc != data[5] || scale_factor_crc != data[8]) {
        fprintf(stderr, "CRC validation failed!\n");
        sensor_data.pressure = -999.0; // Indicate error
        sensor_data.temperature = -999.0;
        return sensor_data;
    }

    // Conversion formulas (from SDP810 datasheet)
    sensor_data.pressure = (float)raw_pressure / 60.0; // Pa
    sensor_data.temperature = (float)raw_temperature / 200.0; // °C

    return sensor_data;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(csv_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(csv_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file
    csv_file = fopen(CSV_FILE, "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Error opening CSV file!\n");
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,Pressure (Pa),Temperature (C)\n");
    }
    rewind(csv_file);

    // Main loop
    while (!terminate) {
        // Send measurement command
        if (send_command(MEASURE_CMD) != 0) {
            fprintf(stderr, "Error sending measurement command, retrying...\n");
            gpioDelay(100000); // Wait 100ms before retrying
