        if (sensor_data.pressure != -999.0 && sensor_data.temperature != -999.0) {
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error converting data, skipping logging.\n");
        }

        // Sleep for 1 second
        gpioDelay(SLEEP_DURATION_US);
