                }
            } else {
                fprintf(stderr, "Failed to read sensor data, retry %d/%d\n", retry + 1, RETRY_COUNT);
            }

            retry++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
        }

        gpioDelay(5000000); // Wait 5 seconds (5000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

