#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SI7021_ADDR 0x40
#define MEASURE_TEMP_HOLD 0xE3
#define MEASURE_HUMID_HOLD 0xE5
#define RESET_CMD 0xFE
#define LOG_FILE "environment.log"
#define ERROR_LOG_FILE "error.log"
#define POLLING_INTERVAL_MS 5000
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
FILE *log_file;
FILE *error_log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int verify_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum);
int log_data(sensor_data_t data);
int log_error(const char *message);
void reset_sensor();
void signal_handler(int signal);

// CRC-8 checksum calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7021_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t cmd;
    uint8_t buffer[3];
    int retries = 0;

    // Measure temperature
    cmd = MEASURE_TEMP_HOLD;
    if (i2cWriteByte(i2c_handle, cmd) != 0) {
        log_error("Failed to write temperature command");
        return -1;
    }
    gpioDelay(20); // Wait for measurement (datasheet specifies 15ms for high repeatability)

    // Read temperature data
    if (i2cReadDevice(i2c_handle, (char *)buffer, 3) != 3) {
        log_error("Failed to read temperature data");
        return -1;
    }

    // Verify temperature CRC
    if (!verify_crc(buffer, 2, buffer[2])) {
        log_error("Temperature CRC check failed");
        return -1;
    }

    // Convert temperature to Celsius
    uint16_t raw_temp = (buffer[0] << 8) | buffer[1];
    data->temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    // Measure humidity
    cmd = MEASURE_HUMID_HOLD;
    if (i2cWriteByte(i2c_handle, cmd) != 0) {
        log_error("Failed to write humidity command");
        return -1;
    }
    gpioDelay(20); // Wait for measurement

    // Read humidity data
    if (i2cReadDevice(i2c_handle, (char *)buffer, 3) != 3) {
        log_error("Failed to read humidity data");
        return -1;
    }

    // Verify humidity CRC
    if (!verify_crc(buffer + 1, 2, buffer[3])) {
        log_error("Humidity CRC check failed");
        return -1;
    }

    // Convert humidity to percentage
    uint16_t raw_humidity = (buffer[1] << 8) | buffer[2];
    data->humidity = (125.0 * raw_humidity / 65536.0) - 6.0;

    return 0;
}

// Verify CRC checksum
int verify_crc(uint8_t data[], int nbrOfBytes, uint8_t checksum) {
    uint8_t calculated_checksum = crc8(data, nbrOfBytes);
    return (calculated_checksum == checksum) ? 1 : 0;
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Log errors to error log file
int log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(error_log_file, "%s,ERROR,%s\n", timestamp, message);
    fflush(error_log_file);
    fprintf(stderr, "%s,ERROR,%s\n", timestamp, message);
    return 0;
}

// Reset the sensor
void reset_sensor() {
    uint8_t cmd = RESET_CMD;
    if (i2cWriteByte(i2c_handle, cmd) != 0) {
        log_error("Failed to reset sensor");
    }
    gpioDelay(10); // Wait for reset to complete
}

