#define SDP810_I2C_ADDR 0x25

// Define the I2C bus number (typically 1 on Raspberry Pi)
#define I2C_BUS 1

// Define the command to trigger continuous measurement
#define MEASURE_CMD 0x362F

// Define the conversion time in milliseconds
#define CONVERSION_TIME 20

// Define the number of bytes to read from the sensor
#define NUM_BYTES_TO_READ 9

// Global variables for I2C handle and file pointer
int i2c_handle = -1;
FILE *fp = NULL;

// Function prototypes
int initialize_i2c();
int write_command(int handle, uint16_t command);
int read_sensor_data(int handle, uint8_t *data, int num_bytes);
int validate_crc(uint8_t data[], int num_bytes);
float convert_pressure(uint16_t raw_pressure);
float convert_temperature(uint16_t raw_temperature);
int log_data(FILE *fp, float pressure, float temperature);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Close the I2C handle if it's open
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close the file pointer if it's open
    if (fp != NULL) {
        fclose(fp);
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Initializes the I2C interface
int initialize_i2c() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Open the I2C device
    i2c_handle = i2cOpen(I2C_BUS, SDP810_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Writes a command to the SDP810 sensor
int write_command(int handle, uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF; // MSB
    buf[1] = command & 0xFF;        // LSB

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to write command: %d\n", result);
        return -1;
    }

    return 0;
}

// Reads data from the SDP810 sensor
int read_sensor_data(int handle, uint8_t *data, int num_bytes) {
    int result = i2cReadDevice(handle, (char *)data, num_bytes);
    if (result != num_bytes) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    return 0;
}

// Validates the CRC-8 checksum
int validate_crc(uint8_t data[], int num_bytes) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < num_bytes; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Converts the raw pressure data to Pascals
float convert_pressure(uint16_t raw_pressure) {
    return (float)raw_pressure / 60.0;
}

// Converts the raw temperature data to degrees Celsius
float convert_temperature(uint16_t raw_temperature) {
    return (float)raw_temperature / 200.0;
}

// Logs the pressure and temperature data to a binary file
int log_data(FILE *fp, float pressure, float temperature) {
    if (fwrite(&pressure, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write pressure to file\n");
        return -1;
    }
    if (fwrite(&temperature, sizeof(float), 1, fp) != 1) {
        fprintf(stderr, "Failed to write temperature to file\n");
        return -1;
    }
    return 0;
}

int main() {
    // Register the signal handler for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the I2C interface
    if (initialize_i2c() != 0) {
        return 1;
    }

    // Open the binary file for appending
    fp = fopen("airflow.dat", "ab");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open airflow.dat for writing\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Main loop to read and log data
    while (1) {
        // Write the measurement command
        if (write_command(i2c_handle, MEASURE_CMD) != 0) {
            fprintf(stderr, "Failed to write measurement command, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Wait for the conversion time
        gpioDelay(CONVERSION_TIME * 1000); // Convert milliseconds to microseconds

        // Read the sensor data
        uint8_t data[NUM_BYTES_TO_READ];
        if (read_sensor_data(i2c_handle, data, NUM_BYTES_TO_READ) != 0) {
            fprintf(stderr, "Failed to read sensor data, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Validate the CRC checksums
        if (validate_crc(data, 2) != 0 || validate_crc(data + 3, 2) != 0) {
            fprintf(stderr, "CRC validation failed\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        // Extract the raw pressure and temperature values
        uint16_t raw_pressure = (data[0] << 8) | data[1];
        uint16_t raw_temperature = (data[3] << 8) | data[4];

        // Convert the raw data to physical units
        float pressure = convert_pressure(raw_pressure);
        float temperature = convert_temperature(raw_temperature);

        // Log the data to the file
        if (log_data(fp, pressure, temperature) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Print the data to the console
        printf("Pressure: %.2f Pa, Temperature: %.2f °C\n", pressure, temperature);

        // Wait for 1 second
        gpioDelay(1000000); // 1 second in microseconds
    }

    // The following lines will never be reached due to the infinite loop,
    // but are included for completeness and to avoid compiler warnings.
    i2cClose(i2c_handle);
    fclose(fp);
    gpioTerminate();

    return 0;
}

