    if (bytes_read != 2) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    *pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    return 0;
}

// Function to convert raw sensor data to flow rate (Pa/s)
float convert_to_flow_rate(int16_t raw_pressure) {
    // Honeywell HAFBLF0100A2AX5 datasheet:
    // 100 Pa/LSB, 0 Pa offset
    // Assuming 100 Pa/LSB and 0 Pa offset for simplicity
    return (float)raw_pressure * 0.1;
}

// Function to set the fan speed using PWM
int set_fan_speed(float flow_rate) {
    // Map flow rate to PWM duty cycle (0-255)
    int duty_cycle = (int)(flow_rate / 100.0 * 255.0); // Assuming 100 Pa/s max flow rate

    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 255) duty_cycle = 255;

