#define TEMP_OUT_H 0x2C

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lps33hw();
int read_pressure(float *pressure);
int read_temperature(float *temperature);
int log_data(float pressure, float temperature);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function to initialize the LPS33HW sensor
int init_lps33hw() {
    // Enable continuous data acquisition (ODR = 1 Hz)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x90) < 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }
    return 0;
}

// Function to read pressure data from the LPS33HW
int read_pressure(float *pressure) {
    char buffer[3];
    int32_t raw_pressure;

    if (i2cReadI2CBlockData(i2c_handle, PRESS_OUT_XL, buffer, 3) != 3) {
        fprintf(stderr, "Error reading pressure data\n");
        return -1;
    }

    raw_pressure = (int32_t)((buffer[2] << 16) | (buffer[1] << 8) | buffer[0]);
    raw_pressure = raw_pressure >> 8; // Align to 24 bits

    // Convert raw pressure to hPa (hPa = hPa * 4)
    *pressure = (float)raw_pressure / 4096.0;

    return 0;
}

// Function to read temperature data from the LPS33HW
int read_temperature(float *temperature) {
    char buffer[2];
    int16_t raw_temperature;

    if (i2cReadI2CBlockData(i2c_handle, TEMP_OUT_L, buffer, 2) != 2) {
        fprintf(stderr, "Error reading temperature data\n");
        return -1;
    }

    raw_temperature = (int16_t)((buffer[1] << 8) | buffer[0]);

    // Convert raw temperature to degrees Celsius (°C = °C * 42.5)
    *temperature = (float)raw_temperature / 480.0;

    return 0;
}

// Function to log data to a file
int log_data(float pressure, float temperature) {
    time_t now;
    struct tm *timeinfo;
    char timestamp[20];

    time(&now);
    timeinfo = localtime(&now);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f hPa, Temperature: %.2f °C\n", timestamp, pressure, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful termination
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    float pressure, temperature;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, LPS33HW_ADDR, 0); // Bus 1, address 0x5C, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LPS33HW sensor
    if (init_lps33hw() < 0) {
        fprintf(stderr, "LPS33HW initialisation failed\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("environmental_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_pressure(&pressure) == 0 && read_temperature(&temperature) == 0) {
            // Log data
            if (log_data(pressure, temperature) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

