#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Constants
#define I2C_BUS 1
#define STLM75_ADDR 0x48
#define LED_GPIO 17
#define BUFFER_SIZE 10
#define TEMP_THRESHOLD 28.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_pigpio();
int open_i2c_bus();
int read_temperature(float *temperature);
void add_to_buffer(CircularBuffer *buffer, float value);
float calculate_average(CircularBuffer *buffer);
void control_led(float average_temperature);
void cleanup();
void signal_handler(int signal);

// Initialize circular buffer
void init_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, STLM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from STLM75 sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "Failed to read temperature: %d\n", result);
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (float)raw_temp / 256.0;

    return 0;
}

// Add temperature reading to circular buffer
void add_to_buffer(CircularBuffer *buffer, float value) {
    buffer->buffer[buffer->head] = value;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Calculate running average of temperature readings
float calculate_average(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

// Control LED based on average temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(LED_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(LED_GPIO, 0); // Turn LED off
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_GPIO, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer temp_buffer;
    init_buffer(&temp_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature;
    float average_temperature;

    // Main loop
    while (!terminate) {
        // Read temperature
        if (read_temperature(&temperature) == 0) {
            // Add to circular buffer
            add_to_buffer(&temp_buffer, temperature);

            // Calculate average temperature
            average_temperature = calculate_average(&temp_buffer);

            // Control LED
            control_led(average_temperature);

            // Print temperature and average
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature. Skipping iteration.\n");
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpioDelay takes milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

