#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// SCD30 I2C address
#define SCD30_I2C_ADDR 0x61

// SCD30 commands
#define CMD_START_PERIODIC_MEASUREMENT 0x0010
#define CMD_READ_MEASUREMENT 0x0300
#define CMD_STOP_PERIODIC_MEASUREMENT 0x0104
#define CMD_GET_DATA_READY 0x0202

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float co2;
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_scd30();
int read_scd30_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void control_ventilation(float co2);
void signal_handler(int signal);
void cleanup();

// CRC-8-ATM checksum calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize the SCD30 sensor
int init_scd30() {
    // Start periodic measurement
    char cmd[2] = {(CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error starting periodic measurement: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Wait for the measurement to start

    // Check data ready status
    char data_ready_cmd[2] = {(CMD_GET_DATA_READY >> 8) & 0xFF, CMD_GET_DATA_READY & 0xFF};
    char data_ready_resp[2];
    result = i2cWriteDevice(i2c_handle, data_ready_cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing data ready command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Small delay
    result = i2cReadDevice(i2c_handle, data_ready_resp, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading data ready response: %d\n", result);
        return -1;
    }

    uint16_t data_ready = (data_ready_resp[0] << 8) | data_ready_resp[1];
    if (!(data_ready & 0x01)) {
        fprintf(stderr, "Data not ready yet\n");
        return -1;
    }

    return 0;
}

// Function to read data from the SCD30 sensor
int read_scd30_data(sensor_data_t *data) {
    char cmd[2] = {(CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF};
    char resp[9];
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing read measurement command: %d\n", result);
        return -1;
    }
    gpioDelay(10); // Small delay
    result = i2cReadDevice(i2c_handle, resp, 9);
    if (result != 9) {
        fprintf(stderr, "Error reading measurement response: %d\n", result);
        return -1;
    }

    // CRC check for CO2
    uint8_t co2_data[2] = {resp[0], resp[1]};
    uint8_t co2_crc = resp[2];
    if (crc8(co2_data, 2) != co2_crc) {
        fprintf(stderr, "CRC check failed for CO2\n");
        return -1;
    }

    // CRC check for Temperature
    uint8_t temp_data[2] = {resp[3], resp[4]};
    uint8_t temp_crc = resp[5];
    if (crc8(temp_data, 2) != temp_crc) {
        fprintf(stderr, "CRC check failed for Temperature\n");
        return -1;
    }

    // CRC check for Humidity
    uint8_t humidity_data[2] = {resp[6], resp[7]};
    uint8_t humidity_crc = resp[8];
    if (crc8(humidity_data, 2) != humidity_crc) {
        fprintf(stderr, "CRC check failed for Humidity\n");
        return -1;
    }

    // Convert data
    data->co2 = (float)((resp[0] << 8) | resp[1]);
    data->temperature = -45 + 175 * ((float)((resp[3] << 8) | resp[4])) / 65535.0;
    data->humidity = 100 * ((float)((resp[6] << 8) | resp[7])) / 65535.0;

    return 0;
}

// Function to log data to a file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, data.co2, data.temperature, data.humidity);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to control ventilation based on CO2 level
void control_ventilation(float co2) {
    if (co2 < 800) {
        printf("CO2 level: %.2f ppm, Ventilation: OFF\n", co2);
    } else if (co2 < 1199) {
        printf("CO2 level: %.2f ppm, Ventilation: LOW\n", co2);
    } else {
        printf("CO2 level: %.2f ppm, Ventilation: HIGH\n", co2);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to close I2C, log file, and terminate pigpio
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, SCD30_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize SCD30 sensor
    if (init_scd30() != 0) {
        fprintf(stderr, "SCD30 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("air_quality.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_scd30_data(&sensor_data) == 0) {
            // Log data
            if (log_data(sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }

            // Control ventilation
            control_ventilation(sensor_data.co2);
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

