#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define constants
#define I2C_BUS 1
#define SDP32_ADDR 0x21
#define SAMPLE_INTERVAL_MS 1000
#define MAX_RETRIES 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    int16_t scale_factor;
} sensor_data_t;

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read data from the SDP32 sensor
int read_sdp32(int i2c_handle, sensor_data_t *data) {
    char buf[9];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, buf, 9);
        if (result == 9) {
            // CRC check for pressure
            if (crc8(buf, 2) != buf[2]) {
                fprintf(stderr, "Error: CRC check failed for pressure (attempt %d)\n", retries + 1);
                retries++;
                gpioDelay(100); // Wait before retrying
                continue;
            }

            // CRC check for temperature
            if (crc8(buf + 3, 2) != buf[5]) {
                fprintf(stderr, "Error: CRC check failed for temperature (attempt %d)\n", retries + 1);
                retries++;
                gpioDelay(100); // Wait before retrying
                continue;
            }

            // CRC check for scale factor
            if (crc8(buf + 6, 2) != buf[8]) {
                fprintf(stderr, "Error: CRC check failed for scale factor (attempt %d)\n", retries + 1);
                retries++;
                gpioDelay(100); // Wait before retrying
                continue;
            }

            // Convert data
            data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
            data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
            data->scale_factor = (int16_t)((buf[6] << 8) | buf[7]);

            return 0; // Success
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(100); // Wait before retrying
        }
    }

    fprintf(stderr, "Error: Failed to read SDP32 after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to print the sensor data with a timestamp
void print_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %d Pa, Temperature: %d °C, Scale Factor: %d\n", timestamp, data.pressure, data.temperature, data.scale_factor);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main(int argc, char *argv[]) {
    int sampling_interval_ms = SAMPLE_INTERVAL_MS;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "i:")) != -1) {
        switch (opt) {
            case 'i':
                sampling_interval_ms = atoi(optarg);
                if (sampling_interval_ms <= 0) {
                    fprintf(stderr, "Error: Invalid sampling interval. Using default value (%d ms).\n", SAMPLE_INTERVAL_MS);
                    sampling_interval_ms = SAMPLE_INTERVAL_MS;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-i interval_ms]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SDP32_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        if (read_sdp32(i2c_handle, &sensor_data) == 0) {
            print_data(sensor_data);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        gpioDelay(sampling_interval_ms);
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

