    if (result != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    // Validate CRC for each 3-byte word
    if (crc8(buf, 2) != buf[2] || crc8(buf + 3, 2) != buf[5] || crc8(buf + 6, 2) != buf[8]) {
        fprintf(stderr, "CRC check failed\n");
        return -1;
    }

    // Convert the raw data to physical units
    int16_t raw_pressure = (buf[0] << 8) | buf[1];
    int16_t raw_temperature = (buf[3] << 8) | buf[4];

    data->pressure = (float)raw_pressure / 60.0; // Scale factor for SDP810-125Pa
    data->temperature = (float)raw_temperature / 200.0; // Scale factor for SDP810-125Pa

    return 0;
}

