#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// HDC1000 I2C address
#define HDC1000_ADDR 0x40

// HDC1000 register addresses
#define TEMP_REG 0x00
#define HUMID_REG 0x01
#define CONFIG_REG 0x02

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int configure_sensor();
int read_sensor_data(uint16_t *temperature, uint16_t *humidity);
float convert_temperature(uint16_t raw_temperature);
float convert_humidity(uint16_t raw_humidity);
void log_data(float temperature, float humidity);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, HDC1000_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the HDC1000 sensor
int configure_sensor() {
    // Configure for 14-bit resolution, temperature and humidity measurement mode
    uint16_t config_value = 0x0000; // Default configuration
    if (i2cWriteWordData(i2c_handle, CONFIG_REG, config_value) < 0) {
        fprintf(stderr, "Failed to write to configuration register\n");
        return -1;
    }
    return 0;
}

// Read temperature and humidity data from the sensor
int read_sensor_data(uint16_t *temperature, uint16_t *humidity) {
    char buf[4];
    int bytes_read = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 4);

    if (bytes_read != 4) {
        fprintf(stderr, "Failed to read sensor data: %d\n", bytes_read);
        return -1;
    }

    *temperature = (buf[0] << 8) | buf[1];
    *humidity = (buf[2] << 8) | buf[3];

    return 0;
}

// Convert raw temperature data to Celsius
float convert_temperature(uint16_t raw_temperature) {
    return ((float)raw_temperature / 65536.0) * 165.0 - 40.0;
}

