    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature\n");
        }

        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7051_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature from the Si7051 sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result;

    // Send temperature measurement command
    result = i2cWriteByte(i2c_handle, TEMP_MEASURE_CMD);
    if (result != 0) {
        fprintf(stderr, "Failed to write temperature command: %d\n", result);
        return 1;
    }

    // Wait for measurement (at least 50ms)
    gpioDelay(50000); // 50ms

    // Read temperature data (2 bytes)
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature data: %d\n", result);
        return 1;
    }

    // Convert raw data to temperature (Celsius)
    uint16_t raw_temp = (buf[0] << 8) | buf[1];
    *temperature = (175.72 * raw_temp / 65536.0) - 46.85;

    return 0;
}

// Log temperature to the console
void log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    printf("[%s] Temperature: %.2f °C\n", timestamp, temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

