#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define I2C_ADDRESS 0x69

// Define the ICP-10101 register addresses
#define ICP10101_REG_TEMP_MSB 0x00
#define ICP10101_REG_TEMP_LSB 0x01
#define ICP10101_REG_TEMP_XLSB 0x02
#define ICP10101_REG_PRESS_MSB 0x03
#define ICP10101_REG_PRESS_LSB 0x04
#define ICP10101_REG_PRESS_XLSB 0x05
#define ICP10101_REG_CONFIG 0x06
#define ICP10101_REG_MEASURE 0x07
#define ICP10101_REG_RESET 0x08

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float pressure;
} sensor_data_t;

// Function prototypes
int initialize_sensor();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to initialize the ICP-10101 sensor
int initialize_sensor() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, ICP10101_REG_RESET, 0x80) < 0) {
        fprintf(stderr, "Error: Failed to reset sensor.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (i2cWriteByteData(i2c_handle, ICP10101_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to configure sensor.\n");
        return -1;
    }

    return 0;
}

// Function to read temperature and pressure data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int16_t raw_temperature, raw_pressure;
    int32_t raw_pressure_xlsb;

    // Trigger a measurement
    if (i2cWriteByteData(i2c_handle, ICP10101_REG_MEASURE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement.\n");
        return -1;
    }

    gpioDelay(7); // Wait for measurement to complete (7 ms)

    // Read 6 bytes of data (temperature MSB, temperature LSB, temperature XLSB, pressure MSB, pressure LSB, pressure XLSB)
    if (i2cReadI2CBlockData(i2c_handle, ICP10101_REG_TEMP_MSB, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read sensor data.\n");
        return -1;
    }

    // Combine the bytes to form the raw temperature and pressure values
    raw_temperature = (int16_t)((buf[0] << 8) | buf[1]);
    raw_pressure = (int16_t)((buf[3] << 8) | buf[4]);
    raw_pressure_xlsb = (int32_t)((buf[5] << 24) | (buf[2] << 16) | (buf[1] << 8) | buf[0]);

    // Convert raw values to temperature (Celsius) and pressure (Pascals)
    data->temperature = (float)raw_temperature / 100.0;
    data->pressure = (float)raw_pressure / 100.0;

    return 0;
}

// Function to log the sensor data with a timestamp
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    printf("%s - Temperature: %.2f °C, Pressure: %.2f Pa\n", timestamp, data.temperature, data.pressure);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, I2C_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Failed to open I2C bus. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (initialize_sensor() < 0) {
        fprintf(stderr, "Error: Sensor initialization failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data. Retrying in 5 seconds.\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000); // 5000 ms = 5 seconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

