    if (i2cWriteByteData(i2c_handle, ICP10101_REG_CONFIG, 0x00) < 0) {
        fprintf(stderr, "Error: Failed to configure sensor.\n");
        return -1;
    }

    return 0;
}

// Function to read temperature and pressure data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int16_t raw_temperature, raw_pressure;
    int32_t raw_pressure_xlsb;

    // Trigger a measurement
    if (i2cWriteByteData(i2c_handle, ICP10101_REG_MEASURE, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to trigger measurement.\n");
        return -1;
    }

    gpioDelay(7); // Wait for measurement to complete (7 ms)

    // Read 6 bytes of data (temperature MSB, temperature LSB, temperature XLSB, pressure MSB, pressure LSB, pressure XLSB)
    if (i2cReadI2CBlockData(i2c_handle, ICP10101_REG_TEMP_MSB, buf, 6) != 6) {
        fprintf(stderr, "Error: Failed to read sensor data.\n");
        return -1;
    }

    // Combine the bytes to form the raw temperature and pressure values
    raw_temperature = (int16_t)((buf[0] << 8) | buf[1]);
    raw_pressure = (int16_t)((buf[3] << 8) | buf[4]);
    raw_pressure_xlsb = (int32_t)((buf[5] << 24) | (buf[2] << 16) | (buf[1] << 8) | buf[0]);

    // Convert raw values to temperature (Celsius) and pressure (Pascals)
    data->temperature = (float)raw_temperature / 100.0;
    data->pressure = (float)raw_pressure / 100.0;

    return 0;
}

