#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define sensor-specific constants
#define I2C_BUS 1
#define SDP800_ADDR 0x25
#define MEASURE_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float pressure;
    float temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(uint8_t *data);
uint8_t crc8(const uint8_t *data, int len);
sensor_data_t process_sensor_data(const uint8_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data
int read_sensor_data(uint8_t *data) {
    char buf[2];
    int bytes_read;

    // Send measurement command
    buf[0] = (MEASURE_CMD >> 8) & 0xFF;
    buf[1] = MEASURE_CMD & 0xFF;
    if (i2cWriteDevice(i2c_handle, buf, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for measurement (at least 45 ms)
    gpioDelay(50000); // 50 ms

    // Read 9 bytes of data
    bytes_read = i2cReadDevice(i2c_handle, (char *)data, 9);
    if (bytes_read != 9) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    return 0;
}

// Function to process sensor data
sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];

    // CRC validation for pressure data
    if (crc8(data, 2) != data[2]) {
        fprintf(stderr, "Pressure CRC error\n");
        sensor_data.pressure = -1000.0; // Indicate error
    } else {
        sensor_data.pressure = (float)raw_pressure / 60.0; // Scale factor from datasheet
    }

    // CRC validation for temperature data
    if (crc8(data + 3, 2) != data[5]) {
        fprintf(stderr, "Temperature CRC error\n");
        sensor_data.temperature = -1000.0; // Indicate error
    } else {
        sensor_data.temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet
    }

    return sensor_data;
}

// Function to log data to file
int log_data(sensor_data_t data) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write data to file
    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, data.pressure, data.temperature);
    fflush(log_file); // Ensure data is written immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    uint8_t sensor_data[9];
    sensor_data_t processed_data;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(sensor_data) == 0) {
            // Process sensor data
            processed_data = process_sensor_data(sensor_data);

            // Log data
            if (processed_data.pressure != -1000.0 && processed_data.temperature != -1000.0) {
                log_data(processed_data);
            } else {
                fprintf(stderr, "Invalid sensor data, skipping logging.\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

