// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDR 0x25

// Define the trigger command
#define TRIGGER_CMD 0x362F

// Define the CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
