        if (result == 2) {
            // Combine the two bytes into a 16-bit integer
            int16_t raw_pressure = (buf[0] << 8) | buf[1];

            // Convert raw pressure to kPa
            *pressure = (float)raw_pressure * PRESSURE_SCALE_FACTOR + PRESSURE_OFFSET;
