#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define HIH6130_ADDR 0x27
#define LOG_FILE "environmental_data.log"
#define MAX_LOG_SIZE 1048576 // 1 MB
#define TRIGGER_COMMAND 0x00
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
    int status;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int validate_sensor_data(const sensor_data_t *data);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, HIH6130_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from HIH6130
int read_sensor_data(sensor_data_t *data) {
    char buf[4];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cWriteByte(i2c_handle, TRIGGER_COMMAND);
        if (result == 0) {
            gpioDelay(40); // Wait for measurement (datasheet specifies 35-40ms)
            result = i2cReadDevice(i2c_handle, buf, 4);
            if (result == 4) {
                // Convert raw data to temperature and humidity
                uint16_t raw_humidity = (buf[0] << 8) | buf[1];
                uint16_t raw_temperature = (buf[2] << 8) | buf[3];

                data->humidity = ((float)raw_humidity / 16383.0) * 100.0;
                data->temperature = ((float)raw_temperature / 16383.0) * 165.0 - 40.0;

                // Validate sensor data
                if (validate_sensor_data(data)) {
                    data->status = 0; // Success
                    return 0;
                } else {
                    fprintf(stderr, "Error: Invalid sensor data\n");
                    data->status = -1; // Invalid data
                    return -1;
                }
            } else {
                fprintf(stderr, "Error reading sensor data: %d\n", result);
                data->status = -2; // I2C read error
                return -1;
            }
        } else {
            fprintf(stderr, "Error triggering sensor: %d\n", result);
            data->status = -3; // I2C write error
            return -1;
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS); // Wait before retrying
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", RETRY_COUNT);
    data->status = -4; // Max retries reached
    return -1;
}

// Validate sensor data
int validate_sensor_data(const sensor_data_t *data) {
    if (data->humidity < 0.0 || data->humidity > 100.0) {
        return 0;
    }
    if (data->temperature < -40.0 || data->temperature > 125.0) {
        return 0;
    }
    return 1;
}

// Log data to file
int log_data(const sensor_data_t *data) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[30];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", &tm);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        return -1;
    }

    // Check if the file is too large
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size > MAX_LOG_SIZE) {
        // Truncate the file to the maximum allowed size
        ftruncate(fileno(fp), MAX_LOG_SIZE);
    }

    // Write data to log file
    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, data->temperature, data->humidity, data->status);

    // Close log file
    fclose(fp);

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            if (log_data(&sensor_data) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data\n");
        }

        // Wait 5 seconds
        sleep(5);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

