#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define SENT_PIN 4
#define DATA_PIN 17
#define CLOCK_PIN 27

// Define constants
#define SENT_TIMEOUT 100000 // 100ms timeout in microseconds
#define PULSE_WIDTH_MIN 12   // Minimum pulse width in microseconds
#define PULSE_WIDTH_MAX 271  // Maximum pulse width in microseconds
#define SYNC_PULSE_WIDTH 56  // Synchronization pulse width in microseconds
#define DATA_BITS 32         // Number of data bits in the SENT frame
#define CHECKSUM_BITS 8      // Number of checksum bits in the SENT frame
#define PULSE_PULSES 64      // Number of pulse pulses to capture

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Structure to hold sensor data
typedef struct {
    int status;
    int data[3];
    int checksum;
} sensor_data_t;

// Function prototypes
int initialize_gpio();
int capture_pulse_widths(int *pulse_widths);
int decode_sent_frame(int *pulse_widths, sensor_data_t *data);
int validate_checksum(sensor_data_t data);
int log_pressure_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENT_PIN, PI_INPUT);
    gpioSetMode(DATA_PIN, PI_INPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);

    return 0;
}

// Capture pulse widths from the SENT signal
int capture_pulse_widths(int *pulse_widths) {
    int i = 0;
    int start_tick = 0;
    int end_tick = 0;
    int pulse_width = 0;

    // Wait for the start of the SENT frame (low to high transition on SENT_PIN)
    int timeout = 0;
    while (gpioRead(SENT_PIN) == 0 && timeout < SENT_TIMEOUT) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }
    if (timeout >= SENT_TIMEOUT) {
        fprintf(stderr, "Error: SENT frame start timeout\n");
        return -1;
    }

    // Capture synchronization pulse width
    timeout = 0;
    while (gpioRead(SENT_PIN) == 1 && timeout < SENT_TIMEOUT) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }
    if (timeout >= SENT_TIMEOUT) {
        fprintf(stderr, "Error: SENT synchronization pulse timeout\n");
        return -1;
    }
    pulse_width = gpioTick();

    // Capture data bits
    for (i = 0; i < DATA_BITS; i++) {
        timeout = 0;
        while (gpioRead(SENT_PIN) == 0 && timeout < SENT_TIMEOUT) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            timeout++;
        }
        if (timeout >= SENT_TIMEOUT) {
            fprintf(stderr, "Error: SENT data bit %d start timeout\n", i);
            return -1;
        }

        timeout = 0;
        while (gpioRead(SENT_PIN) == 1 && timeout < SENT_TIMEOUT) {
            gpioDelay(1); // Small delay to prevent busy-waiting
            timeout++;
        }
        if (timeout >= SENT_TIMEOUT) {
            fprintf(stderr, "Error: SENT data bit %d end timeout\n", i);
            return -1;
        }

        end_tick = gpioTick();
        pulse_width = end_tick - start_tick;
        if (pulse_width < PULSE_WIDTH_MIN || pulse_width > PULSE_WIDTH_MAX) {
            fprintf(stderr, "Error: Invalid pulse width for data bit %d: %d\n", i, pulse_width);
            return -1;
        }

        pulse_widths[i] = pulse_width;
        start_tick = end_tick;
    }

    return 0;
}

// Decode the SENT frame and extract data
int decode_sent_frame(int *pulse_widths, sensor_data_t *data) {
    int i;

    // Extract status nibble
    data->status = (pulse_widths[0] > pulse_widths[1]) ? 1 : 0;

    // Extract data nibbles
    for (i = 0; i < 3; i++) {
        data->data[i] = 0;
        for (int j = 0; j < 4; j++) {
            data->data[i] <<= 1;
            if (pulse_widths[2 + 4 * i + j] > pulse_widths[2 + 4 * i + j + 1]) {
                data->data[i] |= 1;
            }
        }
    }

    // Extract checksum nibble
    data->checksum = 0;
    for (i = 0; i < 8; i++) {
        data->checksum <<= 1;
        if (pulse_widths[2 + 4 * 3 + i] > pulse_widths[2 + 4 * 3 + i + 1]) {
            data->checksum |= 1;
        }
    }

    return 0;
}

// Validate the checksum
int validate_checksum(sensor_data_t data) {
    int checksum = 0;
    int i;

    // Calculate checksum
    for (i = 0; i < 3; i++) {
        checksum += data.data[i];
    }

    // Check if checksum is valid
    if (checksum != data.checksum) {
        fprintf(stderr, "Error: Checksum mismatch: calculated = %d, received = %d\n", checksum, data.checksum);
        return -1;
    }

    return 0;
}

// Log the pressure data to a file
int log_pressure_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Pressure: %.2f Pa\n", timestamp, (float)data.data[0] * 0.1);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    int pulse_widths[DATA_BITS + CHECKSUM_BITS + 1]; // +1 for synchronization pulse
    sensor_data_t sensor_data;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Pressure sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Capture pulse widths
        if (capture_pulse_widths(pulse_widths) == 0) {
            // Decode SENT frame
            if (decode_sent_frame(pulse_widths, &sensor_data) == 0) {
                // Validate checksum
                if (validate_checksum(sensor_data) == 0) {
                    // Log pressure data
                    log_pressure_data(sensor_data);
                } else {
                    fprintf(stderr, "Error: Invalid checksum\n");
                }
            } else {
                fprintf(stderr, "Error: Invalid SENT frame\n");
            }
        } else {
            fprintf(stderr, "Error: Failed to capture pulse widths\n");
        }

        gpioDelay(100); // Delay between readings
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

