#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define TEMP_SCALE 0.0078125
#define LOG_FILE "greenhouse_temps.dat"
#define DEVICE_ID_REG 0x01
#define DEVICE_ID 0x48

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_device_id();
float read_temperature();
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float temperature;
    time_t timestamp;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        cleanup();
        return 1;
    }

    // Read device ID
    if (read_device_id() != 0) {
        fprintf(stderr, "Failed to read device ID. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "wb");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();

        // Log temperature
        if (log_temperature(temperature) != 0) {
            fprintf(stderr, "Failed to log temperature.\n");
        }

        // Wait 60 seconds
        sleep(60);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read the device ID from the TMP117
int read_device_id() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, DEVICE_ID_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read device ID: %d\n", result);
        return 1;
    }

    if (buf[0] != DEVICE_ID) {
        fprintf(stderr, "Incorrect device ID: 0x%02X (expected 0x%02X)\n", buf[0], DEVICE_ID);
        return 1;
    }

    printf("Device ID: 0x%02X\n", buf[0]);
    return 0;
}

// Read the temperature from the TMP117
float read_temperature() {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read temperature: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    int16_t raw_temp = (buf[0] << 8) | buf[1];
    float temperature = raw_temp * TEMP_SCALE;
    return temperature;
}

// Log the temperature to the binary file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    if (fwrite(&temperature, sizeof(float), 1, log_file) != 1) {
        perror("Failed to write temperature to log file");
        return 1;
    }
    if (fwrite(&now, sizeof(time_t), 1, log_file) != 1) {
        perror("Failed to write timestamp to log file");
        return 1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

