    time_t now = time(NULL);
    if (fwrite(&temperature, sizeof(float), 1, log_file) != 1) {
        perror("Failed to write temperature to log file");
        return 1;
    }
    if (fwrite(&now, sizeof(time_t), 1, log_file) != 1) {
        perror("Failed to write timestamp to log file");
        return 1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

