#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define BUFFER_SIZE 60
#define SAMPLE_INTERVAL 5 // seconds

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for temperature data
typedef struct {
    time_t timestamp;
    float temperature;
} TemperatureData;

// Circular buffer structure
typedef struct {
    TemperatureData buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_pigpio();
int init_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float temperature);
void print_buffer(CircularBuffer *cb);
void flush_buffer(CircularBuffer *cb, const char *filename);
void signal_handler(int signal);

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from TMP117 sensor
float read_temperature() {
    char buf[2];
    int result = i2cReadDevice(i2c_handle, buf, 2);

    if (result != 2) {
        fprintf(stderr, "I2C read failed: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    int16_t raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    float temperature = raw_temp * 0.0625;

    return temperature;
}

// Add temperature reading to circular buffer
void add_to_buffer(CircularBuffer *cb, float temperature) {
    time(&cb->buffer[cb->head].timestamp);
    cb->buffer[cb->head].temperature = temperature;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Print contents of circular buffer
void print_buffer(CircularBuffer *cb) {
    printf("Temperature Buffer:\n");
    for (int i = 0; i < cb->count; i++) {
        int index = (cb->head - cb->count + i + BUFFER_SIZE) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&cb->buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Temperature: %.2f °C\n", timestamp_str, cb->buffer[index].temperature);
    }
}

// Flush contents of circular buffer to file
void flush_buffer(CircularBuffer *cb, const char *filename) {
    FILE *fp = fopen(filename, "wb");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open file for writing\n");
        return;
    }

    size_t elements_written = fwrite(cb->buffer, sizeof(TemperatureData), cb->count, fp);
    if (elements_written != cb->count) {
        fprintf(stderr, "Failed to write all elements to file\n");
    }

    fclose(fp);
    printf("Buffer flushed to %s\n", filename);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer temp_buffer;
    temp_buffer.head = 0;
    temp_buffer.count = 0;

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            add_to_buffer(&temp_buffer, temperature);
            printf("Temperature: %.2f °C\n", temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping sample.\n");
        }

        sleep(SAMPLE_INTERVAL);
    }

    // Flush buffer before exiting
    flush_buffer(&temp_buffer, "temperature_log.dat");

    // Close I2C connection
    i2cClose(i2c_handle);

    // Terminate pigpio
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

