#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define TEMP_REG 0x00
#define LOG_FILE "temperature_log.txt"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_temperature(float *temperature);
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional)
typedef struct {
    float temperature;
    int status;
} sensor_data_t;

int main() {
    float temperature;
    int status;

    // Register signal handler for graceful shutdown
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read temperature
        status = read_temperature(&temperature);

        // Log temperature
        if (status == 0) {
            if (log_temperature(temperature) != 0) {
                fprintf(stderr, "Failed to log temperature.\n");
            }
        } else {
            fprintf(stderr, "Failed to read temperature. Status: %d\n", status);
        }

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read temperature from TMP117 sensor
int read_temperature(float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
        if (result == 2) {
            // Combine the two bytes to form the 16-bit temperature value
            int16_t raw_temp = (buf[0] << 8) | buf[1];

            // Convert raw temperature to Celsius (see TMP117 datasheet)
            *temperature = (float)raw_temp * 0.0078125;

            // Check for negative temperatures
            if (*temperature < -40.0) {
                fprintf(stderr, "Temperature reading out of range: %.2f\n", *temperature);
                return -1; // Indicate error
            }

            return 0; // Indicate success
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS); // Wait before retrying
            retries++;
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries.\n", RETRY_COUNT);
    return -1; // Indicate failure after all retries
}

// Log temperature to file
int log_temperature(float temperature) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];
    FILE *fp;

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", LOG_FILE);
        return 1;
    }

    fprintf(fp, "%s, Temperature: %.2f C\n", timestamp, temperature);
    fclose(fp);

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

