#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define DHT11_PIN 4

// Define DHT11 timing constants (in microseconds)
#define DHT11_START_PULSE_LOW 18000
#define DHT11_START_PULSE_HIGH 40
#define DHT11_RESPONSE_LOW 80
#define DHT11_RESPONSE_HIGH 80
#define DHT11_BIT_PULSE_LOW 50
#define DHT11_BIT_PULSE_HIGH_0 26
#define DHT11_BIT_PULSE_HIGH_1 70

// Define DHT11 data structure
typedef struct {
    uint8_t humidity_integer;
    uint8_t humidity_decimal;
    uint8_t temperature_integer;
    uint8_t temperature_decimal;
    uint8_t checksum;
} DHT11Data;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int gpio_init();
int gpio_set_mode(int pin, int mode);
int gpio_write(int pin, int level);
int gpio_read(int pin);
int dht11_read(DHT11Data *data);
int dht11_verify_checksum(const DHT11Data *data);
int log_data(const DHT11Data *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO using pigpio
int gpio_init() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Set GPIO pin mode
int gpio_set_mode(int pin, int mode) {
    if (gpioSetMode(pin, mode) != 0) {
        fprintf(stderr, "Failed to set GPIO %d mode\n", pin);
        return -1;
    }
    return 0;
}

// Write a level to a GPIO pin
int gpio_write(int pin, int level) {
    if (gpioWrite(pin, level) != 0) {
        fprintf(stderr, "Failed to write to GPIO %d\n", pin);
        return -1;
    }
    return 0;
}

// Read a level from a GPIO pin
int gpio_read(int pin) {
    return gpioRead(pin);
}

// Read data from DHT11 sensor
int dht11_read(DHT11Data *data) {
    uint8_t raw_data[5] = {0};
    int i, j;

    // Send start signal
    if (gpio_write(DHT11_PIN, 0) != 0) {
        fprintf(stderr, "Failed to send start signal\n");
        return -1;
    }
    gpioDelay(DHT11_START_PULSE_LOW);
    if (gpio_write(DHT11_PIN, 1) != 0) {
        fprintf(stderr, "Failed to release start signal\n");
        return -1;
    }
    gpioDelay(DHT11_START_PULSE_HIGH);

    // Read response
    if (gpio_read(DHT11_PIN) != 0) {
        fprintf(stderr, "DHT11 response low timeout\n");
        return -1;
    }
    gpioDelay(DHT11_RESPONSE_LOW);
    if (gpio_read(DHT11_PIN) != 1) {
        fprintf(stderr, "DHT11 response high timeout\n");
        return -1;
    }
    gpioDelay(DHT11_RESPONSE_HIGH);

    // Read data bits
    for (i = 0; i < 40; i++) {
        // Wait for low period
        while (gpio_read(DHT11_PIN) == 1) {
            if (!running) return -1; // Timeout
        }
        gpioDelay(DHT11_BIT_PULSE_LOW);

        // Measure high period
        int high_time = 0;
        while (gpio_read(DHT11_PIN) == 0) {
            if (!running) return -1; // Timeout
            high_time++;
            gpioDelay(1); // Small delay to avoid busy-waiting
        }
        gpioDelay(DHT11_BIT_PULSE_HIGH);

        // Determine bit value
        if (high_time > DHT11_BIT_PULSE_HIGH_0) {
            raw_data[i / 8] |= (1 << (7 - (i % 8)));
        }
    }

    // Verify checksum
    if (dht11_verify_checksum(data) != 0) {
        fprintf(stderr, "DHT11 checksum failure\n");
        return -1;
    }

    // Store data
    data->humidity_integer = raw_data[0];
    data->humidity_decimal = raw_data[1];
    data->temperature_integer = raw_data[2];
    data->temperature_decimal = raw_data[3];
    data->checksum = raw_data[4];

    return 0;
}

// Verify DHT11 checksum
int dht11_verify_checksum(const DHT11Data *data) {
    uint8_t checksum = 0;
    checksum += data->humidity_integer;
    checksum += data->humidity_decimal;
    checksum += data->temperature_integer;
    checksum += data->temperature_decimal;

    if (checksum != data->checksum) {
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(const DHT11Data *data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, Humidity: %d.%d, Temperature: %d.%d, Checksum: %d\n",
            timestamp, data->humidity_integer, data->humidity_decimal,
            data->temperature_integer, data->temperature_decimal, data->checksum);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (gpio_init() != 0) {
        return 1;
    }

    // Set GPIO pin mode
    if (gpio_set_mode(DHT11_PIN, PI_OUTPUT) != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("dht11_readings.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    DHT11Data data;

    // Main loop
    while (running) {
        // Read DHT11 sensor
        if (dht11_read(&data) == 0) {
            // Log data
            log_data(&data);
            printf("Humidity: %d.%d, Temperature: %d.%d, Checksum: %d\n",
                   data.humidity_integer, data.humidity_decimal,
                   data.temperature_integer, data.temperature_decimal, data.checksum);
        } else {
            fprintf(stderr, "Failed to read DHT11 sensor\n");
        }

        // Wait for 2 seconds
        sleep(2);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

