    if (result != 0) {
        fprintf(stderr, "Error initializing sensor: %d\n", result);
        return -1;
    }
    gpioDelay(100); // Small delay after initialization
    return 0;
}

// Reads raw sensor data from the ADPD105
sensor_data_t read_sensor_data(int i2c_handle) {
    sensor_data_t data;
    char buffer[8]; // Assuming 8 bytes of data (2 bytes each for red, green, blue, clear)

    int result = i2cReadDevice(i2c_handle, buffer, sizeof(buffer));
    if (result != sizeof(buffer)) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        data.red = 0; data.green = 0; data.blue = 0; data.clear = 0; // Set to 0 on error
        return data;
    }

    // Assuming the data is in the correct order (Red, Green, Blue, Clear)
    data.red = (buffer[1] << 8) | buffer[0];
    data.green = (buffer[3] << 8) | buffer[2];
    data.blue = (buffer[5] << 8) | buffer[4];
    data.clear = (buffer[7] << 8) | buffer[6];

