#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75B_ADDR 0x48
#define FAN_GPIO 18
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 26.0
#define BUFFER_SIZE 60
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
float read_temperature();
void add_to_buffer(CircularBuffer *cb, float temp);
float calculate_average(CircularBuffer *cb);
void control_fan(float average_temp);
void signal_handler(int signal);
void cleanup();

// Initialize circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add temperature to circular buffer
void add_to_buffer(CircularBuffer *cb, float temp) {
    cb->buffer[cb->head] = temp;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate average temperature from circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75B_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from LM75B sensor
float read_temperature() {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // LM75B returns temperature in two bytes, MSB first
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            // Convert to Celsius (0.5 degrees Celsius per LSB)
            float temperature = raw_temp * 0.5;
            return temperature;
        } else {
            fprintf(stderr, "I2C read failed (attempt %d): %d\n", retries + 1, result);
            retries++;
            gpioDelay(10000); // Wait 10ms before retrying
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", RETRY_COUNT);
    return -1000.0; // Indicate error
}

// Control fan based on temperature
void control_fan(float average_temp) {
    if (average_temp > TEMP_THRESHOLD_HIGH) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else if (average_temp < TEMP_THRESHOLD_LOW) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(FAN_GPIO, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize circular buffer
    CircularBuffer temp_buffer;
    init_circular_buffer(&temp_buffer);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_GPIO, PI_OUTPUT);

    // Main loop
    while (!terminate) {
        // Read temperature
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            // Add temperature to buffer
            add_to_buffer(&temp_buffer, temperature);

            // Calculate average temperature
            float average_temp = calculate_average(&temp_buffer);

            // Control fan
            control_fan(average_temp);

            // Print temperature and average
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temp);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping this cycle\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second = 1000000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

