// Function to read data from the SDP810 sensor
int read_sdp810(int i2c_handle, float *pressure, float *temperature) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[9];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cWriteDevice(i2c_handle, cmd, 2);
        if (result == 0) {
            gpioDelay(45000); // Wait 45ms
            result = i2cReadDevice(i2c_handle, buffer, 9);
            if (result == 9) {
                // CRC validation
                uint8_t pressure_data[2] = {buffer[0], buffer[1]};
                uint8_t temperature_data[2] = {buffer[3], buffer[4]};
                uint8_t checksum_pressure = buffer[2];
                uint8_t checksum_temperature = buffer[5];

                if (crc8(pressure_data, 2) == checksum_pressure && crc8(temperature_data, 2) == checksum_temperature) {
                    // Convert data
                    int16_t raw_pressure = (buffer[0] << 8) | buffer[1];
                    int16_t raw_temperature = (buffer[3] << 8) | buffer[4];

                    *pressure = (float)raw_pressure / 240.0; // Scale factor from datasheet
                    *temperature = (float)raw_temperature / 200.0; // Scale factor from datasheet

                    return 0; // Success
                } else {
                    fprintf(stderr, "CRC mismatch: Pressure = %u, Temperature = %u\n", checksum_pressure, checksum_temperature);
                    fprintf(log_file, "%ld,CRC Mismatch,Pressure = %u,Temperature = %u\n", time(NULL), checksum_pressure, checksum_temperature);
                    fflush(log_file);
                }
            } else {
                fprintf(stderr, "I2C read error: %d\n", result);
                fprintf(log_file, "%ld,I2C Read Error,Result = %d\n", time(NULL), result);
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "I2C write error: %d\n", result);
            fprintf(log_file, "%ld,I2C Write Error,Result = %d\n", time(NULL), result);
            fflush(log_file);
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Exponential backoff
    }

    fprintf(stderr, "Failed to read sensor after %d retries.\n", MAX_RETRIES);
    fprintf(log_file, "%ld,Failed to Read Sensor after %d retries.\n", time(NULL), MAX_RETRIES);
    fflush(log_file);
    return -1; // Failure
}

// Function to log data to a file
void log_data(FILE *log_file, float pressure, float temperature) {
    time_t now = time(NULL);
    fprintf(log_file, "%ld,%.2f,%.2f\n", now, pressure, temperature);
    fflush(log_file);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SDP810_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float pressure, temperature;

    // Main loop
    while (!terminate) {
        if (read_sdp810(i2c_handle, &pressure, &temperature) == 0) {
            log_data(log_file, pressure, temperature);

            // Check for pressure threshold
            if (pressure > 5.0) {
                fprintf(stderr, "Warning: Pressure exceeds 5.0 Pa\n");
                fprintf(log_file, "%ld,Warning: Pressure exceeds 5.0 Pa\n", time(NULL));
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
            fprintf(log_file, "%ld,Failed to Read Sensor Data\n", time(NULL));
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Wait for 1 second
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

