// Constants
#define I2C_BUS 1
#define STTS2004_ADDR 0x4A
#define TEMP_REG 0x00
#define LED_GPIO 17
#define TEMP_THRESHOLD_HIGH 28.0
#define TEMP_THRESHOLD_LOW 27.0
#define I2C_RETRY_COUNT 3
#define I2C_RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_temperature(int i2c_handle, float *temperature);
void control_led(int gpio_pin, float temperature);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to read temperature from STTS2004
int read_temperature(int i2c_handle, float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < I2C_RETRY_COUNT) {
        result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
        if (result == 2) {
            // Convert raw data to temperature (Celsius)
            int16_t raw_temp = (buf[0] << 8) | buf[1];
            *temperature = (float)raw_temp / 200.0;
            return 0; // Success
        } else {
            log_error("Failed to read temperature data");
            gpioDelay(I2C_RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    return -1; // Failure after retries
}

// Function to control the LED based on temperature
void control_led(int gpio_pin, float temperature) {
    if (temperature > TEMP_THRESHOLD_HIGH) {
        gpioWrite(gpio_pin, 1); // Turn LED on
    } else if (temperature < TEMP_THRESHOLD_LOW) {
        gpioWrite(gpio_pin, 0); // Turn LED off
    }
}

// Function to log errors with timestamp
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(stderr, "%s: %s (errno: %d, %s)\n", timestamp, message, errno, strerror(errno));
}

