    i2c_handle = i2cOpen(I2C_BUS, STTS2004_ADDR, 0);
    if (i2c_handle < 0) {
        log_error("Failed to open I2C bus");
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        if (read_temperature(i2c_handle, &temperature) == 0) {
            printf("Temperature: %.2f °C\n", temperature);
            control_led(LED_GPIO, temperature);
        } else {
            log_error("Failed to read temperature, retrying...");
        }

        gpioDelay(1000000); // Delay for 1 second (1000000 microseconds)
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();

    printf("Temperature monitoring stopped.\n");

    return 0;
}

