#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDR 0x25

// Define the measurement command
#define MEASURE_CMD 0x362F

// Define the number of bytes to read from the sensor
#define NUM_BYTES 9

// Define the CRC polynomial
#define CRC_POLYNOMIAL 0x31

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t differential_pressure;
    int16_t temperature;
    uint8_t scale_factor[3];
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
uint8_t calculate_crc(const uint8_t *data, int len);
int validate_crc(const uint8_t *data, int len);
int log_data(const sensor_data_t *data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read data from the sensor
int read_sensor_data(sensor_data_t *data) {
    char buf[NUM_BYTES];
    int bytes_read;

    // Send the measurement command
    char cmd[2];
    cmd[0] = (MEASURE_CMD >> 8) & 0xFF;
    cmd[1] = MEASURE_CMD & 0xFF;

    if (i2cWriteDevice(i2c_handle, cmd, 2) != 2) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }

    // Wait for at least 45 ms
    gpioDelay(50000); // 50 ms

    // Read the data from the sensor
    bytes_read = i2cReadDevice(i2c_handle, buf, NUM_BYTES);
    if (bytes_read != NUM_BYTES) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }

    // Parse the data
    data->differential_pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    memcpy(data->scale_factor, buf + 6, 3);

    return 0;
}

// Function to calculate the CRC-8 checksum
uint8_t calculate_crc(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to validate the CRC-8 checksum
int validate_crc(const uint8_t *data, int len) {
    uint8_t calculated_crc = calculate_crc(data, len - 1);
    return (calculated_crc == data[len - 1]);
}

// Function to log the data to a file
int log_data(const sensor_data_t *data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Differential Pressure: %d Pa, Temperature: %d °C, Scale Factor: %d, %d, %d\n",
            timestamp, data->differential_pressure, data->temperature,
            data->scale_factor[0], data->scale_factor[1], data->scale_factor[2]);
    fflush(log_file); // Ensure data is written to the file immediately

    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("flow_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Validate CRC checksums
            if (validate_crc((uint8_t *)&sensor_data.differential_pressure, 2) &&
                validate_crc((uint8_t *)&sensor_data.temperature, 2) &&
                validate_crc((uint8_t *)sensor_data.scale_factor, 3)) {
                // Log the data
                log_data(&sensor_data);
            } else {
                fprintf(stderr, "CRC validation failed\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 1 second
        gpioDelay(1000000); // 1 second
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

