// STS40 I2C address
#define STS40_ADDR 0x44

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// CRC8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read temperature from STS40
float read_sts40_temperature() {
    uint8_t cmd[2] = {0xE3, 0x00}; // Trigger temperature measurement command
    uint8_t data[3];
    int result;

    // Send measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Wait for conversion to complete (at least 10 ms)
    gpioDelay(10000); // 10 ms

    // Read temperature data
    result = i2cReadDevice(i2c_handle, (char *)data, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1000.0; // Indicate error
    }

    // Verify CRC
    uint8_t crc = crc8(data, 2);
    if (crc != data[2]) {
        fprintf(stderr, "CRC check failed!\n");
