#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <pthread.h>

// Configuration
#define I2C_BUS 1
#define SCD40_ADDR 0x62
#define BUFFER_SIZE 100
#define LOG_FILE "/var/log/scd40_data/scd40_data.csv"
#define ERROR_LOG_FILE "/var/log/scd40_error.log"
#define LOGGING_INTERVAL 60 // seconds
#define SLEEP_INTERVAL 5 // seconds

// SCD40 Commands
#define CMD_START_PERIODIC_MEASUREMENT 0x21B1
#define CMD_READ_MEASUREMENT 0xE4B8
#define CMD_STOP_PERIODIC_MEASUREMENT 0x3F86

// CRC-8 Polynomial
#define CRC8_POLYNOMIAL 0x31

// Data Structure for Sensor Readings
typedef struct {
    time_t timestamp;
    float co2;
    float temperature;
    float humidity;
} SensorData;

// Circular Buffer Structure
typedef struct {
    SensorData buffer[BUFFER_SIZE];
    int head;
    int count;
    pthread_mutex_t mutex;
} CircularBuffer;

// Global Variables
int i2c_handle;
CircularBuffer data_buffer;
volatile sig_atomic_t running = 1;

// Function Prototypes
int init_scd40();
int start_periodic_measurement();
int read_measurement(uint16_t *co2, float *temperature, float *humidity);
int stop_periodic_measurement();
void add_to_buffer(CircularBuffer *buffer, time_t timestamp, float co2, float temperature, float humidity);
int get_from_buffer(CircularBuffer *buffer, int index, SensorData *data);
int write_to_csv(CircularBuffer *buffer, const char *filename);
void log_error(const char *message);
void signal_handler(int signal);
uint8_t crc8(const uint8_t *data, int len);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize SCD40 sensor
int init_scd40() {
    // Send start periodic measurement command
    char cmd[2] = {(CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to send start periodic measurement command");
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to start
    return 0;
}

// Start periodic measurement
int start_periodic_measurement() {
    char cmd[2] = {(CMD_START_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_START_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to send start periodic measurement command");
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to start
    return 0;
}

// Read measurement from SCD40
int read_measurement(uint16_t *co2, float *temperature, float *humidity) {
    char cmd[2] = {(CMD_READ_MEASUREMENT >> 8) & 0xFF, CMD_READ_MEASUREMENT & 0xFF};
    char buffer[9];
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to send read measurement command");
        return -1;
    }
    gpioDelay(10); // Wait for measurement (adjust as needed)

    result = i2cReadDevice(i2c_handle, buffer, 9);
    if (result != 9) {
        log_error("Failed to read measurement data");
        return -1;
    }

    // CRC Check
    if (crc8(buffer, 2) != buffer[2] || crc8(buffer + 3, 2) != buffer[5] || crc8(buffer + 6, 2) != buffer[8]) {
        log_error("CRC check failed");
        return -1;
    }

    // Convert data
    *co2 = (buffer[0] << 8) | buffer[1];
    *temperature = -45 + 175 * (float)((buffer[3] << 8) | buffer[4]) / 65535.0;
    *humidity = 100 * (float)((buffer[6] << 8) | buffer[7]) / 65535.0;

    return 0;
}

// Stop periodic measurement
int stop_periodic_measurement() {
    char cmd[2] = {(CMD_STOP_PERIODIC_MEASUREMENT >> 8) & 0xFF, CMD_STOP_PERIODIC_MEASUREMENT & 0xFF};
    int result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        log_error("Failed to send stop periodic measurement command");
        return -1;
    }
    gpioDelay(100); // Wait for the sensor to stop
    return 0;
}

// Add data to circular buffer
void add_to_buffer(CircularBuffer *buffer, time_t timestamp, float co2, float temperature, float humidity) {
    pthread_mutex_lock(&buffer->mutex);
    buffer->buffer[buffer->head].timestamp = timestamp;
    buffer->buffer[buffer->head].co2 = co2;
    buffer->buffer[buffer->head].temperature = temperature;
    buffer->buffer[buffer->head].humidity = humidity;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
    pthread_mutex_unlock(&buffer->mutex);
}

// Get data from circular buffer
int get_from_buffer(CircularBuffer *buffer, int index, SensorData *data) {
    if (index < 0 || index >= buffer->count) {
        return -1; // Invalid index
    }
    pthread_mutex_lock(&buffer->mutex);
    int actual_index = (buffer->head - buffer->count + index + BUFFER_SIZE) % BUFFER_SIZE;
    *data = buffer->buffer[actual_index];
    pthread_mutex_unlock(&buffer->mutex);
    return 0;
}

// Write data to CSV file
int write_to_csv(CircularBuffer *buffer, const char *filename) {
    FILE *fp = fopen(filename, "a");
    if (fp == NULL) {
        log_error("Failed to open CSV file for writing");
        return -1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,CO2 (ppm),Temperature (C),Humidity (%%RH)\n");
    }

    pthread_mutex_lock(&buffer->mutex);
    int start_index = (buffer->head - buffer->count + BUFFER_SIZE) % BUFFER_SIZE;
    for (int i = 0; i < buffer->count; i++) {
        int actual_index = (start_index + i) % BUFFER_SIZE;
        fprintf(fp, "%ld,%.2f,%.2f,%.2f\n", buffer->buffer[actual_index].timestamp, buffer->buffer[actual_index].co2, buffer->buffer[actual_index].temperature, buffer->buffer[actual_index].humidity);
    }
    pthread_mutex_unlock(&buffer->mutex);

    fclose(fp);
    return 0;
}

// Log error messages to file
void log_error(const char *message) {
    FILE *fp = fopen(ERROR_LOG_FILE, "a");
    if (fp == NULL) {
        perror("Failed to open error log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] ERROR: %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, SCD40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    data_buffer.head = 0;
    data_buffer.count = 0;
    pthread_mutex_init(&data_buffer.mutex, NULL);

    // Initialize SCD40 sensor
    if (init_scd40() != 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (running) {
        uint16_t co2;
        float temperature, humidity;

        // Read measurement
        if (read_measurement(&co2, &temperature, &humidity) == 0) {
            // Get current timestamp
            time_t now = time(NULL);

            // Add data to buffer
            add_to_buffer(&data_buffer, now, co2, temperature, humidity);

            // Log data to console
            printf("CO2: %.2f ppm, Temperature: %.2f C, Humidity: %.2f %%RH\n", co2, temperature, humidity);
        } else {
            log_error("Failed to read sensor data");
        }

        // Sleep for the specified interval
        sleep(SLEEP_INTERVAL);
    }

    // Stop periodic measurement
    stop_periodic_measurement();

    // Write data to CSV file
    write_to_csv(&data_buffer, LOG_FILE);

    // Clean up
    pthread_mutex_destroy(&data_buffer.mutex);
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

