sensor_data_t process_sensor_data(const uint8_t *data) {
    sensor_data_t sensor_data;

    // Extract raw values
    int16_t raw_pressure = (data[0] << 8) | data[1];
    int16_t raw_temperature = (data[3] << 8) | data[4];
    int16_t raw_scale_factor = (data[6] << 8) | data[7];

    // CRC validation
    if (crc8(data, 2) != data[2] || crc8(data + 3, 2) != data[5] || crc8(data + 6, 2) != data[8]) {
        fprintf(stderr, "CRC check failed\n");
        sensor_data.pressure = -1000.0; // Indicate CRC failure
        sensor_data.temperature = -1000.0;
        sensor_data.scale_factor = -1000.0;
        return sensor_data;
