#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define constants
#define I2C_BUS 1
#define ICP10125_ADDR 0x69
#define LED_GPIO 17
#define PRESSURE_THRESHOLD 95000.0 // Pa
#define PRESSURE_HYSTERESIS 5000.0 // Pa
#define SAMPLE_INTERVAL_MS 20
#define POLLING_INTERVAL_MS 1000

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
    uint8_t crc;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int open_i2c_connection();
int read_sensor_data(sensor_data_t *data);
void verify_crc(const sensor_data_t *data);
void control_led(int on);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C connection
int open_i2c_connection() {
    i2c_handle = i2cOpen(I2C_BUS, ICP10125_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read sensor data from ICP-10125
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int result = i2cReadDevice(i2c_handle, buf, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read sensor data: %d\n", result);
        return -1;
    }

    data->pressure = (int16_t)((buf[0] << 8) | buf[1]);
    data->temperature = (int16_t)((buf[3] << 8) | buf[4]);
    data->crc = buf[5];

    return 0;
}

// Verify CRC checksum
void verify_crc(const sensor_data_t *data) {
    uint8_t crc_calculated = crc8((uint8_t *)data, 4);
    if (crc_calculated != data->crc) {
        fprintf(stderr, "CRC check failed! Calculated: 0x%02X, Received: 0x%02X\n", crc_calculated, data->crc);
    }
}

// Control LED state
void control_led(int on) {
    gpioWrite(LED_GPIO, on);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    i2cClose(i2c_handle);
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Open I2C connection
    if (open_i2c_connection() != 0) {
        cleanup();
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    sensor_data_t sensor_data;
    int led_state = 0; // 0 = off, 1 = on
    time_t last_blink_time = 0;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Verify CRC
            verify_crc(&sensor_data);

            // Check pressure threshold
            if (sensor_data.pressure < PRESSURE_THRESHOLD) {
                // Toggle LED state
                led_state = !led_state;
                control_led(led_state);

                // Blink LED at 1 Hz
                time_t current_time = time(NULL);
                if (current_time - last_blink_time >= 1) {
                    if (led_state) {
                        gpioWrite(LED_GPIO, 0); // Turn off LED
                    } else {
                        gpioWrite(LED_GPIO, 1); // Turn on LED
                    }
                    last_blink_time = current_time;
                }
            } else {
                // Turn off LED
                control_led(0);
            }
        } else {
            // Handle sensor read error (e.g., retry or exit)
            fprintf(stderr, "Error reading sensor data, retrying...\n");
            // Attempt to re-initialize I2C
            i2cClose(i2c_handle);
            if (open_i2c_connection() != 0) {
                fprintf(stderr, "Failed to re-initialize I2C, exiting...\n");
                terminate = 1; // Exit loop if re-initialization fails
            }
        }

        // Delay for sampling interval
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

