#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define MLX90614_ADDR 0x5A
#define AMBIENT_TEMP_REG 0x06
#define OBJECT_TEMP_REG 0x07
#define FAN_GPIO 18
#define AMBIENT_TEMP_MIN 10.0
#define AMBIENT_TEMP_MAX 40.0
#define OBJECT_TEMP_MIN 20.0
#define OBJECT_TEMP_MAX 60.0
#define FAN_ON_TEMP 30.0
#define FAN_OFF_TEMP 28.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int open_i2c_bus();
int read_temperature(int reg);
float convert_to_celsius(int raw_temp);
int log_temperature(float ambient_temp, float object_temp);
void control_fan(float object_temp);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data
typedef struct {
    float ambient_temp;
    float object_temp;
} sensor_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Open I2C bus
int open_i2c_bus() {
    i2c_handle = i2cOpen(I2C_BUS, MLX90614_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature from a specific register
int read_temperature(int reg) {
    int raw_temp = -1;
    int retries = 0;

    while (retries < RETRY_COUNT) {
        raw_temp = i2cReadWordData(i2c_handle, reg);
        if (raw_temp >= 0) {
            return raw_temp;
        } else {
            fprintf(stderr, "I2C read failed (reg 0x%02X), retry %d/%d\n", reg, retries + 1, RETRY_COUNT);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read temperature after %d retries\n", RETRY_COUNT);
    return -1; // Indicate failure
}

// Convert raw temperature to Celsius
float convert_to_celsius(int raw_temp) {
    return (float)raw_temp * 0.02 - 273.15;
}

// Log temperature data to file
int log_temperature(float ambient_temp, float object_temp) {
    FILE *fp = fopen("temperature_log.txt", "a");
    if (fp == NULL) {
        fprintf(stderr, "Failed to open temperature_log.txt\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, Ambient: %.2f °C, Object: %.2f °C\n", timestamp, ambient_temp, object_temp);
    fclose(fp);
    return 0;
}

// Control fan based on object temperature
void control_fan(float object_temp) {
    if (object_temp > FAN_ON_TEMP) {
        gpioWrite(FAN_GPIO, 1); // Turn fan on
    } else if (object_temp < FAN_OFF_TEMP) {
        gpioWrite(FAN_GPIO, 0); // Turn fan off
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioWrite(FAN_GPIO, 0); // Turn off fan
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        return 1;
    }

    // Open I2C bus
    if (open_i2c_bus() != 0) {
        cleanup();
        return 1;
