#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SHT40_ADDR 0x44
#define MEASURE_CMD 0xFD
#define SERVER_PORT 8080
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10
#define HUMIDITY_CLAMP_MIN 0.0
#define HUMIDITY_CLAMP_MAX 100.0

// Global variables
int i2c_handle;
int server_fd;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float temperature;
    float humidity;
} sensor_data_t;

// Function prototypes
int init_i2c();
int read_sht40(sensor_data_t *data);
int stream_data(sensor_data_t data);
void handle_signal(int signal);
void cleanup();

// Signal handler for graceful shutdown
void handle_signal(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SHT40_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read temperature and humidity from SHT40 sensor
int read_sht40(sensor_data_t *data) {
    unsigned char cmd[2] = {MEASURE_CMD, 0x00};
    unsigned char buffer[6];
    int retries = 0;

    while (retries < MAX_RETRIES) {
        if (i2cWriteDevice(i2c_handle, cmd, 2) == 2) {
            gpioDelay(10); // Wait for measurement (at least 10ms)
            if (i2cReadDevice(i2c_handle, buffer, 6) == 6) {
                // Convert data
                int temperature_raw = (buffer[0] << 8) | buffer[1];
                int humidity_raw = (buffer[3] << 8) | buffer[4];

                data->temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);
                data->humidity = 100.0 * (float)humidity_raw / 65535.0;

                // Clamp humidity to the range 0-100%
                if (data->humidity < HUMIDITY_CLAMP_MIN) {
                    data->humidity = HUMIDITY_CLAMP_MIN;
                } else if (data->humidity > HUMIDITY_CLAMP_MAX) {
                    data->humidity = HUMIDITY_CLAMP_MAX;
                }

                return 0; // Success
            } else {
                fprintf(stderr, "Error reading data from I2C (attempt %d): %d\n", retries + 1, i2c_handle);
            }
        } else {
            fprintf(stderr, "Error writing to I2C (attempt %d): %d\n", retries + 1, i2c_handle);
        }
        retries++;
        gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
    }

    fprintf(stderr, "Failed to read SHT40 after %d retries.\n", MAX_RETRIES);
    return -1; // Failure
}

// Stream data to HTTP server
int stream_data(sensor_data_t data) {
    char response[256];
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    snprintf(response, sizeof(response),
             "HTTP/1.1 200 OK\r\n"
             "Content-Type: text/html\r\n"
             "Content-Length: %d\r\n"
             "\r\n"
             "<!DOCTYPE html><html><head><title>SHT40 Data</title></head><body><h1>SHT40 Data</h1><p>Timestamp: %s</p><p>Temperature: %.2f °C</p><p>Humidity: %.2f %%</p></body></html>",
             strlen(response), timestamp, data.temperature, data.humidity);

    if (send(server_fd, response, strlen(response), 0) < 0) {
        perror("Error sending data to server");
        return -1;
    }
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (server_fd >= 0) {
        close(server_fd);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, handle_signal);
    signal(SIGTERM, handle_signal);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Create socket
    server_fd = socket(AF_INET, SOCK_STREAM, 0);
    if (server_fd == 0) {
        perror("Socket creation failed");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(SERVER_PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("Bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        perror("Listen failed");
        cleanup();
        return 1;
    }

    printf("Server listening on port %d...\n", SERVER_PORT);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Accept connection
        int client_fd = accept(server_fd, (struct sockaddr *)NULL, NULL);
        if (client_fd < 0) {
            perror("Accept failed");
            continue; // Continue listening for other connections
        }

        // Read sensor data
        if (read_sht40(&sensor_data) == 0) {
            // Stream data
            if (stream_data(sensor_data) != 0) {
                fprintf(stderr, "Error streaming data.\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data.\n");
        }

        // Close connection
        close(client_fd);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

