#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <errno.h>

// Constants
#define I2C_BUS 1
#define TMP102_ADDR 0x48
#define TEMP_REG 0x00
#define CSV_FILE "temperature_log.csv"
#define SLEEP_SECONDS 5

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for configuration (optional)
typedef struct {
    int i2c_bus;
    int tmp102_address;
    const char *csv_filename;
    int sleep_seconds;
} config_t;

// Function prototypes
int init_i2c();
int read_temperature(float *temperature);
int log_temperature(float temperature);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, TMP102_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read temperature from TMP102
int read_temperature(float *temperature) {
    char buf[2];
    int result = i2cReadI2CBlockData(i2c_handle, TEMP_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %s\n", strerror(errno));
        return -1;
    }

    // Convert raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    *temperature = (float)raw_temp * 0.0625;

    return 0;
}

// Log temperature to CSV file
int log_temperature(float temperature) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, temperature);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open CSV file for logging
    log_file = fopen(CSV_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening CSV file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Write CSV header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature (C)\n");
    }
    rewind(log_file);

    float temperature;

    // Main loop
    while (!terminate) {
        if (read_temperature(&temperature) == 0) {
            log_temperature(temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, skipping logging.\n");
        }

        gpioSleep(PI_TIME_RELATIVE, SLEEP_SECONDS, 0); // Sleep for 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

