#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define SDP800_ADDR 0x25

// Define the measurement command
#define MEASURE_CMD 0x362F

// Define the CRC-8 polynomial
#define CRC8_POLYNOMIAL 0x31

// Global variables for I2C handle and program termination
int i2c_handle = -1;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t pressure;
    int16_t temperature;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sdp800(sensor_data_t *data);
uint8_t crc8(const uint8_t *data, int len);
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, SDP800_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read data from the SDP800 sensor
int read_sdp800(sensor_data_t *data) {
    char cmd[2] = {(MEASURE_CMD >> 8) & 0xFF, MEASURE_CMD & 0xFF};
    char buffer[6];
    int result;

    // Send the measurement command
    result = i2cWriteDevice(i2c_handle, cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }

    // Wait for 45 milliseconds
    gpioDelay(45000); // 45 ms

    // Read 6 bytes of data
    result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 6) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Extract the pressure and temperature values
    data->pressure = (int16_t)((buffer[0] << 8) | buffer[1]);
    data->temperature = (int16_t)((buffer[3] << 8) | buffer[4]);

    // Validate CRC checksums
    if (crc8(buffer, 2) != buffer[2]) {
        fprintf(stderr, "Pressure CRC check failed\n");
        return -1;
    }
    if (crc8(buffer + 3, 2) != buffer[5]) {
        fprintf(stderr, "Temperature CRC check failed\n");
        return -1;
    }

    return 0;
}

// Function to calculate CRC-8 checksum
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to log the sensor data to the console
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("%s - Pressure: %d Pa, Temperature: %d °C\n", timestamp, data.pressure, data.temperature);
}

// Function to perform cleanup before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    gpioTerminate();
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    if (initialize_i2c() != 0) {
        return 1;
    }

    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read data from the sensor
        if (read_sdp800(&sensor_data) == 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 500 milliseconds
        gpioDelay(500000); // 500 ms
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

