#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration structure
typedef struct {
    float setpoint;
    float Kp;
    float Ki;
    float Kd;
    int relay_gpio;
    int pwm_gpio;
    int pwm_frequency;
    char log_file[64];
} Config;

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static Config config;

// Function prototypes
int read_config(const char *filename, Config *config);
int init_gpio();
int init_ds18b20();
float read_temperature(int sensor_id);
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error, float Kp, float Ki, float Kd);
void set_pwm(int duty_cycle);
void control_relay(int state);
void log_data(float average_temperature, float setpoint, float pid_output, int duty_cycle);
void signal_handler(int signal);

// CRC-8 calculation function
unsigned char crc8(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read configuration from file
int read_config(const char *filename, Config *config) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "setpoint") == 0) {
                config->setpoint = atof(value);
            } else if (strcmp(key, "Kp") == 0) {
                config->Kp = atof(value);
            } else if (strcmp(key, "Ki") == 0) {
                config->Ki = atof(value);
            } else if (strcmp(key, "Kd") == 0) {
                config->Kd = atof(value);
            } else if (strcmp(key, "relay_gpio") == 0) {
                config->relay_gpio = atoi(value);
            } else if (strcmp(key, "pwm_gpio") == 0) {
                config->pwm_gpio = atoi(value);
            } else if (strcmp(key, "pwm_frequency") == 0) {
                config->pwm_frequency = atoi(value);
            } else if (strcmp(key, "log_file") == 0) {
                strncpy(config->log_file, value, sizeof(config->log_file) - 1);
                config->log_file[sizeof(config->log_file) - 1] = '\0'; // Ensure null termination
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(config.relay_gpio, PI_OUTPUT);
    gpioSetMode(config.pwm_gpio, PI_OUTPUT);
    gpioSetPWMfrequency(config.pwm_gpio, config.pwm_frequency);
    gpioSetPWMrange(config.pwm_gpio, 1000); // Set PWM range to 0-1000

    return 0;
}

// Function to initialize DS18B20 sensor
int init_ds18b20() {
    // Add initialization code here if needed for DS18B20 initialization
    // For example, you might need to send specific commands to the sensor
    // to configure it for 1-Wire communication.
    // This is a placeholder.
    return 0;
}

// Function to read temperature from DS18B20 sensor
float read_temperature(int sensor_id) {
    char sensor_path[64];
    snprintf(sensor_path, sizeof(sensor_path), "/sys/bus/w1/devices/28-%02X/w1_slave", sensor_id);

    FILE *fp = fopen(sensor_path, "r");
    if (fp == NULL) {
        perror("Error opening sensor file");
        return -1000.0; // Indicate error with a very low temperature
    }

    char line1[256], line2[256];
    if (fgets(line1, sizeof(line1), fp) == NULL || fgets(line2, sizeof(line2), fp) == NULL) {
        fclose(fp);
        return -1000.0; // Indicate error with a very low temperature
    }

    fclose(fp);

    unsigned char crc1, crc2;
    int temperature_raw;

    // Check for CRC errors
    crc1 = crc8((unsigned char *)line1, strlen(line1) - 1);
    crc2 = crc8((unsigned char *)line2, strlen(line2) - 1);

    if (crc1 != line1[strlen(line1) - 1] || crc2 != line2[strlen(line2) - 1]) {
        fprintf(stderr, "CRC error for sensor %d\n", sensor_id);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Extract temperature data
    temperature_raw = atoi(strstr(line2, "t=") + 2);
    return (float)temperature_raw / 1000.0;
}

// Function to calculate PID output
float calculate_pid(float setpoint, float actual_temperature, float *integral, float *previous_error, float Kp, float Ki, float Kd) {
    float error = setpoint - actual_temperature;
    *integral += error;
    float derivative = error - *previous_error;
    float output = Kp * error + Ki * (*integral) + Kd * derivative;
    *previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm(int duty_cycle) {
    gpioPWM(config.pwm_gpio, duty_cycle);
}

// Function to control the relay
void control_relay(int state) {
    gpioWrite(config.relay_gpio, state);
}

// Function to log data to file
void log_data(float average_temperature, float setpoint, float pid_output, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(log_file, "%d-%02d-%02d %02d:%02d:%02d, %.2f, %.2f, %.2f, %d\n",
            tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec,
            average_temperature, setpoint, pid_output, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
