#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define AHT20_ADDR 0x38
#define GPIO_RELAY 17
#define HUMIDITY_THRESHOLD_HIGH 60.0
#define HUMIDITY_THRESHOLD_LOW 55.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10
#define MEASUREMENT_DELAY_MS 80

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int aht20_init();
int aht20_read_data(uint8_t *data);
float calculate_humidity(uint8_t *data);
void control_relay(float humidity);
void log_data(float humidity);
void signal_handler(int signal);

// Structure for AHT20 data (optional, but good practice)
typedef struct {
    uint32_t humidity;
    uint32_t temperature;
} aht20_data_t;

// AHT20 Initialization Function
int aht20_init() {
    // No specific initialization needed for AHT20 in this example.
    // The sensor can be used directly without initialization.
    return 0; // Indicate success
}

// AHT20 Read Data Function
int aht20_read_data(uint8_t *data) {
    char cmd[3] = {0xAC, 0x33, 0x00}; // Trigger measurement command
    int result;

    result = i2cWriteDevice(i2c_handle, cmd, 3);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    gpioDelay(MEASUREMENT_DELAY_MS * 1000); // Delay for measurement

    result = i2cReadDevice(i2c_handle, (char *)data, 6);
    if (result != 6) {
        fprintf(stderr, "Error reading from I2C device: %d\n", result);
        return -1;
    }

    return 0; // Indicate success
}

// Calculate Humidity Function
float calculate_humidity(uint8_t *data) {
    uint32_t humidity_raw = ((uint32_t)data[1] << 12) | ((uint32_t)data[2] << 4) | ((uint32_t)data[3] >> 4);
    return ((float)humidity_raw / 0x100000) * 100.0;
}

// Control Relay Function
void control_relay(float humidity) {
    if (humidity > HUMIDITY_THRESHOLD_HIGH) {
        gpioWrite(GPIO_RELAY, 1); // Activate relay (HIGH)
    } else if (humidity < HUMIDITY_THRESHOLD_LOW) {
        gpioWrite(GPIO_RELAY, 0); // Deactivate relay (LOW)
    }
}

// Log Data Function
void log_data(float humidity) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Humidity: %.2f%%\n", timestamp, humidity);
}

// Signal Handler Function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, cleaning up...\n");
    terminate = 1;
}

int main() {
    uint8_t data[6];
    float humidity;
    int retry;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize AHT20 sensor
    if (aht20_init() != 0) {
        fprintf(stderr, "AHT20 initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (aht20_read_data(data) == 0) {
                // Verify status byte
                if ((data[0] & 0x80) == 0) {
                    humidity = calculate_humidity(data);
                    log_data(humidity);
                    control_relay(humidity);
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "Error: Sensor busy or calibration failed\n");
                }
            } else {
                fprintf(stderr, "Error reading sensor data, retry %d/%d\n", retry + 1, RETRY_COUNT);
            }

            retry++;
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay before retrying
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Error: Failed to read sensor data after %d retries\n", RETRY_COUNT);
        }

        gpioDelay(5000 * 1000); // Wait 5 seconds
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    gpioTerminate();

    return 0;
}

