            if (json_data != NULL) {
                if (send_http_request(json_data) != 0) {
                    syslog(LOG_ERR, "HTTP request failed");
                }
                free(json_data);
            } else {
                syslog(LOG_ERR, "Failed to format JSON data");
            }
        } else {
            syslog(LOG_ERR, "Failed to read humidity");
        }

        sleep(config.poll_interval);
    }

    // Cleanup and exit
    cleanup();
    gpioTerminate();
    closelog();
    return 0;
}

