int init_i2c() {
    i2c_handle = i2cOpen(config.i2c_bus, config.htu21d_address, 0);
    if (i2c_handle < 0) {
        syslog(LOG_ERR, "Failed to open I2C device: %d", i2c_handle);
        return 1;
    }
    syslog(LOG_INFO, "I2C device opened successfully");
    return 0;
}

// Read humidity from HTU21D sensor
float read_humidity() {
    unsigned char cmd = 0xE5; // Measure humidity command
    int retries = 0;
    int result;

    while (retries < config.max_retries) {
        result = i2cWriteByte(i2c_handle, cmd);
        if (result == 0) {
            gpioDelay(50); // Wait for measurement (datasheet specifies 40ms)
            unsigned char data[3];
            result = i2cReadDevice(i2c_handle, (char*)data, 3);
            if (result == 3) {
                // CRC check
                unsigned char crc = data[2];
                unsigned char crc_calculated = (data[0] + data[1]) & 0xFF;
                if (crc == crc_calculated) {
                    // Convert data to humidity
                    unsigned int humidity_raw = (data[0] << 8) | data[1];
                    float humidity = (float)humidity_raw / 65536.0 * 100.0;
                    return humidity;
                } else {
                    syslog(LOG_ERR, "CRC check failed (calculated: 0x%02X, received: 0x%02X)", crc_calculated, crc);
                }
            } else {
                syslog(LOG_ERR, "Failed to read data from I2C device: %d", result);
            }
