// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// I2C initialization function
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP280_I2C_ADDR, 0); // Bus 1, address 0x76, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Check the chip ID
    int chip_id = i2cReadByteData(i2c_handle, BMP280_REG_ID);
    if (chip_id != 0x58) {
        fprintf(stderr, "Error: Invalid chip ID: 0x%x\n", chip_id);
        i2cClose(i2c_handle);
        return -1;
    }

    // Set oversampling and power mode
    i2cWriteByteData(i2c_handle, BMP280_REG_CTRL_MEAS, 0x3F); // Temperature x1, Pressure x1, Normal mode
    i2cWriteByteData(i2c_handle, BMP280_REG_CONFIG, 0x00); // t_sb = 0.5ms, filter off

    return 0;
}

// Function to read calibration data from the BMP280
int read_calibration_data(struct bmp280_calib_data *calib) {
    calib->dig_T1 = i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00);
    calib->dig_T2 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 2);
    calib->dig_T3 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 4);
    calib->dig_P1 = i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 6);
    calib->dig_P2 = (int16_t)i2cReadWordData(i2c_handle, BMP280_REG_CALIB_00 + 8);
