#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define TMP117_ADDR 0x48
#define AHT20_ADDR 0x38
#define PIR_GPIO 17
#define LOG_DIR "/var/log/motion_detection/"
#define SAMPLE_INTERVAL_SEC 1
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle_tmp117 = -1;
int i2c_handle_aht20 = -1;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int read_tmp117(int i2c_handle, float *temperature);
int read_aht20(int i2c_handle, float *temperature, float *humidity);
int read_pir_sensor(int gpio);
int log_data(const char *filename, float temperature, float humidity, int motion_detected);
int create_log_file(const char *filename);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read temperature from TMP117
int read_tmp117(int i2c_handle, float *temperature) {
    char buf[2];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, buf, 2);
        if (result == 2) {
            // Check status bits (bit 7 of the first byte)
            if (buf[0] & 0x80) {
                fprintf(stderr, "TMP117: Error: Status bit set (0x%02X)\n", buf[0]);
                return -1; // Indicate error
            }

            // Convert raw data to temperature (Celsius)
            int raw_temp = (buf[0] << 4) | (buf[1] >> 4);
            *temperature = (float)raw_temp * 0.0625;
            return 0; // Success
        } else {
            fprintf(stderr, "TMP117: I2C read error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "TMP117: Failed to read temperature after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure after retries
}

// Function to read humidity from AHT20
int read_aht20(int i2c_handle, float *temperature, float *humidity) {
    char buf[6];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadDevice(i2c_handle, buf, 6);
        if (result == 6) {
            // Check status bits (bit 7 of the first byte)
            if (buf[0] & 0x80) {
                fprintf(stderr, "AHT20: Error: Status bit set (0x%02X)\n", buf[0]);
                return -1; // Indicate error
            }

            // Convert raw data to temperature and humidity
            unsigned long raw_humidity = ((unsigned long)buf[1] << 12) | ((unsigned long)buf[2] << 4) | ((unsigned long)buf[3] >> 4);
            unsigned long raw_temperature = ((unsigned long)buf[3] & 0x0F) << 16 | ((unsigned long)buf[4] << 8) | (unsigned long)buf[5];

            *humidity = (float)raw_humidity / 0x100000;
            *temperature = (float)raw_temperature / 0x100000;

            return 0; // Success
        } else {
            fprintf(stderr, "AHT20: I2C read error (attempt %d): %d\n", retries + 1, result);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "AHT20: Failed to read humidity after %d retries\n", MAX_RETRIES);
    return -1; // Indicate failure after retries
}

// Function to read motion detection from PIR sensor
int read_pir_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log data to CSV file
int log_data(const char *filename, float temperature, float humidity, int motion_detected) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open file in append mode
    fp = fopen(filename, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", filename);
        return -1;
    }

    // Write header if the file is newly created
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");
    }

    // Write data to file
    fprintf(fp, "%s,%.2f,%.2f,%d\n", timestamp, temperature, humidity, motion_detected);

    // Close file
    fclose(fp);

    return 0;
}

// Function to create a new log file at midnight
int create_log_file(const char *filename) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char new_filename[256];

    // Format filename with timestamp
    strftime(new_filename, sizeof(new_filename), "%Y-%m-%d_%H%M%S.csv", &tm);

    // Create new file with the same name
    FILE *fp = fopen(new_filename, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error creating log file %s\n", new_filename);
        return -1;
    }

    // Write header
    fprintf(fp, "Timestamp,Temperature(C),Humidity(%),MotionDetected\n");

    // Close file
    fclose(fp);

    return 0;
}

int main() {
    float temperature_tmp117, humidity_aht20;
    int motion_detected;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char filename[256];

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set PIR GPIO as input
    gpioSetMode(PIR_GPIO, PI_INPUT);

    // Open I2C bus for TMP117
    i2c_handle_tmp117 = i2cOpen(I2C_BUS, TMP117_ADDR, 0);
    if (i2c_handle_tmp117 < 0) {
        fprintf(stderr, "Error opening I2C bus for TMP117: %d\n", i2c_handle_tmp117);
        gpioTerminate();
        return 1;
    }

    // Open I2C bus for AHT20
    i2c_handle_aht20 = i2cOpen(I2C_BUS, AHT20_ADDR, 0);
    if (i2c_handle_aht20 < 0) {
        fprintf(stderr, "Error opening I2C bus for AHT20: %d\n", i2c_handle_aht20);
        i2cClose(i2c_handle_tmp117);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_tmp117(i2c_handle_tmp117, &temperature_tmp117) != 0) {
            fprintf(stderr, "Failed to read temperature from TMP117\n");
            temperature_tmp117 = -999.0; // Indicate error
        }
        if (read_aht20(i2c_handle_aht20, &temperature_tmp117, &humidity_aht20) != 0) {
            fprintf(stderr, "Failed to read humidity from AHT20\n");
            humidity_aht20 = -999.0; // Indicate error
        }
        motion_detected = read_pir_sensor(PIR_GPIO);

        // Get current timestamp
        time_t t = time(NULL);
        struct tm tm = *localtime(&t);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

        // Log data to file
        if (temperature_tmp117 != -999.0 && humidity_aht20 != -999.0) {
            snprintf(filename, sizeof(filename), "%s%s.csv", LOG_DIR, timestamp);
            if (log_data(filename, temperature_tmp117, humidity_aht20, motion_detected) != 0) {
                fprintf(stderr, "Failed to log data to file\n");
            }
        } else {
            fprintf(stderr, "Skipping logging data due to sensor errors\n");
        }

        // Create new log file at midnight
        t = time(NULL);
        tm = *localtime(&t);
        if (tm.tm_hour == 0) {
            strftime(filename, sizeof(filename), "%Y-%m-%d_%H%M%S.csv", &tm);
            if (create_log_file(filename) != 0) {
                fprintf(stderr, "Failed to create log file\n");
            }
        }

        // Wait for the next sample
        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    // Close I2C bus
    i2cClose(i2c_handle_tmp117);
    i2cClose(i2c_handle_aht20);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

