void close_window() {
    log_event("Closing window...");
    gpioWrite(MOTOR_IN1_PIN, 1); // Set IN1 HIGH
    gpioWrite(MOTOR_IN2_PIN, 0); // Set IN2 LOW
    gpioPWM(MOTOR_ENA_PIN, MOTOR_SPEED); // Set PWM duty cycle
    gpioDelay(MOTOR_DURATION); // Run motor for specified duration
    stop_motor(); // Stop the motor
    log_event("Window closed.");
}

// Function to stop the motor
void stop_motor() {
    log_event("Stopping motor...");
    gpioPWM(MOTOR_ENA_PIN, 0); // Set PWM duty cycle to 0 to stop the motor
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

