    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Set PWM range (optional, adjust as needed)
    gpioSetPWMrange(MOTOR_ENA_PIN, 255);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Program started");

    // Main loop
    while (program_running) {
        int rain_detected = read_rain_sensor();
        if (rain_detected == 0) {
            log_event("Rain detected!");
            close_window();
        } else if (rain_detected < 0) {
            // Error already logged in read_rain_sensor
            gpioDelay(2000); // Wait 2 seconds before retrying
            continue;
        }

        gpioDelay(2000); // Wait 2 seconds before next reading
    }

    // Cleanup (should not reach here if signal handler works correctly)
    stop_motor();
    gpioTerminate();

    return 0;
}

