#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_cpu_load(float *load);
void map_load_to_color(float load, int *red, int *green, int *blue);
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    set_led_color(0, 0, 0); // Turn off LED
    gpioTerminate();         // Terminate pigpio
    exit(0);
}

// Function to read CPU load from /proc/stat
int read_cpu_load(float *load) {
    FILE *fp;
    char line[256];
    unsigned long long user, nice, system, idle, iowait, irq, softirq, steal, guest, guest_nice;

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Error reading from /proc/stat");
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal) != 8) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    unsigned long long prev_idle = idle + iowait;
    unsigned long long prev_non_idle = user + nice + system + irq + softirq + steal;
    usleep(500000); // Sample every 500ms

    fp = fopen("/proc/stat", "r");
    if (fp == NULL) {
        perror("Error opening /proc/stat");
        return -1;
    }

    if (fgets(line, sizeof(line), fp) == NULL) {
        perror("Error reading from /proc/stat");
        fclose(fp);
        return -1;
    }

    if (sscanf(line, "cpu  %llu %llu %llu %llu %llu %llu %llu %llu",
               &user, &nice, &system, &idle, &iowait, &irq, &softirq, &steal) != 8) {
        fprintf(stderr, "Error parsing /proc/stat\n");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    unsigned long long new_idle = idle + iowait;
    unsigned long long new_non_idle = user + nice + system + irq + softirq + steal;

    unsigned long long totald = new_idle - prev_idle;
    unsigned long long totaln = new_non_idle - prev_non_idle;

    *load = (float)(totaln - totald) / totaln * 100.0;

    return 0;
}

// Function to map CPU load to RGB color
void map_load_to_color(float load, int *red, int *green, int *blue) {
    if (load <= 50.0) {
        *red   = 0;
        *green = (int)(load / 50.0 * 255.0);
        *blue  = 0;
    } else if (load <= 100.0) {
        *red   = (int)((load - 50.0) / 50.0 * 255.0);
        *green = 255;
        *blue  = 0;
    } else {
        *red   = 255;
        *green = 0;
        *blue  = 0;
    }
}

// Function to set RGB LED color using hardware PWM
void set_led_color(int red, int green, int blue) {
    // Common‑anode: Invert the color values
    red   = 255 - red;
    green = 255 - green;
    blue  = 255 - blue;

    gpioPWM(RED_PIN,   red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN,  blue);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RED_PIN,   PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RED_PIN,   255);
    gpioSetPWMrange(GREEN_PIN, 255);
    gpioSetPWMrange(BLUE_PIN,  255);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float cpu_load;
    int red, green, blue;

    printf("CPU Load LED Modulation Program\n");

    while (program_running) {
        // Read CPU load
        if (read_cpu_load(&cpu_load) == 0) {
            // Map load to color
            map_load_to_color(cpu_load, &red, &green, &blue);

            // Set LED color
            set_led_color(red, green, blue);

            printf("CPU Load: %.2f%%, RGB: R=%d, G=%d, B=%d\n", cpu_load, red, green, blue);
        } else {
            fprintf(stderr, "Failed to read CPU load\n");
        }

        // Wait for 500ms
        usleep(500000);
    }

    // Clean up and exit (should not reach here if signal handler works correctly)
    set_led_color(0, 0, 0);
    gpioTerminate();
    return 0;
}

