#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define CE0 8
#define CE1 7
#define CE2 22

// Define SPI channel
#define SPI_CHANNEL 0

// Define SPI baud rate
#define SPI_BAUD 1000000 // 1 MHz

// Define RTD parameters
#define RREF 430.0       // Reference resistor value in ohms
#define A 3.9083
#define B -577.23

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold RTD data
typedef struct {
    uint32_t rtd_raw;
    float temperature;
    int fault_status;
} RTDData;

// Function prototypes
int initialize_pigpio();
int initialize_spi();
int read_rtd_data(int ce_pin, RTDData *data);
float calculate_temperature(uint32_t rtd_raw);
int log_data(FILE *fp, int ce_pin, float temperature, int fault_status);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read RTD data from MAX31865 sensor
int read_rtd_data(int ce_pin, RTDData *data) {
    char tx_buffer[4];
    char rx_buffer[4];
    int result;

    // Build the transmit buffer (4 bytes of 0)
    memset(tx_buffer, 0, sizeof(tx_buffer));

    // Set the chip enable pin low
    gpioWrite(ce_pin, 0);

    // Transfer data
    result = spiXfer(spi_handle, tx_buffer, rx_buffer, sizeof(tx_buffer));

    // Set the chip enable pin high
    gpioWrite(ce_pin, 1);

    if (result != sizeof(rx_buffer)) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract raw data from the response
    data->rtd_raw = ((uint32_t)rx_buffer[0] << 24) | ((uint32_t)rx_buffer[1] << 16) | ((uint32_t)rx_buffer[2] << 8) | (uint32_t)rx_buffer[3];

    // Extract fault status from the response
    data->fault_status = (rx_buffer[3] >> 6) & 0x07;

    return 0;
}

// Calculate temperature from RTD data using Callendar-Van Dusen equation
float calculate_temperature(uint32_t rtd_raw) {
    float rtd_resistance = (float)rtd_raw * RREF / 32768.0; // Convert to resistance (assuming 12-bit ADC)
    float temperature = A * rtd_resistance + B;
    return temperature;
}

// Log data to CSV file
int log_data(FILE *fp, int ce_pin, float temperature, int fault_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(fp, "%s,%d,%.2f,%d\n", timestamp, ce_pin, temperature, fault_status);
    fflush(fp); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Configure chip enable pins as outputs
    gpioSetMode(CE0, PI_OUTPUT);
    gpioSetMode(CE1, PI_OUTPUT);
    gpioSetMode(CE2, PI_OUTPUT);

    // Open log file
    log_file = fopen("rtd_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,CE_Pin,Temperature(C),Fault_Status\n");
    }
    rewind(log_file);

    RTDData rtd_data;

    // Main loop
    while (!terminate) {
        // Read data from CE0
        gpioWrite(CE0, 0);
        if (read_rtd_data(CE0, &rtd_data) == 0) {
            log_data(log_file, CE0, rtd_data.temperature, rtd_data.fault_status);
        } else {
            fprintf(stderr, "Error reading from CE0\n");
        }
        gpioWrite(CE0, 1);

        // Read data from CE1
        gpioWrite(CE1, 0);
        if (read_rtd_data(CE1, &rtd_data) == 0) {
            log_data(log_file, CE1, rtd_data.temperature, rtd_data.fault_status);
        } else {
            fprintf(stderr, "Error reading from CE1\n");
        }
        gpioWrite(CE1, 1);

        // Read data from CE2
        gpioWrite(CE2, 0);
        if (read_rtd_data(CE2, &rtd_data) == 0) {
            log_data(log_file, CE2, rtd_data.temperature, rtd_data.fault_status);
        } else {
            fprintf(stderr, "Error reading from CE2\n");
        }
        gpioWrite(CE2, 1);

        // Wait 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

