uint16_t ac4, ac5, ac6;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float pressure;
} PressureReading;

PressureReading pressure_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
