// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    ac1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    b2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    mb = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    mc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    md = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == PI_BAD_I2C_ADDR || ac2 == PI_BAD_I2C_ADDR || ac3 == PI_BAD_I2C_ADDR ||
        ac4 == PI_BAD_I2C_ADDR || ac5 == PI_BAD_I2C_ADDR || ac6 == PI_BAD_I2C_ADDR ||
        b1 == PI_BAD_I2C_ADDR || b2 == PI_BAD_I2C_ADDR || mb == PI_BAD_I2C_ADDR ||
        mc == PI_BAD_I2C_ADDR || md == PI_BAD_I2C_ADDR) {
        log_error("Failed to read calibration data");
        return -1;
    }

    return 0;
}

// Function to read raw temperature from BMP180
int read_raw_temperature(int32_t *raw_temp) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        log_error("Failed to write temperature measurement command");
        return -1;
    }

    gpioDelay(5000); // Wait 4.5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        log_error("Failed to set register pointer for temperature reading");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, (char *)raw_temp, 2) != 2) {
        log_error("Failed to read raw temperature data");
        return -1;
