        return -1;
    }

    *raw_pressure = (*raw_pressure << 8) | (*raw_pressure >> 8); // Swap bytes
    *raw_pressure = (*raw_pressure << (8 - BMP180_OSS)) | (*raw_pressure >> (8 - BMP180_OSS)); // Right shift

    return 0;
}

// Function to calculate pressure in hPa
float calculate_pressure(int32_t raw_pressure, int32_t raw_temp) {
    int32_t X1, X2, X3, B3, B5, B6, p;
    unsigned int B4, B7;

    // Temperature calculations
    X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    X2 = ((int32_t)mc << 11) / (X1 + md);
    B5 = X1 + X2;
    float temperature = (B5 + 8) >> 4;

    // Pressure calculations
    B6 = B5 - 4000;
    X1 = (b2 * (B6 * B6) >> 12) >> 11;
    X2 = ac2 * B6 >> 11;
    X3 = X1 + X2;
    B3 = (((((int32_t)ac1) * 4 + X3) << BMP180_OSS) + 2) >> 2;
    X1 = ac3 * B6 >> 13;
    X2 = (b1 * (B6 * B6) >> 12) >> 16;
    X3 = ((X1 + X2) + 2) >> 2;
    B4 = ac4 * (unsigned int)(X3 + 32768) >> 15;
    B7 = ((unsigned int)raw_pressure - B3) * (50000 >> BMP180_OSS);
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }
    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    p = p + ((X1 + X2 + 3791) >> 4);

    return p / 100.0; // Return pressure in hPa
}

// Function to calculate rolling average pressure
float calculate_rolling_average() {
    float sum = 0.0;
    int count = 0;
    time_t now = time(NULL);

    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index - BUFFER_SIZE + i + BUFFER_SIZE) % BUFFER_SIZE;
        if (pressure_buffer[index].timestamp >= now - 60) {
            sum += pressure_buffer[index].pressure;
            count++;
        }
    }

    if (count > 0) {
        return sum / count;
    } else {
        return 0.0; // Return 0 if no readings in the last 60 seconds
    }
}

// Function to trigger alert
void trigger_alert() {
    gpioWrite(ALERT_PIN, 1); // Set GPIO HIGH
    gpioDelay(1000);         // Wait for 1 second
    gpioWrite(ALERT_PIN, 0); // Set GPIO LOW
}

// Function to log errors to stderr
