    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO24 as output
    gpioSetMode(ALERT_PIN, PI_OUTPUT);
    gpioWrite(ALERT_PIN, 0); // Ensure alert is initially off

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    int32_t raw_temperature, raw_pressure;
    float pressure, rolling_average;

    // Main loop
    while (!terminate) {
        // Read raw temperature and pressure
        if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
            // Calculate pressure
            pressure = calculate_pressure(raw_pressure, raw_temperature);

            // Store pressure reading in circular buffer
            pressure_buffer[buffer_index].timestamp = time(NULL);
            pressure_buffer[buffer_index].pressure = pressure;
            buffer_index = (buffer_index + 1) % BUFFER_SIZE;

            // Calculate rolling average pressure
            rolling_average = calculate_rolling_average();

            // Check for alert condition
            if (pressure > rolling_average + 5.0) {
                trigger_alert();
            }

            // Print pressure and rolling average
            printf("Pressure: %.2f hPa, Rolling Average: %.2f hPa\n", pressure, rolling_average);
        } else {
            log_error("Failed to read sensor data");
        }

        gpioDelay(50000); // Wait 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

