double calculate_pressure(int32_t raw_pressure, double temperature) {
    int32_t X1 = ((int32_t)temperature * 10 - 4000) * ((int32_t)ac6) / pow(2, 15);
    int32_t X2 = ((int32_t)mc * pow(2, 11)) / (X1 + md);
