    X1 = (pressure / pow(2, 8)) * (pressure / pow(2, 8));
    X1 = (X1 * 3038) / pow(2, 16);
    X2 = (-7357 * pressure) / pow(2, 16);
    double pressure_pa = pressure + (X1 + X2 + 3791) / pow(2, 4);
