#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define LOG_FILE "fan_log.txt"
#define GPIO_PIN 18
#define PWM_FREQUENCY 25000 // 25 kHz
#define PWM_RANGE 255
#define MIN_TEMP 40.0
#define MAX_TEMP 70.0
#define MIN_DUTY 0
#define MAX_DUTY 100

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
float read_temperature();
int map_temperature_to_duty_cycle(float temperature);
int set_fan_speed(int duty_cycle);
int log_data(float temperature, int duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read temperature from file
float read_temperature() {
    FILE *fp;
    int temp_milli_celsius;

    fp = fopen(TEMP_FILE, "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        perror("Error reading temperature from file");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    return (float)temp_milli_celsius / 1000.0;
}

// Function to map temperature to duty cycle
int map_temperature_to_duty_cycle(float temperature) {
    if (temperature < MIN_TEMP) {
        return MIN_DUTY;
    } else if (temperature > MAX_TEMP) {
        return MAX_DUTY;
    } else {
        return (int)(((temperature - MIN_TEMP) / (MAX_TEMP - MIN_TEMP)) * (MAX_DUTY - MIN_DUTY) + MIN_DUTY);
    }
}

// Function to set fan speed using PWM
int set_fan_speed(int duty_cycle) {
    if (gpioPWM(GPIO_PIN, duty_cycle) != 0) {
        perror("Error setting fan speed");
        return -1; // Indicate error
    }
    return 0;
}

// Function to log data to file
int log_data(float temperature, int duty_cycle) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            return -1; // Indicate error
        }
    }

    fprintf(log_file, "%s, Temperature: %.2f °C, Duty Cycle: %d\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    float temperature;
    int duty_cycle;

    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as output
    gpioSetMode(GPIO_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(GPIO_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(GPIO_PIN, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Fan control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        temperature = read_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or defaulting to 50°C.\n");
            temperature = 50.0; // Default to 50°C
        }

        duty_cycle = map_temperature_to_duty_cycle(temperature);

        if (set_fan_speed(duty_cycle) != 0) {
            fprintf(stderr, "Error setting fan speed, continuing with previous value.\n");
        }

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data, continuing.\n");
        }

        sleep(5);
    }

    // Stop the fan
    set_fan_speed(0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("Fan control program stopped.\n");

    return 0;
}

