#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define LM75_ADDR 0x48
#define ALERT_GPIO 18
#define BUFFER_SIZE 60
#define TEMP_THRESHOLD 28.0
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure for circular buffer
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

CircularBuffer temp_buffer;

// Mutex for thread safety
pthread_mutex_t buffer_mutex;

// Function prototypes
int initialize_i2c();
float read_temperature();
void add_to_buffer(float temperature);
float calculate_average();
void control_led(float average_temperature);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Add a temperature reading to the circular buffer
void add_to_buffer(float temperature) {
    pthread_mutex_lock(&buffer_mutex);
    temp_buffer.buffer[temp_buffer.head] = temperature;
    temp_buffer.head = (temp_buffer.head + 1) % BUFFER_SIZE;
    if (temp_buffer.count < BUFFER_SIZE) {
        temp_buffer.count++;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

// Calculate the running average of the temperature readings in the buffer
float calculate_average() {
    pthread_mutex_lock(&buffer_mutex);
    float sum = 0.0;
    if (temp_buffer.count > 0) {
        for (int i = 0; i < temp_buffer.count; i++) {
            sum += temp_buffer.buffer[i];
        }
        return sum / temp_buffer.count;
    } else {
        return 0.0;
    }
    pthread_mutex_unlock(&buffer_mutex);
}

// Read temperature from the LM75 sensor
float read_temperature() {
    char buf[2];
    int result;

    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading temperature: %d\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Convert the raw data to temperature (Celsius)
    int16_t raw_temp = (buf[0] << 4) | (buf[1] >> 4);
    if (raw_temp & 0x800) {
        raw_temp |= 0xF000; // Sign extend if negative
    }
    float temperature = raw_temp * 0.0625;

    return temperature;
}

// Control the alert LED based on the average temperature
void control_led(float average_temperature) {
    if (average_temperature > TEMP_THRESHOLD) {
        gpioWrite(ALERT_GPIO, 1); // Turn LED on
    } else {
        gpioWrite(ALERT_GPIO, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    i2cClose(i2c_handle);
    gpioWrite(ALERT_GPIO, 0); // Turn off LED
    gpioTerminate();
    pthread_mutex_destroy(&buffer_mutex);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize GPIO for alert LED
    gpioSetMode(ALERT_GPIO, PI_OUTPUT);
    gpioWrite(ALERT_GPIO, 0); // Ensure LED is off initially

    // Initialize circular buffer
    init_buffer(&temp_buffer);

    // Initialize mutex
    if (pthread_mutex_init(&buffer_mutex, NULL) != 0) {
        fprintf(stderr, "Mutex initialization failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float temperature = read_temperature();

        if (temperature > -999.0) { // Check for valid temperature reading
            add_to_buffer(temperature);
            float average_temperature = calculate_average();
            control_led(average_temperature);
            printf("Temperature: %.2f °C, Average: %.2f °C\n", temperature, average_temperature);
        } else {
            fprintf(stderr, "Failed to read temperature, retrying...\n");
        }

        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LM75_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

