#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>
#include <jansson.h>

// Configuration file path
#define CONFIG_FILE "config.json"

// Default values
#define DEFAULT_TARGET_TEMP 25.0
#define DEFAULT_KP 1.0
#define DEFAULT_KI 0.1
#define DEFAULT_KD 0.01
#define DEFAULT_PWM_FREQUENCY 1000
#define DEFAULT_PWM_RANGE 1000
#define DEFAULT_SPI_CHANNEL 0
#define DEFAULT_SPI_SPEED 500000
#define DEFAULT_FAILSAFE_TEMP 80.0

// Global variables
static volatile int running = 1;
static int spi_handle;
static int pwm_channel;
static double target_temperature = DEFAULT_TARGET_TEMP;
static double kp = DEFAULT_KP;
static double ki = DEFAULT_KI;
static double kd = DEFAULT_KD;
static int pwm_frequency = DEFAULT_PWM_FREQUENCY;
static int pwm_range = DEFAULT_PWM_RANGE;
static int spi_channel = DEFAULT_SPI_CHANNEL;
static int spi_speed = DEFAULT_SPI_SPEED;
static double failsafe_temperature = DEFAULT_FAILSAFE_TEMP;

// PID variables
static double integral = 0.0;
static double previous_error = 0.0;

// Function prototypes
int load_configuration(const char *filename);
double read_temperature();
double calculate_pid(double setpoint, double actual_temperature);
void set_pwm_duty(double duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to load configuration from JSON file
int load_configuration(const char *filename) {
    json_t *root, *target_temp_json, *kp_json, *ki_json, *kd_json, *pwm_frequency_json, *pwm_range_json, *spi_channel_json, *spi_speed_json, *failsafe_temperature_json;
    json_error_t error;

    root = json_load_file(filename, 0, &error);
    if (!root) {
        fprintf(stderr, "Error: Could not load configuration file: %s\n", error.text);
        return -1;
    }

    target_temp_json = json_object_get(root, "target_temperature");
    kp_json = json_object_get(root, "Kp");
    ki_json = json_object_get(root, "Ki");
    kd_json = json_object_get(root, "Kd");
    pwm_frequency_json = json_object_get(root, "pwm_frequency");
    pwm_range_json = json_object_get(root, "pwm_range");
    spi_channel_json = json_object_get(root, "spi_channel");
    spi_speed_json = json_object_get(root, "spi_speed");
    failsafe_temperature_json = json_object_get(root, "failsafe_temperature");

    if (!json_is_real(target_temp_json) || !json_is_real(kp_json) || !json_is_real(ki_json) || !json_is_real(kd_json) ||
        !json_is_integer(pwm_frequency_json) || !json_is_integer(pwm_range_json) || !json_is_integer(spi_channel_json) ||
        !json_is_integer(spi_speed_json) || !json_is_real(failsafe_temperature_json)) {
        fprintf(stderr, "Error: Invalid configuration values in file\n");
        json_decref(root);
        return -1;
    }

    target_temperature = json_real_value(target_temp_json);
    kp = json_real_value(kp_json);
    ki = json_real_value(ki_json);
    kd = json_real_value(kd_json);
    pwm_frequency = json_integer_value(pwm_frequency_json);
    pwm_range = json_integer_value(pwm_range_json);
    spi_channel = json_integer_value(spi_channel_json);
    spi_speed = json_integer_value(spi_speed_json);
    failsafe_temperature = json_real_value(failsafe_temperature_json);

    json_decref(root);
    return 0;
}

// Function to read temperature from MAX31865
double read_temperature() {
    unsigned char data[4];
    int result;

    result = spiRead(spi_handle, data, 4);
    if (result != 4) {
        fprintf(stderr, "Error: SPI read failed (%d)\n", result);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Check for fault bits
    if (data[3] & 0x07) {
        fprintf(stderr, "Error: MAX31865 fault detected: 0x%02X\n", data[3]);
        return -1000.0; // Indicate error with a very low temperature
    }

    // Extract temperature data (bits 31:18)
    int16_t raw_temp = ((data[0] << 8) | data[1]) >> 2;

    // Convert to Celsius (datasheet formula)
    double temperature = (double)raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = kp * error + ki * integral + kd * derivative;
    previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty(double duty_cycle) {
    if (duty_cycle < 0.0) duty_cycle = 0.0;
    if (duty_cycle > 100.0) duty_cycle = 100.0;

    int pwm_value = (int)(duty_cycle * pwm_range / 100.0);
    gpioPWM(pwm_channel, pwm_value);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    set_pwm_duty(0.0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Load configuration
    if (load_configuration(CONFIG_FILE) != 0) {
        fprintf(stderr, "Error: Failed to load configuration, using default values\n");
    }

    // Set PWM frequency
    gpioSetPWMfrequency(pwm_channel, pwm_frequency);

    // Set PWM range
    gpioSetPWMrange(pwm_channel, pwm_range);

    // Open SPI channel
    spi_handle = spiOpen(spi_channel, spi_speed, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "Error: SPI open failed (%d)\n", spi_handle);
        cleanup();
        return 1;
    }

    // Set PWM channel as output
    gpioSetMode(pwm_channel, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read temperature
        double temperature = read_temperature();

        if (temperature < -999.0) { // Error reading temperature
            fprintf(stderr, "Error: Failed to read temperature, using previous value\n");
            // Optionally add a failsafe here
        } else {
            // Calculate PID output
            double pid_output = calculate_pid(target_temperature, temperature);

            // Limit PID output to 0-100%
            if (pid_output < 0.0) pid_output = 0.0;
            if (pid_output > 100.0) pid_output = 100.0;

            // Set PWM duty cycle
            set_pwm_duty(pid_output);

            // Log data
            time_t now = time(NULL);
            struct tm *t = localtime(&now);
            char timestamp[64];
            strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

            printf("%s - Target: %.2f°C, Actual: %.2f°C, PID Output: %.2f%%\n", timestamp, target_temperature, temperature, pid_output);
        }

        // Wait for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

