#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define BMP180_OSS 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temp);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temp);
int log_breach(double temperature, double pressure);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0); // Bus 1, address 0x77, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read calibration data from the BMP180
int read_calibration_data() {
    ac1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    ac2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    ac3 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    ac4 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    ac5 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    ac6 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    b1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    b2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    mb = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    mc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    md = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);

    if (ac1 == PI_BAD_I2C_ADDR || ac2 == PI_BAD_I2C_ADDR || ac3 == PI_BAD_I2C_ADDR ||
        ac4 == PI_BAD_I2C_ADDR || ac5 == PI_BAD_I2C_ADDR || ac6 == PI_BAD_I2C_ADDR ||
        b1 == PI_BAD_I2C_ADDR || b2 == PI_BAD_I2C_ADDR || mb == PI_BAD_I2C_ADDR ||
        mc == PI_BAD_I2C_ADDR || md == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Read raw temperature data from the BMP180
int read_raw_temperature(int32_t *raw_temp) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x2E; // Temperature measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing temperature measurement command\n");
        return -1;
    }

    gpioDelay(5000); // Wait 4.5ms

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing register address for temperature data\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, (char *)raw_temp, 2) != 2) {
        fprintf(stderr, "Error reading raw temperature data\n");
        return -1;
    }

    *raw_temp = (*raw_temp << 8) | (*raw_temp >> 8); // Byte swap

    return 0;
}

// Read raw pressure data from the BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    char buf[2];
    buf[0] = BMP180_REG_CONTROL;
    buf[1] = 0x34 + (BMP180_OSS << 6); // Pressure measurement command

    if (i2cWriteDevice(i2c_handle, buf, 2) != 0) {
        fprintf(stderr, "Error writing pressure measurement command\n");
        return -1;
    }

    gpioDelay(2 + (3 << BMP180_OSS)); // Wait for conversion

    buf[0] = BMP180_REG_MSB;
    if (i2cWriteDevice(i2c_handle, buf, 1) != 0) {
        fprintf(stderr, "Error writing register address for pressure data\n");
        return -1;
    }

    if (i2cReadDevice(i2c_handle, (char *)raw_pressure, 3) != 3) {
        fprintf(stderr, "Error reading raw pressure data\n");
        return -1;
    }

    *raw_pressure = (*raw_pressure << 8) | (*raw_pressure >> 8); // Byte swap
