#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (OSS)
#define OSS 0

// GPIO pin for cooling fan
#define FAN_PIN 18

// Circular buffer size
#define BUFFER_SIZE 60

// Temperature threshold for fan control
#define TEMPERATURE_THRESHOLD 30.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Circular buffer structure
typedef struct {
    time_t timestamp;
    float temperature;
    float pressure;
} Reading;

Reading readings[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
float calculate_temperature(int32_t raw_temp);
float calculate_pressure(int32_t raw_pressure, int32_t raw_temp);
void add_reading(float temperature, float pressure);
void print_reading();
void control_fan(float temperature);
void timer_callback();
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    i2c_handle = i2cOpen(1, BMP180_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read calibration data from BMP180
int read_calibration_data() {
    ac1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC1);
    if (ac1 < 0) {
        fprintf(stderr, "Error reading AC1: %d\n", ac1);
        return -1;
    }
    ac2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC2);
    if (ac2 < 0) {
        fprintf(stderr, "Error reading AC2: %d\n", ac2);
        return -1;
    }
    ac3 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC3);
    if (ac3 < 0) {
        fprintf(stderr, "Error reading AC3: %d\n", ac3);
        return -1;
    }
    ac4 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC4);
    if (ac4 < 0) {
        fprintf(stderr, "Error reading AC4: %d\n", ac4);
        return -1;
    }
    ac5 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC5);
    if (ac5 < 0) {
        fprintf(stderr, "Error reading AC5: %d\n", ac5);
        return -1;
    }
    ac6 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_AC6);
    if (ac6 < 0) {
        fprintf(stderr, "Error reading AC6: %d\n", ac6);
        return -1;
    }
    b1 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B1);
    if (b1 < 0) {
        fprintf(stderr, "Error reading B1: %d\n", b1);
        return -1;
    }
    b2 = i2cReadWordData(i2c_handle, BMP180_REG_CAL_B2);
    if (b2 < 0) {
        fprintf(stderr, "Error reading B2: %d\n", b2);
        return -1;
    }
    mb = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MB);
    if (mb < 0) {
        fprintf(stderr, "Error reading MB: %d\n", mb);
        return -1;
    }
    mc = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MC);
    if (mc < 0) {
        fprintf(stderr, "Error reading MC: %d\n", mc);
        return -1;
    }
    md = i2cReadWordData(i2c_handle, BMP180_REG_CAL_MD);
    if (md < 0) {
        fprintf(stderr, "Error reading MD: %d\n", md);
        return -1;
    }
    return 0;
}

// Function to read raw temperature from BMP180
int read_raw_temperature(int32_t *raw_temp) {
    i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E); // Request temperature reading
    gpioDelay(5); // Wait 4.5ms
    *raw_temp = i2cReadWordData(i2c_handle, BMP180_REG_MSB);
    if (*raw_temp < 0) {
        fprintf(stderr, "Error reading raw temperature: %d\n", *raw_temp);
        return -1;
    }
    return 0;
}

// Function to read raw pressure from BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)); // Request pressure reading
    switch (OSS) {
        case 0:
            gpioDelay(5); // Wait 4.5ms
            break;
        case 1:
            gpioDelay(8); // Wait 7.5ms
            break;
        case 2:
            gpioDelay(14); // Wait 13.5ms
            break;
        case 3:
            gpioDelay(26); // Wait 25.5ms
            break;
    }
    *raw_pressure = i2cReadWordData(i2c_handle, BMP180_REG_MSB);
    if (*raw_pressure < 0) {
        fprintf(stderr, "Error reading raw pressure: %d\n", *raw_pressure);
        return -1;
    }
    *raw_pressure = (*raw_pressure << 8) | i2cReadByteData(i2c_handle, BMP180_REG_LSB);
    if (*raw_pressure < 0) {
        fprintf(stderr, "Error reading raw pressure LSB: %d\n", *raw_pressure);
        return -1;
    }
    *raw_pressure = (*raw_pressure << 8) | i2cReadByteData(i2c_handle, BMP180_REG_XLSB);
    if (*raw_pressure < 0) {
        fprintf(stderr, "Error reading raw pressure XLSB: %d\n", *raw_pressure);
        return -1;
    }
    return 0;
}

// Function to calculate temperature in degrees Celsius
float calculate_temperature(int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    float temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
float calculate_pressure(int32_t raw_pressure, int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    X1 = (b2 * (B6 * B6) >> 12) >> 11;
    X2 = ac2 * B6 >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << OSS) + 2) >> 2;

    X1 = ac3 * B6 >> 13;
    X2 = (b1 * (B6 * B6) >> 12) >> 16;
    X3 = ((X1 + X2) + 2) >> 2;
    uint32_t B4 = ac4 * (uint32_t)(X3 + 32768) >> 15;

    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> OSS);
    if (B7 < 0x80000000)
    {
        int32_t p = (B7 * 2) / B4;
    }
    else
    {
        int32_t p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    float pressure = p + ((X1 + X2 + 3791) >> 4);
    return pressure;
}

// Function to add a reading to the circular buffer
void add_reading(float temperature, float pressure) {
    readings[buffer_index].timestamp = time(NULL);
    readings[buffer_index].temperature = temperature;
    readings[buffer_index].pressure = pressure;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to print a reading from the circular buffer
void print_reading() {
    time_t timestamp = readings[buffer_index].timestamp;
    struct tm *timeinfo = localtime(&timestamp);
    char timestamp_str[20];
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
    printf("%s, Temperature: %.2f °C, Pressure: %.2f Pa\n", timestamp_str, readings[buffer_index].temperature, readings[buffer_index].pressure);
}

// Function to control the cooling fan
void control_fan(float temperature) {
    if (temperature > TEMPERATURE_THRESHOLD) {
        gpioWrite(FAN_PIN, 1); // Turn fan on
    } else {
        gpioWrite(FAN_PIN, 0); // Turn fan off
    }
}

// Timer callback function
void timer_callback() {
    int32_t raw_temp, raw_pressure;
    float temperature, pressure;

    if (read_raw_temperature(&raw_temp) == 0 && read_raw_pressure(&raw_pressure) == 0) {
        temperature = calculate_temperature(raw_temp);
        pressure = calculate_pressure(raw_pressure, raw_temp);
        add_reading(temperature, pressure);
        print_reading();
        control_fan(temperature);
    } else {
        fprintf(stderr, "Error reading sensor data. Skipping this reading.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function
void cleanup() {
    gpioWrite(FAN_PIN, 0); // Turn fan off
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for fan control
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up hardware timer callback
    gpioSetTimerFuncEx(0, 500, timer_callback, NULL); // Timer 0, every 500ms

    // Main loop
    while (!terminate) {
        sleep(1); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

