// Function to log pressure to a file
void log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
