// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick) {
    if (level == FALLING_EDGE) {
        // Debounce delay
        gpioDelay(200); // 200ms

        // Toggle logging
        if (program_running) {
            program_running = 0;
            printf("Logging stopped.\n");
        } else {
            program_running = 1;
            printf("Logging started.\n");
        }

        // Re-enable interrupt
        gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, interrupt_handler, NULL);
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

