    if (ac1 == PI_BAD_I2C_ADDR || ac2 == PI_BAD_I2C_ADDR || ac3 == PI_BAD_I2C_ADDR ||
        ac4 == PI_BAD_I2C_ADDR || ac5 == PI_BAD_I2C_ADDR || ac6 == PI_BAD_I2C_ADDR ||
        b1 == PI_BAD_I2C_ADDR || b2 == PI_BAD_I2C_ADDR || mb == PI_BAD_I2C_ADDR ||
        mc == PI_BAD_I2C_ADDR || md == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading calibration data\n");
        return -1;
    }

    return 0;
}

// Function to read raw temperature from the BMP180
int read_raw_temperature(int32_t *raw_temp) {
    i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x2E); // Request temperature reading
    gpioDelay(5); // Wait 4.5ms
    *raw_temp = i2cReadWordData(i2c_handle, BMP180_REG_MSB);
    if (*raw_temp == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading raw temperature\n");
        return -1;
    }
    return 0;
}

// Function to read raw pressure from the BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    i2cWriteByteData(i2c_handle, BMP180_REG_CONTROL, 0x34 + (OSS << 6)); // Request pressure reading
    gpioDelay(2 + (3 << OSS)); // Wait for conversion (2.5ms + (2.5ms * OSS))
    *raw_pressure = i2cReadWordData(i2c_handle, BMP180_REG_MSB);
    if (*raw_pressure == PI_BAD_I2C_ADDR) {
        fprintf(stderr, "Error reading raw pressure\n");
        return -1;
    }
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in Pascals
double calculate_pressure(int32_t raw_pressure, double temperature) {
    int32_t X1 = ((raw_pressure - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    X1 = (b2 * (B6 * B6) >> 12) >> 11;
    X2 = ac2 * B6 >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << OSS) + 2) >> 2;

    X1 = ac3 * B6 >> 13;
    X2 = (b1 * (B6 * B6) >> 12) >> 16;
    X3 = ((X1 + X2) + 2) >> 2;
    uint32_t B4 = ac4 * (uint32_t)(X3 + 32768) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> OSS);

    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);
    return pressure;
}

// Function to log pressure to a file
void log_pressure(double pressure) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f Pa\n", timestamp, pressure);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick) {
    if (level == FALLING_EDGE) {
        // Debounce delay
        gpioDelay(200); // 200ms

        // Toggle logging
        if (program_running) {
            program_running = 0;
            printf("Logging stopped.\n");
        } else {
            program_running = 1;
            printf("Logging started.\n");
        }

        // Re-enable interrupt
        gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, interrupt_handler, NULL);
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    program_running = 0;
    cleanup();
    exit(0);
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        gpioTerminate();
        return 1;
    }

    // Read calibration data
    if (read_calibration_data() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("pressure_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetPullUpDown(INTERRUPT_PIN, PI_PUD_UP);

    // Set interrupt handler
    if (gpioSetISRFuncEx(INTERRUPT_PIN, FALLING_EDGE, 0, interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Error setting interrupt handler\n");
        cleanup();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int32_t raw_temperature, raw_pressure;
    double temperature, pressure;

    // Main loop
    while (program_running) {
        if (read_raw_temperature(&raw_temperature) == 0 && read_raw_pressure(&raw_pressure) == 0) {
            temperature = calculate_temperature(raw_temperature);
            pressure = calculate_pressure(raw_pressure, temperature);
            log_pressure(pressure);
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        gpioDelay(2000); // Wait 2 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

