#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HEATER_PIN 17
#define SPI_CE 8

// Define SPI parameters
#define SPI_CHANNEL 0
#define SPI_SPEED 2000000 // 2 MHz
#define SPI_MODE 0

// Define target temperature and duty cycle limits
#define TARGET_TEMPERATURE 25.0
#define MAX_DUTY_CYCLE 80.0

// Define anti-windup parameters
#define KP 1.0
#define KI 0.1
#define MAX_INTEGRAL 100.0

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Structure to hold temperature and duty cycle data
typedef struct {
    float temperature;
    float duty_cycle;
} TemperatureDutyCycleData;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_max31855(uint32_t *raw_data);
float convert_to_temperature(uint32_t raw_data);
float calculate_duty_cycle(float temperature, float target_temperature);
int set_heater_duty_cycle(float duty_cycle);
int log_data(float temperature, float duty_cycle);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HEATER_PIN, PI_OUTPUT);
    gpioSetPWMfrequency(HEATER_PIN, 1000); // Set PWM frequency to 1 kHz
    gpioSetPWMrange(HEATER_PIN, 100);    // Set PWM range to 0-100

    return 0;
}

// Function to initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CE, SPI_SPEED, SPI_MODE);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to read data from MAX31855 thermocouple amplifier
int read_max31855(uint32_t *raw_data) {
    char tx_buffer[4] = {0x00, 0x00, 0x00, 0x00};
    char rx_buffer[4];

    if (spiXfer(spi_handle, tx_buffer, rx_buffer, 4) != 4) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    *raw_data = ((uint32_t)rx_buffer[0] << 24) | ((uint32_t)rx_buffer[1] << 16) | ((uint32_t)rx_buffer[2] << 8) | (uint32_t)rx_buffer[3];

    return 0;
}

// Function to convert raw data to temperature (Celsius)
float convert_to_temperature(uint32_t raw_data) {
    if (raw_data & 0x00000007) {
        fprintf(stderr, "MAX31855 fault detected\n");
        return -273.15; // Return absolute zero on fault
    }

    int16_t thermocouple_data = (raw_data >> 18) & 0x3FFF;
    int16_t internal_data = raw_data & 0x003FFF;

    if (thermocouple_data & 0x2000) {
        thermocouple_data |= 0xC000; // Sign extend
    }

    float thermocouple_temp = thermocouple_data * 0.25;

    return thermocouple_temp;
}

// Function to calculate duty cycle based on temperature and target temperature
float calculate_duty_cycle(float temperature, float target_temperature) {
    float error = target_temperature - temperature;
    static float integral = 0.0;

    integral += error;

    if (integral > MAX_INTEGRAL) {
        integral = MAX_INTEGRAL;
    } else if (integral < -MAX_INTEGRAL) {
        integral = -MAX_INTEGRAL;
    }

    float duty_cycle = KP * error + KI * integral;

    if (duty_cycle < 0.0) {
        duty_cycle = 0.0;
    } else if (duty_cycle > 100.0) {
        duty_cycle = 100.0;
    }

    return duty_cycle;
}

// Function to set heater duty cycle using PWM
int set_heater_duty_cycle(float duty_cycle) {
    int pwm_value = (int)(duty_cycle * 10.0); // Convert duty cycle to PWM value (0-1000)
    gpioPWM(HEATER_PIN, pwm_value);
    return 0;
}

// Function to log data to CSV file
int log_data(float temperature, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    set_heater_duty_cycle(0.0); // Turn off heater
    spiClose(spi_handle);
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("heater_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Temperature(C),DutyCycle(%%)\n");
    }
    rewind(log_file);

    uint32_t raw_data;
    float temperature, duty_cycle;

    // Main loop
    while (program_running) {
        // Read temperature from MAX31855
        if (read_max31855(&raw_data) == 0) {
            // Convert raw data to temperature
            temperature = convert_to_temperature(raw_data);

            // Calculate duty cycle
            duty_cycle = calculate_duty_cycle(temperature, TARGET_TEMPERATURE);

            // Set heater duty cycle
            set_heater_duty_cycle(duty_cycle);

            // Log data
            log_data(temperature, duty_cycle);

            printf("Temperature: %.2f °C, Duty Cycle: %.2f %%\n", temperature, duty_cycle);
        } else {
            fprintf(stderr, "Failed to read temperature, setting duty cycle to 0.0\n");
            set_heater_duty_cycle(0.0);
            log_data(-273.15, 0.0); // Log error
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

