#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define temperature thresholds for RGB color
#define TEMP_LOW   40000
#define TEMP_MED   50000
#define TEMP_HIGH  60000

// Global variables
static volatile sig_atomic_t terminate = 0;
static FILE *temperature_file = NULL;

// Function prototypes
int read_cpu_temperature();
void set_led_color(int red, int green, int blue);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to read CPU temperature from file
int read_cpu_temperature() {
    char buffer[10];
    int temperature = -1; // Initialize to an invalid value

    if (temperature_file == NULL) {
        fprintf(stderr, "Error: Temperature file is not open.\n");
        return -1;
    }

    if (fgets(buffer, sizeof(buffer), temperature_file) == NULL) {
        if (ferror(temperature_file)) {
            fprintf(stderr, "Error reading temperature from file.\n");
            return -1;
        } else {
            // File is empty or EOF reached
            return -1;
        }
    }

    // Convert string to integer
    temperature = atoi(buffer);

    if (temperature == 0 && ferror(temperature_file)) {
        fprintf(stderr, "Error converting temperature to integer.\n");
        return -1;
    }

    return temperature;
}

// Function to set RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    // Invert the PWM values for common anode
    int inverted_red   = 255 - red;
    int inverted_green = 255 - green;
    int inverted_blue  = 255 - blue;

    // Set PWM values for each channel
    gpioPWM(RED_PIN,   inverted_red);
    gpioPWM(GREEN_PIN, inverted_green);
    gpioPWM(BLUE_PIN,  inverted_blue);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM frequency for each channel
    gpioSetPWMfrequency(RED_PIN,   PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQUENCY);

    // Open temperature file
    temperature_file = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (temperature_file == NULL) {
        fprintf(stderr, "Error opening temperature file: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Temperature monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read CPU temperature
        int temperature = read_cpu_temperature();

        if (temperature == -1) {
            fprintf(stderr, "Error reading temperature, skipping this cycle.\n");
            sleep(0.5); // Wait before retrying
            continue;
        }

        // Calculate PWM values based on temperature
        int red   = 0;
        int green = 0;
        int blue  = 0;

        if (temperature < TEMP_LOW) {
            // Solid blue
            blue = 255;
        } else if (temperature < TEMP_MED) {
            // Fade blue to green
            blue = 255 - (int)(((float)(temperature - TEMP_LOW) / (TEMP_MED - TEMP_LOW)) * 255);
            green = (int)(((float)(temperature - TEMP_LOW) / (TEMP_MED - TEMP_LOW)) * 255);
        } else if (temperature < TEMP_HIGH) {
            // Fade green to red
            green = 255 - (int)(((float)(temperature - TEMP_MED) / (TEMP_HIGH - TEMP_MED)) * 255);
            red = (int)(((float)(temperature - TEMP_MED) / (TEMP_HIGH - TEMP_MED)) * 255);
        } else {
            // Solid red
            red = 255;
        }

        // Set LED color
        set_led_color(red, green, blue);

        // Print temperature and PWM values
        printf("Temperature: %d m°C, Red: %d, Green: %d, Blue: %d\n", temperature, red, green, blue);

        // Wait for 0.5 seconds
        sleep(0.5);
    }

    // Cleanup
    printf("Cleaning up...\n");
    set_led_color(0, 0, 0); // Turn off LED
    if (temperature_file != NULL) {
        fclose(temperature_file);
    }
    gpioTerminate();

    return 0;
}

