#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Configuration
#define DHT22_GPIO 4
#define SERVER_URL "http://yourserver.com/api/humidity"
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 100

// Global variables
static volatile int running = 1;
static int sockfd = -1;

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int checksum_error;
} DHT22Data;

// Function prototypes
int read_dht22(int gpio, float *temperature, float *humidity);
int validate_checksum(unsigned char data[], int checksum);
int post_data(const char *url, float temperature, float humidity);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read data from DHT22 sensor
int read_dht22(int gpio, float *temperature, float *humidity) {
    unsigned char data[5] = {0};
    int bit_count = 0;
    int byte_index = 0;
    int i, j;

    // Send start signal
    gpioSetMode(gpio, PI_OUTPUT);
    gpioWrite(gpio, 0);
    gpioDelay(1); // 1ms
    gpioWrite(gpio, 1);
    gpioDelay(30); // 30us
    gpioSetMode(gpio, PI_INPUT);

    // Wait for response (low for ~80us, then high for ~80us)
    int timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 100) {
        gpioDelay(1); // Check every 1us
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "Error: DHT22 response timeout (low)\n");
        return -1; // Timeout error
    }

    timeout = 0;
    while (gpioRead(gpio) == 0 && timeout < 100) {
        gpioDelay(1); // Check every 1us
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "Error: DHT22 response timeout (high)\n");
        return -1; // Timeout error
    }

    timeout = 0;
    while (gpioRead(gpio) == 1 && timeout < 100) {
        gpioDelay(1); // Check every 1us
        timeout++;
    }
    if (timeout >= 100) {
        fprintf(stderr, "Error: DHT22 response timeout (low)\n");
        return -1; // Timeout error
    }

    // Read 40 bits of data
    for (i = 0; i < 40; i++) {
        timeout = 0;
        while (gpioRead(gpio) == 0 && timeout < 100) {
            gpioDelay(1); // Check every 1us
            timeout++;
        }
        if (timeout >= 100) {
            fprintf(stderr, "Error: DHT22 data timeout (low start)\n");
            return -1; // Timeout error
        }

        long start = gpioTick();

        timeout = 0;
        while (gpioRead(gpio) == 1 && timeout < 100) {
            gpioDelay(1); // Check every 1us
            timeout++;
        }
        if (timeout >= 100) {
            fprintf(stderr, "Error: DHT22 data timeout (high start)\n");
            return -1; // Timeout error
        }

        long end = gpioTick();
        long duration = end - start;

        if (duration > 40) {
            data[byte_index] |= (1 << (7 - bit_count));
        }

        bit_count++;
        if (bit_count == 8) {
            bit_count = 0;
            byte_index++;
        }
    }

    // Validate checksum
    if (!validate_checksum(data, data[4])) {
        fprintf(stderr, "Error: DHT22 checksum mismatch\n");
        return -1; // Checksum error
    }

    // Convert data to temperature and humidity
    *humidity = (float)((data[0] << 8) | data[1]) / 10.0;
    *temperature = (float)(((data[2] & 0x7F) << 8) | data[3]) / 10.0;
    if (data[2] & 0x80) {
        *temperature = -*temperature;
    }

    return 0; // Success
}

// Function to validate DHT22 checksum
int validate_checksum(unsigned char data[], int checksum) {
    unsigned char checksum_calculated = 0;
    for (int i = 0; i < 4; i++) {
        checksum_calculated += data[i];
    }
    for (int i = 4; i < 5; i++) {
        checksum_calculated += data[i] & 0xFF; // Handle negative checksums
    }
    return (checksum_calculated == checksum) ? 1 : 0;
}

// Function to post data to HTTP server
int post_data(const char *url, float temperature, float humidity) {
    char payload[100];
    snprintf(payload, sizeof(payload), "{\"temperature\": %.1f, \"humidity\": %.1f}", temperature, humidity);

    struct sockaddr_in servaddr;

    // Create socket
    if ((sockfd = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket creation failed");
        return -1;
    }

    memset(&servaddr, 0, sizeof(servaddr));

    // Server information
    servaddr.sin_family = AF_INET;
    servaddr.sin_port = htons(80);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, SERVER_URL, &servaddr.sin_addr) <= 0) {
        perror("Invalid address/ Address not supported");
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    // Connect to server
    if (connect(sockfd, (struct sockaddr *)&servaddr, sizeof(servaddr)) < 0) {
        perror("connection failed");
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    // Send HTTP request
    char http_request[200];
    snprintf(http_request, sizeof(http_request), "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s",
             url, SERVER_URL, strlen(payload), payload);

    if (send(sockfd, http_request, strlen(http_request), 0) < 0) {
        perror("send failed");
        close(sockfd);
        sockfd = -1;
        return -1;
    }

    // Receive HTTP response (optional, for debugging)
    char response[1024] = {0};
    ssize_t bytes_received = recv(sockfd, response, sizeof(response) - 1, 0);
    if (bytes_received > 0) {
        response[bytes_received] = '\0';
        printf("Received response: %s\n", response);
    }

    // Close socket
    close(sockfd);
    sockfd = -1;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float temperature, humidity;
    int retry;

    while (running) {
        retry = 0;
        while (retry < RETRY_COUNT) {
            if (read_dht22(DHT22_GPIO, &temperature, &humidity) == 0) {
                printf("Temperature: %.1f °C, Humidity: %.1f %%\n", temperature, humidity);
                if (post_data(SERVER_URL, temperature, humidity) != 0) {
                    fprintf(stderr, "Error: Failed to post data to server (attempt %d)\n", retry + 1);
                }
                break; // Exit retry loop on success
            } else {
                fprintf(stderr, "Error: Failed to read DHT22 data (attempt %d)\n", retry + 1);
                retry++;
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            }
        }

        if (retry == RETRY_COUNT) {
            fprintf(stderr, "Error: Failed to read DHT22 data after %d retries\n", RETRY_COUNT);
        }

        gpioDelay(5000 * 1000); // Wait 5 seconds
    }

    // Clean up
    gpioTerminate();
    if (sockfd != -1) {
        close(sockfd);
    }

    return 0;
}

