#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <errno.h>
#include <math.h>
#include <stdbool.h>

// BMP180 I2C address
#define BMP180_ADDR 0x77

// BMP180 registers
#define BMP180_REG_CONTROL 0xF4
#define BMP180_REG_MSB 0xF6
#define BMP180_REG_LSB 0xF7
#define BMP180_REG_XLSB 0xF8

// Calibration data registers
#define BMP180_REG_CAL_AC1 0xAA
#define BMP180_REG_CAL_AC2 0xAC
#define BMP180_REG_CAL_AC3 0xAE
#define BMP180_REG_CAL_AC4 0xB0
#define BMP180_REG_CAL_AC5 0xB2
#define BMP180_REG_CAL_AC6 0xB4
#define BMP180_REG_CAL_B1 0xB6
#define BMP180_REG_CAL_B2 0xB8
#define BMP180_REG_CAL_MB 0xBA
#define BMP180_REG_CAL_MC 0xBC
#define BMP180_REG_CAL_MD 0xBE

// Oversampling setting (0, 1, 2, or 3)
#define OSS 3

// GPIO pin for interrupt
#define INTERRUPT_PIN 4

// Debounce time in microseconds
#define DEBOUNCE_TIME 200000

// Global variables
int i2c_fd;
bool logging_enabled = false;
volatile sig_atomic_t program_running = 1;

// Calibration data
int16_t ac1, ac2, ac3, b1, b2, mb, mc, md;
uint16_t ac4, ac5, ac6;

// Function prototypes
int init_i2c();
int read_calibration_data();
int read_raw_temperature(int32_t *raw_temp);
int read_raw_pressure(int32_t *raw_pressure);
double calculate_temperature(int32_t raw_temp);
double calculate_pressure(int32_t raw_pressure, int32_t raw_temp);
void log_pressure(double pressure);
void interrupt_handler(int gpio, int level, uint32_t tick);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    char *i2c_device = "/dev/i2c-1";
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BMP180_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to read calibration data from the BMP180
int read_calibration_data() {
    uint8_t data[22];
    if (read(i2c_fd, data, 22) != 22) {
        perror("Error reading calibration data");
        return -1;
    }

    ac1 = (data[0] << 8) | data[1];
    ac2 = (data[2] << 8) | data[3];
    ac3 = (data[4] << 8) | data[5];
    ac4 = (data[6] << 8) | data[7];
    ac5 = (data[8] << 8) | data[9];
    ac6 = (data[10] << 8) | data[11];
    b1 = (data[12] << 8) | data[13];
    b2 = (data[14] << 8) | data[15];
    mb = (data[16] << 8) | data[17];
    mc = (data[18] << 8) | data[19];
    md = (data[20] << 8) | data[21];

    return 0;
}

// Function to read raw temperature from the BMP180
int read_raw_temperature(int32_t *raw_temp) {
    uint8_t write_data[2];
    uint8_t read_data[2];

    write_data[0] = BMP180_REG_CONTROL;
    write_data[1] = 0x2E; // Temperature measurement command

    if (write(i2c_fd, write_data, 2) != 2) {
        perror("Error writing temperature measurement command");
        return -1;
    }

    usleep(5000); // Wait 4.5ms

    write_data[0] = BMP180_REG_MSB;
    if (write(i2c_fd, write_data, 1) != 1) {
        perror("Error writing to read register");
        return -1;
    }

    if (read(i2c_fd, read_data, 2) != 2) {
        perror("Error reading raw temperature");
        return -1;
    }

    *raw_temp = (read_data[0] << 8) | read_data[1];
    return 0;
}

// Function to read raw pressure from the BMP180
int read_raw_pressure(int32_t *raw_pressure) {
    uint8_t write_data[2];
    uint8_t read_data[3];

    write_data[0] = BMP180_REG_CONTROL;
    write_data[1] = 0x34 + (OSS << 6); // Pressure measurement command

    if (write(i2c_fd, write_data, 2) != 2) {
        perror("Error writing pressure measurement command");
        return -1;
    }

    usleep(26000); // Wait 25.5ms for OSS = 3

    write_data[0] = BMP180_REG_MSB;
    if (write(i2c_fd, write_data, 1) != 1) {
        perror("Error writing to read register");
        return -1;
    }

    if (read(i2c_fd, read_data, 3) != 3) {
        perror("Error reading raw pressure");
        return -1;
    }

    *raw_pressure = ((read_data[0] << 16) | (read_data[1] << 8) | read_data[2]) >> (8 - OSS);
    return 0;
}

// Function to calculate temperature in degrees Celsius
double calculate_temperature(int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;
    double temperature = ((B5 + 8) >> 4) / 10.0;
    return temperature;
}

// Function to calculate pressure in hPa
double calculate_pressure(int32_t raw_pressure, int32_t raw_temp) {
    int32_t X1 = ((raw_temp - (int32_t)ac6) * (int32_t)ac5) >> 15;
    int32_t X2 = ((int32_t)mc << 11) / (X1 + md);
    int32_t B5 = X1 + X2;

    int32_t B6 = B5 - 4000;
    X1 = (b2 * (B6 * B6) >> 12) >> 11;
    X2 = ac2 * B6 >> 11;
    int32_t X3 = X1 + X2;
    int32_t B3 = (((((int32_t)ac1) * 4 + X3) << OSS) + 2) >> 2;

    X1 = ac3 * B6 >> 13;
    X2 = (b1 * (B6 * B6) >> 12) >> 16;
    X3 = ((X1 + X2) + 2) >> 2;
    uint32_t B4 = ac4 * (uint32_t)(X3 + 32768) >> 15;
    uint32_t B7 = ((uint32_t)raw_pressure - B3) * (50000 >> OSS);

    int32_t p;
    if (B7 < 0x80000000)
    {
        p = (B7 * 2) / B4;
    }
    else
    {
        p = (B7 / B4) * 2;
    }

    X1 = (p >> 8) * (p >> 8);
    X1 = (X1 * 3038) >> 16;
    X2 = (-7357 * p) >> 16;
    double pressure = p + ((X1 + X2 + 3791) >> 4);

    return pressure / 100.0; // Convert to hPa
}

// Function to log pressure to a file
void log_pressure(double pressure) {
    FILE *fp = fopen("pressure_log.txt", "a");
    if (fp == NULL) {
        perror("Error opening pressure_log.txt");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "%d-%02d-%02d %02d:%02d:%02d, %.2f hPa\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, pressure);
    fclose(fp);
}

// Interrupt handler function
void interrupt_handler(int gpio, int level, uint32_t tick) {
    static uint32_t last_tick = 0;
    uint32_t current_tick = tick;

    if (current_tick - last_tick > DEBOUNCE_TIME) {
        logging_enabled = !logging_enabled;
        printf("Logging %s\n", logging_enabled ? "enabled" : "disabled");
