#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <curl/curl.h>
#include <jansson.h>
#include <pigpio.h>

#define DHT22_GPIO 4
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 2000
#define MAX_POST_RETRIES 3
#define POST_RETRY_DELAY_S 5
#define MAX_API_RETRIES 3
#define API_RETRY_DELAY_S 10
#define MAX_API_RETRIES_PER_READ 3
#define API_RETRY_DELAY_MS 100

// Structure to hold DHT22 data
typedef struct {
    float temperature;
    float humidity;
    int valid;
} DHT22Data;

// Global variables
static volatile int running = 1;
static char *api_url = "http://your-the-library's-api-call.com/api/humidity";
static int api_retries = 0;
static int api_retries_per_read = 0;

// Function prototypes
int read_dht22(DHT22Data *data);
int format_json(float temperature, float humidity, char *json_string, size_t json_string_size);
int post_data(const char *json_string);
int handle_api_error(int response_code);
void signal_handler(int signal);
void log_event(int priority, const char *message);

// Callback function for libcurl to write received data
size_t write_callback(char *contents, size_t size, size_t nmemb, void *userp) {
    size_t real_size = size * nmemb;
    return real_size;
}

// Function to read data from DHT22 sensor
int read_dht22(DHT22Data *data) {
    int i, j;
    int data_bits[40];
    int checksum;
    int retries = 0;
    int response_code = 0;
    CURL *curl;
    CURLcode res;
    char json_string[256];

    while (retries < MAX_RETRIES) {
        // Send start signal
        gpioSetMode(DHT22_GPIO, PI_OUTPUT);
        gpioWrite(DHT22_GPIO, 0);
        gpioDelay(1); // 1ms
        gpioWrite(DHT22_GPIO, 1);
        gpioDelay(30); // 30us

        // Set data line as input
        gpioSetMode(DHT22_GPIO, PI_INPUT);

        // Wait for response (low for ~80us, high for ~80us)
        int timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
            gpioDelay(1); // 1us
            timeout++;
        }

        if (timeout >= 100) {
            log_event(LOG_ERR, "DHT22: Timeout waiting for start signal");
            retries++;
            gpioDelay(RETRY_DELAY_MS);
            continue;
        }

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
            gpioDelay(1); // 1us
            timeout++;
        }

        if (timeout >= 100) {
            log_event(LOG_ERR, "DHT22: Timeout waiting for start signal (low)");
            retries++;
            gpioDelay(RETRY_DELAY_MS);
            continue;
        }

        timeout = 0;
        while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
            gpioDelay(1); // 1us
            timeout++;
        }

        if (timeout >= 100) {
            log_event(LOG_ERR, "DHT22: Timeout waiting for start signal (high)");
            retries++;
            gpioDelay(RETRY_DELAY_MS);
            continue;
        }

        // Read 40 bits of data
        for (i = 0; i < 40; i++) {
            timeout = 0;
            while (gpioRead(DHT22_GPIO) == 0 && timeout < 100) {
                gpioDelay(1); // 1us
                timeout++;
            }

            if (timeout >= 100) {
                log_event(LOG_ERR, "DHT22: Timeout waiting for data bit start (low)");
                retries++;
                gpioDelay(RETRY_DELAY_MS);
                goto retry;
            }

            long start = gpioTick();

            timeout = 0;
            while (gpioRead(DHT22_GPIO) == 1 && timeout < 100) {
                gpioDelay(1); // 1us
                timeout++;
            }

            if (timeout >= 100) {
                log_event(LOG_ERR, "DHT22: Timeout waiting for data bit start (high)");
                retries++;
                gpioDelay(RETRY_DELAY_MS);
                goto retry;
            }

            long end = gpioTick();
            long duration = end - start;

            data_bits[i] = (duration > 40) ? 1 : 0; // 0 if below 40us, 1 if above
        }

        // Calculate checksum
        checksum = 0;
        for (i = 0; i < 40; i++) {
            checksum += data_bits[i];
        }
        checksum &= 0xFF; // Mask to get the lower 8 bits

        // Validate checksum
        if (checksum != data_bits[40]) {
            log_event(LOG_ERR, "DHT22: Checksum error");
            retries++;
            gpioDelay(RETRY_DELAY_MS);
            continue;
        }

        // Convert data to temperature and humidity
        data->humidity = (float)(((data_bits[0] << 7) | (data_bits[1] << 6) | (data_bits[2] << 5) | (data_bits[3] << 4) | (data_bits[4] << 3) | (data_bits[5] << 2) | (data_bits[6] << 1) | data_bits[7])) / 10.0;
        data->temperature = (float)(((data_bits[8] << 7) | (data_bits[9] << 6) | (data_bits[10] << 5) | (data_bits[11] << 4) | (data_bits[12] << 3) | (data_bits[13] << 2) | (data_bits[14] << 1) | data_bits[15])) / 10.0;
        if (data->temperature > 125) {
            data->temperature -= 256;
        }

        data->valid = 1;
        return 0; // Success

retry:
        retries++;
        gpioDelay(RETRY_DELAY_MS);
    }

    log_event(LOG_ERR, "DHT22: Failed to read data after multiple retries");
    data->valid = 0;
    return -1; // Failure
}

// Function to format data into JSON string
int format_json(float temperature, float humidity, char *json_string, size_t json_string_size) {
    json_t *root = json_object();
    if (!root) {
        log_event(LOG_ERR, "JSON: Failed to create JSON object");
        return -1;
    }

    json_object_set_new(root, "temperature", json_real(temperature));
    json_object_set_new(root, "humidity", json_real(humidity));

    char *json_str = json_dumps(root, JSON_REAL_PRECISION(2));
    if (!json_str) {
        log_event(LOG_ERR, "JSON: Failed to serialize JSON object");
        json_decref(root);
        return -1;
    }

    strncpy(json_string, json_str, json_string_size - 1);
    json_string[json_string_size - 1] = '\0'; // Ensure null termination
    json_decref(root);
    json_str = NULL; // Free the allocated memory

    return 0;
}

// Function to post data to API endpoint
int post_data(const char *json_string) {
    CURL *curl;
    CURLcode res;
    char error_buffer[CURL_ERROR_SIZE];
    int retries = 0;

    while (retries < MAX_POST_RETRIES) {
        curl_global_init(CURL_GLOBAL_DEFAULT);
        curl = curl_easy_init();
        if (curl) {
            curl_easy_setopt(curl, CURLOPT_URL, api_url);
            curl_easy_setopt(curl, CURLOPT_POST, 1L);
            curl_easy_setopt(curl, CURLOPT_POSTFIELDS, json_string);
            curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, write_callback);
            curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, error_buffer);

            res = curl_easy_perform(curl);
            if (res != CURLE_OK) {
                log_event(LOG_ERR, "HTTP: curl_easy_perform() failed: %s", error_buffer);
                curl_easy_cleanup(curl);
                curl_global_cleanup();
                retries++;
                gpioDelay(POST_RETRY_DELAY_S * 1000); // Exponential backoff
                continue;
            }

            long response_code;
            curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &response_code);
            curl_easy_cleanup(curl);
            curl_global_cleanup();

            if (response_code >= 200 && response_code < 300) {
                return 0; // Success
            } else {
                handle_api_error(response_code);
                return -1; // Failure
            }
        } else {
            log_event(LOG_ERR, "HTTP: curl_easy_init() failed");
            curl_global_cleanup();
            retries++;
            gpioDelay(POST_RETRY_DELAY_S * 1000); // Exponential backoff
            continue;
        }
    }

    log_event(LOG_ERR, "HTTP: Failed to post data after multiple retries");
    return -1; // Failure
}

// Function to handle API errors
int handle_api_error(int response_code) {
    char message[256];
    snprintf(message, sizeof(message), "HTTP: API request failed with code %d", response_code);
    log_event(LOG_ERR, message);

    api_retries++;
    if (api_retries > MAX_API_RETRIES) {
        log_event(LOG_ERR, "HTTP: Max API retries reached");
        return -1; // Failure
    }

    return 0; // Retry
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event(LOG_INFO, "Signal received, shutting down...");
}

// Function to log events with timestamps
void log_event(int priority, const char *message) {
    time_t now = time(NULL);
