    char *json_str = json_dumps(root, JSON_REAL_PRECISION(2));
    if (!json_str) {
        log_event(LOG_ERR, "JSON: Failed to serialize JSON object");
        json_decref(root);
        return -1;
    }

    strncpy(json_string, json_str, json_string_size - 1);
    json_string[json_string_size - 1] = '\0'; // Ensure null termination
