// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;

    fp = fopen(CPU_TEMP_FILE, "r");
    if (fp == NULL) {
        log_message("Error opening CPU temperature file.");
        return -1;
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        log_message("Error reading CPU temperature.");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milli_celsius;
}

