#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/stat.h>
#include <sys/types.h>

// Configuration
#define CPU_TEMP_FILE "/sys/class/thermal/thermal_zone0/temp"
#define FAN_CONTROL_FILE "/sys/class/thermal/cooling_device0/cur_state"
#define LOG_FILE "/var/log/fan_control.log"
#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x48
#define I2C_REG_TEMP 0x00
#define I2C_REG_CONFIG 0x01
#define I2C_REG_CONTROL 0x02
#define I2C_REG_STATUS 0x03
#define I2C_REG_FAULT 0x04
#define I2C_REG_RESET 0x05
#define I2C_REG_DIAG 0x06
#define I2C_REG_DIAG_DATA 0x07
#define I2C_REG_DIAG_STATUS 0x08
#define I2C_REG_DIAG_CONTROL 0x09
#define I2C_REG_DIAG_DATA_LSB 0x0A
#define I2C_REG_DIAG_DATA_MSB 0x0B
#define I2C_REG_DIAG_DATA_XLSB 0x0C

#define MAX_FAN_SPEED 3
#define MIN_FAN_SPEED 0

// Global variables
static volatile int keep_running = 1;
static int i2c_fd = -1;

// Function prototypes
int read_cpu_temp();
int read_fan_state();
int set_fan_speed(int speed);
int log_message(const char *message);
int i2c_write_byte(int fd, uint8_t reg, uint8_t value);
int i2c_read_byte(int fd, uint8_t reg, uint8_t *value);
int i2c_read_word(int fd, uint8_t reg, uint16_t *value);
int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len);
int i2c_write_block(int fd, uint8_t reg, const uint8_t *buf, int len);
void signal_handler(int sig);

// Function to read CPU temperature from file
int read_cpu_temp() {
    FILE *fp;
    int temp_milli_celsius;

    fp = fopen(CPU_TEMP_FILE, "r");
    if (fp == NULL) {
        log_message("Error opening CPU temperature file.");
        return -1;
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        log_message("Error reading CPU temperature.");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return temp_milli_celsius;
}

// Function to read fan state from file
int read_fan_state() {
    FILE *fp;
    int fan_state;

    fp = fopen(FAN_CONTROL_FILE, "r");
    if (fp == NULL) {
        log_message("Error opening fan control file.");
        return -1;
    }

    if (fscanf(fp, "%d", &fan_state) != 1) {
        log_message("Error reading fan state.");
        fclose(fp);
        return -1;
    }

    fclose(fp);
    return fan_state;
}

// Function to set fan speed
int set_fan_speed(int speed) {
    FILE *fp;
    int current_fan_state;

    if (speed < MIN_FAN_SPEED || speed > MAX_FAN_SPEED) {
        log_message("Invalid fan speed.");
        return -1;
    }

    current_fan_state = read_fan_state();
    if (current_fan_state == -1) {
        return -1;
    }

    if (current_fan_state == speed) {
        return 0; // Already at the desired speed
    }

    fp = fopen(FAN_CONTROL_FILE, "w");
    if (fp == NULL) {
        log_message("Error opening fan control file for writing.");
        return -1;
    }

    if (fprintf(fp, "%d", speed) < 0) {
        log_message("Error writing fan state.");
        fclose(fp);
        return -1;
    }

    fclose(fp);

    // Log the fan speed change
    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Fan speed set to %d", speed);
    log_message(log_message_buffer);

    return 0;
}

// Function to log messages with timestamps
int log_message(const char *message) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);

    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
    return 0;
}

// I2C functions (using sysfs)
int i2c_write_byte(int fd, uint8_t reg, uint8_t value) {
    char buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(fd, buf, 2) != 2) {
        log_message("Error writing to I2C device.");
        return -1;
    }
    return 0;
}

int i2c_read_byte(int fd, uint8_t reg, uint8_t *value) {
    if (write(fd, &reg, 1) != 1) {
        log_message("Error writing register address for I2C read.");
        return -1;
    }

    if (read(fd, value, 1) != 1) {
        log_message("Error reading from I2C device.");
        return -1;
    }
    return 0;
}

int i2c_read_word(int fd, uint8_t reg, uint16_t *value) {
    uint8_t lsb, msb;

    if (write(fd, &reg, 1) != 1) {
        log_message("Error writing register address for I2C read.");
        return -1;
    }

    if (read(fd, &lsb, 1) != 1) {
        log_message("Error reading LSB from I2C device.");
        return -1;
    }

    if (read(fd, &msb, 1) != 1) {
        log_message("Error reading MSB from I2C device.");
        return -1;
    }

    *value = (msb << 8) | lsb;
    return 0;
}

int i2c_read_block(int fd, uint8_t reg, uint8_t *buf, int len) {
    if (write(fd, &reg, 1) != 1) {
        log_message("Error writing register address for I2C read.");
        return -1;
    }

    if (read(fd, buf, len) != len) {
        log_message("Error reading from I2C device.");
        return -1;
    }
    return 0;
}

int i2c_write_block(int fd, uint8_t reg, const uint8_t *buf, int len) {
    char buf_with_reg[len + 1];
    buf_with_reg[0] = reg;
    memcpy(buf_with_reg + 1, buf, len);

    if (write(fd, buf_with_reg, len + 1) != len + 1) {
        log_message("Error writing to I2C device.");
        return -1;
    }
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    keep_running = 0;
    log_message("Signal received, shutting down...");
}

int main() {
    int cpu_temp, fan_speed;
    int i2c_config;

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

