    i2c_fd = open(I2C_DEVICE, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return 1;
    }

    // Configure I2C (example: set clock speed and slave address)
    if (ioctl(i2c_fd, I2C_SLAVE, I2C_ADDRESS) < 0) {
