#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define HEATER_GPIO 18
#define SPI_CHANNEL 0
#define SPI_BAUD 500000
#define PWM_FREQUENCY 1000
#define PWM_RANGE 100
#define TARGET_TEMPERATURE 50.0
#define MAX_TEMPERATURE 100.0
#define MIN_TEMPERATURE 0.0
#define LOG_FILE "heater_log.txt"
#define FAILSAFE_TEMPERATURE 100.0
#define FAILSAFE_DURATION 5 // seconds

// PID Gains
#define KP 1.0
#define Ki 0.1
#define Kd 0.01

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// PID State
double integral = 0.0;
double previous_error = 0.0;

// Function Prototypes
int read_max31855(uint8_t *data);
double convert_to_temperature(uint8_t *data);
double calculate_pid(double setpoint, double actual_temperature);
void set_pwm_duty_cycle(int duty_cycle);
void log_data(double temperature, int duty_cycle, double pid_output);
void signal_handler(int signal);
void failsafe_check(double temperature);

// Function to read data from MAX31855 thermocouple amplifier
int read_max31855(uint8_t *data) {
    int result = spiRead(spi_handle, (char *)data, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading from SPI: %d\n", result);
        return -1;
    }
    return 0;
}

// Function to convert raw data to temperature (Celsius)
double convert_to_temperature(uint8_t *data) {
    int16_t raw_temp = (data[0] << 8) | data[1];
    int16_t raw_internal = (data[2] << 8) | data[3];

    // Check for fault bits
    if (data[3] & 0x01) {
        fprintf(stderr, "MAX31855 Fault: Open Circuit\n");
        return -1000.0; // Indicate error with a very low temperature
    }
    if (data[3] & 0x02) {
        fprintf(stderr, "MAX31855 Fault: Short to GND\n");
        return -1000.0; // Indicate error with a very low temperature
    }
    if (data[3] & 0x04) {
        fprintf(stderr, "MAX31855 Fault: Short to VCC\n");
        return -1000.0; // Indicate error with a very low temperature
    }

    // Extract temperature (bits 31:18)
    raw_temp >>= 2; // Remove fault bits
    double temperature = raw_temp * 0.25;

    return temperature;
}

// Function to calculate PID output
double calculate_pid(double setpoint, double actual_temperature) {
    double error = setpoint - actual_temperature;
    integral += error;
    double derivative = error - previous_error;
    double output = Kp * error + Ki * integral + Kd * derivative;
    previous_error = error;
    return output;
}

// Function to set PWM duty cycle
void set_pwm_duty_cycle(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;
    gpioPWM(HEATER_GPIO, duty_cycle);
}

// Function to log data to file
void log_data(double temperature, int duty_cycle, double pid_output) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp)-1, "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, Temperature: %.2f C, Duty Cycle: %d, PID Output: %.2f\n",
            timestamp, temperature, duty_cycle, pid_output);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Failsafe check
void failsafe_check(double temperature) {
    if (temperature > FAILSAFE_TEMPERATURE) {
        fprintf(stderr, "Failsafe triggered! Disabling heater.\n");
        set_pwm_duty_cycle(0);
        gpioTerminate();
        exit(0);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output for PWM
    gpioSetMode(HEATER_GPIO, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(HEATER_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(HEATER_GPIO, PWM_RANGE);

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

