#define PWM_FREQUENCY 25000
#define PWM_RANGE 1000

// Define temperature thresholds and duty cycles
#define TEMP_LOW 40.0
#define TEMP_HIGH 70.0
#define DUTY_LOW 0.0
#define DUTY_HIGH 100.0

// Global variables
FILE *log_file = NULL;
int running = 1;

// Function prototypes
float read_cpu_temperature();
float map_temperature_to_duty_cycle(float temperature);
int set_fan_speed(float duty_cycle);
int log_data(float temperature, float duty_cycle);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;
    set_fan_speed(0.0); // Turn off the fan
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
    exit(0);
}

// Function to read CPU temperature from /sys/class/thermal/thermal_zone0/temp
float read_cpu_temperature() {
    FILE *fp;
    int temp_milli_celsius;
    float temperature;

    fp = fopen("/sys/class/thermal/thermal_zone0/temp", "r");
    if (fp == NULL) {
        perror("Error opening temperature file");
        return -1.0; // Indicate error
    }

    if (fscanf(fp, "%d", &temp_milli_celsius) != 1) {
        perror("Error reading temperature");
        fclose(fp);
        return -1.0; // Indicate error
    }

    fclose(fp);
    temperature = (float)temp_milli_celsius / 1000.0;
    return temperature;
}

// Function to map temperature to duty cycle using linear interpolation
float map_temperature_to_duty_cycle(float temperature) {
    if (temperature < TEMP_LOW) {
        return DUTY_LOW;
    } else if (temperature > TEMP_HIGH) {
        return DUTY_HIGH;
    } else {
        return DUTY_LOW + (temperature - TEMP_LOW) * (DUTY_HIGH - DUTY_LOW) / (TEMP_HIGH - TEMP_LOW);
    }
}

// Function to set fan speed using pigpio
int set_fan_speed(float duty_cycle) {
    int duty_cycle_int = (int)(duty_cycle * PWM_RANGE);
    if (duty_cycle_int < 0) duty_cycle_int = 0;
    if (duty_cycle_int > PWM_RANGE) duty_cycle_int = PWM_RANGE;

    gpioPWM(FAN_PIN, duty_cycle_int);
    return 0;
}

