int log_data(float temperature, float duty_cycle) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    log_file = fopen("cooling_log.csv", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, temperature, duty_cycle);
    fclose(log_file);
    return 0;
}

int main() {
    float temperature;
    float duty_cycle;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency and range
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, PWM_RANGE);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Cooling system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        temperature = read_cpu_temperature();
        if (temperature < 0) {
            fprintf(stderr, "Error reading temperature, using previous value or defaulting to 50°C.\n");
            temperature = 50.0; // Default to 50°C
        }

        duty_cycle = map_temperature_to_duty_cycle(temperature);
        set_fan_speed(duty_cycle);

        if (log_data(temperature, duty_cycle) != 0) {
            fprintf(stderr, "Error logging data.\n");
        }

        printf("Temperature: %.2f °C, Duty Cycle: %.2f %%\n", temperature, duty_cycle);

        sleep(5);
    }

    // Cleanup (should not reach here if signal handler works correctly)
    set_fan_speed(0.0);
    gpioTerminate();

    return 0;
}

