#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define sensor addresses
#define SENSOR1_ADDR 0x70
#define SENSOR2_ADDR 0x71

// Define I2C bus
#define I2C_BUS 1

// Define log file name
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float flow1;
    float flow2;
} sensor_data_t;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_sensor_data(int handle, unsigned char *data);
unsigned char calculate_crc(const unsigned char *data, int len);
int validate_checksum(const unsigned char *data, int len);
int log_data(FILE *fp, float flow1, float flow2);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Read data from the sensor
int read_sensor_data(int handle, unsigned char *data) {
    int bytes_read = i2cReadDevice(handle, (char *)data, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading from I2C device: %d\n", bytes_read);
        return -1;
    }
    return 0;
}

// Calculate CRC-8 checksum
unsigned char calculate_crc(const unsigned char *data, int len) {
    unsigned char crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC checksum
int validate_checksum(const unsigned char *data, int len) {
    unsigned char crc = calculate_crc(data, len - 1);
    return (crc == data[len - 1]);
}

// Log data to file
int log_data(FILE *fp, float flow1, float flow2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    if (flow1 >= -200.0 && flow1 <= 200.0 && flow2 >= -200.0 && flow2 <= 200.0) {
        fprintf(fp, "%s,%.2f,%.2f\n", timestamp, flow1, flow2);
        fflush(fp); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Invalid flow values: flow1=%.2f, flow2=%.2f\n", flow1, flow2);
        return -1;
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C communication with both sensors
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        unsigned char data1[3];
        unsigned char data2[3];
        float flow1 = -1000.0; // Initialize to an invalid value
        float flow2 = -1000.0; // Initialize to an invalid value

        // Read data from sensor 1
        int retries1 = 0;
        while (retries1 < 3) {
            if (read_sensor_data(i2c_handle1, data1) == 0) {
                if (validate_checksum(data1, 3)) {
                    // Convert raw data to flow rate (example conversion, adjust as needed)
                    int raw_flow1 = (data1[0] << 8) | data1[1];
                    flow1 = (float)raw_flow1 / 100.0; // Example scaling
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "CRC check failed for sensor 1, retrying...\n");
                }
            } else {
                fprintf(stderr, "I2C read error for sensor 1, retrying...\n");
            }
            retries1++;
            gpioDelay(100000); // 100ms delay
        }

        // Read data from sensor 2
        int retries2 = 0;
        while (retries2 < 3) {
            if (read_sensor_data(i2c_handle2, data2) == 0) {
                if (validate_checksum(data2, 3)) {
                    // Convert raw data to flow rate (example conversion, adjust as needed)
                    int raw_flow2 = (data2[0] << 8) | data2[1];
                    flow2 = (float)raw_flow2 / 100.0; // Example scaling
                    break; // Exit retry loop on success
                } else {
                    fprintf(stderr, "CRC check failed for sensor 2, retrying...\n");
                }
            } else {
                fprintf(stderr, "I2C read error for sensor 2, retrying...\n");
            }
            retries2++;
            gpioDelay(100000); // 100ms delay
        }

        // Log data if both sensors read successfully
        if (flow1 != -1000.0 && flow2 != -1000.0) {
            log_data(log_file, flow1, flow2);
        }

        gpioDelay(1000000); // 1 second delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

