// Define GPIO pins for the encoder channels
#define ENCODER_A 17
#define ENCODER_B 18

// Define the number of pulses per revolution for the TMAG5110A1
#define PULSES_PER_REVOLUTION 360

// Define the log file name
#define LOG_FILE "encoder_log.txt"

// Global variables
static volatile int pulse_count = 0;
static volatile int last_state = 0;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold encoder data
typedef struct {
    int a_pin;
    int b_pin;
    int pulse_count;
    int last_state;
    FILE *log_file;
} EncoderData;

// Function prototypes
int initialize_gpio();
void encoder_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
double calculate_angular_position(int pulse_count);
void log_position(double angular_position);
void signal_handler(int signal);
void cleanup();

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(ENCODER_A, PI_INPUT);
    gpioSetPullUpDown(ENCODER_A, PI_PUD_UP);
    gpioSetMode(ENCODER_B, PI_INPUT);
    gpioSetPullUpDown(ENCODER_B, PI_PUD_UP);

    // Set up interrupt handlers for both channels
    if (gpioSetISRFuncEx(ENCODER_A, RISING_EDGE, 0, encoder_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for ENCODER_A\n");
        gpioTerminate();
        return 1;
    }
    if (gpioSetISRFuncEx(ENCODER_B, RISING_EDGE, 0, encoder_interrupt_handler, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR for ENCODER_B\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Interrupt handler function for the encoder channels
void encoder_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    EncoderData *data = (EncoderData *)user_data;
    int current_state = (gpio == ENCODER_A) ? gpioRead(ENCODER_A) : gpioRead(ENCODER_B);

    if (current_state == PI_HIGH) {
        if (data->last_state == PI_LOW) {
            if (gpio == ENCODER_A) {
                pulse_count++;
            } else {
                pulse_count--;
            }
        }
    }

    data->last_state = current_state;
}

// Function to calculate the angular position based on the pulse count
double calculate_angular_position(int pulse_count) {
    return (double)pulse_count / PULSES_PER_REVOLUTION * 360.0;
}

// Function to log the angular position to a file
void log_position(double angular_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, angular_position);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Signal handler function for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    EncoderData encoder_data = {ENCODER_A, ENCODER_B, 0, 0, NULL};

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    printf("Encoder monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Calculate angular position
        double angular_position = calculate_angular_position(pulse_count);

        // Log the position
        log_position(angular_position);

        // Reset pulse count for the next revolution
        pulse_count = 0;

        // Sleep for a short interval
        gpioDelay(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

