#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define ADPD144RI_ADDR 0x39
#define RED_REG 0x00
#define INFRARED_REG 0x02
#define LED_GPIO 17
#define THRESHOLD 2000
#define SAMPLE_INTERVAL_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_pigpio();
int init_i2c();
int read_sensor_data(int *red, int *ir);
int log_data(int red, int ir);
void control_led(int state);
void signal_handler(int signal);
void cleanup();

// Structure for sensor data (optional, but good practice)
typedef struct {
    int red;
    int ir;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (init_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("adpd144ri_log.txt", "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Main loop
    int red, ir;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&red, &ir) == 0) {
            // Log data
            if (log_data(red, ir) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }

            // Control LED based on threshold
            if (ir > THRESHOLD) {
                control_led(1); // Turn LED on
            } else {
                control_led(0); // Turn LED off
            }
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Delay
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int init_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C bus
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD144RI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read red and infrared sensor data
int read_sensor_data(int *red, int *ir) {
    char buf[4];
    int result;

    // Read red data
    result = i2cReadI2CBlockData(i2c_handle, RED_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read red data: %d\n", result);
        return 1;
    }
    *red = (buf[1] << 8) | buf[0];

    // Read infrared data
    result = i2cReadI2CBlockData(i2c_handle, INFRARED_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read infrared data: %d\n", result);
        return 1;
    }
    *ir = (buf[1] << 8) | buf[0];

    return 0;
}

// Log data to CSV file
int log_data(int red, int ir) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Write to log file
    fprintf(log_file, "%s,%d,%d\n", timestamp, red, ir);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Control LED state
void control_led(int state) {
    gpioWrite(LED_GPIO, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

