#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins
#define AUDIO_INPUT_PIN 17
#define GAIN_SELECT_PIN 18

// Define log file name
#define LOG_FILE "audio_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int select_gain(int gain);
int read_audio_level();
int log_event(int level);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int audio_input_pin;
    int gain_select_pin;
    int log_file_path[256];
} gpio_config_t;

gpio_config_t config = {AUDIO_INPUT_PIN, GAIN_SELECT_PIN, LOG_FILE};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(config.log_file_path, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", config.log_file_path);
        cleanup();
        return 1;
    }

    printf("Audio monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int audio_level = read_audio_level();
        if (audio_level == 1) {
            log_event(audio_level);
        }
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup and exit
    cleanup();
    printf("Audio monitoring stopped.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.audio_input_pin, PI_INPUT);
    gpioSetMode(config.gain_select_pin, PI_OUTPUT);

    // Set initial gain (60dB)
    if (select_gain(1) != 0) {
        fprintf(stderr, "Failed to select initial gain.\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Select gain (60dB)
int select_gain(int gain) {
    if (gain != 0 && gain != 1) {
        fprintf(stderr, "Invalid gain value. Must be 0 or 1.\n");
        return 1;
    }

    gpioWrite(config.gain_select_pin, gain);
    return 0;
}

// Read audio level
int read_audio_level() {
    return gpioRead(config.audio_input_pin);
}

// Log event to file
int log_event(int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s LEVEL\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

