        if (audio_level == 1) {
            log_event(audio_level);
        }
        gpioDelay(10000); // 10ms delay
    }

    // Cleanup and exit
    cleanup();
    printf("Audio monitoring stopped.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(config.audio_input_pin, PI_INPUT);
    gpioSetMode(config.gain_select_pin, PI_OUTPUT);

    // Set initial gain (60dB)
    if (select_gain(1) != 0) {
        fprintf(stderr, "Failed to select initial gain.\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Select gain (60dB)
int select_gain(int gain) {
    if (gain != 0 && gain != 1) {
        fprintf(stderr, "Invalid gain value. Must be 0 or 1.\n");
        return 1;
    }

    gpioWrite(config.gain_select_pin, gain);
    return 0;
}

// Read audio level
int read_audio_level() {
    return gpioRead(config.audio_input_pin);
}

// Log event to file
int log_event(int level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (fprintf(log_file, "%s LEVEL\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return 1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

