// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Function to read flow rate from the sensor
int read_flow_rate(float *flow_rate) {
    uint8_t cmd[2] = {0x36, 0x08}; // Trigger measurement command
    uint8_t buffer[3];
    int result;

    // Send trigger measurement command
    result = i2cWriteDevice(i2c_handle, (char *)cmd, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", result);
        return -1;
    }

    // Wait for measurement to complete (adjust as needed based on datasheet)
    gpioDelay(10); // 10 ms delay

