    uint8_t crc = crc8(buffer, 2);
    if (crc != buffer[2]) {
        fprintf(stderr, "CRC validation failed!\n");
        return -1;
    }

    // Convert raw data to flow rate (example conversion, adjust based on datasheet)
    int16_t raw_flow = (buffer[0] << 8) | buffer[1];
    *flow_rate = (float)raw_flow / 100.0; // Example scaling

    return 0;
}

