    log_file = fopen(FLOW_LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    // Write data to log file
    fprintf(log_file, "%s,%.2f\n", timestamp, flow_rate);

