    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C device
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read flow rate
        result = read_flow_rate(&flow_rate);
        if (result == 0) {
            // Log flow rate
            if (log_flow_rate(flow_rate) != 0) {
                fprintf(stderr, "Error logging flow rate!\n");
            }
        } else {
            fprintf(stderr, "Error reading flow rate, skipping logging.\n");
        }

        // Wait for 1000 ms
        gpioDelay(1000);
    }

    // Close I2C device
    i2cClose(i2c_handle);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

