}

// Read sensor data from the MICS-VZ-89TE
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buf[4];
    int result;

    // Trigger measurement (replace with actual command from datasheet)
    result = i2cWriteByte(i2c_handle, 0x01); // Example command
    if (result < 0) {
        fprintf(stderr, "Error triggering measurement: %d\n", result);
        data.tvoc = 0; // Set to 0 to indicate error
        data.eco2 = 0;
        return data;
    }

    // Wait for measurement to complete (adjust delay as needed)
    gpioDelay(10000); // 10ms

    // Read 4 bytes of data (TVOC MSB, TVOC LSB, eCO2 MSB, eCO2 LSB)
    result = i2cReadDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        data.tvoc = 0; // Set to 0 to indicate error
        data.eco2 = 0;
        return data;
    }

    // Combine MSB and LSB for TVOC and eCO2
    data.tvoc = (buf[0] << 8) | buf[1];
    data.eco2 = (buf[2] << 8) | buf[3];

    return data;
}

