    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        // Read sensor data
        sensor_data_t sensor_data = read_sensor_data();

        // Calculate IAQ
        float iaq = calculate_iaq(sensor_data.tvoc, sensor_data.eco2);

        // Log data
        if (log_data(iaq) != 0) {
            fprintf(stderr, "Error logging data\n");
        }

        // Wait for the next interval
        gpioDelay(READ_INTERVAL_SEC * 1000000); // Convert seconds to microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

