#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2s.h>
#include <pigpio.h>

// Configuration
#define I2S_DEVICE "/dev/snd/pcmC0D0c"
#define GPIO_PIN 17
#define SAMPLE_RATE 44100
#define NUM_CHANNELS 2
#define BITS_PER_SAMPLE 16
#define BUFFER_SIZE (SAMPLE_RATE * NUM_CHANNELS * BITS_PER_SAMPLE / 8)
#define FILE_NAME "audio_capture.pcm"

// Global variables
static volatile int running = 1;
static int i2s_fd = -1;
static FILE *audio_file = NULL;

// Structure to hold I2S configuration
typedef struct {
    int sample_rate;
    int num_channels;
    int bits_per_sample;
} i2s_config_t;

// Signal handler for graceful termination
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the I2S interface
int init_i2s(const char *device, i2s_config_t *config) {
    int fd = open(device, O_RDWR);
    if (fd < 0) {
        perror("Error opening I2S device");
        return -1;
    }

    // Configure I2S parameters
    struct i2s_config cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.access = I2S_ACCESS_RW_INTERLEAVED;
    cfg.format = I2S_FORMAT_S16_LE;
    cfg.rate = config->sample_rate;
    cfg.channels = config->num_channels;
    cfg.bits = config->bits_per_sample;

    if (ioctl(fd, I2S_IOC_INIT, &cfg) < 0) {
        perror("Error initializing I2S");
        close(fd);
        return -1;
    }

    return fd;
}

// Function to select the left channel
int select_left_channel(int gpio_pin) {
    gpioSetMode(gpio_pin, PI_OUTPUT);
    gpioWrite(gpio_pin, 0); // Select left channel
    return 0;
}

// Function to capture audio data
int capture_audio(int fd, FILE *file, int sample_rate, int num_channels, int bits_per_sample) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_read;

    while (running) {
        bytes_read = read(fd, buffer, BUFFER_SIZE);
        if (bytes_read < 0) {
            perror("Error reading from I2S device");
            return -1;
        } else if (bytes_read == 0) {
            // End of file reached
            break;
        }

        // Write to file
        if (fwrite(buffer, 1, bytes_read, file) != bytes_read) {
            perror("Error writing to file");
            return -1;
        }
    }

    return 0;
}

// Function to cleanup resources
void cleanup(int i2s_fd, FILE *audio_file) {
    if (i2s_fd != -1) {
        close(i2s_fd);
    }
    if (audio_file != NULL) {
        fclose(audio_file);
    }
    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2S
    i2s_config_t i2s_config = {SAMPLE_RATE, NUM_CHANNELS, BITS_PER_SAMPLE};
    i2s_fd = init_i2s(I2S_DEVICE, &i2s_config);
    if (i2s_fd < 0) {
        cleanup(-1, NULL);
        return 1;
    }

    // Select left channel
    select_left_channel(GPIO_PIN);

    // Open audio file
    audio_file = fopen(FILE_NAME, "wb");
    if (audio_file == NULL) {
        perror("Error opening audio file");
        cleanup(i2s_fd, NULL);
        return 1;
    }

    // Capture audio
    if (capture_audio(i2s_fd, audio_file, SAMPLE_RATE, NUM_CHANNELS, BITS_PER_SAMPLE) < 0) {
        cleanup(i2s_fd, audio_file);
        return 1;
    }

    // Cleanup and exit
    cleanup(i2s_fd, audio_file);
    return 0;
}

