#include <pigpio.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 4
#define FAN_PIN 18

// Define PWM frequency
#define PWM_FREQUENCY 100

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Define log file name
#define LOG_FILE "flame_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void control_fan(int state);
void log_event(const char *event_type);
void signal_handler(int signal);
void cleanup();

// Structure to hold GPIO configuration
typedef struct {
    int flame_sensor_pin;
    int fan_pin;
    int pwm_frequency;
    int debounce_time;
    const char *log_file_name;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(FAN_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(FAN_PIN, PWM_FREQUENCY);
    gpioSetPWMrange(FAN_PIN, 1000); // Set PWM range to 1000 for 100% duty cycle

    return 0;
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor\n");
        return -1; // Indicate error
    }
    return value;
}

// Function to control the cooling fan
void control_fan(int state) {
    gpioPWM(FAN_PIN, state);
}

// Function to log events to a file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    // Stop the fan
    control_fan(0);

    // Reset GPIO pins
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT); // Set back to input
    gpioSetMode(FAN_PIN, PI_INPUT);

    // Terminate pigpio
    gpioTerminate();

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    log_event("Program started");

    // Main loop
    while (running) {
        int flame_detected = 0;
        int timeout_count = 0;
        int last_flame_state = -1; // Initialize to an invalid state

        // Read the flame sensor with debouncing
        while (timeout_count < 10) { // Timeout after 10 attempts
            int current_flame_state = read_flame_sensor();
            if (current_flame_state < 0) {
                fprintf(stderr, "Error reading flame sensor, retrying...\n");
                gpioDelay(10); // Small delay before retrying
                timeout_count++;
                continue;
            }

            if (current_flame_state == 0) { // Flame detected (LOW signal)
                flame_detected = 1;
                break;
            }

            if (last_flame_state != current_flame_state) {
                last_flame_state = current_flame_state;
                timeout_count = 0; // Reset timeout if a valid reading is obtained
            }

            gpioDelay(DEBOUNCE_TIME); // Debounce delay
        }

        if (!flame_detected) {
            // Flame sensor timeout
            log_event("Sensor timeout");
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Flame detected
        log_event("Flame detected");

        // Start the fan
        control_fan(1);

        // Wait for 5 seconds
        gpioDelay(5000);

        // Stop the fan
        control_fan(0);

        // Log the end of the event
        log_event("Flame end");
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

