        fprintf(stderr, "Error writing radar config\n");
        fclose(log_file);
        return -1;
    }

    // Write frame data
    if (fwrite(frame_data, 1, frame_size, log_file) != frame_size) {
        fprintf(stderr, "Error writing frame data\n");
        fclose(log_file);
        return -1;
    }

    fclose(log_file);
    return 0;
}

