#define LOG_FILE "flame_log.txt"

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to get the current timestamp in ISO 8601 format
char* get_iso8601_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        perror("Failed to allocate memory for timestamp");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to log the flame state to a file
int log_flame_state(const char *timestamp, int state) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s,%d\n", timestamp, state) < 0) {
        perror("Error writing to log file");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to handle the flame sensor state change
void handle_flame_state_change(int gpio, int level, uint32_t tick) {
    char *timestamp = get_iso8601_timestamp();
    if (timestamp == NULL) {
        fprintf(stderr, "Error getting timestamp.\n");
        return;
    }

    if (log_flame_state(timestamp, level) != 0) {
        fprintf(stderr, "Error logging flame state.\n");
    }

    free(timestamp); // Free the allocated memory
}

// Signal handler for graceful shutdown
