#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define OPT3001_ADDR 0x44

// Define the register addresses
#define RESULT_REG 0x00
#define CONFIG_REG 0x01

// Define the configuration values
#define CONFIG_OS_AUTO 0x8000 // Continuous conversion mode
#define CONFIG_RANGE_400 0x2000 // Full-scale range
#define CONFIG_MODE_CONT 0x0000 // Continuous conversion mode

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor configuration
typedef struct {
    uint16_t config;
} sensor_config_t;

// Function prototypes
int init_i2c();
int configure_sensor(sensor_config_t config);
int read_sensor_data(uint16_t *raw_data);
float convert_to_lux(uint16_t raw_data);
int log_data(float lux_value);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Configure the OPT3001 sensor
int configure_sensor(sensor_config_t config) {
    char buf[3];
    buf[0] = CONFIG_REG;
    buf[1] = (config.config >> 8) & 0xFF;
    buf[2] = config.config & 0xFF;

    int result = i2cWriteDevice(i2c_handle, buf, 3);
    if (result != 0) {
        fprintf(stderr, "Failed to write to config register: %d\n", result);
        return -1;
    }

    return 0;
}

// Read raw sensor data from the OPT3001
int read_sensor_data(uint16_t *raw_data) {
    char buf[1];
    buf[0] = RESULT_REG;

    int result = i2cWriteDevice(i2c_handle, buf, 1);
    if (result != 0) {
        fprintf(stderr, "Failed to write to result register: %d\n", result);
        return -1;
    }

    char read_buf[2];
    result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read from result register: %d\n", result);
        return -1;
    }

    *raw_data = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Convert raw sensor data to lux
float convert_to_lux(uint16_t raw_data) {
    // Check for sensor-absent condition
    if (raw_data == 0xFFFF) {
        fprintf(stderr, "Sensor absent or not ready\n");
        return -1.0;
    }

    // Extract the exponent and result from the raw data
    int exponent = (raw_data >> 12) & 0x0F;
    int result = raw_data & 0x0FFF;

    // Calculate the lux value
    float lux = result * (0.01 * (1 << exponent));

    return lux;
}

// Log the lux value to a file
int log_data(float lux_value) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Configure the sensor
    sensor_config_t config = {CONFIG_OS_AUTO | CONFIG_RANGE_400 | CONFIG_MODE_CONT};
    if (configure_sensor(config) != 0) {
        cleanup();
        return 1;
    }

    printf("OPT3001 sensor initialized and configured. Logging data to light_data.txt...\n");

    // Main loop
    while (!terminate) {
        uint16_t raw_data;
        if (read_sensor_data(&raw_data) == 0) {
            float lux_value = convert_to_lux(raw_data);
            if (lux_value >= 0) {
                log_data(lux_value);
                printf("Lux: %.2f\n", lux_value);
            } else {
                fprintf(stderr, "Failed to convert raw data to lux\n");
            }
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        gpioDelay(100); // Wait 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

