#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pin connected to the flame sensor
#define FLAME_SENSOR_GPIO 17

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in YYYY-MM-DD HH:MM:SS format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    static char timestamp[20]; // Static to persist across calls

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);
    return timestamp;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_GPIO);
    if (value < 0) {
        fprintf(stderr, "%s Error reading flame sensor value: %d\n", get_timestamp(), value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log the flame detection status to the console
void log_flame_status(int sensor_value) {
    char* timestamp = get_timestamp();
    if (sensor_value == 0) {
        printf("%s Flame Detected: YES\n", timestamp);
    } else if (sensor_value == 1) {
        printf("%s Flame Detected: NO\n", timestamp);
    } else {
        fprintf(stderr, "%s Invalid sensor value: %d\n", timestamp, sensor_value);
    }
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "%s pigpio initialisation failed\n", get_timestamp());
        return 1;
    }

    // Request the GPIO line as an input with a pull-up resistor
    if (gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT) != 0) {
        fprintf(stderr, "%s Failed to set GPIO %d as input\n", get_timestamp(), FLAME_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    if (gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP) != 0) {
        fprintf(stderr, "%s Failed to set pull-up resistor on GPIO %d\n", get_timestamp(), FLAME_SENSOR_GPIO);
        gpioTerminate();
        return 1;
    }

    // Main loop to read and log the flame sensor status
    while (program_running) {
        int sensor_value = read_flame_sensor();
        if (sensor_value != -1) {
            log_flame_status(sensor_value);
        }
        sleep(1); // Wait for 1 second
    }

    // Release the GPIO line request
    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT); // Set back to input to avoid issues
    gpioTerminate(); // Terminate the pigpio library

    return 0;
}

