#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensor
#define LEFT_PIN 17
#define CENTER_PIN 18
#define RIGHT_PIN 27

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(LEFT_PIN, PI_INPUT);
    gpioSetMode(CENTER_PIN, PI_INPUT);
    gpioSetMode(RIGHT_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop to read sensor values
    while (program_running) {
        // Read the sensor values
        int left_value = gpioRead(LEFT_PIN);
        int center_value = gpioRead(CENTER_PIN);
        int right_value = gpioRead(RIGHT_PIN);

        // Check for errors during GPIO read
        if (left_value < 0 || center_value < 0 || right_value < 0) {
            fprintf(stderr, "Error reading GPIO pin\n");
            break; // Exit loop on error
        }

        // Print the sensor values to the console
        printf("Left: %d, Center: %d, Right: %d\n", left_value, center_value, right_value);

        // Wait for 50 milliseconds
        usleep(50000);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

