    // Open the GPIO chip
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    // Set the GPIO pins as outputs
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (gpioSetMode(TTP226_CHANNELS[i], PI_OUTPUT) != 0) {
            fprintf(stderr, "Error: Failed to set GPIO %d as output\n", TTP226_CHANNELS[i]);
