    if (channel < 1 || channel > NUM_CHANNELS) {
        fprintf(stderr, "Error: Invalid channel number: %d\n", channel);
        return -1;
    }

    int value = gpioRead(TTP226_CHANNELS[channel - 1]);
    if (value < 0) {
        fprintf(stderr, "Error: Failed to read GPIO %d\n", TTP226_CHANNELS[channel - 1]);
        return -1;
    }

    return value;
}

// Function to log the state of all channels
void log_channels() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] ", timestamp);

    for (int i = 0; i < NUM_CHANNELS; i++) {
        int value = read_channel(i + 1);
        if (value == 0) {
            printf("OUT%d=0 ", i + 1);
        } else if (value == 1) {
            printf("OUT%d=1 ", i + 1);
        } else {
            printf("OUT%d=ERROR ", i + 1);
        }
    }
    printf("\n");
}

