        log_channels();
        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Release resources before exiting
    for (int i = 0; i < NUM_CHANNELS; i++) {
        gpioWrite(TTP226_CHANNELS[i], 0); // Set all channels to LOW
        gpioSetMode(TTP226_CHANNELS[i], PI_INPUT); // Set to input to avoid floating
    }
    gpioTerminate();

    return 0;
}

