#define SENSOR_PIN_4 5
#define SENSOR_PIN_5 6
#define SENSOR_PIN_6 7
#define SENSOR_PIN_7 8
#define SENSOR_PIN_8 9

// Structure to hold sensor data
typedef struct {
    int channel1;
    int channel2;
    int channel3;
    int channel4;
    int channel5;
    int channel6;
    int channel7;
    int channel8;
} sensor_data_t;

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set the GPIO pins as inputs with pull-down resistors
    gpioSetMode(SENSOR_PIN_1, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_1, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_2, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_2, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_3, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_3, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_4, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_4, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_5, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_5, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_6, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_6, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_7, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_7, PI_PUD_DOWN);
    gpioSetMode(SENSOR_PIN_8, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN_8, PI_PUD_DOWN);

    return 0;
}

// Function to read the sensor data from the TTP226
int read_sensor_data(sensor_data_t *data) {
    data->channel1 = gpioRead(SENSOR_PIN_1);
    data->channel2 = gpioRead(SENSOR_PIN_2);
    data->channel3 = gpioRead(SENSOR_PIN_3);
    data->channel4 = gpioRead(SENSOR_PIN_4);
    data->channel5 = gpioRead(SENSOR_PIN_5);
    data->channel6 = gpioRead(SENSOR_PIN_6);
    data->channel7 = gpioRead(SENSOR_PIN_7);
    data->channel8 = gpioRead(SENSOR_PIN_8);

    return 0;
}

// Function to validate the sensor data
int validate_sensor_data(const sensor_data_t *data) {
    if (data->channel1 < 0 || data->channel1 > 1) {
        fprintf(stderr, "Error: Invalid channel 1 value: %d\n", data->channel1);
        return -1;
    }
    if (data->channel2 < 0 || data->channel2 > 1) {
        fprintf(stderr, "Error: Invalid channel 2 value: %d\n", data->channel2);
        return -1;
    }
    if (data->channel3 < 0 || data->channel3 > 1) {
        fprintf(stderr, "Error: Invalid channel 3 value: %d\n", data->channel3);
        return -1;
    }
    if (data->channel4 < 0 || data->channel4 > 1) {
        fprintf(stderr, "Error: Invalid channel 4 value: %d\n", data->channel4);
        return -1;
    }
    if (data->channel5 < 0 || data->channel5 > 1) {
        fprintf(stderr, "Error: Invalid channel 5 value: %d\n", data->channel5);
        return -1;
    }
    if (data->channel6 < 0 || data->channel6 > 1) {
        fprintf(stderr, "Error: Invalid channel 6 value: %d\n", data->channel6);
        return -1;
    }
    if (data->channel7 < 0 || data->channel7 > 1) {
        fprintf(stderr, "Error: Invalid channel 7 value: %d\n", data->channel7);
        return -1;
    }
    if (data->channel8 < 0 || data->channel8 > 1) {
        fprintf(stderr, "Error: Invalid channel 8 value: %d\n", data->channel8);
        return -1;
    }

    return 0;
}

// Function to print the sensor data with a timestamp
void print_sensor_data(const sensor_data_t *data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    long milliseconds = ts.tv_nsec / 1000000;

    printf("[%ld.%03ld] CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d\n",
           ts.tv_sec, milliseconds, data->channel1, data->channel2, data->channel3,
           data->channel4, data->channel5, data->channel6, data->channel7, data->channel8);
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library and configure the GPIO pins
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("TTP226 sensor data acquisition started. Press Ctrl+C to exit.\n");

    // Main loop to read and validate sensor data
    while (program_running) {
        sensor_data_t sensor_data;

        // Read the sensor data
        if (read_sensor_data(&sensor_data) != 0) {
            fprintf(stderr, "Error reading sensor data\n");
            break; // Exit loop on error
        }

        // Validate the sensor data
        if (validate_sensor_data(&sensor_data) != 0) {
            fprintf(stderr, "Error validating sensor data\n");
            break; // Exit loop on error
        }

        // Print the sensor data
        print_sensor_data(&sensor_data);

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100000 microseconds = 100 milliseconds
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    printf("TTP226 sensor data acquisition stopped.\n");

    return 0;
}

