#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pin connected to the tilt sensor
#define TILT_SENSOR_PIN 4

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Configure the GPIO pin as an input with the internal pull-up resistor
    gpioSetMode(TILT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TILT_SENSOR_PIN, PI_PUD_UP);

    // Print a startup banner
    printf("Tilt sensor monitoring started. Press Ctrl+C to exit.\n");

    // Install the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to continuously monitor the tilt sensor
    while (program_running) {
        // Read the state of the tilt sensor
        int sensor_value = gpioRead(TILT_SENSOR_PIN);

        // Check for errors during the read operation
        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor value\n");
            // Attempt to re-initialize the pigpio library
            gpioTerminate();
            gpioInitialise();
            gpioSetMode(TILT_SENSOR_PIN, PI_INPUT);
            gpioSetPullUpDown(TILT_SENSOR_PIN, PI_PUD_UP);
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        // Check if the sensor is tilted (LOW signal)
        if (sensor_value == 0) {
            // Flush the output buffer to ensure the latest state is printed
            fflush(stdout);
            printf("Tilted\n");
        } else {
            // Flush the output buffer to ensure the latest state is printed
            fflush(stdout);
            printf("Not Tilted\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100);
    }

    // Terminate the pigpio library before exiting
    gpioTerminate();

    return 0;
}

