#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define GPIO_ALARM 17
#define FLOW_RATE_THRESHOLD 0.5 // ml/min
#define LOG_FILE "flow_log.txt"
#define START_COMMAND 0x3608 // Start continuous measurement command

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data and configuration
typedef struct {
    int i2c_handle;
    int address;
    float flow_rate;
    int valid;
} sensor_data_t;

// Function prototypes
int initialize_pigpio();
int initialize_i2c(int bus, int addr);
int start_measurement(int handle);
int read_flow_rate(int handle, uint16_t *raw_flow);
float calculate_flow_rate(uint16_t raw_flow);
int validate_crc(uint16_t raw_flow, uint8_t crc);
float calculate_average_flow_rate(float flow_rate1, float flow_rate2);
void control_alarm(float average_flow_rate);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// CRC-8 calculation function (from Sensirion datasheet)
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 1. Exiting.\n");
        cleanup();
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        fprintf(stderr, "Failed to initialize I2C for sensor 2. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        cleanup();
        return 1;
    }

    // Start measurements
    if (start_measurement(i2c_handle1) != 0) {
        log_error("Failed to start measurement for sensor 1");
    }
    if (start_measurement(i2c_handle2) != 0) {
        log_error("Failed to start measurement for sensor 2");
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_flow1, raw_flow2;
        float flow_rate1, flow_rate2, average_flow_rate;
        int valid1 = 0, valid2 = 0;

        // Read flow rates from sensor 1
        if (read_flow_rate(i2c_handle1, &raw_flow1) == 0) {
            flow_rate1 = calculate_flow_rate(raw_flow1);
            if (validate_crc(raw_flow1, crc8((uint8_t *)&raw_flow1, 2)) == 0) {
                valid1 = 1;
            } else {
                log_error("CRC check failed for sensor 1");
            }
        } else {
            log_error("Failed to read flow rate from sensor 1");
        }

        // Read flow rates from sensor 2
        if (read_flow_rate(i2c_handle2, &raw_flow2) == 0) {
            flow_rate2 = calculate_flow_rate(raw_flow2);
            if (validate_crc(raw_flow2, crc8((uint8_t *)&raw_flow2, 2)) == 0) {
                valid2 = 1;
            } else {
                log_error("CRC check failed for sensor 2");
            }
        } else {
            log_error("Failed to read flow rate from sensor 2");
        }

        // Calculate average flow rate
        average_flow_rate = calculate_average_flow_rate(flow_rate1, flow_rate2);

        // Control alarm
        control_alarm(average_flow_rate);

        // Log data
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[64];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

        fprintf(log_file, "%s, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min, Average: %.2f ml/min\n",
                timestamp, flow_rate1, flow_rate2, average_flow_rate);
        fflush(log_file);

        // Wait for 1 second
        gpioDelay(1000); // pigpio's delay function
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    gpioSetMode(GPIO_ALARM, PI_OUTPUT);
    gpioWrite(GPIO_ALARM, 0); // Ensure alarm is initially off
    return 0;
}

// Initialize I2C communication
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Failed to open I2C device at address 0x%02X: %d\n", addr, handle);
        return -1;
    }
    return handle;
}

// Start continuous measurement on the sensor
int start_measurement(int handle) {
    char buf[2];
    buf[0] = (START_COMMAND >> 8) & 0xFF;
    buf[1] = START_COMMAND & 0xFF;

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to start measurement: %d\n", result);
        return -1;
    }
    return 0;
}

// Read flow rate from the sensor
int read_flow_rate(int handle, uint16_t *raw_flow) {
    char buf[2];
    buf[0] = 0x00; // Dummy register address
    buf[1] = 0x00; // Dummy register address

    int result = i2cWriteDevice(handle, buf, 2);
    if (result != 0) {
        fprintf(stderr, "Failed to write register address: %d\n", result);
        return -1;
    }

    char read_buf[3];
    result = i2cReadDevice(handle, read_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Failed to read flow rate: %d\n", result);
        return -1;
    }

    *raw_flow = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Calculate flow rate in ml/min
float calculate_flow_rate(uint16_t raw_flow) {
    // Conversion factor from Sensirion datasheet (example value, check your sensor's datasheet)
    float conversion_factor = 0.001; // Example: 1 unit = 0.001 ml/min
    return (float)raw_flow * conversion_factor;
}

// Validate CRC checksum
int validate_crc(uint16_t raw_flow, uint8_t crc) {
    uint8_t data[2];
    data[0] = (raw_flow >> 8) & 0xFF;
    data[1] = raw_flow & 0xFF;

    uint8_t calculated_crc = crc8(data, 2);
    return calculated_crc != crc;
}

// Calculate average flow rate
float calculate_average_flow_rate(float flow_rate1, float flow_rate2) {
    if (flow_rate1 == -1.0 && flow_rate2 == -1.0) {
        return -1.0; // Indicate no valid readings
    } else if (flow_rate1 == -1.0) {
        return flow_rate2;
    } else if (flow_rate2 == -1.0) {
        return flow_rate1;
    } else {
        return (flow_rate1 + flow_rate2) / 2.0;
    }
}

// Control alarm based on average flow rate
void control_alarm(float average_flow_rate) {
    if (average_flow_rate < FLOW_RATE_THRESHOLD) {
        gpioWrite(GPIO_ALARM, 1); // Turn alarm on
    } else {
        gpioWrite(GPIO_ALARM, 0); // Turn alarm off
    }
}

// Log error messages to file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s, ERROR: %s\n", timestamp, message);
    fflush(log_file);
    perror(message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");

    // Stop measurements
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Release GPIO
    gpioWrite(GPIO_ALARM, 0); // Ensure alarm is off
    gpioTerminate();
}

