#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <time.h>
#include <pigpio.h>

// Define the GPIO pin connected to the KY-033 sensor
#define SENSOR_PIN 4

// Define the circular buffer size
#define BUFFER_SIZE 100

// Structure to hold sensor data and timestamp
typedef struct {
    time_t timestamp;
    int sensor_value;
} SensorData;

// Global variables
SensorData sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
int running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor();
void add_to_buffer(SensorData data);
SensorData get_from_buffer(int index);
void print_buffer();
void signal_handler(int signal);

// Function to initialize the pigpio library and configure the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0; // Indicate success
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to add data to the circular buffer
void add_to_buffer(SensorData data) {
    sensor_buffer[buffer_index] = data;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
    if (buffer_count < BUFFER_SIZE) {
        buffer_count++;
    }
}

// Function to get data from the circular buffer
SensorData get_from_buffer(int index) {
    if (index < 0 || index >= buffer_count) {
        SensorData empty_data = {0, 0}; // Return an empty data structure
        return empty_data;
    }
    return sensor_buffer[index];
}

// Function to print the contents of the circular buffer
void print_buffer() {
    printf("Sensor Data Buffer:\n");
    for (int i = 0; i < buffer_count; i++) {
        SensorData data = get_from_buffer(i);
        struct tm *timeinfo = localtime(&data.timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("[%s] Sensor Value: %d\n", timestamp_str, data.sensor_value);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register the signal handler for SIGINT (Ctrl+C)
    signal(SIGINT, signal_handler);

    // Initialize the GPIO library
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read the sensor value
        int sensor_value = read_sensor();

        // Get the current timestamp
        time_t current_time = time(NULL);

        // Create a SensorData struct
        SensorData data = {current_time, sensor_value};

        // Add the data to the circular buffer
        add_to_buffer(data);

        // Check if an obstacle is detected (LOW signal)
        if (sensor_value == 0) {
            // Get the current timestamp
            struct tm *timeinfo = localtime(&current_time);
            char timestamp_str[20];
            strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Print an alert message
            printf("[%s] Obstacle detected! Sensor Value: %d\n", timestamp_str, sensor_value);
        }

        // Wait for 50 milliseconds
        gpioDelay(50000); // pigpioDelay takes microseconds
    }

    // Print the buffer before exiting
    print_buffer();

    // Release GPIO resources
    gpioTerminate();

    printf("Sensor monitoring stopped.\n");

    return 0;
}

