#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <pigpio.h>

// Constants
#define I2C_BUS "/dev/i2c-1"
#define D7S_ADDR 0x53
#define GPIO_SDA 2
#define GPIO_SCL 3
#define SAMPLE_RATE_MS 500
#define ONE_SECOND_MS 1000
#define MAX_RETRIES 3
#define RETRY_DELAY_MS 10

// Global variables
static int i2c_fd = -1;
static FILE *csv_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int i2c_write_reg(int fd, uint8_t reg, uint8_t value);
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value);
int d7s_init(int fd);
int d7s_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z);
int d7s_set_mode(int fd, uint8_t mode);
int d7s_get_status(int fd);
int check_sensor_status(int status);
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);

// I2C write function with retry
int i2c_write_reg(int fd, uint8_t reg, uint8_t value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_smbus_write_byte_data(fd, reg, value);
        if (result == 0) {
            return 0; // Success
        } else {
            fprintf(stderr, "I2C write error (reg 0x%02X, value 0x%02X): %s (attempt %d/%d)\n", reg, value, strerror(errno), retries + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "I2C write failed after %d retries (reg 0x%02X, value 0x%02X)\n", MAX_RETRIES, reg, value);
    return -1; // Failure
}

// I2C read function with retry
int i2c_read_reg(int fd, uint8_t reg, uint8_t *value) {
    int retries = 0;
    int result;

    while (retries < MAX_RETRIES) {
        result = i2c_smbus_read_byte_data(fd, reg);
        if (result >= 0) {
            *value = (uint8_t)result;
            return 0; // Success
        } else {
            fprintf(stderr, "I2C read error (reg 0x%02X): %s (attempt %d/%d)\n", reg, strerror(errno), retries + 1, MAX_RETRIES);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "I2C read failed after %d retries (reg 0x%02X)\n", MAX_RETRIES, reg);
    return -1; // Failure
}

// D7S initialization function
int d7s_init(int fd) {
    // Reset the sensor
    if (i2c_write_reg(fd, 0x00, 0x80) != 0) {
        fprintf(stderr, "Failed to reset D7S\n");
        return -1;
    }
    gpioDelay(100000); // Wait 100ms

    // Configure the sensor for continuous mode
    if (d7s_set_mode(fd, 0x01) != 0) {
        fprintf(stderr, "Failed to set D7S mode\n");
        return -1;
    }

    return 0;
}

// D7S set mode function
int d7s_set_mode(int fd, uint8_t mode) {
    if (i2c_write_reg(fd, 0x02, mode) != 0) {
        fprintf(stderr, "Failed to set D7S mode\n");
        return -1;
    }
    return 0;
}

// D7S read acceleration function
int d7s_read_acceleration(int fd, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (i2c_read_reg(fd, 0x04, &data[0]) != 0) return -1; // X-axis LSB
    if (i2c_read_reg(fd, 0x05, &data[1]) != 0) return -1; // X-axis MSB
    if (i2c_read_reg(fd, 0x06, &data[2]) != 0) return -1; // Y-axis LSB
    if (i2c_read_reg(fd, 0x07, &data[3]) != 0) return -1; // Y-axis MSB
    if (i2c_read_reg(fd, 0x08, &data[4]) != 0) return -1; // Z-axis LSB
    if (i2c_read_reg(fd, 0x09, &data[5]) != 0) return -1; // Z-axis MSB

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// D7S get status function
int d7s_get_status(int fd) {
    uint8_t status;

    if (i2c_read_reg(fd, 0x03, &status) != 0) {
        fprintf(stderr, "Failed to read D7S status\n");
        return -1;
    }

    return status;
}

// Check sensor status function
int check_sensor_status(int status) {
    // Check if the sensor is ready (bit 0 of status is set)
    return (status & 0x01) ? 1 : 0;
}

// Log data to CSV file function
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to CSV file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int16_t x, y, z;
    int status;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_SDA, PI_OUTPUT);
    gpioSetMode(GPIO_SCL, PI_OUTPUT);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize D7S sensor
    if (d7s_init(i2c_fd) != 0) {
        fprintf(stderr, "D7S initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen("fan_health.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor status
        retries = 0;
        while (retries < MAX_RETRIES) {
            status = d7s_get_status(i2c_fd);
            if (status >= 0) {
                break; // Success
            } else {
                fprintf(stderr, "Failed to read sensor status, retrying... (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }

        if (status < 0) {
            fprintf(stderr, "Failed to read sensor status after %d retries\n", MAX_RETRIES);
            gpioDelay(ONE_SECOND_MS * 1000); // Wait before retrying
            continue;
        }

        // Check sensor status
        if (!check_sensor_status(status)) {
            fprintf(stderr, "Sensor not ready, waiting for 1 second...\n");
            gpioDelay(ONE_SECOND_MS * 1000); // Wait 1 second
            continue;
        }

        // Read acceleration data
        if (d7s_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Log data to CSV file
            if (log_data(csv_file, x, y, z) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for sample rate
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();

    return 0;
}

