int d7s_get_status(int fd) {
    uint8_t status;

    if (i2c_read_reg(fd, 0x03, &status) != 0) {
        fprintf(stderr, "Failed to read D7S status\n");
        return -1;
    }

    return status;
}

// Check sensor status function
int check_sensor_status(int status) {
    // Check if the sensor is ready (bit 0 of status is set)
    return (status & 0x01) ? 1 : 0;
}

// Log data to CSV file function
int log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (fprintf(fp, "%s,%d,%d,%d\n", timestamp, x, y, z) < 0) {
        fprintf(stderr, "Failed to write to CSV file\n");
        return -1;
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler function
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

int main() {
    int16_t x, y, z;
    int status;
    int retries;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(GPIO_SDA, PI_OUTPUT);
    gpioSetMode(GPIO_SCL, PI_OUTPUT);

    // Open I2C device
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, D7S_ADDR) < 0) {
        fprintf(stderr, "Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Initialize D7S sensor
    if (d7s_init(i2c_fd) != 0) {
        fprintf(stderr, "D7S initialization failed\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Open CSV file for appending
    csv_file = fopen("fan_health.csv", "a");
    if (csv_file == NULL) {
        fprintf(stderr, "Failed to open CSV file: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Check if the file is newly created and write the header if needed
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "Timestamp,X,Y,Z\n");
    }
    rewind(csv_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor status
        retries = 0;
        while (retries < MAX_RETRIES) {
            status = d7s_get_status(i2c_fd);
            if (status >= 0) {
                break; // Success
            } else {
                fprintf(stderr, "Failed to read sensor status, retrying... (attempt %d/%d)\n", retries + 1, MAX_RETRIES);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retries++;
            }
        }

        if (status < 0) {
            fprintf(stderr, "Failed to read sensor status after %d retries\n", MAX_RETRIES);
            gpioDelay(ONE_SECOND_MS * 1000); // Wait before retrying
            continue;
        }

        // Check sensor status
        if (!check_sensor_status(status)) {
            fprintf(stderr, "Sensor not ready, waiting for 1 second...\n");
            gpioDelay(ONE_SECOND_MS * 1000); // Wait 1 second
            continue;
        }

        // Read acceleration data
        if (d7s_read_acceleration(i2c_fd, &x, &y, &z) == 0) {
            // Log data to CSV file
            if (log_data(csv_file, x, y, z) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for sample rate
    }

    // Cleanup
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();

    return 0;
}

