#define LOG_FILE "stall_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int pin);
int is_stall_confirmed(int sensor1_value, int sensor2_value);
void log_stall(const char *timestamp);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int pin;
    int value;
} sensor_t;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);

    return 0; // Indicate success
}

// Function to read the value from a sensor
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to check if the stall is confirmed
int is_stall_confirmed(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 0 && sensor2_value == 0);
}

// Function to log the stall event to a file
void log_stall(const char *timestamp) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        return;
    }

    fprintf(fp, "%s\n", timestamp);
    fclose(fp);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    printf("Conveyor belt monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Validate sensor readings
        if (sensor1_value != 0 && sensor1_value != 1) {
            fprintf(stderr, "Error: Invalid sensor 1 value: %d\n", sensor1_value);
        }
        if (sensor2_value != 0 && sensor2_value != 1) {
            fprintf(stderr, "Error: Invalid sensor 2 value: %d\n", sensor2_value);
        }

        // Check for stall confirmation
        if (is_stall_confirmed(sensor1_value, sensor2_value)) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the stall event
            log_stall(timestamp);

            printf("Stall confirmed at %s\n", timestamp);
        }

        // Delay to avoid excessive CPU usage
        gpioDelay(100); // 100 milliseconds
    }

    // Terminate pigpio library before exiting
    gpioTerminate();

    printf("Conveyor belt monitoring stopped.\n");

    return 0;
}

