#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// TMAG5170 I2C address
#define TMAG5170_ADDR 0x0E

// TMAG5170 register addresses
#define TMAG5170_REG_X_MSB 0x00
#define TMAG5170_REG_X_LSB 0x01
#define TMAG5170_REG_Y_MSB 0x02
#define TMAG5170_REG_Y_LSB 0x03
#define TMAG5170_REG_Z_MSB 0x04
#define TMAG5170_REG_Z_LSB 0x05
#define TMAG5170_REG_CONFIG 0x06
#define TMAG5170_REG_STATUS 0x07

// Configuration values
#define CONFIG_CONTINUOUS 0x03 // Continuous conversion mode
#define CONFIG_RANGE_50MT 0x00  // 50 mT range
#define CONFIG_AXIS_ALL 0x07    // Enable all axes

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function prototypes
int init_sensor();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the TMAG5170 sensor
int init_sensor() {
    // Configure the sensor for continuous conversion mode
    char config_data[2];
    config_data[0] = TMAG5170_REG_CONFIG;
    config_data[1] = CONFIG_CONTINUOUS | (CONFIG_RANGE_50MT << 2) | CONFIG_AXIS_ALL;

    int result = i2cWriteDevice(i2c_handle, config_data, 2);
    if (result != 0) {
        fprintf(stderr, "Error writing to config register: %d\n", result);
        return -1;
    }

    // Verify configuration by reading back the register
    char read_config[2];
    read_config[0] = TMAG5170_REG_CONFIG;
    result = i2cWriteDevice(i2c_handle, read_config, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to read config register: %d\n", result);
        return -1;
    }

    result = i2cReadDevice(i2c_handle, read_config, 1);
    if (result != 0) {
        fprintf(stderr, "Error reading from config register: %d\n", result);
        return -1;
    }

    if (read_config[0] != config_data[1]) {
        fprintf(stderr, "Error: Config written to sensor does not match read back.\n");
        return -1;
    }

    return 0;
}

// Read magnetic field data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];

    // Read X, Y, and Z data in one go
    int result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        data.x = 0; // Set to 0 to avoid further issues
        data.y = 0;
        data.z = 0;
        return data;
    }

    // Combine MSB and LSB for each axis
    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Log data to a CSV file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

