        fprintf(stderr, "Error reading from config register: %d\n", result);
        return -1;
    }

    if (read_config[0] != config_data[1]) {
        fprintf(stderr, "Error: Config written to sensor does not match read back.\n");
        return -1;
    }

    return 0;
}

// Read magnetic field data from the sensor
sensor_data_t read_sensor_data() {
    sensor_data_t data;
    char buffer[6];

    // Read X, Y, and Z data in one go
    int result = i2cReadDevice(i2c_handle, buffer, 6);
    if (result != 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        data.x = 0; // Set to 0 to avoid further issues
        data.y = 0;
        data.z = 0;
        return data;
    }

    // Combine MSB and LSB for each axis
    data.x = (int16_t)((buffer[0] << 8) | buffer[1]);
    data.y = (int16_t)((buffer[2] << 8) | buffer[3]);
    data.z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return data;
}

// Log data to a CSV file
void log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%d,%d,%d\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    fprintf(stderr, "Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, TMAG5170_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        cleanup();
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen("magnetic_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Check if the file is empty, if so, write the header
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        sensor_data_t data = read_sensor_data();
        log_data(data);
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

