#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

#define GPIO_PIN 23
#define LOG_FILE "flood_log.txt"
#define REINIT_DELAY 60 // seconds

static volatile int running = 1;
static FILE *log_file = NULL;

// Function to handle signals (SIGINT, SIGTERM)
void signal_handler(int signal) {
    running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the pigpio library
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

// Function to read the water level sensor
int read_water_level() {
    return gpioRead(GPIO_PIN);
}

// Function to generate an alert message
void generate_alert() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s ALERT: Water detected\n", timestamp);
    fflush(log_file); // Ensure the log is written immediately
    printf("%s ALERT: Water detected\n", timestamp);
}

// Function to log an error message
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s ERROR: %s\n", timestamp, message);
    fflush(log_file);
    fprintf(stderr, "%s ERROR: %s\n", timestamp, message);
}

// Function to re-initialize the pigpio library
int reinitialize_gpio() {
    log_error("Re-initializing pigpio...");
    if (gpioInitialise() < 0) {
        log_error("pigpio re-initialisation failed");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_DOWN); // Use pull-down resistor

    return 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        return 1;
    }

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        fclose(log_file);
        return 1;
    }

    time_t last_reinit = time(NULL);

    printf("Water level monitoring started. Press Ctrl+C to exit.\n");

    while (running) {
        int water_level = read_water_level();

        if (water_level == 1) {
            generate_alert();
        }

        // Check for re-initialization attempts every REINIT_DELAY seconds
        time_t current_time = time(NULL);
        if (difftime(current_time, last_reinit) >= REINIT_DELAY) {
            if (reinitialize_gpio() != 0) {
                log_error("Failed to re-initialize GPIO. Retrying in 60 seconds.");
            } else {
                printf("GPIO re-initialized successfully.\n");
                last_reinit = current_time;
            }
        }

        sleep(2);
    }

    // Cleanup
    gpioTerminate();
    fclose(log_file);

    printf("Water level monitoring stopped.\n");

    return 0;
}

