#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pin connected to the MLX90217 sensor
#define SENSOR_PIN 4

// Define the log file name
#define LOG_FILE "rpm_log.txt"

// Define the one-second window duration in milliseconds
#define WINDOW_DURATION 1000

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_rpm(int pulse_count, int window_duration_ms);
void log_rpm(double rpm);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int sensor_pin;
    char *log_file_name;
    int window_duration_ms;
} ProgramState;

ProgramState state = {SENSOR_PIN, LOG_FILE, WINDOW_DURATION};

// Callback function for rising edge detection
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    (void)gpio; // unused
    (void)level; // unused
    (void)tick; // unused
    (void)user_data; // unused
    pulse_count++;
}

// Function to calculate RPM
double calculate_rpm(int pulse_count, int window_duration_ms) {
    if (pulse_count == 0) {
        return 0.0;
    }
    return (double)pulse_count * 60000.0 / (double)window_duration_ms;
}

// Function to log RPM to file
void log_rpm(double rpm) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s %lf\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
        printf("%s %lf\n", timestamp, rpm); // Also print to stdout
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    (void)signal; // unused
    running = 0;
    printf("Caught signal, exiting gracefully...\n");
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pin as input with pull-up resistor
    gpioSetMode(state.sensor_pin, PI_INPUT);
    gpioSetPullUpDown(state.sensor_pin, PI_PUD_UP);

    // Open log file
    log_file = fopen(state.log_file_name, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", state.log_file_name);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up interrupt callback function
    if (gpioSetISRFuncEx(state.sensor_pin, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Error setting up interrupt callback\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Wait for one second
        gpioDelay(state.window_duration_ms * 1000); // pigpioDelay takes microseconds

        // Calculate RPM
        double rpm = calculate_rpm(pulse_count, state.window_duration_ms);

        // Log RPM
        log_rpm(rpm);

        // Reset pulse count
        pulse_count = 0;
    }

    // Disable interrupt callback
    gpioSetISRFuncEx(state.sensor_pin, RISING_EDGE, 0, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    printf("RPM monitoring stopped.\n");

    return 0;
}

