#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pthread.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR_A_GPIO 17
#define SENSOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "rotation_log.txt"

// Define the number of sensors
#define NUM_SENSORS 2

// Define the number of quadrature states
#define NUM_QUADRATURE_STATES 4

// Define the rotation direction enum
enum RotationDirection {
    CLOCKWISE,
    COUNTER_CLOCKWISE,
    UNKNOWN
};

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int quadrature_state;
    enum RotationDirection direction;
    pthread_mutex_t mutex;
} sensor_data_t;

// Global variables
sensor_data_t sensors[NUM_SENSORS];
FILE *log_file = NULL;
pthread_mutex_t log_mutex;
pthread_cond_t log_cond;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int initialize_sensors();
void cleanup_gpio();
void cleanup_sensors();
void cleanup_resources();
void log_rotation_event(int sensor_id, enum RotationDirection direction);
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data);
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data);
void signal_handler(int signal);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_A_GPIO, PI_INPUT);
    gpioSetMode(SENSOR_B_GPIO, PI_INPUT);

    gpioSetPullUpDown(SENSOR_A_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR_B_GPIO, PI_PUD_UP);

    return 0;
}

// Function to initialize the sensors
int initialize_sensors() {
    for (int i = 0; i < NUM_SENSORS; i++) {
        sensors[i].gpio_pin = (i == 0) ? SENSOR_A_GPIO : SENSOR_B_GPIO;
        sensors[i].quadrature_state = 0;
        sensors[i].direction = UNKNOWN;
        pthread_mutex_init(&sensors[i].mutex, NULL);
    }

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
}

// Function to cleanup the sensors
void cleanup_sensors() {
    for (int i = 0; i < NUM_SENSORS; i++) {
        pthread_mutex_destroy(&sensors[i].mutex);
    }
}

// Function to cleanup resources
void cleanup_resources() {
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&log_mutex);
    pthread_cond_destroy(&log_cond);
}

// Function to log rotation events
void log_rotation_event(int sensor_id, enum RotationDirection direction) {
    pthread_mutex_lock(&log_mutex);
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s.%03ld - Sensor %d: %s\n", timestamp, gpioTick() % 1000, sensor_id,
            (direction == CLOCKWISE) ? "Clockwise" : "Counter-Clockwise");
    fflush(log_file); // Ensure the log is written immediately
    pthread_mutex_unlock(&log_mutex);
    pthread_cond_signal(&log_cond);
}

// Interrupt service routine for Sensor A
void sensor_a_isr(int gpio, int level, uint32_t tick, void *user_data) {
    sensor_data_t *sensor = (sensor_data_t *)user_data;
    int new_quadrature_state;

    pthread_mutex_lock(&sensor->mutex);

    if (level == 0) { // Falling edge
        new_quadrature_state = (sensor->quadrature_state + 1) % NUM_QUADRATURE_STATES;
    } else { // Rising edge
        new_quadrature_state = (sensor->quadrature_state + 3) % NUM_QUADRATURE_STATES;
    }

    if (new_quadrature_state == 0) {
        sensor->direction = CLOCKWISE;
    } else if (new_quadrature_state == 1) {
        sensor->direction = UNKNOWN;
    } else if (new_quadrature_state == 2) {
        sensor->direction = COUNTER_CLOCKWISE;
    } else {
        sensor->direction = UNKNOWN;
    }

    sensor->quadrature_state = new_quadrature_state;

    pthread_mutex_unlock(&sensor->mutex);

    log_rotation_event(0, sensor->direction);
}

// Interrupt service routine for Sensor B
void sensor_b_isr(int gpio, int level, uint32_t tick, void *user_data) {
    sensor_data_t *sensor = (sensor_data_t *)user_data;
    int new_quadrature_state;

    pthread_mutex_lock(&sensor->mutex);

    if (level == 0) { // Falling edge
        new_quadrature_state = (sensor->quadrature_state + 3) % NUM_QUADRATURE_STATES;
    } else { // Rising edge
        new_quadrature_state = (sensor->quadrature_state + 1) % NUM_QUADRATURE_STATES;
    }

    if (new_quadrature_state == 0) {
        sensor->direction = COUNTER_CLOCKWISE;
    } else if (new_quadrature_state == 1) {
        sensor->direction = UNKNOWN;
    } else if (new_quadrature_state == 2) {
        sensor->direction = CLOCKWISE;
    } else {
        sensor->direction = UNKNOWN;
    }

    sensor->quadrature_state = new_quadrature_state;

    pthread_mutex_unlock(&sensor->mutex);

    log_rotation_event(1, sensor->direction);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize sensors
    if (initialize_sensors() != 0) {
        cleanup_gpio();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_resources();
        return 1;
    }

    // Initialize mutex and condition variable
    if (pthread_mutex_init(&log_mutex, NULL) != 0 ||
        pthread_cond_init(&log_cond, NULL) != 0) {
        fprintf(stderr, "Mutex or condition variable initialization failed!\n");
        cleanup_resources();
        return 1;
    }

    // Set up interrupt handlers for each sensor
    gpioSetISRFuncEx(SENSOR_A_GPIO, FALLING_EDGE, 0, sensor_a_isr, &sensors[0]);
    gpioSetISRFuncEx(SENSOR_B_GPIO, FALLING_EDGE, 0, sensor_b_isr, &sensors[1]);

