#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 18

// Define SPI device
#define SPI_DEVICE "/dev/spidev0.0"

// Define SPI parameters
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz

// Define ADC parameters
#define ADC_CHANNEL 0
#define ADC_RESOLUTION 10 // 10-bit ADC

// Define touch threshold
#define TOUCH_THRESHOLD 500

// Global variables
int spi_fd;
int running = 1;

// Function prototypes
int gpio_init();
int spi_init();
int read_touch_sensor();
int read_adc(int channel);
int control_led(int state);
void log_event(const char *message);
void signal_handler(int signal);

// Function to initialize GPIO
int gpio_init() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to initialize SPI
int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device: %s", SPI_DEVICE);
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        syslog(LOG_ERR, "Failed to set SPI mode: %s", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        syslog(LOG_ERR, "Failed to set bits per word: %s", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        syslog(LOG_ERR, "Failed to set SPI speed: %s", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read the touch sensor value
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to read the ADC value from MCP3008
int read_adc(int channel) {
    uint8_t tx_buf[3];
    uint8_t rx_buf[3];

    // Construct SPI message
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = (0x08 | channel) << 4; // Single-ended mode, channel select
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    // Extract ADC value
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];

    return adc_value;
}

// Function to control the LED
int control_led(int state) {
    gpioWrite(LED_PIN, state);
    return 0;
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

int main() {
    // Open syslog
    openlog("touch_sensor_led", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    if (gpio_init() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed, exiting");
        closelog();
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        syslog(LOG_ERR, "SPI initialization failed, exiting");
        gpioTerminate();
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("Touch sensor and LED control program started");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor();
        int adc_value = read_adc(ADC_CHANNEL);

        if (touch_detected == 1) {
            if (adc_value > TOUCH_THRESHOLD) {
                control_led(1); // Turn LED on
                log_event("Touch detected and LED turned on");
            } else {
                control_led(0); // Turn LED off
                log_event("Touch detected, but ADC value below threshold");
            }
        } else {
            control_led(0); // Turn LED off
            log_event("No touch detected");
        }

        gpioDelay(50); // Delay for 50ms
    }

    // Cleanup
    control_led(0); // Turn LED off
    close(spi_fd);
    gpioTerminate();
    closelog();

    return 0;
}

