#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 17
#define LED_PIN 18

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO chip
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Function to request a GPIO line for input
int request_touch_sensor_line() {
    if (gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as input\n", TOUCH_SENSOR_PIN);
        return -1;
    }
    return 0;
}

// Function to request a GPIO line for output
int request_led_line() {
    if (gpioSetMode(LED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO%d as output\n", LED_PIN);
        return -1;
    }
    gpioWrite(LED_PIN, 0); // Ensure LED is initially off
    return 0;
}

// Function to wait for a rising edge on the touch sensor line
int wait_for_touch() {
    int rising_edge_count = 0;
    int last_state = gpioRead(TOUCH_SENSOR_PIN);
    struct timespec sleep_time;
    sleep_time.tv_sec = 0;
    sleep_time.tv_nsec = 1000000; // 1 millisecond

    while (program_running) {
        int current_state = gpioRead(TOUCH_SENSOR_PIN);

        if (current_state == 1 && last_state == 0) {
            rising_edge_count++;
            nanosleep(&sleep_time, NULL); // Debounce
        }

        last_state = current_state;

        if (rising_edge_count > 1) {
            return 1; // Multiple rising edges detected
        }
    }
    return 0; // Timeout or program termination
}

// Function to toggle the LED state
int toggle_led() {
    int current_state = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_state);
    return 0;
}

// Function to release GPIO resources
void release_gpio() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Request GPIO lines
    if (request_touch_sensor_line() != 0 || request_led_line() != 0) {
        release_gpio();
        return 1;
    }

    fprintf(stderr, "Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        if (wait_for_touch()) {
            toggle_led();
            fprintf(stderr, "Touch detected! LED toggled.\n");
        } else {
            //fprintf(stderr, "No touch detected.\n"); // Removed for brevity
        }
    }

    // Release GPIO resources before exiting
    release_gpio();

    fprintf(stderr, "Program terminated.\n");
    return 0;
}

