// Structure to store sensor data
typedef struct {
    int pin;
    time_t timestamp;
    int state;
} SensorData;

// Circular buffer
SensorData log_buffer[BUFFER_SIZE];
int buffer_index = 0;
int overflow_count = 0;

// Function prototypes
int read_sensor(int pin);
void control_led(int pin, int state);
void log_event(int pin, int state);
void print_log_buffer();
void signal_handler(int signal);

// Function to read sensor value with debouncing
int read_sensor(int pin) {
    int value = gpioRead(pin);
    gpioDelay(50000); // 50ms delay
    return value;
}

// Function to control LED state
void control_led(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to log sensor event to circular buffer
void log_event(int pin, int state) {
    time_t now = time(NULL);
    if (now == (time_t)-1) {
        perror("time");
        return;
    }

    log_buffer[buffer_index].pin = pin;
    log_buffer[buffer_index].timestamp = now;
    log_buffer[buffer_index].state = state;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    if (buffer_index == 0) {
        overflow_count++;
    }
}

// Function to print the log buffer
void print_log_buffer() {
    printf("\n--- Log Buffer ---\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
