            strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", tm_info);
            printf("Pin: %d, Timestamp: %s, State: %d\n", log_buffer[index].pin, timestamp_str, log_buffer[index].state);
        }
