    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(LED_1_PIN, PI_OUTPUT);
    gpioSetMode(LED_2_PIN, PI_OUTPUT);

    // Initialize LEDs to off state
    control_led(LED_1_PIN, 0);
    control_led(LED_2_PIN, 0);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);

        // Control LEDs based on sensor values
        if (sensor1_value == 1) {
            control_led(LED_1_PIN, 1);
            log_event(SENSOR_1_PIN, 1);
        } else {
            control_led(LED_1_PIN, 0);
        }

        if (sensor2_value == 1) {
            control_led(LED_2_PIN, 1);
            log_event(SENSOR_2_PIN, 1);
        } else {
            control_led(LED_2_PIN, 0);
        }

        // Print log buffer every 5 seconds
        time_t now = time(NULL);
        if (now % 5 == 0) {
            print_log_buffer();
        }

        gpioDelay(100000); // 100ms delay
    }

    return 0;
}

