#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>
#include <sys/types.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define SENSOR1_GPIO 17
#define SENSOR2_GPIO 18

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 5

// Define the log file name
#define LOG_FILE "shaft_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static int sensor1_last_state = 0;
static int sensor2_last_state = 0;
static struct timespec last_tick1, last_tick2;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio);
void log_data(int sensor1_state, int sensor2_state);
double calculate_rpm(int sensor1_state, int sensor2_state);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int gpio;
    int last_state;
    struct timespec last_tick;
} sensor_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR1_GPIO, PI_INPUT);
    gpioSetMode(SENSOR2_GPIO, PI_INPUT);

    // Set pull-up/down resistors (optional, depending on sensor wiring)
    gpioSetPullUpDown(SENSOR1_GPIO, PI_PUD_UP);
    gpioSetPullUpDown(SENSOR2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio) {
    return gpioRead(gpio);
}

// Function to log data to a CSV file
void log_data(int sensor1_state, int sensor2_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s,%d,%d\n", timestamp, sensor1_state, sensor2_state);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Function to calculate RPM
double calculate_rpm(int sensor1_state, int sensor2_state) {
    struct timespec current_tick;
    double time_diff;
    double rpm;

    clock_gettime(CLOCK_MONOTONIC, &current_tick);

    time_diff = (current_tick.tv_sec - last_tick1.tv_sec) + (current_tick.tv_nsec - last_tick1.tv_nsec) / 1000000000.0;

    if (time_diff > 0) {
        rpm = 60.0 / time_diff;
    } else {
        rpm = 0.0;
    }

    last_tick1 = current_tick;

    return rpm;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioTerminate();
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Initialize sensor data
    sensor1_last_state = read_sensor(SENSOR1_GPIO);
    sensor2_last_state = read_sensor(SENSOR2_GPIO);
    clock_gettime(CLOCK_MONOTONIC, &last_tick1);
    clock_gettime(CLOCK_MONOTONIC, &last_tick2);

    printf("RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor1_state = read_sensor(SENSOR1_GPIO);
        int sensor2_state = read_sensor(SENSOR2_GPIO);

        // Debounce sensor 1
        if (sensor1_state != sensor1_last_state) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            if ((now.tv_sec - last_tick1.tv_sec) * 1000000 + (now.tv_nsec - last_tick1.tv_nsec) / 1000 > DEBOUNCE_TIME * 1000) {
                log_data(sensor1_state, sensor2_state);
                printf("Sensor 1 RPM: %.2f\n", calculate_rpm(sensor1_state, sensor2_state));
                sensor1_last_state = sensor1_state;
                last_tick1 = now;
            }
        }

        // Debounce sensor 2
        if (sensor2_state != sensor2_last_state) {
            struct timespec now;
            clock_gettime(CLOCK_MONOTONIC, &now);
            if ((now.tv_sec - last_tick2.tv_sec) * 1000000 + (now.tv_nsec - last_tick2.tv_nsec) / 1000 > DEBOUNCE_TIME * 1000) {
                log_data(sensor1_state, sensor2_state);
                printf("Sensor 2 RPM: %.2f\n", calculate_rpm(sensor1_state, sensor2_state));
                sensor2_last_state = sensor2_state;
                last_tick2 = now;
            }
        }

        gpioDelay(10); // Small delay to prevent busy-waiting
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

