#define REG_MEAS_RATE1 0x09
#define REG_ALS_RATE0 0x0A
#define REG_ALS_RATE1 0x0B
#define REG_PS_RATE0 0x0C
#define REG_PS_RATE1 0x0D
#define REG_COMMAND 0x30

