    int heart_rate;
    int spo2;
} sensor_data_t;

// Function prototypes
int init_si1182();
sensor_data_t read_sensor_data();
void log_data(sensor_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the Si1182 sensor
int init_si1182() {
    // Reset the sensor (example - adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, REG_COMMAND, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1182\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure sensor (example - adjust based on datasheet)
    if (i2cWriteByteData(i2c_handle, REG_MEAS_RATE0, 0x0A) < 0) { // Example: Set measurement rate
        fprintf(stderr, "Error: Failed to set measurement rate\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, REG_ALS_RATE0, 0x0A) < 0) { // Example: Set ALS rate
