    if (i2cReadI2CBlockData(i2c_handle, REG_ALS_VIS_DATA0, (char *)buffer, 6) < 0) {
        fprintf(stderr, "Error: Failed to read ALS data\n");
        data.heart_rate = -1; // Indicate error
        data.spo2 = -1;
        return data;
    }

