#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18
#define ALARM_GPIO 27

// Define alarm duration (in seconds)
#define ALARM_DURATION 2

// Define log file name
#define LOG_FILE "bridge_integrity.log"

// Global variables
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
int log_event(const char *event_type);
int check_alarm_condition(int sensor1_value, int sensor2_value);
void activate_alarm();
void deactivate_alarm();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int sensor1_value;
    int sensor2_value;
} sensor_data_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_DOWN);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_DOWN);
    gpioSetMode(ALARM_GPIO, PI_OUTPUT);
    gpioWrite(ALARM_GPIO, 0); // Ensure alarm is initially off

    return 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log events to file
int log_event(const char *event_type) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s: %s\n", timestamp, event_type);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to check alarm condition
int check_alarm_condition(int sensor1_value, int sensor2_value) {
    return (sensor1_value == 1 && sensor2_value == 1);
}

// Function to activate the alarm
void activate_alarm() {
    gpioWrite(ALARM_GPIO, 1); // Set alarm GPIO HIGH
    printf("Alarm activated\n");
}

// Function to deactivate the alarm
void deactivate_alarm() {
    gpioWrite(ALARM_GPIO, 0); // Set alarm GPIO LOW
    printf("Alarm deactivated\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    program_running = 0;
}

// Cleanup function to release resources
void cleanup() {
    deactivate_alarm();
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Bridge integrity monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        sensor_data_t sensor_data;
        sensor_data.sensor1_value = read_sensor(SENSOR_1_GPIO);
        sensor_data.sensor2_value = read_sensor(SENSOR_2_GPIO);

        if (sensor_data.sensor1_value == -1 || sensor_data.sensor2_value == -1) {
            fprintf(stderr, "Error reading sensor values\n");
            // Attempt to recover by retrying
            gpioDelay(100); // Small delay before retrying
            continue;
        }

        if (check_alarm_condition(sensor_data.sensor1_value, sensor_data.sensor2_value)) {
            if (log_event("Tilt start") != 0) {
                fprintf(stderr, "Error logging tilt start event\n");
            }
            activate_alarm();
        } else {
            if (log_event("Tilt end") != 0) {
                fprintf(stderr, "Error logging tilt end event\n");
            }
            deactivate_alarm();
        }

        gpioDelay(100); // Poll every 100ms
    }

    // Cleanup and exit
    cleanup();
    printf("Bridge integrity monitoring stopped.\n");
    return 0;
}

