#include <math.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define D7S_ADDR 0x4C
#define CTRL1 0x20
#define CTRL2 0x21
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define LED_GPIO 17
#define THRESHOLD 500.0
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_sensor();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void log_event(float magnitude);
void trigger_alert(int gpio, int duration_ms);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to initialize the sensor
int init_sensor() {
    // Verify sensor presence by reading CTRL1 register
    int status = i2cReadByteData(i2c_handle, CTRL1);
    if (status < 0) {
        fprintf(stderr, "Error reading CTRL1 register: %d\n", status);
        return -1;
    }

    // Clear power-down bit (bit 0 of CTRL1)
    status = i2cWriteByteData(i2c_handle, CTRL1, status & 0x7F);
    if (status < 0) {
        fprintf(stderr, "Error writing to CTRL1 register: %d\n", status);
        return -1;
    }

    // Set data rate to 100 Hz (adjust CTRL2 as needed)
