#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_1_PIN 4
#define SENSOR_2_PIN 17
#define SENSOR_3_PIN 27
#define SENSOR_4_PIN 22
#define LED_PIN 18

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read sensor data
int read_sensor(int pin) {
    return gpioRead(pin);
}

// Function to control the LED
void control_led(int state) {
    gpioWrite(LED_PIN, state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(SENSOR_3_PIN, PI_INPUT);
    gpioSetMode(SENSOR_4_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Obstacle detection program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor data
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);
        int sensor3_value = read_sensor(SENSOR_3_PIN);
        int sensor4_value = read_sensor(SENSOR_4_PIN);

        // Check for errors during sensor reading
        if (sensor1_value < 0 || sensor2_value < 0 || sensor3_value < 0 || sensor4_value < 0) {
            fprintf(stderr, "Error reading sensor data\n");
            break; // Exit loop on error
        }

        // Check if any sensor detects an object (active‑low)
        int any_object_detected = (sensor1_value == 0 || sensor2_value == 0 || sensor3_value == 0 || sensor4_value == 0);

        // Control the LED
        control_led(any_object_detected);

        // Delay for 50 milliseconds
        gpioDelay(50000); // 50000 microseconds = 50 milliseconds
    }

    // Clean up GPIO resources
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

