static int chip_fd = -1;

// Function prototypes
int initialize_gpio(void);
int open_gpio_chip(void);
int request_gpio_line(int pin);
int read_gpio_line(int line_fd);
int confirm_flame_transition(int line_fd, int pin);
int log_flame_event(int sensor_id, int pin);
void signal_handler(int sig);
void cleanup(void);

// Signal handler function
void signal_handler(int sig) {
    syslog(LOG_INFO, "Signal received, terminating...");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup(void) {
    syslog(LOG_INFO, "Cleaning up...");

    // Release GPIO lines
    for (int i = 0; i < 5; i++) {
        if (sensors[i].line_fd != -1) {
            close(sensors[i].line_fd);
            sensors[i].line_fd = -1;
        }
    }

    // Close GPIO chip
    if (chip_fd != -1) {
        gpiod_chip_close(chip_fd);
        chip_fd = -1;
    }

    // Close syslog
    closelog();
}

// Initialize GPIO pins
int initialize_gpio(void) {
    // Open syslog
    openlog("flame_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize sensors
    sensors[0].pin = SENSOR_1_PIN;
    sensors[0].sensor_id = 1;
    sensors[1].pin = SENSOR_2_PIN;
    sensors[1].sensor_id = 2;
    sensors[2].pin = SENSOR_3_PIN;
    sensors[2].sensor_id = 3;
    sensors[3].pin = SENSOR_4_PIN;
    sensors[3].sensor_id = 4;
    sensors[4].pin = SENSOR_5_PIN;
    sensors[4].sensor_id = 5;

    // Initialize last change times
    for (int i = 0; i < 5; i++) {
        gettimeofday(&sensors[i].last_change_time, NULL);
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        syslog(LOG_ERR, "GPIO initialization failed");
        return -1;
    }

    syslog(LOG_INFO, "GPIO initialized successfully");
    return 0;
}

// Initialize GPIO chip
int open_gpio_chip(void) {
    chip_fd = gpiod_chip_open_by_name("gpiochip0");
    if (!chip_fd) {
        syslog(LOG_ERR, "Failed to open GPIO chip: %s", strerror(errno));
        return -1;
    }
    return 0;
}

// Request GPIO line
int request_gpio_line(int pin) {
    struct gpiod_line *line;
    struct gpiod_line_request_config config;

    line = gpiod_chip_get_line(chip_fd, pin);
    if (!line) {
        syslog(LOG_ERR, "Failed to get GPIO line %d: %s", pin, strerror(errno));
        return -1;
    }

    memset(&config, 0, sizeof(config));
    config.consumer = "flame_monitor";
    config.request_type = GPIOD_LINE_REQUEST_DIRECTION_INPUT;

    if (gpiod_line_request(line, &config, 0) < 0) {
        syslog(LOG_ERR, "Failed to request GPIO line %d: %s", pin, strerror(errno));
        gpiod_line_release(line);
        return -1;
    }

    return 0;
}

// Read GPIO line
int read_gpio_line(int line_fd) {
    char value_str[2];
    ssize_t bytes_read;

    lseek(line_fd, 0, SEEK_SET); // Rewind to the beginning of the line
    bytes_read = read(line_fd, value_str, 1);

    if (bytes_read < 0) {
        syslog(LOG_ERR, "Failed to read GPIO line: %s", strerror(errno));
        return -1;
    } else if (bytes_read == 0) {
        // Line is not ready yet
        return 0;
    }

    return (value_str[0] == '0') ? 0 : 1;
}

// Confirm flame transition
int confirm_flame_transition(int line_fd, int pin) {
    struct timeval current_time;
    gettimeofday(&current_time, NULL);

    // Check if the time difference is less than the debounce time
    long time_diff_ms = (current_time.tv_sec - sensors[pin - 2].last_change_time.tv_sec) * 1000 +
                       (current_time.tv_usec - sensors[pin - 2].last_change_time.tv_usec) / 1000;

    if (time_diff_ms < DEBOUNCE_TIME) {
        syslog(LOG_WARNING, "Flame transition detected, but debounce time (%ld ms) has not passed.", DEBOUNCE_TIME);
        return 0; // Debounce failed
    }

    // Read the line again to confirm the transition
    int new_value = read_gpio_line(line_fd);
    if (new_value < 0) {
        syslog(LOG_ERR, "Failed to re-read GPIO line after debounce");
        return 0; // Re-read failed
    }

    // Update the last change time
    sensors[pin - 2].last_change_time = current_time;

    return (new_value == 0) ? 1 : 0; // Transition confirmed
}

// Log flame event
int log_flame_event(int sensor_id, int pin) {
    FILE *fp;
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);

    // Format timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    // Open log file in append mode
    fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        syslog(LOG_ERR, "Failed to open log file: %s", strerror(errno));
        return -1;
    }

    // Acquire exclusive lock on the file
    if (flock(fileno(fp), LOCK_EX) == -1) {
        syslog(LOG_ERR, "Failed to acquire lock on log file: %s", strerror(errno));
        fclose(fp);
        return -1;
    }

    // Write log entry
    fprintf(fp, "%s - Sensor ID: %d (GPIO %d) - Flame Detected\n", timestamp, sensor_id, pin);

    // Flush the buffer to ensure data is written to the file
    fflush(fp);

    // Release lock on the file
    if (flock(fileno(fp), LOCK_UN) == -1) {
        syslog(LOG_ERR, "Failed to release lock on log file: %s", strerror(errno));
    }

    // Close log file
    fclose(fp);

    syslog(LOG_INFO, "Flame detected by sensor %d (GPIO %d) at %s", sensor_id, pin, timestamp);
    return 0;
}

int main(void) {
    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open GPIO chip
    if (open_gpio_chip() != 0) {
        cleanup();
        return 1;
    }

    // Request GPIO lines
    for (int i = 0; i < 5; i++) {
        if (request_gpio_line(sensors[i].pin) != 0) {
            cleanup();
            return 1;
        }

        // Open GPIO line for reading
        sensors[i].line_fd = open("/sys/class/gpio/gpio%d/value", O_RDONLY);
        if (sensors[i].line_fd < 0) {
            syslog(LOG_ERR, "Failed to open GPIO line %d: %s", sensors[i].pin, strerror(errno));
            cleanup();
            return 1;
        }
    }

    syslog(LOG_INFO, "Flame monitoring started");

    // Main loop
    while (!terminate) {
        for (int i = 0; i < 5; i++) {
            int value = read_gpio_line(sensors[i].line_fd);
            if (value < 0) {
                syslog(LOG_ERR, "Failed to read sensor %d", sensors[i].sensor_id);
                continue; // Skip to the next sensor
            }

            if (value == 0) {
                // Flame detected (LOW signal)
                if (confirm_flame_transition(sensors[i].line_fd, sensors[i].pin)) {
                    if (log_flame_event(sensors[i].sensor_id, sensors[i].pin) != 0) {
                        syslog(LOG_ERR, "Failed to log flame event for sensor %d", sensors[i].sensor_id);
                    }
                }
            }
        }

        usleep(1000000); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

