#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define the GPIO chip name
#define GPIOCHIP "gpiochip0"

// Define the GPIO pins connected to the TTP226 sensors
const int sensor_pins[] = {5, 6, 13, 19, 26, 12, 16, 20};
const int num_sensors = sizeof(sensor_pins) / sizeof(sensor_pins[0]);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to get the current timestamp in ISO 8601 format
void get_timestamp(char *timestamp) {
    time_t rawtime;
    struct tm *timeinfo;

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 30, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
}

// Function to read the state of a single sensor
int read_sensor(int pin) {
    struct gpiod_chip *chip;
    struct gpiod_line *line;
    int value;
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name(GPIOCHIP);
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get the GPIO line for the specified pin
    line = gpiod_chip_get_line(chip, pin);
    if (!line) {
        fprintf(stderr, "Error getting GPIO line for pin %d: %s\n", pin, strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Request the GPIO line for input
    ret = gpiod_line_request_input(line, "sensor_monitor");
    if (ret < 0) {
        fprintf(stderr, "Error requesting GPIO line for pin %d: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Read the value of the GPIO line
    value = gpiod_line_get_value(line);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO line for pin %d: %s\n", pin, strerror(errno));
        gpiod_line_release(line);
        gpiod_chip_close(chip);
        return -1;
    }

    // Release the GPIO line
    gpiod_line_release(line);

    // Close the GPIO chip
    gpiod_chip_close(chip);

    return value;
}

// Function to log the sensor state change to the console
void log_state_change(int sensor_index, int pin, int state) {
    char timestamp[30];
    get_timestamp(timestamp);

    printf("[%s] Sensor %d (Pin %d): %s\n", timestamp, sensor_index, pin, state ? "Touched" : "Released");
}

int main() {
    // Install signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Main loop to read and log sensor states
    while (program_running) {
        for (int i = 0; i < num_sensors; i++) {
            int current_state = read_sensor(sensor_pins[i]);
            if (current_state < 0) {
                fprintf(stderr, "Error reading sensor %d, exiting...\n", i);
                program_running = 0; // Exit loop if there's an error
                break;
            }

            // Check if the state has changed
            if (current_state != sensor_states[i]) {
                log_state_change(i, sensor_pins[i], current_state);
                sensor_states[i] = current_state;
            }
        }

        // Wait for 50 milliseconds
        usleep(50000); // 50000 microseconds = 50 milliseconds
    }

    return 0;
}

