#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define VEML7700_ADDR 0x48
#define GROW_LED_GPIO 18
#define PWM_FREQUENCY 1000
#define LOG_FILE "grow_log.txt"
#define SAMPLE_INTERVAL_SEC 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int configure_veml7700();
int read_veml7700_lux(float *lux);
int map_lux_to_brightness(float lux);
int set_led_brightness(int brightness);
int log_data(float lux, int brightness, int error_code);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, VEML7700_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Configure VEML7700 sensor
int configure_veml7700() {
    // Recommended settings from the datasheet
    if (i2cWriteByteData(i2c_handle, 0x00, 0x00) < 0) { // Integration time = 100ms
        fprintf(stderr, "Failed to write to VEML7700 (IT)\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x01, 0x00) < 0) { // Gain = 1/4
        fprintf(stderr, "Failed to write to VEML7700 (GAIN)\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, 0x02, 0x00) < 0) { // Power save mode
        fprintf(stderr, "Failed to write to VEML7700 (PSM)\n");
        return -1;
    }
    return 0;
}

// Read lux value from VEML7700 sensor
int read_veml7700_lux(float *lux) {
    uint16_t raw_data;

    raw_data = i2cReadWordData(i2c_handle, 0x04);
    if (raw_data < 0) {
        fprintf(stderr, "Failed to read lux data\n");
        return -1;
    }

    // Convert raw data to lux (example conversion, adjust based on datasheet)
    *lux = (float)raw_data * 0.0576; // Example conversion factor

    return 0;
}

// Map lux value to brightness level (0-100)
int map_lux_to_brightness(float lux) {
    if (lux < 100) {
        return 100;
    } else if (lux < 500) {
        return 75;
    } else if (lux < 1000) {
        return 50;
    } else {
        return 25;
    }
}

// Set LED brightness using hardware PWM
int set_led_brightness(int brightness) {
    if (brightness < 0 || brightness > 100) {
        fprintf(stderr, "Invalid brightness value: %d\n", brightness);
        return -1;
    }

    // Calculate duty cycle (0-255)
    int duty_cycle = (int)(((float)brightness / 100.0) * 255.0);

    gpioPWM(GROW_LED_GPIO, duty_cycle);
    return 0;
}

// Log data to file
int log_data(float lux, int brightness, int error_code) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s, %.2f, %d, %d\n", timestamp, lux, brightness, error_code);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    set_led_brightness(0); // Turn off LED
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Configure VEML7700 sensor
    if (configure_veml7700() != 0) {
        cleanup();
        return 1;
    }

    // Set GPIO18 as output for LED control
    gpioSetMode(GROW_LED_GPIO, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(GROW_LED_GPIO, PWM_FREQUENCY);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    float lux;
    int brightness;
    int error_code = 0;

    printf("Grow light system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        // Read lux value
        if (read_veml7700_lux(&lux) == 0) {
            // Map lux value to brightness
            brightness = map_lux_to_brightness(lux);

            // Set LED brightness
            if (set_led_brightness(brightness) != 0) {
                fprintf(stderr, "Failed to set LED brightness\n");
                error_code = -1; // Indicate error
            }
        } else {
            fprintf(stderr, "Failed to read lux value\n");
            error_code = -2; // Indicate error
        }

        // Log data
        log_data(lux, brightness, error_code);

        // Wait for 1 second
        sleep(SAMPLE_INTERVAL_SEC);
    }

    // Cleanup and exit
    cleanup();
    printf("Grow light system stopped.\n");
    return 0;
}

