            gpioDelay(DEBOUNCE_TIME * 1000);
        }

        // Update previous states
        previous_states = current_states;

        // Check if all channels are released (LED off)
        int all_released = 1;
        for (int i = 1; i <= 8; i++) {
            if (current_states.sensor1_state == 1 || current_states.sensor2_state == 1 ||
