// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the I2C bus
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, OPT3001_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Write the configuration to the OPT3001
int write_config(uint16_t config) {
    char buf[3];
    buf[0] = CONFIG_REG >> 8; // MSB of config register
    buf[1] = CONFIG_REG & 0xFF; // LSB of config register
    buf[2] = (config >> 8) & 0xFF; // MSB of config value
    buf[3] = config & 0xFF; // LSB of config value

    int result = i2cWriteDevice(i2c_handle, buf, 4);
    if (result != 4) {
        fprintf(stderr, "Failed to write configuration: %d\n", result);
        return -1;
    }

    return 0;
}

// Read the result from the OPT3001
int read_result(uint16_t *result) {
    char buf[2];
    buf[0] = RESULT_REG >> 8; // MSB of result register
    buf[1] = RESULT_REG & 0xFF; // LSB of result register

    int result_msb = i2cWriteDevice(i2c_handle, buf, 2);
    if (result_msb != 2) {
        fprintf(stderr, "Failed to write result register address: %d\n", result_msb);
        return -1;
    }

    char read_buf[2];
    int read_result = i2cReadDevice(i2c_handle, read_buf, 2);
    if (read_result != 2) {
        fprintf(stderr, "Failed to read result: %d\n", read_result);
        return -1;
    }

    *result = (read_buf[0] << 8) | read_buf[1];
    return 0;
}

// Convert the raw result to lux
float convert_to_lux(uint16_t raw_value) {
    // Check for overflow (bit 15 of the result register)
    if (raw_value & 0x8000) {
        fprintf(stderr, "Overflow detected!\n");
        return -1.0;
    }

    // Extract the 12-bit lux value from the raw result
    uint16_t lux_value = raw_value >> 4;

    // Apply the conversion formula from the OPT3001 datasheet
    float lux = (float)lux_value * 0.01;

    return lux;
}

// Log the data to a file
int log_data(float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux_value);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Print the data to stdout
void print_data(float lux_value) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    printf("%s, %.2f\n", timestamp, lux_value);
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialization failed, exiting\n");
        return 1;
    }

    // Open the log file
    log_file = fopen("light_data.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    opt3001_config_t config = {CONFIG_CONTINUOUS | CONFIG_RANGE_400 | CONFIG_GAIN_1};

    // Write the configuration to the OPT3001
    if (write_config(config.config) != 0) {
        fprintf(stderr, "Failed to write configuration, exiting\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        uint16_t raw_result;
        if (read_result(&raw_result) == 0) {
            float lux_value = convert_to_lux(raw_result);
            if (lux_value >= 0) {
                log_data(lux_value);
                print_data(lux_value);
            } else {
                fprintf(stderr, "Failed to convert raw value to lux\n");
            }
        } else {
            fprintf(stderr, "Failed to read result, retrying...\n");
        }

        gpioDelay(1000000); // Wait for 1 second (1000000 microseconds)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

