    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    if (fprintf(log_file, "%s: %s\n", timestamp, event_type) < 0) {
        fprintf(stderr, "Error writing to log file.\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 1) {
            // Touch detected
            if (log_touch_event("Touch Detected") != 0) {
                fprintf(stderr, "Error logging touch event.\n");
            }
            control_led(1); // Turn on LED
            gpioDelay(DEBOUNCE_INTERVAL * 1000); // Debounce delay
            control_led(0); // Turn off LED
        } else if (touch_detected == 0) {
            // Touch released
            if (log_touch_event("Touch Released") != 0) {
                fprintf(stderr, "Error logging touch event.\n");
            }
            gpioDelay(DEBOUNCE_INTERVAL * 1000); // Debounce delay
        }

        gpioDelay(1000); // Small delay to prevent busy-waiting
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

