#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SLF3S_ADDR 0x36
#define MEASURE_CMD 0x362F
#define CRC8_POLYNOMIAL 0x31
#define CRC8_INITIAL_VALUE 0xFF
#define FLOW_RATE_MIN 0.0
#define FLOW_RATE_MAX 100.0
#define LOG_FILE "cooling_log.csv"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure for sensor data
typedef struct {
    int16_t flow_rate;
    uint8_t status;
} sensor_data_t;

// Function prototypes
int init_i2c();
int send_command(uint16_t command);
int read_sensor_data(sensor_data_t *data);
uint8_t crc8(const uint8_t *data, int len);
int validate_crc(uint8_t crc, uint8_t calculated_crc);
int validate_flow_rate(int16_t flow_rate);
char* get_status(uint8_t status);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SLF3S_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Send a command to the sensor
int send_command(uint16_t command) {
    char buf[2];
    buf[0] = (command >> 8) & 0xFF;
    buf[1] = command & 0xFF;
    int result = i2cWriteDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }
    return 0;
}

// Read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buf[3];
    int result = i2cReadDevice(i2c_handle, buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    data->flow_rate = (int16_t)((buf[0] << 8) | buf[1]);
    data->status = buf[2];

    return 0;
}

// CRC-8 calculation
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = CRC8_INITIAL_VALUE;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ CRC8_POLYNOMIAL;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Validate CRC
int validate_crc(uint8_t crc, uint8_t calculated_crc) {
    return crc == calculated_crc;
}

// Validate flow rate
int validate_flow_rate(int16_t flow_rate) {
    return (flow_rate >= FLOW_RATE_MIN && flow_rate <= FLOW_RATE_MAX);
}

// Get status string
char* get_status(uint8_t status) {
    switch (status) {
        case 0x00: return "OK";
        case 0x01: return "ERROR_FLOW_RATE_OUT_OF_RANGE";
        case 0x02: return "ERROR_SENSOR_FAULT";
        case 0x03: return "ERROR_SENSOR_NOT_RESPONDING";
        case 0x04: return "ERROR_SENSOR_OVERHEATED";
        case 0x05: return "ERROR_SENSOR_UNDERHEATED";
        case 0x06: return "ERROR_SENSOR_NOT_CALIBRATED";
        case 0x07: return "ERROR_SENSOR_NOT_INITIALIZED";
        default: return "INVALID";
    }
}

// Log data to CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file == NULL) {
        log_file = fopen(LOG_FILE, "w");
        if (log_file == NULL) {
            fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
            return -1;
        }
        fprintf(log_file, "Timestamp,Flow Rate (ml/min),Status\n");
    }

    fprintf(log_file, "%s,%d,%s\n", timestamp, data.flow_rate, get_status(data.status));
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

