void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO chip
bool initialize_gpio() {
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return false;
    }

    // Set the GPIO pins as input
    pinMode(LEFT_SENSOR_PIN, INPUT);
    pinMode(MIDDLE_SENSOR_PIN, INPUT);
    pinMode(RIGHT_SENSOR_PIN, INPUT);

    return true;
}

// Function to read the sensor value from a given GPIO pin
int read_sensor(int pin) {
    return digitalRead(pin);
}

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp: %s\n", strerror(errno));
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to write the sensor data to a CSV file
bool write_to_csv(const char *timestamp, int left, int middle, int right) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        return false;
    }

    fprintf(fp, "%s,%d,%d,%d\n", timestamp, left, middle, right);
    fclose(fp);
    return true;
}

int main() {
    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize the GPIO chip
    if (!initialize_gpio()) {
        return 1;
    }

    printf("Path logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int left_value = read_sensor(LEFT_SENSOR_PIN);
        int middle_value = read_sensor(MIDDLE_SENSOR_PIN);
        int right_value = read_sensor(RIGHT_SENSOR_PIN);

        // Get the current timestamp
        char *timestamp = get_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Error getting timestamp, skipping this iteration.\n");
            delay(50); // Wait before next iteration
            continue;
        }

        // Write the data to the CSV file
        if (!write_to_csv(timestamp, left_value, middle_value, right_value)) {
            fprintf(stderr, "Error writing to CSV file.\n");
        }

        free(timestamp); // Free the allocated memory for the timestamp

        // Wait for 50 milliseconds
        delay(50);
    }

    // Clean up GPIO resources before exiting
    pinMode(LEFT_SENSOR_PIN, INPUT); // Set to input to avoid floating output
    pinMode(MIDDLE_SENSOR_PIN, INPUT);
    pinMode(RIGHT_SENSOR_PIN, INPUT);

    printf("Path logging stopped.\n");

    return 0;
}

