// Define GPIO pins
#define TOUCH_SENSOR_PIN 23
#define LED_PIN 24

// Define GPIO chip and line paths
#define GPIOCHIP_PATH "/sys/class/gpio"
#define GPIOCHIP_PATH_LEN (sizeof(GPIOCHIP_PATH) - 1)

// Define log file path
#define LOG_FILE "touch_log.txt"

// Global variables
static volatile int keep_running = 1;
static FILE *log_file = NULL;

// Function prototypes
int gpio_export(int pin);
int gpio_unexport(int pin);
