// Function to export a GPIO pin
int gpio_export(int pin) {
    char export_path[GPIOCHIP_PATH_LEN + 10];
    int fd;

    snprintf(export_path, sizeof(export_path), "%s/export", GPIOCHIP_PATH);
    fd = open(export_path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", export_path, strerror(errno));
        return -1;
    }

    char pin_str[3];
    snprintf(pin_str, sizeof(pin_str), "%d", pin);
    if (write(fd, pin_str, strlen(pin_str)) < 0) {
        fprintf(stderr, "Error writing to %s: %s\n", export_path, strerror(errno));
        close(fd);
        return -1;
    }

    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int pin) {
    char unexport_path[GPIOCHIP_PATH_LEN + 10];
    int fd;

    snprintf(unexport_path, sizeof(unexport_path), "%s/unexport", GPIOCHIP_PATH);
    fd = open(unexport_path, O_WRONLY);
    if (fd < 0) {
        fprintf(stderr, "Error opening %s: %s\n", unexport_path, strerror(errno));
        return -1;
    }

    char pin_str[3];
