#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <errno.h>
#include <gpiod.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18

// Define buzzer activation duration (in seconds)
#define BUZZER_DURATION 2

// Define log file name
#define LOG_FILE "alert_log.txt"

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *flame_sensor_line = NULL;
static struct gpiod_line *buzzer_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void activate_buzzer();
void log_event(const char *event_message);
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize GPIO lines
int initialize_gpio() {
    // Open GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Get flame sensor line
    flame_sensor_line = gpiod_chip_get_line(chip, FLAME_SENSOR_PIN);
    if (!flame_sensor_line) {
        fprintf(stderr, "Error getting flame sensor line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        return -1;
    }

    // Get buzzer line
    buzzer_line = gpiod_chip_get_line(chip, BUZZER_PIN);
    if (!buzzer_line) {
        fprintf(stderr, "Error getting buzzer line: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        return -1;
    }

    // Request flame sensor line as input
    if (gpiod_line_request_input(flame_sensor_line, "flame_sensor") < 0) {
        fprintf(stderr, "Error requesting flame sensor line as input: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    // Request buzzer line as output
    if (gpiod_line_request_output(buzzer_line, "buzzer", 0) < 0) {
        fprintf(stderr, "Error requesting buzzer line as output: %s\n", strerror(errno));
        gpiod_chip_close(chip);
        gpiod_line_release(flame_sensor_line);
        gpiod_line_release(buzzer_line);
        return -1;
    }

    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    int value = gpiod_line_get_value(flame_sensor_line);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor value: %s\n", strerror(errno));
        return -1;
    }
    return value;
}

// Function to activate the buzzer
void activate_buzzer() {
    if (gpiod_line_set_value(buzzer_line, 1) < 0) {
        fprintf(stderr, "Error setting buzzer value to HIGH: %s\n", strerror(errno));
    }
    usleep(BUZZER_DURATION * 1000000); // Convert seconds to microseconds
    if (gpiod_line_set_value(buzzer_line, 0) < 0) {
        fprintf(stderr, "Error setting buzzer value to LOW: %s\n", strerror(errno));
    }
}

// Function to log an event to the log file
void log_event(const char *event_message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, event_message);
    fflush(log_file); // Ensure the log is written immediately
}

// Function to cleanup GPIO lines and close the chip
void cleanup_gpio() {
    if (flame_sensor_line) {
        gpiod_line_release(flame_sensor_line);
    }
    if (buzzer_line) {
        gpiod_line_release(buzzer_line);
    }
    if (chip) {
        gpiod_chip_close(chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (!log_file) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup_gpio();
        return 1;
    }

    // Log system start
    log_event("System started");

    // Main loop
    while (program_running) {
        int flame_detected = read_flame_sensor();
        if (flame_detected < 0) {
            fprintf(stderr, "Error reading flame sensor. Continuing.\n");
            usleep(500000); // Wait 0.5 seconds before retrying
            continue;
        }

        if (flame_detected == 0) { // Flame detected (LOW signal)
            log_event("FLAME DETECTED");
            activate_buzzer();
        }

        usleep(500000); // Wait 0.5 seconds
    }

    // Log system stop
    log_event("System stopped");

    // Cleanup GPIO
    cleanup_gpio();

    return 0;
}

