// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define LED_PIN 17

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 200

// Define log file name
#define LOG_FILE "touch_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_touch_sensor();
int toggle_led();
int log_touch_event();
void cleanup();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int touch_pin;
    int led_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Set pull-up/down resistor (optional, depending on sensor wiring)
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_UP); // Or PI_PUD_DOWN

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the LED
int toggle_led() {
    int current_state = gpioRead(LED_PIN);
    gpioWrite(LED_PIN, !current_state);
    return current_state;
}

// Function to log a touch event to a file
int log_touch_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    if (fprintf(log_file, "%s\n", timestamp) < 0) {
        fprintf(stderr, "Error writing to log file\n");
        return -1;
    }

    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Function to cleanup GPIO resources
void cleanup() {
    printf("Cleaning up...\n");
    gpioWrite(LED_PIN, 0); // Turn off LED
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor();

        if (touch_detected == 0) { // Assuming touch sensor outputs LOW when touched
            gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
            if (read_touch_sensor() == 0) { // Re-read after debounce
                toggle_led();
                log_touch_event();
            }
        }

        gpioDelay(10 * 1000); // Poll every 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

