int read_sensor(int pin);
int log_event(int sensor_id, int state);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int pin;
    int initial_state;
} sensor_t;

// Array of sensor structures
sensor_t sensors[] = {
    {SENSOR_1_PIN, -1}, // Initialize initial_state to -1
    {SENSOR_2_PIN, -1},
    {SENSOR_3_PIN, -1}
};

int num_sensors = sizeof(sensors) / sizeof(sensors[0]);

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio library. Exiting.\n");
        return 1;
    }

    // Open the log file
