    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Main loop
    while (!terminate) {
        for (int i = 0; i < num_sensors; i++) {
            int current_state = read_sensor(sensors[i].pin);

            if (current_state != sensors[i].initial_state) {
                if (log_event(i + 1, current_state) != 0) {
                    fprintf(stderr, "Failed to log event for sensor %d.\n", i + 1);
                }
                sensors[i].initial_state = current_state;
            }
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Clean up and exit
    fclose(log_file);
    gpioTerminate();
    printf("Program terminated gracefully.\n");
    return 0;
}

