    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    for (int i = 0; i < num_sensors; i++) {
        gpioSetMode(sensors[i].pin, PI_INPUT);
        gpioSetPullUpDown(sensors[i].pin, PI_PUD_UP);
        sensors[i].initial_state = gpioRead(sensors[i].pin); // Read initial state
        if (sensors[i].initial_state < 0) {
            fprintf(stderr, "Failed to read initial state for sensor %d.\n", i + 1);
            gpioTerminate();
            return 1;
        }
    }

    return 0;
}

