// Define the GPIO pin connected to the flame sensor
#define FLAME_SENSOR_GPIO 17

// Define the log file name
#define LOG_FILE "flame_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_flame_sensor();
void log_flame_detection(const char *timestamp);
void signal_handler(int signal);

// Structure to hold program state
typedef struct {
    int gpio_initialized;
    FILE *log_file;
} ProgramState;

ProgramState state = {0, NULL};

// Function to initialize the pigpio library and configure the GPIO pin
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(FLAME_SENSOR_GPIO, PI_INPUT);
    gpioSetPullUpDown(FLAME_SENSOR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    state.gpio_initialized = 1;
    return 0;
}

// Function to read the flame sensor value
int read_flame_sensor() {
    return gpioRead(FLAME_SENSOR_GPIO);
}

// Function to log the flame detection event to a file
void log_flame_detection(const char *timestamp) {
    if (state.log_file != NULL) {
        fprintf(state.log_file, "%s\n", timestamp);
        fflush(state.log_file); // Ensure the data is written to the file immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Install signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the GPIO library
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    state.log_file = fopen(LOG_FILE, "a");
    if (state.log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate(); // Clean up GPIO before exiting
        return 1;
    }

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop to monitor the flame sensor
    while (program_running) {
        int flame_detected = (read_flame_sensor() == 0); // Active-low

        if (flame_detected) {
            // Get the current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20]; // YYYY-MM-DD HH:MM:SS\0

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the flame detection event
            log_flame_detection(timestamp);

            printf("FLAME DETECTED: %s\n", timestamp);
        }

        gpioDelay(100); // Delay for 100 milliseconds
    }

    // Close the log file
    if (state.log_file != NULL) {
        fclose(state.log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

