#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <gpiod.h>

// Define GPIO pins for the touch sensor channels
#define TOUCH_SENSOR_CHANNELS {5, 6, 7, 8, 9, 10, 11, 12}
#define NUM_CHANNELS (sizeof(TOUCH_SENSOR_CHANNELS) / sizeof(TOUCH_SENSOR_CHANNELS[0]))

// Define GPIO pins for the driver output pins
#define DRIVER_OUTPUT_CHANNELS {17, 24, 25, 26, 27, 28, 29, 30}
#define NUM_OUTPUT_CHANNELS (sizeof(DRIVER_OUTPUT_CHANNELS) / sizeof(DRIVER_OUTPUT_CHANNELS[0]))

// Define the log file name
#define LOG_FILE "touch_log.txt"

// Define the initial stabilization delay in milliseconds
#define INITIAL_STABILIZATION_DELAY 200

// Define the polling interval in milliseconds
#define POLLING_INTERVAL 10

// Global variables
static struct gpiod_chip *chip = NULL;
static struct gpiod_line *touch_sensor_lines[NUM_CHANNELS];
static struct gpiod_line *driver_output_lines[NUM_OUTPUT_CHANNELS];
static FILE *log_file = NULL;
static volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_touch_sensor(int channel);
int increment_counter(int channel);
int update_driver_output(int channel, int value);
int log_event(int channel, int counter);
void print_event(int channel, int counter);
void cleanup_gpio();
void signal_handler(int signal);

// Function to initialize the GPIO lines
int initialize_gpio() {
    int ret;

    // Open the GPIO chip
    chip = gpiod_chip_open_by_name("gpiochip0");
    if (!chip) {
        fprintf(stderr, "Error opening GPIO chip: %s\n", strerror(errno));
        return -1;
    }

    // Request GPIO lines for the touch sensor channels
    for (int i = 0; i < NUM_CHANNELS; i++) {
        touch_sensor_lines[i] = gpiod_chip_get_line(chip, TOUCH_SENSOR_CHANNELS[i]);
        if (!touch_sensor_lines[i]) {
            fprintf(stderr, "Error getting touch sensor line %d: %s\n", TOUCH_SENSOR_CHANNELS[i], strerror(errno));
            goto cleanup_chip;
        }

        ret = gpiod_line_request_input(touch_sensor_lines[i], "touch_sensor");
        if (ret < 0) {
            fprintf(stderr, "Error requesting touch sensor line %d as input: %s\n", TOUCH_SENSOR_CHANNELS[i], strerror(errno));
            goto cleanup_lines;
        }
    }

    // Request GPIO lines for the driver output pins
    for (int i = 0; i < NUM_OUTPUT_CHANNELS; i++) {
        driver_output_lines[i] = gpiod_chip_get_line(chip, DRIVER_OUTPUT_CHANNELS[i]);
        if (!driver_output_lines[i]) {
            fprintf(stderr, "Error getting driver output line %d: %s\n", DRIVER_OUTPUT_CHANNELS[i], strerror(errno));
            goto cleanup_lines;
        }

        ret = gpiod_line_request_output(driver_output_lines[i], "driver_output", 0);
        if (ret < 0) {
            fprintf(stderr, "Error requesting driver output line %d as output: %s\n", DRIVER_OUTPUT_CHANNELS[i], strerror(errno));
            goto cleanup_lines;
        }
    }

    return 0;

cleanup_lines:
    for (int i = 0; i < NUM_CHANNELS; i++) {
        if (touch_sensor_lines[i]) {
            gpiod_line_release(touch_sensor_lines[i]);
        }
    }
cleanup_chip:
    gpiod_chip_close(chip);
    return -1;
}

// Function to read the touch sensor value for a given channel
int read_touch_sensor(int channel) {
