#define SENSOR_2_PIN 18
#define SENSOR_3_PIN 27
#define SENSOR_4_PIN 22

// Define the CSV file name
#define CSV_FILE "tracking_log.csv"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading GPIO %d: %d\n", gpio_pin, value);
        return -1; // Indicate an error
    }
    return value;
}

// Function to get the current timestamp in ISO 8601 format
char* get_timestamp() {
    time_t rawtime;
    struct tm *timeinfo;
    char *timestamp = (char*)malloc(25 * sizeof(char)); // Allocate memory for the timestamp string

    if (timestamp == NULL) {
        fprintf(stderr, "Error allocating memory for timestamp\n");
        return NULL;
    }

    time(&rawtime);
    timeinfo = gmtime(&rawtime); // Use gmtime for UTC time

    strftime(timestamp, 25, "%Y-%m-%dT%H:%M:%SZ", timeinfo);
    return timestamp;
}

// Function to write data to the CSV file
int write_to_csv(const char *timestamp, int sensor1, int sensor2, int sensor3, int sensor4) {
    FILE *fp = fopen(CSV_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening CSV file %s\n", CSV_FILE);
        return -1;
    }

    // Check if the file is empty, if so, write the header
    fseek(fp, 0, SEEK_END);
    long file_size = ftell(fp);
    if (file_size == 0) {
        fprintf(fp, "timestamp,sensor1,sensor2,sensor3,sensor4\n");
    }

    fprintf(fp, "%s,%d,%d,%d,%d\n", timestamp, sensor1, sensor2, sensor3, sensor4);
    fclose(fp);
    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(SENSOR_3_PIN, PI_INPUT);
    gpioSetMode(SENSOR_4_PIN, PI_INPUT);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Tracking program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_PIN);
        int sensor2_value = read_sensor(SENSOR_2_PIN);
        int sensor3_value = read_sensor(SENSOR_3_PIN);
        int sensor4_value = read_sensor(SENSOR_4_PIN);

        // Get the current timestamp
        char *timestamp = get_timestamp();
        if (timestamp == NULL) {
            fprintf(stderr, "Error getting timestamp, skipping this iteration.\n");
            gpioDelay(100); // Wait 100ms before next iteration
            continue;
        }

        // Write data to the CSV file
        if (write_to_csv(timestamp, sensor1_value, sensor2_value, sensor3_value, sensor4_value) != 0) {
            fprintf(stderr, "Error writing to CSV file, skipping this iteration.\n");
        }

        // Free the allocated timestamp memory
        free(timestamp);

        // Wait 100ms
        gpioDelay(100);
    }

    // Terminate the pigpio library
    gpioTerminate();

    fprintf(stderr, "Tracking program terminated.\n");
    return 0;
}

