#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the tilt sensors
#define SENSOR_1_GPIO 17
#define SENSOR_2_GPIO 18

// Define the log file path
#define LOG_FILE "/var/log/tilt_events.log"

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor(int gpio_pin);
void log_event(int gpio_pin);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int gpio_pin;
    int last_state;
    unsigned long last_change_time;
} sensor_data_t;

sensor_data_t sensor1_data = {SENSOR_1_GPIO, 1, 0}; // Initialize last_state and last_change_time
sensor_data_t sensor2_data = {SENSOR_2_GPIO, 1, 0};

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio and GPIO pins
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Continuing without logging.\n");
    }

    // Main loop
    while (running) {
        // Read sensor 1
        int sensor1_value = read_sensor(sensor1_data.gpio_pin);
        if (sensor1_value != -1) {
            if (sensor1_value != sensor1_data.last_state) {
                // Debounce
                if (gpioTick() - sensor1_data.last_change_time > DEBOUNCE_TIME * 1000) {
                    log_event(sensor1_data.gpio_pin);
                    sensor1_data.last_state = sensor1_value;
                    sensor1_data.last_change_time = gpioTick();
                }
            }
        }

        // Read sensor 2
        int sensor2_value = read_sensor(sensor2_data.gpio_pin);
        if (sensor2_value != -1) {
            if (sensor2_value != sensor2_data.last_state) {
                // Debounce
                if (gpioTick() - sensor2_data.last_change_time > DEBOUNCE_TIME * 1000) {
                    log_event(sensor2_data.gpio_pin);
                    sensor2_data.last_state = sensor2_value;
                    sensor2_data.last_change_time = gpioTick();
                }
            }
        }

        // Sleep for 100 milliseconds
        gpioDelay(100);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Function to initialize pigpio and GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the state of a sensor
int read_sensor(int gpio_pin) {
    int value = gpioRead(gpio_pin);
    if (value < 0) {
        fprintf(stderr, "Error reading sensor on GPIO %d\n", gpio_pin);
        return -1; // Indicate an error
    }
    return value;
}

// Function to log a tilt event to the log file
void log_event(int gpio_pin) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, Sensor %d tilted\n", timestamp, gpio_pin);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Log file is not open. Event logged to console.\n");
        printf("%s, Sensor %d tilted\n", timestamp, gpio_pin);
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Release GPIO lines
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT); // Set back to input
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

