        fprintf(stderr, "Error writing to log file\n");
        return -1; // Indicate error
    }
    fflush(fp); // Ensure data is written to disk immediately
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SENSOR1_PIN, PI_INPUT);
    gpioSetMode(SENSOR2_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,sensor1,sensor2,led_state\n");
    }
    rewind(log_file);

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Obstacle avoidance system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR1_PIN);
        int sensor2_value = read_sensor(SENSOR2_PIN);

        if (sensor1_value == -1 || sensor2_value == -1) {
            // Error reading sensor, skip this iteration
            gpioDelay(100); // Wait 100ms before next iteration
            continue;
        }

        // Control LED based on sensor readings
        int led_state = (sensor1_value == 0 && sensor2_value == 0) ? 1 : 0;
        if (control_led(LED_PIN, led_state) == -1) {
            // Error controlling LED, skip this iteration
            gpioDelay(100); // Wait 100ms before next iteration
            continue;
        }

        // Log data
        if (log_data(log_file, sensor1_value, sensor2_value, led_state) == -1) {
            // Error logging data, skip this iteration
            gpioDelay(100); // Wait 100ms before next iteration
            continue;
        }

        // Wait 100ms
        gpioDelay(100);
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_led(LED_PIN, 0); // Turn off LED
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

