#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define MIC_PIN 4
#define LED_PIN 17

// Define sampling parameters
#define SAMPLE_RATE 8000 // Hz
#define SAMPLE_PERIOD_US (1000000 / SAMPLE_RATE) // microseconds

// Define peak detection threshold
#define PEAK_THRESHOLD 1 // Digital HIGH

// Define LED current limit (mA)
#define LED_CURRENT_LIMIT 100

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_microphone_sample();
bool is_peak_detected(int sample);
void control_led(bool on);
void log_timestamp();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int mic_pin;
    int led_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(MIC_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    return 0;
}

// Function to read a single microphone sample
int read_microphone_sample() {
    return gpioRead(MIC_PIN);
}

// Function to detect a sound peak
bool is_peak_detected(int sample) {
    return (sample == PEAK_THRESHOLD);
}

// Function to control the LED
void control_led(bool on) {
    gpioWrite(LED_PIN, on ? 1 : 0);
}

// Function to log a timestamp
void log_timestamp() {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);
    printf("%ld.%09ld\n", ts.tv_sec, ts.tv_nsec);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Turn off the LED
    control_led(false);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Sound peak detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read microphone sample
        int sample = read_microphone_sample();

        // Check for errors during GPIO read
        if (sample < 0) {
            fprintf(stderr, "Error reading microphone sample\n");
            break; // Exit loop on error
        }

        // Detect sound peak
        if (is_peak_detected(sample)) {
            // Log timestamp
            log_timestamp();

            // Control LED
            control_led(true);

            // Wait for 100ms
            gpioDelay(LED_CURRENT_LIMIT * 1000); // pigpioDelay takes microseconds

            // Turn off LED
            control_led(false);
        }

        // Delay for the sample period
        gpioDelay(SAMPLE_PERIOD_US);
    }

    return 0;
}

