#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// Si1175 I2C address
#define SI1175_ADDR 0x60

// Si1175 register addresses
#define REG_ALS_VIS_DATA0 0x22
#define REG_ALS_VIS_DATA1 0x23
#define REG_PART_ID 0x00
#define REG_RESET 0x07

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t als_data;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("\nCtrl+C pressed. Exiting gracefully...\n");
    terminate = 1;
}

// Function to initialize the Si1175 sensor
int init_si1175() {
    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, REG_RESET, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to reset Si1175.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Check Part ID
    int part_id = i2cReadByteData(i2c_handle, REG_PART_ID);
    if (part_id < 0) {
        fprintf(stderr, "Error: Failed to read Part ID.\n");
        return -1;
    }
    if (part_id != 0x75) {
