// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the state of a touch sensor
int read_touch_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to format the timestamp
void format_timestamp(char *timestamp_str, size_t timestamp_str_size) {
    struct timespec ts;
    clock_gettime(CLOCK_MONOTONIC, &ts);
    long milliseconds = ts.tv_nsec / 1000000;
    snprintf(timestamp_str, timestamp_str_size, "[%ld.%03ld] ", ts.tv_sec, milliseconds);
}

// Function to generate the line string
void generate_line_string(char *line_str, size_t line_str_size, int ch1, int ch2, int ch3, int ch4, int ch5, int ch6, int ch7, int ch8) {
    snprintf(line_str, line_str_size, "CH1=%d CH2=%d CH3=%d CH4=%d CH5=%d CH6=%d CH7=%d CH8=%d",
             ch1, ch2, ch3, ch4, ch5, ch6, ch7, ch8);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as inputs
    gpioSetMode(TP1_PIN, PI_INPUT);
    gpioSetMode(TP2_PIN, PI_INPUT);
    gpioSetMode(TP3_PIN, PI_INPUT);
    gpioSetMode(TP4_PIN, PI_INPUT);
    gpioSetMode(TP5_PIN, PI_INPUT);
    gpioSetMode(TP6_PIN, PI_INPUT);
    gpioSetMode(TP7_PIN, PI_INPUT);
    gpioSetMode(TP8_PIN, PI_INPUT);

    // Main loop
    while (program_running) {
        // Read the touch sensor states
        int ch1 = read_touch_sensor(TP1_PIN);
        int ch2 = read_touch_sensor(TP2_PIN);
        int ch3 = read_touch_sensor(TP3_PIN);
        int ch4 = read_touch_sensor(TP4_PIN);
        int ch5 = read_touch_sensor(TP5_PIN);
        int ch6 = read_touch_sensor(TP6_PIN);
        int ch7 = read_touch_sensor(TP7_PIN);
        int ch8 = read_touch_sensor(TP8_PIN);

        // Format the timestamp
        char timestamp_str[30];
        format_timestamp(timestamp_str, sizeof(timestamp_str));

        // Generate the line string
        char line_str[100];
        generate_line_string(line_str, sizeof(line_str), ch1, ch2, ch3, ch4, ch5, ch6, ch7, ch8);

        // Print the line to the console
        printf("%s", line_str);

        // Wait for 200 milliseconds
        gpioDelay(200000); // 200 ms = 200000 microseconds
    }

    // Release GPIO resources before exiting
    gpioTerminate();

    return 0;
}

