#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 18
#define BLUE_PIN  27

// Define PWM frequency
#define PWM_FREQUENCY 1000

// Define PWM range
#define PWM_RANGE 255

// Define fade duration (in seconds)
#define FADE_DURATION 5

// Define number of steps for linear interpolation
#define NUM_STEPS 50

// Global variables
static volatile int running = 1;
static int red_value = 0;
static int green_value = 0;
static int blue_value = 0;

// Function prototypes
void signal_handler(int signal);
void initialize_gpio();
void cleanup_gpio();
void set_led_color(int red, int green, int blue);
void fade_to_random_hue();
void linear_interpolation(int start_red, int start_green, int start_blue, int end_red, int end_green, int end_blue, int steps);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize GPIO pins
void initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        exit(EXIT_FAILURE);
    }

    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    gpioSetPWMfrequency(RED_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN, PWM_FREQUENCY);

    gpioSetPWMrange(RED_PIN, PWM_RANGE);
    gpioSetPWMrange(GREEN_PIN, PWM_RANGE);
    gpioSetPWMrange(BLUE_PIN, PWM_RANGE);

    // Seed the random number generator
    FILE *urandom = fopen("/dev/urandom", "r");
    if (urandom == NULL) {
        syslog(LOG_ERR, "Failed to open /dev/urandom");
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    unsigned int seed;
    if (fread(&seed, sizeof(unsigned int), 1, urandom) != 1) {
        syslog(LOG_ERR, "Failed to read from /dev/urandom");
        fclose(urandom);
        gpioTerminate();
        exit(EXIT_FAILURE);
    }
    fclose(urandom);
    srand(seed);

    syslog(LOG_INFO, "GPIO initialized successfully");
}

// Cleanup GPIO pins
void cleanup_gpio() {
    syslog(LOG_INFO, "Cleaning up GPIO...");
    set_led_color(0, 0, 0); // Turn off LED
    gpioTerminate();
    syslog(LOG_INFO, "GPIO cleanup complete");
}

// Set the RGB LED color using PWM
void set_led_color(int red, int green, int blue) {
    gpioPWM(RED_PIN, red);
    gpioPWM(GREEN_PIN, green);
    gpioPWM(BLUE_PIN, blue);
}

// Fade to a random hue
void fade_to_random_hue() {
    int red, green, blue;
    float hue;

    // Generate a random hue between 0 and 360
    hue = (float)(rand() % 360);

    // Convert hue to RGB (simplified HSL to RGB conversion)
    red   = (int)(255 * (1 - fabs(fmod(hue / 60.0, 2) - 1)));
    green = (int)(255 * (1 - fabs(fmod((hue + 120) / 60.0, 2) - 1)));
    blue  = (int)(255 * (1 - fabs(fmod((hue + 240) / 60.0, 2) - 1)));

    // Clamp values to the 0-255 range
    red   = (red   < 0) ? 0 : (red   > 255) ? 255 : red;
    green = (green < 0) ? 0 : (green > 255) ? 255 : green;
    blue  = (blue  < 0) ? 0 : (blue  > 255) ? 255 : blue;

    linear_interpolation(red_value, green_value, blue_value, red, green, blue, NUM_STEPS);
}

// Linear interpolation between two colors
void linear_interpolation(int start_red, int start_green, int start_blue, int end_red, int end_green, int end_blue, int steps) {
    float red_step   = (float)(end_red   - start_red)   / steps;
    float green_step = (float)(end_green - start_green) / steps;
    float blue_step  = (float)(end_blue  - start_blue)  / steps;

    for (int i = 0; i < steps; i++) {
        red_value   = (int)(start_red   + red_step   * i);
        green_value = (int)(start_green + green_step * i);
        blue_value  = (int)(start_blue  + blue_step  * i);

        // Clamp values to the 0-255 range
        red_value   = (red_value   < 0) ? 0 : (red_value   > 255) ? 255 : red_value;
        green_value = (green_value < 0) ? 0 : (green_value > 255) ? 255 : green_value;
        blue_value  = (blue_value  < 0) ? 0 : (blue_value  > 255) ? 255 : blue_value;

        set_led_color(red_value, green_value, blue_value);
        gpioDelay(1000000 / PWM_FREQUENCY / steps); // Delay for 1/steps seconds
    }

    set_led_color(end_red, end_green, end_blue); // Set final color
}

int main() {
    // Open syslog
    openlog("rgb_led_fade", LOG_PID | LOG_CONS, LOG_USER);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    initialize_gpio();

    // Main loop
    while (running) {
        fade_to_random_hue();
        gpioDelay(FADE_DURATION * 1000000); // Delay for fade duration (in microseconds)
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close syslog
    closelog();

    return 0;
}

