#include <linux/i2c-dev.h>
#include <pigpio.h>

// TCS34725 Registers
#define TCS34725_ADDRESS 0x29
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// GPIO Pin for LED
#define LED_PIN 17

// Calibration Threshold
#define CALIBRATION_THRESHOLD 200

// I2C Bus
#define I2C_BUS "/dev/i2c-1"

// Global Variables
int i2c_fd;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int init_i2c();
int init_sensor();
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear);
void calibrate_sensor(uint16_t red, uint16_t green, uint16_t blue, uint16_t clear);
void control_led(uint16_t red);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint16_t red;
    uint16_t green;
    uint16_t blue;
    uint16_t clear;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize sensor
    if (init_sensor() != 0) {
        fprintf(stderr, "Sensor initialisation failed\n");
        cleanup();
        return 1;
    }

    uint16_t red, green, blue, clear;
    sensor_data_t sensor_data;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&red, &green, &blue, &clear) == 0) {
            // Calibrate sensor data
            calibrate_sensor(red, green, blue, clear);

            // Control LED based on calibrated red value
            control_led(red);

            // Print sensor data
            printf("Red: %u, Green: %u, Blue: %u, Clear: %u\n", red, green, blue, clear);

            // Store sensor data in a struct
            sensor_data.red = red;
            sensor_data.green = green;
            sensor_data.blue = blue;
            sensor_data.clear = clear;
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Wait for 200 milliseconds
        gpioDelay(200000); // 200 ms = 200000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, TCS34725_ADDRESS) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize TCS34725 sensor
int init_sensor() {
    // Enable power and RGBC
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_ENABLE, 0x03) < 0) {
        perror("Error writing to ENABLE register");
        return -1;
    }

    // Set integration time (ATIME) - 154ms
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_ATIME, 0xD5) < 0) {
        perror("Error writing to ATIME register");
        return -1;
    }

    // Set gain (CONTROL) - 1x gain
    if (i2c_smbus_write_byte_data(i2c_fd, TCS34725_CONTROL, 0x01) < 0) {
        perror("Error writing to CONTROL register");
        return -1;
    }

    return 0;
}

// Read sensor data
int read_sensor_data(uint16_t *red, uint16_t *green, uint16_t *blue, uint16_t *clear) {
    uint8_t data[8];

    if (i2c_smbus_read_i2c_block_data(i2c_fd, TCS34725_CDATA, (char *)data, 8) < 0) {
        perror("Error reading sensor data");
        return -1;
    }

    *clear = (data[1] << 8) | data[0];
    *red = (data[3] << 8) | data[2];
    *green = (data[5] << 8) | data[4];
    *blue = (data[7] << 8) | data[6];

    return 0;
}

// Calibrate sensor data
void calibrate_sensor(uint16_t red, uint16_t green, uint16_t blue, uint16_t clear) {
    // Simple calibration: scale red value to green
    uint16_t calibrated_red = red; // Scale red to green
    uint16_t calibrated_green = green; // Scale green to green
    uint16_t calibrated_blue = blue; // Scale blue to blue
    uint16_t calibrated_clear = clear; // Scale clear to clear

    // Apply calibration threshold
    if (calibrated_red > CALIBRATION_THRESHOLD) {
        calibrated_red = 1; // Set to 1 if above threshold
    } else {
        calibrated_red = 0; // Set to 0 if below threshold
    }

    if (calibrated_green > CALIBRATION_THRESHOLD) {
        calibrated_green = 1; // Set to 1 if above threshold
    } else {
        calibrated_green = 0; // Set to 0 if below threshold
    }

    if (calibrated_blue > CALIBRATION_THRESHOLD) {
        calibrated_blue = 1; // Set to 1 if above threshold
    } else {
        calibrated_blue = 0; // Set to 0 if below threshold
    }

    if (calibrated_clear > CALIBRATION_THRESHOLD) {
        calibrated_clear = 1; // Set to 1 if above threshold
    } else {
        calibrated_clear = 0; // Set to 0 if below threshold
    }

    // Update sensor data with calibrated values
    *red = calibrated_red;
    *green = calibrated_green;
    *blue = calibrated_blue;
    *clear = calibrated_clear;
}

// Control LED based on calibrated red value
void control_led(uint16_t red) {
    if (red > CALIBRATION_THRESHOLD) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources
void cleanup() {
    // Disable sensor
    i2c_smbus_write_byte_data(i2c_fd, TCS34725_ENABLE, 0x00);

    // Close I2C file descriptor
    close(i2c_fd);

    // Release GPIO line
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioSetMode(LED_PIN, PI_INPUT); // Set to input to avoid floating

    // Terminate pigpio
    gpioTerminate();
}

