#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <bcm2835.h>

// Define constants
#define BH1750_ADDR 0x23
#define CONTINUOUS_HIGH_RES_MODE 0x10
#define NUM_LEDS 10
#define GPIO_PIN RPI_GPIO_P1_12 // GPIO18 (PCM_CLK)
#define PWM_RANGE 1000
#define PWM_CLOCK_DIVIDER BCM2835_PWM_CLOCK_DIVIDER_16
#define PWM_MODE BCM2835_PWM_MODE_MS

// Global variables
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void map_lux_to_brightness(float lux, uint8_t *brightness_levels);
void set_led_brightness(uint8_t brightness_levels[NUM_LEDS]);
void cleanup();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (!bcm2835_init()) {
        fprintf(stderr, "bcm2835_init failed. Are you running as root?\n");
        return 1;
    }

    bcm2835_i2c_begin();
    bcm2835_i2c_setSlaveAddress(BH1750_ADDR);
    bcm2835_i2c_setClockDivider(BCM2835_I2C_CLOCK_DIVIDER_626); // 100kHz

    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    uint8_t config_mode = CONTINUOUS_HIGH_RES_MODE;
    char buf[1];
    buf[0] = config_mode;

    if (bcm2835_i2c_write(buf, 1) != BCM2835_I2C_REASON_OK) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return 1;
    }

    bcm2835_delay(200); // Wait for measurement (at least 180ms)

    char data[2];
    if (bcm2835_i2c_read(data, 2) != BCM2835_I2C_REASON_OK) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return 1;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Map lux value to brightness levels for WS2812B strip
void map_lux_to_brightness(float lux, uint8_t *brightness_levels) {
    // Clamp lux value to a reasonable range
    if (lux < 0) lux = 0;
    if (lux > 1000) lux = 1000;

    // Use logarithmic mapping for brightness
    float log_lux = log10(lux + 1); // Add 1 to avoid log(0)
    float brightness = 100.0 - (log_lux / log10(1001)); // Scale to 0-100

    // Ensure brightness is within valid range
    if (brightness < 0) brightness = 0;
    if (brightness > 100) brightness = 100;

    // Convert brightness to brightness levels (0-255)
    for (int i = 0; i < NUM_LEDS; i++) {
        brightness_levels[i] = (uint8_t)brightness;
    }
}

// Set LED brightness using PWM
void set_led_brightness(uint8_t brightness_levels[NUM_LEDS]) {
    // Calculate the number of clock cycles needed for each LED
    uint32_t clock_cycles[NUM_LEDS];
    for (int i = 0; i < NUM_LEDS; i++) {
        clock_cycles[i] = (uint32_t)((float)PWM_RANGE * brightness_levels[i] / 100.0);
    }

    // Generate the WS2812B timing sequence
    uint32_t start_time = bcm2835_st_read();
    for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t end_time = start_time + clock_cycles[i];
        while (bcm2835_st_read() < end_time);
    }
    start_time = bcm2835_st_read();
    for (int i = 0; i < NUM_LEDS; i++) {
        uint32_t end_time = start_time + clock_cycles[i];
        while (bcm2835_st_read() < end_time);
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    bcm2835_i2c_end();
    bcm2835_close();
}

int main() {
    // Set up signal handling
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c()) {
        return 1;
    }

    // Configure PWM
    bcm2835_pwm_set_clock(PWM_CLOCK_DIVIDER);
    bcm2835_pwm_set_mode(PWM_MODE);
    bcm2835_pwm_set_range(PWM_RANGE);
    bcm2835_pwm_set_data(0, 0); // Initialize all LEDs to off

    float lux;
    uint8_t brightness_levels[NUM_LEDS];

    printf("Starting ambient light monitoring...\n");

    while (program_running) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            // Map lux value to brightness levels
            map_lux_to_brightness(lux, brightness_levels);

            // Set LED brightness
            set_led_brightness(brightness_levels);

            printf("Lux: %.2f, Brightness: ", lux);
            for (int i = 0; i < NUM_LEDS; i++) {
                printf("%d ", brightness_levels[i]);
            }
            printf("\n");
        } else {
            fprintf(stderr, "Failed to read lux value.\n");
        }

        bcm2835_delay(180); // Wait 180ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

