    bcm2835_delay(200); // Wait for measurement (at least 180ms)

    char data[2];
    if (bcm2835_i2c_read(data, 2) != BCM2835_I2C_REASON_OK) {
        fprintf(stderr, "Error reading from I2C device.\n");
        return 1;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
