#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define NUM_LEDS 10
#define AMBIENT_LIGHT_THRESHOLD 500
#define AMBIENT_LIGHT_HYSTERESIS 100
#define MAX_BRIGHTNESS 255
#define MIN_BRIGHTNESS 0
#define MAX_IllumINATION 10000
#define MIN_IllumINATION 0
#define SIGINT_GPIO 17

// Global variables
int i2c_fd;
int spi_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_spi();
int read_bh1750();
float scale_brightness(int raw_value);
void set_apa102_led(int led_index, int brightness, int blue, int green, int red);
void send_apa102_data(int num_leds, int brightness);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    char filename[20];
    snprintf(filename, 19, "/dev/i2c-%d", 1); // I2C bus 1
    i2c_fd = open(filename, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, BH1750_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize SPI communication
int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure max speed hz
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed hz");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Read ambient light level from BH1750 sensor
int read_bh1750() {
    uint8_t config_cmd = 0x10; // Continuous high-resolution mode
    if (write(i2c_fd, &config_cmd, 1) != 1) {
        perror("Error writing to I2C device");
        return -1;
    }

    usleep(200000); // Wait for measurement (at least 180ms)

    uint8_t data[2];
    if (read(i2c_fd, data, 2) != 2) {
        perror("Error reading from I2C device");
        return -1;
    }

    int raw_value = (data[0] << 8) | data[1];
    return raw_value;
}

// Scale brightness value to 0-255 range
float scale_brightness(int raw_value) {
    float brightness = (float)raw_value / MAX_IllumINATION * MAX_BRIGHTNESS;
    if (brightness < MIN_BRIGHTNESS) {
        brightness = MIN_BRIGHTNESS;
    } else if (brightness > MAX_BRIGHTNESS) {
        brightness = MAX_BRIGHTNESS;
    }
    return brightness;
}

// Set APA102 LED frame data
void set_apa102_led(int led_index, int brightness, int blue, int green, int red) {
    uint32_t frame_data[4] = {0};
    frame_data[0] = 0x00000000; // Start frame
    frame_data[1] = (brightness << 16) | (green << 8) | blue; // LED frame
    frame_data[2] = (red << 16) | (green << 8) | blue; // LED frame
    frame_data[3] = 0x00000000; // End frame

    uint8_t spi_data[4 * 4]; // 4 bytes per frame * 4 frames = 16 bytes
    memcpy(spi_data, frame_data, sizeof(spi_data));

    uint8_t spi_tx_buf[4 * 4];
    memcpy(spi_tx_buf, spi_data, sizeof(spi_tx_buf));

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)spi_tx_buf,
        .rx_buf = 0,
        .len = sizeof(spi_tx_buf),
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message");
    }
}

// Send APA102 data stream
void send_apa102_data(int num_leds, int brightness) {
    uint32_t start_frame = 0x00000000;
    uint32_t end_frame = 0x00000000;

    uint8_t spi_data[4 * 4]; // 4 bytes per frame * 4 frames = 16 bytes
    memset(spi_data, 0, sizeof(spi_data));

    for (int i = 0; i < num_leds; i++) {
        set_apa102_led(i, brightness, 0, 0, 0); // Turn off all LEDs
    }

    // Start frame
    memcpy(spi_data, &start_frame, sizeof(start_frame));
    uint8_t spi_tx_buf[4 * 4];
    memcpy(spi_tx_buf, spi_data, sizeof(spi_tx_buf));

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)spi_tx_buf,
        .rx_buf = 0,
        .len = sizeof(spi_tx_buf),
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message (start frame)");
    }

    // LED frames
    for (int i = 0; i < num_leds; i++) {
        memcpy(spi_data, &start_frame, sizeof(start_frame));
        memcpy(spi_data + sizeof(start_frame), &start_frame, sizeof(start_frame));
        memcpy(spi_data + 2 * sizeof(start_frame), &start_frame, sizeof(start_frame));
        memcpy(spi_data + 3 * sizeof(start_frame), &start_frame, sizeof(start_frame));

        uint8_t spi_tx_buf[4 * 4];
        memcpy(spi_tx_buf, spi_data, sizeof(spi_tx_buf));

        transfer = {
            .tx_buf = (unsigned long)spi_tx_buf,
            .rx_buf = 0,
            .len = sizeof(spi_tx_buf),
            .speed_hz = SPI_SPEED,
            .bits_per_word = SPI_BITS_PER_WORD,
            .delay_usecs = 0,
            .cs_change = 0,
        };

        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
            perror("Error sending SPI message (LED frame)");
        }
    }

    // End frame
    memcpy(spi_data, &end_frame, sizeof(end_frame));
    memcpy(spi_data + sizeof(end_frame), &end_frame, sizeof(end_frame));
    memcpy(spi_data + 2 * sizeof(end_frame), &end_frame, sizeof(end_frame));
    memcpy(spi_data + 3 * sizeof(end_frame), &end_frame, sizeof(end_frame));

    uint8_t spi_tx_buf[4 * 4];
    memcpy(spi_tx_buf, spi_data, sizeof(spi_tx_buf));

    transfer = {
        .tx_buf = (unsigned long)spi_tx_buf,
        .rx_buf = 0,
        .len = sizeof(spi_tx_buf),
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
        .delay_usecs = 0,
        .cs_change = 0,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 0) {
        perror("Error sending SPI message (end frame)");
    }
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (spi_fd >= 0) {
        close(spi_fd);
    }
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    int ambient_light_threshold_high = AMBIENT_LIGHT_THRESHOLD + AMBIENT_LIGHT_HYSTERESIS;
    int ambient_light_threshold_low = AMBIENT_LIGHT_THRESHOLD - AMBIENT_LIGHT_HYSTERESIS;

    int last_ambient_light_state = 0; // 0 = below threshold, 1 = above threshold

    // Main loop
    while (program_running) {
        int raw_value = read_bh1750();
        if (raw_value < 0) {
            fprintf(stderr, "Error reading BH1750. Retrying in 1 second.\n");
            sleep(1);
            continue;
        }

        float brightness = scale_brightness(raw_value);

        int ambient_light_state = (raw_value > ambient_light_threshold_high) ? 1 : 0;

        if (ambient_light_state != last_ambient_light_state) {
            printf("Ambient light level changed to %s. Brightness: %.2f\n", ambient_light_state ? "above" : "below", brightness);
            send_apa102_data(NUM_LEDS, (int)brightness);
            last_ambient_light_state = ambient_light_state;
        }

        usleep(120000); // Wait 120ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

