#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <string.h>

// VEML7700 I2C address
#define VEML7700_ADDR 0x48

// VEML7700 register addresses
#define VEML7700_CONFIG 0x00
#define VEML7700_ALS_DATA 0x04

// GPIO pin for WS2812B data line
#define WS2812B_PIN 18

// Gamma correction factor (adjust as needed)
#define GAMMA 2.2

// Global variables
int i2c_fd;
bool running = true;

// Function prototypes
int init_veml7700();
int read_veml7700_als(uint16_t *als_data);
float calculate_lux(uint16_t als_data);
int map_lux_to_brightness(float lux);
void set_led_brightness(int brightness);
void send_ws2812b_data(uint8_t *data, int num_bytes);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
    running = false;
}

// Initialize the VEML7700 sensor
int init_veml7700() {
    // Configuration register: Continuous mode, integration time = 100ms, Gain = 1/4
    if (wiringPiI2CWriteReg8(i2c_fd, VEML7700_CONFIG, 0x01) < 0) {
        fprintf(stderr, "Error writing to VEML7700 config register: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read ambient light data from the VEML7700 sensor
int read_veml7700_als(uint16_t *als_data) {
    int als_low, als_high;

    als_low = wiringPiI2CReadReg8(i2c_fd, VEML7700_ALS_DATA);
    if (als_low < 0) {
        fprintf(stderr, "Error reading ALS data low byte: %s\n", strerror(errno));
        return -1;
    }

    als_high = wiringPiI2CReadReg8(i2c_fd, VEML7700_ALS_DATA + 1);
    if (als_high < 0) {
        fprintf(stderr, "Error reading ALS data high byte: %s\n", strerror(errno));
        return -1;
    }

    *als_data = (als_high << 8) | als_low;
    return 0;
}

// Calculate lux value from ambient light data
float calculate_lux(uint16_t als_data) {
    // Conversion formula from VEML7700 datasheet
    return als_data * 0.0576;
}

// Map lux value to brightness level (0-255)
int map_lux_to_brightness(float lux) {
    // Simple threshold-based brightness mapping
    if (lux < 100) {
        return 0;
    } else if (lux < 500) {
        return (int)((lux - 100) / 400.0 * 255.0);
    } else {
        return 255;
    }
}

// Set the brightness level of the WS2812B LED strip
void set_led_brightness(int brightness) {
    // This is a simplified approach.  A real implementation would
    // use a lookup table to generate the bitstream for the WS2812B.
    // For demonstration purposes, we'll just print a message.
    printf("Setting LED brightness to %d\n", brightness);
}

// Send WS2812B data using bit-banging
void send_ws2812b_data(uint8_t *data, int num_bytes) {
    for (int i = 0; i < num_bytes; i++) {
        for (int j = 7; j >= 0; j--) {
            digitalWrite(WS2812B_PIN, (data[i] >> j) & 1);
            delayMicroseconds(1000); // 1us high
        }
        delayMicroseconds(1000); // 1us low
    }
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "Error initializing wiringPi: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(VEML7700_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "Error initializing I2C: %s\n", strerror(errno));
        return 1;
    }

    // Initialize VEML7700 sensor
    if (init_veml7700() == -1) {
        fprintf(stderr, "Error initializing VEML7700 sensor.\n");
        return 1;
    }

    // Set WS2812B pin as output
    pinMode(WS2812B_PIN, OUTPUT);

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint8_t led_data[3]; // 3 bytes for RGB (GRB)
    uint16_t als_data;
    float lux;
    int brightness;

    // Main loop
    while (running) {
        // Read ambient light data
        if (read_veml7700_als(&als_data) == -1) {
            fprintf(stderr, "Error reading ALS data, retrying...\n");
            delay(100);
            continue;
        }

        // Calculate lux value
        lux = calculate_lux(als_data);

        // Map lux value to brightness level
        brightness = map_lux_to_brightness(lux);

        // Set LED brightness
        set_led_brightness(brightness);

        // Print lux reading and brightness value
        printf("Lux: %.2f, Brightness: %d\n", lux, brightness);

        // Delay for 200ms
        delay(200);
    }

    // Cleanup (this part will not be reached if the loop is exited normally)
    digitalWrite(WS2812B_PIN, LOW); // Turn off LED
    close(i2c_fd); // Close I2C file descriptor
    return 0;
}

