        }

        if (flame_detected) {
            log_event("Flame detected during self-test.");
            activate_buzzer(100);
            activate_led(100);
            break; // Exit self-test if flame is detected
        } else {
            log_event("Flame cleared during self-test.");
        }
    }

    if (!flame_detected) {
        log_event("Self-test failed. Exiting.");
        cleanup();
        return 1;
    }

    log_event("Self-test successful.");

    // Main loop
    while (running) {
        int sensor_value = read_flame_sensor();

        if (sensor_value == 0) {
            log_event("Flame detected!");
            activate_buzzer(100);
            activate_led(100);
        } else {
            log_event("Flame cleared.");
        }

        gpioDelay(50 * 1000); // Delay for 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

