#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define LED_GPIO 17
#define BUFFER_SIZE 60
#define SLEEP_DURATION_SEC 1

// Global variables
int i2c_handle;
volatile sig_atomic_t program_running = 1;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
void add_to_buffer(CircularBuffer *cb, float value);
float calculate_average(CircularBuffer *cb);
void set_led_frequency(float lux);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *cb) {
    cb->head = 0;
    cb->count = 0;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char config_cmd = 0x10; // Continuous high-resolution mode
    if (i2cWriteByte(i2c_handle, config_cmd) != 0) {
        fprintf(stderr, "Error writing to I2C device\n");
        return -1;
    }
    gpioDelay(200); // Wait for measurement (at least 180ms)

    char data[2];
    if (i2cReadDevice(i2c_handle, data, 2) != 2) {
        fprintf(stderr, "Error reading from I2C device\n");
        return -1;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2; // Convert to lux
    return 0;
}

// Add a value to the circular buffer
void add_to_buffer(CircularBuffer *cb, float value) {
    cb->buffer[cb->head] = value;
    cb->head = (cb->head + 1) % BUFFER_SIZE;
    if (cb->count < BUFFER_SIZE) {
        cb->count++;
    }
}

// Calculate the average of the values in the circular buffer
float calculate_average(CircularBuffer *cb) {
    if (cb->count == 0) {
        return 0.0;
    }
    float sum = 0.0;
    for (int i = 0; i < cb->count; i++) {
        sum += cb->buffer[i];
    }
    return sum / cb->count;
}

// Set the LED frequency based on lux value
void set_led_frequency(float lux) {
    float frequency = 0.5 + (lux - 1000.0) / 1000.0 * 4.5; // 0.5Hz to 5Hz
    if (frequency < 0.5) frequency = 0.5;
    if (frequency > 5.0) frequency = 5.0;
    gpioSetPWMfrequency(LED_GPIO, (int)frequency * 1000); // pigpio uses Hz
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    gpioWrite(LED_GPIO, 0); // Turn off LED
    gpioSetMode(LED_GPIO, PI_INPUT); // Set back to input
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer lux_buffer;
    init_circular_buffer(&lux_buffer);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        float lux;
        if (read_bh1750(&lux) == 0) {
            add_to_buffer(&lux_buffer, lux);
            set_led_frequency(lux);
            printf("Lux: %.2f\n", lux);
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }
        gpioDelay(SLEEP_DURATION_SEC * 1000); // Sleep for 1 second
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

