#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define DATA_PIN 17
#define CLOCK_PIN 18
#define LATCH_PIN 27

// Define segment patterns for digits 0-9
const unsigned char digit_patterns[10] = {
    0b00111111, // 0
    0b00000110, // 1
    0b01011011, // 2
    0b01001111, // 3
    0b01100110, // 4
    0b01101101, // 5
    0b01111101, // 6
    0b00000111, // 7
    0b01111111, // 8
    0b01101111  // 9
};

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(DATA_PIN, PI_OUTPUT);
    gpioSetMode(CLOCK_PIN, PI_OUTPUT);
    gpioSetMode(LATCH_PIN, PI_OUTPUT);

    return 0;
}

// Function to shift out a byte of data to the 74HC595
void shift_out(unsigned char data) {
    for (int i = 0; i < 8; i++) {
        gpioWrite(DATA_PIN, (data >> (7 - i)) & 1);
        gpioWrite(CLOCK_PIN, 1);
        gpioWrite(CLOCK_PIN, 0);
    }
}

// Function to latch the data to the 74HC595
void latch_data() {
    gpioWrite(LATCH_PIN, 1);
    gpioWrite(LATCH_PIN, 0);
}

// Function to display a digit on the 74HC595
void display_digit(int digit) {
    if (digit < 0 || digit > 9) {
        fprintf(stderr, "Invalid digit: %d\n", digit);
        return;
    }

    shift_out(digit_patterns[digit]);
    latch_data();
}

// Function to blink a digit on the 74HC595
void blink_digit(int digit, int on_time_ms, int off_time_ms) {
    if (digit < 0 || digit > 9) {
        fprintf(stderr, "Invalid digit: %d\n", digit);
        return;
    }

    for (int i = 0; i < 2; i++) { // Blink twice
        shift_out(digit_patterns[digit]);
        latch_data();
        gpioDelay(on_time_ms * 1000); // Convert ms to microseconds

        shift_out(0x00); // Turn off all segments
        latch_data();
        gpioDelay(off_time_ms * 1000); // Convert ms to microseconds
    }
}

// Function to clean up GPIO pins before exiting
void cleanup_gpio() {
    gpioWrite(DATA_PIN, 0);
    gpioWrite(CLOCK_PIN, 0);
    gpioWrite(LATCH_PIN, 0);
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("74HC595 Display Control\n");

    // Main loop
    while (program_running) {
        // Display digit 5
        display_digit(5);
        gpioDelay(500 * 1000); // 500ms

        // Blink digit 5
        blink_digit(5, 500, 500);
        gpioDelay(500 * 1000); // 500ms
    }

    // Clean up GPIO before exiting
    cleanup_gpio();

    return 0;
}

