}

// Open GPIO chip
int gpio_chip_open(const char *chip_name) {
    chip = gpiod_chip_open_by_name(chip_name);
    if (!chip) {
        perror("Error opening GPIO chip");
        return -1;
    }
    return 0;
}

// Request GPIO line
struct gpiod_line *gpio_line_request(struct gpiod_chip *chip, const char *line_name, unsigned int flags) {
    struct gpiod_line *line = gpiod_chip_get_line(chip, line_name);
    if (!line) {
        perror("Error getting GPIO line");
        return NULL;
    }

    if (gpiod_line_request_output(line, line_name, flags) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_line_release(line);
        return NULL;
    }

    if (gpiod_line_request_input(line, line_name, flags) < 0) {
        perror("Error requesting GPIO line as input");
        gpiod_line_release(line);
        return NULL;
    }

    return line;
}

// Set GPIO line value
int gpio_line_set_value(struct gpiod_line *line, int value) {
    if (gpiod_line_set_value(line, value) < 0) {
        perror("Error setting GPIO line value");
        return -1;
    }
    return 0;
}

// Get GPIO line value
int gpio_line_get_value(struct gpiod_line *line) {
    int value = gpiod_line_get_value(line);
    if (value < 0) {
        perror("Error getting GPIO line value");
        return -1;
    }
    return value;
}

