int gpio_line_release(struct gpiod_line *line) {
    if (gpiod_line_release(line) < 0) {
        perror("Error releasing GPIO line");
        return -1;
    }
    return 0;
}

// Close GPIO chip
int gpio_chip_close(struct gpiod_chip *chip) {
    if (gpiod_chip_close(chip) < 0) {
        perror("Error closing GPIO chip");
        return -1;
    }
    return 0;
}

