    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Open GPIO chip
    if (gpio_chip_open(GPIOCHIP_NAME) < 0) {
        return 1;
    }

    // Request GPIO lines
    led_line = gpio_line_request(chip, LED_LINE, 0);
    button_line = gpio_line_request(chip, BUTTON_LINE, GPIOD_LINE_REQUEST_DIRECTION_INPUT);

    if (!led_line || !button_line) {
        gpio_chip_close(chip);
        return 1;
    }

    // Main loop
    while (1) {
        // Blink LED
        if (gpio_line_set_value(led_line, 1) < 0) {
            gpio_chip_close(chip);
            return 1;
        }
        usleep(2000000); // 2 seconds

        if (gpio_line_set_value(led_line, 0) < 0) {
            gpio_chip_close(chip);
            return 1;
        }
        usleep(2000000); // 2 seconds

        // Wait for button press
        int button_value = gpio_line_get_value(button_line);
        if (button_value < 0) {
            gpio_chip_close(chip);
            return 1;
        }

        if (button_value == 0) {
            printf("Button pressed!\n");
            break; // Exit the loop after button press
        }
    }

    // Cleanup (should not reach here if button is pressed)
    gpio_line_set_value(led_line, 0);
    gpio_line_release(led_line);
    gpio_line_release(button_line);
    gpio_chip_close(chip);

    return 0;
}

