#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the GPIO pin connected to the LED
#define LED_PIN 5

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set the GPIO pin as an output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("LED blinking started. Press Ctrl+C to exit.\n");

    // Main loop to blink the LED
    while (program_running) {
        // Turn the LED on
        gpioWrite(LED_PIN, 1);
        printf("LED ON\n");
        fflush(stdout); // Ensure the output is printed immediately

        // Wait for 750 milliseconds
        gpioDelay(750000); // pigpioDelay takes microseconds

        // Turn the LED off
        gpioWrite(LED_PIN, 0);
        printf("LED OFF\n");
        fflush(stdout); // Ensure the output is printed immediately

        // Wait for 750 milliseconds
        gpioDelay(750000); // pigpioDelay takes microseconds
    }

    // Clean up and exit
    gpioWrite(LED_PIN, 0); // Ensure LED is off before exiting
    gpioTerminate(); // Terminate the pigpio library
    printf("pigpio terminated.\n");
    return 0; // Exit successfully
}

