void blink_led(int duration_ms) {
    gpioWrite(LED_PIN, 1); // Turn LED on
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
    gpioWrite(LED_PIN, 0); // Turn LED off
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
}

