#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for RGB LED
#define RED_PIN   24
#define GREEN_PIN 23
#define BLUE_PIN  18

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 100) {
        fprintf(stderr, "Error: Duty cycle value must be between 0 and 100.\n");
        return -1;
    }

    // Calculate the PWM period (1000000 microseconds / 100 Hz)
    int pwm_period = 1000000 / 100;

    // Calculate the PWM pulse width (duty_cycle * period / 100)
    int pwm_pulse_width = (duty_cycle * pwm_period) / 100;

    // Set the PWM duty cycle
    gpioPWM(gpio_pin, pwm_pulse_width);

    return 0;
}

// Function to generate a random RGB color
void generate_random_color(int *red, int *green, int *blue) {
    *red   = rand() % 101;
    *green = rand() % 101;
    *blue  = rand() % 101;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN, PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN, PI_OUTPUT);

    // Seed the random number generator with the current time
    srand(time(NULL));

    // Register the signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("RGB LED control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Generate a random RGB color
        int red, green, blue;
        generate_random_color(&red, &green, &blue);

        // Set the PWM duty cycles for each colour
        if (set_pwm_duty_cycle(RED_PIN, red) != 0) {
            fprintf(stderr, "Error setting red duty cycle.\n");
        }
        if (set_pwm_duty_cycle(GREEN_PIN, green) != 0) {
            fprintf(stderr, "Error setting green duty cycle.\n");
        }
        if (set_pwm_duty_cycle(BLUE_PIN, blue) != 0) {
            fprintf(stderr, "Error setting blue duty cycle.\n");
        }

        // Wait for 100 milliseconds
        struct timespec sleep_time;
        sleep_time.tv_sec = 0;
        sleep_time.tv_nsec = 100000000; // 100 milliseconds
        nanosleep(&sleep_time, NULL);
    }

    // Clean up GPIO pins before exiting
    gpioWrite(RED_PIN, 0);
    gpioWrite(GREEN_PIN, 0);
    gpioWrite(BLUE_PIN, 0);
    gpioTerminate();

    printf("RGB LED control program stopped.\n");

    return 0;
}

