// LSM303DLHC I2C addresses
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR 0x1E

// LSM303DLHC register addresses
#define CTRL_REG1_A 0x20
#define CTRL_REG4_A 0x23
#define OUT_X_L_A 0x28
#define OUT_X_H_A 0x29
#define OUT_Y_L_A 0x2A
#define OUT_Y_H_A 0x2B
#define OUT_Z_L_A 0x2C
#define OUT_Z_H_A 0x2D
#define CRA_REG_M 0x00
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Y_H_M 0x05
#define OUT_Y_L_M 0x06
#define OUT_Z_H_M 0x07
#define OUT_Z_L_M 0x08

// GPIO pin for impact interrupt
#define IMPACT_PIN 17

// Default impact threshold (G)
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle_accel = -1;
int i2c_handle_mag = -1;
double impact_threshold = DEFAULT_THRESHOLD;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_lsm303();
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z);
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
double calculate_magnitude(int16_t x, int16_t y, int16_t z);
void trigger_impact_interrupt();
void log_data(int16_t x, int16_t y, int16_t z, double magnitude);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

int main(int argc, char *argv[]) {
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                impact_threshold = atof(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-t threshold]\n", argv[0]);
                return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(IMPACT_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_lsm303() != 0) {
        fprintf(stderr, "LSM303 initialisation failed\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    accelerometer_data_t accel_data;
    magnetometer_data_t mag_data;
    double magnitude;

    // Main loop
    while (!terminate) {
        // Read accelerometer data
        if (read_accelerometer(&accel_data.x, &accel_data.y, &accel_data.z) != 0) {
            fprintf(stderr, "Failed to read accelerometer data\n");
        }

        // Read magnetometer data
        if (read_magnetometer(&mag_data.x, &mag_data.y, &mag_data.z) != 0) {
            fprintf(stderr, "Failed to read magnetometer data\n");
        }

        // Calculate magnitude
        magnitude = calculate_magnitude(accel_data.x, accel_data.y, accel_data.z);

        // Log data
        log_data(accel_data.x, accel_data.y, accel_data.z, magnitude);

        // Check for impact
        if (magnitude > impact_threshold) {
            trigger_impact_interrupt();
        }

        // Delay
        gpioDelay(10000); // 10 ms
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle_accel);
    i2cClose(i2c_handle_mag);
    gpioTerminate();

    return 0;
}

// Initialize LSM303DLHC accelerometer and magnetometer
int init_lsm303() {
    // Initialize accelerometer
    i2c_handle_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0);
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Failed to open I2C device for accelerometer: %d\n", i2c_handle_accel);
        return -1;
    }

    // Configure accelerometer: 100 Hz, +/- 2g
    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG1_A, 0x57) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1_A\n");
        i2cClose(i2c_handle_accel);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle_accel, CTRL_REG4_A, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4_A\n");
        i2cClose(i2c_handle_accel);
        return -1;
    }

    // Initialize magnetometer
    i2c_handle_mag = i2cOpen(1, LSM303_MAG_ADDR, 0);
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Failed to open I2C device for magnetometer: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        return -1;
    }

    // Configure magnetometer: 80 Hz, +/- 1.3 Gauss
    if (i2cWriteByteData(i2c_handle_mag, CRA_REG_M, 0x14) < 0) {
        fprintf(stderr, "Failed to write to CRA_REG_M\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        return -1;
    }

    if (i2cWriteByteData(i2c_handle_mag, MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Failed to write to MR_REG_M\n");
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        return -1;
    }

    return 0;
}

// Read accelerometer data
int read_accelerometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle_accel, OUT_X_L_A | 0x80, buffer, 6); // Enable auto-increment

    if (result != 6) {
        fprintf(stderr, "Failed to read accelerometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *y = (int16_t)((buffer[3] << 8) | buffer[2]);
    *z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    int result = i2cReadI2CBlockData(i2c_handle_mag, OUT_X_H_M, buffer, 6);

    if (result != 6) {
        fprintf(stderr, "Failed to read magnetometer data: %d\n", result);
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *y = (int16_t)((buffer[2] << 8) | buffer[3]);
    *z = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Calculate G-force magnitude
double calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    double x_g = (double)x / 16384.0; // Sensitivity for +/- 2g range
    double y_g = (double)y / 16384.0;
    double z_g = (double)z / 16384.0;

    return sqrt(x_g * x_g + y_g * y_g + z_g * z_g);
}

// Trigger impact interrupt
void trigger_impact_interrupt() {
    gpioWrite(IMPACT_PIN, 1); // Set GPIO HIGH
    gpioDelay(50000);        // Wait 50 ms
    gpioWrite(IMPACT_PIN, 0); // Set GPIO LOW
}

// Log data to file
void log_data(int16_t x, int16_t y, int16_t z, double magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, X: %d, Y: %d, Z: %d, Magnitude: %.2f\n", timestamp, x, y, z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Received signal %d, terminating...\n", signal);
    terminate = 1;
}

