#include <unistd.h>

// Constants
#define I2C_BUS 1
#define ADPD188BI_ADDR 0x39
#define ALS_LSB_REG 0x00
#define ALS_MSB_REG 0x01
#define RED_LSB_REG 0x02
#define RED_MSB_REG 0x03
#define GREEN_LSB_REG 0x04
#define GREEN_MSB_REG 0x05
#define BLUE_LSB_REG 0x06
#define BLUE_MSB_REG 0x07
#define LED_GPIO 18
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 1000
#define SAMPLE_INTERVAL_MS 500
#define RETRY_DELAY_MS 100

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_pigpio();
int initialize_i2c();
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue);
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue);
void control_led(uint16_t als);
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    uint16_t als;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} sensor_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        fprintf(stderr, "Failed to initialize pigpio. Exiting.\n");
        return 1;
    }

    // Initialize I2C
    if (initialize_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("color_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,ALS,Red,Green,Blue\n");
    }
    rewind(log_file);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data.als, &sensor_data.red, &sensor_data.green, &sensor_data.blue) == 0) {
            // Log data
            if (log_data(sensor_data.als, sensor_data.red, sensor_data.green, sensor_data.blue) != 0) {
                fprintf(stderr, "Failed to log data.\n");
            }

            // Control LED
            control_led(sensor_data.als);
        } else {
            fprintf(stderr, "Failed to read sensor data.\n");
        }

        // Delay
        gpioDelay(SAMPLE_INTERVAL_MS * 1000); // pigpioDelay takes microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    return 0;
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, ADPD188BI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return 1;
    }
    return 0;
}

// Read sensor data from ADPD188BI
int read_sensor_data(uint16_t *als, uint16_t *red, uint16_t *green, uint16_t *blue) {
    char buf[8];
    int result;

    // Read ALS data
    result = i2cReadI2CBlockData(i2c_handle, ALS_LSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read ALS data: %d\n", result);
        return 1;
    }
    *als = (buf[1] << 8) | buf[0];

    // Read Red data
    result = i2cReadI2CBlockData(i2c_handle, RED_LSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read Red data: %d\n", result);
        return 1;
    }
    *red = (buf[1] << 8) | buf[0];

    // Read Green data
    result = i2cReadI2CBlockData(i2c_handle, GREEN_LSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read Green data: %d\n", result);
        return 1;
    }
    *green = (buf[1] << 8) | buf[0];

    // Read Blue data
    result = i2cReadI2CBlockData(i2c_handle, BLUE_LSB_REG, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read Blue data: %d\n", result);
        return 1;
    }
    *blue = (buf[1] << 8) | buf[0];

    return 0;
}

// Log data to CSV file
int log_data(uint16_t als, uint16_t red, uint16_t green, uint16_t blue) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u\n", timestamp, als, red, green, blue);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Control LED brightness based on ALS value
void control_led(uint16_t als) {
    // Map ALS value to PWM duty cycle (0-1000)
    int duty_cycle = (int)(((float)als / 65535.0) * PWM_RANGE); // Assuming ALS range is 0-65535

    // Set PWM duty cycle
    gpioPWM(LED_GPIO, duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Received signal %d, terminating...\n", signal);
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");

    // Close I2C connection
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Turn off LED
    gpioPWM(LED_GPIO, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();
}

