#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// FXOS8700CQ I2C address
#define FXOS8700CQ_ADDR 0x1F

// FXOS8700CQ register addresses
#define FXOS8700CQ_CTRL_REG1 0x2A
#define FXOS8700CQ_OUT_X_MSB 0x01
#define FXOS8700CQ_WHO_AM_I 0x0D

// Impact threshold (in g)
#define IMPACT_THRESHOLD 2.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int init_i2c();
int init_sensor();
accelerometer_data_t read_accelerometer_data();
float calculate_magnitude(accelerometer_data_t data);
void log_impact(accelerometer_data_t data, float magnitude);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, FXOS8700CQ_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize the FXOS8700CQ sensor
int init_sensor() {
    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, FXOS8700CQ_WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Failed to read WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }

    if (who_am_i != 0xC7) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0xC7\n", who_am_i);
        return -1;
    }

    // Set CTRL_REG1 to active mode, 200 Hz data rate, ±2g range
    if (i2cWriteByteData(i2c_handle, FXOS8700CQ_CTRL_REG1, 0x01 | (0x02 << 2)) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data from the sensor
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, FXOS8700CQ_OUT_X_MSB, buf, 6) != 6) {
        fprintf(stderr, "Failed to read accelerometer data\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    data.x = (int16_t)((buf[0] << 8) | buf[1]);
    data.y = (int16_t)((buf[2] << 8) | buf[3]);
    data.z = (int16_t)((buf[4] << 8) | buf[5]);

    return data;
}

// Calculate the magnitude of the acceleration vector
float calculate_magnitude(accelerometer_data_t data) {
    float x = (float)data.x / 4096.0f; // Convert to g
    float y = (float)data.y / 4096.0f;
    float z = (float)data.z / 4096.0f;

    return sqrt(x * x + y * y + z * z);
}

// Log impact data to a file
void log_impact(accelerometer_data_t data, float magnitude) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%d,%d,%d,%.3f\n", timestamp, data.x, data.y, data.z, magnitude);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() != 0) {
        cleanup();
        return 1;
    }

    // Open the log file
    log_file = fopen("impact_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    fprintf(stderr, "Impact detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        float magnitude = calculate_magnitude(data);

        if (magnitude > IMPACT_THRESHOLD) {
            log_impact(data, magnitude);
            fprintf(stderr, "Impact detected! Magnitude: %.3f g\n", magnitude);
        }

        gpioDelay(50000); // 50 ms delay
    }

    // Cleanup and exit
    cleanup();
    fprintf(stderr, "Exiting.\n");
    return 0;
}

