#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define SAMPLE_RATE_HZ 20
#define SAMPLE_PERIOD_MS (1000 / SAMPLE_RATE_HZ)
#define CALIBRATION_SAMPLES 100
#define ALERT_THRESHOLD_DPS 50.0
#define LOG_FILE "gyro_log.txt"

// L3G4200D Registers
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
gyro_data_t calibrate_gyro(int samples);
gyro_data_t apply_calibration(gyro_data_t raw_data, gyro_data_t zero_offsets);
void log_data(gyro_data_t calibrated_data);
void check_alert(gyro_data_t calibrated_data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    // Wake up the gyroscope (set CTRL_REG1 to 0x0F)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F) < 0) {
        fprintf(stderr, "Error: Could not wake up gyroscope.\n");
        return -1;
    }

    // Set data rate to 20 Hz (set CTRL_REG1 to 0x1F)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x1F) < 0) {
        fprintf(stderr, "Error: Could not set data rate.\n");
        return -1;
    }

    // Set full-scale range to +/- 250 dps (set CTRL_REG4 to 0x00)
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Error: Could not set full-scale range.\n");
        return -1;
    }

    return 0;
}

// Read raw gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t raw_data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data.\n");
        raw_data.x = 0.0;
        raw_data.y = 0.0;
        raw_data.z = 0.0;
        return raw_data;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to degrees per second (dps)
    raw_data.x = (float)x / 14.375; // Sensitivity: 14.375 LSB/dps
    raw_data.y = (float)y / 14.375;
    raw_data.z = (float)z / 14.375;

    return raw_data;
}

// Calibrate the gyroscope
gyro_data_t calibrate_gyro(int samples) {
    gyro_data_t zero_offsets = {0.0, 0.0, 0.0};
    gyro_data_t raw_data;

    for (int i = 0; i < samples; i++) {
        raw_data = read_gyro_data();
        zero_offsets.x += raw_data.x;
        zero_offsets.y += raw_data.y;
        zero_offsets.z += raw_data.z;
        gpioDelay(SAMPLE_PERIOD_MS); // Delay for the sample period
    }

    zero_offsets.x /= samples;
    zero_offsets.y /= samples;
    zero_offsets.z /= samples;

    return zero_offsets;
}

// Apply calibration offsets
gyro_data_t apply_calibration(gyro_data_t raw_data, gyro_data_t zero_offsets) {
    gyro_data_t calibrated_data;
    calibrated_data.x = raw_data.x - zero_offsets.x;
    calibrated_data.y = raw_data.y - zero_offsets.y;
    calibrated_data.z = raw_data.z - zero_offsets.z;
    return calibrated_data;
}

// Log data to file
void log_data(gyro_data_t calibrated_data) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f\n", timestamp, calibrated_data.x, calibrated_data.y, calibrated_data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check for alert conditions
void check_alert(gyro_data_t calibrated_data) {
    if (fabs(calibrated_data.x) > ALERT_THRESHOLD_DPS ||
        fabs(calibrated_data.y) > ALERT_THRESHOLD_DPS ||
        fabs(calibrated_data.z) > ALERT_THRESHOLD_DPS) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[30];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

        fprintf(stderr, "ALERT: %s, X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n", timestamp, calibrated_data.x, calibrated_data.y, calibrated_data.z);
        fprintf(log_file, "ALERT: %s, X: %.2f dps, Y: %.2f dps, Z: %.2f dps\n", timestamp, calibrated_data.x, calibrated_data.y, calibrated_data.z);
        fflush(log_file);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus (%d).\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Verify WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error: Could not read WHO_AM_I register.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }
    if (who_am_i != 0x49) {
        fprintf(stderr, "Error: Incorrect WHO_AM_I value: 0x%02X (expected 0x49).\n", who_am_i);
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() < 0) {
        fprintf(stderr, "Error: Gyroscope initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Calibrate the gyroscope
    gyro_data_t zero_offsets = calibrate_gyro(CALIBRATION_SAMPLES);
    printf("Calibration complete. Zero offsets: X=%.2f, Y=%.2f, Z=%.2f\n", zero_offsets.x, zero_offsets.y, zero_offsets.z);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        // Read raw gyroscope data
        gyro_data_t raw_data = read_gyro_data();

        // Apply calibration offsets
        gyro_data_t calibrated_data = apply_calibration(raw_data, zero_offsets);

        // Log data
        log_data(calibrated_data);

        // Check for alert conditions
        check_alert(calibrated_data);

        // Delay for the sample period
        gpioDelay(SAMPLE_PERIOD_MS);
    }

    // Cleanup
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

