#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATA_FORMAT 0x31
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37

// Full resolution mode and ±2g range
#define DATA_FORMAT_FULL_RES 0x08
#define DATA_FORMAT_FULL_RES_2G 0x00

// GPIO pin for LED
#define LED_PIN 17

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int adxl345_init();
accelerometer_data_t read_accelerometer_data();
void log_data(accelerometer_data_t data);
void control_led(accelerometer_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the ADXL345 accelerometer
int adxl345_init() {
    // Set data format register
    if (i2cWriteByteData(i2c_handle, DATA_FORMAT, DATA_FORMAT_FULL_RES | DATA_FORMAT_FULL_RES_2G) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Set power control register to measure mode
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data
accelerometer_data_t read_accelerometer_data() {
    accelerometer_data_t data;
    char raw_data[6];

    // Read 6 bytes of data (X0, X1, Y0, Y1, Z0, Z1)
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, raw_data, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g units (assuming +/- 2g range)
    data.x = (float)x / 256.0;
    data.y = (float)y / 256.0;
    data.z = (float)z / 256.0;

    return data;
}

// Log data to file
void log_data(accelerometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED based on acceleration magnitude
void control_led(accelerometer_data_t data) {
    float magnitude = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);

    if (magnitude > 2.0) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "ADXL345 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set LED pin as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("accel_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data();
        log_data(data);
        control_led(data);
        gpioDelay(100000); // 100ms delay (10Hz sampling rate)
    }

    // Cleanup
    fclose(log_file);
    i2cClose(i2c_handle);
    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();

    return 0;
}

