#include <math.h>
#include <pigpio.h>

// LSM303DLHC I2C addresses
#define LSM303_ACCEL_ADDR 0x19
#define LSM303_MAG_ADDR 0x1E

// LSM303DLHC register addresses
#define LSM303_ACCEL_CTRL_REG1_A 0x20
#define LSM303_ACCEL_OUT_X_L_A 0x28
#define LSM303_MAG_MR_REG_M 0x02
#define LSM303_MAG_OUT_X_H_M 0x03

// Sensitivity values (adjust based on your sensor's configuration)
#define ACCEL_SENSITIVITY 0.000061 // +/- 2g, 16-bit
#define MAG_SENSITIVITY 0.00014   // +/- 4 gauss, 16-bit

// Global variables
int i2c_handle_accel = -1;
int i2c_handle_mag = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function prototypes
int init_lsm303();
sensor_data_t read_accelerometer();
sensor_data_t read_magnetometer();
float calculate_heading(sensor_data_t accel_data, sensor_data_t mag_data);
void log_data(float heading, sensor_data_t accel_data, sensor_data_t mag_data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the LSM303DLHC sensors
int init_lsm303() {
    // Initialize accelerometer
    i2c_handle_accel = i2cOpen(1, LSM303_ACCEL_ADDR, 0); // Bus 1, address 0x19, no flags
    if (i2c_handle_accel < 0) {
        fprintf(stderr, "Error opening accelerometer I2C device: %d\n", i2c_handle_accel);
        return -1;
    }

    // Configure accelerometer: 100 Hz, +/- 2g
    if (i2cWriteByteData(i2c_handle_accel, LSM303_ACCEL_CTRL_REG1_A, 0x27) < 0) {
        fprintf(stderr, "Error writing to accelerometer CTRL_REG1_A: %d\n", i2c_handle_accel);
        i2cClose(i2c_handle_accel);
        return -1;
    }

    // Initialize magnetometer
    i2c_handle_mag = i2cOpen(1, LSM303_MAG_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle_mag < 0) {
        fprintf(stderr, "Error opening magnetometer I2C device: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        return -1;
    }

    // Configure magnetometer: Continuous conversion mode, +/- 4 gauss
    if (i2cWriteByteData(i2c_handle_mag, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        fprintf(stderr, "Error writing to magnetometer MR_REG_M: %d\n", i2c_handle_mag);
        i2cClose(i2c_handle_accel);
        i2cClose(i2c_handle_mag);
        return -1;
    }

    return 0;
}

// Read accelerometer data
sensor_data_t read_accelerometer() {
    sensor_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle_accel, LSM303_ACCEL_OUT_X_L_A, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data: %d\n", i2c_handle_accel);
        data.x = 0.0; data.y = 0.0; data.z = 0.0; // Return zeroed data on error
        return data;
    }

    // Combine high and low bytes, convert to g
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    data.x = (float)x * ACCEL_SENSITIVITY;
    data.y = (float)y * ACCEL_SENSITIVITY;
    data.z = (float)z * ACCEL_SENSITIVITY;

    return data;
}

// Read magnetometer data
sensor_data_t read_magnetometer() {
    sensor_data_t data;
    char buffer[6];

