#define VL6180X_REG_IDENTIFICATION_MODEL_ID  0x000
#define VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET 0x016
#define VL6180X_REG_SYSTEM_MODE_GPIO1 0x010
#define VL6180X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO 0x014
#define VL6180X_REG_SYSRANGE_START 0x018
#define VL6180X_REG_RESULT_RANGE_VAL 0x062
#define VL6180X_REG_SYSTEM_INTERRUPT_CLEAR 0x015

// GPIO pin for interrupt
#define INTERRUPT_PIN 4

// File to log distance readings
#define LOG_FILE "distance_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int vl6180x_init();
int vl6180x_read_distance();
void log_distance(int distance);
void signal_handler(int signal);

// Structure to hold sensor configuration
typedef struct {
    int i2c_address;
    int interrupt_pin;
    char *log_file_name;
} sensor_config_t;

// Function to initialize the VL6180X sensor
int vl6180x_init() {
    // Check sensor ID
    int sensor_id = i2cReadByteData(i2c_handle, VL6180X_REG_IDENTIFICATION_MODEL_ID);
    if (sensor_id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", sensor_id);
        return -1;
    }
    if (sensor_id != 0xEA) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X\n", sensor_id);
        return -1;
    }

    // Reset the sensor
    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_FRESH_OUT_OF_RESET, 0x01) < 0) {
        fprintf(stderr, "Error resetting sensor\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure GPIO1 for interrupt
    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_MODE_GPIO1, 0x01) < 0) {
        fprintf(stderr, "Error configuring GPIO1\n");
        return -1;
    }

    // Configure interrupt configuration
    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSTEM_INTERRUPT_CONFIG_GPIO, 0x02) < 0) {
        fprintf(stderr, "Error configuring interrupt configuration\n");
        return -1;
    }

    // Start continuous ranging
    if (i2cWriteByteData(i2c_handle, VL6180X_REG_SYSRANGE_START, 0x01) < 0) {
        fprintf(stderr, "Error starting ranging\n");
        return -1;
    }

    return 0;
}

// Function to read the distance from the VL6180X sensor
int vl6180x_read_distance() {
    int distance = i2cReadByteData(i2c_handle, VL6180X_REG_RESULT_RANGE_VAL);
    if (distance < 0) {
        fprintf(stderr, "Error reading distance\n");
        return -1;
    }
    return distance;
}

// Function to log the distance to a file
void log_distance(int distance) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, Distance: %d mm\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, VL6180X_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the VL6180X sensor
    if (vl6180x_init() < 0) {
        fprintf(stderr, "VL6180X initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Set up interrupt handler
    gpioSetMode(INTERRUPT_PIN, PI_INPUT);
    gpioSetAlertFuncEx(INTERRUPT_PIN, NULL, NULL); // Use NULL callback for simplicity

    printf("VL6180X sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int distance = vl6180x_read_distance();
        if (distance >= 0) {
            log_distance(distance);

            if (distance < 100) {
                fprintf(log_file, "DOOR_OPEN\n");
                fflush(log_file);
            } else {
                fprintf(log_file, "DOOR_CLOSED\n");
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Failed to read distance, retrying...\n");
        }

        gpioDelay(100); // Sample every 100ms
    }

    // Clean up
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

