FILE *fp;
volatile sig_atomic_t running = 1;

// Structure to hold IMU data
typedef struct {
    double timestamp;
    double gyro_x;
    double gyro_y;
    double gyro_z;
    double accel_x;
    double accel_y;
    double accel_z;
} imu_data_t;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data);
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data);
int adis16488_init(int handle);
imu_data_t read_imu_data(int handle);
void log_imu_data(FILE *fp, imu_data_t data);
void cleanup();
void signal_handler(int signal);

// SPI Read Function
int spi_read_register(int handle, uint8_t reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the command to read from the specified register
    tx_buf[0] = 0x00; // MSB of command (read)
    tx_buf[1] = reg_addr | 0x80; // Register address (MSB = 1 for read)
    tx_buf[2] = 0x00; // Dummy byte for reading

    if (spiXfer(handle, tx_buf, rx_buf, 3) != 3) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    // Combine the received bytes to form the 16-bit data
    *data = ((uint16_t)rx_buf[1] << 8) | (uint16_t)rx_buf[2];

    return 0;
}

// SPI Write Function
int spi_write_register(int handle, uint8_t reg_addr, uint16_t data) {
    char tx_buf[3];

    // Construct the command to write to the specified register
    tx_buf[0] = 0x02; // MSB of command (write)
    tx_buf[1] = reg_addr & 0x7F; // Register address (MSB = 0 for write)
    tx_buf[2] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[3] = data & 0xFF; // LSB of data

    if (spiXfer(handle, tx_buf, NULL, 4) != 4) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

