#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// ADIS16448 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCL_OUT 0x0A
#define YACCL_OUT 0x0C
#define ZACCL_OUT 0x0E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    float gyro_x;
    float gyro_y;
    float gyro_z;
    float accel_x;
    float accel_y;
    float accel_z;
} imu_data_t;

// Function Prototypes
int spi_init();
int spi_read_register(uint8_t reg_addr, uint16_t *data);
imu_data_t process_imu_data(uint16_t gyro_x, uint16_t gyro_y, uint16_t gyro_z, uint16_t accel_x, uint16_t accel_y, uint16_t accel_z);
void log_imu_data(imu_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize SPI communication
int spi_init() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error opening SPI device: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Read a single register from the ADIS16448
int spi_read_register(uint8_t reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the SPI message to send
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte for reading
    tx_buf[2] = 0x00; // Dummy byte for reading

    // Transfer the SPI message
    int result = spiXfer(spi_handle, tx_buf, rx_buf, 3);
    if (result != 3) {
        fprintf(stderr, "Error during SPI transfer: %d\n", result);
        return -1;
    }

    // Extract the 16-bit data from the response
    *data = ((uint16_t)rx_buf[1] << 8) | (uint16_t)rx_buf[2];

    return 0;
}

// Process raw IMU data and convert to physical units
imu_data_t process_imu_data(uint16_t gyro_x, uint16_t gyro_y, uint16_t gyro_z, uint16_t accel_x, uint16_t accel_y, uint16_t accel_z) {
    imu_data_t data;

    // Convert gyroscope data
    data.gyro_x = (float)gyro_x * 0.02;
    data.gyro_y = (float)gyro_y * 0.02;
    data.gyro_z = (float)gyro_z * 0.02;

    // Convert accelerometer data
    data.accel_x = (float)accel_x * 0.00025;
    data.accel_y = (float)accel_y * 0.00025;
    data.accel_z = (float)accel_z * 0.00025;

    return data;
}

// Log IMU data to the console
void log_imu_data(imu_data_t data) {
    printf("Gyro: X=%.2f dps, Y=%.2f dps, Z=%.2f dps | Accel: X=%.4f g, Y=%.4f g, Z=%.4f g\n",
           data.gyro_x, data.gyro_y, data.gyro_z, data.accel_x, data.accel_y, data.accel_z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        uint16_t gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z;

        // Read gyroscope data
        if (spi_read_register(XGYRO_OUT, &gyro_x) != 0) {
            fprintf(stderr, "Error reading gyro X data\n");
        }
        if (spi_read_register(YGYRO_OUT, &gyro_y) != 0) {
            fprintf(stderr, "Error reading gyro Y data\n");
        }
        if (spi_read_register(ZGYRO_OUT, &gyro_z) != 0) {
            fprintf(stderr, "Error reading gyro Z data\n");
        }

        // Read accelerometer data
        if (spi_read_register(XACCL_OUT, &accel_x) != 0) {
            fprintf(stderr, "Error reading accel X data\n");
        }
        if (spi_read_register(YACCL_OUT, &accel_y) != 0) {
            fprintf(stderr, "Error reading accel Y data\n");
        }
        if (spi_read_register(ZACCL_OUT, &accel_z) != 0) {
            fprintf(stderr, "Error reading accel Z data\n");
        }

        // Process IMU data
        imu_data_t imu_data = process_imu_data(gyro_x, gyro_y, gyro_z, accel_x, accel_y, accel_z);

        // Log IMU data
        log_imu_data(imu_data);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close SPI device and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

