#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_DATAX1 0x33
#define ADXL345_DATAY0 0x34
#define ADXL345_DATAY1 0x35
#define ADXL345_DATAZ0 0x36
#define ADXL345_DATAZ1 0x37
#define ADXL345_THRESH_TAP 0x1D
#define ADXL345_OFSX 0x1E
#define ADXL345_OFSY 0x1F
#define ADXL345_OFSZ 0x20
#define ADXL345_DUR 0x21
#define ADXL345_LATENT 0x22
#define ADXL345_WINDOW 0x23
#define ADXL345_THRESH_ACT 0x24
#define ADXL345_THRESH_INACT 0x25
#define ADXL345_TIME_INACT 0x26
#define ADXL345_ACT_INACT_CTL 0x27
#define ADXL345_THRESH_FF 0x28
#define ADXL345_TIME_FF 0x29
#define ADXL345_TAP_AXES 0x2A
#define ADXL345_ACT_TAP_STATUS 0x2B
#define ADXL345_BW_RATE 0x2C
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_INT_ENABLE 0x2E
#define ADXL345_INT_MAP 0x2F
#define ADXL345_INT_SOURCE 0x30
#define ADXL345_DATA_FORMAT 0x31

// GPIO pin for LED
#define LED_PIN 17

// Global variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Function prototypes
int adxl345_init();
int adxl345_read_register(int reg);
int adxl345_write_register(int reg, int value);
int adxl345_read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void control_led(int state);
void log_impact(int16_t x, int16_t y, int16_t z, float magnitude);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function to initialize the ADXL345
int adxl345_init() {
    // Set data format register to full resolution, +/- 2g range
    if (adxl345_write_register(ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register\n");
        return -1;
    }

    // Set bandwidth rate to 100 Hz
    if (adxl345_write_register(ADXL345_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error writing to BW_RATE register\n");
        return -1;
    }

    // Enable measurement mode
    if (adxl345_write_register(ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register\n");
        return -1;
    }

    return 0;
}

// Function to read a single register from the ADXL345
int adxl345_read_register(int reg) {
    int value = wiringPiI2CReadReg8(i2c_fd, reg);
    if (value < 0) {
        fprintf(stderr, "Error reading register 0x%02X: %s\n", reg, strerror(errno));
        return -1;
    }
    return value;
}

// Function to write a single register to the ADXL345
int adxl345_write_register(int reg, int value) {
    int result = wiringPiI2CWriteReg8(i2c_fd, reg, value);
    if (result < 0) {
        fprintf(stderr, "Error writing register 0x%02X with value 0x%02X: %s\n", reg, value, strerror(errno));
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int adxl345_read_acceleration(int16_t *x, int16_t *y, int16_t *z) {
    int x0, x1, y0, y1, z0, z1;

    x0 = adxl345_read_register(ADXL345_DATAX0);
    x1 = adxl345_read_register(ADXL345_DATAX1);
    y0 = adxl345_read_register(ADXL345_DATAY0);
