#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/time.h>
#include <sys/select.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define ADXL345_POWER_CTL 0x2D
#define ADXL345_DATAX0 0x32
#define ADXL345_INT1_ENABLE 0x2E
#define ADXL345_INT1_MAP 0x2F
#define ADXL345_INT1_SOURCE 0x30
#define ADXL345_DATA_FORMAT 0x31
#define ADXL345_BW_RATE 0x2C

// Freefall threshold (in g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (in milliseconds)
#define FREEFALL_DURATION 50

// GPIO pin for INT1
#define INT1_GPIO 17

// Global variables
static int i2c_fd = -1;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int adxl345_init(int i2c_fd);
accelerometer_data_t read_accelerometer_data(int i2c_fd);
void freefall_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data);
void log_data(FILE *fp, accelerometer_data_t data);
void signal_handler(int signal);

// Function to initialize the ADXL345
int adxl345_init(int i2c_fd) {
    // Set data format: full resolution, +/- 2g range
    if (i2cWriteByteData(i2c_fd, ADXL345_DATA_FORMAT, 0x0B) < 0) {
        fprintf(stderr, "Error writing to DATA_FORMAT register: %s\n", strerror(errno));
        return -1;
    }

    // Set bandwidth rate: 100 Hz
    if (i2cWriteByteData(i2c_fd, ADXL345_BW_RATE, 0x0A) < 0) {
        fprintf(stderr, "Error writing to BW_RATE register: %s\n", strerror(errno));
        return -1;
    }

    // Enable measurement mode
    if (i2cWriteByteData(i2c_fd, ADXL345_POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error writing to POWER_CTL register: %s\n", strerror(errno));
        return -1;
    }

    // Enable INT1 interrupt on pin INT1_GPIO
    if (i2cWriteByteData(i2c_fd, ADXL345_INT1_ENABLE, 0x80) < 0) {
        fprintf(stderr, "Error writing to INT1_ENABLE register: %s\n", strerror(errno));
        return -1;
    }

    // Map INT1 to GPIO17
    if (i2cWriteByteData(i2c_fd, ADXL345_INT1_MAP, 0x40) < 0) {
        fprintf(stderr, "Error writing to INT1_MAP register: %s\n", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to read accelerometer data
accelerometer_data_t read_accelerometer_data(int i2c_fd) {
    accelerometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_fd, ADXL345_DATAX0, buffer, 6) < 0) {
        fprintf(stderr, "Error reading accelerometer data: %s\n", strerror(errno));
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to g-force units (assuming +/- 2g range)
    data.x = (float)x / 256.0;
    data.y = (float)y / 256.0;
    data.z = (float)z / 256.0;

    return data;
}

// Interrupt handler for freefall detection
void freefall_interrupt_handler(int gpio, int level, uint32_t tick, void *user_data) {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    time_t nowtime = tv.tv_sec;
    struct tm *nowtm = localtime(&nowtime);
    char tmbuf[64], buf[64];
    strftime(tmbuf, sizeof(tmbuf), "%Y-%m-%d %H:%M:%S", nowtm);
    snprintf(buf, sizeof(buf), "%s.%03d", tmbuf, (int)(tv.tv_usec / 1000));

    accelerometer_data_t data = read_accelerometer_data(i2c_fd);

    if (data.x > -FREEFALL_THRESHOLD && data.x < FREEFALL_THRESHOLD &&
        data.y > -FREEFALL_THRESHOLD && data.y < FREEFALL_THRESHOLD &&
        data.z > -FREEFALL_THRESHOLD && data.z < FREEFALL_THRESHOLD) {

        log_data(log_file, data);
        fflush(log_file); // Ensure data is written to file immediately
    }
}

// Function to log data to a CSV file
void log_data(FILE *fp, accelerometer_data_t data) {
    fprintf(fp, "%s,%.3f,%.3f,%.3f\n", data.x, data.y, data.z);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

