#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <math.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define WHO_AM_I 0x0F

// Accelerometer and gyroscope sensitivity
#define ACCEL_SENSITIVITY 0.061 // mg/LSB for ±2g range
#define GYRO_SENSITIVITY 8.75  // mdps/LSB for ±250 dps range

// Fall detection thresholds
#define FREEFALL_THRESHOLD 0.2 // g
#define IMPACT_THRESHOLD 2.5  // g
#define IMPACT_WINDOW 1.0    // s

// Global variables
int i2c_handle;
FILE *log_file;
bool running = true;

// Structure to hold sensor data
typedef struct {
    float accel_x;
    float accel_y;
    float accel_z;
    float gyro_x;
    float gyro_y;
    float gyro_z;
} sensor_data_t;

// Function prototypes
int init_lsm6dsr();
int read_sensor_data(sensor_data_t *data);
void log_data(sensor_data_t data);
void fall_detection_state_machine(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Function to initialize the LSM6DSR
int init_lsm6dsr() {
    // Wake up the sensor (set CTRL1_XL to 0x60)
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x60) < 0) {
        fprintf(stderr, "Error: Could not wake up LSM6DSR\n");
        return -1;
    }

    // Set accelerometer range to ±2g (set CTRL1_XL to 0x60)
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x60) < 0) {
        fprintf(stderr, "Error: Could not set accelerometer range\n");
        return -1;
    }

    // Set gyroscope range to ±250 dps (set CTRL2_G to 0x60)
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x60) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *data) {
    char buffer[12];
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 6) < 0) {
        fprintf(stderr, "Error: Could not read accelerometer data\n");
        return -1;
    }
    raw_accel_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_accel_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_accel_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Read gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 6) < 0) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }
    raw_gyro_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_gyro_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_gyro_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw data to g and dps
    data->accel_x = (float)raw_accel_x * ACCEL_SENSITIVITY / 1000.0f;
    data->accel_y = (float)raw_accel_y * ACCEL_SENSITIVITY / 1000.0f;
    data->accel_z = (float)raw_accel_z * ACCEL_SENSITIVITY / 1000.0f;
    data->gyro_x = (float)raw_gyro_x * GYRO_SENSITIVITY / 1000.0f;
    data->gyro_y = (float)raw_gyro_y * GYRO_SENSITIVITY / 1000.0f;
    data->gyro_z = (float)raw_gyro_z * GYRO_SENSITIVITY / 1000.0f;

    return 0;
}

// Function to log data to a CSV file
void log_data(sensor_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f,%.3f,%.3f,%.3f\n",
            timestamp, data.accel_x, data.accel_y, data.accel_z,
            data.gyro_x, data.gyro_y, data.gyro_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Fall detection state machine
void fall_detection_state_machine(sensor_data_t data) {
    static int freefall_count = 0;
    static int impact_count = 0;
    static time_t impact_start_time = 0;

    // Calculate acceleration magnitude
    float magnitude = sqrt(data.accel_x * data.accel_x + data.accel_y * data.accel_y + data.accel_z * data.accel_z);

    // Freefall state
    if (magnitude < FREEFALL_THRESHOLD) {
        freefall_count++;
        if (freefall_count >= 10) { // 10 readings within 100ms
            printf("Fall detected!\n");
            fprintf(log_file, "FALL DETECTED\n");
            fflush(log_file);
            freefall_count = 0; // Reset counter
        }
    } else {
        freefall_count = 0; // Reset counter if not in freefall
    }

    // Impact state
    if (magnitude > IMPACT_THRESHOLD) {
        impact_count++;
        if (impact_count >= 10) { // 10 readings within 100ms
            if (impact_start_time == 0) {
                impact_start_time = time(NULL);
            }
            if (time(NULL) - impact_start_time >= IMPACT_WINDOW) {
                printf("Impact detected!\n");
                fprintf(log_file, "IMPACT DETECTED\n");
                fflush(log_file);
                impact_count = 0; // Reset counter
                impact_start_time = 0;
            }
        }
    } else {
        impact_count = 0; // Reset counter if not in impact
        impact_start_time = 0;
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

// Cleanup function to release resources
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, LSM6DSR_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize LSM6DSR
    if (init_lsm6dsr() < 0) {
        fprintf(stderr, "Error: LSM6DSR initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("motion_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Accel_X,Accel_Y,Accel_Z,Gyro_X,Gyro_Y,Gyro_Z\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    sensor_data_t sensor_data;

    // Main loop
    while (running) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log data
            log_data(sensor_data);

            // Fall detection
            fall_detection_state_machine(sensor_data);
        } else {
            fprintf(stderr, "Error: Failed to read sensor data\n");
        }

        // Delay for 100ms (104 Hz output data rate)
        gpioDelay(100000); // 100000 microseconds = 100 milliseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

