#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define GYRO_ADDR 0x69
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D
#define WHO_AM_I 0x0F
#define SENSITIVITY 0.0875f // 8.75 mdps/LSB
#define SAMPLE_RATE_MS 10
#define RETRY_COUNT 3

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_gyro();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful termination
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the gyroscope
int init_gyro() {
    int retries = 0;
    int status;

    // Verify WHO_AM_I register
    while (retries < RETRY_COUNT) {
        status = i2cReadByteData(i2c_handle, WHO_AM_I);
        if (status == 0xD3) {
            break; // WHO_AM_I value is correct
        } else {
            fprintf(stderr, "Error: WHO_AM_I register returned 0x%02X (attempt %d/%d). Retrying...\n", status, retries + 1, RETRY_COUNT);
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }

    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: WHO_AM_I register read failed after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    // Configure CTRL_REG1: 100 Hz data rate, normal mode
    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG1, 0x0F); // 0x0F = 0b00001111
        if (status == 0) {
            break; // CTRL_REG1 configured successfully
        } else {
            fprintf(stderr, "Error: CTRL_REG1 write failed (attempt %d/%d). Retrying...\n", retries + 1, RETRY_COUNT);
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }

    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: CTRL_REG1 write failed after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    // Configure CTRL_REG4: +/- 250 dps full scale
    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00); // 0x00 = 0b00000000
        if (status == 0) {
            break; // CTRL_REG4 configured successfully
        } else {
            fprintf(stderr, "Error: CTRL_REG4 write failed (attempt %d/%d). Retrying...\n", retries + 1, RETRY_COUNT);
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }

    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: CTRL_REG4 write failed after %d retries.\n", RETRY_COUNT);
        return -1;
    }

    return 0;
}

// Read gyroscope data
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    int16_t raw_x, raw_y, raw_z;
    int status;

    // Read raw X data
    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cReadByteData(i2c_handle, OUT_X_L);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d/%d). Retrying...\n", retries + 1, RETRY_COUNT);
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: I2C read failed after %d retries for OUT_X_L.\n", RETRY_COUNT);
        data.x = 0.0f; // Set to 0.0 to avoid using uninitialized data
    } else {
        raw_x = (int16_t)((status << 8) | i2cReadByteData(i2c_handle, OUT_X_H));
    }

    // Read raw Y data
    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cReadByteData(i2c_handle, OUT_Y_L);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d/%d). Retrying...\n", retries + 1, RETRY_COUNT);
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: I2C read failed after %d retries for OUT_Y_L.\n", RETRY_COUNT);
        data.y = 0.0f; // Set to 0.0 to avoid using uninitialized data
    } else {
        raw_y = (int16_t)((status << 8) | i2cReadByteData(i2c_handle, OUT_Y_H));
    }

    // Read raw Z data
    retries = 0;
    while (retries < RETRY_COUNT) {
        status = i2cReadByteData(i2c_handle, OUT_Z_L);
        if (status >= 0) {
            break;
        } else {
            fprintf(stderr, "Error: I2C read failed (attempt %d/%d). Retrying...\n", retries + 1, RETRY_COUNT);
            gpioDelay(10000); // 10ms delay
            retries++;
        }
    }
    if (retries == RETRY_COUNT) {
        fprintf(stderr, "Error: I2C read failed after %d retries for OUT_Z_L.\n", RETRY_COUNT);
        data.z = 0.0f; // Set to 0.0 to avoid using uninitialized data
    } else {
        raw_z = (int16_t)((status << 8) | i2cReadByteData(i2c_handle, OUT_Z_H));
    }

    // Convert raw data to degrees per second
    data.x = (float)raw_x * SENSITIVITY;
    data.y = (float)raw_y * SENSITIVITY;
    data.z = (float)raw_z * SENSITIVITY;

    return data;
}

// Log data to CSV file
void log_data(gyro_data_t data) {
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    fprintf(log_file, "%ld.%09ld,%.6f,%.6f,%.6f\n", ts.tv_sec, ts.tv_nsec, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(I2C_BUS, GYRO_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: I2C open failed\n");
        gpioTerminate();
        return 1;
    }

    // Initialize gyroscope
    if (init_gyro() != 0) {
        fprintf(stderr, "Error: Gyroscope initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header to log file if it's a new file
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        gpioDelay(SAMPLE_RATE_MS * 1000); // Delay for 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

