#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define the I2C address of the Omron D7S-0001 sensor
#define D7S_I2C_ADDR 0x1D

// Define the register addresses for X, Y, and Z axes
#define D7S_X_AXIS_REG 0x28
#define D7S_Y_AXIS_REG 0x2A
#define D7S_Z_AXIS_REG 0x2C

// Define the scaling factor for converting raw data to g-force
#define SCALE_FACTOR 0.000244 // 244 mg/LSB

// Define the I2C bus number
#define I2C_BUS 1

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    float x;
    float y;
    float z;
} sensor_data_t;

// Function prototypes
int initialize_i2c();
int read_sensor_data(sensor_data_t *data);
int log_data(sensor_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating gracefully...\n", signal);
}

// Function to initialize the I2C bus
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, D7S_I2C_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data from the Omron D7S-0001
int read_sensor_data(sensor_data_t *data) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    // Read X, Y, and Z axes data
    int bytes_read = i2cReadI2CBlockData(i2c_handle, D7S_X_AXIS_REG, buf, 6);
    if (bytes_read != 6) {
        fprintf(stderr, "Error reading sensor data: %d\n", bytes_read);
        return -1;
    }

    // Combine the two bytes for each axis
    raw_x = (int16_t)((buf[1] << 8) | buf[0]);
    raw_y = (int16_t)((buf[3] << 8) | buf[2]);
    raw_z = (int16_t)((buf[5] << 8) | buf[4]);

    // Convert raw data to g-force units
    data->x = (float)raw_x * SCALE_FACTOR;
    data->y = (float)raw_y * SCALE_FACTOR;
    data->z = (float)raw_z * SCALE_FACTOR;

    return 0;
}

// Function to log data to a CSV file
int log_data(sensor_data_t data) {
    time_t now = time(NULL);
    struct tm *t = gmtime(&now);
    char timestamp[32];

    // Format the timestamp as ISO 8601
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    // Write the data to the CSV file
    fprintf(log_file, "%s,%.6f,%.6f,%.6f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Function to perform cleanup before exiting
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open the CSV file for appending
    log_file = fopen("vibration_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    // Write the header row if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X,Y,Z\n");
    }
    rewind(log_file);

    // Main loop
    sensor_data_t sensor_data;
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Log the data
            log_data(sensor_data);
        } else {
            fprintf(stderr, "Error reading sensor data, skipping logging.\n");
        }

        // Wait for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Perform cleanup before exiting
    cleanup();

    return 0;
}

