int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set GPIO pins as inputs with pull-up resistors
    gpioSetMode(SENSOR_1_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_1_GPIO, PI_PUD_UP);
    gpioSetMode(SENSOR_2_GPIO, PI_INPUT);
    gpioSetPullUpDown(SENSOR_2_GPIO, PI_PUD_UP);

    return 0;
}

// Function to read the value from a sensor
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log sensor data to a file
int log_sensor_data(int sensor_number, int sensor_value) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s.%03ld, Sensor %d: %d\n", timestamp, (long)(t % 1000), sensor_number, sensor_value);
    fclose(fp);
    return 0;
}

// Function to simulate halting the conveyor
void simulate_halting() {
    printf("Halting conveyor due to both sensors detecting logic 1!\n");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

int main() {
    // Register signal handlers for SIGINT and SIGTERM
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Conveyor control system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor values
        int sensor1_value = read_sensor(SENSOR_1_GPIO);
        int sensor2_value = read_sensor(SENSOR_2_GPIO);

        // Log sensor data
        if (log_sensor_data(1, sensor1_value) != 0) {
            fprintf(stderr, "Error logging sensor 1 data!\n");
        }
        if (log_sensor_data(2, sensor2_value) != 0) {
            fprintf(stderr, "Error logging sensor 2 data!\n");
        }

