        if (sensor1_value == 1 && sensor2_value == 1) {
            simulate_halting();
        }

        // Delay for 50 milliseconds
        gpioDelay(50000); // pigpioDelay takes microseconds
    }

    // Release GPIO resources before exiting
    gpioTerminate();

    printf("Conveyor control system stopped.\n");

    return 0;
}

