#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// Define the I2C bus and address
#define I2C_BUS "/dev/i2c-1"
#define MMA8452Q_ADDR 0x1D

// Define MMA8452Q registers
#define MMA8452Q_REG_STATUS 0x00
#define MMA8452Q_REG_OUT_X_MSB 0x01
#define MMA8452Q_REG_OUT_X_LSB 0x02
#define MMA8452Q_REG_OUT_Y_MSB 0x03
#define MMA8452Q_REG_OUT_Y_LSB 0x04
#define MMA8452Q_REG_OUT_Z_MSB 0x05
#define MMA8452Q_REG_OUT_Z_LSB 0x06
#define MMA8452Q_REG_CTRL_REG1 0x2A

// Define tilt threshold (in degrees)
#define TILT_THRESHOLD 45.0

// Define fall log file name
#define FALL_LOG_FILE "fall_log.txt"

// Global variables
int i2c_fd = -1;
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_register(uint8_t reg);
int write_register(uint8_t reg, uint8_t value);
int read_acceleration(int16_t *x, int16_t *y, int16_t *z);
float calculate_tilt(int16_t x, int16_t y, int16_t z);
void log_fall(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

