#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3MDL I2C address
#define LIS3MDL_ADDR 0x1E

// LIS3MDL register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// Calibration constants (example values, adjust based on your sensor)
#define X_OFFSET 0.0
#define Y_OFFSET 0.0
#define Z_OFFSET 0.0
#define X_SCALE 0.146
#define Y_SCALE 0.146
#define Z_SCALE 0.146

// Metal detector threshold (800 mG)
#define METAL_THRESHOLD 800.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} magnetometer_data_t;

// Function prototypes
int init_i2c();
int init_lis3mdl();
magnetometer_data_t read_magnetometer_data();
void apply_calibration(magnetometer_data_t *data);
void convert_to_milliGauss(magnetometer_data_t *data);
void log_data(magnetometer_data_t data);
void check_metal_detector(magnetometer_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

// Initialize I2C communication
int init_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(1, LIS3MDL_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize LIS3MDL magnetometer
int init_lis3mdl() {
    // Configure CTRL_REG1: 100 Hz data rate, enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: ±4 gauss full scale
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read magnetometer data
magnetometer_data_t read_magnetometer_data() {
    magnetometer_data_t data;
    char buffer[6];

    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data\n");
        data.x = 0.0; data.y = 0.0; data.z = 0.0; // Return default values
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert to milliGauss
    data.x = (float)x * X_SCALE - X_OFFSET;
    data.y = (float)y * Y_SCALE - Y_OFFSET;
    data.z = (float)z * Z_SCALE - Z_OFFSET;

    return data;
}

// Apply calibration constants
void apply_calibration(magnetometer_data_t *data) {
    data->x -= X_OFFSET;
    data->y -= Y_OFFSET;
    data->z -= Z_OFFSET;
}

// Convert to milliGauss
void convert_to_milliGauss(magnetometer_data_t *data) {
    data->x *= 1000.0;
    data->y *= 1000.0;
    data->z *= 1000.0;
}

// Log data to file
void log_data(magnetometer_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Check metal detector
void check_metal_detector(magnetometer_data_t data) {
    float total_field = sqrt(data.x * data.x + data.y * data.y + data.z * data.z);
    if (total_field > METAL_THRESHOLD) {
        fprintf(stderr, "Metal Detected! Total Field: %.3f mG\n", total_field);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize LIS3MDL
    if (init_lis3mdl() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("magnetic_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        magnetometer_data_t data = read_magnetometer_data();
        apply_calibration(&data);
        convert_to_milliGauss(&data);
        log_data(data);
        check_metal_detector(data);
        gpioDelay(10000); // 10 ms delay (100 Hz sampling rate)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

