#define ADXL354B_REG_ZDATA_L 0x0C
#define ADXL354B_REG_ZDATA_H 0x0D
#define ADXL354B_REG_STATUS 0x0E
#define ADXL354B_REG_POWER_CTL 0x2D
#define ADXL354B_REG_RESET 0x2C

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int count);
int spi_write_register(int handle, uint8_t reg, uint8_t data);
int adxl354b_reset(int handle);
int adxl354b_init(int handle);
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z);
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// SPI Read Function
int spi_read_register(int handle, uint8_t reg, uint8_t *data, int count) {
    char tx_buf[count + 1];
    char rx_buf[count + 1];

    tx_buf[0] = reg | 0x80; // Set MSB for read operation
    memset(tx_buf + 1, 0, count); // Fill with dummy data for reading

    if (spiXfer(handle, tx_buf, rx_buf, count + 1) != count + 1) {
        fprintf(stderr, "SPI read error\n");
        return -1;
    }

    memcpy(data, rx_buf + 1, count);
    return 0;
}

// SPI Write Function
int spi_write_register(int handle, uint8_t reg, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    tx_buf[0] = reg & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;

    if (spiXfer(handle, tx_buf, rx_buf, 2) != 2) {
        fprintf(stderr, "SPI write error\n");
        return -1;
    }

    return 0;
}

// ADXL354B Reset Function
int adxl354b_reset(int handle) {
    if (spi_write_register(handle, ADXL354B_REG_RESET, 0x52) != 0) {
        fprintf(stderr, "Failed to reset ADXL354B\n");
        return -1;
    }
    gpioDelay(1); // Wait 1 ms
    return 0;
}

// ADXL354B Initialization Function
int adxl354b_init(int handle) {
    // Set data rate to 100 Hz
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x02) != 0) {
        fprintf(stderr, "Failed to set data rate\n");
        return -1;
    }

    // Enable measurement mode
    if (spi_write_register(handle, ADXL354B_REG_POWER_CTL, 0x08) != 0) {
        fprintf(stderr, "Failed to enable measurement mode\n");
        return -1;
    }

    return 0;
}

// ADXL354B Read Acceleration Function
int adxl354b_read_acceleration(int handle, int16_t *x, int16_t *y, int16_t *z) {
    uint8_t data[6];

    if (spi_read_register(handle, ADXL354B_REG_XDATA_L, data, 6) != 0) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    *x = (int16_t)((data[1] << 8) | data[0]);
    *y = (int16_t)((data[3] << 8) | data[2]);
    *z = (int16_t)((data[5] << 8) | data[4]);

    return 0;
}

// Data Logging Function
void log_data(FILE *fp, int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

