        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Verify sensor presence
    uint8_t part_id;
    if (spi_read_register(spi_handle, ADXL354B_REG_PARTID, &part_id, 1) != 0) {
        fprintf(stderr, "Failed to read PARTID, exiting\n");
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    if (part_id != 0x35) {
        fprintf(stderr, "Incorrect PARTID: 0x%02X, expected 0x35\n", part_id);
        fclose(log_file);
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    fprintf(stderr, "ADXL354B initialized successfully\n");

    // Main loop
    while (!terminate) {
        if (adxl354b_read_acceleration(spi_handle, &x, &y, &z) == 0) {
            log_data(log_file, x, y, z);
        } else {
            fprintf(stderr, "Failed to read acceleration data, retrying...\n");
            retries--;
            if (retries <= 0) {
                fprintf(stderr, "Max retries reached, exiting\n");
                break;
            }
        }

        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    fprintf(stderr, "Cleaning up...\n");
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
