#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// ADIS16362 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XACCEL_OUT 0x0A
#define YACCEL_OUT 0x0C
#define ZACCEL_OUT 0x0E
#define SMPL_PRD 0x36
#define SENS_AVG 0x38
#define SENS_ADJ 0x3A
#define SENS_ZERO 0x3C
#define SENS_RANGE 0x3E
#define SENS_BIAS 0x40
#define SENS_TEMP 0x42
#define SENS_ID 0x44
#define SMPL_PRD_REG 0x36
#define SENS_AVG_REG 0x38
#define SENS_ADJ_REG 0x3A
#define SENS_ZERO_REG 0x3C
#define SENS_RANGE_REG 0x3E
#define SENS_BIAS_REG 0x40
#define SENS_TEMP_REG 0x42
#define SENS_ID_REG 0x44

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Global Variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold IMU data
typedef struct {
    double gyro_x;
    double gyro_y;
    double gyro_z;
    double accel_x;
    double accel_y;
    double accel_z;
} imu_data_t;

// Function Prototypes
int initialize_pigpio();
int initialize_spi();
int configure_adis16362();
int read_register(uint8_t reg_addr, uint16_t *data);
int write_register(uint8_t reg_addr, uint16_t data);
imu_data_t read_imu_data();
void log_data(imu_data_t data);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Initialize pigpio library
int initialize_pigpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed: %d\n", spi_handle);
        return -1;
    }
    return 0;
}

// Configure ADIS16362
int configure_adis16362() {
    // Set sample period (adjust as needed)
    if (write_register(SMPL_PRD_REG, 0x000A) != 0) { // 100 Hz
        fprintf(stderr, "Failed to set sample period\n");
        return -1;
    }

    // Set sensor averaging (adjust as needed)
    if (write_register(SENS_AVG_REG, 0x0000) != 0) { // No averaging
        fprintf(stderr, "Failed to set sensor averaging\n");
        return -1;
    }

    // Set sensor bias (adjust as needed)
    if (write_register(SENS_BIAS_REG, 0x0000) != 0) { // No bias
        fprintf(stderr, "Failed to set sensor bias\n");
        return -1;
    }

    // Set sensor range (adjust as needed)
    if (write_register(SENS_RANGE_REG, 0x0000) != 0) { // +/- 2g range
        fprintf(stderr, "Failed to set sensor range\n");
        return -1;
    }

    // Set sensor adjustment (adjust as needed)
    if (write_register(SENS_ADJ_REG, 0x0000) != 0) { // No adjustment
        fprintf(stderr, "Failed to set sensor adjustment\n");
        return -1;
    }

    // Set sensor zero (adjust as needed)
    if (write_register(SENS_ZERO_REG, 0x0000) != 0) { // No zero
        fprintf(stderr, "Failed to set sensor zero\n");
        return -1;
    }

    // Verify sensor ID (optional)
    uint16_t sensor_id;
    if (read_register(SENS_ID_REG, &sensor_id) != 0) {
        fprintf(stderr, "Failed to read sensor ID\n");
        return -1;
    }
    if (sensor_id != 0x3636) {
        fprintf(stderr, "Incorrect sensor ID: 0x%04X\n", sensor_id);
        return -1;
    }

    return 0;
}

// Read a register from the ADIS16362
int read_register(uint8_t reg_addr, uint16_t *data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte
    tx_buf[2] = 0x00; // Dummy byte

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    // Combine the received bytes to form the 16-bit data
    *data = ((uint16_t)rx_buf[1] << 8) | (uint16_t)rx_buf[2];

    return 0;
}

// Write a register to the ADIS16362
int write_register(uint8_t reg_addr, uint16_t data) {
    char tx_buf[3];
    char rx_buf[3];

    // Construct the transmit buffer
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = (data >> 8) & 0xFF; // MSB of data
    tx_buf[2] = data & 0xFF; // LSB of data

    if (spiXfer(spi_handle, tx_buf, rx_buf, 3) != 0) {
        fprintf(stderr, "SPI transfer failed\n");
        return -1;
    }

    return 0;
}

// Read IMU data
imu_data_t read_imu_data() {
    imu_data_t data;
    uint16_t raw_gyro_x, raw_gyro_y, raw_gyro_z, raw_accel_x, raw_accel_y, raw_accel_z;

    // Read raw gyroscope data
    if (read_register(XGYRO_OUT, &raw_gyro_x) != 0) {
        data.gyro_x = 0.0; // Set to 0 on error
    } else {
        data.gyro_x = (double)raw_gyro_x * 0.05; // Convert to degrees/sec
    }
    if (read_register(YGYRO_OUT, &raw_gyro_y) != 0) {
        data.gyro_y = 0.0; // Set to 0 on error
    } else {
        data.gyro_y = (double)raw_gyro_y * 0.05; // Convert to degrees/sec
    }
    if (read_register(ZGYRO_OUT, &raw_gyro_z) != 0) {
        data.gyro_z = 0.0; // Set to 0 on error
    } else {
        data.gyro_z = (double)raw_gyro_z * 0.05; // Convert to degrees/sec
    }

    // Read raw accelerometer data
    if (read_register(XACCEL_OUT, &raw_accel_x) != 0) {
        data.accel_x = 0.0; // Set to 0 on error
    } else {
        data.accel_x = (double)raw_accel_x * 0.0025; // Convert to g
    }
    if (read_register(YACCEL_OUT, &raw_accel_y) != 0) {
        data.accel_y = 0.0; // Set to 0 on error
    } else {
        data.accel_y = (double)raw_accel_y * 0.0025; // Convert to g
    }
    if (read_register(ZACCEL_OUT, &raw_accel_z) != 0) {
        data.accel_z = 0.0; // Set to 0 on error
    } else {
        data.accel_z = (double)raw_accel_z * 0.0025; // Convert to g
    }

    return data;
}

// Log data to CSV file
void log_data(imu_data_t data) {
    time_t rawtime;
    struct timespec ts;
    char timestamp[30];

    clock_gettime(CLOCK_REALTIME, &ts);
    time(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&rawtime));
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%09ld", ts.tv_nsec);

    fprintf(log_file, "%s,%.6f,%.6f,%.6f,%.6f,%.6f,%.6f\n", timestamp, data.gyro_x, data.gyro_y, data.gyro_z, data.accel_x, data.accel_y, data.accel_z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources
void cleanup() {
    if (spi_handle >= 0) {
        spiClose(spi_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize pigpio
    if (initialize_pigpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        cleanup();
        return 1;
    }

    // Configure ADIS16362
    if (configure_adis16362() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("imu_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,X_Gyro,Y_Gyro,Z_Gyro,X_Accel,Y_Accel,Z_Accel\n");
    }
    rewind(log_file);

    // Main loop
    while (!terminate) {
        imu_data_t data = read_imu_data();
        log_data(data);
        gpioDelay(10000); // 10 ms delay (100 Hz sampling)
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

