#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define SENSOR_GPIO 17
#define OBSTACLE_THRESHOLD 0 // Obstacle detected when sensor output is LOW
#define OBSTACLE_THRESHOLD_HIGH 1 // Obstacle detected when sensor output is HIGH
#define OBSTACLE_THRESHOLD_RANGE 30 // cm
#define SELF_PARKING_DURATION 5 // seconds
#define SELF_PARKING_DELAY 2 // seconds
#define SELF_PARKING_RETRIES 3

// Global variables
int spi_fd;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int spi_init();
int read_sensor_data();
int is_obstacle_detected(int sensor_value);
void self_parking_sequence();
void log_message(const char *message);
void signal_handler(int signal);

// SPI initialization function
int spi_init() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    int mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    int bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    int speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to read sensor data from MCP3008 ADC
int read_sensor_data() {
    unsigned char tx_buf[3];
    unsigned char rx_buf[3];

    // MCP3008 command: start bit (1), single-ended (1), channel (3 bits), don't care (3 bits)
    tx_buf[0] = 0x01; // Start bit
    tx_buf[1] = 0x80; // Single-ended, channel 0
    tx_buf[2] = 0x00; // Don't care

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 3,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) < 1) {
        perror("Error sending SPI message");
        return -1;
    }

    // Extract ADC value (10 bits)
    int adc_value = ((rx_buf[1] & 0x03) << 8) + rx_buf[2];
    return adc_value;
}

// Function to check if an obstacle is detected based on the sensor value
int is_obstacle_detected(int sensor_value) {
    return (sensor_value == OBSTACLE_THRESHOLD || sensor_value == OBSTACLE_THRESHOLD_HIGH) ? 1 : 0;
}

// Function to simulate the self-parking sequence
void self_parking_sequence() {
    log_message("Self-parking sequence started");
    sleep(SELF_PARKING_DURATION);
    log_message("Self-parking sequence completed");
}

// Function to log messages with timestamps
void log_message(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    printf("[%s] %s\n", timestamp, message);
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    log_message("Received SIGINT, shutting down...");
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as input
    gpioSetMode(SENSOR_GPIO, PI_INPUT);

    // Initialize SPI
    if (spi_init() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    log_message("Self-parking system started");

    while (program_running) {
        // Read sensor data
        int sensor_value = read_sensor_data();
        if (sensor_value < 0) {
            log_message("Error reading sensor data");
            sleep(1); // Wait before retrying
            continue;
        }

        // Check for obstacle detection
        if (is_obstacle_detected(sensor_value)) {
            log_message("Obstacle detected!");

            // Simulate self-parking sequence
            self_parking_sequence();
        }

        // Delay for 1 second
        sleep(1);
    }

    // Cleanup
    close(spi_fd);
    gpioTerminate();
    log_message("Self-parking system stopped");

    return 0;
}

