#include <unistd.h>
#include <signal.h>
#include <time.h>

// ADIS16266 Register Addresses
#define XGYRO_OUT 0x04
#define YGYRO_OUT 0x06
#define ZGYRO_OUT 0x08
#define XGYRO_OUT_L 0x04
#define YGYRO_OUT_L 0x06
#define ZGYRO_OUT_L 0x08
#define XGYRO_OUT_H 0x05
#define YGYRO_OUT_H 0x07
#define ZGYRO_OUT_H 0x09
#define XGYRO_SCALE 0x36
#define YGYRO_SCALE 0x38
#define ZGYRO_SCALE 0x3A
#define XGYRO_CONF 0x32
#define YGYRO_CONF 0x34
#define ZGYRO_CONF 0x36
#define XGYRO_STATUS 0x3E
#define YGYRO_STATUS 0x40
#define ZGYRO_STATUS 0x42
#define XMAG_OUT 0x0A
#define YMAG_OUT 0x0C
#define ZMAG_OUT 0x0E
#define XMAG_OUT_L 0x0A
#define YMAG_OUT_L 0x0C
#define ZMAG_OUT_L 0x0E
#define XMAG_OUT_H 0x0B
#define YMAG_OUT_H 0x0D
#define ZMAG_OUT_H 0x0F
#define XMAG_SCALE 0x3C
#define YMAG_SCALE 0x3E
#define ZMAG_SCALE 0x40
#define XMAG_CONF 0x38
#define YMAG_CONF 0x3A
#define ZMAG_CONF 0x3C
#define XMAG_STATUS 0x44
#define YMAG_STATUS 0x46
#define ZMAG_STATUS 0x48
#define XACCL_OUT 0x10
#define YACCL_OUT 0x12
#define ZACCL_OUT 0x14
#define XACCL_OUT_L 0x10
#define YACCL_OUT_L 0x12
#define ZACCL_OUT_L 0x14
#define XACCL_OUT_H 0x11
#define YACCL_OUT_H 0x13
#define ZACCL_OUT_H 0x15
#define XACCL_SCALE 0x30
#define YACCL_SCALE 0x32
#define ZACCL_SCALE 0x34
#define XACCL_CONF 0x28
#define YACCL_CONF 0x2A
#define ZACCL_CONF 0x2C
#define XACCL_STATUS 0x4A
#define YACCL_STATUS 0x4C
#define ZACCL_STATUS 0x4E
#define TEMP_OUT 0x16
#define TEMP_OUT_L 0x16
#define TEMP_OUT_H 0x17
#define TEMP_SCALE 0x34
#define TEMP_CONF 0x2E
#define TEMP_STATUS 0x4E
#define SYS_DIAG 0x3E
#define SYS_DIAG_L 0x3E
#define SYS_DIAG_H 0x3F
#define SYS_DIAG_STATUS 0x4E

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 1000000 // 1 MHz
#define SPI_FLAGS 0

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Structure to hold magnetometer data
typedef struct {
    float x;
    float y;
    float z;
} mag_data_t;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accel_data_t;

// Structure to hold temperature data
typedef struct {
    float temperature;
} temp_data_t;

// Function Prototypes
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len);
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data);
gyro_data_t read_gyro_data(int handle);
mag_data_t read_mag_data(int handle);
accel_data_t read_accel_data(int handle);
temp_data_t read_temperature_data(int handle);
void log_data(gyro_data_t gyro, mag_data_t mag, accel_data_t accel, temp_data_t temp);
void signal_handler(int signal);

// Function to read a register from the ADIS16266
int spi_read_register(int handle, uint8_t reg_addr, uint8_t *data, int len) {
    char tx_buf[len + 1];
    char rx_buf[len + 1];

    // Construct the transmit buffer
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    for (int i = 1; i < len + 1; i++) {
        tx_buf[i] = 0x00; // Dummy data for reading
    }

    // Transfer the data
    int result = spiXfer(handle, tx_buf, rx_buf, len + 1);
    if (result != len + 1) {
        fprintf(stderr, "SPI read error: %d\n", result);
        return -1;
    }

    // Copy the received data to the output buffer
    for (int i = 0; i < len; i++) {
        data[i] = rx_buf[i + 1];
    }

    return 0;
}

// Function to write a register to the ADIS16266
int spi_write_register(int handle, uint8_t reg_addr, uint8_t data) {
    char tx_buf[2];
    char rx_buf[2];

    // Construct the transmit buffer
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;

    // Transfer the data
    int result = spiXfer(handle, tx_buf, rx_buf, 2);
    if (result != 2) {
        fprintf(stderr, "SPI write error: %d\n", result);
        return -1;
    }

    return 0;
}

// Function to read gyroscope data
gyro_data_t read_gyro_data(int handle) {
    gyro_data_t gyro;
    uint8_t raw_data[6];

    if (spi_read_register(handle, XGYRO_OUT_L, raw_data, 6) != 0) {
        fprintf(stderr, "Error reading gyro data\n");
        gyro.x = 0.0;
        gyro.y = 0.0;
        gyro.z = 0.0;
        return gyro;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to degrees per second
    gyro.x = (float)x * 0.02;
    gyro.y = (float)y * 0.02;
    gyro.z = (float)z * 0.02;

    return gyro;
}

// Function to read magnetometer data
mag_data_t read_mag_data(int handle) {
    mag_data_t mag;
    uint8_t raw_data[6];

    if (spi_read_register(handle, XMAG_OUT_L, raw_data, 6) != 0) {
        fprintf(stderr, "Error reading mag data\n");
        mag.x = 0.0;
        mag.y = 0.0;
        mag.z = 0.0;
        return mag;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to microteslas (uT)
    mag.x = (float)x * 0.0001;
    mag.y = (float)y * 0.0001;
    mag.z = (float)z * 0.0001;

    return mag;
}

// Function to read accelerometer data
accel_data_t read_accel_data(int handle) {
    accel_data_t accel;
    uint8_t raw_data[6];

    if (spi_read_register(handle, XACCL_OUT_L, raw_data, 6) != 0) {
        fprintf(stderr, "Error reading accel data\n");
        accel.x = 0.0;
        accel.y = 0.0;
        accel.z = 0.0;
        return accel;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((raw_data[1] << 8) | raw_data[0]);
    int16_t y = (int16_t)((raw_data[3] << 8) | raw_data[2]);
    int16_t z = (int16_t)((raw_data[5] << 8) | raw_data[4]);

    // Convert to g (assuming +/- 2g range)
    accel.x = (float)x * 0.0002;
    accel.y = (float)y * 0.0002;
    accel.z = (float)z * 0.0002;

    return accel;
}

// Function to read temperature data
temp_data_t read_temperature_data(int handle) {
    temp_data_t temp;
    uint8_t raw_data[2];

    if (spi_read_register(handle, TEMP_OUT_L, raw_data, 2) != 0) {
        fprintf(stderr, "Error reading temperature data\n");
        temp.temperature = 0.0;
        return temp;
    }

    // Combine high and low bytes
    int16_t temp_raw = (int16_t)((raw_data[1] << 8) | raw_data[0]);

    // Convert to degrees Celsius
    temp.temperature = (float)temp_raw * 0.001;

    return temp;
}

// Function to log data to the console
void log_data(gyro_data_t gyro, mag_data_t mag, accel_data_t accel, temp_data_t temp) {
    printf("Gyro: X=%.2f deg/s, Y=%.2f deg/s, Z=%.2f deg/s\n", gyro.x, gyro.y, gyro.z);
    printf("Mag: X=%.2f uT, Y=%.2f uT, Z=%.2f uT\n", mag.x, mag.y, mag.z);
    printf("Accel: X=%.2f g, Y=%.2f g, Z=%.2f g\n", accel.x, accel.y, accel.z);
    printf("Temp: %.2f C\n", temp.temperature);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        gpioTerminate();
        return 1;
    }

    // Set signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read sensor data
        gyro_data_t gyro = read_gyro_data(spi_handle);
        mag_data_t mag = read_mag_data(spi_handle);
        accel_data_t accel = read_accel_data(spi_handle);
        temp_data_t temp = read_temperature_data(spi_handle);

        // Log the data
        log_data(gyro, mag, accel, temp);

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close SPI channel
    spiClose(spi_handle);

    // Terminate pigpio
    gpioTerminate();

    return 0;
}

