#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LSM6DSR I2C address
#define LSM6DSR_ADDR 0x6B

// LSM6DSR register addresses
#define CTRL1_XL 0x10
#define CTRL2_G 0x11
#define OUTX_L_G 0x22
#define OUTX_H_G 0x23
#define OUTY_L_G 0x24
#define OUTY_H_G 0x25
#define OUTZ_L_G 0x26
#define OUTZ_H_G 0x27
#define OUTX_L_XL 0x28
#define OUTX_H_XL 0x29
#define OUTY_L_XL 0x2A
#define OUTY_H_XL 0x2B
#define OUTZ_L_XL 0x2C
#define OUTZ_H_XL 0x2D
#define WHO_AM_I 0x0F

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    fprintf(stderr, "\nCaught signal %d, terminating...\n", signal);
}

// Function to initialize the LSM6DSR
int init_lsm6dsr() {
    // Check WHO_AM_I register
    int who_am_i = i2cReadByteData(i2c_handle, WHO_AM_I);
    if (who_am_i < 0) {
        fprintf(stderr, "Error reading WHO_AM_I register: %d\n", who_am_i);
        return -1;
    }
    if (who_am_i != 0x6B) {
        fprintf(stderr, "WHO_AM_I returned 0x%X, expected 0x6B\n", who_am_i);
        return -1;
    }

    // Configure accelerometer: 104 Hz, +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL1_XL, 0x60) < 0) {
        fprintf(stderr, "Error writing to CTRL1_XL register\n");
        return -1;
    }

    // Configure gyroscope: 104 Hz, +/- 250 dps
    if (i2cWriteByteData(i2c_handle, CTRL2_G, 0x60) < 0) {
        fprintf(stderr, "Error writing to CTRL2_G register\n");
        return -1;
    }

    return 0;
}

// Function to read sensor data
int read_sensor_data(sensor_data_t *accel_data, sensor_data_t *gyro_data) {
    char buffer[12];
    int result;

    // Read accelerometer data
    result = i2cReadI2CBlockData(i2c_handle, OUTX_L_XL, buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Error reading sensor data: %d\n", result);
        return -1;
    }

    accel_data->x = (int16_t)((buffer[1] << 8) | buffer[0]);
    accel_data->y = (int16_t)((buffer[3] << 8) | buffer[2]);
    accel_data->z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Read gyroscope data
    result = i2cReadI2CBlockData(i2c_handle, OUTX_L_G, buffer, 12);
    if (result < 0) {
        fprintf(stderr, "Error reading gyroscope data: %d\n", result);
        return -1;
