#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <math.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37

// Tilt threshold (degrees)
#define TILT_THRESHOLD 30.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} accelerometer_data_t;

// Function prototypes
int initialize_adxl345();
accelerometer_data_t read_acceleration_data();
double calculate_tilt_angle(accelerometer_data_t data);
void log_tilt_event(double angle);
void signal_handler(int signal);

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initializes the ADXL345 accelerometer
int initialize_adxl345() {
    // Set POWER_CTL register to start measurement
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not set POWER_CTL register.\n");
        return -1;
    }
    return 0;
}

// Reads acceleration data from the ADXL345
accelerometer_data_t read_acceleration_data() {
    accelerometer_data_t data;
    char buffer[6];

    // Read 6 bytes of data (X0, X1, Y0, Y1, Z0, Z1)
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        data.x = 0; data.y = 0; data.z = 0; // Return zeroed data on error
        return data;
    }

    // Combine high and low bytes for each axis
    data.x = (int16_t)((buffer[1] << 8) | buffer[0]);
    data.y = (int16_t)((buffer[3] << 8) | buffer[2]);
    data.z = (int16_t)((buffer[5] << 8) | buffer[4]);

    return data;
}

// Calculates the tilt angle in degrees
double calculate_tilt_angle(accelerometer_data_t data) {
    // Calculate tilt angle (in degrees)
    double x_angle = atan2(data.y, sqrt(data.x * data.x + data.z * data.z)) * 180 / M_PI;
    double y_angle = atan2(-data.x, sqrt(data.y * data.y + data.z * data.z)) * 180 / M_PI;

    // Return the average of the two angles
    return (x_angle + y_angle) / 2.0;
}

// Logs a tilt event to /var/log/tilt_events.log
void log_tilt_event(double angle) {
    FILE *fp;
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    // Open the log file in append mode
    fp = fopen("/var/log/tilt_events.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        return;
    }

    // Write the log entry
    fprintf(fp, "%s - Tilt angle: %.2f degrees\n", timestamp, angle);

    // Close the log file
    fclose(fp);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C connection
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C connection. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the ADXL345
    if (initialize_adxl345() != 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        // Read acceleration data
        accelerometer_data_t data = read_acceleration_data();

        // Calculate tilt angle
        double angle = calculate_tilt_angle(data);

        // Check if tilt exceeds threshold
        if (fabs(angle) > TILT_THRESHOLD) {
            // Log the tilt event
            log_tilt_event(angle);
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C connection and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

