#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the doors
#define DOOR_A_GPIO 17
#define DOOR_B_GPIO 27

// Define the log file name
#define LOG_FILE "access_log.txt"

// Define the security code length
#define SECURITY_CODE_LENGTH 6

// Define the unlock duration in seconds
#define UNLOCK_DURATION 5

// Global variables
volatile sig_atomic_t program_running = 1;
FILE *log_file = NULL;

// Function prototypes
int generate_security_code(char *code);
int validate_security_code(const char *code, const char *generated_code);
int unlock_door(int gpio_pin);
int log_access(const char *code);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to generate a random security code
int generate_security_code(char *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Invalid security code pointer.\n");
        return -1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Generate a random six-digit number
    for (int i = 0; i < SECURITY_CODE_LENGTH; i++) {
        code[i] = '0' + (rand() % 10);
    }

    code[SECURITY_CODE_LENGTH] = '\0'; // Null-terminate the string
    return 0;
}

// Function to validate the security code
int validate_security_code(const char *code, const char *generated_code) {
    if (code == NULL || generated_code == NULL) {
        fprintf(stderr, "Error: Invalid security code pointer.\n");
        return -1;
    }

    return (strcmp(code, generated_code) == 0);
}

// Function to unlock the door
int unlock_door(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) { // Activate the relay (LOW to HIGH)
        fprintf(stderr, "Error: Failed to activate relay on GPIO %d.\n", gpio_pin);
        return -1;
    }

    gpioDelay(UNLOCK_DURATION * 1000000); // Wait for the unlock duration (in microseconds)

    if (gpioWrite(gpio_pin, 1) != 0) { // Deactivate the relay (HIGH to LOW)
        fprintf(stderr, "Error: Failed to deactivate relay on GPIO %d.\n", gpio_pin);
        return -1;
    }

    return 0;
}

// Function to log the access event
int log_access(const char *code) {
    if (code == NULL) {
        fprintf(stderr, "Error: Invalid security code pointer.\n");
        return -1;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%s\n", timestamp, code);
    fflush(log_file); // Ensure the data is written to the file immediately

    return 0;
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(DOOR_A_GPIO, PI_OUTPUT);
    gpioSetMode(DOOR_B_GPIO, PI_OUTPUT);

    // Initialize both doors to locked state (HIGH)
    gpioWrite(DOOR_A_GPIO, 1);
    gpioWrite(DOOR_B_GPIO, 1);

    // Open the log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file %s.\n", LOG_FILE);
        gpioTerminate(); // Clean up pigpio before exiting
        return 1;
    }

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    char security_code[SECURITY_CODE_LENGTH + 1];
    char user_input[SECURITY_CODE_LENGTH + 1];

    // Main loop
    while (program_running) {
        // Generate the security code
        if (generate_security_code(security_code) != 0) {
            fprintf(stderr, "Error: Failed to generate security code.\n");
            continue; // Skip to the next iteration
        }

        // Print the security code to stdout
        printf("Security Code: %s\n", security_code);

        // Prompt the user for input
        printf("Enter the security code: ");
        if (fgets(user_input, sizeof(user_input), stdin) == NULL) {
            fprintf(stderr, "Error: Failed to read input from stdin.\n");
            continue; // Skip to the next iteration
        }

        // Remove trailing newline character
        user_input[strcspn(user_input, "\n")] = 0;

        // Validate the security code
        if (validate_security_code(user_input, security_code) == 0) {
            // Unlock the door
            if (unlock_door(DOOR_A_GPIO) == 0) {
                printf("Door A unlocked.\n");
            } else {
                fprintf(stderr, "Error: Failed to unlock Door A.\n");
            }

            if (unlock_door(DOOR_B_GPIO) == 0) {
                printf("Door B unlocked.\n");
            } else {
                fprintf(stderr, "Error: Failed to unlock Door B.\n");
            }

            // Log the access event
            if (log_access(security_code) != 0) {
                fprintf(stderr, "Error: Failed to log access event.\n");
            }
        } else {
            // Log the access denied event
            if (log_access(NULL) != 0) {
                fprintf(stderr, "Error: Failed to log access denied event.\n");
            }
            printf("Access denied.\n");
        }

        // Clear the input buffer
        while (getchar() != '\n'); // Clear the input buffer
    }

    // Clean up resources before exiting
    printf("Cleaning up resources...\n");

    // Set both doors to locked state (HIGH)
    gpioWrite(DOOR_A_GPIO, 1);
    gpioWrite(DOOR_B_GPIO, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

