#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define the I2C bus and address
#define I2C_BUS 1
#define BH1750FVI_ADDR 0x23

// Define the measurement command
#define MEASUREMENT_COMMAND 0x10

// Global variables for I2C handle and log file
int i2c_handle = -1;
FILE *log_file = NULL;

// Function prototypes
int initialize_i2c();
int read_bh1750(float *lux);
int log_data(float lux);
void cleanup();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float lux;
    time_t timestamp;
} sensor_data_t;

// Function to initialize the I2C bus
int initialize_i2c() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    i2c_handle = i2cOpen(I2C_BUS, BH1750FVI_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Function to read illuminance from the BH1750FVI sensor
int read_bh1750(float *lux) {
    char buf[2];
    int result;

    // Send the measurement command
    result = i2cWriteByte(i2c_handle, MEASUREMENT_COMMAND);
    if (result != 0) {
        fprintf(stderr, "Failed to write measurement command: %d\n", result);
        return -1;
    }

    // Wait for the measurement to complete (at least 180ms)
    gpioDelay(200000); // 200ms

    // Read two bytes of data
    result = i2cReadDevice(i2c_handle, buf, 2);
    if (result != 2) {
        fprintf(stderr, "Failed to read data: %d\n", result);
        return -1;
    }

    // Convert the data to lux
    uint16_t raw_value = (buf[0] << 8) | buf[1];
    *lux = (float)raw_value / 1.2;

    return 0;
}

// Function to log the data to a file
int log_data(float lux) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];

    // Format the timestamp
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    // Open the log file in append mode
    log_file = fopen("light_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file\n");
        return -1;
    }

    // Write the data to the log file
    fprintf(log_file, "Timestamp: %s, Lux: %.2f\n", timestamp, lux);

    // Close the log file
    fclose(log_file);

    return 0;
}

// Function to cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    // Close the I2C bus
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }

    // Terminate the pigpio library
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

int main() {
    float lux;
    int result;

    // Register the signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize the I2C bus
    if (initialize_i2c() != 0) {
        return 1;
    }

    printf("BH1750FVI sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        // Read illuminance from the sensor
        result = read_bh1750(&lux);
        if (result == 0) {
            // Log the data
            if (log_data(lux) != 0) {
                fprintf(stderr, "Failed to log data\n");
            }
        } else {
            fprintf(stderr, "Failed to read illuminance\n");
        }

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds
    }

    return 0;
}

