    if (i2cWriteByteData(i2c_handle, 0x80, 0x63) < 0) {
        fprintf(stderr, "Error: Soft reset failed\n");
        return -1;
    }
    gpioDelay(100); // Wait for reset to complete

    // Configure electrode sensitivity (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x0A) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x05) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure baseline filtering (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x5B + (i * 2), 0x01) < 0) { // Touch filter
            fprintf(stderr, "Error: Failed to write touch filter for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x5C + (i * 2), 0x01) < 0) { // Release filter
            fprintf(stderr, "Error: Failed to write release filter for electrode %d\n", i);
            return -1;
        }
    }

    // Configure touch and release thresholds for all electrodes
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x41 + (i * 2), 0x0A) < 0) { // Touch threshold
            fprintf(stderr, "Error: Failed to write touch threshold for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x42 + (i * 2), 0x05) < 0) { // Release threshold
            fprintf(stderr, "Error: Failed to write release threshold for electrode %d\n", i);
            return -1;
        }
    }

    // Configure baseline filtering (example values)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, 0x5B + (i * 2), 0x01) < 0) { // Touch filter
            fprintf(stderr, "Error: Failed to write touch filter for electrode %d\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, 0x5C + (i * 2), 0x01) < 0) { // Release filter
            fprintf(stderr, "Error: Failed to write release filter for electrode %d\n", i);
            return -1;
        }
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_handle, 0x5E, 0x0C) < 0) { // Electrode enable register
