    fprintf(log_file, "%s, Frequency: %d Hz\n", timestamp, frequency);
    fflush(log_file); // Ensure data is written to file immediately
}

// Handle client function
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    int valread;

    valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        perror("Error: Receive failed");
        close(client_socket);
        return;
    }

    buffer[valread] = '\0';
    printf("Received: %s\n", buffer);

    if (strncmp(buffer, "MOTION_DETECTED:", 16) == 0) {
        if (strncmp(buffer + 16, SHARED_SECRET, strlen(SHARED_SECRET)) == 0) {
            printf("Authentication successful\n");

            // Play tone
            unsigned short touch_data;
            if (mpr121_read_touch_data(&touch_data) == 0) {
                for (int i = 0; i < 12; i++) {
                    if (touch_data & (1 << i)) {
