// LSM303DLHC I2C addresses
#define LSM303_MAG_ADDR_1 0x1E
#define LSM303_MAG_ADDR_2 0x1D

// LSM303DLHC magnetometer registers
#define LSM303_MAG_CTRL_REG1_A 0x20
#define LSM303_MAG_CTRL_REG2_A 0x21
#define LSM303_MAG_MR_REG_M 0x02
#define LSM303_MAG_OUT_X_H_M 0x03
#define LSM303_MAG_OUT_X_L_M 0x04
#define LSM303_MAG_OUT_Z_H_M 0x05
#define LSM303_MAG_OUT_Z_L_M 0x06
#define LSM303_MAG_OUT_Y_H_M 0x07
#define LSM303_MAG_OUT_Y_L_M 0x08

// LED GPIO pin (BCM numbering)
#define LED_PIN 17

// PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Global variables
static volatile int keepRunning = 1;
static int i2c_fd_1 = -1;
static int i2c_fd_2 = -1;
static FILE *log_file = NULL;

// Function prototypes
int init_lsm303_mag(int fd);
int read_magnetometer_data(int fd, int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
void set_led_brightness(float magnitude);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    keepRunning = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize the LSM303DLHC magnetometer
int init_lsm303_mag(int fd) {
    // Configure magnetometer: 100 Hz output rate, continuous conversion mode
    if (wiringPiI2CWriteReg8(fd, LSM303_MAG_CTRL_REG1_A, 0x70) < 0) {
        log_error("Failed to write to CTRL_REG1_A");
        return -1;
    }

    // Set gain to +/- 4 gauss
    if (wiringPiI2CWriteReg8(fd, LSM303_MAG_CTRL_REG2_A, 0x20) < 0) {
        log_error("Failed to write to CTRL_REG2_A");
        return -1;
    }

    // Set continuous conversion mode
    if (wiringPiI2CWriteReg8(fd, LSM303_MAG_MR_REG_M, 0x00) < 0) {
        log_error("Failed to write to MR_REG_M");
        return -1;
    }

    return 0;
}

// Read magnetometer data from the sensor
