#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Hard-iron calibration offsets
int16_t x_offset = 0, y_offset = 0, z_offset = 0;

// I2C handle
int i2c_handle;

// Running average buffer size
#define BUFFER_SIZE 100

// Running average buffer
int16_t x_buffer[BUFFER_SIZE];
int16_t y_buffer[BUFFER_SIZE];
int16_t z_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int init_i2c();
int read_hmc5883l_data(int16_t *x, int16_t *y, int16_t *z);
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, int16_t *x_offset, int16_t *y_offset, int16_t *z_offset);
void update_running_average(int16_t x, int16_t y, int16_t z);
void print_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, cleaning up...\n", signal);
    i2cClose(i2c_handle);
    gpioTerminate();
    exit(0);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure HMC5883L (8-average, 15 Hz, normal measurement)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_A\n");
        return -1;
    }

    // Configure HMC5883L (Gain = 1.3 Ga)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_CONFIG_B\n");
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to HMC5883L_MODE\n");
        return -1;
    }

    return 0;
}

// Read raw magnetic field data from HMC5883L
int read_hmc5883l_data(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading HMC5883L data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Apply hard-iron offsets to raw data
void apply_hard_iron_offsets(int16_t x, int16_t y, int16_t z, int16_t *x_offset, int16_t *y_offset, int16_t *z_offset) {
    *x -= *x_offset;
    *y -= *y_offset;
    *z -= *z_offset;
}

// Update running average buffer
void update_running_average(int16_t x, int16_t y, int16_t z) {
    x_buffer[buffer_index] = x;
    y_buffer[buffer_index] = y;
    z_buffer[buffer_index] = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;

    int32_t x_sum = 0, y_sum = 0, z_sum = 0;
    for (int i = 0; i < BUFFER_SIZE; i++) {
        x_sum += x_buffer[i];
        y_sum += y_buffer[i];
        z_sum += z_buffer[i];
    }

    x_offset = (int16_t)(x_sum / BUFFER_SIZE);
    y_offset = (int16_t)(y_sum / BUFFER_SIZE);
    z_offset = (int16_t)(z_sum / BUFFER_SIZE);
}

// Print data to stdout
void print_data(int16_t x, int16_t y, int16_t z) {
    printf("X: %d, Y: %d, Z: %d\n", x, y, z);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;

    // Main loop
    while (1) {
        // Read raw data
        if (read_hmc5883l_data(&x, &y, &z) == 0) {
            // Apply hard-iron offsets
            apply_hard_iron_offsets(x, y, z, &x_offset, &y_offset, &z_offset);

            // Update running average
            update_running_average(x, y, z);

            // Print data
            print_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading data, retrying...\n");
        }

        // Delay for 500 milliseconds
        gpioDelay(500000); // 500 ms = 500000 microseconds
    }

    // Cleanup (this part will not be reached in the infinite loop)
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

