#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for solenoids
#define SOLENOID_1_PIN 17
#define SOLENOID_2_PIN 27

// Function prototypes
void activate_solenoid(int gpio_pin);
void deactivate_solenoid(int gpio_pin);
void cleanup(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void cleanup(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);
    gpioTerminate();
    exit(0);
}

// Function to activate a solenoid
void activate_solenoid(int gpio_pin) {
    if (gpioWrite(gpio_pin, 0) != 0) {
        fprintf(stderr, "Error: Failed to write LOW to GPIO %d\n", gpio_pin);
        cleanup(0); // Exit gracefully
    }
}

// Function to deactivate a solenoid
void deactivate_solenoid(int gpio_pin) {
    if (gpioWrite(gpio_pin, 1) != 0) {
        fprintf(stderr, "Error: Failed to write HIGH to GPIO %d\n", gpio_pin);
        cleanup(0); // Exit gracefully
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(SOLENOID_1_PIN, PI_OUTPUT);
    gpioSetMode(SOLENOID_2_PIN, PI_OUTPUT);

    // Ensure solenoids are initially off
    deactivate_solenoid(SOLENOID_1_PIN);
    deactivate_solenoid(SOLENOID_2_PIN);

    // Set up signal handlers for Ctrl+C and SIGTERM
    signal(SIGINT, cleanup);
    signal(SIGTERM, cleanup);

    fprintf(stderr, "Solenoid control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Activate solenoid 1
        activate_solenoid(SOLENOID_1_PIN);
        fprintf(stderr, "Solenoid 1 activated\n");

        // Delay for 500 milliseconds
        struct timespec delay;
        delay.tv_sec = 0;
        delay.tv_nsec = 500000000; // 500 milliseconds
        nanosleep(&delay, NULL);

        // Deactivate solenoid 1
        deactivate_solenoid(SOLENOID_1_PIN);
        fprintf(stderr, "Solenoid 1 deactivated\n");

        // Activate solenoid 2
        activate_solenoid(SOLENOID_2_PIN);
        fprintf(stderr, "Solenoid 2 activated\n");

        // Delay for 500 milliseconds
        nanosleep(&delay, NULL);

        // Deactivate solenoid 2
        deactivate_solenoid(SOLENOID_2_PIN);
        fprintf(stderr, "Solenoid 2 deactivated\n");
    }

    // Cleanup (should not reach here if signal handler works correctly)
    cleanup(0);

    return 0;
}

