int uart_handle0 = -1;
int uart_handle1 = -1;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_uart(const char *port, int baud_rate);
int read_code(int uart_handle, char *code, int timeout_sec);
int compare_codes(const char *code1, const char *code2);
int control_relay(int gpio_pin, int state);
void log_error(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the UART port
int initialize_uart(const char *port, int baud_rate) {
    int handle = serOpen(port, baud_rate, 0); // 0 for default flags
    if (handle < 0) {
        fprintf(stderr, "Error opening UART port %s: %d\n", port, handle);
        return -1;
    }
    return handle;
}

// Function to read a code from the UART port with a timeout
int read_code(int uart_handle, char *code, int timeout_sec) {
    int start_time = time(NULL);
    int bytes_read = 0;

    while (time(NULL) - start_time < timeout_sec && program_running) {
        int c = serReadByte(uart_handle);
        if (c >= 0) {
            code[bytes_read++] = (char)c;
            if (bytes_read >= 6) {
                code[bytes_read] = '\0';
                return 0; // Code received successfully
            }
        } else {
            if (c < 0) {
                fprintf(stderr, "Error reading from UART port: %d\n", c);
                return -1; // Error reading from UART
            }
            // Timeout occurred, no data received
            return -2; // Timeout occurred
        }
        gpioDelay(1000); // Small delay to avoid busy-waiting
    }

    // Timeout occurred or program terminated
    return -2; // Timeout or program termination
}

// Function to compare two codes
int compare_codes(const char *code1, const char *code2) {
    return strcmp(code1, code2) == 0;
}

// Function to control the relay state
int control_relay(int gpio_pin, int state) {
    if (gpioWrite(gpio_pin, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio_pin, state);
        return -1; // Error writing to GPIO
    }
    return 0; // Success
}

// Function to log errors to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

