    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(LOCK1_GPIO, PI_OUTPUT);
    gpioSetMode(LOCK2_GPIO, PI_OUTPUT);

    // Initialize UART ports
    uart_handle0 = initialize_uart(SERIAL_PORT0, BAUD_RATE);
    if (uart_handle0 < 0) {
        gpioTerminate();
        return 1;
    }

    uart_handle1 = initialize_uart(SERIAL_PORT1, BAUD_RATE);
    if (uart_handle1 < 0) {
        serClose(uart_handle0);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock authentication system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        char code1[7] = {0};
        char code2[7] = {0};

        // Read code from port 0
        int read_result0 = read_code(uart_handle0, code1, TIMEOUT_DURATION);
        if (read_result0 == 0) {
            printf("Code from port 0: %s\n", code1);
        } else if (read_result0 == -1) {
            log_error("Error reading code from port 0");
        } else if (read_result0 == -2) {
            printf("Timeout reading code from port 0\n");
        }

        // Read code from port 1
        int read_result1 = read_code(uart_handle1, code2, TIMEOUT_DURATION);
        if (read_result1 == 0) {
            printf("Code from port 1: %s\n", code2);
        } else if (read_result1 == -1) {
            log_error("Error reading code from port 1");
        } else if (read_result1 == -2) {
            printf("Timeout reading code from port 1\n");
        }

        // Check if both codes are received and match
        if (read_result0 == 0 && read_result1 == 0 && compare_codes(code1, code2)) {
            printf("Codes match!\n");

            // Control the relays
            if (control_relay(LOCK1_GPIO, 1) == 0 && control_relay(LOCK2_GPIO, 1) == 0) {
                printf("Locks locked for 2 seconds\n");
                gpioDelay(2000); // Wait for 2 seconds
                if (control_relay(LOCK1_GPIO, 0) == 0 && control_relay(LOCK2_GPIO, 0) == 0) {
                    printf("Locks unlocked\n");
                } else {
                    log_error("Error unlocking locks");
                }
            } else {
                log_error("Error locking locks");
            }
        } else if (read_result0 == 0 && read_result1 == 0 && !compare_codes(code1, code2)) {
            printf("Codes do not match!\n");
        } else if (read_result0 == -2 || read_result1 == -2) {
            // Timeout occurred, do nothing
        } else {
            // Codes not received or error occurred, do nothing
        }

        gpioDelay(100); // Small delay to avoid busy-waiting
    }

    // Clean up and exit
    serClose(uart_handle0);
    serClose(uart_handle1);
    gpioWrite(LOCK1_GPIO, 0); // Ensure locks are unlocked on exit
    gpioWrite(LOCK2_GPIO, 0);
    gpioTerminate();

    printf("Door lock authentication system stopped.\n");
    return 0;
}

