#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <errno.h>
#include <stdbool.h>

// Configuration
#define PIR_GPIO 4
#define RELAY_GPIO 17
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define DOOR_STRIKE_DURATION_MS 1000
#define PIR_TIMEOUT_MS 10000
#define NUM_RETRIES 3

// Global variables
static volatile int running = 1;
static int spi_fd = -1;

// Function prototypes
int gpio_export(int gpio);
int gpio_unexport(int gpio);
int gpio_set_direction(int gpio, const char *direction);
int gpio_read(int gpio);
int gpio_write(int gpio, int value);
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len);
void log_event(const char *message);
void log_warning(const char *message);
void log_shutdown();
void signal_handler(int sig);
int initialize_gpio();
int initialize_spi();
void cleanup_gpio();
void cleanup_spi();

// Function to export a GPIO pin
int gpio_export(int gpio) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/export", O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open /sys/class/gpio/export: %s", strerror(errno));
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        syslog(LOG_ERR, "Failed to write to /sys/class/gpio/export: %s", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to unexport a GPIO pin
int gpio_unexport(int gpio) {
    char buffer[64];
    int fd;

    fd = open("/sys/class/gpio/unexport", O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open /sys/class/gpio/unexport: %s", strerror(errno));
        return -1;
    }
    snprintf(buffer, sizeof(buffer), "%d", gpio);
    if (write(fd, buffer, strlen(buffer)) < 0) {
        syslog(LOG_ERR, "Failed to write to /sys/class/gpio/unexport: %s", strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to set the direction of a GPIO pin (in or out)
int gpio_set_direction(int gpio, const char *direction) {
    char path[64];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/direction", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", path, strerror(errno));
        return -1;
    }
    if (write(fd, direction, strlen(direction)) < 0) {
        syslog(LOG_ERR, "Failed to write to %s: %s", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to read the value of a GPIO pin
int gpio_read(int gpio) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_RDONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", path, strerror(errno));
        return -1;
    }
    if (read(fd, value_str, 3) < 0) {
        syslog(LOG_ERR, "Failed to read from %s: %s", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return atoi(value_str);
}

// Function to write a value to a GPIO pin
int gpio_write(int gpio, int value) {
    char path[64];
    char value_str[3];
    int fd;

    snprintf(path, sizeof(path), "/sys/class/gpio/gpio%d/value", gpio);
    fd = open(path, O_WRONLY);
    if (fd < 0) {
        syslog(LOG_ERR, "Failed to open %s: %s", path, strerror(errno));
        return -1;
    }
    snprintf(value_str, sizeof(value_str), "%d", value);
    if (write(fd, value_str, strlen(value_str)) < 0) {
        syslog(LOG_ERR, "Failed to write to %s: %s", path, strerror(errno));
        close(fd);
        return -1;
    }
    close(fd);
    return 0;
}

// Function to transfer data over SPI
int spi_transfer(unsigned char *tx_buf, unsigned char *rx_buf, int len) {
    struct spi_ioc_transfer transfer[1];

    memset(transfer, 0, sizeof(transfer));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = len;
    transfer[0].speed_hz = SPI_SPEED;
    transfer[0].bits_per_word = SPI_BITS_PER_WORD;
    transfer[0].delay_usecs = 0;
    transfer[0].cs_change = 0;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        syslog(LOG_ERR, "SPI transfer failed: %s", strerror(errno));
        return -1;
    }

    return 0;
}

// Function to log an event to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Function to log a warning to syslog
void log_warning(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_WARNING, "%s: %s", timestamp, message);
}

// Function to log a shutdown event to syslog
void log_shutdown() {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);
    syslog(LOG_ERR, "%s: System shutdown initiated due to PIR timeout.", timestamp);
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    running = 0;
    log_event("Signal received, shutting down...");
}

// Function to initialize GPIO
int initialize_gpio() {
    if (gpio_export(PIR_GPIO) < 0) return -1;
    if (gpio_set_direction(PIR_GPIO, "in") < 0) {
        gpio_unexport(PIR_GPIO);
        return -1;
    }
    if (gpio_export(RELAY_GPIO) < 0) {
        gpio_unexport(PIR_GPIO);
        gpio_unexport(RELAY_GPIO);
        return -1;
    }
    if (gpio_set_direction(RELAY_GPIO, "out") < 0) {
        gpio_unexport(PIR_GPIO);
        gpio_unexport(RELAY_GPIO);
        return -1;
    }
    gpio_write(RELAY_GPIO, 0); // Ensure relay is initially off
    return 0;
}

// Function to initialize SPI
int initialize_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        syslog(LOG_ERR, "Failed to open SPI device %s: %s", SPI_DEVICE, strerror(errno));
        return -1;
    }

    // Set SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        syslog(LOG_ERR, "Failed to set SPI mode: %s", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        syslog(LOG_ERR, "Failed to set bits per word: %s", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Set max speed hz
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        syslog(LOG_ERR, "Failed to set max speed hz: %s", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to cleanup GPIO
void cleanup_gpio() {
    gpio_write(RELAY_GPIO, 0); // Ensure relay is off
    gpio_unexport(PIR_GPIO);
    gpio_unexport(RELAY_GPIO);
}

// Function to cleanup SPI
void cleanup_spi() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
}

int main() {
    // Initialize syslog
    openlog("motion_detector", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() < 0) {
        log_event("GPIO initialization failed, exiting.");
        closelog();
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() < 0) {
        log_event("SPI initialization failed, exiting.");
        cleanup_gpio();
        closelog();
        return 1;
    }

    log_event("Motion detector started.");

    int pir_state = 0; // 0 = no motion, 1 = motion detected
    time_t last_motion_time = 0;

    while (running) {
        int pir_value = gpio_read(PIR_GPIO);
        if (pir_value < 0) {
            log_event("Failed to read PIR sensor value, retrying...");
            sleep(1); // Wait before retrying
            continue;
        }

        if (pir_value == 1) {
            // Motion detected
            if (pir_state == 0) {
                log_event("Motion detected!");
                pir_state = 1;
                last_motion_time = time(NULL);
            }

            // Check for timeout
            if (difftime(time(NULL), last_motion_time) * 1000 > PIR_TIMEOUT_MS) {
                log_warning("PIR timeout, triggering failsafe.");
                gpio_write(RELAY_GPIO, 0); // De-energize relay
                log_event("Failsafe triggered.");
                log_shutdown();
                running = 0; // Exit loop after shutdown
                break;
            }
        } else {
            // No motion
            if (pir_state == 1) {
                pir_state = 0;
            }
        }

        // Door strike
        if (pir_state == 1) {
            unsigned char tx_buf[2] = {0x01, 0x00}; // Example command to activate relay
            unsigned char rx_buf[2] = {0x00, 0x00};
            if (spi_transfer(tx_buf, rx_buf, 2) == 0) {
                log_event("Door strike activated.");
            } else {
                log_warning("SPI transfer failed during door strike.");
            }
            gpio_write(RELAY_GPIO, 1); // Energize relay
            sleep(DOOR_STRIKE_DURATION_MS / 1000); // Wait for duration
            gpio_write(RELAY_GPIO, 0); // De-energize relay
            log_event("Door strike de-activated.");
        }

        usleep(50000); // 50ms delay
    }

    // Cleanup
    cleanup_gpio();
    cleanup_spi();
    log_event("Motion detector stopped.");
    closelog();

    return 0;
}

