#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the number of relays
#define NUM_RELAYS 4

// Define the duration of each irrigation cycle (in seconds)
#define IRRIGATION_CYCLE_DURATION 300

// Define the pause between irrigation cycles (in seconds)
#define IRRIGATION_PAUSE_DURATION 60

// Define the number of seconds to activate each relay
#define RELAY_DURATION 300

// Global variable to track the current relay state
volatile int current_relay_state = 0;

// Global variable to track the current irrigation cycle
volatile int current_irrigation_cycle = 0;

// Global variable to track the program's state
volatile sig_atomic_t program_running = 1;

// Function prototypes
void signal_handler(int signal);
void log_message(int priority, const char *message);
void initialize_gpio();
void cleanup_gpio();
void irrigation_cycle();
void relay_on(int pin);
void relay_off(int pin);

// Signal handler function
void signal_handler(int signal) {
    if (signal == SIGINT || signal == SIGTERM) {
        log_message(LOG_INFO, "Received signal, shutting down...");
        program_running = 0;
    }
}

// Logging function
void log_message(int priority, const char *message) {
    syslog(priority, "%s", message);
    printf("%s\n", message);
}

// Initialize GPIO pins
void initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        exit(EXIT_FAILURE);
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    relay_off(RELAY1_PIN);
    relay_off(RELAY2_PIN);
    relay_off(RELAY3_PIN);
    relay_off(RELAY4_PIN);

    log_message(LOG_INFO, "GPIO pins initialized");
}

// Cleanup GPIO pins
void cleanup_gpio() {
    // Deactivate all relays
    relay_off(RELAY1_PIN);
    relay_off(RELAY2_PIN);
    relay_off(RELAY3_PIN);
    relay_off(RELAY4_PIN);

    // Terminate pigpio
    gpioTerminate();

    log_message(LOG_INFO, "GPIO pins cleaned up");
}

// Irrigation cycle function
void irrigation_cycle() {
    // Activate relay 1
    relay_on(RELAY1_PIN);
    log_message(LOG_INFO, "Relay 1 activated");
    sleep(RELAY_DURATION);
    relay_off(RELAY1_PIN);
    log_message(LOG_INFO, "Relay 1 deactivated");

    // Pause for 1 minute
    sleep(IRRIGATION_PAUSE_DURATION);

    // Activate relay 2
    relay_on(RELAY2_PIN);
    log_message(LOG_INFO, "Relay 2 activated");
    sleep(RELAY_DURATION);
    relay_off(RELAY2_PIN);
    log_message(LOG_INFO, "Relay 2 deactivated");

    // Pause for 1 minute
    sleep(IRRIGATION_PAUSE_DURATION);

    // Activate relay 3
    relay_on(RELAY3_PIN);
    log_message(LOG_INFO, "Relay 3 activated");
    sleep(RELAY_DURATION);
    relay_off(RELAY3_PIN);
    log_message(LOG_INFO, "Relay 3 deactivated");

    // Pause for 1 minute
    sleep(IRRIGATION_PAUSE_DURATION);

    // Activate relay 4
    relay_on(RELAY4_PIN);
    log_message(LOG_INFO, "Relay 4 activated");
    sleep(RELAY_DURATION);
    relay_off(RELAY4_PIN);
    log_message(LOG_INFO, "Relay 4 deactivated");

    // Increment the current irrigation cycle
    current_irrigation_cycle++;

    // Log the irrigation cycle state
    char log_message_buffer[100];
    snprintf(log_message_buffer, sizeof(log_message_buffer), "Irrigation cycle %d complete", current_irrigation_cycle);
    log_message(LOG_INFO, log_message_buffer);
}

// Relay on function
void relay_on(int pin) {
    gpioWrite(pin, 0); // Set LOW to activate the relay
}

// Relay off function
void relay_off(int pin) {
    gpioWrite(pin, 1); // Set HIGH to deactivate the relay
}

int main() {
    // Open syslog
    openlog("irrigation_system", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    initialize_gpio();

    // Main loop
    while (program_running) {
        irrigation_cycle();
    }

    // Cleanup GPIO
    cleanup_gpio();

    // Close syslog
    closelog();

    return 0;
}

