#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>
#include <errno.h>

// MPU6050 I2C address
#define MPU6050_ADDR 0x68

// MPU6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define ACCEL_YOUT_H 0x3D
#define ACCEL_ZOUT_H 0x3F

// Circular buffer size
#define BUFFER_SIZE 100

// Data structure for accelerometer readings
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
    struct timespec timestamp;
} accel_data_t;

// Global variables
int i2c_handle;
accel_data_t accel_buffer[BUFFER_SIZE];
int buffer_index = 0;
int running = 1;
int server_fd;

// Function prototypes
int init_mpu6050();
int read_accel_data(int16_t *x, int16_t *y, int16_t *z);
void store_data(int16_t x, int16_t y, int16_t z);
accel_data_t get_latest_data();
void signal_handler(int signal);
int setup_socket();
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Initialize MPU6050
int init_mpu6050() {
    // Wake up the MPU6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU6050: %s\n", strerror(errno));
        return -1;
    }
    return 0;
}

// Read accelerometer data from MPU6050
int read_accel_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, ACCEL_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read accelerometer data: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Store data in circular buffer
void store_data(int16_t x, int16_t y, int16_t z) {
    clock_gettime(CLOCK_REALTIME, &accel_buffer[buffer_index].timestamp);
    accel_buffer[buffer_index].x = x;
    accel_buffer[buffer_index].y = y;
    accel_buffer[buffer_index].z = z;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Get the most recent data from the circular buffer
accel_data_t get_latest_data() {
    return accel_buffer[buffer_index];
}

// Setup socket for UDP broadcast
int setup_socket() {
    struct sockaddr_in server_addr;

    // Create socket
    server_fd = socket(AF_INET, SOCK_DGRAM, 0);
    if (server_fd < 0) {
        fprintf(stderr, "Error: Could not create socket: %s\n", strerror(errno));
        return -1;
    }

    // Configure server address
    memset(&server_addr, 0, sizeof(server_addr));
    server_addr.sin_family = AF_INET;
    server_addr.sin_addr.s_addr = INADDR_ANY;
    server_addr.sin_port = htons(5000); // Port 5000

    // Bind socket to address
    if (bind(server_fd, (struct sockaddr *)&server_addr, sizeof(server_addr)) < 0) {
        fprintf(stderr, "Error: Could not bind socket: %s\n", strerror(errno));
        close(server_fd);
        return -1;
    }

    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
