// Define GPIO pins for the relays
#define RELAY1_PIN 18
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Function prototypes
void toggle_relay(int gpio_pin);
void cleanup(int signal);

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void cleanup(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up...\n", signal);

    // Turn off all relays
    gpioWrite(RELAY1_PIN, 0);
    gpioWrite(RELAY2_PIN, 0);
    gpioWrite(RELAY3_PIN, 0);
    gpioWrite(RELAY4_PIN, 0);

    // Release GPIO pins
    gpioSetMode(RELAY1_PIN, PI_INPUT); // Set to input to avoid floating
    gpioSetMode(RELAY2_PIN, PI_INPUT);
    gpioSetMode(RELAY3_PIN, PI_INPUT);
    gpioSetMode(RELAY4_PIN, PI_INPUT);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

// Function to toggle a relay
void toggle_relay(int gpio_pin) {
    int current_state = gpioRead(gpio_pin);
    gpioWrite(gpio_pin, !current_state);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Register signal handler for SIGINT
    signal(SIGINT, cleanup);

    // Register signal handler for SIGTERM
    signal(SIGTERM, cleanup);

    // Main loop
    while (program_running) {
        // Toggle relay 1
        toggle_relay(RELAY1_PIN);
        printf("Relay 1 toggled\n");
        gpioDelay(2000); // Wait for 2 seconds

        // Toggle relay 2
        toggle_relay(RELAY2_PIN);
        printf("Relay 2 toggled\n");
        gpioDelay(3000); // Wait for 3 seconds

        // Toggle relay 3
        toggle_relay(RELAY3_PIN);
        printf("Relay 3 toggled\n");
        gpioDelay(5000); // Wait for 5 seconds

        // Toggle relay 4
        toggle_relay(RELAY4_PIN);
        printf("Relay 4 toggled\n");
        gpioDelay(7000); // Wait for 7 seconds
    }

    return 0;
}

