#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define RELAY_PIN 27

// Define constants
#define DEBOUNCE_DELAY_MS 50
#define RELAY_DURATION_S 3
#define LOG_FILE "alarm_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sound_sensor();
int activate_relay();
int log_event();
void cleanup_gpio();
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int sound_sensor_pin;
    int relay_pin;
} gpio_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Ensure relay is initially off

    return 0;
}

// Function to read the sound sensor
int read_sound_sensor() {
    return gpioRead(SOUND_SENSOR_PIN);
}

// Function to activate the relay
int activate_relay() {
    gpioWrite(RELAY_PIN, 1); // Activate relay
    gpioDelay(RELAY_DURATION_S * 1000000); // Wait for relay duration (microseconds)
    gpioWrite(RELAY_PIN, 0); // Deactivate relay
    return 0;
}

// Function to log the event to a file
int log_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s: Sound event detected\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
        return 0;
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }
}

// Function to cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate(); // Terminate pigpio
    if (log_file != NULL) {
        fclose(log_file);
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    printf("Sound sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sound_detected = read_sound_sensor();

        if (sound_detected == 1) {
            printf("Sound detected!\n");
            if (log_event() == 0) {
                printf("Event logged.\n");
            } else {
                fprintf(stderr, "Error logging event.\n");
            }
            activate_relay(); // Activate relay
            gpioDelay(DEBOUNCE_DELAY_MS * 1000); // Debounce delay
        }

        gpioDelay(100000); // Check every 100ms
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Exiting.\n");
    return 0;
}

