#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <sys/file.h>
#include <sys/select.h>

// Configuration
#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B9600
#define I2C_DEVICE "/dev/i2c-1"
#define I2C_ADDRESS 0x48
#define SAMPLE_INTERVAL_MS 5000
#define LOG_FILE "co2_log.json"
#define ERROR_LOG_FILE "co2_error.log"
#define MAX_RETRIES 3
#define TIMEOUT_MS 100

// Global variables
volatile sig_atomic_t program_running = 1;
int uart_fd = -1;
int i2c_fd = -1;
FILE *log_file = NULL;
FILE *error_log_file = NULL;

// Structure to hold sensor data
typedef struct {
    unsigned int timestamp_us;
    float ppm;
    int error_flag;
} sensor_data_t;

// Function prototypes
int init_uart(const char *device, int baud_rate);
int init_i2c(const char *device, int address);
int read_co2_sensor(int fd, float *ppm);
int read_temperature_sensor(int fd, float *temperature);
int read_humidity_sensor(int fd, float *humidity);
int log_data(FILE *fp, sensor_data_t data);
int send_data_to_api(sensor_data_t data);
void signal_handler(int signal);
int calculate_checksum(const unsigned char *data, int len);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize UART
int init_uart(const char *device, int baud_rate) {
    int fd = open(device, O_RDWR | O_NOCTTY | O_SYNC);
    if (fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    struct termios tty;
    if (tcgetattr(fd, &tty) != 0) {
        perror("Error getting termios attributes");
        close(fd);
        return -1;
    }

    cfsetospeed(&tty, baud_rate);
    cfsetispeed(&tty, baud_rate);

    tty.c_cflag |= (CLOCAL | CREAD);    // Enable receiver and set local mode
    tty.c_cflag &= ~CSIZE;             // Clear data size bits
    tty.c_cflag |= CS8;              // 8-bit data
    tty.c_cflag &= ~(PARENB | PARODD); // No parity
    tty.c_cflag &= ~CSTOPB;            // 1 stop bit
    tty.c_cflag &= ~CRTSCTS;           // Disable hardware flow control

    tty.c_iflag &= ~(IXON | IXOFF | IXANY); // Turn off software flow control
    tty.c_iflag &= ~(IGNBRK | BRKINT | PARMRK | ISTRIP | INLCR | IGNCR | ICRNL);
    tty.c_lflag = 0;                        // No signaling chars, no echo, no canonical processing
    tty.c_oflag = 0;                        // No remapping, no delays
    tty.c_cc[VMIN] = 0;                  // Read doesn't block
    tty.c_cc[VTIME] = 5;                 // 0.5 seconds read timeout

    if (tcsetattr(fd, TCSANOW, &tty) != 0) {
        perror("Error setting termios attributes");
        close(fd);
        return -1;
    }

    return fd;
}

// Initialize I2C
int init_i2c(const char *device, int address) {
    int fd = open(device, O_RDWR);
    if (fd == -1) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(fd, I2C_SLAVE, address) < 0) {
        perror("Error setting I2C slave address");
        close(fd);
        return -1;
    }

    return fd;
}

// Read CO2 sensor data
int read_co2_sensor(int fd, float *ppm) {
    unsigned char command[9] = {0x01, 0x86, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x79};
    unsigned char response[9];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        // Send command
        if (write(fd, command, sizeof(command)) != sizeof(command)) {
            perror("Error writing to I2C device");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Wait for response with timeout
        fd_set readfds;
        struct timeval timeout;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        timeout.tv_sec = TIMEOUT_MS / 1000;
        timeout.tv_usec = (TIMEOUT_MS % 1000) * 1000;

        int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

        if (retval == -1) {
            perror("Error in select");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        } else if (retval == 0) {
            fprintf(stderr, "Timeout waiting for response from I2C device\n");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Read response
        bytes_read = read(fd, response, sizeof(response));
        if (bytes_read != sizeof(response)) {
            perror("Error reading from I2C device");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Calculate checksum
        if (calculate_checksum(response, 8) != response[8]) {
            fprintf(stderr, "Checksum mismatch\n");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Extract CO2 value
        unsigned int co2_value = (response[0] << 8) | response[1];
        *ppm = (float)co2_value;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read CO2 sensor after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Read temperature sensor data
int read_temperature_sensor(int fd, float *temperature) {
    unsigned char command[2] = {0xE3, 0x00};
    unsigned char response[2];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        // Send command
        if (write(fd, command, sizeof(command)) != sizeof(command)) {
            perror("Error writing to I2C device");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Wait for response with timeout
        fd_set readfds;
        struct timeval timeout;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        timeout.tv_sec = TIMEOUT_MS / 1000;
        timeout.tv_usec = (TIMEOUT_MS % 1000) * 1000;

        int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

        if (retval == -1) {
            perror("Error in select");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        } else if (retval == 0) {
            fprintf(stderr, "Timeout waiting for response from I2C device\n");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Read response
        bytes_read = read(fd, response, sizeof(response));
        if (bytes_read != sizeof(response)) {
            perror("Error reading from I2C device");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Calculate temperature
        int temperature_raw = (response[0] << 8) | response[1];
        *temperature = -45.0 + (175.0 * (float)temperature_raw / 65535.0);

        return 0; // Success
    }

    fprintf(stderr, "Failed to read temperature sensor after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Read humidity sensor data
int read_humidity_sensor(int fd, float *humidity) {
    unsigned char command[2] = {0xE5, 0x00};
    unsigned char response[2];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        // Send command
        if (write(fd, command, sizeof(command)) != sizeof(command)) {
            perror("Error writing to I2C device");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Wait for response with timeout
        fd_set readfds;
        struct timeval timeout;
        FD_ZERO(&readfds);
        FD_SET(fd, &readfds);

        timeout.tv_sec = TIMEOUT_MS / 1000;
        timeout.tv_usec = (TIMEOUT_MS % 1000) * 1000;

        int retval = select(fd + 1, &readfds, NULL, NULL, &timeout);

        if (retval == -1) {
            perror("Error in select");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        } else if (retval == 0) {
            fprintf(stderr, "Timeout waiting for response from I2C device\n");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Read response
        bytes_read = read(fd, response, sizeof(response));
        if (bytes_read != sizeof(response)) {
            perror("Error reading from I2C device");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Calculate humidity
        int humidity_raw = (response[0] << 8) | response[1];
        *humidity = 100.0 * (float)humidity_raw / 65535.0;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read humidity sensor after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Calculate checksum
int calculate_checksum(const unsigned char *data, int len) {
    unsigned char checksum = 0xFF;
    for (int i = 0; i < len; i++) {
        checksum ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (checksum & 0x80) {
                checksum = (checksum << 1) ^ 0x131; // Polynomial: x^8 + x^5 + x^4 + 1
            } else {
                checksum <<= 1;
            }
        }
    }
    return checksum;
}

// Log data to file
int log_data(FILE *fp, sensor_data_t data) {
    if (fprintf(fp, "{\"timestamp_us\": %u, \"ppm\": %.2f, \"error_flag\": %d}\n", data.timestamp_us, data.ppm, data.error_flag) < 0) {
        perror("Error writing to log file");
        return -1;
    }
    fflush(fp); // Ensure data is written immediately
    return 0;
}

// Send data to API
int send_data_to_api(sensor_data_t data) {
    printf("Sending data to API: {\"timestamp_us\": %u, \"ppm\": %.2f, \"error_flag\": %d}\n", data.timestamp_us, data.ppm, data.error_flag);
    return 0;
}

int main() {
    // Initialize signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    uart_fd = init_uart(UART_DEVICE, BAUD_RATE);
    if (uart_fd == -1) {
        fprintf(stderr, "UART initialization failed\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = init_i2c(I2C_DEVICE, I2C_ADDRESS);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C initialization failed\n");
        close(uart_fd);
        return 1;
    }

    // Open log files
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        close(uart_fd);
        close(i2c_fd);
        return 1;
    }

    error_log_file = fopen(ERROR_LOG_FILE, "a");
    if (error_log_file == NULL) {
        perror("Error opening error log file");
        fclose(log_file);
        close(uart_fd);
        close(i2c_fd);
        return 1;
    }

    float co2_ppm, temperature, humidity;
    sensor_data_t sensor_data;
    struct timespec ts;
    int retries;

    // Main loop
    while (program_running) {
        // Get timestamp
        if (clock_gettime(CLOCK_REALTIME, &ts) == -1) {
            perror("Error getting timestamp");
            sensor_data.error_flag = 1; // Set error flag
        } else {
            sensor_data.timestamp_us = (unsigned int)(ts.tv_sec * 1000000 + ts.tv_nsec / 1000);
        }

        // Read sensor data
        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_co2_sensor(uart_fd, &co2_ppm) == 0) {
                break; // Success
            } else {
                retries++;
                usleep(10000); // Wait before retrying
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read CO2 sensor after %d retries\n", MAX_RETRIES);
            sensor_data.error_flag = 1; // Set error flag
        } else {
            sensor_data.ppm = co2_ppm;
        }

        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_temperature_sensor(i2c_fd, &temperature) == 0) {
                break; // Success
            } else {
                retries++;
                usleep(10000); // Wait before retrying
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read temperature sensor after %d retries\n", MAX_RETRIES);
            sensor_data.error_flag = 1; // Set error flag
        } else {
            sensor_data.temperature = temperature;
        }

        retries = 0;
        while (retries < MAX_RETRIES) {
            if (read_humidity_sensor(i2c_fd, &humidity) == 0) {
                break; // Success
            } else {
                retries++;
                usleep(10000); // Wait before retrying
            }
        }
        if (retries == MAX_RETRIES) {
            fprintf(stderr, "Failed to read humidity sensor after %d retries\n", MAX_RETRIES);
            sensor_data.error_flag = 1; // Set error flag
        } else {
            sensor_data.humidity = humidity;
        }

        // Log data
        if (log_data(log_file, sensor_data) != 0) {
            fprintf(stderr, "Failed to log data\n");
        }

        // Send data to API
        send_data_to_api(sensor_data);

        // Wait for the next sample
        usleep(SAMPLE_INTERVAL_MS * 1000); // Convert milliseconds to microseconds
    }

    // Close resources
    close(uart_fd);
    close(i2c_fd);
    fclose(log_file);
    fclose(error_log_file);

    return 0;
}

