        // Read response
        bytes_read = read(fd, response, sizeof(response));
        if (bytes_read != sizeof(response)) {
            perror("Error reading from I2C device");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Calculate checksum
        if (calculate_checksum(response, 8) != response[8]) {
            fprintf(stderr, "Checksum mismatch\n");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Extract CO2 value
        unsigned int co2_value = (response[0] << 8) | response[1];
        *ppm = (float)co2_value;

        return 0; // Success
    }

    fprintf(stderr, "Failed to read CO2 sensor after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Read temperature sensor data
int read_temperature_sensor(int fd, float *temperature) {
    unsigned char command[2] = {0xE3, 0x00};
    unsigned char response[2];
    int retries = 0;
    int bytes_read;

    while (retries < MAX_RETRIES) {
        // Send command
        if (write(fd, command, sizeof(command)) != sizeof(command)) {
            perror("Error writing to I2C device");
            retries++;
            usleep(10000); // Wait before retrying
            continue;
        }

        // Wait for response with timeout
        fd_set readfds;
        struct timeval timeout;
        FD_ZERO(&readfds);
