#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// HMC5883L I2C address
#define HMC5883L_ADDR 0x1E

// HMC5883L register addresses
#define HMC5883L_CONFIG_A 0x00
#define HMC5883L_CONFIG_B 0x01
#define HMC5883L_MODE 0x02
#define HMC5883L_DATA_X_MSB 0x03
#define HMC5883L_DATA_X_LSB 0x04
#define HMC5883L_DATA_Z_MSB 0x05
#define HMC5883L_DATA_Z_LSB 0x06
#define HMC5883L_DATA_Y_MSB 0x07
#define HMC5883L_DATA_Y_LSB 0x08

// Hard-iron calibration offsets
#define HARD_IRON_X 100.0
#define HARD_IRON_Y -50.0

// Target heading
#define TARGET_HEADING 90.0

// GPIO pin for LED
#define LED_PIN 17

// Circular buffer size
#define BUFFER_SIZE 100

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Circular buffer structure
typedef struct {
    float buffer[BUFFER_SIZE];
    int head;
    int count;
} CircularBuffer;

// Function prototypes
int init_i2c();
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z);
float compensate_heading(int16_t x, int16_t y, float x_offset, float y_offset);
void add_to_buffer(CircularBuffer *buffer, float heading);
float get_average_heading(CircularBuffer *buffer);
void control_led(float average_heading);
void signal_handler(int signal);
void cleanup();

// Initialize the circular buffer
void init_circular_buffer(CircularBuffer *buffer) {
    buffer->head = 0;
    buffer->count = 0;
}

// Add a heading to the circular buffer
void add_to_buffer(CircularBuffer *buffer, float heading) {
    buffer->buffer[buffer->head] = heading;
    buffer->head = (buffer->head + 1) % BUFFER_SIZE;
    if (buffer->count < BUFFER_SIZE) {
        buffer->count++;
    }
}

// Get the average heading from the circular buffer
float get_average_heading(CircularBuffer *buffer) {
    if (buffer->count == 0) {
        return 0.0;
    }

    float sum = 0.0;
    for (int i = 0; i < buffer->count; i++) {
        sum += buffer->buffer[i];
    }
    return sum / buffer->count;
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(1, HMC5883L_ADDR, 0); // Bus 1, address 0x1E, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }

    // Configure HMC5883L (8-average, 15 Hz, normal measurement)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_A, 0x70) < 0) {
        fprintf(stderr, "Error writing to config A\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Configure HMC5883L (Gain = 1.3 Ga)
    if (i2cWriteByteData(i2c_handle, HMC5883L_CONFIG_B, 0xA0) < 0) {
        fprintf(stderr, "Error writing to config B\n");
        i2cClose(i2c_handle);
        return -1;
    }

    // Set continuous measurement mode
    if (i2cWriteByteData(i2c_handle, HMC5883L_MODE, 0x00) < 0) {
        fprintf(stderr, "Error writing to mode register\n");
        i2cClose(i2c_handle);
        return -1;
    }

    return 0;
}

// Read magnetometer data from HMC5883L
int read_hmc5883l(int16_t *x, int16_t *y, int16_t *z) {
    char buffer[6];
    if (i2cReadI2CBlockData(i2c_handle, HMC5883L_DATA_X_MSB, buffer, 6) != 6) {
        fprintf(stderr, "Error reading magnetometer data\n");
        return -1;
    }

    *x = (int16_t)((buffer[0] << 8) | buffer[1]);
    *z = (int16_t)((buffer[2] << 8) | buffer[3]);
    *y = (int16_t)((buffer[4] << 8) | buffer[5]);

    return 0;
}

// Compensate heading using hard-iron offsets
float compensate_heading(int16_t x, int16_t y, float x_offset, float y_offset) {
    float heading = atan2((float)y - y_offset, (float)x - x_offset) * 180 / M_PI;
    if (heading < 0) {
        heading += 360;
    }
    return heading;
}

// Control the LED based on average heading deviation
void control_led(float average_heading) {
    float deviation = fabs(average_heading - TARGET_HEADING);
    if (deviation > 10.0) {
        gpioWrite(LED_PIN, 1); // Turn LED on
    } else {
        gpioWrite(LED_PIN, 0); // Turn LED off
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup resources before exiting
void cleanup() {
    gpioWrite(LED_PIN, 0); // Turn off LED
    i2cClose(i2c_handle);
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO17 as output
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() < 0) {
        gpioTerminate();
        return 1;
    }

    // Initialize circular buffer
    CircularBuffer heading_buffer;
    init_circular_buffer(&heading_buffer);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    int16_t x, y, z;
    float heading, average_heading;

    // Main loop
    while (!terminate) {
        // Read magnetometer data
        if (read_hmc5883l(&x, &y, &z) == 0) {
            // Compensate heading
            heading = compensate_heading(x, y, HARD_IRON_X, HARD_IRON_Y);

            // Add heading to circular buffer
            add_to_buffer(&heading_buffer, heading);

            // Calculate average heading
            average_heading = get_average_heading(&heading_buffer);

            // Control LED
            control_led(average_heading);

            // Print heading and average heading
            printf("Heading: %.2f, Average Heading: %.2f\n", heading, average_heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Retrying...\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

