            duty_cycle_b = PROPORTIONAL_GAIN * (distance_b - motor_b_threshold);
            if (duty_cycle_b < 0) duty_cycle_b = 0;
        }

        // Control motors based on distance
        if (distance_a < FORWARD_THRESHOLD && distance_b < FORWARD_THRESHOLD) {
            set_motor_a_forward(duty_cycle_a);
            set_motor_b_forward(duty_cycle_b);
