void step_motor(int steps) {
    int i, current_step = 0;
    int direction = (steps > 0) ? 1 : -1; // Determine direction based on sign of steps
    steps = abs(steps); // Ensure steps is positive

    for (i = 0; i < steps && program_running; i++) {
        gpioWrite(IN1, step_sequence[current_step][0]);
        gpioWrite(IN2, step_sequence[current_step][1]);
        gpioWrite(IN3, step_sequence[current_step][2]);
        gpioWrite(IN4, step_sequence[current_step][3]);

        current_step += direction;
        if (current_step < 0) current_step = 3;
        if (current_step > 3) current_step = 0;

