#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>
#include <sys/time.h>
#include <sys/stat.h>
#include <sys/types.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Servo GPIO pin
#define SERVO_PIN 18

// PWM frequency (Hz)
#define PWM_FREQUENCY 50

// PWM period (microseconds)
#define PWM_PERIOD (1000000 / PWM_FREQUENCY)

// Servo angle limits (degrees)
#define SERVO_MIN_ANGLE 0
#define SERVO_MAX_ANGLE 180

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int init_mpu6050();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
void set_servo_angle(float pitch);
void log_data(float pitch, float roll, int position);
void signal_handler(int signal);
void cleanup();

// Function to initialize I2C
int init_i2c() {
    char *i2c_device = "/dev/i2c-1";
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Function to initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2c_smbus_write_byte_data(i2c_fd, PWR_MGMT_1, 0) < 0) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }
    return 0;
}

// Function to read raw accelerometer and gyroscope data
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z) {
    char buf[14];
    if (read(i2c_fd, buf, 14) != 14) {
        perror("Error reading data from MPU-6050");
        return -1;
    }

    *accel_x = (int16_t)((buf[0] << 8) | buf[1]);
    *accel_y = (int16_t)((buf[2] << 8) | buf[3]);
    *accel_z = (int16_t)((buf[4] << 8) | buf[5]);
    *gyro_x  = (int16_t)((buf[8] << 8) | buf[9]);
    *gyro_y  = (int16_t)((buf[10] << 8) | buf[11]);
    *gyro_z  = (int16_t)((buf[12] << 8) | buf[13]);

    return 0;
}

// Function to process raw data and calculate pitch and roll
float process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z) {
    // Accelerometer sensitivity scale factor (assuming +/- 2g range)
    float accel_scale = 16384.0f; // Sensitivity scale factor for +/- 2g range

    // Gyroscope sensitivity scale factor (assuming +/- 250 deg/s range)
    float gyro_scale = 131.0f; // Sensitivity scale factor for +/- 250 deg/s range

    // Convert raw accelerometer data to g-force units
    float accel_x_g = (float)accel_x / accel_scale;
    float accel_y_g = (float)accel_y / accel_scale;
    float accel_z_g = (float)accel_z / accel_scale;

    // Convert raw gyroscope data to degrees per second
    float gyro_x_dps = (float)gyro_x / gyro_scale;
    float gyro_y_dps = (float)gyro_y / gyro_scale;
    float gyro_z_dps = (float)gyro_z / gyro_scale;

    // Calculate pitch and roll using accelerometer data
    float pitch = atan2(accel_y_g, accel_z_g) * 180 / M_PI;
    float roll  = atan2(-accel_x_g, sqrt(accel_y_g * accel_y_g + accel_z_g * accel_z_g)) * 180 / M_PI;

    // Apply complementary filter (adjust the weight for desired response)
    static float last_pitch = 0.0f;
    static float last_roll  = 0.0f;
    float alpha = 0.98f; // Adjust this value for desired response

    last_pitch = alpha * last_pitch + (1 - alpha) * pitch;
    last_roll  = alpha * last_roll  + (1 - alpha) * roll;

    return last_pitch;
}

// Function to set servo angle using PWM
void set_servo_angle(float pitch) {
    // Map pitch angle to servo position (0-180 degrees)
    int position = (int)((pitch + 90.0f) / 180.0f * 180.0f);

    // Clamp position to the valid range
    if (position < 0) {
        position = 0;
    } else if (position > 180) {
        position = 180;
    }

    // Calculate PWM duty cycle (50% for 0-180 degrees)
    int duty_cycle = (int)((position / 180.0f) * PWM_PERIOD);

    // Export PWM channel if it doesn't exist
    char export_path[64];
    snprintf(export_path, sizeof(export_path), "/sys/class/pwm/pwmchip2/export");
    int export_fd = open(export_path, O_WRONLY);
    if (export_fd < 0) {
        if (errno == EBUSY) {
            // PWM channel already exported
        } else {
            perror("Error opening PWM export file");
            return;
        }
    } else {
        char channel_str[4];
        snprintf(channel_str, sizeof(channel_str), "%d", 0);
        if (write(export_fd, channel_str, strlen(channel_str)) < 0) {
            perror("Error writing to PWM export file");
            close(export_fd);
            return;
        }
        close(export_fd);
    }

    // Set PWM period
    char period_path[64];
    snprintf(period_path, sizeof(period_path), "/sys/class/pwm/pwmchip2/pwm0/period");
    int period_fd = open(period_path, O_WRONLY);
    if (period_fd < 0) {
        perror("Error opening PWM period file");
        return;
    }
    char period_str[16];
    snprintf(period_str, sizeof(period_str), "%d", PWM_PERIOD);
    if (write(period_fd, period_str, strlen(period_str)) < 0) {
        perror("Error writing to PWM period file");
        close(period_fd);
        return;
    }
    close(period_fd);

    // Set PWM duty cycle
    char duty_cycle_path[64];
    snprintf(duty_cycle_path, sizeof(duty_cycle_path), "/sys/class/pwm/pwmchip2/pwm0/duty_cycle");
    int duty_cycle_fd = open(duty_cycle_path, O_WRONLY);
    if (duty_cycle_fd < 0) {
        perror("Error opening PWM duty cycle file");
        return;
    }
    char duty_cycle_str[16];
    snprintf(duty_cycle_str, sizeof(duty_cycle_str), "%d", duty_cycle);
    if (write(duty_cycle_fd, duty_cycle_str, strlen(duty_cycle_str)) < 0) {
        perror("Error writing to PWM duty cycle file");
        close(duty_cycle_fd);
        return;
    }
    close(duty_cycle_fd);

    // Enable PWM channel
    char enable_path[64];
    snprintf(enable_path, sizeof(enable_path), "/sys/class/pwm/pwmchip2/pwm0/enable");
    int enable_fd = open(enable_path, O_WRONLY);
    if (enable_fd < 0) {
        perror("Error opening PWM enable file");
        return;
    }
    if (write(enable_fd, "1", 1) < 0) {
        perror("Error writing to PWM enable file");
        close(enable_fd);
        return;
    }
    close(enable_fd);
}

// Function to log data to file
void log_data(float pitch, float roll, int position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Disable PWM channel
    char enable_path[64];
    snprintf(enable_path, sizeof(enable_path), "/sys/class/pwm/pwmchip2/pwm0/enable");
    int enable_fd = open(enable_path, O_WRONLY);
    if (enable_fd >= 0) {
        if (write(enable_fd, "0", 1) < 0) {
            perror("Error writing to PWM enable file during cleanup");
        }
        close(enable_fd);
    }

    // Unexport PWM channel
    char unexport_path[64];
    snprintf(unexport_path, sizeof(unexport_path), "/sys/class/pwm/pwmchip2/unexport");
    int unexport_fd = open(unexport_path, O_WRONLY);
    if (unexport_fd >= 0) {
        char channel_str[4];
        snprintf(channel_str, sizeof(channel_str), "%d", 0);
        if (write(unexport_fd, channel_str, strlen(channel_str)) < 0) {
            perror("Error writing to PWM unexport file during cleanup");
        }
        close(unexport_fd);
    }

    // Close I2C device
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU-6050 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("solar_tracker.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch;
    int position;

    // Main loop
    while (program_running) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Process data
            pitch = process_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

            // Set servo angle
            set_servo_angle(pitch);

            // Get servo position (simulated)
            position = (int)((pitch + 90.0f) / 180.0f * 180.0f);

            // Log data
            log_data(pitch, 0.0f, position); // Roll is always 0 for this example
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Delay
        usleep(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

