    if (write(duty_cycle_fd, duty_cycle_str, strlen(duty_cycle_str)) < 0) {
        perror("Error writing to PWM duty cycle file");
        close(duty_cycle_fd);
        return;
    }
    close(duty_cycle_fd);

    // Enable PWM channel
    char enable_path[64];
    snprintf(enable_path, sizeof(enable_path), "/sys/class/pwm/pwmchip2/pwm0/enable");
    int enable_fd = open(enable_path, O_WRONLY);
    if (enable_fd < 0) {
        perror("Error opening PWM enable file");
        return;
    }
    if (write(enable_fd, "1", 1) < 0) {
        perror("Error writing to PWM enable file");
        close(enable_fd);
        return;
    }
    close(enable_fd);
}

// Function to log data to file
void log_data(float pitch, float roll, int position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d\n", timestamp, pitch, roll, position);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup function to release resources
void cleanup() {
    printf("Cleaning up resources...\n");

    // Disable PWM channel
    char enable_path[64];
    snprintf(enable_path, sizeof(enable_path), "/sys/class/pwm/pwmchip2/pwm0/enable");
    int enable_fd = open(enable_path, O_WRONLY);
    if (enable_fd >= 0) {
        if (write(enable_fd, "0", 1) < 0) {
            perror("Error writing to PWM enable file during cleanup");
        }
        close(enable_fd);
    }

    // Unexport PWM channel
    char unexport_path[64];
    snprintf(unexport_path, sizeof(unexport_path), "/sys/class/pwm/pwmchip2/unexport");
    int unexport_fd = open(unexport_path, O_WRONLY);
    if (unexport_fd >= 0) {
        char channel_str[4];
        snprintf(channel_str, sizeof(channel_str), "%d", 0);
        if (write(unexport_fd, channel_str, strlen(channel_str)) < 0) {
            perror("Error writing to PWM unexport file during cleanup");
        }
        close(unexport_fd);
    }

    // Close I2C device
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "MPU-6050 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("solar_tracker.log", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float pitch;
    int position;

    // Main loop
    while (program_running) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Process data
            pitch = process_data(accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z);

            // Set servo angle
            set_servo_angle(pitch);

            // Get servo position (simulated)
            position = (int)((pitch + 90.0f) / 180.0f * 180.0f);

            // Log data
            log_data(pitch, 0.0f, position); // Roll is always 0 for this example
        } else {
            fprintf(stderr, "Failed to read sensor data. Retrying...\n");
        }

        // Delay
        usleep(100000); // 100ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

