#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the fade duration in seconds
#define FADE_DURATION 1800

// Define the PWM frequency
#define PWM_FREQUENCY 100

// Global variables
FILE *schedule_file = NULL;
int running = 1;

// Function prototypes
int read_schedule(const char *filename, struct timespec *sunrise, struct timespec *sunset);
void set_relay_state(int pin, int state);
void fade_in(int pin, int duty_cycle);
void fade_out(int pin, int duty_cycle);
void signal_handler(int signal);

// Function to read the lighting schedule from a file
int read_schedule(const char *filename, struct timespec *sunrise, struct timespec *sunset) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening schedule file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp) != NULL) {
        // Remove trailing newline character
        line[strcspn(line, "\n")] = 0;

        // Parse the line
        char *token = strtok(line, ":");
        if (token == NULL) continue; // Skip empty lines
        char *time_str = strtok(NULL, ":");
        if (time_str == NULL) continue; // Skip lines without time
        char *relay_str = strtok(NULL, ":");
        if (relay_str == NULL) continue; // Skip lines without relay number
        char *state_str = strtok(NULL, ";");
        if (state_str == NULL) continue; // Skip lines without state

        // Parse time
        struct tm timeinfo;
        if (strptime(time_str, "%H:%M:%S", &timeinfo) == NULL) {
            fprintf(stderr, "Error parsing time: %s\n", time_str);
            continue;
        }

        // Parse relay number
        int relay_number = atoi(relay_str);
        if (relay_number < 1 || relay_number > 4) {
            fprintf(stderr, "Invalid relay number: %d\n", relay_number);
            continue;
        }

        // Parse state
        int state = (strcmp(state_str, "on") == 0) ? 1 : 0;

        // Convert time to seconds since midnight
        time_t rawtime = time(NULL);
        struct tm *timeinfo_now = localtime(&rawtime);
        time_t now = timeinfo_now->tm_hour * 3600 + timeinfo_now->tm_min * 60 + timeinfo_now->tm_sec;
        time_t sunrise_time = timeinfo.tm_hour * 3600 + timeinfo.tm_min * 60 + timeinfo.tm_sec;
        time_t sunset_time = sunrise_time + 86400; // Sunset is the next day

        // Determine the correct time for the relay
        if (now < sunrise_time) {
            time_t time_to_sunrise = sunrise_time - now;
            if (time_to_sunrise > 86400) time_to_sunrise -= 86400; // Handle rollover
            sunrise->tv_sec = time_to_sunrise;
            sunrise->tv_nsec = 0;
        } else if (now < sunset_time) {
            sunset->tv_sec = 0;
            sunset->tv_nsec = 0;
        } else {
            time_t time_to_sunset = now - sunset_time;
            if (time_to_sunset > 86400) time_to_sunset -= 86400; // Handle rollover
            sunset->tv_sec = time_to_sunset;
            sunset->tv_nsec = 0;
        }

        // Set the relay state
        set_relay_state(relay_number - 1, state);
    }

    fclose(fp);
    return 0;
}

// Function to set the state of a relay
void set_relay_state(int pin, int state) {
    gpioWrite(pin, state);
}

// Function to fade in a relay
void fade_in(int pin, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(pin, duty_cycle);
}

// Function to fade out a relay
void fade_out(int pin, int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > 100) duty_cycle = 100;

    gpioPWM(pin, 100 - duty_cycle);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = 0;

    // Turn off all relays
    set_relay_state(RELAY1_PIN, 0);
    set_relay_state(RELAY2_PIN, 0);
    set_relay_state(RELAY3_PIN, 0);
    set_relay_state(RELAY4_PIN, 0);

    // Release GPIO resources
    gpioTerminate();

    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Set PWM range (0-100)
    gpioSetPWMrange(RELAY1_PIN, 100);
    gpioSetPWMrange(RELAY2_PIN, 100);
    gpioSetPWMrange(RELAY3_PIN, 100);
    gpioSetPWMrange(RELAY4_PIN, 100);

    // Open the schedule file
    schedule_file = fopen("lighting_schedule.txt", "r");
    if (schedule_file == NULL) {
        perror("Error opening schedule file");
        gpioTerminate();
        return 1;
    }

    // Read the initial schedule
    struct timespec sunrise, sunset;
    if (read_schedule("lighting_schedule.txt", &sunrise, &sunset) != 0) {
        fprintf(stderr, "Failed to read initial schedule. Exiting.\n");
        fclose(schedule_file);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    struct timespec current_time, next_time;
    clock_gettime(CLOCK_REALTIME, &current_time);
    next_time = current_time;

    while (running) {
        // Calculate the next time to read the schedule
        next_time.tv_sec += 1;
        if (next_time.tv_sec > sunset.tv_sec) {
            next_time.tv_sec = sunrise.tv_sec;
            next_time.tv_nsec = 0;
        }

        // Check if the current time is within the sunrise/sunset window
        if (current_time.tv_sec >= sunrise.tv_sec && current_time.tv_sec <= sunset.tv_sec) {
            // Read the schedule
            if (read_schedule("lighting_schedule.txt", &sunrise, &sunset) != 0) {
                fprintf(stderr, "Failed to read schedule. Continuing with previous values.\n");
            }
        }

        // Calculate the time difference between the current time and the next time
        long time_diff_sec = next_time.tv_sec - current_time.tv_sec;
        long time_diff_nsec = next_time.tv_nsec - current_time.tv_nsec;

        if (time_diff_nsec < 0) {
            time_diff_sec--;
            time_diff_nsec += 1000000000;
        }

        // Calculate the fade duration in seconds
        double fade_duration_sec = (double)time_diff_sec + (double)time_diff_nsec / 1000000000.0;

        // Calculate the fade increment
        double fade_increment = (double)100.0 / fade_duration_sec;

        // Calculate the current duty cycle
        int duty_cycle = (int)(fade_increment * (fade_duration_sec - time_diff_sec));

        // Fade in the relays
        fade_in(RELAY1_PIN, duty_cycle);
        fade_in(RELAY2_PIN, duty_cycle);
        fade_in(RELAY3_PIN, duty_cycle);
        fade_in(RELAY4_PIN, duty_cycle);

        // Update the current time
        clock_gettime(CLOCK_REALTIME, &current_time);

        // Wait for the next second
        gpioDelay(1000000); // 1 second
    }

    // Cleanup (should not reach here if signal handler works correctly)
    fclose(schedule_file);
    gpioTerminate();

    return 0;
}

