// Define GPIO pins for RGB LED
#define RED_PIN   17
#define GREEN_PIN 22
#define BLUE_PIN  27

// Define PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the PWM duty cycle for a given GPIO pin
int set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Error: Duty cycle value must be between 0 and 255.\n");
        return -1;
    }

    if (gpioPWM(gpio_pin, duty_cycle) != 0) {
        fprintf(stderr, "Error: Failed to set PWM duty cycle for GPIO %d.\n", gpio_pin);
        return -1;
    }

    return 0;
}

// Function to set the color of the RGB LED using PWM
void set_led_color(float proximity) {
    // Map proximity value (0.0 to 1.0) to PWM duty cycles (0 to 255)
    int red_duty_cycle   = (int)(255.0 * (1.0 - proximity));
    int green_duty_cycle = (int)(255.0 * proximity);
    int blue_duty_cycle  = 0; // Blue is off for sine wave

    // Set PWM duty cycles for each color
    if (set_pwm_duty_cycle(RED_PIN,   red_duty_cycle) != 0) return;
    if (set_pwm_duty_cycle(GREEN_PIN, green_duty_cycle) != 0) return;
    if (set_pwm_duty_cycle(BLUE_PIN,  blue_duty_cycle) != 0) return;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RED_PIN,   PI_OUTPUT);
    gpioSetMode(GREEN_PIN, PI_OUTPUT);
    gpioSetMode(BLUE_PIN,  PI_OUTPUT);

    // Set PWM frequency for all GPIO pins
    gpioSetPWMfrequency(RED_PIN,   PWM_FREQUENCY);
    gpioSetPWMfrequency(GREEN_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(BLUE_PIN,  PWM_FREQUENCY);

    // Register signal handler for SIGINT
    signal(SIGINT, signal_handler);

    printf("RGB LED color transition started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Generate sine wave function for proximity value
        float proximity = sin(2.0 * M_PI * (float)time(NULL) / 10.0); // Period of 10 seconds

        // Set LED color
        set_led_color(proximity);

        // Delay for a short period
        gpioDelay(10000); // 10 ms
    }

    // Turn off the LED before exiting
    set_pwm_duty_cycle(RED_PIN,   0);
    set_pwm_duty_cycle(GREEN_PIN, 0);
    set_pwm_duty_cycle(BLUE_PIN,  0);

    // Terminate pigpio library
    gpioTerminate();

    printf("RGB LED color transition stopped.\n");

    return 0;
}

