#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>
#include <math.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor for +/- 250°/s range
#define GYRO_SCALE 131.0

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Function prototypes
int init_i2c();
int init_mpu6050();
gyro_data_t read_gyro_data();
void log_data(gyro_data_t data);
void signal_handler(int sig);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    terminate = 1;
    printf("Signal received, exiting gracefully...\n");
}

// Initialize I2C communication
int init_i2c() {
    char *i2c_device = "/dev/i2c-1";
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C device");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, MPU6050_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (write(i2c_fd, "\0", 1) != 1) {
        perror("Error writing to PWR_MGMT_1 register");
        return -1;
    }

    // Set gyroscope full-scale range to +/- 250°/s
    if (write(i2c_fd, "\x00", 1) != 1) {
        perror("Error writing to GYRO_CONFIG register");
        return -1;
    }

    return 0;
}

// Read gyroscope data from MPU-6050
gyro_data_t read_gyro_data() {
    gyro_data_t data;
    char buffer[6];

    if (read(i2c_fd, buffer, 6) != 6) {
        perror("Error reading gyroscope data");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (buffer[0] << 8) | buffer[1];
    int16_t raw_y = (buffer[2] << 8) | buffer[3];
    int16_t raw_z = (buffer[4] << 8) | buffer[5];

    // Convert raw data to degrees per second
    data.x = (float)raw_x / GYRO_SCALE;
    data.y = (float)raw_y / GYRO_SCALE;
    data.z = (float)raw_z / GYRO_SCALE;

    return data;
}

// Log data to file
void log_data(gyro_data_t data) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f, %.2f, %.2f\n", timestamp, data.x, data.y, data.z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Cleanup resources before exiting
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    while (!terminate) {
        gyro_data_t data = read_gyro_data();
        log_data(data);
        usleep(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

