#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define BUTTON_PIN 17
#define BUZZER_PIN 18

// Define melody lookup table
const int melody[] = {440, 494, 523, 0}; // C4, D4, E4, rest

// Debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
volatile int melody_playing = 0;
volatile int button_pressed = 0;

// Function prototypes
void button_isr(int gpio, int level, uint32_t tick, void *user_data);
void play_melody();
void stop_melody();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    stop_melody();
    gpioTerminate();
    exit(0);
}

// Interrupt service routine for button press
void button_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 0) { // Button pressed (active low)
        button_pressed = 1;
        gpioDelay(DEBOUNCE_TIME * 1000); // Debounce
        if (button_pressed) {
            if (!melody_playing) {
                play_melody();
            } else {
                stop_melody();
            }
            button_pressed = 0; // Reset flag after processing
        }
    }
}

// Function to play the melody
void play_melody() {
    if (!melody_playing) {
        melody_playing = 1;
        printf("Playing melody...\n");
        for (int i = 0; melody[i] != 0; i += 2) {
            gpioPWM(BUZZER_PIN, melody[i + 1] * 50); // Set PWM duty cycle (50% for volume)
            gpioDelay(melody[i] * 1000); // Play tone for duration
        }
        melody_playing = 0;
        printf("Melody stopped.\n");
    }
}

// Function to stop the melody
void stop_melody() {
    if (melody_playing) {
        melody_playing = 0;
        gpioPWM(BUZZER_PIN, 0); // Stop PWM
        printf("Melody stopped.\n");
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Set pull-up resistor on button pin
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set PWM frequency (adjust as needed)
    gpioSetPWMfrequency(BUZZER_PIN, 440); // Example frequency

    // Set PWM range (adjust as needed)
    gpioSetPWMrange(BUZZER_PIN, 1000); // Example range

    // Register interrupt service routine for button press
    if (gpioSetISRFuncEx(BUTTON_PIN, FALLING_EDGE, 0, button_isr, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Doorbell monitoring started. Press Ctrl+C to exit.\n");

    // Main loop (keep the program running until a signal is received)
    while (1) {
        if (melody_playing) {
            gpioDelay(100000); // Check every 0.1 seconds
        } else {
            gpioDelay(10000); // Check every 0.1 seconds if no melody is playing
        }
    }

    return 0;
}

