#include <pigpio.h>

// Configuration
#define GPIO_PIN 17
#define SLIDING_WINDOW_SIZE 5
#define EARTHQUAKE_THRESHOLD 3
#define LOG_FILE "vibration_events.log"
#define POLL_TIMEOUT_MS 1000

// Global variables
volatile sig_atomic_t program_running = 1;
int log_fd = -1;

// Structure to hold the sliding window
typedef struct {
    int window[SLIDING_WINDOW_SIZE];
    int head;
    int count;
} SlidingWindow;

// Function prototypes
int initialize_gpio();
int read_sensor();
void update_sliding_window(SlidingWindow *window, int value);
int is_earthquake_alert(SlidingWindow *window);
void log_event(int value);
void print_alert();
void signal_handler(int signal);
void cleanup();

// Initialize the sliding window
void sliding_window_init(SlidingWindow *window) {
    window->head = 0;
    window->count = 0;
    memset(window->window, 0, sizeof(window->window));
}

// Update the sliding window with a new value
void update_sliding_window(SlidingWindow *window, int value) {
    window->window[window->head] = value;
    window->head = (window->head + 1) % SLIDING_WINDOW_SIZE;
    if (window->count < SLIDING_WINDOW_SIZE) {
        window->count++;
    }
}

// Check if the sliding window contains enough HIGH values
int is_earthquake_alert(SlidingWindow *window) {
    int high_count = 0;
    for (int i = 0; i < window->count; i++) {
        if (window->window[i] == 1) {
            high_count++;
        }
    }
    return (high_count >= EARTHQUAKE_THRESHOLD);
}

// Log an event to the log file
void log_event(int value) {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[30];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ldZ", tv.tv_usec);

    if (log_fd != -1) {
        dprintf(log_fd, "%s,%d\n", timestamp, value);
        fsync(log_fd); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Print an alert message
void print_alert() {
    struct timeval tv;
    struct tm *tm_info;
    char timestamp[30];

    gettimeofday(&tv, NULL);
    tm_info = localtime(&tv.tv_sec);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", tm_info);
    snprintf(timestamp + strlen(timestamp), sizeof(timestamp) - strlen(timestamp), ".%06ldZ", tv.tv_usec);

    printf("EARTHQUAKE ALERT: %s\n", timestamp);
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_INPUT);
    gpioSetPullUpDown(GPIO_PIN, PI_PUD_UP); // Enable pull-up resistor

    return 0;
}

// Read the sensor value
int read_sensor() {
    return gpioRead(GPIO_PIN);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
}

// Cleanup resources before exiting
void cleanup() {
    if (log_fd != -1) {
        close(log_fd);
    }
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    int poll_timeout_ms = POLL_TIMEOUT_MS;
    int opt;

    // Parse command-line arguments
    while ((opt = getopt(argc, argv, "t:")) != -1) {
        switch (opt) {
            case 't':
                poll_timeout_ms = atoi(optarg);
                if (poll_timeout_ms <= 0) {
                    fprintf(stderr, "Invalid poll timeout. Using default value (%d ms).\n", POLL_TIMEOUT_MS);
                    poll_timeout_ms = POLL_TIMEOUT_MS;
                }
                break;
            default:
                fprintf(stderr, "Usage: %s [-t timeout_ms]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return EXIT_FAILURE;
    }

    // Open the log file
    log_fd = open(LOG_FILE, O_WRONLY | O_CREAT | O_APPEND, 0644);
    if (log_fd == -1) {
        fprintf(stderr, "Error opening log file: %s\n", strerror(errno));
        cleanup();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize sliding window
    SlidingWindow earthquake_window;
    sliding_window_init(&earthquake_window);

    printf("Vibration sensor monitoring started. Polling timeout: %d ms. Press Ctrl+C to exit.\n", poll_timeout_ms);

    // Main loop
    while (program_running) {
        int sensor_value = read_sensor();

        // Read sensor value with timeout
        struct timeval start_time, current_time;
        gettimeofday(&start_time, NULL);

        fd_set readfds;
        FD_ZERO(&readfds);
        FD_SET(0, &readfds); // Add stdin to the set

        int max_fd = 0;
        if (0 > max_fd) max_fd = 0;

        struct timeval timeout;
        timeout.tv_sec = 0;
        timeout.tv_usec = poll_timeout_ms * 1000; // Convert ms to us

        int retval = select(max_fd + 1, &readfds, NULL, NULL, &timeout);

        if (retval == -1) {
            if (errno == EINTR) {
                // Interrupted by signal, exit loop
                break;
            }
            fprintf(stderr, "Error in select: %s\n", strerror(errno));
            break;
        } else if (retval == 0) {
            // Timeout occurred, read sensor value
            sensor_value = read_sensor();
        } else {
            // Data is available, read sensor value
            sensor_value = read_sensor();
        }

        gettimeofday(&current_time, NULL);
        double elapsed_time = (current_time.tv_sec - start_time.tv_sec) + (current_time.tv_usec - start_time.tv_usec) / 1000000.0;

        // Update sliding window
        update_sliding_window(&earthquake_window, sensor_value);

        // Check for earthquake alert
        if (is_earthquake_alert(&earthquake_window)) {
            print_alert();
        }

        // Log event
        log_event(sensor_value);

        // Small delay to avoid busy-waiting
        usleep(10000); // 10ms
    }

    // Cleanup and exit
    cleanup();
    return EXIT_SUCCESS;
}

