#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/i2c-dev.h>

// LSM303DLHC I2C address
#define LSM303_ADDR 0x1E

// LSM303DLHC magnetometer registers
#define MR_REG_M 0x02
#define OUT_X_H_M 0x03
#define OUT_X_L_M 0x04
#define OUT_Z_H_M 0x05
#define OUT_Z_L_M 0x06
#define OUT_Y_H_M 0x07
#define OUT_Y_L_M 0x08

// Hard-iron calibration offsets
#define X_OFFSET 10
#define Y_OFFSET -5
#define Z_OFFSET 20

// I2C bus
#define I2C_BUS "/dev/i2c-1"

// File to log data
#define LOG_FILE "mag_log.csv"

// Global variables
int i2c_fd;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z);
void calibrate_magnetometer(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *calibrated_x, float *calibrated_y, float *calibrated_z);
float calculate_heading(float calibrated_x, float calibrated_y);
char *get_compass_direction(float heading);
void log_data(float calibrated_x, float calibrated_y, float calibrated_z, float heading);
void signal_handler(int signal);
void cleanup();

// Structure to hold magnetometer data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} magnetometer_data_t;

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "Failed to initialize I2C. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s. Exiting.\n", strerror(errno));
        cleanup();
        return 1;
    }

    // Check if the file is empty and write the header if needed
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Calibrated X,Calibrated Y,Calibrated Z,Heading\n");
    }
    rewind(log_file);

    magnetometer_data_t raw_data;
    float calibrated_x, calibrated_y, calibrated_z;
    float heading;
    char *compass_direction;

    // Main loop
    while (program_running) {
        // Read magnetometer data
        if (read_magnetometer(&raw_data.x, &raw_data.y, &raw_data.z) == 0) {
            // Calibrate magnetometer data
            calibrate_magnetometer(raw_data.x, raw_data.y, raw_data.z, &calibrated_x, &calibrated_y, &calibrated_z);

            // Calculate heading
            heading = calculate_heading(calibrated_x, calibrated_y);

            // Get compass direction
            compass_direction = get_compass_direction(heading);

            // Log data
            log_data(calibrated_x, calibrated_y, calibrated_z, heading);

            // Print compass direction and heading
            printf("Compass: %s, Heading: %.2f degrees\n", compass_direction, heading);
        } else {
            fprintf(stderr, "Failed to read magnetometer data. Skipping sample.\n");
        }

        // Wait for 1 second
        sleep(1);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Failed to open I2C bus: %s. Error: %s\n", I2C_BUS, strerror(errno));
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, LSM303_ADDR) < 0) {
        fprintf(stderr, "Failed to acquire bus access and/or talk to slave. Error: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    // Configure magnetometer (continuous conversion mode, 80 Hz ODR)
    uint8_t config_value = 0x70; // Continuous conversion mode, 80 Hz ODR
    if (write(i2c_fd, &config_value, 1) != 1) {
        fprintf(stderr, "Failed to write to I2C device. Error: %s\n", strerror(errno));
        close(i2c_fd);
        return -1;
    }

    return 0;
}

// Read magnetometer data
int read_magnetometer(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t buffer[6];

    if (read(i2c_fd, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read magnetometer data. Error: %s\n", strerror(errno));
        return -1;
    }

    *x = (int16_t)((buffer[1] << 8) | buffer[0]);
    *z = (int16_t)((buffer[3] << 8) | buffer[2]);
    *y = (int16_t)((buffer[5] << 8) | buffer[4]);

    return 0;
}

// Calibrate magnetometer data
void calibrate_magnetometer(int16_t raw_x, int16_t raw_y, int16_t raw_z, float *calibrated_x, float *calibrated_y, float *calibrated_z) {
    *calibrated_x = (float)raw_x - X_OFFSET;
    *calibrated_y = (float)raw_y - Y_OFFSET;
    *calibrated_z = (float)raw_z - Z_OFFSET;
}

// Calculate heading in degrees
float calculate_heading(float calibrated_x, float calibrated_y) {
    float heading = atan2(calibrated_y, calibrated_x) * 180 / M_PI;

    // Normalize heading to 0-360 degrees
    if (heading < 0) {
        heading += 360;
    }

    return heading;
}

// Get compass direction
char *get_compass_direction(float heading) {
    if (heading >= 337.5 || heading < 22.5) {
        return "N";
    } else if (heading >= 22.5 && heading < 67.5) {
        return "NE";
    } else if (heading >= 67.5 && heading < 112.5) {
        return "E";
    } else if (heading >= 112.5 && heading < 157.5) {
        return "SE";
    } else if (heading >= 157.5 && heading < 202.5) {
        return "S";
    } else if (heading >= 202.5 && heading < 247.5) {
        return "SW";
    } else if (heading >= 247.5 && heading < 292.5) {
        return "W";
    } else {
        return "NW";
    }
}

// Log data to file
void log_data(float calibrated_x, float calibrated_y, float calibrated_z, float heading) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%.2f,%.2f\n", timestamp, calibrated_x, calibrated_y, calibrated_z, heading);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    program_running = 0;
}

// Cleanup resources
void cleanup() {
    if (i2c_fd >= 0) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
}

