// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 23
#define RELAY3_PIN 24
#define RELAY4_PIN 25

// Define the moisture threshold
#define MOISTURE_THRESHOLD 30

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_moisture_level();
void activate_relay(int relay_pin, int duration_seconds);
void log_data(int relay_number, int moisture_level);
void signal_handler(int signal);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Ensure all relays are initially off
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    return 0;
}

// Read moisture level from a simulated sensor
int read_moisture_level() {
    // Seed the random number generator
    srand(time(NULL));

    // Generate a random moisture level between 0 and 100
    int moisture_level = rand() % 101;

    // Validate the moisture level
    if (moisture_level < 0 || moisture_level > 100) {
        fprintf(stderr, "Error: Invalid moisture level: %d\n", moisture_level);
        return -1; // Indicate an error
    }

    return moisture_level;
}

// Activate a relay for a specified duration
void activate_relay(int relay_pin, int duration_seconds) {
    gpioWrite(relay_pin, 0); // Activate the relay (LOW)
    gpioDelay(duration_seconds * 1000000); // Delay for the specified duration (microseconds)
    gpioWrite(relay_pin, 1); // Deactivate the relay (HIGH)
}

// Log data to the log file
void log_data(int relay_number, int moisture_level) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    fprintf(log_file, "%s, Relay %d, Moisture Level: %d\n", timestamp, relay_number, moisture_level);
    fflush(log_file); // Ensure data is written to the file immediately
}

// Cleanup function to deactivate relays and close the log file
void cleanup() {
    // Deactivate all relays
    gpioWrite(RELAY1_PIN, 1);
    gpioWrite(RELAY2_PIN, 1);
    gpioWrite(RELAY3_PIN, 1);
    gpioWrite(RELAY4_PIN, 1);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open the log file in append mode
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Main loop
    while (running) {
        // Read moisture level
        int moisture_level = read_moisture_level();
        if (moisture_level == -1) {
            fprintf(stderr, "Error reading moisture level, retrying in 10 seconds...\n");
            sleep(10);
            continue; // Skip to the next iteration
        }

        // Log the data
        log_data(1, moisture_level);
        log_data(2, moisture_level);
        log_data(3, moisture_level);
        log_data(4, moisture_level);

        // Check if the moisture level is below the threshold
        if (moisture_level < MOISTURE_THRESHOLD) {
            // Activate relay 1
            activate_relay(RELAY1_PIN, 5);
            log_data(1, moisture_level);

            // Wait for 1 second
            gpioDelay(1000000);

            // Activate relay 2
            activate_relay(RELAY2_PIN, 5);
            log_data(2, moisture_level);

            // Wait for 1 second
            gpioDelay(1000000);

            // Activate relay 3
            activate_relay(RELAY3_PIN, 5);
            log_data(3, moisture_level);

            // Wait for 1 second
            gpioDelay(1000000);

            // Activate relay 4
            activate_relay(RELAY4_PIN, 5);
            log_data(4, moisture_level);

            // Wait for 1 second
            gpioDelay(1000000);
        }

        // Wait for 10 seconds
        sleep(10);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

