#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define TRIGGER_PIN 17
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 50000       // 50ms timeout
#define SAMPLE_INTERVAL_US 1000000 // 1 second

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
void trigger_sensor();
long measure_pulse_width();
float calculate_distance(long pulse_width);
void log_distance(float distance);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIGGER_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIGGER_PIN, 0);
}

// Function to measure the pulse width of the echo signal
long measure_pulse_width() {
    long start_tick = 0, end_tick = 0;

    // Wait for the echo pin to go high (rising edge)
    int timeout = 0;
    while (gpioRead(ECHO_PIN) == 0 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pin did not go high (rising edge) within timeout.\n");
        return -1; // Indicate timeout error
    }
    start_tick = gpioTick();

    // Wait for the echo pin to go low (falling edge)
    timeout = 0;
    while (gpioRead(ECHO_PIN) == 1 && timeout < TIMEOUT_US) {
        timeout++;
        gpioDelay(1); // Small delay to prevent busy-waiting
    }
    if (timeout >= TIMEOUT_US) {
        fprintf(stderr, "Error: Echo pin did not go low (falling edge) within timeout.\n");
        return -1; // Indicate timeout error
    }
    end_tick = gpioTick();

    return end_tick - start_tick;
}

// Function to calculate the distance in centimeters
float calculate_distance(long pulse_width) {
    if (pulse_width < 0) {
        return -1.0; // Indicate error
    }
    return (pulse_width * SPEED_OF_SOUND) / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log the distance to a file
void log_distance(float distance) {
    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return;
    }

    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[80];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s, %.2f\n", timestamp, distance);
    fflush(log_file); // Ensure data is written to disk immediately
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIGGER_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open the log file in append mode
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    fprintf(stderr, "Ultrasonic distance sensor logging started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        trigger_sensor();
        long pulse_width = measure_pulse_width();

        if (pulse_width > 0) {
            float distance = calculate_distance(pulse_width);
            if (distance >= 0) {
                log_distance(distance);
            } else {
                fprintf(stderr, "Error: Invalid distance measurement.\n");
                fprintf(log_file, "Error: Invalid distance measurement.\n");
                fflush(log_file);
            }
        } else {
            fprintf(stderr, "Error: Invalid pulse width measurement.\n");
            fprintf(log_file, "Error: Invalid pulse width measurement.\n");
            fflush(log_file);
        }

        gpioDelay(SAMPLE_INTERVAL_US); // Wait for the next sample
    }

    // Close the log file and terminate pigpio library
    fclose(log_file);
    gpioTerminate();

    fprintf(stderr, "Ultrasonic distance sensor logging stopped.\n");

    return 0;
}

