#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor for +/- 250 degrees/second range
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    float x;
    float y;
    float z;
} gyro_data_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
    terminate = 1;
}

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }
    return 0;
}

// Function to read gyroscope data
int read_gyro_data(gyro_data_t *data) {
    char buf[6];
    int16_t raw_x, raw_y, raw_z;

    // Read raw gyroscope data
    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes
    raw_x = (int16_t)((buf[0] << 8) | buf[1]);
    raw_y = (int16_t)((buf[2] << 8) | buf[3]);
    raw_z = (int16_t)((buf[4] << 8) | buf[5]);

    // Convert to degrees per second
    data->x = (float)raw_x / GYRO_SCALE;
    data->y = (float)raw_y / GYRO_SCALE;
    data->z = (float)raw_z / GYRO_SCALE;

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    gyro_data_t gyro_data;
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&gyro_data) == 0) {
            // Print gyroscope data
            printf("X: %.2f deg/s, Y: %.2f deg/s, Z: %.2f deg/s\n", gyro_data.x, gyro_data.y, gyro_data.z);
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data. Retrying...\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms = 100000 microseconds
    }

    // Close I2C bus and terminate pigpio
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

