        activate_relay(RELAY2_PIN);
        gpioDelay(WATERING_DURATION * 1000); // Delay for WATERING_DURATION seconds
        deactivate_relay(RELAY2_PIN);

        // Activate relay 3
        activate_relay(RELAY3_PIN);
        gpioDelay(WATERING_DURATION * 1000); // Delay for WATERING_DURATION seconds
        deactivate_relay(RELAY3_PIN);

        // Activate relay 4
        activate_relay(RELAY4_PIN);
        gpioDelay(WATERING_DURATION * 1000); // Delay for WATERING_DURATION seconds
        deactivate_relay(RELAY4_PIN);

        // Log the watering cycle
        log_watering_cycle();

        // Wait for 86400 seconds (24 hours)
        sleep(86400);
    }

    // Deactivate all relays before exiting
    deactivate_relay(RELAY1_PIN);
    deactivate_relay(RELAY2_PIN);
    deactivate_relay(RELAY3_PIN);
    deactivate_relay(RELAY4_PIN);

    // Terminate pigpio
    gpioTerminate();

    printf("Plant watering system stopped.\n");

    return 0;
}

