#include <pigpio.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 17
#define RELAY2_PIN 18
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define PWM frequency (1 kHz)
#define PWM_FREQUENCY 1000

// Define sunrise duration (30 minutes)
#define SUNRISE_DURATION 1800 // seconds

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
void set_relay_intensity(int relay_pin, int intensity);
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Received signal, shutting down...");
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    return 0; // Indicate success
}

// Function to set the intensity of a relay
void set_relay_intensity(int relay_pin, int intensity) {
    if (intensity < 0 || intensity > 255) {
        fprintf(stderr, "Invalid intensity value: %d\n", intensity);
        return;
    }

    gpioPWM(relay_pin, intensity);
}

// Function to log events to a file
void log_event(const char *message) {
    FILE *fp = fopen("smart_lighting.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1; // Exit if initialization fails
    }

    log_event("Smart lighting system started");

    // Sunrise effect loop
    for (int i = 0; i <= 255 && program_running; i++) {
        set_relay_intensity(RELAY1_PIN, i);
        set_relay_intensity(RELAY2_PIN, i);
        set_relay_intensity(RELAY3_PIN, i);
        set_relay_intensity(RELAY4_PIN, i);
        log_event("Sunrise intensity: Relay1 = ");
        log_event(i == 255 ? "MAX" : i);
        sleep(1);
    }

    // Wait for the sunrise duration
    sleep(SUNRISE_DURATION);

    // Fade out the lights
    for (int i = 255; i >= 0 && program_running; i--) {
        set_relay_intensity(RELAY1_PIN, i);
        set_relay_intensity(RELAY2_PIN, i);
        set_relay_intensity(RELAY3_PIN, i);
        set_relay_intensity(RELAY4_PIN, i);
        log_event("Fade out intensity: Relay1 = ");
        log_event(i == 0 ? "MIN" : i);
        sleep(1);
    }

    // Turn off all relays
    set_relay_intensity(RELAY1_PIN, 0);
    set_relay_intensity(RELAY2_PIN, 0);
    set_relay_intensity(RELAY3_PIN, 0);
    set_relay_intensity(RELAY4_PIN, 0);
    log_event("All relays turned off");

    log_event("Smart lighting system stopped");

    gpioTerminate(); // Terminate pigpio

    return 0;
}

