#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <gpiod.h>
#include <stdbool.h>

// MPU-9250 Register Addresses
#define MPU9250_ADDR_1 0x68
#define MPU9250_ADDR_2 0x69
#define MPU9250_GYRO_XOUT_H 0x43
#define MPU9250_PWR_MGMT_1 0x6B
#define MPU9250_GYRO_CONFIG 0x1B

// Sensitivity scale factor for gyroscope (±250°/s)
#define GYRO_SCALE 131.0

// SPI device and chip select line
#define SPI_DEVICE "/dev/spidev0.0"
#define CS_LINE 8

// Global variables
static int spi_fd = -1;
static struct gpiod_chip *gpio_chip = NULL;
static struct gpiod_line *cs_line = NULL;
static FILE *log_file = NULL;
static volatile sig_atomic_t terminate = 0;

// Function prototypes
int init_spi();
int init_gpio();
int init_mpu9250();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
int log_data(int16_t x, int16_t y, int16_t z);
void signal_handler(int sig);
void cleanup();

// Structure to hold gyroscope data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} gyro_data_t;

// Function to initialize the SPI interface
int init_spi() {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) < 0) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = 8; // 8 bits per word
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) < 0) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure max speed hz
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) < 0) {
        perror("Error setting max speed hz");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// Function to initialize the GPIO interface
int init_gpio() {
    gpio_chip = gpiod_chip_open_by_name("gpiochip0");
    if (!gpio_chip) {
        perror("Error opening GPIO chip");
        return -1;
    }

    cs_line = gpiod_chip_get_line(gpio_chip, CS_LINE);
    if (!cs_line) {
        perror("Error getting GPIO line");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    if (gpiod_line_request_output(cs_line, "mpu9250_cs", 0) < 0) {
        perror("Error requesting GPIO line as output");
        gpiod_chip_close(gpio_chip);
        return -1;
    }

    return 0;
}

// Function to initialize the MPU-9250
int init_mpu9250() {
    // Wake up the MPU-9250 (clear sleep bit)
    uint8_t data[2];
    data[0] = MPU9250_PWR_MGMT_1;
    data[1] = 0; // Clear sleep bit
    if (write(spi_fd, data, 2) != 2) {
        perror("Error writing to MPU-9250 PWR_MGMT_1");
        return -1;
    }
    usleep(10000); // Wait for the MPU-9250 to wake up

    // Configure gyroscope range (+/- 250°/s)
    data[0] = MPU9250_GYRO_CONFIG;
    data[1] = 0x00; // Set full scale range to +/- 250°/s
    if (write(spi_fd, data, 2) != 2) {
        perror("Error writing to MPU-9250 GYRO_CONFIG");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data from the MPU-9250
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    uint8_t tx_buf[4];
    uint8_t rx_buf[4];
    struct spi_ioc_transfer transfer[1];

    // Set CS line low
    if (gpiod_line_set_value(cs_line, 0) < 0) {
        perror("Error setting CS line low");
        return -1;
    }

    // Read gyroscope data (X, Y, Z)
    tx_buf[0] = MPU9250_GYRO_XOUT_H | 0x80; // Read multiple bytes starting from GYRO_XOUT_H
    memset(rx_buf, 0, sizeof(rx_buf));

    transfer[0].tx_buf = (unsigned long)tx_buf;
    transfer[0].rx_buf = (unsigned long)rx_buf;
    transfer[0].len = 4;
    transfer[0].speed_hz = 1000000; // 1 MHz
    transfer[0].bits_per_word = 8;

    if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), transfer) < 0) {
        perror("Error during SPI transfer");
        // Set CS line high
        if (gpiod_line_set_value(cs_line, 1) < 0) {
            perror("Error setting CS line high on error");
        }
        return -1;
    }

    // Set CS line high
    if (gpiod_line_set_value(cs_line, 1) < 0) {
        perror("Error setting CS line high");
        return -1;
    }

    // Combine high and low bytes for each axis
    *x = (int16_t)((rx_buf[0] << 8) | rx_buf[1]);
    *y = (int16_t)((rx_buf[2] << 8) | rx_buf[3]);

    return 0;
}

// Function to log data to a CSV file
int log_data(int16_t x, int16_t y, int16_t z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];
    struct timespec ts;

    // Get current time
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%S", timeinfo);

    // Get nanosecond resolution timestamp
    clock_gettime(CLOCK_REALTIME, &ts);
    long nanoseconds = ts.tv_nsec;

    // Write data to log file
    fprintf(log_file, "%s.%09ld,%d,%d,%d\n", timestamp, nanoseconds, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int sig) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Cleanup function to release resources
void cleanup() {
    if (spi_fd != -1) {
        close(spi_fd);
    }
    if (gpio_chip) {
        gpiod_line_set_value(cs_line, 1); // Set CS line high before closing
        gpiod_line_release(cs_line);
        gpiod_chip_close(gpio_chip);
    }
    if (log_file) {
        fclose(log_file);
    }
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize SPI
    if (init_spi() < 0) {
        fprintf(stderr, "SPI initialization failed. Exiting.\n");
        return 1;
    }

    // Initialize GPIO
    if (init_gpio() < 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Initialize MPU-9250
    if (init_mpu9250() < 0) {
        fprintf(stderr, "MPU-9250 initialization failed. Exiting.\n");
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.txt", "a");
    if (!log_file) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Main loop
    int16_t x, y, z;
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Log data
            log_data(x, y, z);
        } else {
            fprintf(stderr, "Error reading gyroscope data. Retrying...\n");
        }

        // Wait for 10 milliseconds
        usleep(10000);
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

