#include <stdint.h>
#include <stdbool.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPU-6050 Registers
#define MPU6050_ADDR 0x68
#define PWR_MGMT_1 0x6B
#define GYRO_CONFIG 0x1B
#define GYRO_XOUT_H 0x43
#define GYRO_YOUT_H 0x45
#define GYRO_ZOUT_H 0x47

// Circular Buffer Size
#define BUFFER_SIZE 64

// Threshold for Angular Velocity (degrees/second)
#define THRESHOLD 200.0

// SPI Configuration
#define SPI_CHANNEL 0
#define SPI_BAUD 39000
#define SPI_FLAGS 0

// GPIO Configuration
#define LED_GPIO 17

// Global Variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    time_t timestamp;
    float x;
    float y;
    float z;
} gyro_data_t;

// Circular Buffer
gyro_data_t gyro_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function Prototypes
int init_mpu6050();
int read_gyro_data(float *x, float *y, float *z);
void add_to_buffer(float x, float y, float z);
bool check_threshold(float x, float y, float z);
void blink_led();
void signal_handler(int signal);
void print_buffer();

// Function to initialize the MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(spi_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Configure the gyroscope range (+/- 250 degrees/second)
    if (i2cWriteByteData(spi_handle, GYRO_CONFIG, 0) < 0) {
        fprintf(stderr, "Error: Could not configure gyroscope range\n");
        return -1;
    }

    return 0;
}

// Function to read gyroscope data from the MPU-6050
int read_gyro_data(float *x, float *y, float *z) {
    char buffer[6];

    // Read all six gyroscope registers (X, Y, Z)
    if (i2cReadI2CBlockData(spi_handle, GYRO_XOUT_H, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    int16_t raw_x = (buffer[0] << 8) | buffer[1];
    int16_t raw_y = (buffer[2] << 8) | buffer[3];
    int16_t raw_z = (buffer[4] << 8) | buffer[5];

    // Convert raw data to degrees per second (assuming +/- 250 degrees/second range)
    *x = (float)raw_x / 131.0;
    *y = (float)raw_y / 131.0;
    *z = (float)raw_z / 131.0;

    return 0;
}

// Function to add data to the circular buffer
void add_to_buffer(float x, float y, float z) {
    time(&gyro_buffer[buffer_index].timestamp);
    gyro_buffer[buffer_index].x = x;
    gyro_buffer[buffer_index].y = y;
    gyro_buffer[buffer_index].z = z;

    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Function to check if the angular velocity exceeds the threshold
bool check_threshold(float x, float y, float z) {
    return (fabs(x) > THRESHOLD || fabs(y) > THRESHOLD || fabs(z) > THRESHOLD);
}

// Function to blink the LED
void blink_led() {
    gpioWrite(LED_GPIO, 1); // Turn LED on
    gpioDelay(500);          // Wait for 500ms
    gpioWrite(LED_GPIO, 0); // Turn LED off
    gpioDelay(500);          // Wait for 500ms
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    fprintf(stderr, "Caught signal %d, terminating...\n", signal);
    terminate = 1;
}

// Function to print the entire circular buffer as CSV
void print_buffer() {
    printf("Timestamp,X,Y,Z\n");
    for (int i = 0; i < BUFFER_SIZE; i++) {
        int index = (buffer_index + i) % BUFFER_SIZE;
        struct tm *timeinfo = localtime(&gyro_buffer[index].timestamp);
        char timestamp_str[20];
        strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);
        printf("%s,%.2f,%.2f,%.2f\n", timestamp_str, gyro_buffer[index].x, gyro_buffer[index].y, gyro_buffer[index].z);
    }
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open SPI channel
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, SPI_FLAGS);
    if (spi_handle < 0) {
        fprintf(stderr, "Error: Could not open SPI channel\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    float x, y, z;

    // Main loop
    while (!terminate) {
        // Read gyroscope data
        if (read_gyro_data(&x, &y, &z) == 0) {
            // Add data to the circular buffer
            add_to_buffer(x, y, z);

            // Check if threshold is exceeded
            if (check_threshold(x, y, z)) {
                // Blink the LED
                blink_led();
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyroscope data, retrying...\n");
        }

        // Delay to avoid overwhelming the MPU-6050
        gpioDelay(10); // 10ms delay
    }

    // Print the circular buffer before exiting
    print_buffer();

    // Close SPI channel and terminate pigpio
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

