#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <math.h>
#include <wiringPi.h>
#include <wiringPiI2C.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define ACCEL_XOUT_H 0x3B
#define GYRO_XOUT_H  0x43

// Sensitivity scales (adjust based on your sensor's configuration)
#define ACCEL_SCALE 16384.0f // +/- 2g range
#define GYRO_SCALE  131.0f  // +/- 250 deg/s range

// GPIO pin for LED
#define LED_PIN 21

// Global variables
int i2c_fd;
FILE *log_file;
bool running = true;

// Function prototypes
int init_mpu6050();
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z);
float process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z);
void calculate_roll_pitch(float accel_x, float accel_y, float accel_z, float *roll, float *pitch);
void log_data(float roll, float pitch);
void control_led(float roll, float pitch);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    float accel_x;
    float accel_y;
    float accel_z;
    float gyro_x;
    float gyro_y;
    float gyro_z;
} sensor_data_t;

int main()
{
    // Initialize WiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "WiringPi initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPU6050_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "I2C initialization failed: %s\n", strerror(errno));
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() != 0) {
        fprintf(stderr, "MPU-6050 initialization failed\n");
        return 1;
    }

    // Open log file
    log_file = fopen("tilt_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file: %s\n", strerror(errno));
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    int16_t accel_x, accel_y, accel_z, gyro_x, gyro_y, gyro_z;
    float roll, pitch;
    sensor_data_t sensor_data;

    while (running) {
        // Read raw data
        if (read_raw_data(&accel_x, &accel_y, &accel_z, &gyro_x, &gyro_y, &gyro_z) == 0) {
            // Process data
            sensor_data.accel_x = (float)accel_x / ACCEL_SCALE;
            sensor_data.accel_y = (float)accel_y / ACCEL_SCALE;
            sensor_data.accel_z = (float)accel_z / ACCEL_SCALE;
            sensor_data.gyro_x  = (float)gyro_x  / GYRO_SCALE;
            sensor_data.gyro_y  = (float)gyro_y  / GYRO_SCALE;
            sensor_data.gyro_z  = (float)gyro_z  / GYRO_SCALE;

            // Calculate roll and pitch
            calculate_roll_pitch(sensor_data.accel_x, sensor_data.accel_y, sensor_data.accel_z, &roll, &pitch);

            // Log data
            log_data(roll, pitch);

            // Control LED
            control_led(roll, pitch);
        } else {
            fprintf(stderr, "Failed to read sensor data\n");
        }

        // Delay for 100 milliseconds
        delay(100);
    }

    // Cleanup
    fclose(log_file);
    digitalWrite(LED_PIN, LOW); // Turn off LED
    return 0;
}

// Initialize MPU-6050
int init_mpu6050()
{
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (wiringPiI2CWriteReg8(i2c_fd, PWR_MGMT_1, 0) == -1) {
        fprintf(stderr, "Failed to write to PWR_MGMT_1 register: %s\n", strerror(errno));
        return -1;
    }
    delay(100); // Wait for the sensor to wake up
    return 0;
}

// Read raw accelerometer and gyroscope data
int read_raw_data(int16_t *accel_x, int16_t *accel_y, int16_t *accel_z, int16_t *gyro_x, int16_t *gyro_y, int16_t *gyro_z)
{
    int16_t raw_accel_x, raw_accel_y, raw_accel_z, raw_gyro_x, raw_gyro_y, raw_gyro_z;

    // Read accelerometer data
    raw_accel_x = wiringPiI2CReadReg16(i2c_fd, ACCEL_XOUT_H);
    if (raw_accel_x == -1) {
        fprintf(stderr, "Failed to read ACCEL_XOUT_H register: %s\n", strerror(errno));
        return -1;
    }
    raw_accel_y = wiringPiI2CReadReg16(i2c_fd, ACCEL_XOUT_H + 2);
    if (raw_accel_y == -1) {
        fprintf(stderr, "Failed to read ACCEL_XOUT_H + 2 register: %s\n", strerror(errno));
        return -1;
    }
    raw_accel_z = wiringPiI2CReadReg16(i2c_fd, ACCEL_XOUT_H + 4);
    if (raw_accel_z == -1) {
        fprintf(stderr, "Failed to read ACCEL_XOUT_H + 4 register: %s\n", strerror(errno));
        return -1;
    }

    // Read gyroscope data
    raw_gyro_x = wiringPiI2CReadReg16(i2c_fd, GYRO_XOUT_H);
    if (raw_gyro_x == -1) {
        fprintf(stderr, "Failed to read GYRO_XOUT_H register: %s\n", strerror(errno));
        return -1;
    }
    raw_gyro_y = wiringPiI2CReadReg16(i2c_fd, GYRO_XOUT_H + 2);
    if (raw_gyro_y == -1) {
        fprintf(stderr, "Failed to read GYRO_XOUT_H + 2 register: %s\n", strerror(errno));
        return -1;
    }
    raw_gyro_z = wiringPiI2CReadReg16(i2c_fd, GYRO_XOUT_H + 4);
    if (raw_gyro_z == -1) {
        fprintf(stderr, "Failed to read GYRO_XOUT_H + 4 register: %s\n", strerror(errno));
        return -1;
    }

    *accel_x = raw_accel_x;
    *accel_y = raw_accel_y;
    *accel_z = raw_accel_z;
    *gyro_x  = raw_gyro_x;
    *gyro_y  = raw_gyro_y;
    *gyro_z  = raw_gyro_z;

    return 0;
}

// Process raw data (convert to g and deg/s)
float process_data(int16_t accel_x, int16_t accel_y, int16_t accel_z, int16_t gyro_x, int16_t gyro_y, int16_t gyro_z)
{
    // Placeholder for data processing (replace with actual calculations)
    // This is a simplified example and may need adjustment based on your sensor's configuration
    float accel_x_g = (float)accel_x / ACCEL_SCALE;
    float accel_y_g = (float)accel_y / ACCEL_SCALE;
    float accel_z_g = (float)accel_z / ACCEL_SCALE;
    float gyro_x_dps = (float)gyro_x / GYRO_SCALE;
    float gyro_y_dps = (float)gyro_y / GYRO_SCALE;
    float gyro_z_dps = (float)gyro_z / GYRO_SCALE;

    // Example: Apply a simple low-pass filter (replace with your actual filter)
    // This is a placeholder and may need adjustment
    float accel_x_filtered = accel_x_g * 0.98 + accel_x_g * 0.02; // Simple moving average filter
    float accel_y_filtered = accel_y_g * 0.98 + accel_y_g * 0.02;
    float accel_z_filtered = accel_z_g * 0.98 + accel_z_g * 0.02;
    float gyro_x_filtered  = gyro_x_dps * 0.98 + gyro_x_dps * 0.02;
    float gyro_y_filtered  = gyro_y_dps * 0.98 + gyro_y_dps * 0.02;
    float gyro_z_filtered  = gyro_z_dps * 0.98 + gyro_z_dps * 0.02;

    return accel_x_filtered; // Return the filtered accelerometer data
}

// Calculate roll and pitch from accelerometer data
void calculate_roll_pitch(float accel_x, float accel_y, float accel_z, float *roll, float *pitch)
{
    // Calculate roll (assuming +X is front)
    *roll = atan2(accel_y, accel_z) * 180 / M_PI;

    // Calculate pitch (assuming +Y is up)
    *pitch = atan2(-accel_x, sqrt(accel_y * accel_y + accel_z * accel_z)) * 180 / M_PI;
}

// Log data to file
void log_data(float roll, float pitch)
{
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f\n", timestamp, roll, pitch);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Control LED based on tilt
void control_led(float roll, float pitch)
{
    if (fabs(roll) > 45.0 || fabs(pitch) > 45.0) {
        digitalWrite(LED_PIN, HIGH); // Turn on LED
    } else {
        digitalWrite(LED_PIN, LOW);  // Turn off LED
    }
}

// Signal handler for Ctrl+C
void signal_handler(int signal)
{
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = false;
}

