int read_register(uint8_t reg);
int write_register(uint8_t reg, uint8_t value);
int read_ambient_light();
int read_proximity();
void log_data(int ambient_light, int proximity);
void control_led(int proximity);
void signal_handler(int signal);
void cleanup();

// Structure for sensor configuration (optional)
typedef struct {
    uint8_t meas_rate;
} sensor_config_t;

// Function to initialize the I2C bus
int init_i2c() {
    i2c_fd = open(I2C_BUS, O_RDWR);
    if (i2c_fd < 0) {
        perror("Error opening I2C bus");
        return -1;
    }

    if (ioctl(i2c_fd, I2C_SLAVE, SI1145_ADDR) < 0) {
        perror("Error setting I2C slave address");
        close(i2c_fd);
        return -1;
    }

    // Reset the sensor
    if (write_register(REG_COMMAND, CMD_RESET) < 0) {
        fprintf(stderr, "Error resetting Si1145\n");
        close(i2c_fd);
        return -1;
    }
    usleep(10000); // Wait for reset to complete

    // Configure the sensor (example configuration)
    if (write_register(REG_MEAS_RATE0, 0x0A) < 0) return -1; // Measurement rate
    if (write_register(REG_MEAS_RATE1, 0x00) < 0) return -1; // Measurement rate

    return 0;
}

// Function to read a register from the Si1145
int read_register(uint8_t reg) {
    uint8_t buf[1];
    buf[0] = reg;
    if (write(i2c_fd, buf, 1) != 1) {
        perror("Error writing register address");
        return -1;
    }

    if (read(i2c_fd, buf, 1) != 1) {
        perror("Error reading register value");
        return -1;
    }

    return buf[0];
}

// Function to write a register to the Si1145
int write_register(uint8_t reg, uint8_t value) {
    uint8_t buf[2];
    buf[0] = reg;
    buf[1] = value;

    if (write(i2c_fd, buf, 2) != 2) {
        perror("Error writing to register");
        return -1;
    }

    return 0;
}

// Function to read ambient light data
int read_ambient_light() {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = read_register(REG_ALS_VIS_DATA0);
        if (result >= 0) {
            return result;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
    }

    fprintf(stderr, "Failed to read ambient light after %d retries\n", RETRY_COUNT);
    return -1;
}

// Function to read proximity data
int read_proximity() {
    int retries = 0;
    int result;

    while (retries < RETRY_COUNT) {
        result = read_register(REG_PS1_DATA0);
        if (result >= 0) {
            return result;
        }
        retries++;
        usleep(RETRY_DELAY_MS * 1000); // Convert ms to microseconds
    }

    fprintf(stderr, "Failed to read proximity after %d retries\n", RETRY_COUNT);
    return -1;
}

