void log_data(int ambient_light, int proximity) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s,AmbientLight:%d,Proximity:%d\n", timestamp, ambient_light, proximity);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to control the presence LED
void control_led(int proximity) {
    if (proximity > PROXIMITY_THRESHOLD) {
        if (!led_on) {
            gpioWrite(LED_GPIO, 1); // Turn LED on
            led_on = true;
        }
    } else {
        if (led_on) {
            gpioWrite(LED_GPIO, 0); // Turn LED off
            led_on = false;
        }
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Cleanup function to close I2C and log file
void cleanup() {
    if (i2c_fd != -1) {
        close(i2c_fd);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(LED_GPIO, 0); // Turn off LED
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize I2C
    if (init_i2c() < 0) {
        fprintf(stderr, "I2C initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Error opening log file");
        cleanup();
        return 1;
    }

    // Configure LED GPIO as output
    gpioSetMode(LED_GPIO, PI_OUTPUT);

    // Main loop
    while (1) {
        int ambient_light = read_ambient_light();
        int proximity = read_proximity();

        if (ambient_light >= 0 && proximity >= 0) {
            log_data(ambient_light, proximity);
            control_led(proximity);
        } else {
            fprintf(stderr, "Error reading sensor data. Retrying...\n");
        }

        usleep(100000); // 100ms
    }

    return 0;
}

