#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define SPI_DEVICE "/dev/spidev0.0"
#define SPI_MODE SPI_MODE_0
#define SPI_BITS_PER_WORD 8
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define SAMPLE_RATE_HZ 100
#define SAMPLE_DELAY_US (1000000 / SAMPLE_RATE_HZ) // Delay between samples in microseconds
#define CSV_FILE "gyro_data.csv"
#define MAX_RETRIES 3

// ADXRS290 Register Addresses (Example - Refer to datasheet for correct values)
#define ADXRS290_REG_X_RATE 0x00
#define ADXRS290_REG_Y_RATE 0x02
#define ADXRS290_REG_TEMP 0x04
#define ADXRS290_REG_CTRL 0x06
#define ADXRS290_REG_STATUS 0x08

// Global variables
int spi_fd = -1;
FILE *csv_file = NULL;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    int16_t x_rate;
    int16_t y_rate;
} gyro_data_t;

// Function prototypes
int spi_init(void);
int spi_read_register(uint8_t reg_addr, uint8_t *data);
int spi_write_register(uint8_t reg_addr, uint8_t data);
gyro_data_t read_gyro_data(void);
int log_data(gyro_data_t data);
void signal_handler(int signal);
void cleanup(void);

// SPI initialization function
int spi_init(void) {
    spi_fd = open(SPI_DEVICE, O_RDWR);
    if (spi_fd < 0) {
        perror("Error opening SPI device");
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = SPI_MODE;
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        perror("Error setting SPI mode");
        close(spi_fd);
        return -1;
    }

    // Configure bits per word
    uint8_t bits = SPI_BITS_PER_WORD;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        perror("Error setting bits per word");
        close(spi_fd);
        return -1;
    }

    // Configure SPI speed
    uint32_t speed = SPI_SPEED;
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        perror("Error setting SPI speed");
        close(spi_fd);
        return -1;
    }

    return 0;
}

// SPI read register function
int spi_read_register(uint8_t reg_addr, uint8_t *data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Construct the transmit buffer (read command + dummy byte)
    tx_buf[0] = reg_addr | 0x80; // Set MSB for read operation
    tx_buf[1] = 0x00; // Dummy byte

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

    int retries = 0;
    while (retries < MAX_RETRIES) {
        if (ioctl(spi_fd, SPI_IOC_MESSAGE(1), &transfer) == 1) {
            // Success
            *data = rx_buf[1];
            return 0;
        } else {
            perror("SPI read failed");
            retries++;
            usleep(10000); // Wait before retrying
        }
    }

    fprintf(stderr, "SPI read failed after %d retries\n", MAX_RETRIES);
    return -1;
}

// SPI write register function
int spi_write_register(uint8_t reg_addr, uint8_t data) {
    uint8_t tx_buf[2];
    uint8_t rx_buf[2];

    // Construct the transmit buffer (write command + data)
    tx_buf[0] = reg_addr & 0x7F; // Clear MSB for write operation
    tx_buf[1] = data;

    struct spi_ioc_transfer transfer = {
        .tx_buf = (unsigned long)tx_buf,
        .rx_buf = (unsigned long)rx_buf,
        .len = 2,
        .speed_hz = SPI_SPEED,
        .bits_per_word = SPI_BITS_PER_WORD,
    };

