// Define GPIO pins
#define SENSOR_1_PIN 23
#define SENSOR_2_PIN 24
#define ALERT_PIN 17

// Define alert duration (in milliseconds)
#define ALERT_DURATION 2000

// Define debounce delay (in milliseconds)
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void sensor1_callback(int gpio, int level, uint32_t tick);
void sensor2_callback(int gpio, int level, uint32_t tick);
void alert_callback(int gpio, int level, uint32_t tick);
void log_event(const char *message);
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int pin;
    uint32_t last_tick;
} sensor_data_t;

sensor_data_t sensor1_data = {SENSOR_1_PIN, 0};
sensor_data_t sensor2_data = {SENSOR_2_PIN, 0};

// Callback function for sensor 1
void sensor1_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        if (tick - sensor1_data.last_tick > DEBOUNCE_DELAY * 1000) { // Debounce
            log_event("Sensor 1: Rising edge detected");
            gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
            gpioDelay(ALERT_DURATION * 1000); // Wait for alert duration
            gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
            sensor1_data.last_tick = tick;
        }
    }
}

// Callback function for sensor 2
void sensor2_callback(int gpio, int level, uint32_t tick) {
    if (level == 1) { // Rising edge
        if (tick - sensor2_data.last_tick > DEBOUNCE_DELAY * 1000) { // Debounce
            log_event("Sensor 2: Rising edge detected");
            gpioWrite(ALERT_PIN, 1); // Set alert pin HIGH
            gpioDelay(ALERT_DURATION * 1000); // Wait for alert duration
            gpioWrite(ALERT_PIN, 0); // Set alert pin LOW
            sensor2_data.last_tick = tick;
        }
    }
}

// Callback function for alert pin
void alert_callback(int gpio, int level, uint32_t tick) {
    // This function is not used, but it's required for the callback registration.
}

// Function to log events to a file
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s - %s\n", timestamp, message);
        fflush(log_file); // Ensure the log is written immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
        printf("Log file closed.\n");
    }

    // Set alert pin LOW
    gpioWrite(ALERT_PIN, 0);
    printf("Alert pin set LOW.\n");

    // Terminate the pigpio library
    gpioTerminate();
    printf("pigpio terminated.\n");

    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }
    printf("pigpio initialised successfully\n");

    // Open the log file
    log_file = fopen("seismic_events.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        gpioTerminate();
        return 1;
    }
    printf("Log file opened successfully\n");

    // Set GPIO modes
    gpioSetMode(SENSOR_1_PIN, PI_INPUT);
    gpioSetMode(SENSOR_2_PIN, PI_INPUT);
    gpioSetMode(ALERT_PIN, PI_OUTPUT);

    // Set pull-down resistors
    gpioSetPullUpDown(SENSOR_1_PIN, PI_PUD_DOWN);
    gpioSetPullUpDown(SENSOR_2_PIN, PI_PUD_DOWN);

    // Register callback functions
    if (gpioSetAlertFuncEx(SENSOR_1_PIN, sensor1_callback, NULL) != 0) {
        fprintf(stderr, "Error registering callback for sensor 1!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }
    if (gpioSetAlertFuncEx(SENSOR_2_PIN, sensor2_callback, NULL) != 0) {
        fprintf(stderr, "Error registering callback for sensor 2!\n");
        fclose(log_file);
        gpioTerminate();
        return 1;
    }

    // Set alert pin LOW initially
    gpioWrite(ALERT_PIN, 0);
    printf("Alert pin set LOW initially\n");

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Seismic monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        gpioDelay(100); // Reduce CPU usage
    }

    return 0;
}

