// Configuration
#define SPI_CHANNEL 0
#define SPI_SPEED 1000000 // 1 MHz
#define CS_PIN 8          // GPIO8 (CE0)
#define SCLK_PIN 11       // GPIO11
#define MOSI_PIN 10       // GPIO10
#define MISO_PIN 9        // GPIO9
#define LED_PIN 17         // GPIO17
#define THRESHOLD 20.0   // Degrees per second
#define BUFFER_SIZE 100
#define SAMPLE_RATE_HZ 10

// Data structure for circular buffer
typedef struct {
    struct timespec timestamp;
    float angular_rate;
} Reading;

// Circular buffer
Reading buffer[BUFFER_SIZE];
int buffer_index = 0;
int buffer_count = 0;
pthread_mutex_t buffer_mutex = PTHREAD_MUTEX_INITIALIZER;

// Global variables
int spi_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int spi_transfer(int handle, uint8_t address, uint8_t *data, int count);
int read_gyro_data(int handle, float *angular_rate);
void add_reading(float angular_rate);
void *monitor_threshold(void *arg);
void signal_handler(int signal);

// SPI transfer function
int spi_transfer(int handle, uint8_t address, uint8_t *data, int count) {
    char tx_buffer[count + 1];
    char rx_buffer[count + 1];

    // Construct the transmit buffer
    tx_buffer[0] = address | 0x80; // Set MSB for read operation
    for (int i = 0; i < count; i++) {
        tx_buffer[i + 1] = data[i];
    }

    gpioWrite(CS_PIN, 0); // Select the chip
    int result = spiXfer(handle, tx_buffer, rx_buffer, count + 1);
    gpioWrite(CS_PIN, 1); // Deselect the chip

    if (result != count + 1) {
        fprintf(stderr, "SPI transfer failed: %d\n", result);
        return -1;
    }

    // Extract the received data
    for (int i = 0; i < count; i++) {
        data[i] = rx_buffer[i + 1];
    }

    return 0;
}

// Function to read gyroscope data
int read_gyro_data(int handle, float *angular_rate) {
    uint8_t data[2];

    if (spi_transfer(handle, 0x00, data, 2) != 0) {
        fprintf(stderr, "Failed to read gyroscope data\n");
        return -1;
    }

    // Combine the two bytes into a 16-bit signed integer
    int16_t raw_data = (data[0] << 8) | data[1];

    // Convert raw data to degrees per second (assuming +/- 250 dps range)
    *angular_rate = (float)raw_data / 131.0; // Sensitivity for ADXRS290 is 131 LSB/deg/s

    return 0;
}

