#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the lamps
#define LAMP1_GPIO 17
#define LAMP2_GPIO 18
#define LAMP3_GPIO 27

// Define PWM frequency (100 Hz)
#define PWM_FREQUENCY 100

// Define PWM range (0-255)
#define PWM_RANGE 255

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, terminating program...\n", signal);
}

// Function to initialize the pigpio library and set GPIO modes
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(LAMP1_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP2_GPIO, PI_OUTPUT);
    gpioSetMode(LAMP3_GPIO, PI_OUTPUT);

    return 0;
}

// Function to set the PWM duty cycle for a given GPIO pin
void set_pwm_duty_cycle(int gpio_pin, int duty_cycle) {
    gpioPWM(gpio_pin, duty_cycle);
}

// Function to fade a lamp from full brightness to off
void fade_lamp(int gpio_pin, int total_duration_seconds) {
    int current_duty_cycle = 0;
    int increment = 1; // Increment duty cycle by 1 each iteration

    // Calculate the number of steps to fade over the specified duration
    int steps = total_duration_seconds * PWM_FREQUENCY;

    // Fade from full brightness to off
    for (int i = 0; i < steps && program_running; ++i) {
        current_duty_cycle += increment;
        if (current_duty_cycle > PWM_RANGE) {
            current_duty_cycle = PWM_RANGE;
            increment = -1; // Decrement duty cycle
        } else if (current_duty_cycle < 0) {
            current_duty_cycle = 0;
            increment = 1; // Increment duty cycle
        }

        set_pwm_duty_cycle(gpio_pin, current_duty_cycle);
        gpioDelay(1000000 / PWM_FREQUENCY); // Delay for 1 ms (adjust as needed)
    }

    // Ensure the lamp is fully off at the end
    set_pwm_duty_cycle(gpio_pin, 0);
}

// Function to simulate sunset
void simulate_sunset(int total_duration_seconds) {
    printf("Simulating sunset for %d seconds...\n", total_duration_seconds);

    // Fade lamp 1
    fade_lamp(LAMP1_GPIO, total_duration_seconds);
    printf("Lamp 1 faded to off.\n");

    // Fade lamp 2
    fade_lamp(LAMP2_GPIO, total_duration_seconds);
    printf("Lamp 2 faded to off.\n");

    // Fade lamp 3
    fade_lamp(LAMP3_GPIO, total_duration_seconds);
    printf("Lamp 3 faded to off.\n");

    printf("Sunset simulation complete.\n");
}

int main(int argc, char *argv[]) {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Check command-line argument
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <total_duration_seconds>\n", argv[0]);
        return 1;
    }

    // Validate total duration
    int total_duration_seconds = atoi(argv[1]);
    if (total_duration_seconds < 1 || total_duration_seconds > 3600) {
        fprintf(stderr, "Error: Total duration must be between 1 and 3600 seconds.\n");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Set PWM frequency and range
    gpioSetPWMfrequency(LAMP1_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP2_GPIO, PWM_FREQUENCY);
    gpioSetPWMfrequency(LAMP3_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(LAMP1_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP2_GPIO, PWM_RANGE);
    gpioSetPWMrange(LAMP3_GPIO, PWM_RANGE);

    // Simulate sunset
    simulate_sunset(total_duration_seconds);

    // Turn off all lamps
    set_pwm_duty_cycle(LAMP1_GPIO, 0);
    set_pwm_duty_cycle(LAMP2_GPIO, 0);
    set_pwm_duty_cycle(LAMP3_GPIO, 0);

    // Release GPIO resources
    gpioTerminate();

    return 0;
}

