#define YELLOW_PIN 22
#define GREEN_PIN 23
#define YELLOW_PIN 24

// Define the duration of each state in seconds
#define RED_DURATION   10
#define RED_YELLOW_DURATION 2
#define GREEN_DURATION 10
#define YELLOW_DURATION 3

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT (Ctrl+C)
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the state of a GPIO pin
int set_gpio_state(int gpio_pin, int state) {
    int result = gpioWrite(gpio_pin, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio_pin, result);
        return -1;
    }
    return 0;
}

// Function to simulate the traffic light sequence
void traffic_light_sequence() {
    // Red
    if (set_gpio_state(RED_PIN, 0) != 0) return;
    printf("Red\n");
    sleep(RED_DURATION);

    // Red + Yellow
    if (set_gpio_state(RED_PIN, 1) != 0) return;
    if (set_gpio_state(YELLOW_PIN, 0) != 0) return;
    printf("Red + Yellow\n");
    sleep(RED_YELLOW_DURATION);

    // Green
    if (set_gpio_state(GREEN_PIN, 0) != 0) return;
    printf("Green\n");
    sleep(GREEN_DURATION);

    // Yellow
    if (set_gpio_state(YELLOW_PIN, 1) != 0) return;
    printf("Yellow\n");
    sleep(YELLOW_DURATION);
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    if (gpioSetMode(RED_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", RED_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(YELLOW_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", YELLOW_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(GREEN_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", GREEN_PIN);
        gpioTerminate();
        return 1;
    }
    if (gpioSetMode(YELLOW_PIN, PI_OUTPUT) != 0) {
        fprintf(stderr, "Failed to set GPIO %d as output\n", YELLOW_PIN);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        traffic_light_sequence();
    }

    // Clean up GPIO pins before exiting
    set_gpio_state(RED_PIN, 1); // Turn off red
    set_gpio_state(YELLOW_PIN, 1); // Turn off yellow
    set_gpio_state(GREEN_PIN, 1); // Turn off green
    set_gpio_state(YELLOW_PIN, 1); // Turn off yellow

    // Terminate the pigpio library
    gpioTerminate();

    return 0;
}

