#include <wiringPi.h>
#include <wiringPiI2C.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define constants
#define MPR121_I2C_ADDR 0x5A
#define RELAY_PIN 17
#define DEBOUNCE_DELAY_MS 100
#define TOUCH_THRESHOLD 40
#define RELEASE_THRESHOLD 20
#define RELAY_TOGGLE_DELAY_MS 500

// Global variables
int i2c_fd;
FILE *log_file;
bool relay_state = false;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void debounce_touch(uint16_t touch_status);
void toggle_relay();
void log_error(const char *message);
void signal_handler(int signal);

// Function to initialize the MPR121
int mpr121_init() {
    // Stop mode
    if (wiringPiI2CWriteReg8(i2c_fd, 0x80, 0x63) < 0) {
        log_error("Failed to set MPR121 to stop mode.");
        return -1;
    }
    delay(1);

    // Electrode configuration
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5E, 0xC0) < 0) {
        log_error("Failed to set MPR121 electrode configuration.");
        return -1;
    }
    if (wiringPiI2CWriteReg8(i2c_fd, 0x5F, 0x01) < 0) {
        log_error("Failed to set MPR121 electrode configuration.");
        return -1;
    }

    // Touch and release thresholds
    for (int i = 0; i < 12; i++) {
        if (wiringPiI2CWriteReg8(i2c_fd, 0x41 + (i * 2), TOUCH_THRESHOLD) < 0) {
            log_error("Failed to set MPR121 touch threshold.");
            return -1;
        }
        if (wiringPiI2CWriteReg8(i2c_fd, 0x42 + (i * 2), RELEASE_THRESHOLD) < 0) {
            log_error("Failed to set MPR121 release threshold.");
            return -1;
        }
    }

    // Enter run mode
    if (wiringPiI2CWriteReg8(i2c_fd, 0x80, 0x10) < 0) {
        log_error("Failed to set MPR121 to run mode.");
        return -1;
    }
    delay(1);

    return 0;
}

// Function to read touch status from the MPR121
int read_touch_status(uint16_t *touch_status) {
    int msb = wiringPiI2CReadReg8(i2c_fd, 0x00);
    int lsb = wiringPiI2CReadReg8(i2c_fd, 0x01);

    if (msb < 0 || lsb < 0) {
        log_error("Failed to read touch status from MPR121.");
        return -1;
    }

    *touch_status = (msb << 8) | lsb;
    return 0;
}

// Function to debounce touch events
void debounce_touch(uint16_t touch_status) {
    delay(DEBOUNCE_DELAY_MS);
    uint16_t debounced_touch_status = read_touch_status(&touch_status);
    if (debounced_touch_status < 0) {
        log_error("Failed to read touch status after debounce.");
        return;
    }

    if (touch_status != debounced_touch_status) {
        // Re-read the status after the debounce delay
        delay(DEBOUNCE_DELAY_MS);
        debounced_touch_status = read_touch_status(&touch_status);
        if (debounced_touch_status < 0) {
            log_error("Failed to read touch status after second debounce.");
            return;
        }

        if (touch_status != debounced_touch_status) {
            // Re-read the status after the debounce delay
            delay(DEBOUNCE_DELAY_MS);
            debounced_touch_status = read_touch_status(&touch_status);
            if (debounced_touch_status < 0) {
                log_error("Failed to read touch status after third debounce.");
                return;
            }

            if (touch_status != debounced_touch_status) {
                // Electrode 0 touched
                if (touch_status & 0x01) {
                    toggle_relay();
                }
            }
        }
    }
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    digitalWrite(RELAY_PIN, relay_state ? HIGH : LOW);
    char log_message[100];
    snprintf(log_message, sizeof(log_message), "Relay toggled to %s", relay_state ? "HIGH" : "LOW");
    log_error(log_message);
}

// Function to log errors to a file
void log_error(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: %s\n", timestamp, message);
    fflush(log_file); // Ensure the log is written immediately
    perror(message); // Also print to stderr
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    digitalWrite(RELAY_PIN, LOW); // Ensure relay is off
    close(i2c_fd);
    fclose(log_file);
    exit(0);
}

int main() {
    // Initialize wiringPi
    if (wiringPiSetupGpio() == -1) {
        fprintf(stderr, "wiringPiSetupGpio failed, exiting...\n");
        return 1;
    }

    // Initialize I2C
    i2c_fd = wiringPiI2CSetup(MPR121_I2C_ADDR);
    if (i2c_fd == -1) {
        fprintf(stderr, "wiringPiI2CSetup failed, exiting...\n");
        return 1;
    }

    // Initialize MPR121
    if (mpr121_init() == -1) {
        fprintf(stderr, "MPR121 initialization failed, exiting...\n");
        return 1;
    }

    // Set relay pin as output
    pinMode(RELAY_PIN, OUTPUT);
    digitalWrite(RELAY_PIN, LOW); // Initialize relay to LOW

    // Open log file
    log_file = fopen("touch_relay.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file, exiting...\n");
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    uint16_t touch_status;

    // Main loop
    while (1) {
        if (read_touch_status(&touch_status) == 0) {
            debounce_touch(touch_status);
        } else {
            log_error("Failed to read touch status, retrying...");
        }
        delay(10); // Check every 10ms
    }

    return 0;
}

