#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins
#define FLAME_SENSOR_PIN 17
#define BUZZER_PIN 18
#define LED_PIN 23

// Define log file name
#define LOG_FILE "flame_log.txt"

// Define debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_flame_sensor();
void log_flame_event(const char *timestamp);
void activate_buzzer_led(int duration_ms);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to read the flame sensor
int read_flame_sensor() {
    int value = gpioRead(FLAME_SENSOR_PIN);
    if (value < 0) {
        fprintf(stderr, "Error reading flame sensor: %d\n", value);
        return -1; // Indicate error
    }
    return value;
}

// Function to log a flame event to a file
void log_flame_event(const char *timestamp) {
    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open.\n");
        return;
    }

    fprintf(log_file, "%s - Flame Detected\n", timestamp);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Function to activate the buzzer and LED for a specified duration
void activate_buzzer_led(int duration_ms) {
    gpioWrite(BUZZER_PIN, 1); // Turn on buzzer
    gpioWrite(LED_PIN, 1);    // Turn on LED
    gpioDelay(duration_ms * 1000); // Delay for specified duration (microseconds)
    gpioWrite(BUZZER_PIN, 0); // Turn off buzzer
    gpioWrite(LED_PIN, 0);    // Turn off LED
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(FLAME_SENSOR_PIN, PI_INPUT);
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Flame sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int flame_detected = 0;
        int consecutive_low_count = 0;

        // Read flame sensor with debouncing
        for (int i = 0; i < 3; i++) {
            int sensor_value = read_flame_sensor();
            if (sensor_value == 0) {
                flame_detected = 1;
                consecutive_low_count++;
                gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            } else if (sensor_value < 0) {
                // Error reading sensor, exit loop
                break;
            } else {
                // Sensor value is HIGH, reset count
                consecutive_low_count = 0;
                gpioDelay(DEBOUNCE_DELAY * 1000); // Debounce delay
            }
        }

        // Check if all three readings were LOW
        if (flame_detected && consecutive_low_count == 3) {
            // Get current timestamp
            time_t rawtime;
            struct tm *timeinfo;
            char timestamp[20];

            time(&rawtime);
            timeinfo = localtime(&rawtime);

            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

            // Log the event
            log_flame_event(timestamp);

            // Activate buzzer and LED
            activate_buzzer_led(500); // Activate for 500ms
        }

        gpioDelay(100 * 1000); // Check every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    gpioWrite(BUZZER_PIN, 0); // Ensure buzzer is off
    gpioWrite(LED_PIN, 0);    // Ensure LED is off
    fclose(log_file);
    gpioTerminate();

    printf("Exiting.\n");
    return 0;
}

