#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Motor A GPIO pins
#define MOTOR_A_FORWARD 17
#define MOTOR_A_BACKWARD 18

// Motor B GPIO pins
#define MOTOR_B_FORWARD 22
#define MOTOR_B_BACKWARD 23

// Enable A GPIO pin
#define ENABLE_A 24

// Enable B GPIO pin
#define ENABLE_B 25

// PID gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// PWM frequency
#define PWM_FREQUENCY 1000

// Log file name
#define LOG_FILE "balance_log.txt"

// Global variables
FILE *log_file = NULL;
volatile sig_atomic_t program_running = 1;

// PID variables
float integral = 0.0;
float previous_error = 0.0;

// Function prototypes
float generate_tilt_error();
float read_distance();
void set_motor_speed(int motor, int speed);
void stop_motors();
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed);
void signal_handler(int signal);

// Function to generate a random tilt error
float generate_tilt_error() {
    return (float)(rand() % 201 - 100) / 10.0;
}

// Function to read distance from the ultrasonic sensor
float read_distance() {
    // Simulate reading a distance between 2.0 and 400.0 cm
    return (float)(rand() % 381 + 20);
}

// Function to set motor speed
void set_motor_speed(int motor, int speed) {
    if (speed > 255) speed = 255;
    if (speed < -255) speed = -255;

    if (motor == 1) {
        if (speed > 0) {
            gpioWrite(MOTOR_A_FORWARD, 1);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENABLE_A, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 1);
            gpioPWM(ENABLE_A, -speed);
        } else {
            gpioWrite(MOTOR_A_FORWARD, 0);
            gpioWrite(MOTOR_A_BACKWARD, 0);
            gpioPWM(ENABLE_A, 0);
        }
    } else if (motor == 2) {
        if (speed > 0) {
            gpioWrite(MOTOR_B_FORWARD, 1);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENABLE_B, speed);
        } else if (speed < 0) {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 1);
            gpioPWM(ENABLE_B, -speed);
        } else {
            gpioWrite(MOTOR_B_FORWARD, 0);
            gpioWrite(MOTOR_B_BACKWARD, 0);
            gpioPWM(ENABLE_B, 0);
        }
    } else {
        fprintf(stderr, "Invalid motor number: %d\n", motor);
    }
}

// Function to stop motors
void stop_motors() {
    gpioWrite(MOTOR_A_FORWARD, 0);
    gpioWrite(MOTOR_A_BACKWARD, 0);
    gpioWrite(MOTOR_B_FORWARD, 0);
    gpioWrite(MOTOR_B_BACKWARD, 0);
    gpioPWM(ENABLE_A, 0);
    gpioPWM(ENABLE_B, 0);
}

// Function to log data to file
void log_data(float tilt_error, float distance, int motor_a_speed, int motor_b_speed) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.2f,%.2f,%d,%d\n", timestamp, tilt_error, distance, motor_a_speed, motor_b_speed);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, stopping motors and exiting...\n", signal);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(MOTOR_A_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_A_BACKWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_FORWARD, PI_OUTPUT);
    gpioSetMode(MOTOR_B_BACKWARD, PI_OUTPUT);
    gpioSetMode(ENABLE_A, PI_OUTPUT);
    gpioSetMode(ENABLE_B, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(ENABLE_A, PWM_FREQUENCY);
    gpioSetPWMfrequency(ENABLE_B, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(ENABLE_A, 255);
    gpioSetPWMrange(ENABLE_B, 255);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    // Seed the random number generator
    srand(time(NULL));

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Balance robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Generate tilt error
        float tilt_error = generate_tilt_error();

        // Read distance
        float distance = read_distance();

        // Calculate PID output
        float error = tilt_error;
        integral += error;
        float derivative = error - previous_error;
        float output = KP * error + KI * integral + KD * derivative;

        // Clamp PID output to -255 to 255
        if (output > 255) output = 255;
        if (output < -255) output = -255;

        // Calculate motor speeds
        int motor_a_speed = (int)(output + 128); // Adjust 128 for centering
        int motor_b_speed = (int)(output - 128); // Adjust 128 for centering

        // Set motor speeds
        set_motor_speed(1, motor_a_speed);
        set_motor_speed(2, motor_b_speed);

        // Log data
        log_data(tilt_error, distance, motor_a_speed, motor_b_speed);

        // Update previous error
        previous_error = error;

        // Delay
        gpioDelay(50000); // 50ms
    }

    // Stop motors before exiting
    stop_motors();

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    printf("Balance robot stopped.\n");

    return 0;
}

