#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    // Set touch sensor pin as input with pull-down resistor
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(TOUCH_SENSOR_PIN, PI_PUD_DOWN);

    // Set relay pin as output
    gpioSetMode(RELAY_PIN, PI_OUTPUT);
    gpioWrite(RELAY_PIN, 0); // Initially turn the relay off

    return 0;
}

// Function to read the touch sensor
int read_touch_sensor() {
    return gpioRead(TOUCH_SENSOR_PIN);
}

// Function to toggle the relay state
void toggle_relay() {
    int current_state = gpioRead(RELAY_PIN);
    gpioWrite(RELAY_PIN, !current_state);
}

// Function to delay for a specified duration
void delay_ms(int milliseconds) {
    gpioDelay(milliseconds * 1000); // pigpioDelay takes microseconds
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Touch sensor monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read touch sensor
        int touch_detected = read_touch_sensor();

        // Check for touch
        if (touch_detected == 1) {
            printf("Touch detected!\n");

            // Toggle relay
            toggle_relay();

            // Debounce delay
            delay_ms(DEBOUNCE_DELAY);
        }

        // Small delay to prevent busy-waiting
        gpioDelay(10000); // 10ms
    }

    // Cleanup GPIO before exiting
    gpioWrite(RELAY_PIN, 0); // Ensure relay is off
    gpioTerminate();

    printf("Program terminated.\n");
    return 0;
}

