#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// TCS34725 I2C address
#define TCS34725_ADDRESS 0x29

// TCS34725 register addresses
#define TCS34725_ENABLE 0x80
#define TCS34725_ATIME 0x81
#define TCS34725_CONTROL 0x8F
#define TCS34725_CDATA 0x94
#define TCS34725_RDATA 0x96
#define TCS34725_GDATA 0x98
#define TCS34725_BDATA 0x9A

// Integration time values
#define TCS34725_INTEGRATIONTIME_2_4MS 0xFF
#define TCS34725_INTEGRATIONTIME_24MS 0xF6
#define TCS34725_INTEGRATIONTIME_101MS 0xD5
#define TCS34725_INTEGRATIONTIME_154MS 0xC0
#define TCS34725_INTEGRATIONTIME_700MS 0xA0

// Enable register values
#define TCS34725_ENABLE_PON 0x01
#define TCS34725_ENABLE_AEN 0x02

// Global variables
int i2c_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold color data
typedef struct {
    uint16_t clear;
    uint16_t red;
    uint16_t green;
    uint16_t blue;
} color_data_t;

// Function prototypes
int initialize_sensor();
color_data_t read_color_data();
void log_data(color_data_t data);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "\nCaught signal %d, cleaning up...\n", signal);
    terminate = 1;
}

// Initializes the TCS34725 sensor
int initialize_sensor() {
    // Enable power and ALS
    if (i2cWriteByteData(i2c_handle, TCS34725_ENABLE, TCS34725_ENABLE_PON | TCS34725_ENABLE_AEN) < 0) {
        fprintf(stderr, "Error writing to ENABLE register: %d\n", i2c_handle);
        return -1;
    }

    // Set integration time
    if (i2cWriteByteData(i2c_handle, TCS34725_ATIME, TCS34725_INTEGRATIONTIME_154MS) < 0) {
        fprintf(stderr, "Error writing to ATIME register: %d\n", i2c_handle);
        return -1;
    }

    // Set gain (optional, adjust as needed)
    if (i2cWriteByteData(i2c_handle, TCS34725_CONTROL, 0x00) < 0) {
        fprintf(stderr, "Error writing to CONTROL register: %d\n", i2c_handle);
        return -1;
    }

    return 0;
}

// Reads color data from the TCS34725 sensor
color_data_t read_color_data() {
    color_data_t data;
    uint8_t buffer[8];

    // Read all color data registers in one go
    if (i2cReadI2CBlockData(i2c_handle, TCS34725_CDATA, (char *)buffer, 8) != 8) {
        fprintf(stderr, "Error reading color data: %d\n", i2c_handle);
        data.clear = 0;
        data.red = 0;
        data.green = 0;
        data.blue = 0;
        return data;
    }

    // Combine the bytes to form the color values
    data.clear = (buffer[1] << 8) | buffer[0];
    data.red = (buffer[3] << 8) | buffer[2];
    data.green = (buffer[5] << 8) | buffer[4];
    data.blue = (buffer[7] << 8) | buffer[6];

    return data;
}

