#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for relays
#define RELAY1_PIN 17
#define RELAY2_PIN 27
#define RELAY3_PIN 22
#define RELAY4_PIN 23

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 1000

// Define sunrise and sunset durations (seconds)
#define SUNRISE_DURATION 3600
#define SUNSET_DURATION 3600

// Define daytime and nighttime durations (seconds)
#define DAYTIME_DURATION 21600
#define NIGHTTIME_DURATION 50400

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for SIGINT and SIGTERM
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the duty cycle for a relay
void set_relay_duty_cycle(int pin, int duty_cycle) {
    if (duty_cycle < 0 || duty_cycle > 255) {
        fprintf(stderr, "Error: Duty cycle must be between 0 and 255.\n");
        return;
    }

    gpioPWM(pin, duty_cycle);
}

// Function to turn on a relay
void turn_on_relay(int pin) {
    gpioWrite(pin, 0); // Active-low relay
}

// Function to turn off a relay
void turn_off_relay(int pin) {
    gpioWrite(pin, 1); // Active-low relay
}

// Function to simulate sunrise
void simulate_sunrise() {
    printf("Simulating sunrise...\n");
    for (int duty_cycle = 0; duty_cycle <= 255 && program_running; duty_cycle++) {
        set_relay_duty_cycle(RELAY1_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY2_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY3_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY4_PIN, duty_cycle);
        gpioDelay(100000); // 100ms delay
    }
}

// Function to simulate sunset
void simulate_sunset() {
    printf("Simulating sunset...\n");
    for (int duty_cycle = 255; duty_cycle >= 0 && program_running; duty_cycle--) {
        set_relay_duty_cycle(RELAY1_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY2_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY3_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY4_PIN, duty_cycle);
        gpioDelay(100000); // 100ms delay
    }
}

// Function to simulate daytime
void simulate_daytime() {
    printf("Simulating daytime...\n");
    for (int duty_cycle = 0; duty_cycle <= 255 && program_running; duty_cycle++) {
        set_relay_duty_cycle(RELAY1_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY2_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY3_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY4_PIN, duty_cycle);
        gpioDelay(100000); // 100ms delay
    }
}

// Function to simulate nighttime
void simulate_nighttime() {
    printf("Simulating nighttime...\n");
    for (int duty_cycle = 255; duty_cycle >= 0 && program_running; duty_cycle--) {
        set_relay_duty_cycle(RELAY1_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY2_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY3_PIN, duty_cycle);
        set_relay_duty_cycle(RELAY4_PIN, duty_cycle);
        gpioDelay(100000); // 100ms delay
    }
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(RELAY1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(RELAY4_PIN, PWM_FREQUENCY);

    // Set PWM range (0-255)
    gpioSetPWMrange(RELAY1_PIN, 255);
    gpioSetPWMrange(RELAY2_PIN, 255);
    gpioSetPWMrange(RELAY3_PIN, 255);
    gpioSetPWMrange(RELAY4_PIN, 255);

    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        // Sunrise phase
        simulate_sunrise();

        // Daytime phase
        simulate_daytime();

        // Sunset phase
        simulate_sunset();

        // Nighttime phase
        simulate_nighttime();
    }

    // Turn off all relays before exiting
    turn_off_relay(RELAY1_PIN);
    turn_off_relay(RELAY2_PIN);
    turn_off_relay(RELAY3_PIN);
    turn_off_relay(RELAY4_PIN);

    // Terminate pigpio library
    gpioTerminate();

    return 0;
}

