#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define LED_PIN 27

// Define debounce interval (in milliseconds)
#define DEBOUNCE_INTERVAL 200

// Define log file path
#define LOG_FILE "/home/pi/logs/motion_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
int debounce_sensor();
int capture_video();
int log_motion_event();
void cleanup();
void signal_handler(int signal);

// Structure to hold sensor data
typedef struct {
    int pin;
    int led_pin;
    int debounce_interval;
    char *log_file_path;
} sensor_config_t;

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetMode(LED_PIN, PI_OUTPUT);

    gpioWrite(LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to debounce the sensor
int debounce_sensor() {
    gpioDelay(DEBOUNCE_INTERVAL * 1000); // Delay in microseconds
    return read_sensor();
}

// Function to capture a video using raspivid
int capture_video() {
    time_t rawtime;
    struct tm *timeinfo;
    char filename[80];
    char command[200];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(filename, sizeof(filename), "/home/pi/videos/%Y%m%d_%H%M%S.h264", timeinfo);

    snprintf(command, sizeof(command), "raspivid -o %s -t 5000", filename);

    int status = system(command);

    if (status == 0) {
        printf("Video captured successfully: %s\n", filename);
        return 0; // Success
    } else {
        fprintf(stderr, "Error capturing video: %s\n", command);
        return -1; // Failure
    }
}

// Function to log motion event to file
int log_motion_event() {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[30];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s\n", timestamp);
        fflush(log_file); // Ensure data is written to disk immediately
        printf("Motion event logged: %s\n", timestamp);
        return 0; // Success
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1; // Failure
    }
}

// Function to perform cleanup before exiting
void cleanup() {
    printf("Cleaning up...\n");

    if (log_file != NULL) {
        fclose(log_file);
    }

    gpioWrite(LED_PIN, 0); // Turn off LED
    gpioTerminate();       // Terminate pigpio

    printf("Cleanup complete. Exiting.\n");
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting...\n", signal);
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value == 0) { // Obstacle detected (LOW signal)
            if (debounce_sensor() == 0) { // Debounced
                printf("Obstacle detected and debounced!\n");

                if (capture_video() == 0) {
                    if (log_motion_event() != 0) {
                        fprintf(stderr, "Error logging motion event.\n");
                    }
                } else {
                    fprintf(stderr, "Error capturing video.\n");
                }
            }
        }

        gpioDelay(10000); // Check every 10ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

