#include <stdint.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// MPU-6050 I2C address
#define MPU6050_ADDR 0x68

// MPU-6050 registers
#define PWR_MGMT_1   0x6B
#define GYRO_CONFIG  0x1B
#define GYRO_XOUT_H  0x43
#define GYRO_YOUT_H  0x45
#define GYRO_ZOUT_H  0x47

// Sensitivity scale factor for +/- 250°/s range
#define GYRO_SCALE 131.0

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold gyroscope data
typedef struct {
    double timestamp;
    double x_degps;
    double y_degps;
    double z_degps;
} gyro_data_t;

// Function prototypes
int init_mpu6050();
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z);
gyro_data_t process_gyro_data(int16_t x, int16_t y, int16_t z);
int log_data(gyro_data_t data);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize MPU-6050
int init_mpu6050() {
    // Wake up the MPU-6050 (clear sleep mode bit)
    if (i2cWriteByteData(i2c_handle, PWR_MGMT_1, 0) < 0) {
        fprintf(stderr, "Error: Could not wake up MPU-6050\n");
        return -1;
    }

    // Set gyroscope full-scale range to +/- 250°/s
    if (i2cWriteByteData(i2c_handle, GYRO_CONFIG, 0) < 0) {
        fprintf(stderr, "Error: Could not set gyroscope full-scale range\n");
        return -1;
    }

    return 0;
}

// Read gyroscope data from MPU-6050
int read_gyro_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];

    if (i2cReadI2CBlockData(i2c_handle, GYRO_XOUT_H, buf, 6) != 6) {
        fprintf(stderr, "Error: Could not read gyroscope data\n");
        return -1;
    }

    *x = (int16_t)((buf[0] << 8) | buf[1]);
    *y = (int16_t)((buf[2] << 8) | buf[3]);
    *z = (int16_t)((buf[4] << 8) | buf[5]);

    return 0;
}

// Process gyroscope data (convert to degrees per second)
gyro_data_t process_gyro_data(int16_t x, int16_t y, int16_t z) {
    gyro_data_t data;
    struct timespec ts;
    clock_gettime(CLOCK_REALTIME, &ts);

    data.timestamp = (double)ts.tv_sec + (double)ts.tv_nsec / 1000000000.0;
    data.x_degps = (double)x / GYRO_SCALE;
    data.y_degps = (double)y / GYRO_SCALE;
    data.z_degps = (double)z / GYRO_SCALE;

    return data;
}

// Log data to CSV file
int log_data(gyro_data_t data) {
    if (fprintf(log_file, "%.6f,%.6f,%.6f,%.6f\n", data.timestamp, data.x_degps, data.y_degps, data.z_degps) < 0) {
        fprintf(stderr, "Error: Could not write data to log file\n");
        return -1;
    }
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C bus\n");
        gpioTerminate();
        return 1;
    }

    // Initialize MPU-6050
    if (init_mpu6050() < 0) {
        fprintf(stderr, "Error: MPU-6050 initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("gyro_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "timestamp,X_degps,Y_degps,Z_degps\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    int16_t x, y, z;
    while (!terminate) {
        if (read_gyro_data(&x, &y, &z) == 0) {
            gyro_data_t data = process_gyro_data(x, y, z);
            if (log_data(data) != 0) {
                fprintf(stderr, "Error: Failed to log data, attempting re-initialization...\n");
                // Attempt to re-initialize the sensor
                i2cClose(i2c_handle);
                gpioDelay(1000); // Wait 1 second before re-initializing
                i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
                if (i2c_handle < 0) {
                    fprintf(stderr, "Error: Could not re-open I2C bus\n");
                    terminate = 1; // Exit loop if re-initialization fails
                } else {
                    if (init_mpu6050() < 0) {
                        fprintf(stderr, "Error: MPU-6050 re-initialisation failed\n");
                        terminate = 1; // Exit loop if re-initialization fails
                    }
                }
            }
        } else {
            fprintf(stderr, "Error: Failed to read gyro data, attempting re-initialization...\n");
            // Attempt to re-initialize the sensor
            i2cClose(i2c_handle);
            gpioDelay(1000); // Wait 1 second before re-initializing
            i2c_handle = i2cOpen(1, MPU6050_ADDR, 0);
            if (i2c_handle < 0) {
                fprintf(stderr, "Error: Could not re-open I2C bus\n");
                terminate = 1; // Exit loop if re-initialization fails
