#include <stdio.h>
#include <stdlib.h>
#include <pigpio.h>
#include <time.h>
#include <signal.h>
#include <string.h>

// Define GPIO pins for the relays
#define RELAY1_PIN 4
#define RELAY2_PIN 17
#define RELAY3_PIN 27
#define RELAY4_PIN 22

// Define the moisture threshold
#define MOISTURE_THRESHOLD 30

// Define the log file name
#define LOG_FILE "irrigation_log.txt"

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int read_moisture_sensor();
void control_relay(int zone, int state);
void log_data(int moisture1, int moisture2, int moisture3, int moisture4, int relay1_state, int relay2_state, int relay3_state, int relay4_state);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);

    // Deactivate all relays
    control_relay(1, 1); // Turn off relay 1
    control_relay(2, 1); // Turn off relay 2
    control_relay(3, 1); // Turn off relay 3
    control_relay(4, 1); // Turn off relay 4

    // Close the log file
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp != NULL) {
        fprintf(fp, "Program terminated by signal %d\n", signal);
        fclose(fp);
    } else {
        perror("Error closing log file");
    }

    // Terminate the pigpio library
    gpioTerminate();

    exit(0);
}

// Function to initialize the pigpio library and configure GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1; // Indicate failure
    }

    // Set GPIO pins as outputs
    gpioSetMode(RELAY1_PIN, PI_OUTPUT);
    gpioSetMode(RELAY2_PIN, PI_OUTPUT);
    gpioSetMode(RELAY3_PIN, PI_OUTPUT);
    gpioSetMode(RELAY4_PIN, PI_OUTPUT);

    // Initialize all relays to OFF (HIGH)
    control_relay(1, 1);
    control_relay(2, 1);
    control_relay(3, 1);
    control_relay(4, 1);

    return 0; // Indicate success
}

// Function to read the moisture sensor value
int read_moisture_sensor() {
    // Simulate reading a moisture sensor value (replace with actual sensor reading)
    // In a real application, this would involve reading from an ADC or DHT22 sensor
    // For simulation, generate a random value between 0 and 100
    return rand() % 101; // Simulate a value between 0 and 100
}

// Function to control the relay state
void control_relay(int zone, int state) {
    int pin;

    switch (zone) {
        case 1:
            pin = RELAY1_PIN;
            break;
        case 2:
            pin = RELAY2_PIN;
            break;
        case 3:
            pin = RELAY3_PIN;
            break;
        case 4:
            pin = RELAY4_PIN;
            break;
        default:
            fprintf(stderr, "Invalid relay zone: %d\n", zone);
            return;
    }

    gpioWrite(pin, state); // Set the pin HIGH or LOW
}

// Function to log the data to a file
void log_data(int moisture1, int moisture2, int moisture3, int moisture4, int relay1_state, int relay2_state, int relay3_state, int relay4_state) {
    FILE *fp = fopen(LOG_FILE, "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(fp, "%s, Moisture1: %d, Moisture2: %d, Moisture3: %d, Moisture4: %d, Relay1: %s, Relay2: %s, Relay3: %s, Relay4: %s\n",
            timestamp, moisture1, moisture2, moisture3, moisture4,
            relay1_state ? "ON" : "OFF", relay2_state ? "ON" : "OFF", relay3_state ? "ON" : "OFF", relay4_state ? "ON" : "OFF");

    fclose(fp);
}

int main() {
    // Seed the random number generator
    srand(time(NULL));

    // Install signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Smart Greenhouse Irrigation System started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read moisture sensor values
        int moisture1 = read_moisture_sensor();
        int moisture2 = read_moisture_sensor();
        int moisture3 = read_moisture_sensor();
        int moisture4 = read_moisture_sensor();

        // Control relays based on moisture levels
        if (moisture1 < MOISTURE_THRESHOLD) {
            control_relay(1, 0); // Turn on relay 1
        } else {
            control_relay(1, 1); // Turn off relay 1
        }

        if (moisture2 < MOISTURE_THRESHOLD) {
            control_relay(2, 0); // Turn on relay 2
        } else {
            control_relay(2, 1); // Turn off relay 2
        }

        if (moisture3 < MOISTURE_THRESHOLD) {
            control_relay(3, 0); // Turn on relay 3
        } else {
            control_relay(3, 1); // Turn off relay 3
        }

        if (moisture4 < MOISTURE_THRESHOLD) {
            control_relay(4, 0); // Turn on relay 4
        } else {
            control_relay(4, 1); // Turn off relay 4
        }

        // Log the data
        log_data(moisture1, moisture2, moisture3, moisture4,
                gpioRead(RELAY1_PIN), gpioRead(RELAY2_PIN), gpioRead(RELAY3_PIN), gpioRead(RELAY4_PIN));

        // Wait for 5 seconds
        gpioDelay(5000000); // 5 seconds in microseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    control_relay(1, 1); // Turn off relay 1
    control_relay(2, 1); // Turn off relay 2
    control_relay(3, 1); // Turn off relay 3
    control_relay(4, 1); // Turn off relay 4
    gpioTerminate();

    return 0;
}

