#include <math.h>
#include <pigpio.h>

// ADXL345 I2C address
#define ADXL345_ADDRESS 0x53

// ADXL345 registers
#define POWER_CTL 0x2D
#define DATAX0 0x32
#define DATAX1 0x33
#define DATAY0 0x34
#define DATAY1 0x35
#define DATAZ0 0x36
#define DATAZ1 0x37

// Freefall threshold (0.2 g)
#define FREEFALL_THRESHOLD 0.2

// Freefall duration (0.5 seconds)
#define FREEFALL_DURATION 0.5

// Alarm GPIO pin (BCM numbering)
#define ALARM_PIN 27

// Global variables
int i2c_handle;
FILE *log_file;
bool running = true;

// Function prototypes
int adxl345_init();
int read_acceleration(float *x, float *y, float *z);
bool is_freefall(float x, float y, float z);
void trigger_alarm();
void log_event(float x, float y, float z);
void signal_handler(int signal);

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function to initialize the ADXL345 accelerometer
int adxl345_init() {
    // Set POWER_CTL register to start measurement
    if (i2cWriteByteData(i2c_handle, POWER_CTL, 0x08) < 0) {
        fprintf(stderr, "Error: Could not set POWER_CTL register.\n");
        return -1;
    }
    return 0;
}

// Function to read acceleration data from the ADXL345
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int16_t x_raw, y_raw, z_raw;

    // Read 6 bytes of data starting from DATAX0
    if (i2cReadI2CBlockData(i2c_handle, DATAX0, buffer, 6) != 6) {
        fprintf(stderr, "Error: Could not read acceleration data.\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    x_raw = (int16_t)((buffer[1] << 8) | buffer[0]);
    y_raw = (int16_t)((buffer[3] << 8) | buffer[2]);
    z_raw = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to g-force units (assuming +/- 2g range)
    *x = (float)x_raw / 256.0;
    *y = (float)y_raw / 256.0;
    *z = (float)z_raw / 256.0;

    return 0;
}

// Function to detect freefall
bool is_freefall(float x, float y, float z) {
    return (fabs(x) < FREEFALL_THRESHOLD && fabs(y) < FREEFALL_THRESHOLD && fabs(z) < FREEFALL_THRESHOLD);
}

// Function to trigger the alarm
void trigger_alarm() {
    gpioWrite(ALARM_PIN, 1); // Set GPIO high
    gpioDelay(5000);        // Wait for 5 seconds
    gpioWrite(ALARM_PIN, 0); // Set GPIO low
}

// Function to log the event to a file
void log_event(float x, float y, float z) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%.3f,%.3f,%.3f\n", timestamp, x, y, z);
    fflush(log_file); // Ensure data is written to disk immediately
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    running = false;

    // Close I2C handle
    i2cClose(i2c_handle);

    // Set alarm GPIO low
    gpioWrite(ALARM_PIN, 0);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    float x, y, z;
    bool freefall_detected = false;
    time_t start_time;

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C handle
    i2c_handle = i2cOpen(1, ADXL345_ADDRESS, 0); // Bus 1, address 0x53, no flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error: Could not open I2C device. Error code: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize ADXL345
    if (adxl345_init() < 0) {
        fprintf(stderr, "Error: ADXL345 initialisation failed.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set alarm GPIO as output
    gpioSetMode(ALARM_PIN, PI_OUTPUT);

    // Open log file
    log_file = fopen("freefall.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file.\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Freefall detection started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(&x, &y, &z) == 0) {
            // Check for freefall
            if (is_freefall(x, y, z)) {
                if (!freefall_detected) {
                    printf("Freefall detected!\n");
                    log_event(x, y, z);
                    trigger_alarm();
                    freefall_detected = true;
                    start_time = time(NULL);
                } else {
                    // Check if freefall duration has elapsed
                    if (difftime(time(NULL), start_time) >= FREEFALL_DURATION) {
                        printf("Freefall event confirmed.\n");
                        log_event(x, y, z);
                        trigger_alarm();
                        freefall_detected = false; // Reset flag
                    }
                }
            } else {
                freefall_detected = false; // Reset flag if not freefall
            }
        } else {
            fprintf(stderr, "Error reading acceleration data. Retrying...\n");
        }

        gpioDelay(100); // Poll every 100 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    i2cClose(i2c_handle);
    gpioWrite(ALARM_PIN, 0);
    fclose(log_file);
    gpioTerminate();

