#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TRIG_PIN 4
#define ECHO_PIN 18

// Define constants
#define SPEED_OF_SOUND 34300.0 // cm/s
#define TIMEOUT_US 100000      // 100ms timeout
#define MAX_PULSE_WIDTH 23200000 // 4m maximum range

// Global variables
static volatile int pulse_start = 0;
static volatile int pulse_end = 0;
static volatile int pulse_width = 0;
static volatile int timeout_flag = 0;
static FILE *log_file = NULL;
static int running = 1;

// Mutex for protecting shared resources
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void trigger_sensor();
void echo_rising_edge(int gpio, int level, uint32_t tick);
void echo_falling_edge(int gpio, int level, uint32_t tick);
double calculate_distance(int pulse_width);
void log_distance(double distance);
void signal_handler(int signal);

// Function to trigger the ultrasonic sensor
void trigger_sensor() {
    gpioWrite(TRIG_PIN, 1);
    gpioDelay(10); // 10 us trigger pulse
    gpioWrite(TRIG_PIN, 0);
}

// Callback function for rising edge of echo pulse
void echo_rising_edge(int gpio, int level, uint32_t tick) {
    if (level == 1) {
        pulse_start = tick;
    }
}

// Callback function for falling edge of echo pulse
void echo_falling_edge(int gpio, int level, uint32_t tick) {
    if (level == 0) {
        pulse_end = tick;
        pulse_width = pulse_end - pulse_start;

        // Mutex lock
        pthread_mutex_lock(&mutex);
        timeout_flag = 0; // Reset timeout flag
        pthread_mutex_unlock(&mutex);
    }
}

// Function to calculate distance in centimeters
double calculate_distance(int pulse_width) {
    if (pulse_width <= 0) {
        return -1.0; // Indicate invalid pulse width
    }
    return (double)pulse_width * SPEED_OF_SOUND / 2000000.0; // Divide by 2 for one-way distance
}

// Function to log distance to file
void log_distance(double distance) {
    if (distance >= 0) {
        time_t rawtime;
        struct tm *timeinfo;
        char timestamp[30];

        time(&rawtime);
        timeinfo = localtime(&rawtime);

        strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

        fprintf(log_file, "%s,%.2f\n", timestamp, distance);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Invalid distance reading.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TRIG_PIN, PI_OUTPUT);
    gpioSetMode(ECHO_PIN, PI_INPUT);

    // Open log file
    log_file = fopen("distance_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Failed to open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Ultrasonic sensor program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        trigger_sensor();

        // Mutex lock
        pthread_mutex_lock(&mutex);
        timeout_flag = 1; // Set timeout flag
        pthread_mutex_unlock(&mutex);

        // Wait for echo pulse or timeout
        int timeout_count = 0;
        while (pulse_width <= 0 && timeout_count < TIMEOUT_US) {
            gpioDelay(1); // Small delay to avoid busy-waiting
            timeout_count++;
        }

        // Mutex lock
        pthread_mutex_lock(&mutex);
        if (pulse_width > 0) {
            timeout_flag = 0; // Reset timeout flag
        }
        pthread_mutex_unlock(&mutex);

        if (pulse_width > 0) {
            // Calculate distance
            double distance = calculate_distance(pulse_width);

            // Log distance
            log_distance(distance);

            printf("Distance: %.2f cm\n", distance);
        } else if (timeout_flag) {
            fprintf(stderr, "Error: Timeout waiting for echo pulse.\n");
        } else {
            fprintf(stderr, "Error: Invalid pulse width.\n");
        }

        gpioDelay(200); // Delay between trigger cycles
    }

    // Cancel callbacks
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);
    gpioSetAlertFuncEx(ECHO_PIN, NULL, NULL);

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio library
    gpioTerminate();

    // Destroy mutex
    pthread_mutex_destroy(&mutex);

    printf("Program terminated.\n");
    return 0;
}

