#include <stdbool.h>
#include <math.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// LIS3DH I2C address
#define LIS3DH_ADDR 0x18

// LIS3DH register addresses
#define CTRL_REG1 0x20
#define CTRL_REG4 0x23
#define OUT_X_L 0x28
#define OUT_X_H 0x29
#define OUT_Y_L 0x2A
#define OUT_Y_H 0x2B
#define OUT_Z_L 0x2C
#define OUT_Z_H 0x2D

// GPIO pin for buzzer
#define BUZZER_PIN 17

// Default free-fall threshold (0.2 g)
#define DEFAULT_FREEFALL_THRESHOLD 0.2

// Default impact threshold (1.5 g)
#define DEFAULT_IMPACT_THRESHOLD 1.5

// I2C bus
#define I2C_BUS 1

// Global variables
int i2c_handle;
bool running = true;
float freefall_threshold = DEFAULT_FREEFALL_THRESHOLD;
float impact_threshold = DEFAULT_IMPACT_THRESHOLD;

// Function prototypes
int init_i2c();
int init_lis3dh();
int read_acceleration(float *x, float *y, float *z);
float calculate_magnitude(float x, float y, float z);
bool detect_freefall(float magnitude);
bool detect_impact(float magnitude);
void activate_buzzer();
void signal_handler(int signal);
void cleanup();

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    if (argc > 1) {
        freefall_threshold = atof(argv[1]);
        printf("Free-fall threshold set to: %.2f g\n", freefall_threshold);
    }
    if (argc > 2) {
        impact_threshold = atof(argv[2]);
        printf("Impact threshold set to: %.2f g\n", impact_threshold);
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set buzzer pin as output
    gpioSetMode(BUZZER_PIN, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        fprintf(stderr, "I2C initialisation failed\n");
        cleanup();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh() != 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        cleanup();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    accelerometer_data_t accel_data;
    float magnitude;

    // Main loop
    while (running) {
        // Read acceleration data
        if (read_acceleration(&accel_data.x, &accel_data.y, &accel_data.z) == 0) {
            // Calculate acceleration magnitude
            magnitude = calculate_magnitude(accel_data.x, accel_data.y, accel_data.z);

            // Detect freefall
            if (detect_freefall(magnitude)) {
                printf("Freefall detected! Magnitude: %.2f g\n", magnitude);
            }

            // Detect impact
            if (detect_impact(magnitude)) {
                printf("Impact detected! Magnitude: %.2f g\n", magnitude);
                activate_buzzer();
            }
        } else {
            fprintf(stderr, "Failed to read acceleration data\n");
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100 ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

// Initialize I2C interface
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, LIS3DH_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Failed to open I2C device: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Initialize LIS3DH accelerometer
int init_lis3dh() {
    // Enable accelerometer (100 Hz, normal mode)
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG1\n");
        return -1;
    }

    // Set full-scale range to +/- 2g
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) < 0) {
        fprintf(stderr, "Failed to write to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read acceleration data from LIS3DH
int read_acceleration(float *x, float *y, float *z) {
    char buffer[6];
    int16_t raw_x, raw_y, raw_z;

    // Read 6 bytes of data (X_L, X_H, Y_L, Y_H, Z_L, Z_H)
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L | 0x80, buffer, 6) != 6) {
        fprintf(stderr, "Failed to read acceleration data\n");
        return -1;
    }

    // Combine high and low bytes for each axis
    raw_x = (int16_t)((buffer[1] << 8) | buffer[0]);
    raw_y = (int16_t)((buffer[3] << 8) | buffer[2]);
    raw_z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to g-force units (assuming +/- 2g full-scale)
    *x = (float)raw_x / 16384.0f;
    *y = (float)raw_y / 16384.0f;
    *z = (float)raw_z / 16384.0f;

    return 0;
}

// Calculate acceleration magnitude
float calculate_magnitude(float x, float y, float z) {
    return sqrt(x * x + y * y + z * z);
}

// Detect freefall
bool detect_freefall(float magnitude) {
    return magnitude < freefall_threshold;
}

// Detect impact
bool detect_impact(float magnitude) {
    return magnitude > impact_threshold;
}

// Activate buzzer for 1 second
void activate_buzzer() {
    gpioWrite(BUZZER_PIN, 1); // Turn buzzer on
    gpioDelay(1000000);       // Wait for 1 second
    gpioWrite(BUZZER_PIN, 0); // Turn buzzer off
}

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    printf("Ctrl+C pressed. Exiting...\n");
    running = false;
}

// Cleanup resources
void cleanup() {
    // Close I2C device
    i2cClose(i2c_handle);

    // Turn off buzzer
    gpioWrite(BUZZER_PIN, 0);

    // Terminate pigpio
    gpioTerminate();
}

