#define SCALE_FACTOR 0.000061 // 2g/±2g = 0.000061 g/LSB

// Threshold in g
#define DEFAULT_THRESHOLD 2.0

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Structure to hold accelerometer data
typedef struct {
    float x;
    float y;
    float z;
} accelerometer_data_t;

// Function prototypes
int init_lis3dh(int i2c_handle);
accelerometer_data_t read_accelerometer_data(int i2c_handle);
void log_high_acceleration(accelerometer_data_t data, float threshold);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize the LIS3DH accelerometer
int init_lis3dh(int i2c_handle) {
    // Configure CTRL_REG1: 100 Hz data rate, enable all axes
    if (i2cWriteByteData(i2c_handle, CTRL_REG1, 0x77) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG1\n");
        return -1;
    }

    // Configure CTRL_REG4: +/- 2g range, high‑resolution mode
    if (i2cWriteByteData(i2c_handle, CTRL_REG4, 0x00) != 0) {
        fprintf(stderr, "Error writing to CTRL_REG4\n");
        return -1;
    }

    return 0;
}

// Read accelerometer data from the LIS3DH
accelerometer_data_t read_accelerometer_data(int i2c_handle) {
    accelerometer_data_t data;
    char buffer[6];

    // Read 6 bytes of data (X_L, X_H, Y_L, Y_H, Z_L, Z_H)
    if (i2cReadI2CBlockData(i2c_handle, OUT_X_L, buffer, 6) != 6) {
        fprintf(stderr, "Error reading accelerometer data\n");
        data.x = 0.0;
        data.y = 0.0;
        data.z = 0.0;
        return data;
    }

    // Combine high and low bytes for each axis
    int16_t x = (int16_t)((buffer[1] << 8) | buffer[0]);
    int16_t y = (int16_t)((buffer[3] << 8) | buffer[2]);
    int16_t z = (int16_t)((buffer[5] << 8) | buffer[4]);

    // Convert raw values to g units
    data.x = (float)x * SCALE_FACTOR;
    data.y = (float)y * SCALE_FACTOR;
    data.z = (float)z * SCALE_FACTOR;

    return data;
}

// Log high acceleration data to /var/log/high_acceleration.log
void log_high_acceleration(accelerometer_data_t data, float threshold) {
    FILE *fp = fopen("/var/log/high_acceleration.log", "a");
    if (fp == NULL) {
        fprintf(stderr, "Error opening log file\n");
        return;
    }

    time_t t = time(NULL);
    struct tm *tm = localtime(&t);
    char s[64];
    strftime(s, sizeof(s), "%Y-%m-%d %H:%M:%S", tm);

    fprintf(fp, "%s, %.3f, %.3f, %.3f\n", s, data.x, data.y, data.z);
    fclose(fp);

    printf("%s, %.3f, %.3f, %.3f\n", s, data.x, data.y, data.z);

    if (data.x > threshold || data.y > threshold || data.z > threshold) {
        printf("High acceleration detected! Shutting down...\n");
        system("sudo shutdown -h now");
