        } else if (strcmp(argv[1], "-t") == 0 && argc > 2) {
            threshold = strtof(argv[2], NULL);
            if (threshold <= 0) {
                fprintf(stderr, "Error: Invalid threshold. Must be greater than 0.\n");
                return 1;
            }
        } else {
            fprintf(stderr, "Usage: %s [-a i2c_address] [-t threshold]\n", argv[0]);
            return 1;
        }
    }

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize LIS3DH
    if (init_lis3dh(i2c_handle) != 0) {
        fprintf(stderr, "LIS3DH initialisation failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (!terminate) {
        accelerometer_data_t data = read_accelerometer_data(i2c_handle);
        log_high_acceleration(data, threshold);
        gpioDelay(100); // 100 ms delay
    }

    // Cleanup
    i2cClose(i2c_handle);
    gpioTerminate();

    return 0;
}

