#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LEFT_SENSOR_PIN 4
#define CENTER_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27
#define ALERT_LED_PIN 22

// Define circular buffer size
#define BUFFER_SIZE 5

// Structure to hold sensor readings
typedef struct {
    int left;
    int center;
    int right;
} SensorReadings;

// Circular buffer
SensorReadings sensor_buffer[BUFFER_SIZE];
int buffer_index = 0;

// Function prototypes
int initialize_gpio();
SensorReadings read_sensors();
void log_sensor_data(SensorReadings readings);
void control_motor(int direction);
void handle_error(const char *message);
void cleanup_gpio();
void signal_handler(int signal);

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio library
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    printf("Autonomous line following robot started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read sensor data
        SensorReadings readings = read_sensors();

        // Log sensor data
        log_sensor_data(readings);

        // Control the motor based on sensor readings
        if (readings.center == 0) {
            control_motor(1); // Move forward
        } else if (readings.left == 0) {
            control_motor(2); // Turn left
        } else if (readings.right == 0) {
            control_motor(3); // Turn right
        } else {
            control_motor(0); // Stop
        }

        // Check for no line condition
        int no_line_count = 0;
        for (int i = 0; i < BUFFER_SIZE; i++) {
            if (sensor_buffer[i].center == 1) {
                no_line_count++;
            }
        }

        if (no_line_count >= 5) {
            printf("No line detected for 5 consecutive readings. Stopping.\n");
            control_motor(0); // Stop
            gpioWrite(ALERT_LED_PIN, 1); // Turn on alert LED
            gpioDelay(2000); // Wait for 2 seconds
            gpioWrite(ALERT_LED_PIN, 0); // Turn off alert LED
            no_line_count = 0; // Reset counter
        }

        gpioDelay(10); // Poll every 10 milliseconds
    }

    // Cleanup GPIO resources before exiting
    cleanup_gpio();

    printf("Autonomous line following robot stopped.\n");
    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO pins as input or output
    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(CENTER_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetMode(ALERT_LED_PIN, PI_OUTPUT);

    // Initialize alert LED to off
    gpioWrite(ALERT_LED_PIN, 0);

    return 0;
}

// Read sensor data
SensorReadings read_sensors() {
    SensorReadings readings;
    readings.left = gpioRead(LEFT_SENSOR_PIN);
    readings.center = gpioRead(CENTER_SENSOR_PIN);
    readings.right = gpioRead(RIGHT_SENSOR_PIN);

    // Basic error checking
    if (readings.left < 0 || readings.center < 0 || readings.right < 0) {
        handle_error("Error reading sensor data");
        readings.left = 1; // Return 1 to avoid further issues
        readings.center = 1;
        readings.right = 1;
    }

    return readings;
}

// Log sensor data to circular buffer
void log_sensor_data(SensorReadings readings) {
    sensor_buffer[buffer_index] = readings;
    buffer_index = (buffer_index + 1) % BUFFER_SIZE;
}

// Control the motor based on sensor readings
void control_motor(int direction) {
    switch (direction) {
        case 1: // Move forward
            printf("Moving forward.\n");
            gpioWrite(LEFT_SENSOR_PIN, 1);
            gpioWrite(CENTER_SENSOR_PIN, 1);
            gpioWrite(RIGHT_SENSOR_PIN, 1);
            break;
        case 2: // Turn left
            printf("Turning left.\n");
            gpioWrite(LEFT_SENSOR_PIN, 0);
            gpioWrite(CENTER_SENSOR_PIN, 1);
            gpioWrite(RIGHT_SENSOR_PIN, 1);
            break;
        case 3: // Turn right
            printf("Turning right.\n");
            gpioWrite(LEFT_SENSOR_PIN, 1);
            gpioWrite(CENTER_SENSOR_PIN, 0);
            gpioWrite(RIGHT_SENSOR_PIN, 1);
            break;
        case 0: // Stop
            printf("Stopping.\n");
            gpioWrite(LEFT_SENSOR_PIN, 0);
            gpioWrite(CENTER_SENSOR_PIN, 0);
            gpioWrite(RIGHT_SENSOR_PIN, 0);
            break;
        default:
            fprintf(stderr, "Invalid motor direction: %d\n", direction);
            break;
    }
}

// Handle errors
void handle_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioWrite(ALERT_LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

