#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SI7210_ADDR 0x40
#define RELAY_GPIO 17
#define THRESHOLD_MT 5.0
#define SAMPLE_INTERVAL_MS 100
#define MAX_RETRIES 50
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z);
float calculate_magnitude(int16_t x, int16_t y, int16_t z);
int control_relay(int state);
int log_event(const char *event_type, float magnitude);
void signal_handler(int signal);

// Structure for sensor data
typedef struct {
    int16_t x;
    int16_t y;
    int16_t z;
} sensor_data_t;

// Function to initialize the I2C interface
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, SI7210_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Function to read sensor data from the Si7210
int read_sensor_data(int16_t *x, int16_t *y, int16_t *z) {
    char buf[6];
    int result;
    int retries = 0;

    while (retries < MAX_RETRIES) {
        result = i2cReadI2CBlockData(i2c_handle, 0x00, buf, 6); // Read 6 bytes starting from register 0x00
        if (result == 6) {
            *x = (int16_t)((buf[0] << 8) | buf[1]);
            *y = (int16_t)((buf[2] << 8) | buf[3]);
            *z = (int16_t)((buf[4] << 8) | buf[5]);
            return 0; // Success
        } else {
            fprintf(stderr, "Error reading sensor data: %d (attempt %d)\n", result, retries + 1);
            gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
            retries++;
        }
    }

    fprintf(stderr, "Failed to read sensor data after %d retries\n", MAX_RETRIES);
    return -1; // Failure
}

// Function to calculate the magnitude of the magnetic field
float calculate_magnitude(int16_t x, int16_t y, int16_t z) {
    return sqrt(x * x + y * y + z * z) / 1000.0; // Convert to mT
}

// Function to control the relay
int control_relay(int state) {
    int result = gpioWrite(RELAY_GPIO, state);
