#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

#define GPIO_PIN 18
#define PORT 5000
#define BUFFER_SIZE 1024
#define LOG_FILE "relay_log.txt"

// Global variables for signal handling
volatile sig_atomic_t program_running = 1;
int server_socket = -1;
int client_socket = -1;
FILE *log_file = NULL;

// Function prototypes
void signal_handler(int signal);
int setup_gpio();
int setup_socket();
void handle_client(int client_socket);
void log_event(const char *event_type);
void cleanup();

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Setup GPIO pin
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(GPIO_PIN, PI_OUTPUT);
    gpioWrite(GPIO_PIN, 0); // Ensure relay is initially off
    return 0;
}

// Setup socket
int setup_socket() {
    int server_socket = socket(AF_INET, SOCK_STREAM, 0);
    if (server_socket == -1) {
        perror("Error creating socket");
        return -1;
    }

    struct sockaddr_in server_address;
    server_address.sin_family = AF_INET;
    server_address.sin_addr.s_addr = INADDR_ANY;
    server_address.sin_port = htons(PORT);

    if (bind(server_socket, (struct sockaddr *)&server_address, sizeof(server_address)) < 0) {
        perror("Error binding socket");
        close(server_socket);
        return -1;
    }

    if (listen(server_socket, 5) < 0) {
        perror("Error listening on socket");
        close(server_socket);
        return -1;
    }

    return server_socket;
}

// Handle client connection
void handle_client(int client_socket) {
    char buffer[BUFFER_SIZE];
    ssize_t bytes_received;

    while (program_running) {
        bytes_received = recv(client_socket, buffer, BUFFER_SIZE - 1, 0);
        if (bytes_received > 0) {
            buffer[bytes_received] = '\0';
            printf("Received: %s\n", buffer);

            // Case-insensitive comparison
            if (strcasecmp(buffer, "ON") == 0) {
                gpioWrite(GPIO_PIN, 1);
                log_event("ON");
                printf("Relay turned ON\n");
            } else if (strcasecmp(buffer, "OFF") == 0) {
                gpioWrite(GPIO_PIN, 0);
                log_event("OFF");
                printf("Relay turned OFF\n");
            } else {
                log_event("INVALID_COMMAND");
                fprintf(stderr, "Invalid command: %s\n", buffer);
            }
        } else if (bytes_received == 0) {
            printf("Client disconnected\n");
            break;
        } else {
            perror("Error receiving data");
            break;
        }
    }

    close(client_socket);
}

// Log event to file
void log_event(const char *event_type) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, event_type);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up resources...\n");

    if (client_socket != -1) {
        close(client_socket);
    }
    if (server_socket != -1) {
        close(server_socket);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_PIN, 0); // Ensure relay is off
    gpioTerminate();

    printf("Cleanup complete. Exiting.\n");
}

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Setup GPIO
    if (setup_gpio() != 0) {
        return 1;
    }

    // Setup socket
    server_socket = setup_socket();
    if (server_socket == -1) {
        cleanup();
        return 1;
    }

    printf("Relay control server started on port %d. Listening...\n", PORT);

    while (program_running) {
        struct sockaddr_in client_address;
        socklen_t client_address_len = sizeof(client_address);
        client_socket = accept(server_socket, (struct sockaddr *)&client_address, &client_address_len);
        if (client_socket == -1) {
            perror("Error accepting connection");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted from %s:%d\n", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        // Open log file
        log_file = fopen(LOG_FILE, "a");
        if (log_file == NULL) {
            perror("Error opening log file");
            close(client_socket);
            continue; // Continue listening for other connections
        }

        // Handle client connection
        handle_client(client_socket);

        // Cleanup resources
        fclose(log_file);
        client_socket = -1; // Reset client_socket to -1 to avoid double close
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

