#include <time.h>
#include <signal.h>
#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define SENSOR1_ADDR 0x36
#define SENSOR2_ADDR 0x37
#define RELAY_GPIO 18
#define FLOW_THRESHOLD 5.0 // ml/min
#define POLLING_INTERVAL 100 // ms
#define LOG_FILE "flow_log.txt"

// Global variables
int i2c_handle1 = -1;
int i2c_handle2 = -1;
FILE *log_file = NULL;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c(int bus, int addr);
int read_flow_rate(int handle);
float convert_to_ml_per_min(int raw_flow);
int log_flow_rate(float flow1, float flow2);
int control_relay(int gpio, int state);
void cleanup(int i2c_handle1, int i2c_handle2, FILE *log_file);
void signal_handler(int signal);

// CRC-8 calculation function
uint8_t crc8(const uint8_t *data, int len) {
    uint8_t crc = 0xFF;
    for (int i = 0; i < len; i++) {
        crc ^= data[i];
        for (int j = 0; j < 8; j++) {
            if (crc & 0x80) {
                crc = (crc << 1) ^ 0x31;
            } else {
                crc <<= 1;
            }
        }
    }
    return crc;
}

// Initialize I2C bus
int initialize_i2c(int bus, int addr) {
    int handle = i2cOpen(bus, addr, 0);
    if (handle < 0) {
        fprintf(stderr, "Error opening I2C bus %d at address 0x%02X: %d\n", bus, addr, handle);
        return -1;
    }
    return handle;
}

// Read flow rate from sensor
int read_flow_rate(int handle) {
    char cmd[2] = {0x36, 0x08}; // Start measurement command
    char buf[3];
    int bytes_read;

    // Send start measurement command
    if (i2cWriteDevice(handle, cmd, 2) != 0) {
        fprintf(stderr, "Error writing to I2C device: %d\n", handle);
        return -1;
    }

    // Wait for measurement to complete (adjust as needed based on datasheet)
    gpioDelay(10); // 10 ms delay

    // Read 3 bytes of data
    bytes_read = i2cReadDevice(handle, buf, 3);
    if (bytes_read != 3) {
        fprintf(stderr, "Error reading from I2C device: %d, read %d bytes\n", handle, bytes_read);
        return -1;
    }

    // CRC check
    uint8_t crc = crc8(buf, 2);
    if (crc != buf[2]) {
        fprintf(stderr, "CRC check failed for sensor %d\n", handle);
        return -1;
    }

    // Convert raw data to flow rate (adjust scaling factor as needed)
    int raw_flow = (buf[0] << 8) | buf[1];
    return raw_flow;
}

// Convert raw flow rate to ml/min
float convert_to_ml_per_min(int raw_flow) {
    // Conversion factor from SLF3S-1300F datasheet (example value, check your sensor's datasheet)
    // This is a placeholder; replace with the correct conversion factor
    float flow_rate = (float)raw_flow * 0.01; // Example conversion
    return flow_rate;
}

// Log flow rate to file
int log_flow_rate(float flow1, float flow2) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[20];

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Sensor 1: %.2f ml/min, Sensor 2: %.2f ml/min\n", timestamp, flow1, flow2);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Control relay
int control_relay(int gpio, int state) {
    if (gpioWrite(gpio, state) != 0) {
        fprintf(stderr, "Error writing to GPIO %d: %d\n", gpio, state);
        return -1;
    }
    return 0;
}

// Cleanup resources
void cleanup(int i2c_handle1, int i2c_handle2, FILE *log_file) {
    printf("Cleaning up resources...\n");
    if (i2c_handle1 >= 0) {
        i2cClose(i2c_handle1);
    }
    if (i2c_handle2 >= 0) {
        i2cClose(i2c_handle2);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is de-energized on exit
    gpioTerminate();
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Signal received (%d). Terminating...\n", signal);
    terminate = 1;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO18 as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    i2c_handle1 = initialize_i2c(I2C_BUS, SENSOR1_ADDR);
    if (i2c_handle1 < 0) {
        cleanup(-1, -1, NULL);
        return 1;
    }

    i2c_handle2 = initialize_i2c(I2C_BUS, SENSOR2_ADDR);
    if (i2c_handle2 < 0) {
        cleanup(i2c_handle1, -1, NULL);
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup(i2c_handle1, i2c_handle2, NULL);
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        int raw_flow1 = read_flow_rate(i2c_handle1);
        int raw_flow2 = read_flow_rate(i2c_handle2);

        if (raw_flow1 >= 0 && raw_flow2 >= 0) {
            float flow1 = convert_to_ml_per_min(raw_flow1);
            float flow2 = convert_to_ml_per_min(raw_flow2);

            log_flow_rate(flow1, flow2);

            // Control relay based on flow rates
            if (flow1 >= FLOW_THRESHOLD && flow2 >= FLOW_THRESHOLD) {
                control_relay(RELAY_GPIO, 1); // Energize relay
            } else {
                control_relay(RELAY_GPIO, 0); // De-energize relay
            }
        } else {
            fprintf(stderr, "Error reading flow rates. Skipping relay control.\n");
        }

        gpioDelay(POLLING_INTERVAL); // Wait for polling interval
    }

    // Cleanup and exit
    cleanup(i2c_handle1, i2c_handle2, log_file);
    return 0;
}

