// Define GPIO pins
#define RAIN_SENSOR_PIN 17
#define MOTOR_ENA_PIN 22
#define MOTOR_IN1_PIN 23
#define MOTOR_IN2_PIN 24

// Define motor activation duration (in seconds)
#define MOTOR_DURATION 5

// Define consecutive dry polls threshold (in milliseconds)
#define CONSECUTIVE_DRY_POLLS 600

// Global variables
static volatile int running = 1;
static volatile int consecutive_dry_polls = 0;
static volatile int last_rain_state = 1; // Assume wet initially

// Function prototypes
int read_rain_sensor();
void close_window();
void stop_motor();
void signal_handler(int signal);
void log_event(const char *message);

// Function to read the rain sensor
int read_rain_sensor() {
    int rain_state = gpioRead(RAIN_SENSOR_PIN);
    if (rain_state < 0) {
        log_event("Error reading rain sensor");
        return -1; // Indicate error
    }
    return rain_state;
}

// Function to close the window
void close_window() {
    log_event("Closing window...");
    gpioWrite(MOTOR_ENA_PIN, 1); // Enable motor
    gpioWrite(MOTOR_IN1_PIN, 1);  // Set IN1 high
    gpioWrite(MOTOR_IN2_PIN, 0);  // Set IN2 low
    gpioDelay(MOTOR_DURATION * 1000000); // Delay for motor duration (microseconds)
    gpioWrite(MOTOR_ENA_PIN, 0); // Disable motor
    gpioWrite(MOTOR_IN1_PIN, 0);  // Set IN1 low
    gpioWrite(MOTOR_IN2_PIN, 0);  // Set IN2 low
    log_event("Window closed.");
}

// Function to stop the motor
void stop_motor() {
    log_event("Stopping motor...");
    gpioWrite(MOTOR_ENA_PIN, 0); // Disable motor
    gpioWrite(MOTOR_IN1_PIN, 0);  // Set IN1 low
    gpioWrite(MOTOR_IN2_PIN, 0);  // Set IN2 low
    log_event("Motor stopped.");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    log_event("Signal received, shutting down...");
    running = 0;
}

// Function to log events with timestamps
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_USER, "%s: %s", timestamp, message);
    printf("%s: %s\n", timestamp, message);
}

int main() {
    // Initialize syslog
    openlog("rain_window", LOG_PID | LOG_CONS, LOG_USER);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        log_event("pigpio initialisation failed");
        closelog();
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_ENA_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);

    // Initialize motor to stop state
    gpioWrite(MOTOR_ENA_PIN, 0);
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);

    log_event("Rain window control system started.");

    // Main loop
    while (running) {
        int rain_state = read_rain_sensor();
        if (rain_state == -1) {
            // Error reading sensor, continue to the next iteration
            gpioDelay(200000); // Wait 200ms before retrying
            continue;
        }

        if (rain_state == 0) {
            // Rain detected
            consecutive_dry_polls = 0; // Reset counter
            log_event("Rain detected!");
        } else {
            // Rain not detected
            consecutive_dry_polls++;
            if (consecutive_dry_polls >= CONSECUTIVE_DRY_POLLS) {
                // Enough consecutive dry polls, close the window
                close_window();
                consecutive_dry_polls = 0; // Reset counter after closing window
            }
        }

        last_rain_state = rain_state;
        gpioDelay(200000); // Wait 200ms
    }

    // Stop the motor before exiting
    stop_motor();

    // Clean up pigpio
    gpioTerminate();

    // Close syslog
    closelog();

    log_event("Rain window control system stopped.");

    return 0;
}

