// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define pulse widths (microseconds)
#define LOCK_PULSE_WIDTH 2000
#define UNLOCK_PULSE_WIDTH 1000

// Debounce delay (milliseconds)
#define DEBOUNCE_DELAY 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to lock the door
int lock_door() {
    int result = gpioServo(SERVO_PIN, LOCK_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Error locking door: %d\n", result);
        return -1;
    }
    printf("Door locked.\n");
    return 0;
}

// Function to unlock the door
int unlock_door() {
    int result = gpioServo(SERVO_PIN, UNLOCK_PULSE_WIDTH);
    if (result != 0) {
        fprintf(stderr, "Error unlocking door: %d\n", result);
        return -1;
    }
    printf("Door unlocked.\n");
    return 0;
}

// Function to shutdown the system
int shutdown_system() {
    int result = gpioServo(SERVO_PIN, 0);
    if (result != 0) {
        fprintf(stderr, "Error shutting down system: %d\n", result);
        return -1;
    }
    printf("System shutting down.\n");
    return 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    // Enable pull-up resistors
    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Door lock system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read button states
        int lock_button_state = gpioRead(LOCK_BUTTON_PIN);
        int unlock_button_state = gpioRead(UNLOCK_BUTTON_PIN);

        // Check for lock button press
        if (lock_button_state == 0) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds

            // Re-read the button state after debounce
            if (gpioRead(LOCK_BUTTON_PIN) == 0) {
                if (lock_door() != 0) {
                    fprintf(stderr, "Error locking door, exiting.\n");
                    program_running = 0; // Exit loop on error
                }
            }
        }

        // Check for unlock button press
        if (unlock_button_state == 0) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // Convert milliseconds to microseconds

            // Re-read the button state after debounce
            if (gpioRead(UNLOCK_BUTTON_PIN) == 0) {
                if (unlock_door() != 0) {
                    fprintf(stderr, "Error unlocking door, exiting.\n");
                    program_running = 0; // Exit loop on error
                }
            }
        }

        // Small delay to prevent busy-waiting
        gpioDelay(10000); // 10ms
    }

    // Shutdown the system before exiting
    shutdown_system();

    // Terminate pigpio library
    gpioTerminate();

    printf("Door lock system stopped.\n");

    return 0;
}

