// Define GPIO pins
#define PIR_SENSOR_PIN 4
#define FLOODLIGHT_PIN 17

// Define log file name
#define LOG_FILE "security_log.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_pir_sensor();
void activate_floodlight();
void deactivate_floodlight();
void log_event(const char *event_type);
void signal_handler(int signal);

// Structure to hold floodlight activation data
typedef struct {
    time_t start_time;
    int duration_seconds;
} FloodlightActivationData;

FloodlightActivationData floodlight_data = {0, 0};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "GPIO initialization failed. Exiting.\n");
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s. Exiting.\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Security system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        // Read PIR sensor
        int motion_detected = read_pir_sensor();

        if (motion_detected) {
            // Activate floodlight
            activate_floodlight();

            // Log event
            log_event("motion_detected");

            // Wait for 60 seconds
            gpioDelay(60000); // 60000 milliseconds = 60 seconds

