bool is_touch_event(uint16_t touch_status, int electrode);
void toggle_relay();
void signal_handler(int signal);

// Function to initialize the MPR121 sensor
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_fd, MPR121_ECR, 0x8F) < 0) {
        fprintf(stderr, "Error: Failed to reset MPR121 (ECR write).\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure electrode configuration (enable all 12 electrodes)
    if (i2cWriteByteData(i2c_fd, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to configure electrode configuration (ELECTRODE_CONFIG write).\n");
        return -1;
    }

    // Configure baseline filtering
    if (i2cWriteByteData(i2c_fd, MPR121_MHD_R, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure MHD_R (MHD_R write).\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_fd, MPR121_NHD_R, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure NHD_R (NHD_R write).\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_fd, MPR121_NCL_R, 0x0E) < 0) {
        fprintf(stderr, "Error: Failed to configure NCL_R (NCL_R write).\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_fd, MPR121_FDL_R, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure FDL_R (FDL_R write).\n");
        return -1;
    }

    // Configure touch and release thresholds
    for (int i = 0; i < NUM_ELECTRODES; i++) {
        if (i2cWriteByteData(i2c_fd, 0x41 + (i * 2), 0x30) < 0) {
            fprintf(stderr, "Error: Failed to configure touch threshold for electrode %d (0x41 + (i * 2) write).\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_fd, 0x42 + (i * 2), 0x10) < 0) {
            fprintf(stderr, "Error: Failed to configure release threshold for electrode %d (0x42 + (i * 2) write).\n", i);
            return -1;
        }
    }

    // Configure debounce
    if (i2cWriteByteData(i2c_fd, MPR121_CONFIG1, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure debounce (CONFIG1 write).\n");
        return -1;
    }

    // Configure FFI
    if (i2cWriteByteData(i2c_fd, MPR121_CONFIG2, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure FFI (CONFIG2 write).\n");
        return -1;
    }

    // Configure SFI
    if (i2cWriteByteData(i2c_fd, MPR121_CONFIG3, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure SFI (CONFIG3 write).\n");
        return -1;
    }

    // Configure CDT
    if (i2cWriteByteData(i2c_fd, MPR121_CONFIG4, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure CDT (CONFIG4 write).\n");
        return -1;
    }

    // Enable auto configuration
    if (i2cWriteByteData(i2c_fd, MPR121_CONFIG5, 0x01) < 0) {
        fprintf(stderr, "Error: Failed to configure auto configuration (CONFIG5 write).\n");
        return -1;
    }

    // Enable all electrodes
    if (i2cWriteByteData(i2c_fd, MPR121_CONFIG6, 0x0C) < 0) {
        fprintf(stderr, "Error: Failed to configure all electrodes (CONFIG6 write).\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121 sensor
int mpr121_read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_fd, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status (I2C read).\n");
        return -1;
    }

    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to check if a touch event occurred on a specific electrode
bool is_touch_event(uint16_t touch_status, int electrode) {
    return (touch_status & (1 << electrode));
}

// Function to toggle the relay state
void toggle_relay() {
    relay_state = !relay_state;
    gpioWrite(RELAY_GPIO, relay_state);
    printf("Relay toggled to %s\n", relay_state ? "ON" : "OFF");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    gpioWrite(RELAY_GPIO, 0); // Turn off relay
    close(i2c_fd);
    gpioTerminate();
    exit(0);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed.\n");
        return 1;
    }

    // Open I2C device
    char i2c_device[20];
    snprintf(i2c_device, sizeof(i2c_device), "/dev/i2c-1"); // Assuming I2C bus 1
    i2c_fd = open(i2c_device, O_RDWR);
    if (i2c_fd < 0) {
        fprintf(stderr, "Error: Failed to open I2C device: %s\n", strerror(errno));
        gpioTerminate();
        return 1;
    }

    // Set I2C slave address
    if (ioctl(i2c_fd, I2C_SLAVE, MPR121_I2C_ADDR) < 0) {
        fprintf(stderr, "Error: Failed to set I2C slave address: %s\n", strerror(errno));
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);
    gpioWrite(RELAY_GPIO, 0); // Initially turn off the relay

    // Initialize MPR121 sensor
    if (mpr121_init() < 0) {
        fprintf(stderr, "Error: MPR121 initialisation failed.\n");
        close(i2c_fd);
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("MPR121 relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (1) {
        uint16_t touch_status;
        if (mpr121_read_touch_status(&touch_status) == 0) {
            // Check if electrode 0 is touched (rising edge)
            if (is_touch_event(touch_status, 0)) {
                time_t current_time = time(NULL);
                if (current_time - last_touch_time > DEBOUNCE_MS / 1000.0) {
                    toggle_relay();
                    last_touch_time = current_time;
                }
            }

            // Check if electrode 0 is released (falling edge)
            if (!is_touch_event(touch_status, 0)) {
                // Optionally, add a release delay here
            }
        } else {
            fprintf(stderr, "Error: Failed to read touch status. Retrying...\n");
        }

        gpioDelay(10); // Small delay to avoid busy-waiting
    }

    return 0;
}

