#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <syslog.h>
#include <time.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define SERVO_GPIO 17
#define PIR_GPIO 4
#define PORT 5000
#define PWM_FREQUENCY 50
#define PWM_RANGE 2000000 // 2ms
#define PIR_THRESHOLD 1000 // Debounce time in microseconds
#define LOG_FILE "security.log"

// Global variables
int server_fd, new_socket;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_servo_angle(int angle);
int read_pir_sensor();
void handle_client(int client_socket);
void log_event(int priority, const char *format, ...);
void signal_handler(int signal);
void cleanup();

// Function to initialize GPIO
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_event(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(SERVO_GPIO, PI_OUTPUT);
    gpioSetMode(PIR_GPIO, PI_INPUT);
    gpioSetPullUpDown(PIR_GPIO, PI_PUD_DOWN); // Use pull-down resistor

    // Set PWM frequency and range
    gpioSetPWMfrequency(SERVO_GPIO, PWM_FREQUENCY);
    gpioSetPWMrange(SERVO_GPIO, PWM_RANGE);

    return 0;
}

// Function to set servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        log_event(LOG_ERR, "Invalid servo angle: %d", angle);
        return -1;
    }

    // Calculate pulse width (500us - 2500us)
    int pulse_width = 500 + (int)((float)angle / 180.0 * 2000.0);

    gpioPWM(SERVO_GPIO, pulse_width);
    return 0;
}

// Function to read PIR sensor
int read_pir_sensor() {
    int pir_value = gpioRead(PIR_GPIO);
    if (pir_value < 0) {
        log_event(LOG_ERR, "Failed to read PIR sensor");
        return -1;
    }
    return pir_value;
}

// Function to handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    int valread;

    while (program_running) {
        valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
        if (valread > 0) {
            buffer[valread] = '\0';
            log_event(LOG_INFO, "Received command: %s", buffer);

            if (strcmp(buffer, "PIR") == 0) {
                int pir_value = read_pir_sensor();
                if (pir_value >= 0) {
                    char response[10];
                    snprintf(response, sizeof(response), "PIR:%d", pir_value);
                    send(client_socket, response, strlen(response), 0);
                    log_event(LOG_INFO, "Sent PIR response: %s", response);
                } else {
                    log_event(LOG_ERR, "Failed to read PIR sensor in response");
                }
            } else {
                char *token = strtok(buffer, " ");
                if (token != NULL) {
                    char command[100];
                    snprintf(command, sizeof(command), "set_servo_angle(%s)", token);
                    int angle = atoi(token);
                    if (angle >= 0 && angle <= 180) {
                        if (set_servo_angle(angle) == 0) {
                            char response[10];
                            snprintf(response, sizeof(response), "Servo angle set to %d", angle);
                            send(client_socket, response, strlen(response), 0);
                            log_event(LOG_INFO, "Servo angle set to %d", angle);
                        } else {
                            log_event(LOG_ERR, "Failed to set servo angle");
                        }
                    } else {
                        log_event(LOG_ERR, "Invalid servo angle received: %d", angle);
                    }
                } else {
                    log_event(LOG_ERR, "Invalid command received: %s", buffer);
                }
            }
        } else if (valread == 0) {
            log_event(LOG_INFO, "Client disconnected");
            break;
        } else {
            log_event(LOG_ERR, "Receive failed");
            break;
        }
    }
}

// Function to log events
void log_event(int priority, const char *format, ...) {
    va_list args;
    va_start(args, format);

    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s ", timestamp);
    vfprintf(log_file, format, args);
    fprintf(log_file, "\n");
    fflush(log_file);

    syslog(priority, format, args);
    va_end(args);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_event(LOG_INFO, "Signal received, shutting down...");
}

// Cleanup function to release resources
void cleanup() {
    log_event(LOG_INFO, "Cleaning up...");

    // Stop PWM
    gpioPWM(SERVO_GPIO, 0);

    // Close socket
    if (new_socket > 0) {
        close(new_socket);
    }
    if (server_fd > 0) {
        close(server_fd);
    }

    // Close log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate pigpio
    gpioTerminate();

    log_event(LOG_INFO, "Cleanup complete. Exiting.");
}

int main() {
    // Open syslog
    openlog("security_system", LOG_PID | LOG_CONS, LOG_USER);

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        perror("Failed to open log file");
        syslog(LOG_ERR, "Failed to open log file");
        return 1;
    }

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        log_event(LOG_ERR, "GPIO initialization failed, exiting");
        fclose(log_file);
        closelog();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Create socket
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        log_event(LOG_ERR, "Socket creation failed");
        syslog(LOG_ERR, "Socket creation failed");
        cleanup();
        return 1;
    }

    // Bind socket to address and port
    struct sockaddr_in address;
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(PORT);

    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        log_event(LOG_ERR, "Bind failed");
        syslog(LOG_ERR, "Bind failed");
        cleanup();
        return 1;
    }

    // Listen for connections
    if (listen(server_fd, 3) < 0) {
        log_event(LOG_ERR, "Listen failed");
        syslog(LOG_ERR, "Listen failed");
        cleanup();
        return 1;
    }

    log_event(LOG_INFO, "Listening on port %d", PORT);

    // Accept connections
    while (program_running) {
        struct sockaddr_in client_address;
        int client_address_len = sizeof(client_address);

        if ((new_socket = accept(server_fd, (struct sockaddr *)&client_address, (socklen_t *)&client_address_len)) < 0) {
            log_event(LOG_ERR, "Accept failed");
            syslog(LOG_ERR, "Accept failed");
            continue; // Continue listening for other connections
        }

        log_event(LOG_INFO, "Connection accepted from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        // Handle client connection
        handle_client(new_socket);

        // Close client socket
        close(new_socket);
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

