        log_event(LOG_INFO, "Connection accepted from %s:%d", inet_ntoa(client_address.sin_addr), ntohs(client_address.sin_port));

        // Handle client connection
        handle_client(new_socket);

        // Close client socket
        close(new_socket);
    }

    // Cleanup and exit
    cleanup();
    closelog();
    return 0;
}

