#include <string.h>
#include <unistd.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define RELAY_GPIO 23
#define LUX_THRESHOLD 150.0
#define SAMPLE_INTERVAL_SEC 2
#define RETRY_COUNT 3
#define RETRY_DELAY_MS 10

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int init_i2c();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize I2C communication
int init_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char config_cmd[1] = {0x10}; // Continuous high-resolution mode
    int result;

    result = i2cWriteDevice(i2c_handle, config_cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(200); // Wait for measurement (at least 180ms)

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2; // Convert to lux

    return 0;
}

// Control the grow-light relay
int control_relay(int state) {
    int result = gpioWrite(RELAY_GPIO, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO: %d\n", result);
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(float lux) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, %.2f\n", timestamp, lux);
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(RELAY_GPIO, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set relay GPIO as output
    gpioSetMode(RELAY_GPIO, PI_OUTPUT);

    // Initialize I2C
    if (init_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen("grow_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int relay_state = 0; // 0 = off, 1 = on

    printf("Grow light control system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        int retry = 0;
        int read_result = -1;

        while (retry < RETRY_COUNT && read_result != 0) {
            read_result = read_bh1750(&lux);
            if (read_result != 0) {
                fprintf(stderr, "I2C read failed, retry %d/%d\n", retry + 1, RETRY_COUNT);
                gpioDelay(RETRY_DELAY_MS * 1000); // Delay in microseconds
                retry++;
            }
        }

        if (read_result == 0) {
            printf("Lux: %.2f\n", lux);
            log_data(lux);

            if (lux < LUX_THRESHOLD && relay_state == 0) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    printf("Relay activated\n");
                } else {
                    fprintf(stderr, "Failed to activate relay\n");
                }
            } else if (lux >= LUX_THRESHOLD && relay_state == 1) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    printf("Relay deactivated\n");
                } else {
                    fprintf(stderr, "Failed to deactivate relay\n");
                }
            }
        } else {
            fprintf(stderr, "Failed to read lux after multiple retries\n");
        }

        gpioDelay(SAMPLE_INTERVAL_SEC * 1000000); // Delay in microseconds
    }

    cleanup();
    return 0;
}

