#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DOUT 23
#define HX711_SCK 24
#define SOLENOID_PIN 25

// Define default values
#define DEFAULT_SCALE_FACTOR 1.0
#define DEFAULT_THRESHOLD 1000.0
#define DEFAULT_DURATION 200

// Global variables
volatile sig_atomic_t program_running = 1;
double scale_factor = DEFAULT_SCALE_FACTOR;
double threshold = DEFAULT_THRESHOLD;
int duration = DEFAULT_DURATION;

// Function prototypes
int initialize_gpio();
long read_hx711();
double average_readings(long *readings, int num_readings);
double apply_scale_factor(double raw_weight, double scale_factor);
void control_solenoid(int state);
void signal_handler(int signal);
void log_message(int priority, const char *message);

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        log_message(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(HX711_DOUT, PI_INPUT);
    gpioSetMode(HX711_SCK, PI_OUTPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Ensure solenoid is initially LOW
    control_solenoid(0);

    return 0;
}

// Function to read data from HX711
long read_hx711() {
    long count = 0;
    int i;

    gpioWrite(HX711_SCK, 0); // Ensure SCK is LOW initially

    // Wait for DOUT to go LOW
    int timeout = 1000; // Timeout after 1 second
    while (gpioRead(HX711_DOUT) == 1 && timeout > 0) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout--;
    }

    if (timeout == 0) {
        log_message(LOG_ERR, "HX711 timeout waiting for DOUT to go LOW");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK, 1);
        gpioDelay(1); // Small delay
        count = count << 1;
        if (gpioRead(HX711_DOUT)) {
            count++;
        }
        gpioWrite(HX711_SCK, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse for gain selection (Channel A, gain 128)
    gpioWrite(HX711_SCK, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (count & 0x800000) {
        count |= ~0xffffff; // Sign extend
    }

    return count;
}

// Function to average readings
double average_readings(long *readings, int num_readings) {
    double sum = 0.0;
    for (int i = 0; i < num_readings; i++) {
        sum += readings[i];
    }
    return sum / num_readings;
}

// Function to apply scale factor
double apply_scale_factor(double raw_weight, double scale_factor) {
    return raw_weight * scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    log_message(LOG_INFO, "Signal received, shutting down...");
}

// Function to log messages with timestamps
void log_message(int priority, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    syslog(priority, "%s: %s", timestamp, message);
    printf("%s: %s\n", timestamp, message);
}

int main(int argc, char *argv[]) {
    // Parse command-line arguments
    int opt;
    while ((opt = getopt(argc, argv, "s:t:d:")) != -1) {
        switch (opt) {
            case 's':
                scale_factor = atof(optarg);
                break;
            case 't':
                threshold = atof(optarg);
                break;
            case 'd':
                duration = atoi(optarg);
                break;
            default:
                fprintf(stderr, "Usage: %s [-s scale_factor] [-t threshold] [-d duration]\n", argv[0]);
                exit(EXIT_FAILURE);
        }
    }

    // Initialize syslog
    openlog("weight_monitor", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        closelog();
        return EXIT_FAILURE;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_message(LOG_INFO, "Weight monitoring started");

    // Tare the HX711
    long tare_readings[10];
    for (int i = 0; i < 10; i++) {
        tare_readings[i] = read_hx711();
        if (tare_readings[i] == -1) {
            log_message(LOG_ERR, "Error reading tare reading, retrying...");
            gpioDelay(100); // Wait before retrying
            continue;
        }
        gpioDelay(10); // Small delay between readings
    }
    double tare_value = average_readings(tare_readings, 10);
    log_message(LOG_INFO, "Tare value: %.2f", tare_value);

    // Main loop
    while (program_running) {
        long readings[5];
        for (int i = 0; i < 5; i++) {
            readings[i] = read_hx711();
            if (readings[i] == -1) {
                log_message(LOG_ERR, "Error reading reading, retrying...");
                gpioDelay(100); // Wait before retrying
                continue;
            }
            gpioDelay(10); // Small delay between readings
        }

        double raw_weight = average_readings(readings, 5);
        double scaled_weight = apply_scale_factor(raw_weight - tare_value, scale_factor);

        log_message(LOG_INFO, "Raw weight: %.2f, Scaled weight: %.2f", raw_weight, scaled_weight);

        if (scaled_weight > threshold) {
            log_message(LOG_INFO, "Weight exceeds threshold, activating solenoid lock");
            control_solenoid(1); // Activate solenoid
            gpioDelay(duration); // Keep solenoid active for specified duration
            control_solenoid(0); // Deactivate solenoid
            log_message(LOG_INFO, "Solenoid lock deactivated");
        }

        gpioDelay(500); // Poll every 500ms
    }

    // Cleanup
    control_solenoid(0); // Ensure solenoid is LOW on exit
    gpioTerminate(); // Terminate pigpio
    closelog(); // Close syslog

    log_message(LOG_INFO, "Weight monitoring stopped");

    return EXIT_SUCCESS;
}

