#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for servos
#define SERVO1_PIN 7
#define SERVO2_PIN 8
#define SERVO3_PIN 9
#define SERVO4_PIN 10
#define SERVO5_PIN 11

// Define pulse width limits (microseconds)
#define MIN_PULSE_WIDTH 500
#define MAX_PULSE_WIDTH 2500

// Define target pulse widths (microseconds)
#define TARGET_PULSE_WIDTH1 1000
#define TARGET_PULSE_WIDTH2 1500
#define TARGET_PULSE_WIDTH3 2000
#define TARGET_PULSE_WIDTH4 500
#define TARGET_PULSE_WIDTH5 2500

// Define PWM frequency (Hz)
#define PWM_FREQUENCY 50

// Global variable to indicate program termination
volatile sig_atomic_t program_running = 1;

// Signal handler for Ctrl+C
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to set the pulse width of a servo
int set_servo_pulse_width(int gpio_pin, int pulse_width) {
    if (pulse_width < MIN_PULSE_WIDTH || pulse_width > MAX_PULSE_WIDTH) {
        fprintf(stderr, "Error: Pulse width out of range (%d us). Must be between %d and %d us.\n", pulse_width, MIN_PULSE_WIDTH, MAX_PULSE_WIDTH);
        return -1; // Indicate error
    }

    // Calculate the duty cycle (500us = 0%, 2500us = 100%)
    int duty_cycle = (int)(((float)(pulse_width - MIN_PULSE_WIDTH) / (float)(MAX_PULSE_WIDTH - MIN_PULSE_WIDTH)) * 1000.0);

    // Set the PWM duty cycle
    gpioPWM(gpio_pin, duty_cycle);

    return 0; // Indicate success
}

int main() {
    // Initialize the pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1; // Exit with an error code
    }

    // Set GPIO pins as outputs
    gpioSetMode(SERVO1_PIN, PI_OUTPUT);
    gpioSetMode(SERVO2_PIN, PI_OUTPUT);
    gpioSetMode(SERVO3_PIN, PI_OUTPUT);
    gpioSetMode(SERVO4_PIN, PI_OUTPUT);
    gpioSetMode(SERVO5_PIN, PI_OUTPUT);

    // Set PWM frequency
    gpioSetPWMfrequency(SERVO1_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO2_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO3_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO4_PIN, PWM_FREQUENCY);
    gpioSetPWMfrequency(SERVO5_PIN, PWM_FREQUENCY);

    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Main loop
    while (program_running) {
        // Move servos to target positions
        if (set_servo_pulse_width(SERVO1_PIN, TARGET_PULSE_WIDTH1) != 0) {
            fprintf(stderr, "Error setting servo 1 pulse width.\n");
        }
        if (set_servo_pulse_width(SERVO2_PIN, TARGET_PULSE_WIDTH2) != 0) {
            fprintf(stderr, "Error setting servo 2 pulse width.\n");
        }
        if (set_servo_pulse_width(SERVO3_PIN, TARGET_PULSE_WIDTH3) != 0) {
            fprintf(stderr, "Error setting servo 3 pulse width.\n");
        }
        if (set_servo_pulse_width(SERVO4_PIN, TARGET_PULSE_WIDTH4) != 0) {
            fprintf(stderr, "Error setting servo 4 pulse width.\n");
        }
        if (set_servo_pulse_width(SERVO5_PIN, TARGET_PULSE_WIDTH5) != 0) {
            fprintf(stderr, "Error setting servo 5 pulse width.\n");
        }

        // Wait for 3 seconds
        sleep(3);
    }

    // Stop PWM and release GPIO resources
    gpioPWM(SERVO1_PIN, 0);
    gpioPWM(SERVO2_PIN, 0);
    gpioPWM(SERVO3_PIN, 0);
    gpioPWM(SERVO4_PIN, 0);
    gpioPWM(SERVO5_PIN, 0);
    gpioTerminate();

    return 0; // Exit successfully
}

