#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <signal.h>
#include <unistd.h>
#include <time.h>
#include <math.h>
#include <pigpio.h>

// Motor A
#define MOTOR_A_PWM 17
#define MOTOR_A_DIR 18

// Motor B
#define MOTOR_B_PWM 22
#define MOTOR_B_DIR 23

// Encoder A
#define ENCODER_A_PHASE_A 4
#define ENCODER_A_PHASE_B 5

// Encoder B
#define ENCODER_B_PHASE_A 6
#define ENCODER_B_PHASE_B 12

// PID Gains
#define KP 1.0
#define KI 0.1
#define KD 0.01

// Target RPM
#define TARGET_RPM 50.0

// PWM Frequency
#define PWM_FREQUENCY 10000 // 10 kHz

// Stall Detection Timeout (seconds)
#define STALL_TIMEOUT 2.0

// Global Variables
volatile int encoder_a_count = 0;
volatile int encoder_b_count = 0;
volatile bool encoder_a_phase_a_prev = false;
volatile bool encoder_a_phase_b_prev = false;
volatile bool encoder_b_phase_a_prev = false;
volatile bool encoder_b_phase_b_prev = false;
volatile bool motor_a_forward = false;
volatile bool motor_b_forward = false;
volatile bool motor_a_running = false;
volatile bool motor_b_running = false;
volatile bool stall_detected = false;

// PID Variables
double integral = 0.0;
double previous_error = 0.0;

// Function Prototypes
void encoder_a_isr(int gpio, int level, uint32_t tick);
void encoder_b_isr(int gpio, int level, uint32_t tick);
void motor_a_forward(int duty_cycle);
void motor_a_backward(int duty_cycle);
void motor_a_stop();
void motor_b_forward(int duty_cycle);
void motor_b_backward(int duty_cycle);
void motor_b_stop();
double calculate_rpm(int encoder_count);
double calculate_pid(double current_rpm, double target_rpm);
void set_motor_pwm(int motor_pwm, int duty_cycle);
void set_motor_direction(int motor_dir, bool forward);
void stall_detection_check();
void signal_handler(int signal);

// Encoder A ISR
void encoder_a_isr(int gpio, int level, uint32_t tick) {
    bool phase_a = gpioRead(ENCODER_A_PHASE_A);
    bool phase_b = gpioRead(ENCODER_A_PHASE_B);

    if (phase_a && !phase_b) {
        if (encoder_a_phase_a_prev) {
            encoder_a_count++;
        } else {
            encoder_a_count--;
        }
    } else if (!phase_a && phase_b) {
        if (encoder_a_phase_b_prev) {
            encoder_a_count--;
        } else {
            encoder_a_count++;
        }
    }

    encoder_a_phase_a_prev = phase_a;
    encoder_a_phase_b_prev = phase_b;
}

// Encoder B ISR
void encoder_b_isr(int gpio, int level, uint32_t tick) {
    bool phase_a = gpioRead(ENCODER_B_PHASE_A);
    bool phase_b = gpioRead(ENCODER_B_PHASE_B);

    if (phase_a && !phase_b) {
        if (encoder_b_phase_a_prev) {
            encoder_b_count++;
        } else {
            encoder_b_count--;
        }
    } else if (!phase_a && phase_b) {
        if (encoder_b_phase_b_prev) {
            encoder_b_count--;
        } else {
            encoder_b_count++;
        }
    }

    encoder_b_phase_a_prev = phase_a;
    encoder_b_phase_b_prev = phase_b;
}

// Motor A Forward
void motor_a_forward(int duty_cycle) {
    set_motor_direction(MOTOR_A_DIR, true);
    set_motor_pwm(MOTOR_A_PWM, duty_cycle);
    motor_a_running = true;
}

// Motor A Backward
void motor_a_backward(int duty_cycle) {
    set_motor_direction(MOTOR_A_DIR, false);
    set_motor_pwm(MOTOR_A_PWM, duty_cycle);
    motor_a_running = true;
}

// Motor A Stop
void motor_a_stop() {
    set_motor_pwm(MOTOR_A_PWM, 0);
    motor_a_running = false;
}

// Motor B Forward
void motor_b_forward(int duty_cycle) {
    set_motor_direction(MOTOR_B_DIR, true);
    set_motor_pwm(MOTOR_B_PWM, duty_cycle);
    motor_b_running = true;
}

// Motor B Backward
void motor_b_backward(int duty_cycle) {
    set_motor_direction(MOTOR_B_DIR, false);
    set_motor_pwm(MOTOR_B_PWM, duty_cycle);
    motor_b_running = true;
}

// Motor B Stop
void motor_b_stop() {
    set_motor_pwm(MOTOR_B_PWM, 0);
