#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define BH1750_ADDR 0x23
#define GPIO_RELAY 17
#define LUX_THRESHOLD_LOW 50.0
#define LUX_THRESHOLD_HIGH 200.0
#define HYSTERESIS_TIME 180 // milliseconds
#define LOG_FILE "chicken_coop_log.txt"

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_i2c();
int read_bh1750(float *lux);
int control_relay(int state);
int log_data(float lux, int relay_state);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(I2C_BUS, BH1750_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C: %d\n", i2c_handle);
        return -1;
    }
    return 0;
}

// Read lux value from BH1750 sensor
int read_bh1750(float *lux) {
    char config_cmd[1] = {0x10}; // Continuous high-resolution mode
    int result;

    result = i2cWriteDevice(i2c_handle, config_cmd, 1);
    if (result != 0) {
        fprintf(stderr, "Error writing to I2C: %d\n", result);
        return -1;
    }

    gpioDelay(200); // Wait for measurement (at least 180ms)

    char data[2];
    result = i2cReadDevice(i2c_handle, data, 2);
    if (result != 2) {
        fprintf(stderr, "Error reading from I2C: %d\n", result);
        return -1;
    }

    uint16_t raw_value = (data[0] << 8) | data[1];
    *lux = (float)raw_value / 1.2; // Convert to lux
    return 0;
}

// Control the relay (ON/OFF)
int control_relay(int state) {
    int result = gpioWrite(GPIO_RELAY, state);
    if (result != 0) {
        fprintf(stderr, "Error writing to GPIO: %d\n", result);
        return -1;
    }
    return 0;
}

// Log data to file
int log_data(float lux, int relay_state) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[20];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", t);

    fprintf(log_file, "%s: Lux = %.2f, Relay = %s\n", timestamp, lux, relay_state ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately
    return 0;
}

// Cleanup resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");
    if (i2c_handle >= 0) {
        i2cClose(i2c_handle);
    }
    if (log_file != NULL) {
        fclose(log_file);
    }
    gpioWrite(GPIO_RELAY, 0); // Ensure relay is off
    gpioTerminate();
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO_RELAY as output
    gpioSetMode(GPIO_RELAY, PI_OUTPUT);

    // Initialize I2C
    if (initialize_i2c() != 0) {
        cleanup();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        cleanup();
        return 1;
    }

    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    float lux;
    int relay_state = 0; // 0 = OFF, 1 = ON
    int last_relay_state = 0; // Store the last known relay state
    int hysteresis_active = 0; // Flag to indicate hysteresis is active
    time_t hysteresis_start_time = 0; // Time when hysteresis started

    printf("Chicken coop monitoring started. Press Ctrl+C to exit.\n");

    while (!terminate) {
        // Read lux value
        if (read_bh1750(&lux) == 0) {
            printf("Lux: %.2f\n", lux);

            // Control relay based on lux value
            if (lux < LUX_THRESHOLD_LOW && !relay_state && !hysteresis_active) {
                if (control_relay(1) == 0) {
                    relay_state = 1;
                    log_data(lux, relay_state);
                    printf("Relay turned ON\n");
                } else {
                    fprintf(stderr, "Failed to turn relay ON\n");
                }
                hysteresis_active = 1;
                hysteresis_start_time = time(NULL);
            } else if (lux > LUX_THRESHOLD_HIGH && relay_state && !hysteresis_active) {
                if (control_relay(0) == 0) {
                    relay_state = 0;
                    log_data(lux, relay_state);
                    printf("Relay turned OFF\n");
                } else {
                    fprintf(stderr, "Failed to turn relay OFF\n");
                }
                hysteresis_active = 1;
                hysteresis_start_time = time(NULL);
            }

            // Check hysteresis condition
            if (hysteresis_active) {
                time_t current_time = time(NULL);
                if (difftime(current_time, hysteresis_start_time) * 1000 >= HYSTERESIS_TIME) {
                    if (relay_state) {
                        if (control_relay(0) == 0) {
                            relay_state = 0;
                            log_data(lux, relay_state);
                            printf("Relay turned OFF due to hysteresis\n");
                        } else {
                            fprintf(stderr, "Failed to turn relay OFF due to hysteresis\n");
                        }
                    }
                    hysteresis_active = 0;
                }
            }

            last_relay_state = relay_state; // Update last known relay state
        } else {
            fprintf(stderr, "Failed to read lux value\n");
        }

        gpioDelay(5000); // Wait 5 seconds
    }

    // Cleanup and exit
    cleanup();
    return 0;
}

