#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define TOUCH_SENSOR_PIN 4
#define RELAY_PIN 17

// Debounce delay in milliseconds
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static int relay_state = 0; // 0 = OFF, 1 = ON

// Function prototypes
int read_touch_sensor(int gpio_pin);
int toggle_relay(int gpio_pin, int current_state);
void log_relay_state(int state);
void signal_handler(int signal);

// Function to read the touch sensor
int read_touch_sensor(int gpio_pin) {
    int touch_detected = gpioRead(gpio_pin);
    if (touch_detected < 0) {
        fprintf(stderr, "Error reading touch sensor on GPIO %d: %d\n", gpio_pin, touch_detected);
        return -1; // Indicate error
    }
    return touch_detected;
}

// Function to toggle the relay
int toggle_relay(int gpio_pin, int current_state) {
    int new_state = !current_state;
    if (gpioWrite(gpio_pin, new_state) != 0) {
        fprintf(stderr, "Error writing to relay on GPIO %d: %d\n", gpio_pin, new_state);
        return -1; // Indicate error
    }
    return new_state;
}

// Function to log the relay state
void log_relay_state(int state) {
    time_t now = time(NULL);
    struct tm *tstruct = localtime(&now);
    char buf[80];
    strftime(buf, sizeof(buf), "%Y-%m-%dT%H:%M:%SZ", tstruct);
    printf("[%s] Relay state: %s\n", buf, state ? "ON" : "OFF");
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    printf("Caught signal %d, exiting gracefully...\n", signal);
    gpioWrite(RELAY_PIN, 0); // Turn off the relay
    gpioTerminate(); // Release pigpio resources
    exit(0);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(TOUCH_SENSOR_PIN, PI_INPUT);
    gpioSetMode(RELAY_PIN, PI_OUTPUT);

    // Initialize relay to OFF state
    gpioWrite(RELAY_PIN, 0);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    printf("Touch-toggled relay control started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int touch_detected = read_touch_sensor(TOUCH_SENSOR_PIN);
        if (touch_detected < 0) {
            fprintf(stderr, "Error reading touch sensor, exiting...\n");
            break;
        }

        if (touch_detected == 1) {
            // Debounce delay
            gpioDelay(DEBOUNCE_DELAY * 1000); // pigpioDelay takes microseconds

            // Re-read the sensor after the debounce
            int re_touch_detected = read_touch_sensor(TOUCH_SENSOR_PIN);
            if (re_touch_detected < 0) {
                fprintf(stderr, "Error reading touch sensor after debounce, exiting...\n");
                break;
            }

            if (re_touch_detected == 1) {
                // Toggle the relay
                relay_state = toggle_relay(RELAY_PIN, relay_state);

                // Log the relay state
                log_relay_state(relay_state);
            }
        }

        gpioDelay(10 * 1000); // Sleep for 10 milliseconds
    }

    // Cleanup (should not reach here if signal handler works correctly)
    gpioWrite(RELAY_PIN, 0);
    gpioTerminate();

    return 0;
}

