#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define FLOW_SENSOR_PIN 17
#define SOLENOID_PIN 27

// Define constants
#define PULSES_PER_LITER 450.0
#define SOLENOID_OPEN_TIME_MS 500
#define SOLENOID_CLOSE_TIME_MS 500
#define SOLENOID_HYSTERESIS_MS 250
#define DEBOUNCE_TIME_MS 100
#define LOG_FILE_NAME "water_flow.log"

// Global variables
static volatile int pulse_count = 0;
static volatile int solenoid_state = 1; // 1 = open, 0 = closed
static volatile int flow_exceeded = 0;
static volatile int flow_below_hysteresis = 1;
static volatile int program_running = 1;
static FILE *log_file = NULL;
static pthread_mutex_t pulse_mutex = PTHREAD_MUTEX_INITIALIZER;

// Function prototypes
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data);
double calculate_lpm(int pulse_count);
void log_data(double lpm, int solenoid_state);
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();

// Callback function for flow sensor pulses
void pulse_callback(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        pthread_mutex_lock(&pulse_mutex);
        pulse_count++;
        pthread_mutex_unlock(&pulse_mutex);
    }
}

// Function to calculate LPM
double calculate_lpm(int pulse_count) {
    return (double)pulse_count / PULSES_PER_LITER * 60.0;
}

// Function to log data to file
void log_data(double lpm, int solenoid_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file != NULL) {
        fprintf(log_file, "%s, LPM: %.2f, Solenoid: %s\n", timestamp, lpm, solenoid_state ? "OPEN" : "CLOSED");
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("Caught signal %d, exiting gracefully.\n", signal);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(FLOW_SENSOR_PIN, PI_INPUT);
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 1); // Initialize solenoid to open state

    // Set up interrupt on flow sensor pin
    if (gpioSetISRFuncEx(FLOW_SENSOR_PIN, RISING_EDGE, 0, pulse_callback, NULL) != 0) {
        fprintf(stderr, "Failed to set ISR function\n");
        gpioTerminate();
        return 1;
    }

    return 0;
}

// Function to cleanup GPIO pins
void cleanup_gpio() {
    gpioWrite(SOLENOID_PIN, 1); // Ensure solenoid is closed on exit
    gpioTerminate();
    if (log_file != NULL) {
        fclose(log_file);
    }
    pthread_mutex_destroy(&pulse_mutex);
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE_NAME, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    printf("Water flow monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        int current_pulse_count;
        double lpm;

        // Debounce the flow sensor
        gpioDelay(DEBOUNCE_TIME_MS * 1000); // Convert ms to microseconds

        pthread_mutex_lock(&pulse_mutex);
        current_pulse_count = pulse_count;
        pulse_count = 0; // Reset pulse count for the next second
        pthread_mutex_unlock(&pulse_mutex);

        lpm = calculate_lpm(current_pulse_count);

        // Check for flow exceedance
        if (lpm > 5.0 && !flow_exceeded) {
            printf("Flow exceeded threshold! LPM: %.2f\n", lpm);
            log_data(lpm, solenoid_state);
            flow_exceeded = 1;
            gpioWrite(SOLENOID_PIN, 0); // Close solenoid
            gpioDelay(SOLENOID_CLOSE_TIME_MS * 1000); // Wait for close time
            gpioWrite(SOLENOID_PIN, 1); // Reopen solenoid
            flow_below_hysteresis = 0; // Reset hysteresis
        }

        // Check for flow below hysteresis
        if (lpm < 4.5 && flow_below_hysteresis) {
            printf("Flow below hysteresis! LPM: %.2f\n", lpm);
            log_data(lpm, solenoid_state);
            flow_below_hysteresis = 0; // Reset hysteresis
        }

        // Log data every second
        if (lpm > 0.0) {
            log_data(lpm, solenoid_state);
        }

        gpioDelay(1000 * 1000); // Wait for 1 second
    }

    // Cleanup and exit
    cleanup_gpio();
    printf("Water flow monitoring stopped.\n");
    return 0;
}

