#define HX711_SCK_PIN 24

// Function to read configuration from file
int read_config() {
    FILE *fp = fopen(CONFIG_FILE, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        return -1;
    }

    char line[256];
    while (fgets(line, sizeof(line), fp)) {
        // Remove newline character
        line[strcspn(line, "\n")] = 0;

        // Parse key-value pairs
        char *key = strtok(line, "=");
        char *value = strtok(NULL, "=");

        if (key != NULL && value != NULL) {
            if (strcmp(key, "target_weight") == 0) {
                target_weight = atof(value);
            } else if (strcmp(key, "calibration_factor") == 0) {
                calibration_factor = atof(value);
            } else if (strcmp(key, "api_endpoint") == 0) {
                strncpy(api_endpoint, value, sizeof(api_endpoint) - 1);
                api_endpoint[sizeof(api_endpoint) - 1] = '\0'; // Ensure null termination
            } else if (strcmp(key, "api_timeout") == 0) {
                api_timeout = atoi(value);
            } else if (strcmp(key, "servo_pin") == 0) {
                servo_pin = atoi(value);
            } else if (strcmp(key, "servo_frequency") == 0) {
                servo_frequency = atoi(value);
            } else if (strcmp(key, "servo_min_pulsewidth") == 0) {
                servo_min_pulsewidth = atoi(value);
            } else if (strcmp(key, "servo_max_pulsewidth") == 0) {
                servo_max_pulsewidth = atoi(value);
            }
        }
    }

    fclose(fp);
    return 0;
}

// Function to setup GPIO pins
int setup_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_SCK_PIN, PI_OUTPUT);
    gpioSetMode(servo_pin, PI_OUTPUT);

    return 0;
}

// Function to setup socket
int setup_socket() {
    struct sockaddr_in address;
    int opt = 1;

    // Creating socket file descriptor
    if ((server_fd = socket(AF_INET, SOCK_STREAM, 0)) == 0) {
        perror("socket failed");
        return -1;
    }

    // Forcefully attaching socket to the port 12345
    if (setsockopt(server_fd, SOL_SOCKET, SO_REUSEADDR | SO_REUSEPORT, &opt, sizeof(opt))) {
        perror("setsockopt");
        return -1;
    }
    address.sin_family = AF_INET;
    address.sin_addr.s_addr = INADDR_ANY;
    address.sin_port = htons(12345);

    // Forcefully attaching socket to the port 12345
    if (bind(server_fd, (struct sockaddr *)&address, sizeof(address)) < 0) {
        perror("bind failed");
        return -1;
    }
    if (listen(server_fd, 3) < 0) {
        perror("listen");
        return -1;
    }
    return 0;
}

// Function to handle client connection
void handle_client(int client_socket) {
    char buffer[1024] = {0};
    ssize_t valread;

    valread = recv(client_socket, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        perror("recv failed");
        return;
    }

    printf("Received: %s\n", buffer);

    // Parse JSON request
    json_error_t error;
    json_t *root = json_loads(buffer, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        send_response(client_socket, "Error parsing JSON");
        return;
    }

    json_t *target_weight_json = json_object_get(root, "target_weight");
    if (!json_is_real(target_weight_json)) {
        fprintf(stderr, "Error: target_weight is not a real number\n");
        send_response(client_socket, "Error: target_weight is not a real number");
        json_decref(root);
        return;
    }

    target_weight = json_real_value(target_weight_json);

    // Dispense the ingredient
    int dispense_result = dispense_ingredient(target_weight);

    // Send response
    char response_buffer[256];
    snprintf(response_buffer, sizeof(response_buffer), "{\"target_weight\": %.2f, \"actual_weight\": %.2f, \"error_message\": \"%s\"}",
             target_weight, calibration_factor * read_hx711(), dispense_result == 0 ? "" : "Dispense failed");
    send_response(client_socket, response_buffer);

    // Log the event
    if (dispense_result != 0) {
        log_event("ERROR", target_weight, calibration_factor * read_hx711(), dispense_result == 1 ? "HX711 timeout" : "API call failed");
    } else {
        log_event("SUCCESS", target_weight, calibration_factor * read_hx711(), "");
    }

    json_decref(root);
    close(client_socket);
}

// Function to read raw data from HX711
double read_hx711() {
    long count = 0;
    int timeout = 0;

    gpioWrite(HX711_SCK_PIN, 0);

    // Wait for DATA pin to go low
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < 1000) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "HX711 timeout waiting for DATA pin to go low\n");
        return -1.0; // Indicate timeout error
    }

    // Read 24 bits of data
    for (int i = 0; i < 24; i++) {
        gpioWrite(HX711_SCK_PIN, 1);
        gpioDelay(1); // Small delay
        count = count << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            count++;
        }
        gpioWrite(HX711_SCK_PIN, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse for gain selection (channel A, gain 128)
    gpioWrite(HX711_SCK_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_SCK_PIN, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (count & 0x800000) {
        count |= ~0xffffff;
    }

    return (double)count;
}

// Function to calibrate weight
double calibrate_weight(double raw_weight) {
    return raw_weight / calibration_factor;
}

// Function to dispense ingredient using the API call
int dispense_ingredient(double target_weight) {
    char payload[256];
    snprintf(payload, sizeof(payload), "{\"target_weight\": %.2f}", target_weight);

    // Construct the HTTP request
    char request[512];
    snprintf(request, sizeof(request), "POST %s HTTP/1.1\r\nHost: %s\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s",
             api_endpoint, api_endpoint, strlen(payload), payload);

    // Send the HTTP request
    int sock = 0, valread;
    struct sockaddr_in serv_addr;
    char buffer[1024] = {0};

    if ((sock = socket(AF_INET, SOCK_STREAM, 0)) < 0) {
        perror("socket failed");
        return -1;
    }

    serv_addr.sin_family = AF_INET;
    serv_addr.sin_port = htons(8080);

    // Convert IPv4 and IPv6 addresses from text to binary form
    if (inet_pton(AF_INET, api_endpoint, &serv_addr.sin_addr) <= 0) {
        perror("inet_pton failed");
        close(sock);
        return -1;
    }

    if (connect(sock, (struct sockaddr *)&serv_addr, sizeof(serv_addr)) < 0) {
        perror("connect failed");
        close(sock);
        return -1;
    }

    send(sock, request, strlen(request), 0);

    // Receive the HTTP response
    valread = recv(sock, buffer, sizeof(buffer) - 1, 0);
    if (valread < 0) {
        perror("recv failed");
        close(sock);
        return -1;
    }

    buffer[valread] = '\0'; // Null-terminate the received data

    // Parse the HTTP response (simplified for demonstration)
    char *status_line = strstr(buffer, "HTTP/1.1");
    if (status_line == NULL) {
        fprintf(stderr, "Error: Invalid HTTP response\n");
        close(sock);
        return -1;
    }

    char *response_code = strstr(status_line, " ");
    if (response_code == NULL) {
        fprintf(stderr, "Error: Invalid HTTP response\n");
        close(sock);
        return -1;
    }

    int response_code_int = atoi(response_code);
    if (response_code_int != 200) {
        fprintf(stderr, "Error: HTTP request failed with status code: %d\n", response_code_int);
        close(sock);
        return -1;
    }

    // Parse the JSON response
    json_error_t error;
    json_t *root = json_loads(buffer, 0, &error);
    if (!root) {
        fprintf(stderr, "Error parsing JSON: %s\n", error.text);
        close(sock);
        return -1;
    }

    json_t *success_json = json_object_get(root, "success");
    if (!json_is_boolean(success_json)) {
        fprintf(stderr, "Error: success is not a boolean\n");
        json_decref(root);
        close(sock);
        return -1;
    }

    int success = json_boolean_value(success_json);
    json_decref(root);

    close(sock);
    return success ? 0 : -1;
}

// Function to send a response to the client
int send_response(int client_socket, const char *message) {
    char response[512];
    snprintf(response, sizeof(response), "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: %zu\r\n\r\n%s",
             strlen(message), message);
    send(client_socket, response, strlen(response), 0);
    return 0;
}

// Function to log events to a file
int log_event(const char *event_type, double target_weight, double actual_weight, const char *error_message) {
    FILE *fp = fopen("dispensing_log.json", "a");
    if (fp == NULL) {
        perror("Error opening dispensing_log.json");
        return -1;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    json_t *root = json_object();
    json_object_set_new(root, "timestamp", json_string(timestamp));
    json_object_set_new(root, "event_type", json_string(event_type));
    json_object_set_new(root, "target_weight", json_real(target_weight));
    json_object_set_new(root, "actual_weight", json_real(actual_weight));
    json_object_set_new(root, "error_message", json_string(error_message));

    char *json_string = json_dumps(root, JSON_REAL_PRECISION(3));
    if (!json_string) {
        fprintf(stderr, "Error creating JSON string\n");
        json_decref(root);
        fclose(fp);
        return -1;
    }

    fprintf(fp, "%s\n", json_string);
    free(json_string);
    json_decref(root);

    fclose(fp);
    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);

    // Stop the servo motor
    gpioServo(servo_pin, 0);

    // Close the socket
    close(new_socket);
    close(server_fd);

    // Terminate pigpio
    gpioTerminate();

    exit(0);
}

int main() {
    // Read configuration from file
    if (read_config() != 0) {
        fprintf(stderr, "Failed to read configuration, using default values\n");
    }

    // Setup GPIO
    if (setup_gpio() != 0) {
        return 1;
    }

    // Setup socket
    if (setup_socket() != 0) {
        gpioTerminate();
        return 1;
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    printf("Server listening on 127.0.0.1:12345\n");

    // Main loop
    while (1) {
        // Accept incoming connection
        if ((new_socket = accept(server_fd, (struct sockaddr *)&address, (socklen_t *)&addrlen)) < 0) {
            perror("accept");
            continue; // Continue listening for other connections
        }

        printf("Connection accepted\n");

        // Handle the client connection
        handle_client(new_socket);
    }

    return 0;
}

