#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SENSOR_PIN 17
#define DEBOUNCE_WINDOW_MS 2

// Define RPM calculation parameters
#define PULSES_PER_REVOLUTION 1 // Assuming one pulse per revolution
#define TIME_PER_REVOLUTION_US 1000000 // 1 second

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static struct timespec last_pulse_time;
static struct timespec current_time;
static double rpm = 0.0;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
void cleanup_gpio();
void log_rpm(double rpm);
void print_rpm(double rpm);
void sensor_callback(int gpio, int level, uint32_t tick);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    fprintf(stderr, "\nCaught signal %d, exiting gracefully...\n", signal);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    // Initialize last pulse time
    clock_gettime(CLOCK_MONOTONIC, &last_pulse_time);

    return 0;
}

// Cleanup GPIO pins
void cleanup_gpio() {
    gpioTerminate();
}

// Log RPM to file
void log_rpm(double rpm) {
    if (log_file != NULL) {
        time_t now = time(NULL);
        struct tm *t = localtime(&now);
        char timestamp[32];
        strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

        fprintf(log_file, "%s,%.2f\n", timestamp, rpm);
        fflush(log_file); // Ensure data is written to disk immediately
    } else {
        fprintf(stderr, "Error: Log file is not open.\n");
    }
}

// Print RPM to console
void print_rpm(double rpm) {
    printf("RPM: %.2f\n", rpm);
}

// Callback function for sensor events
void sensor_callback(int gpio, int level, uint32_t tick) {
    struct timespec current_time;
    clock_gettime(CLOCK_MONOTONIC, &current_time);

    // Debounce the sensor
    if (current_time.tv_nsec - last_pulse_time.tv_nsec > DEBOUNCE_WINDOW_MS * 1000000) {
        // Calculate time difference between pulses
        double time_diff_us = (current_time.tv_sec - last_pulse_time.tv_sec) * 1000000.0 + (current_time.tv_nsec - last_pulse_time.tv_nsec) / 1000.0;

        // Calculate RPM
        rpm = (60.0 * PULSES_PER_REVOLUTION) / (time_diff_us / 1000.0);

        // Update last pulse time
        last_pulse_time = current_time;

        // Log RPM
        log_rpm(rpm);

        // Print RPM
        print_rpm(rpm);
    }
}

int main() {
    // Register signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Open log file
    log_file = fopen("motor_rpm.log", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file!\n");
        cleanup_gpio();
        return 1;
    }

    // Set up callback function for rising edge detection
    gpioSetAlertFuncEx(SENSOR_PIN, sensor_callback, NULL);

    fprintf(stderr, "RPM monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        sleep(5);
    }

    // Cleanup
    cleanup_gpio();
    if (log_file != NULL) {
        fclose(log_file);
    }

    fprintf(stderr, "RPM monitoring stopped.\n");

    return 0;
}

