#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define VALVE_ENABLE_PIN 23
#define VALVE_DIRECTION_PIN 24
#define VALVE_PWM_PIN 18
#define FLOW_SENSOR_PIN 24

// Define constants
#define PWM_FREQUENCY 1000 // Hz
#define PWM_RANGE 255
#define PULSES_PER_LITER 450.0 // Example value, calibrate this
#define TARGET_FLOW_RATE_LPM 10.0 // Default target flow rate
#define LOG_FILE "flow_log.csv"
#define SAMPLE_INTERVAL_MS 100

// Global variables
static volatile int pulse_count = 0;
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data);
double calculate_flow_rate(int pulse_count, double pulses_per_liter);
int set_valve_position(int duty_cycle);
int log_data(double flow_rate, int valve_position);
void signal_handler(int signal);
int parse_arguments(int argc, char *argv[], double *target_flow_rate);

// Interrupt service routine for flow sensor
void pulse_counter_isr(int gpio, int level, uint32_t tick, void *user_data) {
    if (level == 1) { // Rising edge
        pulse_count++;
    }
}

// Function to calculate flow rate in L/min
double calculate_flow_rate(int pulse_count, double pulses_per_liter) {
    return (double)pulse_count / pulses_per_liter * 60.0;
}

// Function to set the valve position using PWM
int set_valve_position(int duty_cycle) {
    if (duty_cycle < 0) duty_cycle = 0;
    if (duty_cycle > PWM_RANGE) duty_cycle = PWM_RANGE;

    gpioPWM(VALVE_PWM_PIN, duty_cycle);
    return 0;
}

// Function to log data to a CSV file
int log_data(double flow_rate, int valve_position) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Error: Log file is not open.\n");
        return -1;
    }

    fprintf(log_file, "%s,%.2f,%d\n", timestamp, flow_rate, valve_position);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

