#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define LOCK_1_PIN 17
#define LOCK_2_PIN 27
#define BUTTON_PIN 22

// Define SPI channel and baud rate
#define SPI_CHANNEL 0
#define SPI_BAUD 100000

// Define log file path
#define LOG_FILE "/var/log/door_access.log"

// Define valid tag ID
#define VALID_TAG_ID "0000000000"

// Define debounce time in milliseconds
#define DEBOUNCE_TIME 50

// Global variables
int spi_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int initialize_spi();
int read_rfid_tag(unsigned char *tag_id);
int validate_tag(const unsigned char *tag_id);
int control_lock(int lock_number, int state);
int log_access_attempt(const char *status, const char *message);
void button_callback(int gpio, int level, uint32_t tick);
void signal_handler(int signal);

// Structure to hold lock states
typedef struct {
    int lock1_engaged;
    int lock2_engaged;
} LockStates;

LockStates current_lock_states = {0, 0};

int main() {
    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        fprintf(stderr, "Failed to initialize GPIO. Exiting.\n");
        return 1;
    }

    // Initialize SPI
    if (initialize_spi() != 0) {
        fprintf(stderr, "Failed to initialize SPI. Exiting.\n");
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Failed to open log file. Exiting.\n");
        spiClose(spi_handle);
        gpioTerminate();
        return 1;
    }

    // Set button pin as input with pull-up resistor
    gpioSetMode(BUTTON_PIN, PI_INPUT);
    gpioSetPullUpDown(BUTTON_PIN, PI_PUD_UP);

    // Set up callback for button press
    gpioSetAlertFuncEx(BUTTON_PIN, button_callback, NULL);

    unsigned char tag_id[10];
    int tag_present = 0;
    int button_pressed = 0;
    int lock1_engaged = 0;
    int lock2_engaged = 0;

    printf("Door access control system started. Press Ctrl+C to exit.\n");

    while (program_running) {
        // Read RFID tag
        if (read_rfid_tag(tag_id) == 0) {
            tag_present = 1;

            // Validate tag
            if (validate_tag(tag_id)) {
                printf("Valid tag ID: %s\n", VALID_TAG_ID);
                log_access_attempt("Entry", "Valid tag ID");

                // Debounce button press
                if (!button_pressed) {
                    button_pressed = 1;
                    gpioDelay(DEBOUNCE_TIME * 1000); // Convert ms to microseconds

                    // Disengage locks
                    if (control_lock(1, 0) == 0 && control_lock(2, 0) == 0) {
                        lock1_engaged = 0;
                        lock2_engaged = 0;
                        printf("Locks disengaged.\n");
                        log_access_attempt("Entry", "Locks disengaged");
                        gpioDelay(5000 * 1000); // 5 seconds

                        // Re-engage locks
                        if (control_lock(1, 1) == 0 && control_lock(2, 1) == 0) {
                            lock1_engaged = 1;
                            lock2_engaged = 1;
                            printf("Locks re-engaged.\n");
                            log_access_attempt("Entry", "Locks re-engaged");
                        } else {
                            fprintf(stderr, "Failed to re-engage locks.\n");
                            log_access_attempt("Entry", "Failed to re-engage locks");
                        }
                    } else {
                        fprintf(stderr, "Failed to disengage locks.\n");
                        log_access_attempt("Entry", "Failed to disengage locks");
                    }
                }
            } else {
                printf("Invalid tag ID: %s\n", tag_id);
                log_access_attempt("Entry", "Invalid tag ID");
            }
        } else {
            // Log RFID read failure
            log_access_attempt("Entry", "RFID read failure");
        }

        gpioDelay(100 * 1000); // Check every 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_lock(1, 1); // Ensure locks are disengaged
    control_lock(2, 1);
    fclose(log_file);
    spiClose(spi_handle);
    gpioTerminate();

    return 0;
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(LOCK_1_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_2_PIN, PI_OUTPUT);

    return 0;
}

// Initialize SPI interface
int initialize_spi() {
    spi_handle = spiOpen(SPI_CHANNEL, SPI_BAUD, 0); // Mode 0
    if (spi_handle < 0) {
        fprintf(stderr, "SPI open failed\n");
        return 1;
    }

    return 0;
}

// Read RFID tag from SPI
int read_rfid_tag(unsigned char *tag_id) {
    char tx_buffer[10] = {0x01, 0x02, 0x03, 0x04, 0x05, 0x06, 0x07, 0x08, 0x09, 0x0A};
    char rx_buffer[10] = {0};
    int i, retries = 4;

    while (retries > 0) {
        if (spiXfer(spi_handle, tx_buffer, rx_buffer, 10) == 0) {
            // Check for all-zero response (no tag present)
            if (rx_buffer[0] == 0 && rx_buffer[1] == 0 && rx_buffer[2] == 0 && rx_buffer[3] == 0 &&
                rx_buffer[4] == 0 && rx_buffer[5] == 0 && rx_buffer[6] == 0 && rx_buffer[7] == 0 &&
                rx_buffer[8] == 0 && rx_buffer[9] == 0) {
                fprintf(stderr, "No tag present (SPI read error).\n");
                log_access_attempt("Entry", "No tag present (SPI read error)");
                return 1; // Indicate failure
            }

            // Copy received data to tag_id
            for (i = 0; i < 10; i++) {
                tag_id[i] = rx_buffer[i];
            }

            return 0; // Indicate success
        } else {
            fprintf(stderr, "SPI transfer failed (attempt %d).\n", 4 - retries + 1);
            log_access_attempt("Entry", "SPI transfer failed");
            gpioDelay(100 * 1000); // Wait before retrying
            retries--;
        }
    }

    fprintf(stderr, "Failed to read RFID tag after multiple retries.\n");
    log_access_attempt("Entry", "Failed to read RFID tag after multiple retries");
    return 1; // Indicate failure after retries
}

// Validate tag ID
int validate_tag(const unsigned char *tag_id) {
    return (strcmp((char *)tag_id, VALID_TAG_ID) == 0);
}

// Control lock (engage/disengage)
int control_lock(int lock_number, int state) {
    int pin;

    if (lock_number == 1) {
        pin = LOCK_1_PIN;
    } else if (lock_number == 2) {
        pin = LOCK_2_PIN;
    } else {
        fprintf(stderr, "Invalid lock number: %d\n", lock_number);
        return 1;
    }

    gpioWrite(pin, state);
    return 0;
}

// Log access attempt
int log_access_attempt(const char *status, const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[30];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", t);

    fprintf(log_file, "%s [%s] %s\n", timestamp, status, message);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Button callback function
void button_callback(int gpio, int level, uint32_t tick) {
    if (level == 0) { // Button pressed (active-low)
        printf("Button pressed!\n");
        log_access_attempt("Entry", "Button pressed");
        button_pressed = 0; // Reset flag
    }
}

// Signal handler function
void signal_handler(int signal) {
    printf("Signal received (%d). Shutting down...\n", signal);
    program_running = 0;
}

