}

// Encoder 1 Callback
void encoder1_callback(int gpio, int level, uint32_t tick, void *user_data) {
    static int last_level = 0;
    int current_level = gpioRead(gpio);

    if (current_level != last_level) {
        if (gpio == ENCODER1_A) {
            if (current_level == 1 && last_level == 0) {
                pthread_mutex_lock(&encoder1_mutex);
                encoder1_count++;
                pthread_mutex_unlock(&encoder1_mutex);
            } else if (current_level == 0 && last_level == 1) {
                pthread_mutex_lock(&encoder1_mutex);
                encoder1_count--;
                pthread_mutex_unlock(&encoder1_mutex);
            }
        } else if (gpio == ENCODER1_B) {
