    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,Motor1_RPM,Motor2_RPM,PID_Output,P,I,D\n");
    }
    rewind(log_file);

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Set up encoder interrupts
    gpioSetISRFuncEx(ENCODER1_A, RISING_EDGE, 0, encoder1_callback, NULL);
    gpioSetISRFuncEx(ENCODER1_B, RISING_EDGE, 0, encoder1_callback, NULL);
    gpioSetISRFuncEx(ENCODER2_A, RISING_EDGE, 0, encoder2_callback, NULL);
    gpioSetISRFuncEx(ENCODER2_B, RISING_EDGE, 0, encoder2_callback, NULL);

