        double motor2_rpm = (double)encoder2_count_local / ENCODER_COUNTS_PER_REVOLUTION * 60.0;

        // Calculate PID output
        double pid_output = calculate_pid(TARGET_SPEED, (motor1_rpm + motor2_rpm) / 2.0);

        // Limit PID output to PWM range
        if (pid_output < 0) {
            pid_output = 0;
        } else if (pid_output > PWM_RANGE) {
            pid_output = PWM_RANGE;
        }

        // Set motor speeds based on PID output
        if (pid_output > 0) {
            motor_forward(MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, (int)pid_output);
            motor_forward(MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4, (int)pid_output);
        } else {
            motor_backward(MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2, (int)(-pid_output));
            motor_backward(MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4, (int)(-pid_output));
        }

        // Log data
        log_data(motor1_rpm, motor2_rpm, pid_output, KP * pid_output, KI * pid_output, KD * pid_output);

        // Delay for 100ms
        gpioDelay(100000); // 100ms = 100000 microseconds
    }

    // Cleanup (should not reach here in normal operation due to signal handler)
    motor_stop(MOTOR1_ENA, MOTOR1_IN1, MOTOR1_IN2);
    motor_stop(MOTOR2_ENB, MOTOR2_IN3, MOTOR2_IN4);
    gpioTerminate();
    fclose(log_file);

