#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// MPR121 I2C address
#define MPR121_ADDR 0x5A

// MPR121 registers
#define MPR121_TOUCHSTATUS_L 0x00
#define MPR121_TOUCHSTATUS_H 0x01
#define MPR121_ELECTRODE_CONFIG 0x5E
#define MPR121_FILTERTH_0 0x24
#define MPR121_BASELINE_0 0x1E
#define MPR121_TOUCHTH_0 0x41
#define MPR121_RELEASETH_0 0x42
#define MPR121_ECR 0x5E
#define MPR121_CONFIG1 0x5B
#define MPR121_CONFIG2 0x5C
#define MPR121_CONFIG3 0x5D

// GPIO pin for relay control
#define RELAY_PIN 17

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t program_running = 1;

// Function prototypes
int mpr121_init();
int read_touch_status(uint16_t *touch_status);
void control_relay(uint16_t touch_status);
void log_relay_state(uint16_t touch_status);
void signal_handler(int signal);

// Structure to hold configuration data
typedef struct {
    int touch_threshold;
    int release_threshold;
} electrode_config_t;

// Function to initialize the MPR121 sensor
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x80) < 0) {
        fprintf(stderr, "Error: Soft reset failed.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure electrode configuration (example configuration)
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Electrode configuration failed.\n");
        return -1;
    }

    // Configure filtering parameters (example configuration)
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_0, 0x05) < 0) {
        fprintf(stderr, "Error: Filter threshold configuration failed.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_0, 0x05) < 0) {
        fprintf(stderr, "Error: Baseline configuration failed.\n");
        return -1;
    }

    // Configure touch and release thresholds for each electrode (example configuration)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 0x0A) < 0) {
            fprintf(stderr, "Error: Touch threshold configuration failed for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 0x05) < 0) {
            fprintf(stderr, "Error: Release threshold configuration failed for electrode %d.\n", i);
            return -1;
        }
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Run mode configuration failed.\n");
        return -1;
    }

    return 0;
}

// Function to read the touch status from the MPR121 sensor
int read_touch_status(uint16_t *touch_status) {
    char buf[2];
    if (i2cReadI2CBlockData(i2c_handle, MPR121_TOUCHSTATUS_L, buf, 2) != 2) {
        fprintf(stderr, "Error: Failed to read touch status.\n");
        return -1;
    }
    *touch_status = (buf[1] << 8) | buf[0];
    return 0;
}

// Function to control the relay based on the touch status
void control_relay(uint16_t touch_status) {
    if (touch_status) {
        gpioWrite(RELAY_PIN, 1); // Set relay HIGH
    } else {
        gpioWrite(RELAY_PIN, 0); // Set relay LOW
    }
}

// Function to log the relay state to a file
void log_relay_state(uint16_t touch_status) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
