// Structure to hold configuration data
typedef struct {
    int touch_threshold;
    int release_threshold;
} electrode_config_t;

// Function to initialize the MPR121 sensor
int mpr121_init() {
    // Soft reset
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x80) < 0) {
        fprintf(stderr, "Error: Soft reset failed.\n");
        return -1;
    }
    gpioDelay(10); // Wait for reset to complete

    // Configure electrode configuration (example configuration)
    if (i2cWriteByteData(i2c_handle, MPR121_ELECTRODE_CONFIG, 0x0C) < 0) {
        fprintf(stderr, "Error: Electrode configuration failed.\n");
        return -1;
    }

    // Configure filtering parameters (example configuration)
    if (i2cWriteByteData(i2c_handle, MPR121_FILTERTH_0, 0x05) < 0) {
        fprintf(stderr, "Error: Filter threshold configuration failed.\n");
        return -1;
    }
    if (i2cWriteByteData(i2c_handle, MPR121_BASELINE_0, 0x05) < 0) {
        fprintf(stderr, "Error: Baseline configuration failed.\n");
        return -1;
    }

    // Configure touch and release thresholds for each electrode (example configuration)
    for (int i = 0; i < 12; i++) {
        if (i2cWriteByteData(i2c_handle, MPR121_TOUCHTH_0 + 2 * i, 0x0A) < 0) {
            fprintf(stderr, "Error: Touch threshold configuration failed for electrode %d.\n", i);
            return -1;
        }
        if (i2cWriteByteData(i2c_handle, MPR121_RELEASETH_0 + 2 * i, 0x05) < 0) {
            fprintf(stderr, "Error: Release threshold configuration failed for electrode %d.\n", i);
            return -1;
        }
    }

    // Enable run mode
    if (i2cWriteByteData(i2c_handle, MPR121_ECR, 0x00) < 0) {
        fprintf(stderr, "Error: Run mode configuration failed.\n");
        return -1;
    }

    return 0;
