void cleanup() {
    printf("Cleaning up...\n");

    // Close the log file
    if (log_file != NULL) {
        fclose(log_file);
    }

    // Terminate the pigpio library
    gpioTerminate();

    // Ensure relay is off
    control_relay(0);
}

