        fprintf(stderr, "Error opening log file!\n");
        cleanup();
        return 1;
    }

    printf("Motion detection system started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int motion_detected = read_pir_sensor();

        if (motion_detected == 1) {
            // Motion detected
            time_t now = time(NULL);
            if (difftime(now, last_motion_time) >= RATE_LIMITING_DURATION) {
                // Rate limiting is not violated
                printf("Motion detected!\n");
                log_event("Motion Detected");
                control_relay(1); // Activate relay
