                control_relay(0); // Deactivate relay
                log_event("Door Unlocked");
                last_motion_time = now; // Update last motion time
            } else {
                // Rate limiting is violated
                printf("Rate limiting violated! Ignoring motion.\n");
                log_event("Rate Limiting Violated");
            }
        }

        gpioDelay(50 * 1000); // Check every 50ms
    }

    // Cleanup and exit
    cleanup();
    return 0;
