#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27

// Define weight threshold
#define WEIGHT_THRESHOLD 10.0

// Define timeout duration (in seconds)
#define TIMEOUT_DURATION 0.5

// Define calibration file name
#define CALIBRATION_FILE "calibration.txt"

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;
static double scale_factor = 1.0;
static double offset = 0.0;

// Function prototypes
int read_hx711();
double convert_to_weight(int raw_value);
void control_solenoid(int engage);
void log_weight(double weight);
void load_calibration_data();
void save_calibration_data();
void signal_handler(int signal);

// Function to read raw data from HX711
int read_hx711() {
    int data = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for the HX711 to be ready (data line low)
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < 1000) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= 1000) {
        fprintf(stderr, "Error: HX711 timeout waiting for data.\n");
        return -1; // Indicate timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Small delay
        data = data << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            data++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Small delay
    }

    // Apply the 25th clock pulse for gain selection (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1); // Small delay
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1); // Small delay

    // Convert to signed 24-bit integer
    if (data & 0x800000) {
        data |= 0xFF000000; // Sign extend if negative
    }

    return data;
}

// Function to convert raw data to weight
double convert_to_weight(int raw_value) {
    return (double)(raw_value - offset) / scale_factor;
}

// Function to control the solenoid lock
void control_solenoid(int engage) {
    gpioWrite(SOLENOID_PIN, engage);
}

// Function to log weight data to a file
void log_weight(double weight) {
    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", &tm);

    fprintf(log_file, "%s, Weight: %.2f kg\n", timestamp, weight);
    fflush(log_file); // Ensure data is written to file immediately
}

// Function to load calibration data from file
void load_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "r");
    if (fp == NULL) {
        fprintf(stderr, "Warning: Could not open calibration file %s. Using default values.\n", CALIBRATION_FILE);
        return;
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) != NULL) {
        if (sscanf(line, "%lf %lf", &scale_factor, &offset) == 2) {
            printf("Calibration data loaded: scale_factor=%.2f, offset=%.2f\n", scale_factor, offset);
        } else {
            fprintf(stderr, "Warning: Invalid calibration data in %s. Using default values.\n", CALIBRATION_FILE);
            fclose(fp);
            return;
        }
    } else {
        fprintf(stderr, "Warning: Could not read calibration data from %s. Using default values.\n", CALIBRATION_FILE);
        fclose(fp);
        return;
    }

    fclose(fp);
}

// Function to save calibration data to file
void save_calibration_data() {
    FILE *fp = fopen(CALIBRATION_FILE, "w");
    if (fp == NULL) {
        fprintf(stderr, "Error: Could not open calibration file %s for writing.\n", CALIBRATION_FILE);
        return;
    }

    fprintf(fp, "%.2f %.2f\n", scale_factor, offset);
    fclose(fp);
    printf("Calibration data saved to %s\n", CALIBRATION_FILE);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully.\n", signal);
    running = 0;
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);

    // Load calibration data
    load_calibration_data();

    // Open log file
    log_file = fopen("weight_log.txt", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file\n");
        gpioTerminate();
        return 1;
    }

    // Register signal handler
    signal(SIGINT, signal_handler);

    printf("Weight monitoring started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int raw_value = read_hx711();
        if (raw_value == -1) {
            fprintf(stderr, "Error: Failed to read HX711 data. Skipping iteration.\n");
            gpioDelay(100); // Small delay before next iteration
            continue;
        }

        double weight = convert_to_weight(raw_value);
        log_weight(weight);

        if (weight > WEIGHT_THRESHOLD) {
            control_solenoid(1); // Engage solenoid
            printf("Weight threshold exceeded! Weight: %.2f kg\n", weight);
        } else {
            control_solenoid(0); // Deactivate solenoid
        }

        gpioDelay(500); // Delay for 500 milliseconds
    }

    // Cleanup
    control_solenoid(0); // Deactivate solenoid
    fclose(log_file);
    gpioTerminate();

    return 0;
}

