#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <pigpio.h>

// Define GPIO pins
#define RAIN_SENSOR_PIN 4
#define MOTOR_IN1_PIN 17
#define MOTOR_IN2_PIN 18
#define MOTOR_PWM_PIN 27

// Define rain detection threshold
#define RAIN_THRESHOLD 3

// Define motor control parameters
#define MOTOR_CLOSE_DURATION 5 // seconds
#define MOTOR_CLOSE_DUTY_CYCLE 150 // PWM duty cycle (0-255)

// Define debounce delay (milliseconds)
#define DEBOUNCE_DELAY 50

// Global variables
static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int read_rain_sensor();
int detect_rain(int sensor_values[], int num_readings);
void close_window();
void stop_motor();
void log_event(const char *message);
void signal_handler(int signal);

// Function to read the rain sensor
int read_rain_sensor() {
    int sensor_value = gpioRead(RAIN_SENSOR_PIN);
    if (sensor_value < 0) {
        syslog(LOG_ERR, "Error reading rain sensor: %d", sensor_value);
        return -1; // Indicate error
    }
    return sensor_value;
}

// Function to detect rain based on sensor readings
int detect_rain(int sensor_values[], int num_readings) {
    int rain_count = 0;
    for (int i = 0; i < num_readings; i++) {
        if (sensor_values[i] == 0) {
            rain_count++;
        }
    }
    return (rain_count >= RAIN_THRESHOLD);
}

// Function to close the window
void close_window() {
    gpioWrite(MOTOR_IN1_PIN, 1);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, MOTOR_CLOSE_DUTY_CYCLE);
    log_event("Closing window...");
    gpioDelay(MOTOR_CLOSE_DURATION * 1000); // Delay in milliseconds
    stop_motor();
    log_event("Window closed.");
}

// Function to stop the motor
void stop_motor() {
    gpioWrite(MOTOR_IN1_PIN, 0);
    gpioWrite(MOTOR_IN2_PIN, 0);
    gpioPWM(MOTOR_PWM_PIN, 0);
    log_event("Stopping motor.");
}

// Function to log events to syslog
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    syslog(LOG_INFO, "%s: %s", timestamp, message);
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    running = 0;
    log_event("Received signal, shutting down...");
}

int main() {
    // Initialize syslog
    openlog("window_control", LOG_PID | LOG_CONS, LOG_USER);

    // Initialize pigpio
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return 1;
    }

    // Set GPIO modes
    gpioSetMode(RAIN_SENSOR_PIN, PI_INPUT);
    gpioSetMode(MOTOR_IN1_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_IN2_PIN, PI_OUTPUT);
    gpioSetMode(MOTOR_PWM_PIN, PI_OUTPUT);

    // Set PWM range (0-255)
    gpioSetPWMrange(MOTOR_PWM_PIN, 255);

    // Set PWM frequency (1000 Hz)
    gpioSetPWMfrequency(MOTOR_PWM_PIN, 1000);

    // Initialize sensor values array
    int sensor_values[5];

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System started.");

    // Main loop
    while (running) {
        // Read rain sensor
        int sensor_value = read_rain_sensor();
        if (sensor_value < 0) {
            // Error reading sensor, retry after a delay
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Store sensor value in circular buffer
        sensor_values[0] = sensor_value;
        for (int i = 1; i < 5; i++) {
            sensor_values[i] = sensor_values[i - 1];
        }

        // Detect rain
        if (detect_rain(sensor_values, 5)) {
            log_event("Rain detected!");
            close_window();
        }

        // Wait 60 seconds
        gpioDelay(60000); // Wait 60 seconds
    }

    // Cleanup
    stop_motor();
    gpioTerminate();
    closelog();

    return 0;
}

