    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    log_event("System started.");

    // Main loop
    while (running) {
        // Read rain sensor
        int sensor_value = read_rain_sensor();
        if (sensor_value < 0) {
            // Error reading sensor, retry after a delay
            gpioDelay(1000); // Wait 1 second before retrying
            continue;
        }

        // Store sensor value in circular buffer
        sensor_values[0] = sensor_value;
        for (int i = 1; i < 5; i++) {
            sensor_values[i] = sensor_values[i - 1];
        }

        // Detect rain
        if (detect_rain(sensor_values, 5)) {
            log_event("Rain detected!");
            close_window();
        }

        // Wait 60 seconds
        gpioDelay(60000); // Wait 60 seconds
    }

    // Cleanup
    stop_motor();
    gpioTerminate();
    closelog();

