#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/ioctl.h>
#include <linux/spi/spidev.h>
#include <pigpio.h>

// Configuration
#define HX711_DATA_PIN 4
#define HX711_CLOCK_PIN 17
#define SOLENOID_PIN 27
#define CALIBRATION_FILE "calibration.txt"
#define LOG_FILE "security.log"
#define WEIGHT_THRESHOLD 5.0 // kg
#define SOLENOID_DURATION 5 // seconds
#define TIMEOUT_US 100000 // 100ms

// Global variables
static volatile int running = 1;
static int spi_fd;
static double calibration_factor = 0.0;
static FILE *log_file = NULL;

// Function prototypes
int init_gpio();
int init_spi();
int read_hx711();
double calibrate_hx711();
double get_weight(double calibration_factor);
void control_solenoid(int state);
void log_event(const char *message);
void signal_handler(int signal);

// HX711 read function using bit-banging
int read_hx711() {
    int32_t count = 0;
    int i;

    gpioSetMode(HX711_DATA_PIN, PI_INPUT);
    gpioSetMode(HX711_CLOCK_PIN, PI_OUTPUT);

    // Wait for data line to go low (timeout)
    int timeout = 0;
    while (gpioRead(HX711_DATA_PIN) == 1 && timeout < TIMEOUT_US) {
        gpioDelay(1); // Small delay to prevent busy-waiting
        timeout++;
    }

    if (timeout >= TIMEOUT_US) {
        log_event("HX711 Timeout: Data line high for too long.");
        return -1; // Timeout error
    }

    // Read 24 bits of data
    for (i = 0; i < 24; i++) {
        gpioWrite(HX711_CLOCK_PIN, 1);
        gpioDelay(1); // Clock high delay
        count = count << 1;
        if (gpioRead(HX711_DATA_PIN)) {
            count++;
        }
        gpioWrite(HX711_CLOCK_PIN, 0);
        gpioDelay(1); // Clock low delay
    }

    // Apply the 25th clock pulse for gain selection (channel A, gain 128)
    gpioWrite(HX711_CLOCK_PIN, 1);
    gpioDelay(1);
    gpioWrite(HX711_CLOCK_PIN, 0);
    gpioDelay(1);

    // Convert to signed 24-bit integer
    if (count & 0x800000) {
        count |= 0xFF000000; // Sign extend if negative
    }

    return count;
}

// Calibration function
double calibrate_hx711() {
    double known_weight;
    int raw_value;

    printf("Place a known weight on the load cell (in kg): ");
    if (scanf("%lf", &known_weight) != 1) {
        fprintf(stderr, "Error: Invalid input for known weight.\n");
        return -1.0;
    }

    printf("Reading raw value from HX711...\n");
    raw_value = read_hx711();
    if (raw_value == -1) {
        fprintf(stderr, "Error: Failed to read raw value from HX711.\n");
        return -1.0;
    }

    printf("Calibration factor: %lf\n", known_weight / (double)raw_value);
    return known_weight / (double)raw_value;
}

// Weight calculation function
double get_weight(double calibration_factor) {
    int raw_value = read_hx711();
    if (raw_value == -1) {
        return -1.0; // Indicate error
    }
    return (double)raw_value / calibration_factor;
}

// Solenoid control function
void control_solenoid(int state) {
    gpioWrite(SOLENOID_PIN, state);
}

// Logging function
void log_event(const char *message) {
    time_t now = time(NULL);
    struct tm *t = localtime(&now);
    char timestamp[64];
    strftime(timestamp, sizeof(timestamp) - 1, "%Y-%m-%d %H:%M:%S", t);

    if (log_file != NULL) {
        fprintf(log_file, "%s: %s\n", timestamp, message);
        fflush(log_file); // Ensure immediate write
    } else {
        fprintf(stderr, "Error: Log file not opened.\n");
    }
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

// Initialize GPIO
int init_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "Error: pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOLENOID_PIN, PI_OUTPUT);
    gpioWrite(SOLENOID_PIN, 0); // Ensure solenoid is initially off

    return 0;
}

// Initialize SPI
int init_spi() {
    spi_fd = open("/dev/spidev0.0", O_RDWR);
    if (spi_fd < 0) {
        fprintf(stderr, "Error: Could not open SPI device: %s\n", strerror(errno));
        return -1;
    }

    // Configure SPI mode
    uint8_t mode = 0; // SPI mode 0
    if (ioctl(spi_fd, SPI_IOC_WR_MODE, &mode) == -1) {
        fprintf(stderr, "Error: Could not set SPI mode: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure SPI bits per word
    uint8_t bits = 8;
    if (ioctl(spi_fd, SPI_IOC_WR_BITS_PER_WORD, &bits) == -1) {
        fprintf(stderr, "Error: Could not set SPI bits per word: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    // Configure SPI max speed hz
    uint32_t speed = 1000000; // 1 MHz
    if (ioctl(spi_fd, SPI_IOC_WR_MAX_SPEED_HZ, &speed) == -1) {
        fprintf(stderr, "Error: Could not set SPI max speed hz: %s\n", strerror(errno));
        close(spi_fd);
        return -1;
    }

    return 0;
}

int main() {
    // Install signal handler
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (init_gpio() != 0) {
        return 1;
    }

    // Initialize SPI
    if (init_spi() != 0) {
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen(LOG_FILE, "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error: Could not open log file: %s\n", strerror(errno));
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    // Calibrate HX711
    calibration_factor = calibrate_hx711();
    if (calibration_factor < 0) {
        log_event("Calibration failed. Exiting.");
        fclose(log_file);
        close(spi_fd);
        gpioTerminate();
        return 1;
    }

    printf("Calibration factor: %lf\n", calibration_factor);

    // Main loop
    while (running) {
        double weight = get_weight(calibration_factor);
        if (weight >= 0) {
            printf("Weight: %.2f kg\n", weight);

            if (weight > WEIGHT_THRESHOLD) {
                printf("Weight threshold exceeded! Activating solenoid.\n");
                control_solenoid(1); // Activate solenoid
                log_event("Weight threshold exceeded. Activating solenoid.");
                gpioDelay(SOLENOID_DURATION * 1000000); // Wait for 5 seconds
                control_solenoid(0); // Deactivate solenoid
                log_event("Solenoid deactivated.");
            }
        } else {
            fprintf(stderr, "Error: Failed to read weight.\n");
        }

        gpioDelay(100000); // Delay 100ms
    }

    // Cleanup
    printf("Cleaning up...\n");
    control_solenoid(0); // Ensure solenoid is off
    fclose(log_file);
    close(spi_fd);
    gpioTerminate();

    return 0;
}

