static volatile int running = 1;
static FILE *log_file = NULL;

// Function prototypes
int initialize_gpio();
int read_sensor();
int toggle_relay(int current_state);
int log_event(int new_state);
void signal_handler(int signal);

// Structure to hold GPIO configuration
typedef struct {
    int sensor_pin;
    int relay_pin;
} gpio_config_t;

