    gpioWrite(RELAY_PIN, RELAY_OFF);

    return 0;
}

// Function to read the sensor value
int read_sensor() {
    return gpioRead(SENSOR_PIN);
}

// Function to toggle the relay state
int toggle_relay(int current_state) {
    int new_state = (current_state == RELAY_ON) ? RELAY_OFF : RELAY_ON;
    gpioWrite(RELAY_PIN, new_state);
    return new_state;
}

// Function to log the event to a file
int log_event(int new_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%dT%H:%M:%SZ", timeinfo);

    if (log_file == NULL) {
        fprintf(stderr, "Log file is not open\n");
        return -1;
    }

    fprintf(log_file, "%s - Relay toggled to %s\n", timestamp, (new_state == RELAY_ON) ? "ON" : "OFF");
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, exiting gracefully...\n", signal);
    running = 0;
}

