        fprintf(stderr, "Error opening log file: %s\n", LOG_FILE);
        gpioTerminate();
        return 1;
    }

    printf("Relay control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (running) {
        int sensor_value = read_sensor();

        if (sensor_value < 0) {
            fprintf(stderr, "Error reading sensor, retrying...\n");
            gpioDelay(100); // Wait before retrying
            continue;
        }

        if (sensor_value == 0) { // Obstacle detected (LOW signal)
            int new_relay_state = toggle_relay(gpio_config.relay_pin);
            if (new_relay_state != gpio_config.relay_pin) {
                if (log_event(new_relay_state) != 0) {
                    fprintf(stderr, "Error logging event\n");
                }
            }
        }

        gpioDelay(100); // Delay to avoid excessive CPU usage
    }

    // Cleanup
    gpioWrite(RELAY_PIN, RELAY_OFF); // Ensure relay is OFF on exit
    fclose(log_file);
    gpioTerminate();

    printf("Relay control program stopped.\n");

    return 0;
}

