#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Configuration file path
#define CONFIG_FILE "watering.conf"

// GPIO pin for the solenoid valve
#define VALVE_GPIO 18

// Global variable to track program termination
volatile sig_atomic_t program_running = 1;

// Function prototypes
int read_watering_duration(const char *filename);
void activate_valve(int duration_seconds);
void deactivate_valve();
void log_event(const char *message);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    log_event("Signal received, shutting down...");
}

// Function to read the watering duration from the configuration file
int read_watering_duration(const char *filename) {
    FILE *fp = fopen(filename, "r");
    if (fp == NULL) {
        perror("Error opening config file");
        log_event("Error opening config file, using default duration");
        return 60; // Default duration in seconds
    }

    char line[256];
    if (fgets(line, sizeof(line), fp) == NULL) {
        fclose(fp);
        log_event("Error reading config file, using default duration");
        return 60; // Default duration in seconds
    }

    fclose(fp);

    // Remove newline character
    line[strcspn(line, "\n")] = 0;

    // Parse the duration
    char *token = strtok(line, "=");
    if (token == NULL || strcmp(token, "duration") != 0) {
        log_event("Invalid config file format, using default duration");
        return 60; // Default duration in seconds
    }

    token = strtok(NULL, "=");
    if (token == NULL) {
        log_event("Invalid config file format, using default duration");
        return 60; // Default duration in seconds
    }

    long duration_seconds = strtol(token, NULL, 10);

    // Validate the duration
    if (duration_seconds <= 0 || duration_seconds > 3600) {
        log_event("Invalid duration value, using default duration");
        return 60; // Default duration in seconds
    }

    return (int)duration_seconds;
}

// Function to activate the valve for a specified duration
void activate_valve(int duration_seconds) {
    gpioWrite(VALVE_GPIO, 1); // Set GPIO HIGH to activate the valve
    log_event("Valve activated");
    gpioDelay(duration_seconds * 1000000); // Delay for the specified duration (microseconds)
    gpioWrite(VALVE_GPIO, 0); // Set GPIO LOW to deactivate the valve
    log_event("Valve deactivated");
}

// Function to deactivate the valve
void deactivate_valve() {
    gpioWrite(VALVE_GPIO, 0); // Set GPIO LOW to deactivate the valve
    log_event("Valve deactivated");
}

// Function to log events to a file with a timestamp
void log_event(const char *message) {
    FILE *fp = fopen("watering.log", "a");
    if (fp == NULL) {
        perror("Error opening log file");
        return;
    }

    time_t t = time(NULL);
    struct tm tm = *localtime(&t);
    fprintf(fp, "[%d-%02d-%02d %02d:%02d:%02d] %s\n", tm.tm_year + 1900, tm.tm_mon + 1, tm.tm_mday, tm.tm_hour, tm.tm_min, tm.tm_sec, message);
    fclose(fp);
}

int main() {
    // Initialize pigpio library
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        log_event("pigpio initialisation failed");
        return 1;
    }

    // Set GPIO18 as an output
    gpioSetMode(VALVE_GPIO, PI_OUTPUT);

    // Set initial valve state to LOW (off)
    gpioWrite(VALVE_GPIO, 0);

    // Read watering duration from the configuration file
    int duration_seconds = read_watering_duration(CONFIG_FILE);

    // Set up signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (program_running) {
        activate_valve(duration_seconds);
    }

    // Clean up and exit
    deactivate_valve();
    gpioTerminate();
    log_event("Program terminated");
    return 0;
}

