#include <stdio.h>
#include <stdlib.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins
#define SERVO_PIN 18
#define LOCK_BUTTON_PIN 21
#define UNLOCK_BUTTON_PIN 22

// Define servo pulse width limits
#define SERVO_MIN_PULSE_WIDTH 500
#define SERVO_MAX_PULSE_WIDTH 2500

// Global variable to track program state for signal handling
volatile sig_atomic_t program_running = 1;

// Function prototypes
int initialize_gpio();
int set_servo_angle(int angle);
int read_button(int pin);
void debounce_button(int pin);
void lock_door();
void unlock_door();
void cleanup_gpio();
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, cleaning up and exiting...\n", signal);
    cleanup_gpio();
    exit(0);
}

// Initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    gpioSetMode(SERVO_PIN, PI_OUTPUT);
    gpioSetMode(LOCK_BUTTON_PIN, PI_INPUT);
    gpioSetMode(UNLOCK_BUTTON_PIN, PI_INPUT);

    gpioSetPullUpDown(LOCK_BUTTON_PIN, PI_PUD_UP);
    gpioSetPullUpDown(UNLOCK_BUTTON_PIN, PI_PUD_UP);

    return 0;
}

// Set servo angle
int set_servo_angle(int angle) {
    if (angle < 0 || angle > 180) {
        fprintf(stderr, "Invalid servo angle: %d\n", angle);
        return 1;
    }

    int pulse_width = SERVO_MIN_PULSE_WIDTH + (int)(((float)angle / 180.0) * (SERVO_MAX_PULSE_WIDTH - SERVO_MIN_PULSE_WIDTH));
    gpioServo(SERVO_PIN, pulse_width);
    return 0;
}

// Read button state
int read_button(int pin) {
    return gpioRead(pin);
}

// Debounce button press
void debounce_button(int pin) {
    gpioDelay(100000); // 100ms
}

// Lock the door
void lock_door() {
    printf("Locking door...\n");
    if (set_servo_angle(0) != 0) {
        fprintf(stderr, "Failed to set servo angle to 0\n");
    }
}

// Unlock the door
void unlock_door() {
    printf("Unlocking door...\n");
    if (set_servo_angle(180) != 0) {
        fprintf(stderr, "Failed to set servo angle to 180\n");
    }
}

// Cleanup GPIO resources
void cleanup_gpio() {
    gpioServo(SERVO_PIN, 0); // Stop the servo
    gpioTerminate();
}

int main() {
    // Register signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    printf("Door lock control program started. Press Ctrl+C to exit.\n");

    // Main loop
    while (program_running) {
        // Read lock button
        if (read_button(LOCK_BUTTON_PIN) == 0) {
            debounce_button(LOCK_BUTTON_PIN);
            lock_door();
        }

        // Read unlock button
        if (read_button(UNLOCK_BUTTON_PIN) == 0) {
            debounce_button(UNLOCK_BUTTON_PIN);
            unlock_door();
        }

        gpioDelay(10000); // Check every 10ms
    }

    return 0;
}

