#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <signal.h>
#include <unistd.h>
#include <zmq.h>
#include <pigpio.h>

// Define GPIO pins
#define SOUND_SENSOR_PIN 17
#define ALARM_LED_PIN 27

// Define ZeroMQ endpoints
#define SOUND_SENSOR_ENDPOINT "tcp://*:5555"
#define ALARM_NODE_ENDPOINT "tcp://*:5556"

// Define ZeroMQ topic
#define SOUND_ALERTS_TOPIC "SOUND_ALERTS"

// Global variables
void *sound_context = NULL;
void *sound_socket = NULL;
void *alarm_context = NULL;
void *alarm_socket = NULL;

// Function prototypes
int initialize_gpio();
int initialize_zmq();
void sound_sensor_mode();
void alarm_node_mode();
void cleanup();
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Initializes the GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }

    gpioSetMode(SOUND_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(SOUND_SENSOR_PIN, PI_PUD_UP); // Enable pull-up resistor

    gpioSetMode(ALARM_LED_PIN, PI_OUTPUT);
    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off initially

    return 0;
}

// Initializes the ZeroMQ sockets
int initialize_zmq() {
    sound_context = zmq_ctx_new();
    if (!sound_context) {
        fprintf(stderr, "Failed to create ZeroMQ context for sound sensor\n");
        return -1;
    }

    sound_socket = zmq_socket(sound_context, ZMQ_SUB);
    if (!sound_socket) {
        fprintf(stderr, "Failed to create ZeroMQ socket for sound sensor\n");
        zmq_ctx_destroy(sound_context);
        return -1;
    }

    int rc = zmq_bind(sound_socket, SOUND_SENSOR_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "Failed to bind ZeroMQ socket for sound sensor: %s\n", zmq_strerror(errno));
        zmq_close(sound_socket);
        zmq_ctx_destroy(sound_context);
        return -1;
    }

    rc = zmq_setsockopt(sound_socket, ZMQ_SUBSCRIBE, SOUND_ALERTS_TOPIC, strlen(SOUND_ALERTS_TOPIC));
    if (rc != 0) {
        fprintf(stderr, "Failed to set ZeroMQ socket options for sound sensor: %s\n", zmq_strerror(errno));
        zmq_close(sound_socket);
        zmq_ctx_destroy(sound_context);
        return -1;
    }

    alarm_context = zmq_ctx_new();
    if (!alarm_context) {
        fprintf(stderr, "Failed to create ZeroMQ context for alarm node\n");
        zmq_close(sound_socket);
        zmq_ctx_destroy(sound_context);
        return -1;
    }

    alarm_socket = zmq_socket(alarm_context, ZMQ_PUB);
    if (!alarm_socket) {
        fprintf(stderr, "Failed to create ZeroMQ socket for alarm node\n");
        zmq_close(sound_socket);
        zmq_ctx_destroy(sound_context);
        zmq_ctx_destroy(alarm_context);
        return -1;
    }

    rc = zmq_bind(alarm_socket, ALARM_NODE_ENDPOINT);
    if (rc != 0) {
        fprintf(stderr, "Failed to bind ZeroMQ socket for alarm node: %s\n", zmq_strerror(errno));
        zmq_close(alarm_socket);
        zmq_ctx_destroy(sound_context);
        zmq_ctx_destroy(alarm_context);
        return -1;
    }

    return 0;
}

// Runs the sound sensor mode
void sound_sensor_mode() {
    printf("Sound sensor mode started. Press Ctrl+C to exit.\n");

    while (1) {
        int sound_detected = gpioRead(SOUND_SENSOR_PIN) == 0; // Active low

        if (sound_detected) {
            printf("Sound detected!\n");

            // Publish alert message
            char message[256];
            snprintf(message, sizeof(message), "%s", SOUND_ALERTS_TOPIC);
            int rc = zmq_send(sound_socket, message, strlen(message), 0);
            if (rc == -1) {
                fprintf(stderr, "Failed to send alert message: %s\n", zmq_strerror(errno));
            }

            // Wait for a short period to avoid multiple triggers
            gpioDelay(100000); // 100ms
        }

        gpioDelay(10000); // 10ms delay
    }
}

// Runs the alarm node mode
void alarm_node_mode() {
    printf("Alarm node mode started. Press Ctrl+C to exit.\n");

    while (1) {
        zmq_msg_t message;
        zmq_msg_init(&message);

        int rc = zmq_msg_recv(&message, alarm_socket, 0);
        if (rc == -1) {
            fprintf(stderr, "Failed to receive message: %s\n", zmq_strerror(errno));
            zmq_msg_close(&message);
            continue; // Continue to the next iteration
        }

        char *topic = zmq_msg_data(&message);
        int topic_len = zmq_msg_size(&message);

        if (strncmp(topic, SOUND_ALERTS_TOPIC, topic_len) == 0) {
            printf("Alarm triggered!\n");

            // Turn on the alarm LED
            gpioWrite(ALARM_LED_PIN, 1);
            gpioDelay(1000000); // 1 second
            gpioWrite(ALARM_LED_PIN, 0);
        }

        zmq_msg_close(&message);
    }
}

// Cleans up resources before exiting
void cleanup() {
    printf("Cleaning up resources...\n");

    if (sound_socket) {
        zmq_close(sound_socket);
    }
    if (sound_context) {
        zmq_ctx_destroy(sound_context);
    }

    if (alarm_socket) {
        zmq_close(alarm_socket);
    }
    if (alarm_context) {
        zmq_ctx_destroy(alarm_context);
    }

    gpioWrite(ALARM_LED_PIN, 0); // Ensure LED is off
    gpioTerminate();
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <sound_sensor|alarm_node>\n", argv[0]);
        return 1;
    }

    if (strcmp(argv[1], "sound_sensor") == 0) {
        if (initialize_gpio() != 0) {
            return 1;
        }
        if (initialize_zmq() != 0) {
            cleanup();
            return 1;
        }
        signal(SIGINT, signal_handler);
        signal(SIGTERM, signal_handler);
        sound_sensor_mode();
    } else if (strcmp(argv[1], "alarm_node") == 0) {
        if (initialize_gpio() != 0) {
            return 1;
        }
        if (initialize_zmq() != 0) {
            cleanup();
            return 1;
        }
        signal(SIGINT, signal_handler);
        signal(SIGTERM, signal_handler);
        alarm_node_mode();
    } else {
        fprintf(stderr, "Invalid mode: %s\n", argv[1]);
        return 1;
    }

    return 0;
}

