#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <syslog.h>
#include <mosquitto.h>
#include <pigpio.h>

// Configuration
#define IR_GPIO 17
#define MQTT_BROKER "localhost"
#define MQTT_PORT 1883
#define MQTT_TOPIC "ir/decoded"
#define LOG_FILE "ir_decoder.log"
#define NEC_FRAME_LENGTH 32
#define NEC_INVERTED_LENGTH 32
#define NEC_PULSE_BUFFER_SIZE 1024
#define NEC_PULSE_TIMEOUT_US 50000 // 50ms timeout

// Global variables
static volatile int running = 1;
static int pulse_buffer[NEC_PULSE_BUFFER_SIZE];
static int pulse_buffer_index = 0;
static int pulse_buffer_overflow = 0;
static struct mosquitto *mosq = NULL;
static int mqtt_connected = 0;

// NEC timing constants (in microseconds)
#define NEC_MARK 9000
#define NEC_SPACE 4500
#define NEC_BIT_MARK 560
#define NEC_ONE_SPACE 1690
#define NEC_ZERO_SPACE 560

// NEC command structure
typedef struct {
    unsigned int address;
    unsigned int command;
} nec_command_t;

// Function prototypes
void signal_handler(int signal);
int initialize_gpio();
int initialize_mqtt();
void alert_callback(int gpio, int level, uint32_t tick, void *user);
int decode_nec_frame(unsigned int *address, unsigned int *command);
int validate_nec_checksum(unsigned int address, unsigned int command);
int publish_mqtt_message(unsigned int address, unsigned int command);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    syslog(LOG_INFO, "Signal received, shutting down...");
    running = 0;
}

// Initialize GPIO using pigpio
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        syslog(LOG_ERR, "pigpio initialisation failed");
        return -1;
    }

    gpioSetMode(IR_GPIO, PI_INPUT);
    gpioSetPullUpDown(IR_GPIO, PI_PUD_UP); // Enable pull-up resistor

    // Set alert function for falling edge detection
    if (gpioSetAlertFuncEx(IR_GPIO, alert_callback, NULL) != 0) {
        syslog(LOG_ERR, "Failed to set alert function");
        gpioTerminate();
        return -1;
    }

    return 0;
}

// Initialize MQTT client
int initialize_mqtt() {
    mosquitto_lib_init();
    mosq = mosquitto_new(NULL, true, NULL);
    if (!mosq) {
        syslog(LOG_ERR, "Failed to create mosquitto instance");
        return -1;
    }

    int rc = mosquitto_connect(mosq, MQTT_BROKER, MQTT_PORT, 60);
    if (rc != MOSQ_ERR_SUCCESS) {
        syslog(LOG_ERR, "Failed to connect to MQTT broker: %s", mosquitto_strerror(rc));
        mosquitto_destroy(mosq);
        mosquitto_lib_cleanup();
        return -1;
    }

    mosquitto_loop_start(mosq);
    mqtt_connected = 0; // Initialize to disconnected state
    return 0;
}

// Alert callback function
void alert_callback(int gpio, int level, uint32_t tick, void *user) {
    if (level == FALLING_EDGE) {
        // Add pulse to the pulse buffer
        if (pulse_buffer_index < NEC_PULSE_BUFFER_SIZE) {
            pulse_buffer[pulse_buffer_index++] = tick;
        } else {
            pulse_buffer_overflow = 1;
            syslog(LOG_WARNING, "Pulse buffer overflow!");
        }
    }
}

// Decode NEC frame
int decode_nec_frame(unsigned int *address, unsigned int *command) {
    if (pulse_buffer_index < NEC_FRAME_LENGTH * 2) {
        syslog(LOG_WARNING, "Not enough pulses received (%d), waiting for full frame", pulse_buffer_index);
        return -1;
    }

    // Check for valid start pulse
    if (pulse_buffer[0] < NEC_MARK * 0.8 || pulse_buffer[0] > NEC_MARK * 1.2 ||
        pulse_buffer[1] < NEC_SPACE * 0.8 || pulse_buffer[1] > NEC_SPACE * 1.2) {
        syslog(LOG_WARNING, "Invalid start pulse");
        return -1;
    }

    // Decode address and command
    *address = 0;
    *command = 0;
    for (int i = 2; i < NEC_FRAME_LENGTH * 2; i += 2) {
        if (pulse_buffer[i] < NEC_BIT_MARK * 0.8 || pulse_buffer[i] > NEC_BIT_MARK * 1.2) {
            syslog(LOG_WARNING, "Invalid bit mark");
            return -1;
        }

        if (pulse_buffer[i + 1] < NEC_ONE_SPACE * 0.8 || pulse_buffer[i + 1] > NEC_ONE_SPACE * 1.2) {
            syslog(LOG_WARNING, "Invalid one space");
            return -1;
        }

        if (i < NEC_FRAME_LENGTH * 2 - 4) {
            // Decode address (8 bits)
            if (pulse_buffer[i + 2] < NEC_ONE_SPACE * 0.8 || pulse_buffer[i + 2] > NEC_ONE_SPACE * 1.2) {
                syslog(LOG_WARNING, "Invalid one space for address");
                return -1;
            }
            if (pulse_buffer[i + 3] < NEC_ZERO_SPACE * 0.8 || pulse_buffer[i + 3] > NEC_ZERO_SPACE * 1.2) {
                syslog(LOG_WARNING, "Invalid zero space for address");
                return -1;
            }
            if (pulse_buffer[i + 2] > pulse_buffer[i + 3]) {
                *address |= (1 << (i / 2 - 2));
            }
        } else {
            // Decode command (8 bits)
            if (pulse_buffer[i + 2] < NEC_ONE_SPACE * 0.8 || pulse_buffer[i + 2] > NEC_ONE_SPACE * 1.2) {
                syslog(LOG_WARNING, "Invalid one space for command");
                return -1;
            }
            if (pulse_buffer[i + 3] < NEC_ZERO_SPACE * 0.8 || pulse_buffer[i + 3] > NEC_ZERO_SPACE * 1.2) {
                syslog(LOG_WARNING, "Invalid zero space for command");
                return -1;
            }
