#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>
#include <pigpio.h>

// Constants
#define I2C_BUS 1
#define SENSOR_ADDRESSES {0x23, 0x5C, 0x4C, 0x1C}
#define NUM_SENSORS 4
#define MULTICAST_ADDR "239.255.255.250"
#define MULTICAST_PORT 5005
#define READ_DELAY_MS 180

// Global variables
int i2c_handles[NUM_SENSORS];
int udp_socket;
volatile sig_atomic_t terminate = 0;

// Function prototypes
int initialize_sensor(int i2c_handle);
float read_lux(int i2c_handle);
void send_udp_packet(float lux_values[NUM_SENSORS]);
void signal_handler(int signal);

// Signal handler function
void signal_handler(int signal) {
    fprintf(stderr, "Signal received, terminating...\n");
    terminate = 1;
}

// Initializes a BH1750FVI sensor
int initialize_sensor(int i2c_handle) {
    // Set continuous high-resolution mode
    if (i2cWriteByteData(i2c_handle, 0x00, 0x10) < 0) {
        fprintf(stderr, "Error writing to I2C device.\n");
        return -1;
    }
    return 0;
}

// Reads lux value from a BH1750FVI sensor
float read_lux(int i2c_handle) {
    char buffer[2];
    int bytes_read;

    bytes_read = i2cReadI2CBlockData(i2c_handle, 0x00, buffer, 2);
    if (bytes_read != 2) {
        fprintf(stderr, "Error reading from I2C device. Bytes read: %d\n", bytes_read);
        return NAN; // Return NaN on error
    }

    // Convert raw data to lux
    uint16_t raw_value = (buffer[0] << 8) | buffer[1];
    float lux = (float)raw_value / 1.2;

    return lux;
}

// Sends a UDP multicast packet
void send_udp_packet(float lux_values[NUM_SENSORS]) {
    struct sockaddr_in addr;
    char message[256];
    int i;

    // Create message string
    for (i = 0; i < NUM_SENSORS; i++) {
        if (isnan(lux_values[i])) {
            snprintf(message + strlen(message), sizeof(message) - strlen(message), "%d,%.1f;", i + 1, NAN);
        } else {
            snprintf(message + strlen(message), sizeof(message) - strlen(message), "%d,%.1f;", i + 1, lux_values[i]);
        }
    }

    // Create socket
    udp_socket = socket(AF_INET, SOCK_DGRAM, 0);
    if (udp_socket < 0) {
        perror("Error creating socket");
        return;
    }

    // Configure multicast address
    memset(&addr, 0, sizeof(addr));
    addr.sin_family = AF_INET;
    addr.sin_addr.s_addr = inet_addr(MULTICAST_ADDR);
    addr.sin_port = htons(MULTICAST_PORT);

    // Send message
    if (sendto(udp_socket, message, strlen(message), 0, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("Error sending UDP packet");
    }

    // Close socket
    close(udp_socket);
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C handles for each sensor
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2c_handles[i] = i2cOpen(I2C_BUS, SENSOR_ADDRESSES[i], 0);
        if (i2c_handles[i] < 0) {
            fprintf(stderr, "Error opening I2C device at address 0x%02X: %d\n", SENSOR_ADDRESSES[i], i2c_handles[i]);
            // Attempt to close any previously opened handles
            for (int j = 0; j < i; j++) {
                i2cClose(i2c_handles[j]);
            }
            gpioTerminate();
            return 1;
        }

        // Initialize the sensor
        if (initialize_sensor(i2c_handles[i]) < 0) {
            fprintf(stderr, "Error initializing sensor at address 0x%02X\n", SENSOR_ADDRESSES[i]);
            // Attempt to close any previously opened handles
            for (int j = 0; j <= i; j++) {
                i2cClose(i2c_handles[j]);
            }
            gpioTerminate();
            return 1;
        }
    }

    // Set up signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Main loop
    while (!terminate) {
        float lux_values[NUM_SENSORS];

        // Read lux values from each sensor
        for (int i = 0; i < NUM_SENSORS; i++) {
            lux_values[i] = read_lux(i2c_handles[i]);
        }

        // Send UDP packet
        send_udp_packet(lux_values);

        // Wait for 1 second
        gpioDelay(1000); // pigpioDelay takes milliseconds
    }

    // Close I2C handles and terminate pigpio
    for (int i = 0; i < NUM_SENSORS; i++) {
        i2cClose(i2c_handles[i]);
    }
    gpioTerminate();

    return 0;
}

