#include <string.h>
#include <unistd.h>

// AS7341 I2C address
#define AS7341_ADDR 0x39

// AS7341 register addresses
#define AS7341_ENABLE 0x00
#define AS7341_CFG6 0x03
#define AS7341_SP_EN 0x04
#define AS7341_ID 0x12
#define AS7341_DATA_START 0x18

// Global variables
int i2c_handle;
FILE *log_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold sensor data
typedef struct {
    uint16_t f1;
    uint16_t f2;
    uint16_t f3;
    uint16_t f4;
    uint16_t f5;
    uint16_t f6;
    uint16_t f7;
    uint16_t f8;
    uint16_t clear;
    uint16_t nir;
} sensor_data_t;

// Function prototypes
int init_sensor();
int read_sensor_data(sensor_data_t *data);
float calculate_lux(const sensor_data_t *data);
int log_data(const sensor_data_t *data, float lux);
void signal_handler(int signal);

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("\nCaught signal %d, terminating gracefully...\n", signal);
}

// Initialize the AS7341 sensor
int init_sensor() {
    // Check sensor ID
    int id = i2cReadByteData(i2c_handle, AS7341_ID);
    if (id < 0) {
        fprintf(stderr, "Error reading sensor ID: %d\n", id);
        return -1;
    }
    if (id != 0x41) {
        fprintf(stderr, "Incorrect sensor ID: 0x%02X (expected 0x41)\n", id);
        return -1;
    }

    // Enable the sensor (PON bit)
    if (i2cWriteByteData(i2c_handle, AS7341_ENABLE, 0x03) < 0) {
        fprintf(stderr, "Error writing to ENABLE register\n");
        return -1;
    }

    // Configure SMUX (channel selection)
    if (i2cWriteByteData(i2c_handle, AS7341_CFG6, 0x00) < 0) {
        fprintf(stderr, "Error writing to CFG6 register\n");
        return -1;
    }

    // Enable spectral measurement
    if (i2cWriteByteData(i2c_handle, AS7341_SP_EN, 0x01) < 0) {
        fprintf(stderr, "Error writing to SP_EN register\n");
        return -1;
    }

    return 0;
}

// Read spectral data from the AS7341 sensor
int read_sensor_data(sensor_data_t *data) {
    uint8_t buffer[18]; // 16 bytes for spectral data + 2 bytes for clear and nir

    // Read all 18 bytes of data (F1-F8, Clear, NIR)
    if (i2cReadI2CBlockData(i2c_handle, AS7341_DATA_START, (char *)buffer, 18) != 18) {
        fprintf(stderr, "Error reading sensor data\n");
        return -1;
    }

    // Extract spectral data
    data->f1 = (buffer[1] << 8) | buffer[0];
    data->f2 = (buffer[3] << 8) | buffer[2];
    data->f3 = (buffer[5] << 8) | buffer[4];
    data->f4 = (buffer[7] << 8) | buffer[6];
    data->f5 = (buffer[9] << 8) | buffer[8];
    data->f6 = (buffer[11] << 8) | buffer[10];
    data->f7 = (buffer[13] << 8) | buffer[12];
    data->f8 = (buffer[15] << 8) | buffer[14];
    data->clear = (buffer[17] << 8) | buffer[16];

    return 0;
}

// Calculate lux value from spectral data (simplified approximation)
float calculate_lux(const sensor_data_t *data) {
    // This is a placeholder.  A real implementation would use
    // the spectral data to calculate lux.
    // For example, you might use a logarithmic relationship.
    // This example returns a constant value.
    return 100.0; // Example lux value
}

// Log data to a CSV file
int log_data(const sensor_data_t *data, float lux) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    fprintf(log_file, "%s,%u,%u,%u,%u,%u,%u,%u,%u,%u,%u,%.2f\n",
            timestamp, data->f1, data->f2, data->f3, data->f4, data->f5, data->f6, data->f7, data->f8, data->clear, data->nir, lux);
    fflush(log_file); // Ensure data is written to disk immediately

    return 0;
}

int main() {
    // Initialize pigpio
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return 1;
    }

    // Open I2C bus
    i2c_handle = i2cOpen(1, AS7341_ADDR, 0);
    if (i2c_handle < 0) {
        fprintf(stderr, "Error opening I2C bus: %d\n", i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Initialize the sensor
    if (init_sensor() < 0) {
        fprintf(stderr, "Sensor initialization failed\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Open log file
    log_file = fopen("spectral_log.csv", "a");
    if (log_file == NULL) {
        fprintf(stderr, "Error opening log file\n");
        i2cClose(i2c_handle);
        gpioTerminate();
        return 1;
    }

    // Write header if the file is newly created
    fseek(log_file, 0, SEEK_END);
    long file_size = ftell(log_file);
    if (file_size == 0) {
        fprintf(log_file, "Timestamp,F1,F2,F3,F4,F5,F6,F7,F8,Clear,NIR,Lux\n");
    }
    rewind(log_file);

    // Set up signal handler for Ctrl+C
    signal(SIGINT, signal_handler);

    sensor_data_t sensor_data;
    float lux;

    // Main loop
    while (!terminate) {
        // Read sensor data
        if (read_sensor_data(&sensor_data) == 0) {
            // Calculate lux value
            lux = calculate_lux(&sensor_data);

            // Log data
            if (log_data(&sensor_data, lux) != 0) {
                fprintf(stderr, "Error logging data\n");
            }
        } else {
            fprintf(stderr, "Error reading sensor data, retrying...\n");
        }

        // Wait for 5 seconds
        sleep(5);
    }

    // Close resources before exiting
    i2cClose(i2c_handle);
    fclose(log_file);
    gpioTerminate();

    return 0;
}

