// Default values
#define DEFAULT_I2C_ADDRESS 0x1D
#define DEFAULT_SAMPLING_INTERVAL 1
#define DEFAULT_FILENAME "seismic_data.csv"

// D7S Register Addresses (Example - Refer to Datasheet for correct values)
#define REG_X_AXIS_LSB 0x28
#define REG_X_AXIS_MSB 0x29
#define REG_Y_AXIS_LSB 0x2A
#define REG_Y_AXIS_MSB 0x2B
#define REG_Z_AXIS_LSB 0x2C
#define REG_Z_AXIS_MSB 0x2D

// Global variables
