    terminate = 1;
    printf("\nCaught signal %d, terminating...\n", signal);
}

// Initialize I2C communication
int initialize_i2c() {
    i2c_handle = i2cOpen(1, i2c_address, 0); // Bus 1, address, flags
    if (i2c_handle < 0) {
        log_error("Failed to open I2C device");
        return -1;
    }
    return 0;
}

// Read sensor data from the D7S
int read_sensor_data(sensor_data_t *data) {
    char buffer[6];
    int result;

    // Read X axis data
    result = i2cReadI2CBlockData(i2c_handle, REG_X_AXIS_LSB, buffer, 6);
    if (result != 6) {
        log_error("Failed to read sensor data");
        return -1;
    }

    // Combine LSB and MSB for each axis
    int16_t x_raw = (buffer[1] << 8) | buffer[0];
    int16_t y_raw = (buffer[3] << 8) | buffer[2];
    int16_t z_raw = (buffer[5] << 8) | buffer[4];

    // Convert raw data to g-force units (adjust scaling factor as needed)
    data->x = (float)x_raw / 1000.0f; // Example scaling factor
    data->y = (float)y_raw / 1000.0f;
    data->z = (float)z_raw / 1000.0f;

    return 0;
}

