// Define UART parameters
#define UART_DEVICE "/dev/ttyS0"
#define BAUD_RATE 921600
#define BUFFER_SIZE 4096

// Define TLV types
#define TLV_TYPE_RANGE 1
#define TLV_TYPE_VELOCITY 2

// Define magic word
#define MAGIC_WORD 0x02010403

// Global variables
int uart_handle;
FILE *csv_file;
volatile sig_atomic_t terminate = 0;

// Structure to hold TLV data
typedef struct {
    uint16_t type;
    uint16_t length;
    uint8_t *data;
} tlv_t;

// Function prototypes
int initialize_uart();
int read_uart_data(char *buffer, int max_len);
int validate_frame(const char *buffer, int len);
tlv_t *parse_tlv(const char *buffer, int len);
void process_tlv(tlv_t *tlv);
void log_error(const char *message);
void signal_handler(int signal);
void cleanup();

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    terminate = 1;
    printf("Caught signal %d, terminating...\n", signal);
}

// Initialize UART
int initialize_uart() {
    uart_handle = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for default flags
    if (uart_handle < 0) {
        log_error("Failed to open UART");
        return -1;
    }
    printf("UART initialized on %s at %d baud\n", UART_DEVICE, BAUD_RATE);
    return 0;
}

// Read data from UART with timeout
int read_uart_data(char *buffer, int max_len) {
    int bytes_read = 0;
    int start_time = time(NULL);

    while (bytes_read < max_len && !terminate) {
        int available = serDataAvailable(uart_handle);
        if (available > 0) {
            int read_size = (available > max_len - bytes_read) ? max_len - bytes_read : available;
            int result = serRead(uart_handle, buffer + bytes_read, read_size);
            if (result > 0) {
                bytes_read += result;
            } else if (result < 0) {
                log_error("UART read error");
                return -1;
            } else {
                // No data available, sleep for a short interval
                gpioDelay(1000); // 1ms
            }
        } else {
            // No data available, sleep for a short interval
            gpioDelay(1000); // 1ms
        }

        if (time(NULL) - start_time > 5) {
            log_error("Timeout waiting for data");
            return -1;
        }
    }

    return bytes_read;
}

// Validate frame checksum
int validate_frame(const char *buffer, int len) {
    if (len < 8) {
        log_error("Frame too short");
        return -1;
    }

    uint32_t frame_magic = *((uint32_t *)buffer);
    if (frame_magic != MAGIC_WORD) {
        log_error("Invalid frame magic word");
        return -1;
    }

    uint32_t frame_checksum = *((uint32_t *)(buffer + 4));
    uint32_t calculated_checksum = 0;
    for (int i = 0; i < len - 8; i++) {
        calculated_checksum += buffer[i];
    }

    if (calculated_checksum != frame_checksum) {
        log_error("Checksum mismatch");
        return -1;
    }

    return 0;
}

// Parse TLV data
tlv_t *parse_tlv(const char *buffer, int len) {
    tlv_t *tlv = (tlv_t *)malloc(sizeof(tlv_t));
    if (tlv == NULL) {
        log_error("Failed to allocate memory for TLV");
        return NULL;
    }

    tlv->type = *((uint16_t *)buffer);
    tlv->length = *((uint16_t *)(buffer + 2));

    if (tlv->length > len - 8) {
        log_error("TLV length exceeds frame length");
        free(tlv);
        return NULL;
    }

    tlv->data = (uint8_t *)malloc(tlv->length);
    if (tlv->data == NULL) {
        log_error("Failed to allocate memory for TLV data");
        free(tlv);
        return NULL;
    }

    memcpy(tlv->data, buffer + 8, tlv->length);

    return tlv;
}

// Process TLV data (extract range and velocity)
void process_tlv(tlv_t *tlv) {
    if (tlv->type == TLV_TYPE_RANGE) {
        // Assuming range is a float in meters
        float range = *((float *)tlv->data);
        printf("Range: %.2f m\n", range);
    } else if (tlv->type == TLV_TYPE_VELOCITY) {
        // Assuming velocity is a float in m/s
        float velocity = *((float *)tlv->data);
        printf("Velocity: %.2f m/s\n", velocity);
    } else {
        printf("Unknown TLV type: %d\n", tlv->type);
    }
}

// Log errors to stderr
void log_error(const char *message) {
    fprintf(stderr, "Error: %s\n", message);
}

// Cleanup resources
void cleanup() {
    printf("Cleaning up...\n");
    if (uart_handle >= 0) {
        serClose(uart_handle);
    }
    if (csv_file != NULL) {
        fclose(csv_file);
    }
    gpioTerminate();
}

