    }

    // Open CSV file
    csv_file = fopen("radar_data.csv", "a");
    if (csv_file == NULL) {
        log_error("Failed to open CSV file");
        cleanup();
        return 1;
    }

    // Write header if the file is newly created
    fseek(csv_file, 0, SEEK_END);
    long file_size = ftell(csv_file);
    if (file_size == 0) {
        fprintf(csv_file, "timestamp,object_index,range_m,velocity_mps\n");
    }
    rewind(csv_file);

    char buffer[BUFFER_SIZE];
    int bytes_read;

    // Main loop
    while (!terminate) {
        bytes_read = read_uart_data(buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            if (validate_frame(buffer, bytes_read) == 0) {
