#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <fcntl.h>
#include <termios.h>
#include <unistd.h>
#include <sys/select.h>
#include <errno.h>
#include <signal.h>
#include <time.h>
#include <sys/time.h>

#define UART_DEVICE "/dev/serial0"
#define BAUD_RATE B115200
#define TIMEOUT_MS 500
#define BUFFER_SIZE 256

volatile sig_atomic_t program_running = 1;
int uart_fd = -1;

// Structure to hold UART configuration
typedef struct {
    int fd;
    struct termios tty;
} uart_config_t;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    program_running = 0;
    printf("\nCaught signal %d, exiting gracefully...\n", signal);
}

// Function to initialize the UART
int init_uart(uart_config_t *config) {
    config->fd = open(UART_DEVICE, O_RDWR | O_NOCTTY | O_SYNC);
    if (config->fd == -1) {
        perror("Error opening UART");
        return -1;
    }

    if (tcgetattr(config->fd, &config->tty) != 0) {
        perror("Error getting UART attributes");
        close(config->fd);
        return -1;
    }

    config->tty.c_cflag = (config->tty.c_cflag & ~CSIZE) | CS8;     // 8-bit chars
    config->tty.c_iflag &= ~IGNBRK;         // disable break processing
    config->tty.c_lflag = 0;                // no signaling chars, no echo, no canonical processing
    config->tty.c_oflag = 0;                // no remapping, no delays
    config->tty.c_cc[VMIN]  = 0;            // read doesn't block
    config->tty.c_cc[VTIME] = 5;            // 0.5 seconds read timeout

    config->tty.c_iflag &= ~(IXON | IXOFF | IXANY); // shut off xon/xoff ctrl

    config->tty.c_cflag |= (CLOCAL | CREAD);// ignore modem controls, enable reading
    config->tty.c_cflag &= ~(PARENB | PARODD);      // shut off parity
    config->tty.c_cflag &= ~CSTOPB;
    config->tty.c_cflag &= ~CRTSCTS;

    if (cfsetospeed(&config->tty, BAUD_RATE) != 0 || cfsetispeed(&config->tty, BAUD_RATE) != 0) {
        perror("Error setting baud rate");
        close(config->fd);
        return -1;
    }

    if (tcsetattr(config->fd, TCSANOW, &config->tty) != 0) {
        perror("Error setting UART attributes");
        close(config->fd);
        return -1;
    }

    return 0;
}

// Function to read data from the UART with timeout
int read_uart(uart_config_t *config, char *buffer, size_t buffer_size) {
    fd_set readfds;
    struct timeval timeout;

    FD_ZERO(&readfds);
    FD_SET(config->fd, &readfds);

    timeout.tv_sec = 0;
    timeout.tv_usec = TIMEOUT_MS * 1000; // Convert milliseconds to microseconds

    int retval = select(config->fd + 1, &readfds, NULL, NULL, &timeout);

    if (retval == -1) {
        perror("Error in select");
        return -1;
    } else if (retval == 0) {
        // Timeout occurred
        return 0;
    } else {
        // Data is available
        ssize_t bytes_read = read(config->fd, buffer, buffer_size - 1);
        if (bytes_read == -1) {
            perror("Error reading from UART");
            return -1;
        } else {
            buffer[bytes_read] = '\0'; // Null-terminate the buffer
            return bytes_read;
        }
    }
}

// Function to parse the received data
int parse_data(const char *data, double *timestamp, double *range) {
    char *token;
    char *line = strdup(data); // Duplicate the string to avoid modifying the original
    if (line == NULL) {
        perror("strdup failed");
        return -1;
    }

    token = strtok(line, ",");
    if (token != NULL) {
        *timestamp = strtod(token, NULL);
    } else {
        fprintf(stderr, "Error: Timestamp not found in data: %s\n", data);
        free(line);
        return -1;
    }

    token = strtok(NULL, "\n");
    if (token != NULL) {
        *range = strtod(token, NULL);
    } else {
        fprintf(stderr, "Error: Range not found in data: %s\n", data);
        free(line);
        return -1;
    }

    free(line);
    return 0;
}

// Function to log the detection data
void log_detection(double timestamp, double range) {
    struct tm *timeinfo;
    char timestamp_str[20];

    timeinfo = localtime(&timestamp);
    strftime(timestamp_str, sizeof(timestamp_str), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("Timestamp: %s, Range: %.2f meters\n", timestamp_str, range);
}

int main() {
    uart_config_t uart_config;
    char buffer[BUFFER_SIZE];
    double timestamp, range;
    int bytes_read;

    // Install signal handlers
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize UART
    if (init_uart(&uart_config) != 0) {
        return 1;
    }
    uart_fd = uart_config.fd;

    printf("UART initialized successfully. Reading data...\n");

    while (program_running) {
        bytes_read = read_uart(&uart_config, buffer, BUFFER_SIZE);
        if (bytes_read > 0) {
            // Process the received data
            if (parse_data(buffer, &timestamp, &range) == 0) {
                log_detection(timestamp, range);
            } else {
                fprintf(stderr, "Error parsing data: %s\n", buffer);
            }
        } else if (bytes_read < 0) {
            // Error reading from UART, but continue running
            fprintf(stderr, "Error reading from UART, retrying...\n");
        }

        usleep(10000); // Sleep for 10ms to avoid busy-waiting
    }

    // Close UART
    close(uart_fd);
    printf("UART closed.\n");

    return 0;
}

