#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <signal.h>
#include <unistd.h>
#include <pigpio.h>

// Define GPIO pins for the sensors
#define LEFT_SENSOR_PIN 4
#define MIDDLE_SENSOR_PIN 17
#define RIGHT_SENSOR_PIN 27

// Define UART device and baud rate
#define UART_DEVICE "/dev/ttyAMA0"
#define BAUD_RATE 115200

// Global variables for UART file descriptor and pigpio initialization status
int uart_fd = -1;
int pigpio_initialized = 0;

// Function prototypes
int initialize_gpio();
int initialize_uart();
int read_sensor(int gpio_pin);
int log_sensor_data(int left_state, int middle_state, int right_state);
int send_emergency_stop_message();
void signal_handler(int signal);
void cleanup();

// Structure to hold sensor data
typedef struct {
    int left;
    int middle;
    int right;
} SensorData;

// Signal handler for graceful shutdown
void signal_handler(int signal) {
    printf("Caught signal %d, cleaning up...\n", signal);
    cleanup();
    exit(0);
}

// Function to initialize GPIO pins
int initialize_gpio() {
    if (gpioInitialise() < 0) {
        fprintf(stderr, "pigpio initialisation failed\n");
        return -1;
    }
    pigpio_initialized = 1;

    gpioSetMode(LEFT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(LEFT_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(MIDDLE_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(MIDDLE_SENSOR_PIN, PI_PUD_UP);

    gpioSetMode(RIGHT_SENSOR_PIN, PI_INPUT);
    gpioSetPullUpDown(RIGHT_SENSOR_PIN, PI_PUD_UP);

    return 0;
}

// Function to initialize UART
int initialize_uart() {
    uart_fd = serOpen(UART_DEVICE, BAUD_RATE, 0); // 0 for no flags
    if (uart_fd < 0) {
        fprintf(stderr, "Failed to open UART device %s: %d\n", UART_DEVICE, uart_fd);
        return -1;
    }
    return 0;
}

// Function to read sensor value
int read_sensor(int gpio_pin) {
    return gpioRead(gpio_pin);
}

// Function to log sensor data with timestamp
int log_sensor_data(int left_state, int middle_state, int right_state) {
    time_t rawtime;
    struct tm *timeinfo;
    char timestamp[20];

    time(&rawtime);
    timeinfo = localtime(&rawtime);

    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", timeinfo);

    printf("[%s] Left: %d, Middle: %d, Right: %d\n", timestamp, left_state, middle_state, right_state);
    return 0;
}

// Function to send emergency stop message over UART
int send_emergency_stop_message() {
    if (uart_fd < 0) {
        fprintf(stderr, "UART not initialized\n");
        return -1;
    }

    if (serWrite(uart_fd, "EMERGENCY STOP!\n", strlen("EMERGENCY STOP!\n")) < 0) {
        fprintf(stderr, "Failed to write to UART\n");
        return -1;
    }
    return 0;
}

// Function to cleanup resources
void cleanup() {
    if (uart_fd >= 0) {
        serClose(uart_fd);
    }
    if (pigpio_initialized) {
        gpioTerminate();
    }
}

int main() {
    // Register signal handlers for graceful shutdown
    signal(SIGINT, signal_handler);
    signal(SIGTERM, signal_handler);

    // Initialize GPIO
    if (initialize_gpio() != 0) {
        return 1;
    }

    // Initialize UART
    if (initialize_uart() != 0) {
        cleanup();
        return 1;
    }

    // Main loop
    while (1) {
        // Read sensor values
        int left_state = read_sensor(LEFT_SENSOR_PIN);
        int middle_state = read_sensor(MIDDLE_SENSOR_PIN);
        int right_state = read_sensor(RIGHT_SENSOR_PIN);

        // Log sensor data
        log_sensor_data(left_state, middle_state, right_state);

        // Check for emergency stop condition
        if (left_state == 0 && middle_state == 0 && right_state == 0) {
            // Send emergency stop message
            if (send_emergency_stop_message() != 0) {
                fprintf(stderr, "Failed to send emergency stop message\n");
            }
        }

        // Delay for 100 milliseconds
        gpioDelay(100000); // 100000 microseconds = 100 milliseconds
    }

    return 0;
}

